module qam16_mapper_interpolated #(
    parameter int N         = 4,   // Number of input symbols (>=2, multiple of 2)
    parameter int IN_WIDTH  = 4,   // Bit width of each input symbol (fixed at 4)
    parameter int OUT_WIDTH = 3    // Bit width of each output component (fixed at 3)
) (
    input  logic [N*IN_WIDTH-1:0]           bits,
    output logic [(N+N/2)*OUT_WIDTH-1:0]    I,
    output logic [(N+N/2)*OUT_WIDTH-1:0]    Q
);

    // Map a 2-bit field to the QAM16 amplitude: 00->-3, 01->-1, 10->1, 11->3
    function automatic signed [OUT_WIDTH-1:0] qam_map(input logic [1:0] b);
        // amplitude = 2*b - 3  (00->-3, 01->-1, 10->1, 11->3)
        integer amp;
        amp = (2 * b) - 3;
        qam_map = amp[OUT_WIDTH-1:0];
    endfunction

    genvar p;
    generate
        for (p = 0; p < N/2; p = p + 1) begin : gen_pair
            // Two consecutive symbols of this pair
            localparam int S0 = 2*p;
            localparam int S1 = 2*p + 1;

            // Extract the MSB (I) and LSB (Q) fields of each symbol
            logic [1:0] msb0, lsb0, msb1, lsb1;
            assign msb0 = bits[S0*IN_WIDTH + IN_WIDTH-1 -: 2];
            assign lsb0 = bits[S0*IN_WIDTH + 1        -: 2];
            assign msb1 = bits[S1*IN_WIDTH + IN_WIDTH-1 -: 2];
            assign lsb1 = bits[S1*IN_WIDTH + 1        -: 2];

            // Mapped amplitudes (signed, OUT_WIDTH bits)
            logic signed [OUT_WIDTH-1:0] I0, Q0, I1, Q1;
            assign I0 = qam_map(msb0);
            assign Q0 = qam_map(lsb0);
            assign I1 = qam_map(msb1);
            assign Q1 = qam_map(lsb1);

            // Interpolated samples need 1 extra bit to hold the sum of two signed
            // OUT_WIDTH values before the divide-by-2.
            logic signed [OUT_WIDTH:0] I_interp, Q_interp;
            assign I_interp = ($signed(I0) + $signed(I1)) >>> 1;
            assign Q_interp = ($signed(Q0) + $signed(Q1)) >>> 1;

            // Output arrangement per pair: mapped0, interpolated, mapped1
            localparam int O0 = 3*p;     // first mapped symbol
            localparam int O1 = 3*p + 1; // interpolated value
            localparam int O2 = 3*p + 2; // second mapped symbol

            assign I[O0*OUT_WIDTH +: OUT_WIDTH] = I0;
            assign Q[O0*OUT_WIDTH +: OUT_WIDTH] = Q0;

            assign I[O1*OUT_WIDTH +: OUT_WIDTH] = I_interp[OUT_WIDTH-1:0];
            assign Q[O1*OUT_WIDTH +: OUT_WIDTH] = Q_interp[OUT_WIDTH-1:0];

            assign I[O2*OUT_WIDTH +: OUT_WIDTH] = I1;
            assign Q[O2*OUT_WIDTH +: OUT_WIDTH] = Q1;
        end
    endgenerate

endmodule

module qam16_demapper_interpolated #(
    parameter integer N         = 4,
    parameter integer OUT_WIDTH = 4,
    parameter integer IN_WIDTH  = 3
) (
    input  wire [(N + N/2)*IN_WIDTH-1:0] I,
    input  wire [(N + N/2)*IN_WIDTH-1:0] Q,
    output wire [N*OUT_WIDTH-1:0]        bits,
    output wire                          error_flag
);

    // Tolerance on the interpolated-vs-expected deviation.
    localparam integer ERROR_THRESHOLD = 1;
    localparam integer NGROUPS         = N/2;

    // ------------------------------------------------------------------
    // Bit mapping.  For each mapped symbol k (0..N-1) extract its I and Q
    // constellation values and translate to 2 bits each:
    //   -3 -> 00, -1 -> 01, 1 -> 10, 3 -> 11   (== (v+3)/2)
    // The 4-bit output segment is {I_code (MSBs), Q_code (LSBs)}.
    // Sample layout is repeating [mapped_a, interpolated, mapped_b]:
    //   mapped symbol k lives at sample index 3*(k/2) + 2*(k%2).
    // ------------------------------------------------------------------
    genvar k;
    generate
        for (k = 0; k < N; k = k + 1) begin : gen_map
            wire signed [IN_WIDTH-1:0] i_val =
                $signed(I[(3*(k/2) + 2*(k%2))*IN_WIDTH +: IN_WIDTH]);
            wire signed [IN_WIDTH-1:0] q_val =
                $signed(Q[(3*(k/2) + 2*(k%2))*IN_WIDTH +: IN_WIDTH]);
            wire signed [IN_WIDTH:0]   i_lvl = i_val + 3;
            wire signed [IN_WIDTH:0]   q_lvl = q_val + 3;
            wire [1:0] i_code = i_lvl >>> 1;
            wire [1:0] q_code = q_lvl >>> 1;
            assign bits[k*OUT_WIDTH +: OUT_WIDTH] = {i_code, q_code};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Error detection.  For each group g, the expected interpolated value
    // is the average of the two surrounding mapped values.  The absolute
    // deviation of the actual interpolated sample from the expected value
    // is compared against ERROR_THRESHOLD (for both I and Q).
    // Arithmetic uses IN_WIDTH+1 bits to avoid carry/overflow.
    // ------------------------------------------------------------------
    wire [NGROUPS-1:0] grp_err;
    genvar g;
    generate
        for (g = 0; g < NGROUPS; g = g + 1) begin : gen_err
            wire signed [IN_WIDTH-1:0] i_a  = $signed(I[(3*g)  *IN_WIDTH +: IN_WIDTH]);
            wire signed [IN_WIDTH-1:0] i_in = $signed(I[(3*g+1)*IN_WIDTH +: IN_WIDTH]);
            wire signed [IN_WIDTH-1:0] i_b  = $signed(I[(3*g+2)*IN_WIDTH +: IN_WIDTH]);
            wire signed [IN_WIDTH-1:0] q_a  = $signed(Q[(3*g)  *IN_WIDTH +: IN_WIDTH]);
            wire signed [IN_WIDTH-1:0] q_in = $signed(Q[(3*g+1)*IN_WIDTH +: IN_WIDTH]);
            wire signed [IN_WIDTH-1:0] q_b  = $signed(Q[(3*g+2)*IN_WIDTH +: IN_WIDTH]);

            wire signed [IN_WIDTH:0] i_sum  = i_a + i_b;
            wire signed [IN_WIDTH:0] q_sum  = q_a + q_b;
            wire signed [IN_WIDTH:0] i_exp  = i_sum >>> 1;
            wire signed [IN_WIDTH:0] q_exp  = q_sum >>> 1;
            wire signed [IN_WIDTH:0] i_diff = i_in - i_exp;
            wire signed [IN_WIDTH:0] q_diff = q_in - q_exp;
            wire        [IN_WIDTH:0] i_abs  = i_diff[IN_WIDTH] ? -i_diff : i_diff;
            wire        [IN_WIDTH:0] q_abs  = q_diff[IN_WIDTH] ? -q_diff : q_diff;

            assign grp_err[g] = (i_abs > ERROR_THRESHOLD) || (q_abs > ERROR_THRESHOLD);
        end
    endgenerate

    assign error_flag = |grp_err;

endmodule

module brent_kung_adder (
  input  [31:0] a,
  input  [31:0] b,
  input         carry_in,
  output [31:0] sum,
  output        carry_out
);

  // Bit-level generate / propagate
  logic [31:0] g0, p0;
  assign g0 = a & b;
  assign p0 = a ^ b;

  // Inclusive parallel-prefix generate/propagate:
  //   G[i], P[i] cover bit range [0..i].
  // Computed with a correct log-depth prefix tree (5 levels for 32 bits).
  logic [31:0] G, P;

  int  i, d;
  logic [31:0] Gt, Pt, Gn, Pn;
  always_comb begin
    Gt = g0;
    Pt = p0;
    for (d = 1; d <= 16; d = d + d) begin
      Gn = Gt;
      Pn = Pt;
      for (i = 0; i < 32; i = i + 1) begin
        if (i >= d) begin
          Gn[i] = Gt[i] | (Pt[i] & Gt[i-d]);
          Pn[i] = Pt[i] & Pt[i-d];
        end
      end
      Gt = Gn;
      Pt = Pn;
    end
    G = Gt;
    P = Pt;
  end

  // Carry into each bit position: c[i] = carry entering bit i.
  logic [31:0] c;
  assign c[0] = carry_in;
  genvar k;
  generate
    for (k = 1; k < 32; k = k + 1) begin : carry_gen
      assign c[k] = G[k-1] | (P[k-1] & carry_in);
    end
  endgenerate

  assign sum       = p0 ^ c;
  assign carry_out = G[31] | (P[31] & carry_in);

endmodule

module decoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic [65:0]  decoder_data_in,     // 66-bit encoded input
    output logic [63:0]  decoder_data_out,    // Decoded 64-bit data output
    output logic         sync_error           // Sync error flag
);

    // Spec-named intermediate signals (preserved verbatim)
    logic [1:0]  sync_header_in;   // 2-bit sync header extracted from the input word
    logic [63:0] data_in;          // 64-bit data payload extracted from the input word

    assign sync_header_in = decoder_data_in[65:64];
    assign data_in        = decoder_data_in[63:0];

    // Registered decode: one clock cycle of latency, asynchronous active-high reset.
    // sync_header 2'b01 -> valid data (pass payload); all other headers
    // (2'b00, 2'b10, 2'b11) -> zero output and assert sync_error.
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            decoder_data_out <= 64'b0;
            sync_error       <= 1'b0;
        end
        else begin
            case (sync_header_in)
                2'b01: begin
                    decoder_data_out <= data_in;   // valid data encoding
                    sync_error       <= 1'b0;
                end
                default: begin
                    decoder_data_out <= 64'b0;      // unsupported/invalid header
                    sync_error       <= 1'b1;
                end
            endcase
        end
    end

endmodule

module decoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic         decoder_data_valid_in, // Input data valid signal
    input  logic [65:0]  decoder_data_in,     // 66-bit encoded input
    output logic [63:0]  decoder_data_out,    // Decoded 64-bit data output
    output logic [7:0]   decoder_control_out, // Decoded 8-bit control output
    output logic         sync_error,          // Sync error flag
    output logic         decoder_error_out    // Type field error flag
);

    logic [1:0] sync_header;
    logic [7:0] type_field;
    logic [63:0] data_in;
    logic type_field_valid;
    logic decoder_wrong_ctrl_received;
    logic decoder_wrong_type_field;

    assign sync_header = decoder_data_in[65:64];
    assign type_field = decoder_data_in[63:56];
    assign data_in = decoder_data_in[55:0];

    // ----------------------------------------------------------------
    // Control-character constants (inserted into decoded data output)
    // ----------------------------------------------------------------
    localparam logic [7:0] CTRL_I = 8'h07; // /I/ Idle
    localparam logic [7:0] CTRL_S = 8'hFB; // /S/ Start of Frame
    localparam logic [7:0] CTRL_T = 8'hFD; // /T/ End of Frame
    localparam logic [7:0] CTRL_E = 8'hFE; // /E/ Error
    localparam logic [7:0] CTRL_Q = 8'h9C; // /Q/ Ordered Set

    // ----------------------------------------------------------------
    // Payload data byte-lanes D0..D6 (D0 = LSB byte of the 56-bit payload).
    // Pre-sliced via continuous assigns so part-selects stay outside the
    // always block (avoids the iverilog constant-select-in-process limitation).
    // ----------------------------------------------------------------
    logic [7:0] d0, d1, d2, d3, d4, d5, d6;
    assign d0 = data_in[7:0];
    assign d1 = data_in[15:8];
    assign d2 = data_in[23:16];
    assign d3 = data_in[31:24];
    assign d4 = data_in[39:32];
    assign d5 = data_in[47:40];
    assign d6 = data_in[55:48];

    // ----------------------------------------------------------------
    // Combinational decode (registered one cycle later for 1-cyc latency)
    // ----------------------------------------------------------------
    logic [63:0] decoder_data_out_c;
    logic [7:0]  decoder_control_out_c;
    logic        sync_error_c;
    logic        decoder_error_out_c;

    always_comb begin
        // defaults (no latch)
        type_field_valid            = 1'b1;
        decoder_wrong_ctrl_received = 1'b0;
        decoder_data_out_c          = 64'h0;
        decoder_control_out_c       = 8'h00;
        sync_error_c                = 1'b0;

        case (sync_header)
            // Data-only mode: the 64 bits following the sync header are data
            2'b01: begin
                decoder_data_out_c    = decoder_data_in[63:0];
                decoder_control_out_c = 8'h00;
            end

            // Control-only / mixed mode: dispatch on the type field
            2'b10: begin
                case (type_field)
                    8'h1E: begin
                        decoder_control_out_c = 8'b11111111;
                        decoder_data_out_c    = {CTRL_E, CTRL_E, CTRL_E, CTRL_E,
                                                 CTRL_E, CTRL_E, CTRL_E, CTRL_E};
                    end
                    8'h33: begin
                        decoder_control_out_c = 8'b00011111;
                        decoder_data_out_c    = {d6, d5, d4, CTRL_S,
                                                 CTRL_I, CTRL_I, CTRL_I, CTRL_I};
                    end
                    8'h78: begin
                        decoder_control_out_c = 8'b00000001;
                        decoder_data_out_c    = {d6, d5, d4, d3,
                                                 d2, d1, d0, CTRL_S};
                    end
                    8'h87: begin
                        decoder_control_out_c = 8'b11111110;
                        decoder_data_out_c    = {CTRL_I, CTRL_I, CTRL_I, CTRL_I,
                                                 CTRL_I, CTRL_I, CTRL_I, CTRL_T};
                    end
                    8'h99: begin
                        decoder_control_out_c = 8'b11111110;
                        decoder_data_out_c    = {CTRL_I, CTRL_I, CTRL_I, CTRL_I,
                                                 CTRL_I, CTRL_I, CTRL_T, d0};
                    end
                    8'hAA: begin
                        decoder_control_out_c = 8'b11111100;
                        decoder_data_out_c    = {CTRL_I, CTRL_I, CTRL_I, CTRL_I,
                                                 CTRL_I, CTRL_T, d1, d0};
                    end
                    8'hB4: begin
                        decoder_control_out_c = 8'b11111000;
                        decoder_data_out_c    = {CTRL_I, CTRL_I, CTRL_I, CTRL_I,
                                                 CTRL_T, d2, d1, d0};
                    end
                    8'hCC: begin
                        decoder_control_out_c = 8'b11110000;
                        decoder_data_out_c    = {CTRL_I, CTRL_I, CTRL_I, CTRL_T,
                                                 d3, d2, d1, d0};
                    end
                    8'hD2: begin
                        decoder_control_out_c = 8'b11100000;
                        decoder_data_out_c    = {CTRL_I, CTRL_I, CTRL_T, d4,
                                                 d3, d2, d1, d0};
                    end
                    8'hE1: begin
                        decoder_control_out_c = 8'b11000000;
                        decoder_data_out_c    = {CTRL_I, CTRL_T, d5, d4,
                                                 d3, d2, d1, d0};
                    end
                    8'hFF: begin
                        decoder_control_out_c = 8'b10000000;
                        decoder_data_out_c    = {CTRL_T, d6, d5, d4,
                                                 d3, d2, d1, d0};
                    end
                    8'h2D: begin
                        decoder_control_out_c = 8'b00011111;
                        decoder_data_out_c    = {d6, d5, d4, CTRL_Q,
                                                 CTRL_I, CTRL_I, CTRL_I, CTRL_I};
                    end
                    8'h4B: begin
                        decoder_control_out_c = 8'b11110001;
                        decoder_data_out_c    = {CTRL_I, CTRL_I, CTRL_I, CTRL_I,
                                                 d2, d1, d0, CTRL_Q};
                    end
                    8'h55: begin
                        decoder_control_out_c = 8'b00010001;
                        decoder_data_out_c    = {d6, d5, d4, CTRL_Q,
                                                 d2, d1, d0, CTRL_Q};
                    end
                    8'h66: begin
                        decoder_control_out_c = 8'b00010001;
                        decoder_data_out_c    = {d6, d5, d4, CTRL_S,
                                                 d2, d1, d0, CTRL_Q};
                    end
                    default: begin
                        // invalid type field: raise decode error, force outputs to zero
                        type_field_valid      = 1'b0;
                        decoder_data_out_c    = 64'h0;
                        decoder_control_out_c = 8'h00;
                    end
                endcase
            end

            // Invalid sync header (neither 2'b01 nor 2'b10): sync error only
            default: begin
                sync_error_c          = 1'b1;
                decoder_data_out_c    = 64'h0;
                decoder_control_out_c = 8'h00;
            end
        endcase

        // Decode-error causes: invalid type field OR wrong control pattern.
        // Sync errors are reported ONLY on sync_error, never here.
        decoder_wrong_type_field = (sync_header == 2'b10) & ~type_field_valid;
        decoder_error_out_c      = decoder_wrong_type_field | decoder_wrong_ctrl_received;
    end

    // ----------------------------------------------------------------
    // Registered outputs: 1-cycle latency, async active-high reset,
    // hold previous output while valid is deasserted.
    // ----------------------------------------------------------------
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            decoder_data_out    <= 64'h0;
            decoder_control_out <= 8'h00;
            sync_error          <= 1'b0;
            decoder_error_out   <= 1'b0;
        end else if (decoder_data_valid_in) begin
            decoder_data_out    <= decoder_data_out_c;
            decoder_control_out <= decoder_control_out_c;
            sync_error          <= sync_error_c;
            decoder_error_out   <= decoder_error_out_c;
        end
    end

endmodule

module encoder (
    input  wire        clk_in,
    input  wire        rst_in,
    input  wire [63:0] encoder_data_in,
    input  wire [7:0]  encoder_control_in,
    output reg  [65:0] encoder_data_out
);

    // 2-bit sync header values
    localparam [1:0] SYNC_DATA    = 2'b01; // all octets are pure data
    localparam [1:0] SYNC_CONTROL = 2'b10; // at least one control character

    always @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            encoder_data_out <= 66'd0;
        end else begin
            if (encoder_control_in == 8'b00000000) begin
                // pure data encoding: pass 64-bit data with data sync header
                encoder_data_out <= {SYNC_DATA, encoder_data_in};
            end else begin
                // control character present: control encoding not supported,
                // drive zero data with the control sync header
                encoder_data_out <= {SYNC_CONTROL, 64'd0};
            end
        end
    end

endmodule


