module encoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic [63:0]  encoder_data_in,     // 64-bit data input
    input  logic [7:0]   encoder_control_in,  // 8-bit control input
    output logic [65:0]  encoder_data_out     // 66-bit encoded output
);

    logic [1:0]  sync_word;
    logic [63:0] encoded_data;

    // Per-byte control-character to code-byte mapping.
    //  /I/ Idle           0x07 -> 7'h00   (byte 0x00)
    //  /S/ Start          0xFB -> 4'b0000 (byte 0x00)
    //  /T/ Terminate      0xFD -> 4'b0000 (byte 0x00)
    //  /E/ Error          0xFE -> 7'h1E   (byte 0x1E)
    //  /Q/ Ordered set    0x9C -> 4'b1111 (byte 0x0F)
    function automatic [7:0] ctrl_code(input [7:0] b);
        case (b)
            8'h07:   ctrl_code = 8'h00;
            8'hFB:   ctrl_code = 8'h00;
            8'hFD:   ctrl_code = 8'h00;
            8'hFE:   ctrl_code = 8'h1E;
            8'h9C:   ctrl_code = 8'h0F;
            default: ctrl_code = 8'h00;
        endcase
    endfunction

    // One byte-lane of the byte-oriented encoding: control bytes are replaced
    // by their code byte, data bytes pass through unchanged.
    function automatic [7:0] enc_lane(input ctrl_bit, input [7:0] b);
        enc_lane = ctrl_bit ? ctrl_code(b) : b;
    endfunction

    // Block type field lookup, keyed on the control pattern and, where the
    // pattern is ambiguous, on the distinguishing control character.
    function automatic [7:0] type_lookup(input [7:0] ctrl,
                                         input [7:0] byte0,
                                         input [7:0] byte4);
        case (ctrl)
            8'hFF:   type_lookup = (byte0 == 8'hFD) ? 8'h87 : 8'h1E; // all control / T0
            8'h80:   type_lookup = 8'hFF;                           // T7
            8'hC0:   type_lookup = 8'hE1;                           // T6
            8'hE0:   type_lookup = 8'hD2;                           // T5
            8'hF0:   type_lookup = 8'hCC;                           // T4
            8'hF8:   type_lookup = 8'hB4;                           // T3
            8'hFC:   type_lookup = 8'hAA;                           // T2
            8'hFE:   type_lookup = (byte0 == 8'hFD) ? 8'h87 : 8'h99; // T0 / T1
            8'h1F:   type_lookup = (byte4 == 8'h9C) ? 8'h2D : 8'h33; // Q4 / S4
            8'h01:   type_lookup = 8'h78;                           // S0
            8'hF1:   type_lookup = 8'h4B;                           // Q0
            8'h11:   type_lookup = (byte4 == 8'hFB) ? 8'h66 : 8'h55; // S4+Q0 / Q4+Q0
            default: type_lookup = 8'h1E;
        endcase
    endfunction

    logic [63:0] enc_bytes;
    logic [7:0]  type_field;

    assign enc_bytes[7:0]   = enc_lane(encoder_control_in[0], encoder_data_in[7:0]);
    assign enc_bytes[15:8]  = enc_lane(encoder_control_in[1], encoder_data_in[15:8]);
    assign enc_bytes[23:16] = enc_lane(encoder_control_in[2], encoder_data_in[23:16]);
    assign enc_bytes[31:24] = enc_lane(encoder_control_in[3], encoder_data_in[31:24]);
    assign enc_bytes[39:32] = enc_lane(encoder_control_in[4], encoder_data_in[39:32]);
    assign enc_bytes[47:40] = enc_lane(encoder_control_in[5], encoder_data_in[47:40]);
    assign enc_bytes[55:48] = enc_lane(encoder_control_in[6], encoder_data_in[55:48]);
    assign enc_bytes[63:56] = enc_lane(encoder_control_in[7], encoder_data_in[63:56]);

    assign type_field = type_lookup(encoder_control_in,
                                    encoder_data_in[7:0],
                                    encoder_data_in[39:32]);

    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            sync_word    <= 2'b00;
            encoded_data <= 64'b0;
        end else begin
            if (encoder_control_in == 8'b00000000) begin
                // Data-only mode: sync = 01, full 64 bits are data (no type field).
                sync_word    <= 2'b01;
                encoded_data <= encoder_data_in;
            end else begin
                // Control-only / mixed mode: sync = 10, 8-bit type field, 56-bit encoded data.
                sync_word    <= 2'b10;
                encoded_data <= {type_field, enc_bytes[55:0]};
            end
        end
    end

    assign encoder_data_out = {sync_word, encoded_data};

endmodule

module encoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic [63:0]  encoder_data_in,     // 64-bit data input
    input  logic [7:0]   encoder_control_in,  // 8-bit control input
    output logic [65:0]  encoder_data_out     // 66-bit encoded output
);

    // Registered state
    logic [1:0]  sync_word;
    logic [63:0] encoded_data;
    logic [1:0]  sync_ctrl_word;
    logic [7:0]  type_field;
    logic [55:0] encoded_ctrl_words;

    // Shared combinational match signals: each wide-constant comparison is
    // computed exactly ONCE and reused to drive both the block type field and
    // the control-word payload (originally these compares were duplicated
    // between the get_output function and the encoded_ctrl_words case).
    wire m_ff_a = (encoder_data_in == 64'h0707070707070707);
    wire m_ff_b = (encoder_data_in == 64'hFEFEFEFEFEFEFEFE);
    wire m_ff_c = (encoder_data_in == 64'h07070707070707FD);
    wire m_1f_a = (encoder_data_in[39:0]  == 40'hFB07070707);
    wire m_1f_b = (encoder_data_in[39:0]  == 40'h9C07070707);
    wire m_01   = (encoder_data_in[7:0]   == 8'hFB);
    wire m_fe   = (encoder_data_in[63:8]  == 56'h070707070707FD);
    wire m_fc   = (encoder_data_in[63:16] == 48'h0707070707FD);
    wire m_f8   = (encoder_data_in[63:24] == 40'h07070707FD);
    wire m_f0   = (encoder_data_in[63:32] == 32'h070707FD);
    wire m_e0   = (encoder_data_in[63:40] == 24'h0707FD);
    wire m_c0   = (encoder_data_in[63:48] == 16'h07FD);
    wire m_80   = (encoder_data_in[63:56] == 8'hFD);
    wire m_f1   = ({encoder_data_in[63:32], encoder_data_in[7:0]} == 40'h070707079C);
    wire m_11_a = ({encoder_data_in[39:32], encoder_data_in[7:0]} == 16'h9C9C);
    wire m_11_b = ({encoder_data_in[39:32], encoder_data_in[7:0]} == 16'hFB9C);

    // Single registered block (one clock cycle latency preserved). The type
    // field and control-word payload are decoded together from the shared
    // match signals, folding the former get_output priority chain and the
    // encoded_ctrl_words case into one decode. Each field keeps its original
    // update semantics, including the sticky hold on sync_ctrl_word when the
    // control bus is all-zero and the odd 56'hFFFFFFF default on the 0xF0 case.
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            sync_word          <= 2'b00;
            encoded_data       <= 64'b0;
            sync_ctrl_word     <= 2'b00;
            type_field         <= 8'b0;
            encoded_ctrl_words <= 56'b0;
        end else begin
            sync_word    <= (encoder_control_in == 8'b00000000) ? 2'b01 : 2'b10;
            encoded_data <= (encoder_control_in == 8'b00000000) ? encoder_data_in : 64'b0;
            if (encoder_control_in != 8'b00000000)
                sync_ctrl_word <= 2'b10;

            // Defaults (no match / unlisted control): both fields clear to 0.
            type_field         <= 8'h00;
            encoded_ctrl_words <= 56'h0;
            case (encoder_control_in)
                8'b11111111: begin
                    if (m_ff_a)      begin type_field <= 8'h1e; encoded_ctrl_words <= 56'h0; end
                    else if (m_ff_b) begin type_field <= 8'h1e; encoded_ctrl_words <= {7'h1E, 7'h1E, 7'h1E, 7'h1E, 7'h1E, 7'h1E, 7'h1E, 7'h1E}; end
                    else if (m_ff_c) begin type_field <= 8'h87; encoded_ctrl_words <= 56'h0; end
                end
                8'b00011111: begin
                    if (m_1f_a)      begin type_field <= 8'h33; encoded_ctrl_words <= {encoder_data_in[63:40], 4'h0, 7'h00, 7'h00, 7'h00, 7'h00}; end
                    else if (m_1f_b) begin type_field <= 8'h2d; encoded_ctrl_words <= {encoder_data_in[63:40], 4'hF, 7'h00, 7'h00, 7'h00, 7'h00}; end
                end
                8'b00000001: begin
                    if (m_01) begin type_field <= 8'h78; encoded_ctrl_words <= {encoder_data_in[63:8]}; end
                end
                8'b11111110: begin
                    if (m_fe) begin type_field <= 8'h99; encoded_ctrl_words <= {7'h00, 7'h00, 7'h00, 7'h00, 7'h00, 7'h00, 6'b000000, encoder_data_in[7:0]}; end
                end
                8'b11111100: begin
                    if (m_fc) begin type_field <= 8'haa; encoded_ctrl_words <= {7'h00, 7'h00, 7'h00, 7'h00, 7'h00, 5'b00000, encoder_data_in[15:0]}; end
                end
                8'b11111000: begin
                    if (m_f8) begin type_field <= 8'hb4; encoded_ctrl_words <= {7'h00, 7'h00, 7'h00, 7'h00, 4'b0000, encoder_data_in[23:0]}; end
                end
                8'b11110000: begin
                    if (m_f0) begin type_field <= 8'hcc; encoded_ctrl_words <= {7'h00, 7'h00, 7'h00, 3'b000, encoder_data_in[31:0]}; end
                    else      begin encoded_ctrl_words <= 56'hFFFFFFF; end
                end
                8'b11100000: begin
                    if (m_e0) begin type_field <= 8'hd2; encoded_ctrl_words <= {7'h00, 7'h00, 2'b00, encoder_data_in[39:0]}; end
                end
                8'b11000000: begin
                    if (m_c0) begin type_field <= 8'he1; encoded_ctrl_words <= {7'h00, 1'b0, encoder_data_in[47:0]}; end
                end
                8'b10000000: begin
                    if (m_80) begin type_field <= 8'hff; encoded_ctrl_words <= encoder_data_in[55:0]; end
                end
                8'b11110001: begin
                    if (m_f1) begin type_field <= 8'h4b; encoded_ctrl_words <= {7'h00, 7'h00, 7'h00, 7'h00, encoder_data_in[31:8], 4'b1111}; end
                end
                8'b00010001: begin
                    if (m_11_a)      begin type_field <= 8'h55; encoded_ctrl_words <= {encoder_data_in[63:40], 8'hFF, encoder_data_in[31:8]}; end
                    else if (m_11_b) begin type_field <= 8'h66; encoded_ctrl_words <= {encoder_data_in[63:40], 8'h0F, encoder_data_in[31:8]}; end
                end
                default: begin type_field <= 8'h00; encoded_ctrl_words <= 56'd0; end
            endcase
        end
    end

    always_comb begin
        if (|encoder_control_in)
            encoder_data_out = {sync_ctrl_word, type_field, encoded_ctrl_words};
        else
            encoder_data_out = {sync_word, encoded_data};
    end

endmodule

