// Parameterized priority encoder.
//   N = input width, M = log2(N) = output width.
//   MSB of input_signal has the highest priority, LSB the lowest.
//   Outputs the index of the highest-priority active input; 0 when none active.
module priority_encoder #(
    parameter N = 8,
    parameter M = $clog2(N)
) (
    input      [N-1:0] input_signal,   // N-bit input to encode
    output reg [M-1:0] out             // index of highest-priority active bit
);

    integer i;

    always @(*) begin
        out = {M{1'b0}};                 // default when no inputs are active
        // Ascending scan: the highest active index writes last and wins,
        // so the MSB holds the highest priority.
        for (i = 0; i < N; i = i + 1) begin
            if (input_signal[i])
                out = i[M-1:0];
        end
    end

endmodule

// Cascaded priority encoder: splits input_signal into an upper and a lower
// half, encodes each half with a priority_encoder instance, then combines
// the two half-results into the full index. MSB keeps the highest priority.
module cascaded_encoder #(
    parameter N = 8,
    parameter M = $clog2(N)
) (
    input      [N-1:0] input_signal,     // N-bit input to encode
    output reg [M-1:0] out,              // full highest-priority index
    output     [M-2:0] out_upper_half,   // highest-priority index of MS half
    output     [M-2:0] out_lower_half    // highest-priority index of LS half
);

    // Split into most-significant (upper) and least-significant (lower) halves.
    wire [N/2-1:0] upper_half = input_signal[N-1:N/2];
    wire [N/2-1:0] lower_half = input_signal[N/2-1:0];

    wire upper_active = |upper_half;

    // Encode each half; each half is N/2 wide -> (M-1)-bit index.
    priority_encoder #(.N(N/2), .M(M-1)) pe_upper (
        .input_signal (upper_half),
        .out          (out_upper_half)
    );

    priority_encoder #(.N(N/2), .M(M-1)) pe_lower (
        .input_signal (lower_half),
        .out          (out_lower_half)
    );

    // Combine: if any upper-half bit is active it wins (its full index is
    // offset by N/2 -> MSB of out set); otherwise fall back to the lower half.
    always @(*) begin
        if (upper_active)
            out = {1'b1, out_upper_half};
        else if (|lower_half)
            out = {1'b0, out_lower_half};
        else
            out = {M{1'b0}};             // default when no inputs are active
    end

endmodule

module Attenuator (
    input        clk,
    input        reset,
    input  [4:0] data,
    output reg   ATTN_CLK,
    output reg   ATTN_DATA,
    output reg   ATTN_LE
);

// Internal Signals
reg        clk_div2;
reg  [1:0] current_state, next_state;
reg  [4:0] shift_reg;
reg  [2:0] bit_count;
reg  [4:0] old_data;

// Parameters for FSM States
localparam IDLE  = 2'b00,
           LOAD  = 2'b01,
           SHIFT = 2'b10,
           LATCH = 2'b11;

// Next-state combinational logic
always @(*) begin
    next_state = current_state;
    case (current_state)
        IDLE   : if (data != old_data) next_state = LOAD;
        LOAD   : next_state = SHIFT;
        SHIFT  : if (bit_count == 3'd5) next_state = LATCH;
        LATCH  : next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

// Sequential FSM + datapath (async reset per partial code)
always @(posedge clk or posedge reset) begin
    if (reset) begin
        clk_div2      <= 1'b0;
        current_state <= IDLE;
        ATTN_CLK      <= 1'b0;
        ATTN_DATA     <= 1'b0;
        ATTN_LE       <= 1'b0;
        shift_reg     <= 5'b00000;
        bit_count     <= 3'd0;
        old_data      <= 5'b00000;
    end else begin
        // Clock divider: generate a half-rate communication clock
        clk_div2 <= ~clk_div2;

        // State register
        current_state <= next_state;

        case (current_state)
            IDLE: begin
                ATTN_CLK  <= 1'b0;
                ATTN_DATA <= 1'b0;
                ATTN_LE   <= 1'b0;
                bit_count <= 3'd0;
                // Detect a newly-loaded control word
                if (data != old_data) begin
                    shift_reg <= data;
                    old_data  <= data;
                end
            end

            LOAD: begin
                // Capture the 5-bit control word into the shift register
                shift_reg <= data;
                old_data  <= data;
                bit_count <= 3'd0;
                ATTN_CLK  <= 1'b0;
                ATTN_DATA <= 1'b0;
                ATTN_LE   <= 1'b0;
            end

            SHIFT: begin
                ATTN_LE <= 1'b0;
                // Toggle the attenuator clock at the divided rate
                ATTN_CLK <= clk_div2;
                if (clk_div2 == 1'b0) begin
                    // Present the next bit (MSB-first) while the clock is low
                    ATTN_DATA <= shift_reg[4];
                    shift_reg <= {shift_reg[3:0], 1'b0};
                    bit_count <= bit_count + 3'd1;
                end
            end

            LATCH: begin
                // Pulse the latch-enable to load the shifted data
                ATTN_CLK  <= 1'b0;
                ATTN_DATA <= 1'b0;
                ATTN_LE   <= 1'b1;
                bit_count <= 3'd0;
            end

            default: begin
                ATTN_CLK  <= 1'b0;
                ATTN_DATA <= 1'b0;
                ATTN_LE   <= 1'b0;
            end
        endcase
    end
end

endmodule

module GP (
    output o_generate,
    output o_propagate,
    output o_Cout,
    input  i_A,
    input  i_B,
    input  i_Cin
);

    // Generate: carry is generated when both operand bits are 1
    assign o_generate  = i_A & i_B;

    // Propagate: carry is propagated when either operand bit is 1
    assign o_propagate = i_A | i_B;

    // Carry-out: generated, or propagated together with the incoming carry
    assign o_Cout      = o_generate | (o_propagate & i_Cin);

endmodule


