module pipelined_adder_32bit (
    input clk,       // Synchronous to posedge of clk
    input reset,     // Synchronous active high reset
    input [31:0] A,  // 32 bit operand for addition
    input [31:0] B,  // 32 bit operand for addition
    input start,     // Active high signal to indicate when valid input data is provided
    output [31:0] S, // Final sum or result
    output Co,       // Final carry out
    output done      // Completion signal, active high when computation is complete
);

    wire [7:0] A1, B1, A2, B2, A3, B3;
    wire carry1, carry2, carry3;
    wire [7:0] s13, s23, s12, A21, B21, A31, B31, A32, B32;
    wire [7:0] s1, s2, s3;
    wire control2, control1, control3, control4;

    // Stage 1: capture the start signal to initiate the pipeline
    dff #(1) FF00 (.clk(clk), .reset(reset), .D(start), .Q(control1));

    dff #(8) FF11 (.clk(clk), .reset(reset), .D(A[15:8]),  .Q(A1));
    dff #(8) FF12 (.clk(clk), .reset(reset), .D(B[15:8]),  .Q(B1));
    dff #(8) FF13 (.clk(clk), .reset(reset), .D(A[23:16]), .Q(A2));
    dff #(8) FF14 (.clk(clk), .reset(reset), .D(B[23:16]), .Q(B2));
    dff #(8) FF15 (.clk(clk), .reset(reset), .D(A[31:24]), .Q(A3));
    dff #(8) FF16 (.clk(clk), .reset(reset), .D(B[31:24]), .Q(B3));

    carry_lookahead_adder #(8) ADD1 (.clk(clk), .reset(reset), .A(A[7:0]), .B(B[7:0]), .Cin(1'b0), .S(s1), .carry(carry1));

    dff #(1) FF01 (.clk(clk), .reset(reset), .D(control1), .Q(control2));

    // Stage 2: forward byte2 to ADD3 next, forward byte3 one more stage
    dff #(8) FF21 (.clk(clk), .reset(reset), .D(s1), .Q(s12));
    dff #(8) FF23 (.clk(clk), .reset(reset), .D(A2), .Q(A21));
    dff #(8) FF24 (.clk(clk), .reset(reset), .D(B2), .Q(B21));
    dff #(8) FF25 (.clk(clk), .reset(reset), .D(A3), .Q(A31));
    dff #(8) FF26 (.clk(clk), .reset(reset), .D(B3), .Q(B31));

    carry_lookahead_adder #(8) ADD2 (.clk(clk), .reset(reset), .A(A1), .B(B1), .Cin(carry1), .S(s2), .carry(carry2));

    dff #(1) FF10 (.clk(clk), .reset(reset), .D(control2), .Q(control3));

    // Stage 3: ADD3 processes byte2, forward byte3 to ADD4
    dff #(8) FF31 (.clk(clk), .reset(reset), .D(s2),  .Q(s13));
    dff #(8) FF32 (.clk(clk), .reset(reset), .D(s12), .Q(s23));
    dff #(8) FF35 (.clk(clk), .reset(reset), .D(A31), .Q(A32));
    dff #(8) FF36 (.clk(clk), .reset(reset), .D(B31), .Q(B32));

    carry_lookahead_adder #(8) ADD3 (.clk(clk), .reset(reset), .A(A21), .B(B21), .Cin(carry2), .S(s3), .carry(carry3));

    dff #(1) FF111 (.clk(clk), .reset(reset), .D(control3), .Q(done));

    // Stage 4: assemble the 32-bit result (byte0->[7:0], byte1->[15:8], byte2->[23:16])
    dff #(8) FF41 (.clk(clk), .reset(reset), .D(s23), .Q(S[7:0]));
    dff #(8) FF42 (.clk(clk), .reset(reset), .D(s13), .Q(S[15:8]));
    dff #(8) FF43 (.clk(clk), .reset(reset), .D(s3),  .Q(S[23:16]));

    carry_lookahead_adder #(8) ADD4 (.clk(clk), .reset(reset), .A(A32), .B(B32), .Cin(carry3), .S(S[31:24]), .carry(Co));

endmodule

module carry_lookahead_adder #(parameter WIDTH = 32) (
    input [WIDTH-1:0] A,       // WIDTH bit operand for addition
    input [WIDTH-1:0] B,       // WIDTH bit operand for addition
    input Cin, clk, reset,     // Cin -> carry in, clk -> posedge, reset -> synchronous active high
    output reg [WIDTH-1:0] S,  // Final sum or result
    output reg carry           // Final carry out
);

    wire [WIDTH-1:0] P;
    wire [WIDTH-1:0] G;
    wire [WIDTH:0]   C;         // combinational carry vector

    wire [WIDTH-1:0] S1;
    wire carry1;

    // Generate (G) and Propagate (P)
    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : gp_gen
            assign P[i] = A[i] ^ B[i];
            assign G[i] = A[i] & B[i];
        end
    endgenerate

    // Carry calculation (combinational carry lookahead)
    assign C[0] = Cin;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : carry_chain
            assign C[i+1] = G[i] | (P[i] & C[i]);
        end
    endgenerate

    // Final sum
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : sum_gen
            assign S1[i] = P[i] ^ C[i];
        end
    endgenerate

    // Final carry-out is the MSB of the carry vector
    assign carry1 = C[WIDTH];

    // Latch combinational sum/carry to the module output on posedge clk
    always @(posedge clk) begin
        if (reset) begin
            S <= 0;
            carry <= 0;
        end else begin
            S <= S1;
            carry <= carry1;
        end
    end

endmodule

module dff #(parameter WIDTH = 1) (
    input clk,               // clk -> Synchronous to posedge of clk
    input reset,             // reset -> Synchronous active high reset
    input [WIDTH-1:0] D,     // D -> Data signal
    output reg [WIDTH-1:0] Q // Q -> Output signal
);
    always @(posedge clk) begin
        if (reset)
            Q <= {WIDTH{1'b0}};
        else
            Q <= D;
    end
endmodule

module fir_filter (
    input logic clk,                 // Clock signal
    input logic reset,               // Reset signal
    input logic signed [15:0] input_sample,  // Input data sample
    output logic signed [15:0] output_sample, // Output filtered sample
    input logic signed [15:0] coeff0, // Coefficient for current input sample
    input logic signed [15:0] coeff1, // Coefficient for first delay
    input logic signed [15:0] coeff2, // Coefficient for second delay
    input logic signed [15:0] coeff3  // Coefficient for third delay
);

    // Declare internal storage for delay elements and accumulation
    logic signed [15:0] sample_delay1, sample_delay2, sample_delay3;
    logic signed [31:0] accumulator;

    // Sequential block to handle operations on clock or reset
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset state: Clear all registers and output
            sample_delay1 <= 16'sd0;
            sample_delay2 <= 16'sd0;
            sample_delay3 <= 16'sd0;
            accumulator   <= 32'sd0;
            output_sample <= 16'sd0;
        end else begin
            // Regular operation: Shift samples, compute filtered output

            // Data propagation: shift the input through the delay line
            sample_delay1 <= input_sample;
            sample_delay2 <= sample_delay1;
            sample_delay3 <= sample_delay2;

            // Accumulation: multiply each sample by its coefficient and sum.
            // Signed 16x16 products widen to the 32-bit signed accumulator.
            accumulator   <= (coeff0 * input_sample) +
                             (coeff1 * sample_delay1) +
                             (coeff2 * sample_delay2) +
                             (coeff3 * sample_delay3);

            // Output register: total latency to the fully-filtered result is
            // 4 clock cycles after the input sample is first registered.
            output_sample <= accumulator[15:0];
        end
    end

endmodule


