module fir_filter (
    input wire clk,                  // Clock signal
    input wire reset,                // Asynchronous reset
    input wire [15:0] data_in,       // Input data
    output reg [15:0] data_out,      // Filtered output data
    input wire [1:0] window_type     // Window type selector: 0-Rectangular, 1-Hanning, 2-Hamming, 3-Blackman
);

    reg [15:0] coeff0, coeff1, coeff2, coeff3, coeff4, coeff5, coeff6, coeff7;
    reg [15:0] shift_reg0, shift_reg1, shift_reg2, shift_reg3, shift_reg4, shift_reg5, shift_reg6, shift_reg7;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset logic: zero the output and all shift registers
            data_out   <= 16'd0;
            shift_reg0 <= 16'd0;
            shift_reg1 <= 16'd0;
            shift_reg2 <= 16'd0;
            shift_reg3 <= 16'd0;
            shift_reg4 <= 16'd0;
            shift_reg5 <= 16'd0;
            shift_reg6 <= 16'd0;
            shift_reg7 <= 16'd0;
        end else begin
            // Shift register updates: cascade data_in through the delay line
            shift_reg0 <= data_in;
            shift_reg1 <= shift_reg0;
            shift_reg2 <= shift_reg1;
            shift_reg3 <= shift_reg2;
            shift_reg4 <= shift_reg3;
            shift_reg5 <= shift_reg4;
            shift_reg6 <= shift_reg5;
            shift_reg7 <= shift_reg6;

            // Coefficient selection based on window type
            case (window_type)
                2'b00: begin // Rectangular window: sequential 10..17
                    coeff0 <= 16'd10;
                    coeff1 <= 16'd11;
                    coeff2 <= 16'd12;
                    coeff3 <= 16'd13;
                    coeff4 <= 16'd14;
                    coeff5 <= 16'd15;
                    coeff6 <= 16'd16;
                    coeff7 <= 16'd17;
                end
                2'b01: begin // Hanning window
                    coeff0 <= 16'd2;
                    coeff1 <= 16'd4;
                    coeff2 <= 16'd8;
                    coeff3 <= 16'd12;
                    coeff4 <= 16'd12;
                    coeff5 <= 16'd8;
                    coeff6 <= 16'd4;
                    coeff7 <= 16'd2;
                end
                2'b10: begin // Hamming window
                    coeff0 <= 16'd3;
                    coeff1 <= 16'd6;
                    coeff2 <= 16'd9;
                    coeff3 <= 16'd11;
                    coeff4 <= 16'd11;
                    coeff5 <= 16'd9;
                    coeff6 <= 16'd6;
                    coeff7 <= 16'd3;
                end
                2'b11: begin // Blackman window
                    coeff0 <= 16'd1;
                    coeff1 <= 16'd2;
                    coeff2 <= 16'd5;
                    coeff3 <= 16'd9;
                    coeff4 <= 16'd9;
                    coeff5 <= 16'd5;
                    coeff6 <= 16'd2;
                    coeff7 <= 16'd1;
                end
                default: begin
                    coeff0 <= 16'd10;
                    coeff1 <= 16'd11;
                    coeff2 <= 16'd12;
                    coeff3 <= 16'd13;
                    coeff4 <= 16'd14;
                    coeff5 <= 16'd15;
                    coeff6 <= 16'd16;
                    coeff7 <= 16'd17;
                end
            endcase

            // Output calculation: sum of coefficient-weighted taps, normalized by >>> 4
            data_out <= (coeff0 * shift_reg0 +
                         coeff1 * shift_reg1 +
                         coeff2 * shift_reg2 +
                         coeff3 * shift_reg3 +
                         coeff4 * shift_reg4 +
                         coeff5 * shift_reg5 +
                         coeff6 * shift_reg6 +
                         coeff7 * shift_reg7) >>> 4;
        end
    end
endmodule


