// glitch_free_mux: glitch-free switching between two synchronous input clocks.
//   sel = 0 -> clkout = clk1
//   sel = 1 -> clkout = clk2
// Standard 2-flop cross-coupled clock-mux: each clock's enable is de-asserted
// (in its own domain) before the other clock's enable is asserted, so the
// output gate is never opened on two clocks at once -> no glitch.
module glitch_free_mux (
    input  wire clk1,
    input  wire clk2,
    input  wire sel,
    input  wire rst_n,
    output wire clkout
);

    // First synchronizer stage in each clock domain.
    reg clk1_sync;
    reg clk2_sync;

    // Second stage = the qualified per-clock enables (spec waveform names).
    reg clk1_en;
    reg clk2_en;

    // clk1 domain: request clk1 when sel==0 and clk2 is already disabled.
    always @(posedge clk1 or negedge rst_n) begin
        if (!rst_n) begin
            clk1_sync <= 1'b0;
            clk1_en   <= 1'b0;
        end else begin
            clk1_sync <= ~sel & ~clk2_en;
            clk1_en   <= clk1_sync;
        end
    end

    // clk2 domain: request clk2 when sel==1 and clk1 is already disabled.
    always @(posedge clk2 or negedge rst_n) begin
        if (!rst_n) begin
            clk2_sync <= 1'b0;
            clk2_en   <= 1'b0;
        end else begin
            clk2_sync <= sel & ~clk1_en;
            clk2_en   <= clk2_sync;
        end
    end

    // Gate each clock with its enable; only one enable is ever high, and the
    // reset drives both enables (hence clkout) low.
    assign clkout = (clk1 & clk1_en) | (clk2 & clk2_en);

endmodule


