module glitch_free_mux
(
    input  clk1,    // input clk1
    input  clk2,    // input clk2
    input  rst_n,   // async reset
    input  sel,     // selection line
    output clkout   // clock output
);

    // Final per-domain enable registers (spec-named).  These drive the output
    // AND-mask and are guaranteed never to be high simultaneously
    // (break-before-make cross-coupling).
    reg clk1_enable;
    reg clk2_enable;

    // First (metastability-capture) stage of each domain's enable path.
    // Together with the final *_enable flop these form a genuine two-flop
    // clock-domain-crossing synchronizer for the enable launched by the OTHER
    // clock, so the async input can never propagate to clkout while metastable.
    reg clk1_enable_pre;
    reg clk2_enable_pre;

    // ------------------------------------------------------------------
    // CLK1 domain.  Enable clk1 only when sel==0 and clk2 is fully
    // disabled.  clk2_enable is LAUNCHED by clk2 and CAPTURED here by clk1:
    //   clk1_enable_pre = 1st (meta) flop, clk1_enable = 2nd (resolving) flop.
    // The two posedge-clk1 stages also give the required 2-clk1-edge latency:
    // on a sel 0->1 change clk1_enable clears on the SECOND clk1 posedge.
    // ------------------------------------------------------------------
    always @(posedge clk1 or negedge rst_n) begin
        if (~rst_n) begin
            clk1_enable_pre <= 1'b0;
            clk1_enable     <= 1'b0;
        end else begin
            clk1_enable_pre <= ~sel & ~clk2_enable;
            clk1_enable     <= clk1_enable_pre;
        end
    end

    // ------------------------------------------------------------------
    // CLK2 domain.  Enable clk2 only when sel==1 and clk1 is fully
    // disabled.  clk1_enable is LAUNCHED by clk1 and CAPTURED here by clk2:
    //   clk2_enable_pre = 1st (meta) flop, clk2_enable = 2nd (resolving) flop.
    // The two posedge-clk2 stages give the required 2-clk2-edge latency:
    // after clk1 is disabled, clk2_enable asserts on the SECOND clk2 posedge.
    // ------------------------------------------------------------------
    always @(posedge clk2 or negedge rst_n) begin
        if (~rst_n) begin
            clk2_enable_pre <= 1'b0;
            clk2_enable     <= 1'b0;
        end else begin
            clk2_enable_pre <= sel & ~clk1_enable;
            clk2_enable     <= clk2_enable_pre;
        end
    end

    // ------------------------------------------------------------------
    // Glitch-free output.  Only one enable is ever asserted, and each mask
    // settles through a two-flop path so it changes while its own clock is at
    // the idle level -> no runt / glitch pulses on clkout during a switch.
    // ------------------------------------------------------------------
    assign clkout = (clk1 & clk1_enable) | (clk2 & clk2_enable);

endmodule

module iir_filter (
    input  logic clk,
    input  logic rst,
    input  logic signed [15:0] x,
    output logic signed [15:0] y
);

    parameter signed [15:0] b0 = 16'h0F00;
    parameter signed [15:0] b1 = 16'h0E00;
    parameter signed [15:0] b2 = 16'h0D00;
    parameter signed [15:0] b3 = 16'h0C00;
    parameter signed [15:0] b4 = 16'h0B00;
    parameter signed [15:0] b5 = 16'h0A00;
    parameter signed [15:0] b6 = 16'h0900;
    parameter signed [15:0] a1 = -16'h0800;
    parameter signed [15:0] a2 = -16'h0700;
    parameter signed [15:0] a3 = -16'h0600;
    parameter signed [15:0] a4 = -16'h0500;
    parameter signed [15:0] a5 = -16'h0400;
    parameter signed [15:0] a6 = -16'h0300;

    logic signed [15:0] x_prev1, x_prev2, x_prev3, x_prev4, x_prev5, x_prev6;
    logic signed [15:0] y_prev1, y_prev2, y_prev3, y_prev4, y_prev5, y_prev6;

    // Combinational filter accumulation (moved out of the sequential block).
    // 32-bit signed context preserves the original arithmetic exactly: the whole
    // multiply-accumulate is context-determined to 32 bits, then >>> 16. Only the
    // low 16 bits of the shifted result feed y (== sum[31:16]); the upper 16 bits
    // are redundant sign bits that are intentionally unused.
    /* verilator lint_off UNUSEDSIGNAL */
    logic signed [31:0] temp_y;
    /* verilator lint_on UNUSEDSIGNAL */

    always_comb begin
        temp_y = (b0 * x + b1 * x_prev1 + b2 * x_prev2 + b3 * x_prev3 +
                  b4 * x_prev4 + b5 * x_prev5 + b6 * x_prev6 -
                  a1 * y_prev1 - a2 * y_prev2 - a3 * y_prev3 -
                  a4 * y_prev4 - a5 * y_prev5 - a6 * y_prev6) >>> 16;
    end

    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            y       <= 16'sd0;
            x_prev1 <= 16'sd0; x_prev2 <= 16'sd0; x_prev3 <= 16'sd0;
            x_prev4 <= 16'sd0; x_prev5 <= 16'sd0; x_prev6 <= 16'sd0;
            y_prev1 <= 16'sd0; y_prev2 <= 16'sd0; y_prev3 <= 16'sd0;
            y_prev4 <= 16'sd0; y_prev5 <= 16'sd0; y_prev6 <= 16'sd0;
        end else begin
            if (x > 16'h8000)
                y <= 16'h7FFF;
            else
                y <= temp_y[15:0];

            x_prev6 <= x_prev5; x_prev5 <= x_prev4; x_prev4 <= x_prev3;
            x_prev3 <= x_prev2; x_prev2 <= x_prev1; x_prev1 <= x;
            y_prev6 <= y_prev5; y_prev5 <= y_prev4; y_prev4 <= y_prev3;
            y_prev3 <= y_prev2; y_prev2 <= y_prev1; y_prev1 <= y;
        end
    end

endmodule

`define NOTCONNECTED_PIN(x)   /* verilator lint_off PINCONNECTEMPTY */ \
                        . x () \
                        /* verilator lint_on PINCONNECTEMPTY */

module cache_mshr #(
    parameter INSTANCE_ID                   = "mo_mshr"             ,
    parameter MSHR_SIZE                     = 32                    ,
    parameter CS_LINE_ADDR_WIDTH            = 10                    ,
    parameter WORD_SEL_WIDTH                = 4                     ,
    parameter WORD_SIZE                     = 4                     ,
    // Derived parameters
    parameter MSHR_ADDR_WIDTH               = $clog2(MSHR_SIZE)     , // default = 5
    parameter TAG_WIDTH                     = 32 - (CS_LINE_ADDR_WIDTH+ $clog2(WORD_SIZE) + WORD_SEL_WIDTH), // default = 16
    parameter CS_WORD_WIDTH                 = WORD_SIZE * 8 ,// default = 32
    parameter DATA_WIDTH                    = WORD_SEL_WIDTH + WORD_SIZE + CS_WORD_WIDTH + TAG_WIDTH // default =  4 + 4 + 32 + 16 = 56

    ) (
    input wire clk,
    input wire reset,

    // allocate
    input wire                          allocate_valid,
    output wire                         allocate_ready,
    input wire [CS_LINE_ADDR_WIDTH-1:0] allocate_addr,
    input wire                          allocate_rw,
    input wire [DATA_WIDTH-1:0]         allocate_data,
    output wire [MSHR_ADDR_WIDTH-1:0]   allocate_id,
    output wire                         allocate_pending,
    output wire [MSHR_ADDR_WIDTH-1:0]   allocate_previd,

    // finalize
    input wire                          finalize_valid,
    input wire [MSHR_ADDR_WIDTH-1:0]    finalize_id
);

    // -------------------------------------------------------------------------
    // Intermediate variable initialization
    // -------------------------------------------------------------------------
    // Per-entry meta-data registers (the MSHR entry register file)
    reg [CS_LINE_ADDR_WIDTH-1:0] cs_line_addr_table [0:MSHR_SIZE-1];
    reg [MSHR_SIZE-1:0]          entry_valid_table_q, entry_valid_table_d;
    reg [MSHR_SIZE-1:0]          is_write_table;

    reg [MSHR_SIZE-2:0]          next_ptr_valid_table_q, next_ptr_valid_table_d;
    reg [MSHR_ADDR_WIDTH-1:0]    next_index_ptr [0:MSHR_SIZE-1]; // ptr to the next index

    reg                          allocate_pending_q;
    wire                         allocate_pending_d;

    wire [MSHR_ADDR_WIDTH-1:0]   allocate_id_d;   // first available slot index (comb)
    reg  [MSHR_ADDR_WIDTH-1:0]   allocate_id_q;   // registered (1-cycle latency)

    wire [MSHR_ADDR_WIDTH-1:0]   prev_idx;        // tail index of matching chain (comb)
    reg  [MSHR_ADDR_WIDTH-1:0]   prev_idx_q;      // registered (1-cycle latency)

    wire                         full_d;          // MSHR is full when no free slot

    wire allocate_fire = allocate_valid && allocate_ready;

    // Address lookup: which valid entries match the incoming allocate address.
    wire [MSHR_SIZE-1:0] addr_matches;
    genvar gi;
    generate
        for (gi = 0; gi < MSHR_SIZE; gi = gi + 1) begin : g_addr_matches
            assign addr_matches[gi] = entry_valid_table_q[gi]
                                   && (cs_line_addr_table[gi] == allocate_addr)
                                   && allocate_fire;
        end
    endgenerate

    // The chain tail is the matching entry that does not yet have a next pointer.
    wire [MSHR_SIZE-1:0] match_with_no_next = addr_matches & ~next_ptr_valid_table_q;

    leading_zero_cnt #(
            .DATA_WIDTH (MSHR_SIZE),
            .REVERSE (1)
    ) allocate_idx (
            .data   (~entry_valid_table_q), // bit-wise invert for availabe slots
            .leading_zeros  (allocate_id_d),
            .all_zeros (full_d)
    );

    leading_zero_cnt #(
            .DATA_WIDTH (MSHR_SIZE),
            .REVERSE (1)
    ) allocate_prev_idx (
            .data   (match_with_no_next), // allocate address matches that doesn't have next address pointer
            .leading_zeros  (prev_idx),
            `NOTCONNECTED_PIN(all_zeros) // not connected
    );

    // -------------------------------------------------------------------------
    // MSHR RTL implementation (allocation + finalize)
    // -------------------------------------------------------------------------
    // Next-state of the valid / next-pointer-valid tables (combinational).
    always @(*) begin
        entry_valid_table_d    = entry_valid_table_q;
        next_ptr_valid_table_d = next_ptr_valid_table_q;

        // finalize: release (invalidate) the entry (e.g. cache-hit release)
        if (finalize_valid) begin
            entry_valid_table_d[finalize_id] = 1'b0;
        end

        // allocate: reserve the first available slot for the new request
        if (allocate_fire) begin
            entry_valid_table_d[allocate_id_d]    = 1'b1;
            next_ptr_valid_table_d[allocate_id_d] = 1'b0;
        end

        // pending (outstanding miss to same line): link previous tail to new slot
        if (allocate_pending_d) begin
            next_ptr_valid_table_d[prev_idx] = 1'b1;
        end
    end

    // Sequential state update (synchronous active-high reset).
    always @(posedge clk) begin
        if (reset) begin
            entry_valid_table_q    <= '0;
            next_ptr_valid_table_q <= '0;
            allocate_pending_q     <= 1'b0;
        end else begin
            entry_valid_table_q    <= entry_valid_table_d;
            next_ptr_valid_table_q <= next_ptr_valid_table_d;
            allocate_pending_q     <= allocate_pending_d;
        end

        if (allocate_fire) begin
            cs_line_addr_table[allocate_id_d] <= allocate_addr;
            is_write_table[allocate_id_d]     <= allocate_rw;
        end

        if (allocate_pending_d) begin
            next_index_ptr[prev_idx] <= allocate_id_d;
        end
    end

    // Registered allocation outputs (introduces the 1-cycle allocation latency).
    always @(posedge clk) begin
        if (reset) begin
            allocate_id_q <= '0;
            prev_idx_q    <= '0;
        end else begin
            if (allocate_fire) begin
                allocate_id_q <= allocate_id_d;
                prev_idx_q    <= prev_idx;
            end
        end
    end

    // Single-port RAM storing the MSHR entry data (write latency 1 cycle).
    reg [DATA_WIDTH-1:0] ram [0:MSHR_SIZE-1];
    always @(posedge clk) begin
        if (allocate_fire) begin
            ram[allocate_id_d] <= allocate_data;
        end
    end

    // Output assignments
    assign allocate_pending_d = |addr_matches;
    assign allocate_id        = allocate_id_q;
    assign allocate_ready     = ~full_d;
    assign allocate_previd    = prev_idx_q;
    assign allocate_pending   = allocate_pending_q;

endmodule


module leading_zero_cnt #(
    parameter DATA_WIDTH = 32,
    parameter REVERSE = 0
)(
    input  [DATA_WIDTH -1:0] data,
    output  [$clog2(DATA_WIDTH)-1:0] leading_zeros,
    output all_zeros
);
    localparam NIBBLES_NUM = DATA_WIDTH/4 ;
    reg [NIBBLES_NUM-1 :0] all_zeros_flag ;
    reg [1:0]  zeros_cnt_per_nibble [NIBBLES_NUM-1 :0]  ;

    genvar i;
    integer k ;
    // Assign data/nibble
    reg [3:0]  data_per_nibble [NIBBLES_NUM-1 :0]  ;
    generate
        for (i=0; i < NIBBLES_NUM ; i=i+1) begin
            always @* begin
                data_per_nibble[i] = data[(i*4)+3: (i*4)] ;
            end
        end
    endgenerate

    generate
        for (i=0; i < NIBBLES_NUM ; i=i+1) begin : g_nibble
            if (REVERSE) begin : g_trailing
                always @* begin
                        zeros_cnt_per_nibble[i] [1] = ~(data_per_nibble[i][1] | data_per_nibble[i][0]);
                        zeros_cnt_per_nibble[i] [0] = (~data_per_nibble[i][0]) &
                                                      ((~data_per_nibble[i][2]) | data_per_nibble[i][1]);
                        all_zeros_flag[i] = (data_per_nibble[i] == 4'b0000);
                end
            end else begin :g_leading
                always @* begin
                    zeros_cnt_per_nibble[NIBBLES_NUM-1-i][1] = ~(data_per_nibble[i][3] | data_per_nibble[i][2]);
                    zeros_cnt_per_nibble[NIBBLES_NUM-1-i][0] = (~data_per_nibble[i][3]) &
                                     ((~data_per_nibble[i][1]) | data_per_nibble[i][2]);

                    all_zeros_flag[NIBBLES_NUM-1-i] = (data_per_nibble[i] == 4'b0000);
                end
            end
        end
    endgenerate



    reg [$clog2(NIBBLES_NUM)-1:0] index ;
    reg [1:0]    choosen_nibbles_zeros_count ;
    reg [ $clog2(NIBBLES_NUM*4)-1:0] zeros_count_result ;
    wire [NIBBLES_NUM-1:0]         all_zeros_flag_decoded;

    assign all_zeros_flag_decoded[0] = all_zeros_flag[0] ;
    genvar j;
        generate
            for (j=1; j < NIBBLES_NUM; j=j+1) begin
                assign all_zeros_flag_decoded[j] = all_zeros_flag_decoded[j-1] & all_zeros_flag[j];
            end
        endgenerate

    always@ * begin
        index = 0 ;
        for ( k =0 ; k< NIBBLES_NUM ; k =k +1) begin
            index = index + all_zeros_flag_decoded[k] ;
        end
    end

    always@* begin
        choosen_nibbles_zeros_count = zeros_cnt_per_nibble[index]  ;
        zeros_count_result = choosen_nibbles_zeros_count + (index <<2) ;
    end

    assign leading_zeros =  zeros_count_result ;
    assign all_zeros = (data ==0) ;

endmodule


