module serial_line_code_converter #(parameter CLK_DIV = 16)(
    input  logic clk,             // System clock
    input  logic reset_n,         // Active-low reset
    input  logic serial_in,       // Serial input signal
    input  logic [2:0] mode,      // Mode selector
    output logic serial_out       // Serial output signal
);

    // Internal signals
    logic [3:0] clk_counter;      // Clock divider counter
    logic clk_pulse;              // Clock pulse for sampling
    logic prev_serial_in;         // Previous serial input for edge detection
    logic prev_value;             // Holds the previous value of serial_in
    logic nrz_out;                // NRZ encoding output
    logic rz_out;                 // Return-to-Zero encoding output
    logic diff_out;               // Differential encoding output
    logic inv_nrz_out;            // Inverted NRZ output
    logic alt_invert_out;         // NRZ with alternating bit inversion output
    logic alt_invert_state;       // State for alternating inversion
    logic parity_out;             // Parity Bit Output
    logic scrambled_out;          // Scrambled NRZ output
    logic edge_triggered_out;     // Edge-Triggered NRZ output

    // Clock Pulse Generation
    // Divide the system clock by CLK_DIV: assert clk_pulse for one cycle when
    // clk_counter reaches CLK_DIV-1, then reset the counter.
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            clk_counter <= 0;
            clk_pulse   <= 0;
        end else begin
            if (clk_counter == CLK_DIV - 1) begin
                clk_counter <= 0;
                clk_pulse   <= 1;
            end else begin
                clk_counter <= clk_counter + 1'b1;
                clk_pulse   <= 0;
            end
        end
    end

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            prev_value <= 0;
            prev_serial_in <= 0;
        end else begin
            prev_value <= serial_in;
            prev_serial_in <= prev_value;
        end
    end

    // NRZ Pass-Through (direct output of serial input)
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            nrz_out <= 0;
        end else begin
            nrz_out <= serial_in;
        end
    end

    // Return-to-Zero (RZ) Encoding
    // Output high only during the clk_pulse when serial_in is high; returns to
    // zero within the same clock cycle.
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            rz_out <= 0;
        end else begin
            rz_out <= (clk_pulse & serial_in);
        end
    end

    // Differential Encoding
    // XOR the current serial input with the previously registered input value.
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            diff_out <= 0;
        end else begin
            diff_out <= (serial_in ^ prev_value);
        end
    end

    // Inverted NRZ Encoding
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            inv_nrz_out <= 0;
        end else begin
            inv_nrz_out <= ~serial_in;
        end
    end

    // NRZ with Alternating Bit Inversion
    // Toggle alt_invert_state every cycle; alternate between the inverted and
    // non-inverted serial_in.
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            alt_invert_state <= 0;
            alt_invert_out   <= 0;
        end else begin
            alt_invert_state <= ~alt_invert_state;
            alt_invert_out   <= alt_invert_state ? ~serial_in : serial_in;
        end
    end

    // Parity Bit Output (Odd Parity Calculation)
    // Accumulate the running XOR of all received serial bits.
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            parity_out <= 0;
        end else begin
            parity_out <= (parity_out ^ serial_in);
        end
    end

    // Scrambled NRZ (XOR with the LSB of the clock counter)
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            scrambled_out <= 0;
        end else begin
            scrambled_out <= (serial_in ^ clk_counter[0]);
        end
    end

    // Edge-Triggered NRZ
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            edge_triggered_out <= 0;
        end else  begin
            edge_triggered_out <= (serial_in & ~prev_serial_in);
        end
    end

    // Output Multiplexer to a single output
    // Purely combinational selection over the independently-registered encoder
    // outputs; any invalid mode drives serial_out to 0.
    always_comb begin
        case (mode)
            3'b000: serial_out = nrz_out;            // NRZ
            3'b001: serial_out = rz_out;             // RZ
            3'b010: serial_out = diff_out;           // Differential
            3'b011: serial_out = inv_nrz_out;        // Inverted NRZ
            3'b100: serial_out = alt_invert_out;     // Alternating Bit Inversion
            3'b101: serial_out = parity_out;         // Odd Parity
            3'b110: serial_out = scrambled_out;      // Scrambled NRZ
            3'b111: serial_out = edge_triggered_out; // Edge-Triggered NRZ
            default: serial_out = 1'b0;
        endcase
    end

endmodule

module serial_line_code_converter #(parameter CLK_DIV = 16)(
    input  logic         clk,             // System clock
    input  logic         reset_n,         // Active-low asynchronous reset
    input  logic         serial_in,       // Serial input signal
    input  logic         enable,          // Module enable (active high)
    input  logic [2:0]   mode,            // Mode selector
    output logic         serial_out,      // Serial output signal
    output logic         error_flag,      // Error flag (serial_in x/z)
    output logic [15:0]  diagnostic_bus   // Diagnostic status bus
);

    // Internal signals
    logic [$clog2(CLK_DIV)-1:0] clk_counter; // Clock divider counter
    logic clk_pulse;              // Clock pulse for sampling
    logic prev_serial_in;         // Previous serial input for edge detection
    logic prev_value;             // Holds the previous value of serial_in
    logic nrz_out;                // NRZ encoding output
    logic rz_out;                 // Return-to-Zero encoding output
    logic diff_out;               // Differential encoding output
    logic inv_nrz_out;            // Inverted NRZ output
    logic alt_invert_out;         // NRZ with alternating bit inversion output
    logic alt_invert_state;       // State for alternating inversion
    logic parity_out;             // Parity Bit Output
    logic scrambled_out;          // Scrambled NRZ output
    logic edge_triggered_out;     // Edge-Triggered NRZ output
    logic [7:0] error_counter;    // Error counter
    logic serial_encoded;         // Mode-selected encoded value
    logic s_clean;                // Sanitized serial input (x/z -> 0)

    // Sanitize the serial input so encoders never propagate x/z; invalid
    // values are still reported via error_flag / error_counter.
    always_comb begin
        if ((serial_in === 1'bx) || (serial_in === 1'bz))
            s_clean = 1'b0;
        else
            s_clean = serial_in;
    end

    // Clock divider: free-running timing reference.
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            clk_counter <= 0;
            clk_pulse   <= 0;
        end else if (clk_counter == CLK_DIV - 1) begin
            clk_counter <= 0;
            clk_pulse   <= 1;
        end else begin
            clk_counter <= clk_counter + 1;
            clk_pulse   <= 0;
        end
    end

    // Previous-input tracking (paused when disabled).
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            prev_value     <= 0;
            prev_serial_in <= 0;
        end else if (enable) begin
            prev_value     <= s_clean;
            prev_serial_in <= prev_value;
        end
    end

    // NRZ
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)        nrz_out <= 0;
        else if (enable)     nrz_out <= s_clean;
    end

    // RZ
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)        rz_out <= 0;
        else if (enable)     rz_out <= s_clean & clk_pulse;
    end

    // Differential
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)        diff_out <= 0;
        else if (enable)     diff_out <= s_clean ^ prev_serial_in;
    end

    // Inverted NRZ
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)        inv_nrz_out <= 0;
        else if (enable)     inv_nrz_out <= ~s_clean;
    end

    // NRZ with alternating bit inversion
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            alt_invert_out   <= 0;
            alt_invert_state <= 0;
        end else if (enable) begin
            alt_invert_state <= ~alt_invert_state;
            alt_invert_out   <= alt_invert_state ? ~s_clean : s_clean;
        end
    end

    // Odd parity (running)
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)        parity_out <= 0;
        else if (enable)     parity_out <= s_clean ^ parity_out;
    end

    // Scrambled NRZ
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)        scrambled_out <= 0;
        else if (enable)     scrambled_out <= s_clean ^ clk_counter[0];
    end

    // Edge-triggered NRZ (rising edge)
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n)        edge_triggered_out <= 0;
        else if (enable)     edge_triggered_out <= (s_clean & ~prev_serial_in);
    end

    // Error detection and counter (only while enabled).
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            error_flag    <= 0;
            error_counter <= 0;
        end else if (enable && ((serial_in === 1'bx) || (serial_in === 1'bz))) begin
            error_flag    <= 1;
            error_counter <= error_counter + 1;
        end else begin
            error_flag    <= 0;
        end
    end

    // Encoding mux (gated by enable; invalid mode -> 0).
    always_comb begin
        if (!enable) begin
            serial_encoded = 1'b0;
        end else begin
            case (mode)
                3'b000: serial_encoded = nrz_out;
                3'b001: serial_encoded = rz_out;
                3'b010: serial_encoded = diff_out;
                3'b011: serial_encoded = inv_nrz_out;
                3'b100: serial_encoded = alt_invert_out;
                3'b101: serial_encoded = parity_out;
                3'b110: serial_encoded = scrambled_out;
                3'b111: serial_encoded = edge_triggered_out;
                default: serial_encoded = 1'b0;
            endcase
        end
    end

    assign serial_out = serial_encoded;

    // Diagnostic bus (forced to 0 when disabled).
    always_comb begin
        if (!enable) begin
            diagnostic_bus = 16'b0;
        end else begin
            diagnostic_bus[15:13] = mode;
            diagnostic_bus[12]    = error_flag;
            diagnostic_bus[11:4]  = error_counter;
