module String_to_ASCII_Converter (
    input  wire       clk,                 // Clock signal
    input  wire       reset,               // Reset signal
    input  wire       start,               // Start conversion
    input  wire [7:0] char_in [7:0],       // 8-character input string (custom encoded: 0-95)
    output reg  [7:0] ascii_out [7:0],     // Parallel ASCII output (one per input character)
    output reg        valid,               // Indicates valid output
    output reg        ready                // Indicates module ready to accept input
);
    // ASCII Offsets
    localparam [7:0] DIGIT_OFFSET   = 8'd48;   // '0' = 48
    localparam [7:0] UPPER_OFFSET   = 8'd65;   // 'A' = 65
    localparam [7:0] LOWER_OFFSET   = 8'd97;   // 'a' = 97
    localparam [7:0] SPECIAL_OFFSET = 8'd33;   // '!' = 33

    // Convert one custom-encoded character to its ASCII value.
    //   Digits (0-9)            -> value + 48
    //   Uppercase (10-35)       -> (value - 10) + 65
    //   Lowercase (36-61)       -> (value - 36) + 97
    //   Special  (62-...)       -> (value - 62) + 33
    function [7:0] convert_char;
        input [7:0] c;
        begin
            if (c < 8'd10)
                convert_char = c + DIGIT_OFFSET;                 // '0'-'9'
            else if (c < 8'd36)
                convert_char = (c - 8'd10) + UPPER_OFFSET;       // 'A'-'Z'
            else if (c < 8'd62)
                convert_char = (c - 8'd36) + LOWER_OFFSET;       // 'a'-'z'
            else
                convert_char = (c - 8'd62) + SPECIAL_OFFSET;     // special
        end
    endfunction

    integer i;

    // Parallel conversion: all 8 characters converted in a single clock cycle
    // when start is asserted while ready.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < 8; i = i + 1)
                ascii_out[i] <= 8'd0;
            valid <= 1'b0;
            ready <= 1'b1;
        end else begin
            if (start && ready) begin
                // Convert every character simultaneously in one cycle
                for (i = 0; i < 8; i = i + 1)
                    ascii_out[i] <= convert_char(char_in[i]);
                valid <= 1'b1;   // output valid this cycle
                ready <= 1'b0;    // deassert ready while the result is presented
            end else begin
                // Processing complete: clear outputs, reassert ready, drop valid
                for (i = 0; i < 8; i = i + 1)
                    ascii_out[i] <= 8'd0;
                valid <= 1'b0;
                ready <= 1'b1;
            end
        end
    end
endmodule

module sync_muller_c_element #(
  parameter NUM_INPUT  = 2, // Number of input signals
  parameter PIPE_DEPTH = 1  // Number of pipeline stages
) (
  input  logic                  clk   , // Clock signal
  input  logic                  srst  , // Synchronous reset signal
  input  logic                  clr   , // Clear pipeline and output
  input  logic                  clk_en, // Clock enable signal
  input  logic  [NUM_INPUT-1:0] inp   , // Input signals (NUM_INPUT-width vector)
  output logic                  out     // Output signal
);

  // Pipeline to store intermediate states of inputs
  logic [(PIPE_DEPTH*NUM_INPUT)-1:0] pipe;
  genvar i;

  // Generate block for pipeline implementation
  generate
    for (i = 0; i < PIPE_DEPTH; i = i + 1) begin : gen_pipe_stage
      always_ff @(posedge clk) begin
        if (srst || clr) begin
          // Synchronous reset / clear: flush this stage to 0
          pipe[i*NUM_INPUT +: NUM_INPUT] <= '0;
        end else if (clk_en) begin
          if (i == 0) begin
            // First stage captures the input signals
            pipe[i*NUM_INPUT +: NUM_INPUT] <= inp;
          end else begin
            // Subsequent stages propagate the previous stage
            pipe[i*NUM_INPUT +: NUM_INPUT] <= pipe[(i-1)*NUM_INPUT +: NUM_INPUT];
          end
        end
        // clk_en low: retain current pipeline state
      end
    end
  endgenerate

  // Output logic: consensus of the final pipeline stage
  always_ff @(posedge clk) begin
    if (srst || clr) begin
      out <= 1'b0;
    end else if (clk_en) begin
      if (&pipe[(PIPE_DEPTH-1)*NUM_INPUT +: NUM_INPUT]) begin
        // All bits of the final stage are high
        out <= 1'b1;
      end else if (~|pipe[(PIPE_DEPTH-1)*NUM_INPUT +: NUM_INPUT]) begin
        // All bits of the final stage are low
        out <= 1'b0;
      end
      // Otherwise: retain previous state (out <= out implied)
    end
    // clk_en low: output remains unchanged
  end

endmodule


