module adc_data_rotate #(
    parameter DATA_WIDTH = 8 // Parameterized data width
)(
    // Inputs
    input logic                     i_clk,             // Clock signal
    input logic                     i_rst_n,           // Active-low reset
    input logic [DATA_WIDTH-1:0]    i_adc_data_in,     // Input ADC data
    input logic [3:0]               i_shift_count,     // Number of bits to shift
    input logic                     i_shift_direction, // Shift direction (0: Left, 1: Right)

    // Outputs
    output logic [DATA_WIDTH-1:0]   o_processed_data,  // Rotated output data
    output logic                    o_operation_status // Operation status
);

    // Effective rotation amount, reduced modulo DATA_WIDTH so that a
    // shift count of 0 or DATA_WIDTH (or any value exceeding DATA_WIDTH)
    // is handled correctly.
    localparam int SHW = (DATA_WIDTH <= 1) ? 1 : $clog2(DATA_WIDTH);

    logic [4:0]            shift_ext;   // zero-extended shift count
    logic [SHW:0]          eff_shift;   // effective shift = count % DATA_WIDTH
    logic [DATA_WIDTH-1:0] rotate_left; // left-rotated combinational result
    logic [DATA_WIDTH-1:0] rotate_right;// right-rotated combinational result
    logic [DATA_WIDTH-1:0] rotate_result;

    always_comb begin
        shift_ext = {1'b0, i_shift_count};
        eff_shift = shift_ext % DATA_WIDTH;

        if (eff_shift == 0) begin
            rotate_left  = i_adc_data_in;
            rotate_right = i_adc_data_in;
        end else begin
            rotate_left  = (i_adc_data_in << eff_shift) |
                           (i_adc_data_in >> (DATA_WIDTH - eff_shift));
            rotate_right = (i_adc_data_in >> eff_shift) |
                           (i_adc_data_in << (DATA_WIDTH - eff_shift));
        end

        rotate_result = i_shift_direction ? rotate_right : rotate_left;
    end

    always_ff @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            o_processed_data   <= '0;
            o_operation_status <= 1'b0;
        end else begin
            o_processed_data   <= rotate_result;
            o_operation_status <= 1'b1;
        end
    end

endmodule

module key_expansion_128aes #(
    parameter NBW_KEY = 'd128,
    parameter NBW_OUT = 'd1408
) (
    input  logic               clk,
    input  logic               rst_async_n,
    input  logic               i_start,
    input  logic [NBW_KEY-1:0] i_key,
    output logic               o_done,
    output logic [NBW_OUT-1:0] o_expanded_key
);

localparam NBW_BYTE = 'd8;
localparam STEPS    = 'd10;
localparam NBW_WORD = 'd32;

// Round constants (indexed by the round being computed)
logic [NBW_BYTE-1:0] Rcon [STEPS];

// State registers
logic [NBW_OUT-1:0] expanded_key_ff;
logic [NBW_OUT-1:0] expanded_key_nx;
logic [STEPS:0]     steps_ff;

// Single round-key transform datapath (area-optimized: 4 sboxes instead of 40)
int                  rnd;        // index of the most-recently-completed round key
logic [NBW_KEY-1:0]  src_key;    // source round key RK[rnd]
logic [NBW_WORD-1:0] RotWord;
logic [NBW_WORD-1:0] SubWord;
logic [NBW_WORD-1:0] RconXor;
logic [NBW_KEY-1:0]  next_key;   // computed round key RK[rnd+1]

assign Rcon[0] = 8'h01;
assign Rcon[1] = 8'h02;
assign Rcon[2] = 8'h04;
assign Rcon[3] = 8'h08;
assign Rcon[4] = 8'h10;
assign Rcon[5] = 8'h20;
assign Rcon[6] = 8'h40;
assign Rcon[7] = 8'h80;
assign Rcon[8] = 8'h1b;
assign Rcon[9] = 8'h36;

// One-hot (steps_ff) -> binary round index of the last completed round key.
always_comb begin
    rnd = 0;
    for (int j = 0; j < STEPS; j++) begin
        if (steps_ff[j]) rnd = j;
    end
end

// Source round key is slot 'rnd' (round keys packed MSB-first).
assign src_key = expanded_key_ff[(NBW_OUT-1) - rnd*NBW_KEY -: NBW_KEY];

// RotWord operates on the last 32-bit word (W3) of the source round key,
// i.e. src_key[31:0] left-rotated by one byte.
assign RotWord = {src_key[NBW_WORD-NBW_BYTE-1:0], src_key[NBW_WORD-1:NBW_WORD-NBW_BYTE]};

sbox uu_sbox0 (.i_data(RotWord[31:24]), .o_data(SubWord[31:24]));
sbox uu_sbox1 (.i_data(RotWord[23:16]), .o_data(SubWord[23:16]));
sbox uu_sbox2 (.i_data(RotWord[15:8]),  .o_data(SubWord[15:8]));
sbox uu_sbox3 (.i_data(RotWord[7:0]),   .o_data(SubWord[7:0]));

// Standard AES-128 word recurrence for the next round key.
always_comb begin
    RconXor          = {SubWord[31:24] ^ Rcon[rnd], SubWord[23:0]};
    next_key[127:96] = src_key[127:96] ^ RconXor;
    next_key[95:64]  = src_key[95:64]  ^ next_key[127:96];
    next_key[63:32]  = src_key[63:32]  ^ next_key[95:64];
    next_key[31:0]   = src_key[31:0]   ^ next_key[63:32];
end

// Next value of the expanded-key register: hold everything, and update exactly
// one round-key slot per cycle (slot 0 on start, slot rnd+1 while computing).
always_comb begin
    expanded_key_nx = expanded_key_ff;
    if (i_start & o_done) begin
        expanded_key_nx[(NBW_OUT-1) -: NBW_KEY] = i_key;
    end else if (|steps_ff[STEPS-1:0]) begin
        expanded_key_nx[(NBW_OUT-1) - (rnd+1)*NBW_KEY -: NBW_KEY] = next_key;
    end
end

// Timing / control shift register (kept identical to the original -> same latency).
always_ff @(posedge clk or negedge rst_async_n) begin : reset_regs
    if (~rst_async_n) begin
        expanded_key_ff <= {NBW_OUT{1'b0}};
        steps_ff        <= 11'h400;
    end else begin
        expanded_key_ff <= expanded_key_nx;
        if (i_start || (|steps_ff[STEPS-1:0])) begin
            steps_ff <= {steps_ff[STEPS-1:0], (i_start & o_done)};
        end
    end
end

assign o_done         = steps_ff[STEPS];
assign o_expanded_key = expanded_key_ff;

endmodule : key_expansion_128aes

