module alphablending #(
    parameter H = 5,
    parameter N = 3,
    parameter W = 8
) (
    input clk,
    input reset,
    input start,
    input [(24*H*W)-1:0] pixel_in,    // N pixels, each 24-bit RGB
    input [(8*H*W)-1:0] alpha_in,     // N alpha values, each 8-bit
    input [(24*H*W)-1:0] bg_pixel_in, // N background pixels, each 24-bit RGB
    output reg [(24*H*W)-1:0] blended_out, // N blended output pixels
    output reg done
);

// State Encoding
localparam IDLE     = 2'b00;
localparam LOAD     = 2'b01;
localparam COMPUTE  = 2'b10;
localparam COMPLETE = 2'b11;

reg [1:0] state, next_state;

// Registers for inputs and outputs
reg [23:0] pixel [0:H*W-1];       // Individual pixels (24-bit each)
reg [7:0] alpha [0:H*W-1];        // Individual alpha values (8-bit each)
reg [23:0] bg_pixel [0:H*W-1];    // Individual background pixels (24-bit each)
reg [23:0] blended [0:H*W-1];     // Individual blended results (24-bit each)

// Pixel count and padding logic
integer pixel_count;
integer total_pixels;
integer padded_pixels;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        pixel_count <= 0;
        total_pixels <= 0;
        padded_pixels <= 0;
    end else if (state == IDLE && start) begin
        pixel_count <= 0;
        total_pixels <= H * W;
        padded_pixels <= (((H * W + N - 1) / N) * N) - (H * W);
    end else if (state == COMPUTE && pixel_count < total_pixels + padded_pixels) begin
        pixel_count <= pixel_count + N;
    end
end

// State Transition Logic
always @(posedge clk or posedge reset) begin
    if (reset)
        state <= IDLE;
    else
        state <= next_state;
end

// Next State Logic (combinational)
always @(*) begin
    case (state)
        IDLE:     next_state = (start) ? LOAD : IDLE;
        LOAD:     next_state = COMPUTE;
        COMPUTE:  next_state = (pixel_count < total_pixels + padded_pixels) ? LOAD : COMPLETE;
        COMPLETE: next_state = IDLE;
        default:  next_state = IDLE;
    endcase
end

// Alpha Blending Calculation
// Formula: blended = (alpha * pixel + (255 - alpha) * bg_pixel) / 255
always @(posedge clk) begin
    if (state == LOAD) begin
        // Unpack inputs into arrays
        for (int i = 0; i < N; i = i + 1) begin
            if (pixel_count + i < total_pixels) begin
                pixel[i] <= pixel_in[(pixel_count + i)*24 +: 24];
                alpha[i] <= alpha_in[(pixel_count + i)*8 +: 8];
                bg_pixel[i] <= bg_pixel_in[(pixel_count + i)*24 +: 24];
            end
            else begin
                pixel[i] <= 24'd0; // Pad with 0 if out of bounds
                alpha[i] <= 8'd0;
                bg_pixel[i] <= 24'd0;
            end
        end
    end
    else if (state == COMPUTE) begin
        for (int i = 0; i < N; i = i + 1) begin
            blended[pixel_count + i][23:16] <= (alpha[i] * pixel[i][23:16] + (255 - alpha[i]) * bg_pixel[i][23:16]) / 255;
            blended[pixel_count + i][15:8]  <= (alpha[i] * pixel[i][15:8]  + (255 - alpha[i]) * bg_pixel[i][15:8])  / 255;
            blended[pixel_count + i][7:0]   <= (alpha[i] * pixel[i][7:0]   + (255 - alpha[i]) * bg_pixel[i][7:0])   / 255;
        end
    end
end

// Output Logic: done + blended_out packing (single driver, async reset)
always @(posedge clk or posedge reset) begin
    if (reset) begin
        done <= 0;
        blended_out <= 0;
    end
    else if (state == COMPLETE) begin
        done <= 1;
        // Pack blended results into output
        for (int j = 0; j < H*W; j = j + 1) begin
            blended_out[j*24 +: 24] <= blended[j][23:0];
        end
    end
    else begin
        done <= 0;
    end
end

endmodule

// APB DSP Operation Module (corrected)
module apb_dsp_op #(
    parameter ADDR_WIDTH = 'd8,
    parameter DATA_WIDTH = 'd32
) (
    input  logic                  clk_dsp,    // Faster clock to DSP operation
    input  logic                  en_clk_dsp, // Enable DSP operation with faster clock
    input  logic                  PCLK,       // APB clock
    input  logic                  PRESETn,    // Active low asynchronous APB Reset
    input  logic [ADDR_WIDTH-1:0] PADDR,      // APB address
    input  logic                  PWRITE,     // Write/Read enable
    input  logic [DATA_WIDTH-1:0] PWDATA,     // Write data
    input  logic                  PSEL,       // DSP selector
    input  logic                  PENABLE,    // APB enable
    output logic [DATA_WIDTH-1:0] PRDATA,     // Read data
    output logic                  PREADY,     // Ready signal
    output logic                  PSLVERR     // Error signal
);

    // --------------------------------------------------------------------
    // Register bank address map (byte addressed, per specification)
    // --------------------------------------------------------------------
    localparam [ADDR_WIDTH-1:0] ADDRESS_A         = 8'h00; // REG_OPERAND_A
    localparam [ADDR_WIDTH-1:0] ADDRESS_B         = 8'h01; // REG_OPERAND_B
    localparam [ADDR_WIDTH-1:0] ADDRESS_C         = 8'h02; // REG_OPERAND_C
    localparam [ADDR_WIDTH-1:0] ADDRESS_O         = 8'h03; // REG_OPERAND_O
    localparam [ADDR_WIDTH-1:0] ADDRESS_CONTROL   = 8'h04; // REG_CONTROL
    localparam [ADDR_WIDTH-1:0] ADDRESS_WDATA     = 8'h05; // REG_WDATA_SRAM
    localparam [ADDR_WIDTH-1:0] ADDRESS_SRAM_ADDR = 8'h06; // REG_ADDR_SRAM

    // Control modes
    localparam SRAM_WRITE     = 32'd1;
    localparam SRAM_READ      = 32'd2;
    localparam DSP_READ_OP_A  = 32'd3;
    localparam DSP_READ_OP_B  = 32'd4;
    localparam DSP_READ_OP_C  = 32'd5;
    localparam DSP_WRITE_OP_O = 32'd6;

    localparam integer SRAM_DEPTH = 64;

    // --------------------------------------------------------------------
    // Internal registers
    // --------------------------------------------------------------------
    logic [DATA_WIDTH-1:0] reg_operand_a;
    logic [DATA_WIDTH-1:0] reg_operand_b;
    logic [DATA_WIDTH-1:0] reg_operand_c;
    logic [DATA_WIDTH-1:0] reg_operand_o;
    logic [DATA_WIDTH-1:0] reg_control;
    logic [DATA_WIDTH-1:0] reg_wdata_sram;
    logic [DATA_WIDTH-1:0] reg_addr_sram;

    logic signed [DATA_WIDTH-1:0] wire_op_a;
    logic signed [DATA_WIDTH-1:0] wire_op_b;
    logic signed [DATA_WIDTH-1:0] wire_op_c;
    logic signed [DATA_WIDTH-1:0] wire_op_o;
    logic        [DATA_WIDTH-1:0] sram_data_in;
    logic                         sram_we;
    logic        [DATA_WIDTH-1:0] sram_addr;
    logic        [DATA_WIDTH-1:0] sram_data_out;

    // --------------------------------------------------------------------
    // Address / error decode
    // --------------------------------------------------------------------
    logic paddr_valid;
    logic mem_mode;
    logic sram_oob;

    always_comb begin
        paddr_valid = (PADDR == ADDRESS_A)       ||
                      (PADDR == ADDRESS_B)       ||
                      (PADDR == ADDRESS_C)       ||
                      (PADDR == ADDRESS_O)       ||
                      (PADDR == ADDRESS_CONTROL) ||
                      (PADDR == ADDRESS_WDATA)   ||
                      (PADDR == ADDRESS_SRAM_ADDR);

        // A memory-touching control mode is active (modes 1..6)
        mem_mode = (reg_control >= SRAM_WRITE) && (reg_control <= DSP_WRITE_OP_O);

        // SRAM address currently addressed exceeds the physical depth
        sram_oob = (sram_addr >= SRAM_DEPTH);
    end

    // --------------------------------------------------------------------
    // APB handshake outputs (no wait states -> combinational, same-cycle)
    // --------------------------------------------------------------------
    // PREADY: 0 out of reset (PSEL low); asserts in the access phase.
    assign PREADY  = PSEL & PENABLE;

    // PSLVERR: asserted during the access phase on an invalid register
    // address or an out-of-bounds SRAM access; deasserted otherwise.
    assign PSLVERR = (PSEL & PENABLE) & ((~paddr_valid) | (mem_mode & sram_oob));

    // --------------------------------------------------------------------
    // APB register writes (registered on PCLK)
    // --------------------------------------------------------------------
    always_ff @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            reg_operand_a  <= '0;
            reg_operand_b  <= '0;
            reg_operand_c  <= '0;
            reg_operand_o  <= '0;
            reg_control    <= '0;
            reg_wdata_sram <= '0;
            reg_addr_sram  <= '0;
        end else if (PSEL & PENABLE & PWRITE & paddr_valid) begin
            case (PADDR)
                ADDRESS_A         : reg_operand_a  <= PWDATA;
                ADDRESS_B         : reg_operand_b  <= PWDATA;
                ADDRESS_C         : reg_operand_c  <= PWDATA;
                ADDRESS_O         : reg_operand_o  <= PWDATA;
                ADDRESS_CONTROL   : reg_control    <= PWDATA;
                ADDRESS_WDATA     : reg_wdata_sram <= PWDATA;
                ADDRESS_SRAM_ADDR : reg_addr_sram  <= PWDATA;
                default           : ; // no write
            endcase
        end
    end

    // --------------------------------------------------------------------
    // CDC: bring SRAM read data (clk_dsp domain) into the PCLK domain
    // through a dual-flop synchronizer before it is consumed by APB reads.
    // --------------------------------------------------------------------
    logic [DATA_WIDTH-1:0] sram_rdata_meta;
    logic [DATA_WIDTH-1:0] sram_rdata_sync;
    always_ff @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            sram_rdata_meta <= '0;
            sram_rdata_sync <= '0;
        end else begin
            sram_rdata_meta <= sram_data_out;
            sram_rdata_sync <= sram_rdata_meta;
        end
    end

    // --------------------------------------------------------------------
    // APB read data (combinational, available in the access phase)
    // --------------------------------------------------------------------
    always_comb begin
        PRDATA = '0;
        if (reg_control == SRAM_READ) begin
            PRDATA = sram_rdata_sync;
        end else begin
            case (PADDR)
                ADDRESS_A         : PRDATA = reg_operand_a;
                ADDRESS_B         : PRDATA = reg_operand_b;
                ADDRESS_C         : PRDATA = reg_operand_c;
                ADDRESS_O         : PRDATA = reg_operand_o;
                ADDRESS_CONTROL   : PRDATA = reg_control;
                ADDRESS_WDATA     : PRDATA = reg_wdata_sram;
                ADDRESS_SRAM_ADDR : PRDATA = reg_addr_sram;
                default           : PRDATA = '0;
            endcase
        end
    end

    // --------------------------------------------------------------------
    // CDC: synchronize en_clk_dsp (PCLK-originated) into the clk_dsp domain
    // with a dual-flop synchronizer before it selects the DSP clock.
    // --------------------------------------------------------------------
    logic en_dsp_meta, en_dsp_sync;
    always_ff @(posedge clk_dsp or negedge PRESETn) begin
        if (!PRESETn) begin
            en_dsp_meta <= 1'b0;
            en_dsp_sync <= 1'b0;
        end else begin
            en_dsp_meta <= en_clk_dsp;
            en_dsp_sync <= en_dsp_meta;
        end
    end

    // --------------------------------------------------------------------
    // Glitch-free clock multiplexer (cross-coupled, break-before-make).
    // Selects clk_dsp when the (synchronized) enable is high, otherwise PCLK.
    // Second-stage retiming on the negedge gates the AND only while the
    // clock is low, guaranteeing no runt/glitch pulses on the switch.
    // --------------------------------------------------------------------
    logic dsp_clk;
    wire  sel_dsp = en_dsp_sync;

    logic q1_dsp, q2_dsp;
    logic q1_pclk, q2_pclk;

    // clk_dsp branch
    always_ff @(posedge clk_dsp or negedge PRESETn)
        if (!PRESETn) q1_dsp <= 1'b0; else q1_dsp <= sel_dsp & ~q2_pclk;
    always_ff @(negedge clk_dsp or negedge PRESETn)
        if (!PRESETn) q2_dsp <= 1'b0; else q2_dsp <= q1_dsp;

    // PCLK branch
    always_ff @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) q1_pclk <= 1'b0; else q1_pclk <= ~sel_dsp & ~q2_dsp;
    always_ff @(negedge PCLK or negedge PRESETn)
        if (!PRESETn) q2_pclk <= 1'b0; else q2_pclk <= q1_pclk;

    assign dsp_clk = (q2_dsp & clk_dsp) | (q2_pclk & PCLK);

    // --------------------------------------------------------------------
    // SRAM datapath control (combinational)
    // --------------------------------------------------------------------
    always_comb begin
        sram_data_in = (reg_control == SRAM_WRITE) ? reg_wdata_sram : wire_op_o;

        sram_we = ((reg_control == SRAM_WRITE) || (reg_control == DSP_WRITE_OP_O));

        case (reg_control)
            DSP_READ_OP_A  : sram_addr = reg_operand_a;
            DSP_READ_OP_B  : sram_addr = reg_operand_b;
            DSP_READ_OP_C  : sram_addr = reg_operand_c;
            DSP_WRITE_OP_O : sram_addr = reg_operand_o;
            default        : sram_addr = reg_addr_sram;
        endcase
    end

    // --------------------------------------------------------------------
    // SRAM: located in the DSP clock domain (clocked by the selected clock)
    // --------------------------------------------------------------------
    logic [DATA_WIDTH-1:0] mem [SRAM_DEPTH-1:0];

    always_ff @(posedge dsp_clk) begin
        if (sram_we && !sram_oob) begin
            mem[sram_addr[5:0]] <= sram_data_in;
        end else begin
            sram_data_out <= mem[sram_addr[5:0]];
        end
    end

    // --------------------------------------------------------------------
    // DSP operation (same DSP clock domain as the SRAM)
    // --------------------------------------------------------------------
    always_ff @(posedge dsp_clk or negedge PRESETn) begin
        if (!PRESETn) begin
            wire_op_a <= '0;
            wire_op_b <= '0;
            wire_op_c <= '0;
        end else begin
            case (reg_control)
                DSP_READ_OP_A  : wire_op_a <= sram_data_out;
                DSP_READ_OP_B  : wire_op_b <= sram_data_out;
                DSP_READ_OP_C  : wire_op_c <= sram_data_out;
                default        : ; // hold
            endcase
        end
    end

    assign wire_op_o = (wire_op_a * wire_op_b) + wire_op_c;

endmodule

// apb_dsp_unit : APB-mapped DSP unit with 1 KB SRAM datapath.
// Configuration registers (0x00-0x05) plus an addressable memory region.
// Modes (r_Enable): 0=disabled, 1=addition, 2=multiplication, 3=data-writing.
module apb_dsp_unit (
    // Clock & Reset
    input  wire        pclk,        // APB clock
    input  wire        presetn,     // active-low async reset
    // APB interface
    input  wire [9:0]  paddr,       // address bus (CSR + memory)
    input  wire        pselx,       // APB select
    input  wire        penable,     // APB enable
    input  wire        pwrite,      // 1=write, 0=read
    input  wire [7:0]  pwdata,      // write data bus
    output reg         pready,      // transaction complete
    output reg  [7:0]  prdata,      // read data bus
    output reg         pslverr,     // slave error
    // SRAM interface
    input  wire        sram_valid   // rising edge latches r_write_data -> r_write_address
);

    // ---------------------------------------------------------------
    // Register address map (spec-named, preserved verbatim)
    // ---------------------------------------------------------------
    localparam [9:0] ADDR_OPERAND_1     = 10'h0;
    localparam [9:0] ADDR_OPERAND_2     = 10'h1;
    localparam [9:0] ADDR_ENABLE        = 10'h2;
    localparam [9:0] ADDR_WRITE_ADDRESS = 10'h3;
    localparam [9:0] ADDR_WRITE_DATA    = 10'h4;
    localparam [9:0] ADDR_RESULT        = 10'h5;
    localparam [9:0] REG_LIMIT          = 10'h5; // 0x00..0x05 reserved for CSRs

    // Configuration / status registers
    reg [7:0] r_operand_1;      // 0x0 : memory address of first operand
    reg [7:0] r_operand_2;      // 0x1 : memory address of second operand
    reg [7:0] r_Enable;         // 0x2 : operating mode
    reg [7:0] r_write_address;  // 0x3 : memory write address
    reg [7:0] r_write_data;     // 0x4 : memory write data
    reg [7:0] r_result;         // 0x5 : computed result (read-only via APB)

    // 1 KB SRAM (byte-wide, 1024 entries)
    reg [7:0] sram [0:1023];

    // FSM
    localparam [1:0] IDLE        = 2'b00,
                     READ_STATE  = 2'b01,
                     WRITE_STATE = 2'b10;
    reg [1:0] state;
    reg [1:0] next_state;

    // SRAM write-strobe edge detector
    reg sram_valid_d;

    integer i; // reset loop index

    // ---------------------------------------------------------------
    // Next-state logic (combinational)
    // ---------------------------------------------------------------
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (pselx && !penable)
                    next_state = pwrite ? WRITE_STATE : READ_STATE;
                else
                    next_state = IDLE;
            end
            READ_STATE:  next_state = IDLE;
            WRITE_STATE: next_state = IDLE;
            default:     next_state = IDLE;
        endcase
    end

    // ---------------------------------------------------------------
    // State register
    // ---------------------------------------------------------------
    always @(posedge pclk or negedge presetn) begin
        if (!presetn)
            state <= IDLE;
        else
            state <= next_state;
    end

    // ---------------------------------------------------------------
    // APB datapath, CSRs, memory and DSP compute
    // ---------------------------------------------------------------
    always @(posedge pclk or negedge presetn) begin
        if (!presetn) begin
            pready          <= 1'b0;
            prdata          <= 8'h00;
            pslverr         <= 1'b0;
            r_operand_1     <= 8'h00;
            r_operand_2     <= 8'h00;
            r_Enable        <= 8'h00;
            r_write_address <= 8'h00;
            r_write_data    <= 8'h00;
            r_result        <= 8'h00;
            sram_valid_d    <= 1'b0;
            for (i = 0; i < 1024; i = i + 1)
                sram[i] <= 8'h00;
        end else begin
            // defaults for single-cycle strobes
            pready       <= 1'b0;
            pslverr      <= 1'b0;
            sram_valid_d <= sram_valid;

            // ---- APB WRITE ----
            if (state == WRITE_STATE) begin
                pready <= 1'b1;
                if (paddr <= REG_LIMIT) begin
                    case (paddr)
                        ADDR_OPERAND_1:     r_operand_1     <= pwdata;
                        ADDR_OPERAND_2:     r_operand_2     <= pwdata;
                        ADDR_ENABLE:        r_Enable        <= pwdata;
                        ADDR_WRITE_ADDRESS: r_write_address <= pwdata;
                        ADDR_WRITE_DATA:    r_write_data    <= pwdata;
                        ADDR_RESULT:        pslverr         <= 1'b1; // read-only reg
                        default:            pslverr         <= 1'b1;
                    endcase
                end else begin
                    // memory region write-back
                    sram[paddr] <= pwdata;
                end
            end

            // ---- APB READ ----
            if (state == READ_STATE) begin
                pready <= 1'b1;
                if (paddr <= REG_LIMIT) begin
                    case (paddr)
                        ADDR_OPERAND_1:     prdata <= r_operand_1;
                        ADDR_OPERAND_2:     prdata <= r_operand_2;
                        ADDR_ENABLE:        prdata <= r_Enable;
                        ADDR_WRITE_ADDRESS: prdata <= r_write_address;
                        ADDR_WRITE_DATA:    prdata <= r_write_data;
                        ADDR_RESULT:        prdata <= r_result;
                        default: begin
                            prdata  <= 8'h00;
                            pslverr <= 1'b1;
                        end
                    endcase
                end else begin
                    // memory region read-back
                    prdata <= sram[paddr];
                end
            end

            // ---- Data-writing mode: latch r_write_data on sram_valid rising edge ----
            if ((sram_valid && !sram_valid_d) && (r_Enable == 8'd3)) begin
                sram[r_write_address] <= r_write_data;
            end

            // ---- DSP compute: result stored at address 0x5 ----
            case (r_Enable)
                8'd1: r_result <= sram[r_operand_1] + sram[r_operand_2]; // addition
                8'd2: r_result <= sram[r_operand_1] * sram[r_operand_2]; // multiplication
                default: r_result <= r_result;                          // hold
            endcase
        end
    end

endmodule


