module cvdp_copilot_apb_gpio #(
    parameter GPIO_WIDTH = 8
) (
    // APB interface
    input  wire                   pclk,
    input  wire                   preset_n,
    input  wire                   psel,
    input  wire [7:2]             paddr,
    input  wire                   penable,
    input  wire                   pwrite,
    input  wire [31:0]            pwdata,
    output reg  [31:0]            prdata,
    output wire                   pready,
    output wire                   pslverr,
    // GPIO interface
    input  wire [GPIO_WIDTH-1:0]  gpio_in,
    output wire [GPIO_WIDTH-1:0]  gpio_out,
    output wire [GPIO_WIDTH-1:0]  gpio_enable,
    output reg  [GPIO_WIDTH-1:0]  gpio_int,
    output wire                   comb_int
);

    // ------------------------------------------------------------------
    // Register address map (word-aligned, decoded on paddr[7:2])
    // ------------------------------------------------------------------
    localparam [5:0] ADDR_IN     = 6'h00 >> 2; // 0x00 GPIO Input Data      (RO)
    localparam [5:0] ADDR_OUT    = 6'h04 >> 2; // 0x04 GPIO Output Data
    localparam [5:0] ADDR_OE     = 6'h08 >> 2; // 0x08 GPIO Output Enable
    localparam [5:0] ADDR_IE     = 6'h0C >> 2; // 0x0C GPIO Interrupt Enable
    localparam [5:0] ADDR_ITYPE  = 6'h10 >> 2; // 0x10 GPIO Interrupt Type
    localparam [5:0] ADDR_IPOL   = 6'h14 >> 2; // 0x14 GPIO Interrupt Polarity
    localparam [5:0] ADDR_ISTATE = 6'h18 >> 2; // 0x18 GPIO Interrupt State  (RO)

    // ------------------------------------------------------------------
    // Internal configuration / data registers
    // ------------------------------------------------------------------
    reg [GPIO_WIDTH-1:0] reg_out;      // 0x04 output data
    reg [GPIO_WIDTH-1:0] reg_oe;       // 0x08 output enable / direction
    reg [GPIO_WIDTH-1:0] reg_int_en;   // 0x0C interrupt enable
    reg [GPIO_WIDTH-1:0] reg_int_type; // 0x10 1 = edge, 0 = level
    reg [GPIO_WIDTH-1:0] reg_int_pol;  // 0x14 1 = active-high/rising, 0 = active-low/falling

    // ------------------------------------------------------------------
    // Two-stage synchronizer for gpio_in (metastability mitigation),
    // plus a third stage to detect edges.
    // ------------------------------------------------------------------
    reg [GPIO_WIDTH-1:0] sync_0;
    reg [GPIO_WIDTH-1:0] sync_1;
    reg [GPIO_WIDTH-1:0] sync_prev;

    always @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            sync_0    <= {GPIO_WIDTH{1'b0}};
            sync_1    <= {GPIO_WIDTH{1'b0}};
            sync_prev <= {GPIO_WIDTH{1'b0}};
        end else begin
            sync_0    <= gpio_in;
            sync_1    <= sync_0;
            sync_prev <= sync_1;
        end
    end

    // ------------------------------------------------------------------
    // APB access qualifiers.  pready is always high (no wait states),
    // so the ACCESS phase completes when psel & penable are asserted.
    // ------------------------------------------------------------------
    assign pready  = 1'b1;
    assign pslverr = 1'b0;

    wire write_en = psel & penable & pwrite;

    // ------------------------------------------------------------------
    // APB write logic
    // ------------------------------------------------------------------
    always @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            reg_out      <= {GPIO_WIDTH{1'b0}};
            reg_oe       <= {GPIO_WIDTH{1'b0}};
            reg_int_en   <= {GPIO_WIDTH{1'b0}};
            reg_int_type <= {GPIO_WIDTH{1'b0}};
            reg_int_pol  <= {GPIO_WIDTH{1'b0}};
        end else if (write_en) begin
            case (paddr)
                ADDR_OUT:   reg_out      <= pwdata[GPIO_WIDTH-1:0];
                ADDR_OE:    reg_oe       <= pwdata[GPIO_WIDTH-1:0];
                ADDR_IE:    reg_int_en   <= pwdata[GPIO_WIDTH-1:0];
                ADDR_ITYPE: reg_int_type <= pwdata[GPIO_WIDTH-1:0];
                ADDR_IPOL:  reg_int_pol  <= pwdata[GPIO_WIDTH-1:0];
                default:    ; // undefined address: no effect (incl. RO regs)
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Interrupt generation.
    //   Level mode (type=0): active-high when pol=1, active-low when pol=0.
    //   Edge  mode (type=1): rising  edge when pol=1, falling  edge when pol=0.
    // Interrupts are masked by reg_int_en.  Lower GPIO numbers naturally
    // hold the lower bit positions (priority to lower GPIO numbers).
    // ------------------------------------------------------------------
    reg [GPIO_WIDTH-1:0] int_raw;
    integer i;

    always @(*) begin
        for (i = 0; i < GPIO_WIDTH; i = i + 1) begin
            if (reg_int_type[i]) begin
                // edge-sensitive
                if (reg_int_pol[i])
                    int_raw[i] =  sync_1[i] & ~sync_prev[i]; // rising
                else
                    int_raw[i] = ~sync_1[i] &  sync_prev[i]; // falling
            end else begin
                // level-sensitive
                if (reg_int_pol[i])
                    int_raw[i] =  sync_1[i];  // active-high
                else
                    int_raw[i] = ~sync_1[i];  // active-low
            end
        end
    end

    always @(posedge pclk or negedge preset_n) begin
        if (!preset_n)
            gpio_int <= {GPIO_WIDTH{1'b0}};
        else
            gpio_int <= int_raw & reg_int_en;
    end

    assign comb_int = |gpio_int;

    // ------------------------------------------------------------------
    // GPIO outputs
    // ------------------------------------------------------------------
    assign gpio_out    = reg_out;
    assign gpio_enable = reg_oe; // high = output, low = input

    // ------------------------------------------------------------------
    // APB read logic (combinational read data mux).
    // Undefined addresses read back 0.
    // ------------------------------------------------------------------
    always @(*) begin
        prdata = 32'h0000_0000;
        case (paddr)
            ADDR_IN:     prdata[GPIO_WIDTH-1:0] = sync_1;       // synchronized input
            ADDR_OUT:    prdata[GPIO_WIDTH-1:0] = reg_out;
            ADDR_OE:     prdata[GPIO_WIDTH-1:0] = reg_oe;
            ADDR_IE:     prdata[GPIO_WIDTH-1:0] = reg_int_en;
            ADDR_ITYPE:  prdata[GPIO_WIDTH-1:0] = reg_int_type;
            ADDR_IPOL:   prdata[GPIO_WIDTH-1:0] = reg_int_pol;
            ADDR_ISTATE: prdata[GPIO_WIDTH-1:0] = gpio_int;     // interrupt state
            default:     prdata = 32'h0000_0000;
        endcase
    end

endmodule

module cvdp_copilot_apb_gpio #(
  parameter GPIO_WIDTH = 8
)(
  // Clock and Reset Signals
  input logic pclk,       // Clock signal
  input logic preset_n,   // Active-low reset signal

  // APB Interface Inputs
  input logic psel,           // Peripheral select
  input logic [7:2] paddr,    // APB address bus (bits [7:2])
  input logic penable,        // Transfer control signal
  input logic pwrite,         // Write control signal
  input logic [31:0] pwdata,  // Write data bus

  // APB Interface Outputs
  output logic [31:0] prdata, // Read data bus
  output logic pready,        // Device ready signal
  output logic pslverr,       // Device error response

  // GPIO Interface Inputs and Outputs
  input logic [GPIO_WIDTH-1:0] gpio_in,     // GPIO input signals
  output logic [GPIO_WIDTH-1:0] gpio_out,   // GPIO output signals
  output logic [GPIO_WIDTH-1:0] gpio_enable, // GPIO output enable signals

  // Interrupt Outputs
  output logic [GPIO_WIDTH-1:0] gpio_int, // Individual interrupt outputs
  output logic comb_int                   // Combined interrupt output
);

  // Signals for Read/Write Controls
  logic read_enable;                     // Read enable signal
  logic write_enable;                    // Write enable signal
  logic write_enable_reg_04;             // Write enable for Data Output register
  logic write_enable_reg_08;             // Write enable for Output Enable register
  logic write_enable_reg_0C;             // Write enable for Interrupt Enable register
  logic write_enable_reg_10;             // Write enable for Interrupt Type register
  logic write_enable_reg_14;             // Write enable for Interrupt Polarity register
  logic write_enable_reg_18;             // Write enable for Interrupt State register
  logic write_enable_reg_1C;             // Write enable for Direction Control register
  logic write_enable_reg_20;             // Write enable for Power Management register
  logic write_enable_reg_24;             // Write enable for Interrupt Reset register
  logic [GPIO_WIDTH-1:0] read_mux;       // Read data multiplexer
  logic [GPIO_WIDTH-1:0] read_mux_d1;    // Registered read data

  // Control Registers
  logic [GPIO_WIDTH-1:0] reg_dout;       // Data Output register
  logic [GPIO_WIDTH-1:0] reg_dout_en;    // Output Enable register
  logic [GPIO_WIDTH-1:0] reg_int_en;     // Interrupt Enable register
  logic [GPIO_WIDTH-1:0] reg_int_type;   // Interrupt Type register
  logic [GPIO_WIDTH-1:0] reg_int_pol;    // Interrupt Polarity register
  logic [GPIO_WIDTH-1:0] reg_int_state;  // Interrupt State register
  logic [GPIO_WIDTH-1:0] gpio_dir;       // Direction Control register (0x1C): 0=input, 1=output
  logic                  reg_pwr;        // Power Management register (0x20) bit[0]: global power-down

  // I/O Signal Path and Interrupt Logic
  logic [GPIO_WIDTH-1:0] data_in_sync1;            // First stage of input synchronization
  logic [GPIO_WIDTH-1:0] data_in_sync2;            // Second stage of input synchronization
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted;     // Polarity-adjusted input data
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted_dly; // Delayed version of polarity-adjusted input data
  logic [GPIO_WIDTH-1:0] edge_detect;              // Edge detection signals
  logic [GPIO_WIDTH-1:0] raw_int;                  // Raw interrupt signals
  logic [GPIO_WIDTH-1:0] int_masked;               // Masked interrupt signals
  logic [GPIO_WIDTH-1:0] clear_interrupt;          // Clear interrupt signals (0x18 write-1-to-clear)
  logic [GPIO_WIDTH-1:0] int_reset;                // Interrupt reset signals (0x24 write-1-to-clear)

  // Read and Write Control Signals
  assign read_enable = psel & (~pwrite); // Read enable
  assign write_enable = psel & (~penable) & pwrite; // Write enable

  // Write Enable Signals for Specific Registers
  assign write_enable_reg_04 = write_enable & (paddr[7:2] == 6'd1); // Address 0x04
  assign write_enable_reg_08 = write_enable & (paddr[7:2] == 6'd2); // Address 0x08
  assign write_enable_reg_0C = write_enable & (paddr[7:2] == 6'd3); // Address 0x0C
  assign write_enable_reg_10 = write_enable & (paddr[7:2] == 6'd4); // Address 0x10
  assign write_enable_reg_14 = write_enable & (paddr[7:2] == 6'd5); // Address 0x14
  assign write_enable_reg_18 = write_enable & (paddr[7:2] == 6'd6); // Address 0x18
  assign write_enable_reg_1C = write_enable & (paddr[7:2] == 6'd7); // Address 0x1C
  assign write_enable_reg_20 = write_enable & (paddr[7:2] == 6'd8); // Address 0x20
  assign write_enable_reg_24 = write_enable & (paddr[7:2] == 6'd9); // Address 0x24

  // Write Operations for Control Registers

  // Data Output Register (reg_dout)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_04)
      reg_dout <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Output Enable Register (reg_dout_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_08)
      reg_dout_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Enable Register (reg_int_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_0C)
      reg_int_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Type Register (reg_int_type)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_type <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_10)
      reg_int_type <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Polarity Register (reg_int_pol)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_pol <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_14)
      reg_int_pol <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Direction Control Register (gpio_dir) at address 0x1C
  // 0 = input, 1 = output. Synchronized to pclk. Reset default: all inputs (0).
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      gpio_dir <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_1C)
      gpio_dir <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Power Management Register (reg_pwr) at address 0x20
  // bit[0] = global power-down. Reserved bits ignored. Reset default: normal operation (0).
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_pwr <= 1'b0;
    else if (write_enable_reg_20)
      reg_pwr <= pwdata[0];
  end

  // Read Operation: Multiplexing Register Data Based on Address
  always_comb begin
    case (paddr[7:2])
      6'd0: read_mux = data_in_sync2;   // Input Data Register at address 0x00
      6'd1: read_mux = reg_dout;        // Data Output Register at address 0x04
      6'd2: read_mux = reg_dout_en;     // Output Enable Register at address 0x08
      6'd3: read_mux = reg_int_en;      // Interrupt Enable Register at address 0x0C
      6'd4: read_mux = reg_int_type;    // Interrupt Type Register at address 0x10
      6'd5: read_mux = reg_int_pol;     // Interrupt Polarity Register at address 0x14
      6'd6: read_mux = reg_int_state;   // Interrupt State Register at address 0x18
      6'd7: read_mux = gpio_dir;        // Direction Control Register at address 0x1C
      6'd8: read_mux = reg_pwr;         // Power Management Register at address 0x20 (bit0)
      6'd9: read_mux = {GPIO_WIDTH{1'b0}}; // Interrupt Reset Register at 0x24 reads as 0
      default: read_mux = {GPIO_WIDTH{1'b0}}; // Default to zeros if address is invalid
    endcase
  end

  // Registering Read Data for Timing Alignment
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      read_mux_d1 <= {GPIO_WIDTH{1'b0}};
    else
      read_mux_d1 <= read_mux;
  end

  // Output Read Data to APB Interface
  assign prdata = (read_enable) ? {{(32-GPIO_WIDTH){1'b0}}, read_mux_d1} : {32{1'b0}};
  assign pready = 1'b1; // Always ready
  assign pslverr = 1'b0; // No error

  // Driving GPIO Outputs and Output Enables
  // Direction Control (0x1C) adds runtime direction control on top of the legacy
  // Output Enable register (0x08); either can enable a pin as an output (preserving
  // backward compatibility, since gpio_dir resets to 0). Global power-down (0x20 bit0)
  // forces all pins inactive (high-Z / driven low) for a safe low-power state.
  assign gpio_enable = reg_pwr ? {GPIO_WIDTH{1'b0}} : (reg_dout_en | gpio_dir);
  assign gpio_out    = reg_pwr ? {GPIO_WIDTH{1'b0}} : reg_dout;

  // Input Synchronization to Avoid Metastability
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_sync1 <= {GPIO_WIDTH{1'b0}};
      data_in_sync2 <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_sync1 <= gpio_in;
      data_in_sync2 <= data_in_sync1;
    end
  end

  // Interrupt Logic

  // Adjusting Input Data Based on Interrupt Polarity
  assign data_in_pol_adjusted = data_in_sync2 ^ reg_int_pol; // Polarity adjustment

  // Registering Polarity-Adjusted Input Data and Delaying for Edge Detection
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_pol_adjusted_dly <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_pol_adjusted_dly <= data_in_pol_adjusted;
    end
  end

  // Edge Detection Logic for Interrupts
  assign edge_detect = data_in_pol_adjusted & (~data_in_pol_adjusted_dly); // Rising edge detection

  // Selecting Interrupt Type (Edge or Level-Triggered)
  assign raw_int = (reg_int_type & edge_detect) | (~reg_int_type & data_in_pol_adjusted); // Interrupt source

  // Applying Interrupt Enable Mask
  assign int_masked = raw_int & reg_int_en; // Masked interrupts

  // Clear Interrupt Signals (legacy: write to Interrupt State register 0x18)
  assign clear_interrupt = pwdata[GPIO_WIDTH-1:0] & {GPIO_WIDTH{write_enable_reg_18}};

  // Interrupt Reset Signals (new: write 1 to Interrupt Reset register 0x24)
  assign int_reset = pwdata[GPIO_WIDTH-1:0] & {GPIO_WIDTH{write_enable_reg_24}};

  // Updating Interrupt State Register
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      reg_int_state <= {GPIO_WIDTH{1'b0}};
    end else begin
      integer i;
      for (i = 0; i < GPIO_WIDTH; i = i + 1) begin
        if (reg_int_type[i]) begin
          // Edge-triggered interrupt
          if (clear_interrupt[i] || int_reset[i]) begin
            reg_int_state[i] <= 1'b0;
          end else if (int_masked[i]) begin
            reg_int_state[i] <= 1'b1;
          end
        end else begin
          // Level-triggered interrupt
          reg_int_state[i] <= int_reset[i] ? 1'b0 : int_masked[i];
        end
      end
    end
  end

  // Connecting Interrupt Outputs
  assign gpio_int = reg_int_state;     // Individual interrupt outputs
  assign comb_int = |reg_int_state;    // Combined interrupt output

endmodule

// APB-accessible 8-bit global history shift register for branch prediction.
// Misprediction has highest priority. Internal clock gating for power.
module APBGlobalHistoryRegister (
    // Clock & reset
    input  wire        pclk,
    input  wire        presetn,      // active-low async reset
    // APB interface
    input  wire [9:0]  paddr,
    input  wire        pselx,
    input  wire        penable,
    input  wire        pwrite,
    input  wire [7:0]  pwdata,
    output reg         pready,
    output reg  [7:0]  prdata,
    output reg         pslverr,
    // History shift interface
    input  wire        history_shift_valid,
    // Clock gating enable
    input  wire        clk_gate_en,
    // Status & interrupt signals
    output wire        history_full,
    output wire        history_empty,
    output wire        error_flag,
    output wire        interrupt_full,
    output wire        interrupt_error
);

    // -----------------------------------------------------------------
    // Register addresses
    // -----------------------------------------------------------------
    localparam [9:0] ADDR_CONTROL = 10'h0;
    localparam [9:0] ADDR_TRAIN   = 10'h1;
    localparam [9:0] ADDR_PREDICT = 10'h2;

    // -----------------------------------------------------------------
    // Architectural registers (spec-named, preserved verbatim)
    // -----------------------------------------------------------------
    reg [7:0] control_register;   // 0x0
    reg [7:0] train_history;      // 0x1 (train_history[6:0] valid, [7] reserved=0)
    reg [7:0] predict_history;    // 0x2 (shift register)

    // Control-register bit fields (spec-named, kept as real named nets)
    wire predict_valid      = control_register[0];
    wire predict_taken      = control_register[1];
    wire train_mispredicted = control_register[2];
    wire train_taken        = control_register[3];

    // -----------------------------------------------------------------
    // Clock gating: enable is sampled on the low phase of pclk (negedge
    // aligned) to avoid glitches. Asserting clk_gate_en gates pclk off.
    // -----------------------------------------------------------------
    reg gate_latch;
    always @(pclk or clk_gate_en) begin
        if (~pclk)
            gate_latch = clk_gate_en;
    end
    wire gclk = pclk & ~gate_latch;

    // -----------------------------------------------------------------
    // APB FSM state (observable). Two-cycle transaction, no wait states.
    // -----------------------------------------------------------------
    localparam [1:0] IDLE        = 2'b00,
                     READ_STATE  = 2'b01,
                     WRITE_STATE = 2'b10;
    reg [1:0] state;

    always @(posedge gclk or negedge presetn) begin
        if (!presetn) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (pselx && !penable)
                        state <= pwrite ? WRITE_STATE : READ_STATE;
                end
                READ_STATE:  state <= IDLE;
                WRITE_STATE: state <= IDLE;
                default:     state <= IDLE;
            endcase
        end
    end

    // -----------------------------------------------------------------
    // Address validity
    // -----------------------------------------------------------------
    wire addr_valid = (paddr == ADDR_CONTROL) ||
                      (paddr == ADDR_TRAIN)   ||
                      (paddr == ADDR_PREDICT);

    // -----------------------------------------------------------------
    // CSR write path (registered). predict_history is not APB-writable.
    // -----------------------------------------------------------------
    always @(posedge gclk or negedge presetn) begin
        if (!presetn) begin
            control_register <= 8'b0;
            train_history    <= 8'b0;
        end else if (pselx && penable && pwrite) begin
            case (paddr)
                ADDR_CONTROL: control_register <= {4'b0, pwdata[3:0]};
                ADDR_TRAIN:   train_history    <= {1'b0, pwdata[6:0]};
                default:      ; // ADDR_PREDICT is read-only; invalid = no write
            endcase
        end
    end

    // -----------------------------------------------------------------
    // APB read / handshake outputs (combinational: no wait states,
    // pready driven high during the access phase).
    // -----------------------------------------------------------------
    always @(*) begin
        prdata  = 8'b0;
        pslverr = 1'b0;
        pready  = 1'b0;
        if (pselx && penable) begin
            pready = 1'b1;
            if (!addr_valid) begin
                pslverr = 1'b1;
            end else if (!pwrite) begin
                case (paddr)
                    ADDR_CONTROL: prdata = {4'b0, control_register[3:0]};
                    ADDR_TRAIN:   prdata = {1'b0, train_history[6:0]};
                    ADDR_PREDICT: prdata = predict_history;
                    default:      prdata = 8'b0;
                endcase
            end
        end
    end

    // -----------------------------------------------------------------
    // Error flag (latched interrupt source for invalid address access).
    // -----------------------------------------------------------------
    reg error_flag_r;
    always @(posedge gclk or negedge presetn) begin
        if (!presetn)
            error_flag_r <= 1'b0;
        else if (pselx && penable)
            error_flag_r <= ~addr_valid;
    end
    assign error_flag = error_flag_r;

    // -----------------------------------------------------------------
    // Prediction update: updated only on rising edge of history_shift_valid.
    // Misprediction has highest priority.
    // -----------------------------------------------------------------
    always @(posedge history_shift_valid or negedge presetn) begin
        if (!presetn) begin
            predict_history <= 8'b0;
        end else if (train_mispredicted) begin
            // Restore history before mispredicted branch + actual outcome
            predict_history <= {train_history[6:0], train_taken};
        end else if (predict_valid) begin
            // Shift in predicted direction at LSB (youngest branch)
            predict_history <= {predict_history[6:0], predict_taken};
        end
    end

    // -----------------------------------------------------------------
    // Status & interrupt outputs
    // -----------------------------------------------------------------
    assign history_full    = (predict_history == 8'hFF);
    assign history_empty   = (predict_history == 8'h00);
    assign interrupt_full  = history_full;
    assign interrupt_error = error_flag;

endmodule

module arithmetic_progression_generator #(
    parameter DATA_WIDTH = 16,  // Width of the input data
    parameter SEQUENCE_LENGTH = 10 // Number of terms in the progression
)(
    clk,
    resetn,
    enable,
    start_val,
    step_size,
    out_val,
    done
);
  // ----------------------------------------
  // - Local parameter definition
  // ----------------------------------------
    // Maximum term = (2**DATA_WIDTH-1)*SEQUENCE_LENGTH, which is strictly
    // less than 2**(DATA_WIDTH+$clog2(SEQUENCE_LENGTH)); that many bits are
    // sufficient (and necessary) to hold the largest term without overflow.
    localparam WIDTH_OUT_VAL = DATA_WIDTH + $clog2(SEQUENCE_LENGTH);

  // ----------------------------------------
  // - Interface Definitions
  // ----------------------------------------
    input  logic clk;                          // Clock signal
    input  logic resetn;                       // Active-low reset
    input  logic enable;                       // Enable signal for the generator
    input  logic [DATA_WIDTH-1:0] start_val;   // Start value of the sequence
    input  logic [DATA_WIDTH-1:0] step_size;   // Step size of the sequence
    output logic [WIDTH_OUT_VAL-1:0] out_val;  // Current value of the sequence
    output logic done;                         // High when sequence generation is complete

  // ----------------------------------------
  // - Internal signals
  // ----------------------------------------
    logic [WIDTH_OUT_VAL-1:0] current_val;  // Register to hold the current value
    logic [$clog2(SEQUENCE_LENGTH)-1:0] counter;  // Counter to track sequence length

  // ----------------------------------------
  // - Procedural block
  // ----------------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_val <= 0;
            counter     <= 0;
            done        <= 1'b0;
        end else if (enable) begin
            if (!done) begin
                if (counter < SEQUENCE_LENGTH) begin
                    // Produce one term per enabled clock cycle:
                    //   term[0]        = start_val
                    //   term[k] (k>=1) = term[k-1] + step_size
                    if (counter == 0)
                        current_val <= start_val;
                    else
                        current_val <= current_val + step_size;
                    counter <= counter + 1'b1;
                end else begin
                    // All SEQUENCE_LENGTH terms generated: assert done and
                    // hold the final value (done stays set until reset).
                    done <= 1'b1;
                end
            end
        end
    end

  // ----------------------------------------
  // - Combinational Assignments
  // ----------------------------------------
    assign out_val = current_val;

endmodule

module arithmetic_progression_generator #(
    parameter DATA_WIDTH = 16,  // Width of the input data
    parameter SEQUENCE_LENGTH = 10 // Number of terms in the progression
)(
    clk,
    resetn,
    enable,
    start_val,
    step_size,
    out_val,
    done
);
  // ----------------------------------------
  // - Local parameter definition
  // ----------------------------------------

    // Guard $clog2 against SEQUENCE_LENGTH = 0 (and 1) so it never produces
    // a math-domain error / a negative bit range. For SEQUENCE_LENGTH >= 2
    // these evaluate to exactly the original values, so behaviour is unchanged
    // for every valid non-zero length.
    localparam WIDTH_OUT_VAL = (SEQUENCE_LENGTH <= 1) ? DATA_WIDTH
                                                      : ($clog2(SEQUENCE_LENGTH) + DATA_WIDTH); // Bit width of out_val to prevent overflow
    localparam CNT_WIDTH     = (SEQUENCE_LENGTH <= 1) ? 1
                                                      : $clog2(SEQUENCE_LENGTH); // Counter width, always >= 1

  // ----------------------------------------
  // - Interface Definitions
  // ----------------------------------------
    input logic clk;                          // Clock signal
    input logic resetn;                       // Active-low reset
    input logic enable;                       // Enable signal for the generator
    input logic [DATA_WIDTH-1:0] start_val;   // Start value of the sequence
    input logic [DATA_WIDTH-1:0] step_size;   // Step size of the sequence
    output logic [WIDTH_OUT_VAL-1:0] out_val; // Current value of the sequence
    output logic done;                        // High when sequence generation is complete


  // ----------------------------------------
  // - Internal signals
  // ----------------------------------------
    logic [WIDTH_OUT_VAL-1:0] current_val;  // Register to hold the current value
    logic [CNT_WIDTH-1:0] counter;          // Counter to track sequence length

  // ----------------------------------------
  // - Procedural block
  // ----------------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            current_val <= 0;
            counter <= 0;
            done <= 1'b0;
        end else if (enable && (SEQUENCE_LENGTH != 0)) begin
            // When SEQUENCE_LENGTH == 0 there is nothing to generate:
            // current_val stays at its reset value (0) and done never asserts.
            if (!done) begin
                if (counter == 0) begin
                    current_val <= start_val; // Initialize with start value
                end else begin
                    current_val <= current_val + step_size; // Compute next term
                end

                if (counter < SEQUENCE_LENGTH - 1) begin
                    counter <= counter + 1; // Increment counter
                end else begin
                    done <= 1'b1; // Mark completion
                end
            end
        end
    end

  // ----------------------------------------
  // - Combinational Assignments
  // ----------------------------------------
    assign out_val = current_val;

endmodule

module async_filo #(
    parameter DATA_WIDTH = 16,
    parameter DEPTH      = 8
  ) (
    input                         w_clk,    // Write clock
    input                         w_rst,    // Write reset
    input                         push,     // Push signal
    input                         r_rst,    // Read reset
    input                         r_clk,    // Read clock
    input                         pop,      // Pop signal
    input        [DATA_WIDTH-1:0] w_data,   // Data input for push
    output logic [DATA_WIDTH-1:0] r_data,   // Data output for pop
    output logic                  r_empty,  // Empty flag
    output logic                  w_full    // Full flag
  );

    localparam PTR_W = $clog2(DEPTH);

    // Storage
    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // Pointers / counters (declared per template)
    logic [PTR_W:0] w_ptr, r_ptr;
    logic [PTR_W:0] w_count_bin, r_count_bin;
    logic [PTR_W:0] wq2_rptr, rq2_wptr;

    // Gray-code registers and 2-flop synchronizers for CDC
    logic [PTR_W:0] w_gray;              // write count gray, in write domain
    logic [PTR_W:0] r_gray;              // read  count gray, in read  domain
    logic [PTR_W:0] wgray_sync1, wgray_sync2; // w_gray synced into read domain
    logic [PTR_W:0] rgray_sync1, rgray_sync2; // r_gray synced into write domain

    // -----------------------------------------------------------------
    // Gray <-> binary helpers
    // -----------------------------------------------------------------
    function automatic [PTR_W:0] bin2gray(input [PTR_W:0] b);
      bin2gray = b ^ (b >> 1);
    endfunction

    function automatic [PTR_W:0] gray2bin(input [PTR_W:0] g);
      integer i;
      reg [PTR_W:0] b;
      begin
        b[PTR_W] = g[PTR_W];
        for (i = PTR_W-1; i >= 0; i = i - 1)
          b[i] = b[i+1] ^ g[i];
        gray2bin = b;
      end
    endfunction

    // -----------------------------------------------------------------
    // Next-count combinational values
    // -----------------------------------------------------------------
    wire [PTR_W:0] w_count_next = (push && !w_full) ? (w_count_bin + 1'b1) : w_count_bin;
    wire [PTR_W:0] r_count_next = (pop  && !r_empty) ? (r_count_bin + 1'b1) : r_count_bin;

    // Synchronized write count in the read domain (binary)
    assign rq2_wptr = gray2bin(wgray_sync2);
    // Synchronized read  count in the write domain (binary)
    assign wq2_rptr = gray2bin(rgray_sync2);

    // Read-side top-of-stack address computation
    wire            empty_now = (r_count_bin == rq2_wptr);
    wire [PTR_W:0]  r_avail   = rq2_wptr - r_count_bin;                 // items available
    wire [PTR_W:0]  rd_addr   = empty_now ? {(PTR_W+1){1'b0}}
                                          : (r_avail - 1'b1);           // top of stack

    // -----------------------------------------------------------------
    // Write (push) logic
    // -----------------------------------------------------------------
    always_ff @(posedge w_clk or posedge w_rst) begin
      if (w_rst) begin
        w_count_bin <= '0;
        w_ptr       <= '0;
      end
      else begin
        if (push && !w_full) begin
          mem[w_ptr]  <= w_data;
          w_ptr       <= w_ptr + 1'b1;
          w_count_bin <= w_count_bin + 1'b1;
        end
      end
    end

    // Write-domain gray register
    always_ff @(posedge w_clk or posedge w_rst) begin
      if (w_rst) w_gray <= '0;
      else       w_gray <= bin2gray(w_count_next);
    end

    // -----------------------------------------------------------------
    // Read (pop) logic
    // -----------------------------------------------------------------
    always_ff @(posedge r_clk or posedge r_rst) begin
      if (r_rst) begin
        r_count_bin <= '0;
        r_ptr       <= '0;
        r_data      <= '0;
      end
      else begin
        r_ptr <= rd_addr;
        if (pop && !r_empty) begin
          r_data      <= mem[rd_addr];
          r_count_bin <= r_count_bin + 1'b1;
        end
      end
    end

    // Read-domain gray register
    always_ff @(posedge r_clk or posedge r_rst) begin
      if (r_rst) r_gray <= '0;
      else       r_gray <= bin2gray(r_count_next);
    end

    // -----------------------------------------------------------------
    // CDC synchronizers
    // -----------------------------------------------------------------
    // w_gray -> read domain
    always_ff @(posedge r_clk or posedge r_rst) begin
      if (r_rst) begin
        wgray_sync1 <= '0;
        wgray_sync2 <= '0;
      end
      else begin
        wgray_sync1 <= w_gray;
        wgray_sync2 <= wgray_sync1;
      end
    end

    // r_gray -> write domain
    always_ff @(posedge w_clk or posedge w_rst) begin
      if (w_rst) begin
        rgray_sync1 <= '0;
        rgray_sync2 <= '0;
      end
      else begin
        rgray_sync1 <= r_gray;
        rgray_sync2 <= rgray_sync1;
      end
    end

    // -----------------------------------------------------------------
    // Empty flag logic (read domain)
    // -----------------------------------------------------------------
    always_ff @(posedge r_clk or posedge r_rst) begin
      if (r_rst) r_empty <= 1'b1;
      else       r_empty <= (r_count_next == rq2_wptr);
    end

    // -----------------------------------------------------------------
    // Full flag logic (write domain)
    // -----------------------------------------------------------------
    always_ff @(posedge w_clk or posedge w_rst) begin
      if (w_rst) w_full <= 1'b0;
      else       w_full <= (w_count_next == DEPTH[PTR_W:0]);
    end

endmodule

`timescale 1ns / 1ps

module async_filo #(
    parameter DATA_WIDTH = 16,
    parameter DEPTH      = 8
) (
    input                         w_clk,    // Write clock
    input                         w_rst,    // Write reset
    input                         push,     // Push signal
    input                         r_rst,    // Read reset
    input                         r_clk,    // Read clock
    input                         pop,      // Pop signal
    input        [DATA_WIDTH-1:0] w_data,   // Data input for push
    output logic [DATA_WIDTH-1:0] r_data,   // Data output for pop
    output logic                  r_empty,  // Empty flag
    output logic                  w_full    // Full flag
);

  // Address width
  localparam ADDR_WIDTH = $clog2(DEPTH);

  // Gray-coded pointers (registered)
  logic [ADDR_WIDTH:0] w_ptr;
  logic [ADDR_WIDTH:0] r_ptr;

  // Binary counters and next-state values
  logic [ADDR_WIDTH:0] w_count_bin, r_count_bin;
  wire  [ADDR_WIDTH:0] w_count_next_bin, r_count_next_bin;
  wire  [ADDR_WIDTH:0] w_ptr_next, r_ptr_next;

  // Memory and address nets
  logic [DATA_WIDTH-1:0] mem[0:DEPTH-1];
  wire  [ADDR_WIDTH-1:0] w_addr;
  wire  [ADDR_WIDTH-1:0] r_addr;

  // Two-flop pointer synchronizers
  logic [ADDR_WIDTH:0] wq1_rptr, wq2_rptr;
  logic [ADDR_WIDTH:0] rq1_wptr, rq2_wptr;
  wire  [ADDR_WIDTH:0] wq2_rptr_bin;

  // Binary <-> Gray conversion
  function automatic [ADDR_WIDTH:0] bin2gray(input [ADDR_WIDTH:0] bin);
    bin2gray = bin ^ (bin >> 1);
  endfunction

  function automatic [ADDR_WIDTH:0] gray2bin(input [ADDR_WIDTH:0] gray);
    gray2bin = gray;
    for (int i = 1; i <= ADDR_WIDTH; i++) gray2bin[i] = gray2bin[i] ^ gray2bin[i-1];
  endfunction

  // Write-domain memory write
  always @(posedge w_clk) begin
    if (push && !w_full) mem[w_addr] <= w_data;
  end

  // Combinational read
  assign r_data = mem[r_addr];

  // Read-pointer synchronized into the write clock domain
  always @(posedge w_clk, posedge w_rst) begin
    if (w_rst) begin
      wq1_rptr <= 0;
      wq2_rptr <= 0;
    end else begin
      wq1_rptr <= r_ptr;
      wq2_rptr <= wq1_rptr;
    end
  end

  // Write-pointer synchronized into the read clock domain
  always @(posedge r_clk, posedge r_rst) begin
    if (r_rst) begin
      rq1_wptr <= 0;
      rq2_wptr <= 0;
    end else begin
      rq1_wptr <= w_ptr;
      rq2_wptr <= rq1_wptr;
    end
  end

  // Write-domain binary counter / Gray pointer
  always @(posedge w_clk, posedge w_rst) begin
    if (w_rst) begin
      w_count_bin <= 0;
      w_ptr       <= 0;
    end else begin
      w_count_bin <= w_count_next_bin;
      w_ptr       <= w_ptr_next;
    end
  end

  assign w_count_next_bin = w_count_bin + ({(ADDR_WIDTH+1){push}} & ~{(ADDR_WIDTH+1){w_full}});
  assign w_ptr_next       = bin2gray(w_count_next_bin);
  assign wq2_rptr_bin     = gray2bin(wq2_rptr);

  // Read-domain binary counter / Gray pointer
  always @(posedge r_clk, posedge r_rst) begin
    if (r_rst) begin
      r_count_bin <= 0;
      r_ptr       <= 0;
    end else begin
      r_count_bin <= r_count_next_bin;
      r_ptr       <= r_ptr_next;
    end
  end

  assign r_count_next_bin = r_count_bin + ({(ADDR_WIDTH+1){pop}} & ~{(ADDR_WIDTH+1){r_empty}});
  assign r_ptr_next       = bin2gray(r_count_next_bin);

  assign w_addr = w_count_bin[ADDR_WIDTH-1:0];
  assign r_addr = r_count_bin[ADDR_WIDTH-1:0];

  // Empty flag (read domain)
  always @(posedge r_clk or posedge r_rst) begin
    if (r_rst) begin
      r_empty <= 1'b1;
    end else begin
      r_empty <= (r_ptr_next == rq2_wptr);
    end
  end

  // Full flag (write domain)
  always @(posedge w_clk or posedge w_rst) begin
    if (w_rst) begin
      w_full <= 1'b0;
    end else begin
      w_full <= (w_count_next_bin[ADDR_WIDTH] != wq2_rptr_bin[ADDR_WIDTH]) &&
                (w_count_next_bin[ADDR_WIDTH-1:0] == wq2_rptr_bin[ADDR_WIDTH-1:0]);
    end
  end

endmodule

module axi_alu (
    input  wire        axi_clk_in,
    input  wire        fast_clk_in,
    input  wire        reset_in,

    // AXI Interface
    input  wire        axi_awvalid_i,
    input  wire        axi_wvalid_i,
    input  wire        axi_bready_i,
    input  wire        axi_arvalid_i,
    input  wire        axi_rready_i,

    output wire        axi_awready_o,
    output wire        axi_wready_o,
    output wire        axi_bvalid_o,
    output wire        axi_arready_o,
    output wire        axi_rvalid_o,

    input  wire [31:0] axi_awaddr_i,
    input  wire [31:0] axi_wdata_i,
    input  wire [31:0] axi_araddr_i,

    input  wire [3:0]  axi_wstrb_i,
    output wire [31:0] axi_rdata_o,
    output wire [63:0] result_o,

    // AXI4 Burst / Response signals
    input  wire [7:0]  axi_awlen_i,
    input  wire [2:0]  axi_awsize_i,
    input  wire [1:0]  axi_awburst_i,
    input  wire        axi_wlast_i,
    input  wire [7:0]  axi_arlen_i,
    input  wire [2:0]  axi_arsize_i,
    input  wire [1:0]  axi_arburst_i,
    output wire        axi_rlast_o,
    output wire [1:0]  axi_rresp_o,
    output wire [1:0]  axi_bresp_o
);

    wire        clk;
    wire [1:0]  op_select;
    wire        start, clock_control;
    wire [31:0] data_a, data_b, data_c;

    // CSR outputs (AXI clock domain)
    wire [31:0] csr_operand_a, csr_operand_b, csr_operand_c;
    wire [1:0]  csr_op_select;
    wire        csr_start;

    // CDC-synchronized versions (destination = controlled clock domain)
    wire [31:0] sync_operand_a, sync_operand_b, sync_operand_c;
    wire [1:0]  sync_op_select;
    wire        sync_start;

    // Operands actually used by memory / DSP
    wire [31:0] operand_a, operand_b, operand_c;

    // DSP result and its sync back into the AXI (CSR) domain
    wire [63:0] dsp_result;
    wire [63:0] dsp_result_sync;
    wire [63:0] dsp_result_to_csr;

    // RAM interface between CSR block and memory block
    wire        ram_we;
    wire [3:0]  ram_waddr;
    wire [31:0] ram_wdata;
    wire [3:0]  ram_raddr;
    wire [31:0] ram_rdata;

    clock_control u_clock_control (
        .axi_clk_in  (axi_clk_in),
        .fast_clk_in (fast_clk_in),
        .clk_ctrl    (clock_control),
        .clk         (clk)
    );

    axi_csr_block u_axi_csr_block (
        .axi_aclk_i    (axi_clk_in),
        .axi_areset_i  (reset_in),
        .axi_awvalid_i (axi_awvalid_i),
        .axi_awready_o (axi_awready_o),
        .axi_awaddr_i  (axi_awaddr_i),
        .axi_awlen_i   (axi_awlen_i),
        .axi_awsize_i  (axi_awsize_i),
        .axi_awburst_i (axi_awburst_i),
        .axi_wvalid_i  (axi_wvalid_i),
        .axi_wready_o  (axi_wready_o),
        .axi_wdata_i   (axi_wdata_i),
        .axi_wstrb_i   (axi_wstrb_i),
        .axi_wlast_i   (axi_wlast_i),
        .axi_bvalid_o  (axi_bvalid_o),
        .axi_bready_i  (axi_bready_i),
        .axi_bresp_o   (axi_bresp_o),
        .axi_arvalid_i (axi_arvalid_i),
        .axi_arready_o (axi_arready_o),
        .axi_araddr_i  (axi_araddr_i),
        .axi_arlen_i   (axi_arlen_i),
        .axi_arsize_i  (axi_arsize_i),
        .axi_arburst_i (axi_arburst_i),
        .axi_rvalid_o  (axi_rvalid_o),
        .axi_rready_i  (axi_rready_i),
        .axi_rdata_o   (axi_rdata_o),
        .axi_rlast_o   (axi_rlast_o),
        .axi_rresp_o   (axi_rresp_o),
        .operand_a     (csr_operand_a),
        .operand_b     (csr_operand_b),
        .operand_c     (csr_operand_c),
        .op_select     (csr_op_select),
        .start         (csr_start),
        .clock_control (clock_control),
        .ram_we        (ram_we),
        .ram_waddr     (ram_waddr),
        .ram_wdata     (ram_wdata),
        .ram_raddr     (ram_raddr),
        .ram_rdata     (ram_rdata),
        .dsp_result    (dsp_result_to_csr)
    );

    // CDC double-flop synchronizers into the controlled-clock domain.
    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_a (.clk_dst(clk), .reset_in(reset_in), .data_in(csr_operand_a), .data_out(sync_operand_a));
    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_b (.clk_dst(clk), .reset_in(reset_in), .data_in(csr_operand_b), .data_out(sync_operand_b));
    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_c (.clk_dst(clk), .reset_in(reset_in), .data_in(csr_operand_c), .data_out(sync_operand_c));
    cdc_synchronizer #(.WIDTH(2))  u_cdc_op_select (.clk_dst(clk), .reset_in(reset_in), .data_in(csr_op_select), .data_out(sync_op_select));
    cdc_synchronizer #(.WIDTH(1))  u_cdc_start     (.clk_dst(clk), .reset_in(reset_in), .data_in(csr_start),     .data_out(sync_start));

    // Sync the DSP result back into the AXI clock domain.
    cdc_synchronizer #(.WIDTH(64)) u_cdc_dsp_result (.clk_dst(axi_clk_in), .reset_in(reset_in), .data_in(dsp_result), .data_out(dsp_result_sync));

    // Gate CDC by clock_control: HIGH -> use synchronized values (fast domain),
    // LOW -> AXI clock domain, pass CSR values through directly.
    assign operand_a = clock_control ? sync_operand_a : csr_operand_a;
    assign operand_b = clock_control ? sync_operand_b : csr_operand_b;
    assign operand_c = clock_control ? sync_operand_c : csr_operand_c;
    assign op_select = clock_control ? sync_op_select : csr_op_select;
    assign start     = clock_control ? sync_start     : csr_start;

    assign dsp_result_to_csr = clock_control ? dsp_result_sync : dsp_result;

    memory_block u_memory_block (
        .axi_clk        (axi_clk_in),
        .reset_in       (reset_in),
        .we             (ram_we),
        .write_address  (ram_waddr),
        .write_data     (ram_wdata),
        .address_a      (operand_a[3:0]),
        .address_b      (operand_b[3:0]),
        .address_c      (operand_c[3:0]),
        .address_rd     (ram_raddr),
        .data_a         (data_a),
        .data_b         (data_b),
        .data_c         (data_c),
        .data_rd        (ram_rdata)
    );

    dsp_block u_dsp_block (
        .clk        (clk),
        .reset_in   (reset_in),
        .operand_a  (data_a),
        .operand_b  (data_b),
        .operand_c  (data_c),
        .op_select  (op_select),
        .start      (start),
        .result     (dsp_result)
    );

    assign result_o = dsp_result;

endmodule

// ------------------------------------------------------------------
// CDC Synchronizer Module (Double Flop Synchronization)
// ------------------------------------------------------------------
module cdc_synchronizer #(parameter WIDTH = 1) (
    input  wire             clk_dst,   // Destination clock
    input  wire             reset_in,  // Reset signal
    input  wire [WIDTH-1:0] data_in,   // Data from source domain
    output reg  [WIDTH-1:0] data_out   // Synchronized data in destination domain
);
    reg [WIDTH-1:0] data_sync_1;

    always @(posedge clk_dst or posedge reset_in) begin
        if (reset_in) begin
            data_sync_1 <= {WIDTH{1'b0}};
            data_out    <= {WIDTH{1'b0}};
        end else begin
            data_sync_1 <= data_in;     // First stage
            data_out    <= data_sync_1; // Second stage
        end
    end
endmodule

// ------------------------------------------------------------------
// Clock Control Module
// ------------------------------------------------------------------
module clock_control (
    input  wire axi_clk_in,
    input  wire fast_clk_in,
    input  wire clk_ctrl,
    output wire clk
);
    assign clk = clk_ctrl ? fast_clk_in : axi_clk_in;
endmodule

// ------------------------------------------------------------------
// AXI-to-CSR Register Block (with burst + response handling)
// ------------------------------------------------------------------
module axi_csr_block (
    input  wire        axi_aclk_i,
    input  wire        axi_areset_i,

    // AXI Write Address Channel
    input  wire        axi_awvalid_i,
    output wire        axi_awready_o,
    input  wire [31:0] axi_awaddr_i,
    input  wire [7:0]  axi_awlen_i,
    input  wire [2:0]  axi_awsize_i,
    input  wire [1:0]  axi_awburst_i,

    // AXI Write Data Channel
    input  wire        axi_wvalid_i,
    output wire        axi_wready_o,
    input  wire [31:0] axi_wdata_i,
    input  wire [3:0]  axi_wstrb_i,
    input  wire        axi_wlast_i,

    // AXI Write Response Channel
    output reg         axi_bvalid_o,
    input  wire        axi_bready_i,
    output wire [1:0]  axi_bresp_o,

    // AXI Read Address Channel
    input  wire        axi_arvalid_i,
    output wire        axi_arready_o,
    input  wire [31:0] axi_araddr_i,
    input  wire [7:0]  axi_arlen_i,
    input  wire [2:0]  axi_arsize_i,
    input  wire [1:0]  axi_arburst_i,

    // AXI Read Data Channel
    output reg         axi_rvalid_o,
    input  wire        axi_rready_i,
    output reg  [31:0] axi_rdata_o,
    output wire        axi_rlast_o,
    output wire [1:0]  axi_rresp_o,

    // CSR Outputs
    output wire [31:0] operand_a,
    output wire [31:0] operand_b,
    output wire [31:0] operand_c,
    output wire [1:0]  op_select,
    output wire        start,
    output wire        clock_control,

    // RAM write / read interface (to memory_block)
    output reg         ram_we,
    output reg  [3:0]  ram_waddr,
    output reg  [31:0] ram_wdata,
    output wire [3:0]  ram_raddr,
    input  wire [31:0] ram_rdata,

    // DSP result (already synchronized into this clock domain)
    input  wire [63:0] dsp_result
);
    reg [31:0] csr_reg [0:4];

    // --------------------------------------------------------------
    // Write FSM (handles both single and INCR-burst writes)
    // --------------------------------------------------------------
    localparam W_IDLE = 2'd0, W_DATA = 2'd1, W_RESP = 2'd2;
    reg [1:0]  wstate;
    reg [31:0] waddr;   // current write byte address
    reg [7:0]  wbeats;  // remaining beats after the current one

    assign axi_awready_o = (wstate == W_IDLE);
    assign axi_wready_o  = (wstate == W_DATA);
    assign axi_bresp_o   = 2'b00; // OKAY

    integer k;
    always @(posedge axi_aclk_i or posedge axi_areset_i) begin
        if (axi_areset_i) begin
            wstate       <= W_IDLE;
            waddr        <= 32'd0;
            wbeats       <= 8'd0;
            axi_bvalid_o <= 1'b0;
            ram_we       <= 1'b0;
            ram_waddr    <= 4'd0;
            ram_wdata    <= 32'd0;
            for (k = 0; k < 5; k = k + 1)
                csr_reg[k] <= 32'd0;
        end else begin
            ram_we <= 1'b0; // default; pulses high only on an accepted RAM beat
            case (wstate)
                W_IDLE: begin
                    if (axi_awvalid_i) begin
                        waddr  <= axi_awaddr_i;
                        wbeats <= axi_awlen_i;
                        wstate <= W_DATA;
                    end
                end
                W_DATA: begin
                    if (axi_wvalid_i) begin
                        if (waddr < 32'd32) begin
                            // Control / configuration registers (0x00 - 0x1C)
                            if (waddr[4:2] <= 3'd4)
                                csr_reg[waddr[4:2]] <= axi_wdata_i;
                        end else if (waddr < 32'd96) begin
                            // Memory data registers (0x20 - 0x5C) -> RAM
                            ram_we    <= 1'b1;
                            ram_waddr <= (waddr - 32'd32) >> 2;
                            ram_wdata <= axi_wdata_i;
                        end
                        waddr <= waddr + 32'd4; // INCR by one 32-bit word
                        if (axi_wlast_i || (wbeats == 8'd0)) begin
                            wstate       <= W_RESP;
                            axi_bvalid_o <= 1'b1;
                        end else begin
                            wbeats <= wbeats - 8'd1;
                        end
                    end
                end
                W_RESP: begin
                    if (axi_bready_i) begin
                        axi_bvalid_o <= 1'b0;
                        wstate       <= W_IDLE;
                    end
                end
                default: wstate <= W_IDLE;
            endcase
        end
    end

    // --------------------------------------------------------------
    // Read FSM (handles single and INCR-burst reads)
    // --------------------------------------------------------------
    localparam R_IDLE = 1'b0, R_DATA = 1'b1;
    reg        rstate;
    reg [31:0] raddr;   // byte address of the beat currently presented
    reg [7:0]  rbeats;  // remaining beats after the current one

    assign axi_arready_o = (rstate == R_IDLE);
    assign axi_rresp_o   = 2'b00;            // OKAY
    assign axi_rlast_o   = (rbeats == 8'd0); // last beat when no beats remain
    assign ram_raddr     = (raddr - 32'd32) >> 2;

    always @(posedge axi_aclk_i or posedge axi_areset_i) begin
        if (axi_areset_i) begin
            rstate       <= R_IDLE;
            raddr        <= 32'd0;
            rbeats       <= 8'd0;
            axi_rvalid_o <= 1'b0;
        end else begin
            case (rstate)
                R_IDLE: begin
                    if (axi_arvalid_i) begin
                        raddr        <= axi_araddr_i;
                        rbeats       <= axi_arlen_i;
                        rstate       <= R_DATA;
                        axi_rvalid_o <= 1'b1;
                    end
                end
                R_DATA: begin
                    if (axi_rready_i) begin
                        if (rbeats == 8'd0) begin
                            axi_rvalid_o <= 1'b0;
                            rstate       <= R_IDLE;
                        end else begin
                            raddr  <= raddr + 32'd4;
                            rbeats <= rbeats - 8'd1;
                        end
                    end
                end
                default: rstate <= R_IDLE;
            endcase
        end
    end

    // Combinational read-data decode (raddr holds the current beat address).
    always @(*) begin
        if (raddr < 32'd32) begin
            if (raddr[4:2] <= 3'd4)
                axi_rdata_o = csr_reg[raddr[4:2]];
            else
                axi_rdata_o = 32'd0;
        end else if (raddr < 32'd96) begin
            axi_rdata_o = ram_rdata;
        end else begin
            axi_rdata_o = dsp_result[31:0]; // result register readback
        end
    end

    // CSR register outputs
    assign operand_a     = csr_reg[0];
    assign operand_b     = csr_reg[1];
    assign operand_c     = csr_reg[2];
    assign op_select     = csr_reg[3][1:0];
    assign start         = csr_reg[3][2];
    assign clock_control = csr_reg[4][0];

endmodule

// ------------------------------------------------------------------
// Memory Block (RAM: 16 x 32-bit, synchronous write, asynchronous read)
// ------------------------------------------------------------------
module memory_block (
    input  wire        axi_clk,
    input  wire        reset_in,
    input  wire        we,
    input  wire [3:0]  write_address,
    input  wire [31:0] write_data,
    input  wire [3:0]  address_a,
    input  wire [3:0]  address_b,
    input  wire [3:0]  address_c,
    input  wire [3:0]  address_rd,
    output wire [31:0] data_a,
    output wire [31:0] data_b,
    output wire [31:0] data_c,
    output wire [31:0] data_rd
);
    reg [31:0] ram [0:15];
    reg [31:0] result_address;
    integer i;

    // Synchronous write on the AXI clock, reset clears the array.
    always @(posedge axi_clk or posedge reset_in) begin
        if (reset_in) begin
            for (i = 0; i < 16; i = i + 1)
                ram[i] <= 32'd0;
            result_address <= 32'd0;
        end else begin
            if (we)
                ram[write_address] <= write_data;
            result_address <= ram[0];
        end
    end

    // Asynchronous (combinational) reads.
    assign data_a  = reset_in ? 32'd0 : ram[address_a];
    assign data_b  = reset_in ? 32'd0 : ram[address_b];
    assign data_c  = reset_in ? 32'd0 : ram[address_c];
    assign data_rd = ram[address_rd];
endmodule

// ------------------------------------------------------------------
// DSP Processing Block
// ------------------------------------------------------------------
module dsp_block (
    input  wire        clk,
    input  wire        reset_in,
    input  wire [31:0] operand_a,
    input  wire [31:0] operand_b,
    input  wire [31:0] operand_c,
    input  wire [1:0]  op_select,
    input  wire        start,
    output reg  [63:0] result
);
    always @(posedge clk or posedge reset_in) begin
        if (reset_in)
            result <= 64'd0;
        else begin
            if (start) begin
                case (op_select)
                    2'b00: result <= (operand_a + operand_b) * operand_c;        // MAC
                    2'b01: result <= operand_a * operand_b;                       // Multiplication
                    2'b10: result <= operand_a >> operand_b[4:0];                 // Shift Right
                    2'b11: result <= operand_b ? (operand_a / operand_b) : 64'hDEADDEAD; // Division
                endcase
            end
        end
    end
endmodule

module axi_register #(
    parameter int ADDR_WIDTH = 32,
    parameter int DATA_WIDTH = 32
) (
    input  logic                      clk_i,
    input  logic                      rst_n_i,

    // Write address channel
    input  logic [ADDR_WIDTH-1:0]     awaddr_i,
    input  logic                      awvalid_i,
    output logic                      awready_o,

    // Write data channel
    input  logic [DATA_WIDTH-1:0]     wdata_i,
    input  logic                      wvalid_i,
    input  logic [(DATA_WIDTH/8)-1:0] wstrb_i,
    output logic                      wready_o,

    // Write response channel
    output logic [1:0]                bresp_o,
    output logic                      bvalid_o,
    input  logic                      bready_i,

    // Read address channel
    input  logic [ADDR_WIDTH-1:0]     araddr_i,
    input  logic                      arvalid_i,
    output logic                      arready_o,

    // Read data channel
    output logic [DATA_WIDTH-1:0]     rdata_o,
    output logic                      rvalid_o,
    output logic [1:0]                rresp_o,
    input  logic                      rready_i,

    // Hardware-side signals
    input  logic                      done_i,
    output logic [19:0]               beat_o,
    output logic                      start_o,
    output logic                      writeback_o
);

    // -------------------------------------------------------------------------
    // Local parameters
    // -------------------------------------------------------------------------
    localparam logic [11:0] BEAT_OFFSET      = 12'h100;
    localparam logic [11:0] START_OFFSET     = 12'h200;
    localparam logic [11:0] DONE_OFFSET      = 12'h300;
    localparam logic [11:0] WRITEBACK_OFFSET = 12'h400;
    localparam logic [11:0] ID_OFFSET        = 12'h500;

    localparam logic [DATA_WIDTH-1:0] ID_VALUE = 'h0001_0001;

    localparam logic [1:0] RESP_OKAY   = 2'b00;
    localparam logic [1:0] RESP_SLVERR = 2'b10;

    // Write channel FSM states
    localparam logic [1:0] W_IDLE = 2'd0;
    localparam logic [1:0] W_DATA = 2'd1;
    localparam logic [1:0] W_RESP = 2'd2;

    // Read channel FSM states
    localparam logic [1:0] R_IDLE = 2'd0;
    localparam logic [1:0] R_DATA = 2'd1;

    // -------------------------------------------------------------------------
    // Internal state
    // -------------------------------------------------------------------------
    logic [1:0]            wstate;
    logic [1:0]            rstate;
    logic [11:0]           waddr;
    logic [11:0]           raddr;
    logic                  done_reg;
    logic                  full_write;

    assign full_write = &wstrb_i;

    // -------------------------------------------------------------------------
    // Done status tracking
    //   - set by the hardware done_i
    //   - cleared by an AXI write of 1 to the DONE register
    // -------------------------------------------------------------------------
    logic done_clear;

    // -------------------------------------------------------------------------
    // Write channel
    // -------------------------------------------------------------------------
    always_ff @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            wstate       <= W_IDLE;
            waddr        <= 12'd0;
            awready_o    <= 1'b0;
            wready_o     <= 1'b0;
            bvalid_o     <= 1'b0;
            bresp_o      <= RESP_OKAY;
            beat_o       <= 20'd0;
            start_o      <= 1'b0;
            writeback_o  <= 1'b0;
            done_clear   <= 1'b0;
        end else begin
            done_clear <= 1'b0;
            case (wstate)
                W_IDLE: begin
                    awready_o <= 1'b1;
                    wready_o  <= 1'b0;
                    bvalid_o  <= 1'b0;
                    if (awvalid_i && awready_o) begin
                        waddr     <= awaddr_i[11:0];
                        awready_o <= 1'b0;
                        wready_o  <= 1'b1;
                        wstate    <= W_DATA;
                    end
                end

                W_DATA: begin
                    if (wvalid_i && wready_o) begin
                        wready_o <= 1'b0;
                        bvalid_o <= 1'b1;
                        bresp_o  <= RESP_OKAY;

                        // Only a full (all byte-strobes set) write modifies a register.
                        if (full_write) begin
                            case (waddr)
                                BEAT_OFFSET: begin
                                    beat_o <= wdata_i[19:0];
                                end
                                START_OFFSET: begin
                                    start_o <= wdata_i[0];
                                end
                                DONE_OFFSET: begin
                                    if (wdata_i[0])
                                        done_clear <= 1'b1;
                                end
                                WRITEBACK_OFFSET: begin
                                    writeback_o <= wdata_i[0];
                                end
                                ID_OFFSET: begin
                                    // read-only register -> error
                                    bresp_o <= RESP_SLVERR;
                                end
                                default: begin
                                    // invalid address -> error
                                    bresp_o <= RESP_SLVERR;
                                end
                            endcase
                        end else begin
                            // Partial write: acknowledge, do not modify register.
                            // Still flag error for read-only / invalid addresses.
                            case (waddr)
                                BEAT_OFFSET,
                                START_OFFSET,
                                DONE_OFFSET,
                                WRITEBACK_OFFSET: bresp_o <= RESP_OKAY;
                                ID_OFFSET:        bresp_o <= RESP_SLVERR;
                                default:          bresp_o <= RESP_SLVERR;
                            endcase
                        end
                        wstate <= W_RESP;
                    end
                end

                W_RESP: begin
                    if (bready_i && bvalid_o) begin
                        bvalid_o  <= 1'b0;
                        awready_o <= 1'b1;
                        wstate    <= W_IDLE;
                    end
                end

                default: wstate <= W_IDLE;
            endcase
        end
    end

    // Done status register
    always_ff @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            done_reg <= 1'b0;
        end else begin
            if (done_clear)
                done_reg <= 1'b0;
            else if (done_i)
                done_reg <= 1'b1;
        end
    end

    // -------------------------------------------------------------------------
    // Read channel
    // -------------------------------------------------------------------------
    always_ff @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            rstate    <= R_IDLE;
            raddr     <= 12'd0;
            arready_o <= 1'b0;
            rvalid_o  <= 1'b0;
            rresp_o   <= RESP_OKAY;
            rdata_o   <= {DATA_WIDTH{1'b0}};
        end else begin
            case (rstate)
                R_IDLE: begin
                    arready_o <= 1'b1;
                    rvalid_o  <= 1'b0;
                    if (arvalid_i && arready_o) begin
                        raddr     <= araddr_i[11:0];
                        arready_o <= 1'b0;
                        rvalid_o  <= 1'b1;
                        rresp_o   <= RESP_OKAY;
                        case (araddr_i[11:0])
                            BEAT_OFFSET: begin
                                rdata_o <= {{(DATA_WIDTH-20){1'b0}}, beat_o};
                                rresp_o <= RESP_OKAY;
                            end
                            START_OFFSET: begin
                                rdata_o <= {{(DATA_WIDTH-1){1'b0}}, start_o};
                                rresp_o <= RESP_OKAY;
                            end
                            DONE_OFFSET: begin
                                rdata_o <= {{(DATA_WIDTH-1){1'b0}}, done_reg};
                                rresp_o <= RESP_OKAY;
                            end
                            WRITEBACK_OFFSET: begin
                                rdata_o <= {{(DATA_WIDTH-1){1'b0}}, writeback_o};
                                rresp_o <= RESP_OKAY;
                            end
                            ID_OFFSET: begin
                                rdata_o <= ID_VALUE;
                                rresp_o <= RESP_OKAY;
                            end
                            default: begin
                                rdata_o <= {DATA_WIDTH{1'b0}};
                                rresp_o <= RESP_SLVERR;
                            end
                        endcase
                        rstate <= R_DATA;
                    end
                end

                R_DATA: begin
                    if (rready_i && rvalid_o) begin
                        rvalid_o  <= 1'b0;
                        arready_o <= 1'b1;
                        rstate    <= R_IDLE;
                    end
                end

                default: rstate <= R_IDLE;
            endcase
        end
    end

endmodule


