module axis_resize (

  input                                           clk,          //Global clock signal: Signals are sampled on the rising edge of clk
  input                                           resetn,       //The global reset signal: resetn is synchronous active-LOW reset.

  input                                           s_valid,      //The s_axis_valid signal indicates that the slave is driving a valid transfer.
  output  reg                                     s_ready,      //The s_axis_ready indicates that the slave can accept a transfer in the current cycle.
  input       [15:0]  s_data,                                   //The s_axis_data is the primary payload data from slave.

  output  reg                                     m_valid,      //The m_axis_valid indicates that the master is driving a valid transfer.
  input                                           m_ready,      //The m_axis_ready indicates that the slave can accept a transfer in the current cycle.
  output  reg [7:0] m_data                                      //The m_axis_data is the primary payload data to master.
);

  // Split one 16-bit slave beat into two 8-bit master beats.
  // AXI-Stream byte-lane convention: byte lane 0 (low byte) is sent first.

  localparam ACCEPT    = 2'd0;   // ready to accept a new 16-bit word
  localparam SEND_LOW  = 2'd1;   // driving low  byte s_data[7:0]
  localparam SEND_HIGH = 2'd2;   // driving high byte s_data[15:8]

  reg [1:0]  state;
  reg [15:0] data_reg;           // captured 16-bit slave payload

  always @(posedge clk) begin
    if (!resetn) begin
      state    <= ACCEPT;
      s_ready  <= 1'b0;
      m_valid  <= 1'b0;
      m_data   <= 8'b0;
      data_reg <= 16'b0;
    end
    else begin
      case (state)
        ACCEPT: begin
          m_valid <= 1'b0;
          if (s_valid && s_ready) begin
            // Accept the wide word; present low byte next cycle.
            data_reg <= s_data;
            m_data   <= s_data[7:0];
            m_valid  <= 1'b1;
            s_ready  <= 1'b0;         // stop accepting while draining
            state    <= SEND_LOW;
          end
          else begin
            s_ready <= 1'b1;          // advertise readiness to accept
          end
        end

        SEND_LOW: begin
          // Low byte is being offered; wait for master to consume it.
          if (m_valid && m_ready) begin
            m_data  <= data_reg[15:8];
            m_valid <= 1'b1;
            state   <= SEND_HIGH;
          end
        end

        SEND_HIGH: begin
          // High byte is being offered; wait for master to consume it.
          if (m_valid && m_ready) begin
            m_valid <= 1'b0;
            s_ready <= 1'b1;          // ready to accept the next word
            state   <= ACCEPT;
          end
        end

        default: begin
          state   <= ACCEPT;
          m_valid <= 1'b0;
          s_ready <= 1'b0;
        end
      endcase
    end
  end

endmodule


