//==============================================================================
// axis_upscale
//------------------------------------------------------------------------------
// AXI-Stream data upsizer: upscales single-channel input data from 24 bits to
// 32 bits with data-format control (sign extension / MSB carry-forward), while
// maintaining a single pipeline register stage.
//==============================================================================
module axis_upscale (
    input  wire        clk,           // Global clock
    input  wire        resetn,        // Active-low synchronous reset

    input  wire        dfmt_enable,   // Data format enable
    input  wire        dfmt_type,     // Data format type (1: invert MSB carry)
    input  wire        dfmt_se,        // Data format sign extension

    input  wire        s_axis_valid,  // Slave driving a valid transfer
    input  wire [23:0] s_axis_data,   // Slave payload data
    input  wire        m_axis_ready,  // Master can accept a transfer

    output wire        s_axis_ready,  // Slave can accept a transfer
    output reg         m_axis_valid,  // Master driving a valid transfer
    output reg  [31:0] m_axis_data    // Master payload data
);

    // Ready flows straight through the single register stage.
    assign s_axis_ready = m_axis_ready;

    // ---------------------------------------------------------------------
    // Data-format upscale (combinational next value)
    //   bit [23]    : slave MSB carry-forward, optionally inverted
    //   bits [22:0] : lower payload passthrough
    //   bits [31:24]: sign extension of bit 23 (or zero)
    //   dfmt_enable=0 : plain zero-extension of the 24-bit payload
    // ---------------------------------------------------------------------
    wire        msb_carry = dfmt_type ? ~s_axis_data[23] : s_axis_data[23];
    wire        ext_bit   = dfmt_se   ?  s_axis_data[23] : 1'b0;

    wire [31:0] data_fmt  = dfmt_enable ?
                              { {8{ext_bit}}, msb_carry, s_axis_data[22:0] } :
                              { 8'b0, s_axis_data };

    // ---------------------------------------------------------------------
    // Single pipeline register stage (synchronous active-low reset)
    // ---------------------------------------------------------------------
    always @(posedge clk) begin
        if (resetn == 1'b0) begin
            m_axis_valid <= 1'b0;
            m_axis_data  <= 32'b0;
        end else if (m_axis_ready) begin
            m_axis_valid <= s_axis_valid;
            m_axis_data  <= data_fmt;
        end
    end

endmodule


