wire read_accept_w       = (read_port_q == read_port_r && read_pending_q != 4'hF) || (read_pending_q == 4'h0);

assign outport_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd0);
assign outport_araddr_o  = inport_araddr_i;
assign outport_rready_o  = inport_rready_i;

assign outport_peripheral0_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_araddr_o  = inport_araddr_i;
assign outport_peripheral0_rready_o  = inport_rready_i;

// AXI Read channel: mux the read-data response from the port that the
// outstanding reads were routed to (read_port_q).
reg                  inport_rvalid_r;
reg [DATA_WIDTH-1:0] inport_rdata_r;
reg [1:0]            inport_rresp_r;

always @ *
begin
    case (read_port_q)
    `ADDR_SEL_W'd1:
    begin
        inport_rvalid_r = outport_peripheral0_rvalid_i;
        inport_rdata_r  = outport_peripheral0_rdata_i;
        inport_rresp_r  = outport_peripheral0_rresp_i;
    end
    default:
    begin
        inport_rvalid_r = outport_rvalid_i;
        inport_rdata_r  = outport_rdata_i;
        inport_rresp_r  = outport_rresp_i;
