module axi_tap #(
    parameter ADDR_WIDTH    = 32, // Width of AXI4-Lite Address
    parameter DATA_WIDTH    = 32, // Width of AXI4-Lite Data
    parameter TIMEOUT_WIDTH = 32  // Width of the timeout timer / threshold
)(
    // Global Ports
    input           clk_i,
    input           rst_i,

    // Master Write Address Channel (AW)
    input           inport_awvalid_i,
    input  [ADDR_WIDTH-1:0]   inport_awaddr_i,
    output          inport_awready_o,
    // Master Write Data Channel (W)
    input           inport_wvalid_i,
    input  [DATA_WIDTH-1:0]   inport_wdata_i,
    input  [3:0]    inport_wstrb_i,
    output          inport_wready_o,
    // Master Write Response Channel (B)
    input           inport_bready_i,
    output          inport_bvalid_o,
    output [1:0]    inport_bresp_o,
    // Master Read Address Channel (AR)
    input           inport_arvalid_i,
    input  [ADDR_WIDTH-1:0]   inport_araddr_i,
    output          inport_arready_o,
    // Master Read Data Channel (R)
    input           inport_rready_i,
    output          inport_rvalid_o,
    output [DATA_WIDTH-1:0]   inport_rdata_o,
    output [1:0]    inport_rresp_o,

    // Default AXI outport
    // Write Address Channel (AW)
    input           outport_awready_i,
    output          outport_awvalid_o,
    output [ADDR_WIDTH-1:0]   outport_awaddr_o,
    // Write Data Channel (W)
    input           outport_wready_i,
    output          outport_wvalid_o,
    output [DATA_WIDTH-1:0]   outport_wdata_o,
    output [3:0]    outport_wstrb_o,
    // Write Response Channel (B)
    input           outport_bvalid_i,
    input  [1:0]    outport_bresp_i,
    output          outport_bready_o,
    // Read Address Channel (AR)
    input           outport_arready_i,
    output          outport_arvalid_o,
    output [ADDR_WIDTH-1:0]   outport_araddr_o,
    // Read Data Channel (R)
    input           outport_rvalid_i,
    input  [DATA_WIDTH-1:0]   outport_rdata_i,
    input  [1:0]    outport_rresp_i,
    output          outport_rready_o,

    // Peripheral 0 interface
    // Write Address Channel (AW)
    input           outport_peripheral0_awready_i,
    output          outport_peripheral0_awvalid_o,
    output [ADDR_WIDTH-1:0]   outport_peripheral0_awaddr_o,
    // Write Data Channel (W)
    input           outport_peripheral0_wready_i,
    output          outport_peripheral0_wvalid_o,
    output [DATA_WIDTH-1:0]   outport_peripheral0_wdata_o,
    output [3:0]    outport_peripheral0_wstrb_o,
    // Write Response Channel (B)
    input  [1:0]    outport_peripheral0_bresp_i,
    input           outport_peripheral0_bvalid_i,
    output          outport_peripheral0_bready_o,
    // Read Address Channel (AR)
    input           outport_peripheral0_arready_i,
    output          outport_peripheral0_arvalid_o,
    output [ADDR_WIDTH-1:0]   outport_peripheral0_araddr_o,
    // Read Data Channel (R)
    input  [1:0]    outport_peripheral0_rresp_i,
    input           outport_peripheral0_rvalid_i,
    input  [DATA_WIDTH-1:0]   outport_peripheral0_rdata_i,
    output          outport_peripheral0_rready_o,

    // Transaction timeout detection
    input  [TIMEOUT_WIDTH-1:0] TIMEOUT_THRESHOLD, // Allowed transaction duration (cycles)
    output          timeout_flag                  // Asserted when a transaction times out
);

`define ADDR_SEL_W           1
`define PERIPH0_ADDR         32'h80000000
`define PERIPH0_MASK         32'h80000000

//-----------------------------------------------------------------
// AXI: Read
//-----------------------------------------------------------------
reg [3:0]              read_pending_q;
reg [3:0]              read_pending_r;
reg [`ADDR_SEL_W-1:0]  read_port_q;
reg [`ADDR_SEL_W-1:0]  read_port_r;

always @ *
begin
    read_port_r = `ADDR_SEL_W'b0;
    if ((inport_araddr_i & `PERIPH0_MASK) == `PERIPH0_ADDR) read_port_r = `ADDR_SEL_W'd1;
end

wire read_incr_w = (inport_arvalid_i && inport_arready_o);
wire read_decr_w = (inport_rvalid_o && inport_rready_i);

always @ *
begin
    read_pending_r = read_pending_q;

    if (read_incr_w && !read_decr_w)
        read_pending_r = read_pending_r + 4'd1;
    else if (!read_incr_w && read_decr_w)
        read_pending_r = read_pending_r - 4'd1;
end

always @ (posedge clk_i )
if (rst_i)
begin
    read_pending_q <= 4'b0;
    read_port_q    <= `ADDR_SEL_W'b0;
end
else
begin
    read_pending_q <= read_pending_r;

    // Read command accepted
    if (inport_arvalid_i && inport_arready_o)
    begin
        read_port_q <= read_port_r;
    end
end

wire read_accept_w       = (read_port_q == read_port_r && read_pending_q != 4'hF) || (read_pending_q == 4'h0);

assign outport_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd0);
assign outport_araddr_o  = inport_araddr_i;
assign outport_rready_o  = inport_rready_i;

assign outport_peripheral0_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_araddr_o  = inport_araddr_i;
assign outport_peripheral0_rready_o  = inport_rready_i;

reg        outport_rvalid_r;
reg [DATA_WIDTH-1:0] outport_rdata_r;
reg [1:0]  outport_rresp_r;

always @ *
begin
    case (read_port_q)
    `ADDR_SEL_W'd1:
    begin
        outport_rvalid_r = outport_peripheral0_rvalid_i;
        outport_rdata_r  = outport_peripheral0_rdata_i;
        outport_rresp_r  = outport_peripheral0_rresp_i;
    end
    default:
    begin
        outport_rvalid_r = outport_rvalid_i;
        outport_rdata_r  = outport_rdata_i;
        outport_rresp_r  = outport_rresp_i;
    end
    endcase
end

assign inport_rvalid_o  = outport_rvalid_r;
assign inport_rdata_o   = outport_rdata_r;
assign inport_rresp_o   = outport_rresp_r;

reg inport_arready_r;
always @ *
begin
    case (read_port_r)
    `ADDR_SEL_W'd1:
        inport_arready_r = outport_peripheral0_arready_i;
    default:
        inport_arready_r = outport_arready_i;
    endcase
end

assign inport_arready_o = read_accept_w & inport_arready_r;

//-------------------------------------------------------------
// Write Request
//-------------------------------------------------------------
reg awvalid_q;
reg wvalid_q;

wire wr_cmd_accepted_w  = (inport_awvalid_i && inport_awready_o) || awvalid_q;
wire wr_data_accepted_w = (inport_wvalid_i  && inport_wready_o)  || wvalid_q;

always @ (posedge clk_i )
if (rst_i)
    awvalid_q <= 1'b0;
else if (inport_awvalid_i && inport_awready_o && (!wr_data_accepted_w))
    awvalid_q <= 1'b1;
else if (wr_data_accepted_w)
    awvalid_q <= 1'b0;

always @ (posedge clk_i )
if (rst_i)
    wvalid_q <= 1'b0;
else if (inport_wvalid_i && inport_wready_o && !wr_cmd_accepted_w)
    wvalid_q <= 1'b1;
else if (wr_cmd_accepted_w)
    wvalid_q <= 1'b0;

//-----------------------------------------------------------------
// AXI: Write
//-----------------------------------------------------------------
reg [3:0]              write_pending_q;
reg [3:0]              write_pending_r;
reg [`ADDR_SEL_W-1:0]  write_port_q;
reg [`ADDR_SEL_W-1:0]  write_port_r;

always @ *
begin
    if (inport_awvalid_i & ~awvalid_q)
    begin
        write_port_r = `ADDR_SEL_W'b0;
        if ((inport_awaddr_i & `PERIPH0_MASK) == `PERIPH0_ADDR) write_port_r = `ADDR_SEL_W'd1;
    end
    else
        write_port_r = write_port_q;
end

wire write_incr_w = (inport_awvalid_i && inport_awready_o);
wire write_decr_w = (inport_bvalid_o  && inport_bready_i);

always @ *
begin
    write_pending_r = write_pending_q;

    if (write_incr_w && !write_decr_w)
        write_pending_r = write_pending_r + 4'd1;
    else if (!write_incr_w && write_decr_w)
        write_pending_r = write_pending_r - 4'd1;
end

always @ (posedge clk_i )
if (rst_i)
begin
    write_pending_q <= 4'b0;
    write_port_q    <= `ADDR_SEL_W'b0;
end
else
begin
    write_pending_q <= write_pending_r;

    // Write command accepted
    if (inport_awvalid_i && inport_awready_o)
    begin
        write_port_q <= write_port_r;
    end
end

wire write_accept_w      = (write_port_q == write_port_r && write_pending_q != 4'hF) || (write_pending_q == 4'h0);

assign outport_awvalid_o = inport_awvalid_i & ~awvalid_q & write_accept_w & (write_port_r == `ADDR_SEL_W'd0);
assign outport_awaddr_o  = inport_awaddr_i;
assign outport_wvalid_o  = inport_wvalid_i & ~wvalid_q & (inport_awvalid_i || awvalid_q) & (write_port_r == `ADDR_SEL_W'd0);
assign outport_wdata_o   = inport_wdata_i;
assign outport_wstrb_o   = inport_wstrb_i;
assign outport_bready_o  = inport_bready_i;

assign outport_peripheral0_awvalid_o = inport_awvalid_i & ~awvalid_q & write_accept_w & (write_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_awaddr_o  = inport_awaddr_i;
assign outport_peripheral0_wvalid_o  = inport_wvalid_i & ~wvalid_q & ((inport_awvalid_i && write_accept_w) || awvalid_q) & (write_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_wdata_o   = inport_wdata_i;
assign outport_peripheral0_wstrb_o   = inport_wstrb_i;
assign outport_peripheral0_bready_o  = inport_bready_i;

reg        outport_bvalid_r;
reg [1:0]  outport_bresp_r;

always @ *
begin
    case (write_port_q)
    `ADDR_SEL_W'd1:
    begin
        outport_bvalid_r = outport_peripheral0_bvalid_i;
        outport_bresp_r  = outport_peripheral0_bresp_i;
    end
    default:
    begin
        outport_bvalid_r = outport_bvalid_i;
        outport_bresp_r  = outport_bresp_i;
    end
    endcase
end

assign inport_bvalid_o  = outport_bvalid_r;
assign inport_bresp_o   = outport_bresp_r;

reg inport_awready_r;
reg inport_wready_r;

always @ *
begin
    case (write_port_r)
    `ADDR_SEL_W'd1:
    begin
        inport_awready_r = outport_peripheral0_awready_i;
        inport_wready_r  = outport_peripheral0_wready_i;
    end
    default:
    begin
        inport_awready_r = outport_awready_i;
        inport_wready_r  = outport_wready_i;
    end
    endcase
end

assign inport_awready_o = write_accept_w & ~awvalid_q & inport_awready_r;
assign inport_wready_o  = write_accept_w & ~wvalid_q & inport_wready_r;

//-----------------------------------------------------------------
// Transaction Timeout Detection
//
// Per the specification a transaction begins when the address channel
// `valid` is asserted and completes when the response handshake fires
// (R for reads, B for writes).  A per-direction timer counts the number
// of cycles a transaction is outstanding; if the timer reaches the
// run-time-configurable TIMEOUT_THRESHOLD before the transaction
// completes, the sticky `timeout_flag` is asserted and remains high
// until reset.
//-----------------------------------------------------------------

// Spec-named transaction-begin indicator: a transaction starts when a
// read (AR) or write (AW) address-channel `valid` is asserted.
wire valid = inport_arvalid_i | inport_awvalid_i;

// A direction is "in flight" while a request is outstanding, i.e. from
// the cycle its address `valid` is asserted until its response completes.
wire read_active  = (read_pending_q  != 4'd0) || (valid & inport_arvalid_i);
wire write_active = (write_pending_q != 4'd0) || (valid & inport_awvalid_i);

// Response-handshake completion for each direction.
wire read_complete_w  = read_decr_w;   // inport_rvalid_o && inport_rready_i
wire write_complete_w = write_decr_w;   // inport_bvalid_o && inport_bready_i

reg [TIMEOUT_WIDTH-1:0] read_timeout_counter;
reg [TIMEOUT_WIDTH-1:0] write_timeout_counter;
reg                     timeout_flag_q;

// Read transaction timer
always @ (posedge clk_i)
if (rst_i)
    read_timeout_counter <= {TIMEOUT_WIDTH{1'b0}};
else if (read_complete_w || !read_active)
    read_timeout_counter <= {TIMEOUT_WIDTH{1'b0}};
else
    read_timeout_counter <= read_timeout_counter + {{(TIMEOUT_WIDTH-1){1'b0}}, 1'b1};

// Write transaction timer
always @ (posedge clk_i)
if (rst_i)
    write_timeout_counter <= {TIMEOUT_WIDTH{1'b0}};
else if (write_complete_w || !write_active)
    write_timeout_counter <= {TIMEOUT_WIDTH{1'b0}};
else
    write_timeout_counter <= write_timeout_counter + {{(TIMEOUT_WIDTH-1){1'b0}}, 1'b1};

// Compare the NEXT counter value against the threshold to avoid an
// off-by-one late detection.
wire read_timeout_w  = read_active  &&
                       ((read_timeout_counter  + {{(TIMEOUT_WIDTH-1){1'b0}}, 1'b1}) >= TIMEOUT_THRESHOLD);
wire write_timeout_w = write_active &&
                       ((write_timeout_counter + {{(TIMEOUT_WIDTH-1){1'b0}}, 1'b1}) >= TIMEOUT_THRESHOLD);

// Sticky timeout flag: latched on any timeout, held until reset.
always @ (posedge clk_i)
if (rst_i)
    timeout_flag_q <= 1'b0;
else if (read_timeout_w || write_timeout_w)
    timeout_flag_q <= 1'b1;

assign timeout_flag = timeout_flag_q;

endmodule

module precision_counter_axi #(
    parameter integer C_S_AXI_DATA_WIDTH = 32,
    parameter integer C_S_AXI_ADDR_WIDTH = 8
) (
    input  wire                              axi_aclk,
    input  wire                              axi_aresetn,

    // Write address channel
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]     axi_awaddr,
    input  wire                              axi_awvalid,
    output reg                               axi_awready,

    // Write data channel
    input  wire [C_S_AXI_DATA_WIDTH-1:0]     axi_wdata,
    input  wire [(C_S_AXI_DATA_WIDTH/8)-1:0] axi_wstrb,
    input  wire                              axi_wvalid,
    output reg                               axi_wready,

    // Write response channel
    output reg  [1:0]                        axi_bresp,
    output reg                               axi_bvalid,
    input  wire                              axi_bready,

    // Read address channel
    input  wire [C_S_AXI_ADDR_WIDTH-1:0]     axi_araddr,
    input  wire                              axi_arvalid,
    output reg                               axi_arready,

    // Read data channel
    output reg  [C_S_AXI_DATA_WIDTH-1:0]     axi_rdata,
    output reg  [1:0]                        axi_rresp,
    output reg                               axi_rvalid,
    input  wire                              axi_rready,

    // Control outputs
    output wire                              axi_ap_done,
    output wire                              irq
);

    // ------------------------------------------------------------------
    // Register offsets
    // ------------------------------------------------------------------
    localparam [7:0] ADDR_CTL        = 8'h00; // start/stop
    localparam [7:0] ADDR_APDONE     = 8'h0C; // ap_done status (read only)
    localparam [7:0] ADDR_T          = 8'h10; // elapsed time
    localparam [7:0] ADDR_V          = 8'h20; // countdown value
    localparam [7:0] ADDR_IRQ_MASK   = 8'h24; // irq mask
    localparam [7:0] ADDR_IRQ_THRESH = 8'h28; // irq threshold

    // Software-visible registers
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_ctl;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_t;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_v;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_irq_mask;
    reg [C_S_AXI_DATA_WIDTH-1:0] slv_reg_irq_thresh;

    // Internal AXI bookkeeping
    reg [C_S_AXI_ADDR_WIDTH-1:0] awaddr_q;
    reg [C_S_AXI_ADDR_WIDTH-1:0] araddr_q;
    reg                          aw_en;

    integer bi;

    wire slv_reg_wren = axi_awready & axi_awvalid & axi_wready & axi_wvalid;
    wire slv_reg_rden = axi_arready & axi_arvalid & ~axi_rvalid;

    // Address validity for response generation
    wire aw_addr_ok = (awaddr_q == ADDR_CTL)      ||
                      (awaddr_q == ADDR_T)        ||
                      (awaddr_q == ADDR_V)        ||
                      (awaddr_q == ADDR_IRQ_MASK) ||
                      (awaddr_q == ADDR_IRQ_THRESH);

    wire ar_addr_ok = (araddr_q == ADDR_CTL)      ||
                      (araddr_q == ADDR_APDONE)   ||
                      (araddr_q == ADDR_T)        ||
                      (araddr_q == ADDR_V)        ||
                      (araddr_q == ADDR_IRQ_MASK) ||
                      (araddr_q == ADDR_IRQ_THRESH);

    // ------------------------------------------------------------------
    // Write address handshake + aw_en
    // ------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_awready <= 1'b0;
            aw_en       <= 1'b1;
            awaddr_q    <= {C_S_AXI_ADDR_WIDTH{1'b0}};
        end else begin
            if (~axi_awready && axi_awvalid && axi_wvalid && aw_en) begin
                axi_awready <= 1'b1;
                aw_en       <= 1'b0;
                awaddr_q    <= axi_awaddr;
            end else if (axi_bready && axi_bvalid) begin
                axi_awready <= 1'b0;
                aw_en       <= 1'b1;
            end else begin
                axi_awready <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Write data handshake
    // ------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_wready <= 1'b0;
        end else begin
            if (~axi_wready && axi_wvalid && axi_awvalid && aw_en)
                axi_wready <= 1'b1;
            else
                axi_wready <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // Write response
    // ------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_bvalid <= 1'b0;
            axi_bresp  <= 2'b00;
        end else begin
            if (axi_awready && axi_awvalid && ~axi_bvalid && axi_wready && axi_wvalid) begin
                axi_bvalid <= 1'b1;
                axi_bresp  <= aw_addr_ok ? 2'b00 : 2'b10;
            end else if (axi_bready && axi_bvalid) begin
                axi_bvalid <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Registers + countdown / elapsed-time logic
    // ------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            slv_reg_ctl        <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_t          <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_v          <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_irq_mask   <= {C_S_AXI_DATA_WIDTH{1'b0}};
            slv_reg_irq_thresh <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else begin
            // ---- countdown value ----
            if (slv_reg_wren && (awaddr_q == ADDR_V)) begin
                for (bi = 0; bi < (C_S_AXI_DATA_WIDTH/8); bi = bi + 1)
                    if (axi_wstrb[bi])
                        slv_reg_v[bi*8 +: 8] <= axi_wdata[bi*8 +: 8];
            end else if (slv_reg_ctl[0] && (slv_reg_v != {C_S_AXI_DATA_WIDTH{1'b0}})) begin
                slv_reg_v <= slv_reg_v - 1'b1;
            end

            // ---- elapsed time ----
            if (slv_reg_wren && (awaddr_q == ADDR_CTL)) begin
                slv_reg_t <= {C_S_AXI_DATA_WIDTH{1'b0}};
            end else if (slv_reg_wren && (awaddr_q == ADDR_T)) begin
                for (bi = 0; bi < (C_S_AXI_DATA_WIDTH/8); bi = bi + 1)
                    if (axi_wstrb[bi])
                        slv_reg_t[bi*8 +: 8] <= axi_wdata[bi*8 +: 8];
            end else if (slv_reg_v == {C_S_AXI_DATA_WIDTH{1'b0}}) begin
                slv_reg_t <= slv_reg_t + 1'b1;
            end

            // ---- control ----
            if (slv_reg_wren && (awaddr_q == ADDR_CTL)) begin
                for (bi = 0; bi < (C_S_AXI_DATA_WIDTH/8); bi = bi + 1)
                    if (axi_wstrb[bi])
                        slv_reg_ctl[bi*8 +: 8] <= axi_wdata[bi*8 +: 8];
            end

            // ---- irq mask ----
            if (slv_reg_wren && (awaddr_q == ADDR_IRQ_MASK)) begin
                for (bi = 0; bi < (C_S_AXI_DATA_WIDTH/8); bi = bi + 1)
                    if (axi_wstrb[bi])
                        slv_reg_irq_mask[bi*8 +: 8] <= axi_wdata[bi*8 +: 8];
            end

            // ---- irq threshold ----
            if (slv_reg_wren && (awaddr_q == ADDR_IRQ_THRESH)) begin
                for (bi = 0; bi < (C_S_AXI_DATA_WIDTH/8); bi = bi + 1)
                    if (axi_wstrb[bi])
                        slv_reg_irq_thresh[bi*8 +: 8] <= axi_wdata[bi*8 +: 8];
            end
        end
    end

    // ------------------------------------------------------------------
    // Read address handshake
    // ------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_arready <= 1'b0;
            araddr_q    <= {C_S_AXI_ADDR_WIDTH{1'b0}};
        end else begin
            if (~axi_arready && axi_arvalid) begin
                axi_arready <= 1'b1;
                araddr_q    <= axi_araddr;
            end else begin
                axi_arready <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Read response + data
    // ------------------------------------------------------------------
    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_rvalid <= 1'b0;
            axi_rresp  <= 2'b00;
        end else begin
            if (axi_arready && axi_arvalid && ~axi_rvalid) begin
                axi_rvalid <= 1'b1;
                axi_rresp  <= ar_addr_ok ? 2'b00 : 2'b10;
            end else if (axi_rvalid && axi_rready) begin
                axi_rvalid <= 1'b0;
            end
        end
    end

    always @(posedge axi_aclk or negedge axi_aresetn) begin
        if (!axi_aresetn) begin
            axi_rdata <= {C_S_AXI_DATA_WIDTH{1'b0}};
        end else if (slv_reg_rden) begin
            case (araddr_q)
                ADDR_CTL:        axi_rdata <= slv_reg_ctl;
                ADDR_APDONE:     axi_rdata <= {{(C_S_AXI_DATA_WIDTH-1){1'b0}}, axi_ap_done};
                ADDR_T:          axi_rdata <= slv_reg_t;
                ADDR_V:          axi_rdata <= slv_reg_v;
                ADDR_IRQ_MASK:   axi_rdata <= slv_reg_irq_mask;
                ADDR_IRQ_THRESH: axi_rdata <= slv_reg_irq_thresh;
                default:         axi_rdata <= {C_S_AXI_DATA_WIDTH{1'b0}};
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Status / interrupt outputs
    // ------------------------------------------------------------------
    assign axi_ap_done = (slv_reg_v == {C_S_AXI_DATA_WIDTH{1'b0}});

    assign irq = slv_reg_ctl[0] &&
                 slv_reg_irq_mask[0] &&
                 (slv_reg_v == slv_reg_irq_thresh);

endmodule

`timescale 1ps / 1ps

module axis_image_border_gen #(
    parameter IMG_WIDTH  = 336,               // Image width (X resolution)
    parameter IMG_HEIGHT = 256,               // Image height (Y resolution)
    parameter BORDER_COLOR = 16'hFFFF,        // Border pixel value
    parameter DATA_MASK    = 16'h0000         // Mask for input pixels
)(
    input  wire            clk,               // AXI clock
    input  wire            resetn,            // Active-low reset

    // AXI Stream input interface
    input  wire [15:0]     s_axis_tdata,      // Input stream data
    input  wire            s_axis_tvalid,     // Input data valid
    output wire            s_axis_tready,     // Output ready
    input  wire            s_axis_tlast,      // Input last signal
    input  wire            s_axis_tuser,      // Frame start signal

    // AXI Stream output interface
    output wire [15:0]     m_axis_tdata,      // Output stream data
    output wire            m_axis_tvalid,     // Output data valid
    input  wire            m_axis_tready,     // Input ready
    output wire            m_axis_tlast,      // Output last signal
    output wire            m_axis_tuser       // Frame start signal
);

    // State definitions
    localparam [2:0] ST_IDLE        = 3'd0;   // Wait for a new frame start (tuser)
    localparam [2:0] ST_ROW_FIRST   = 3'd1;   // Top border row
    localparam [2:0] ST_PROCESS_ROW = 3'd2;   // Middle rows (left/right border + data)
    localparam [2:0] ST_BORDER_ROW  = 3'd3;   // Bottom border row
    localparam [2:0] ST_ROW_LAST    = 3'd4;   // Complete, return to idle

    // State and Counter Registers
    reg [2:0]  state, next_state;
    reg [15:0] x_count, y_count;
    reg        border_valid;

    // Internal Control Signals (output-coordinate space, (IMG_WIDTH+2) x (IMG_HEIGHT+2))
    wire is_top_row      = (y_count == 16'd0);
    wire is_bottom_row   = (y_count == IMG_HEIGHT + 1);
    wire is_left_border  = (x_count == 16'd0);
    wire is_right_border = (x_count == IMG_WIDTH + 1);
    wire is_border_pixel = (is_top_row || is_bottom_row || is_left_border || is_right_border);

    // The module is producing an output pixel in these states
    wire producing = (state == ST_ROW_FIRST) ||
                     (state == ST_PROCESS_ROW) ||
                     (state == ST_BORDER_ROW);

    // An interior pixel (requires an input pixel) occurs only within the middle rows,
    // away from the left/right border columns.
    wire need_input = (state == ST_PROCESS_ROW) && !is_left_border && !is_right_border;

    // Last output column of a row
    wire row_end = (x_count == IMG_WIDTH + 1);

    // ---------------------------------------------------------------
    // AXI Stream protocol / output signals (combinational, wire outputs)
    // ---------------------------------------------------------------
    // tvalid never depends on m_axis_tready (AXI compliant). For interior
    // pixels output is valid only when input data is available; border
    // pixels are always available while producing.
    assign m_axis_tvalid = producing ? (need_input ? s_axis_tvalid : 1'b1) : 1'b0;

    // Only accept input during interior pixels, and only when downstream ready.
    assign s_axis_tready = need_input ? m_axis_tready : 1'b0;

    // Border pixels take BORDER_COLOR; interior pixels pass the (masked) input.
    assign m_axis_tdata  = is_border_pixel ? BORDER_COLOR : (s_axis_tdata | DATA_MASK);

    // End-of-line marker on the last output column while producing.
    assign m_axis_tlast  = producing & row_end;

    // Start-of-frame marker on the very first output pixel.
    assign m_axis_tuser  = (state == ST_ROW_FIRST) & is_left_border & is_top_row;

    // An output pixel transfer completes (advances the raster position).
    wire px_fire = m_axis_tvalid & m_axis_tready;

    // ---------------------------------------------------------------
    // Next-state / border-valid logic (combinational)
    // ---------------------------------------------------------------
    always @(*) begin
        next_state   = state;
        border_valid = is_border_pixel;
        case (state)
            ST_IDLE: begin
                // Wait for a frame start pixel; do NOT consume it here.
                if (s_axis_tvalid && s_axis_tuser)
                    next_state = ST_ROW_FIRST;
            end
            ST_ROW_FIRST: begin
                if (px_fire && row_end)
                    next_state = ST_PROCESS_ROW;
            end
            ST_PROCESS_ROW: begin
                if (px_fire && row_end && (y_count == IMG_HEIGHT))
                    next_state = ST_BORDER_ROW;
            end
            ST_BORDER_ROW: begin
                if (px_fire && row_end)
                    next_state = ST_ROW_LAST;
            end
            ST_ROW_LAST: begin
                next_state = ST_IDLE;
            end
            default: next_state = ST_IDLE;
        endcase
    end

    // ---------------------------------------------------------------
    // Sequential FSM + raster counters
    // ---------------------------------------------------------------
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state   <= ST_IDLE;
            x_count <= 16'd0;
            y_count <= 16'd0;
        end else begin
            state <= next_state;
            case (state)
                ST_IDLE: begin
                    x_count <= 16'd0;
                    y_count <= 16'd0;
                end
                ST_ROW_FIRST: begin
                    if (px_fire) begin
                        if (row_end) begin
                            x_count <= 16'd0;
                            y_count <= 16'd1;          // first middle row
                        end else begin
                            x_count <= x_count + 16'd1;
                        end
                    end
                end
                ST_PROCESS_ROW: begin
                    if (px_fire) begin
                        if (row_end) begin
                            x_count <= 16'd0;
                            y_count <= y_count + 16'd1; // next middle row / bottom border
                        end else begin
                            x_count <= x_count + 16'd1;
                        end
                    end
                end
                ST_BORDER_ROW: begin
                    if (px_fire) begin
                        if (row_end)
                            x_count <= 16'd0;
                        else
                            x_count <= x_count + 16'd1;
                    end
                end
                ST_ROW_LAST: begin
                    x_count <= 16'd0;
                    y_count <= 16'd0;
                end
                default: begin
                    x_count <= 16'd0;
                    y_count <= 16'd0;
                end
            endcase
        end
    end

endmodule


