// axis_joiner: merges three AXI Stream inputs into one AXI Stream output
// via a round-robin/priority FSM (STATE_IDLE, STATE_1, STATE_2, STATE_3)
// with a single-word skid buffer (temp) for lossless backpressure handling.
module axis_joiner (
    input  wire       clk,
    input  wire       rst,

    // AXI Stream input 1
    input  wire [7:0] s_axis_tdata_1,
    input  wire       s_axis_tvalid_1,
    output reg        s_axis_tready_1,
    input  wire       s_axis_tlast_1,

    // AXI Stream input 2
    input  wire [7:0] s_axis_tdata_2,
    input  wire       s_axis_tvalid_2,
    output reg        s_axis_tready_2,
    input  wire       s_axis_tlast_2,

    // AXI Stream input 3
    input  wire [7:0] s_axis_tdata_3,
    input  wire       s_axis_tvalid_3,
    output reg        s_axis_tready_3,
    input  wire       s_axis_tlast_3,

    // Merged AXI Stream output
    output reg  [7:0] m_axis_tdata,
    output reg        m_axis_tvalid,
    input  wire       m_axis_tready,
    output reg        m_axis_tlast,
    output reg  [1:0] m_axis_tuser,

    // Status
    output reg        busy
);

    // FSM state encoding
    localparam [1:0] STATE_IDLE = 2'd0,
                     STATE_1    = 2'd1,
                     STATE_2    = 2'd2,
                     STATE_3    = 2'd3;

    // Source identification tags for m_axis_tuser
    localparam [1:0] TAG_ID_1 = 2'h1,
                     TAG_ID_2 = 2'h2,
                     TAG_ID_3 = 2'h3;

    reg [1:0] state;

    // MUX outputs: selected stream's data/valid/last/user based on state
    reg [7:0] mux_tdata;
    reg       mux_tvalid;
    reg       mux_tlast;
    reg [1:0] mux_tuser;

    // Skid buffer for stalled output
    reg       temp;        // flag: buffered data is being held
    reg [7:0] temp_tdata;
    reg       temp_tlast;
    reg [1:0] temp_tuser;

    // ------------------------------------------------------------------
    // Input selection multiplexer (combinational)
    // ------------------------------------------------------------------
    always @(*) begin
        case (state)
            STATE_1: begin
                mux_tdata  = s_axis_tdata_1;
                mux_tvalid = s_axis_tvalid_1;
                mux_tlast  = s_axis_tlast_1;
                mux_tuser  = TAG_ID_1;
            end
            STATE_2: begin
                mux_tdata  = s_axis_tdata_2;
                mux_tvalid = s_axis_tvalid_2;
                mux_tlast  = s_axis_tlast_2;
                mux_tuser  = TAG_ID_2;
            end
            STATE_3: begin
                mux_tdata  = s_axis_tdata_3;
                mux_tvalid = s_axis_tvalid_3;
                mux_tlast  = s_axis_tlast_3;
                mux_tuser  = TAG_ID_3;
            end
            default: begin
                mux_tdata  = 8'd0;
                mux_tvalid = 1'b0;
                mux_tlast  = 1'b0;
                mux_tuser  = 2'd0;
            end
        endcase
    end

    // ------------------------------------------------------------------
    // tready generation: only the active stream is acknowledged, and only
    // when the output can accept new data (not currently holding a word).
    // ------------------------------------------------------------------
    always @(*) begin
        s_axis_tready_1 = 1'b0;
        s_axis_tready_2 = 1'b0;
        s_axis_tready_3 = 1'b0;
        if (!temp) begin
            case (state)
                STATE_1: s_axis_tready_1 = m_axis_tready;
                STATE_2: s_axis_tready_2 = m_axis_tready;
                STATE_3: s_axis_tready_3 = m_axis_tready;
                default: ;
            endcase
        end
    end

    // ------------------------------------------------------------------
    // busy indicator
    // ------------------------------------------------------------------
    always @(*) begin
        busy = (state != STATE_IDLE);
    end

    // ------------------------------------------------------------------
    // FSM + output register / skid buffer
    // ------------------------------------------------------------------
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state         <= STATE_IDLE;
            m_axis_tdata  <= 8'd0;
            m_axis_tvalid <= 1'b0;
            m_axis_tlast  <= 1'b0;
            m_axis_tuser  <= 2'd0;
            temp          <= 1'b0;
            temp_tdata    <= 8'd0;
            temp_tlast    <= 1'b0;
            temp_tuser    <= 2'd0;
        end else begin
            // Clear the output valid once the downstream consumes it,
            // unless we immediately refill (handled below).
            if (m_axis_tvalid && m_axis_tready) begin
                m_axis_tvalid <= 1'b0;
            end

            case (state)
                STATE_IDLE: begin
                    // Priority arbitration among the three inputs.
                    if (s_axis_tvalid_1)
                        state <= STATE_1;
                    else if (s_axis_tvalid_2)
                        state <= STATE_2;
                    else if (s_axis_tvalid_3)
                        state <= STATE_3;
                end

                STATE_1, STATE_2, STATE_3: begin
                    if (temp) begin
                        // We are holding a word; push it out when output is free.
                        if (!m_axis_tvalid || m_axis_tready) begin
                            m_axis_tdata  <= temp_tdata;
                            m_axis_tvalid <= 1'b1;
                            m_axis_tlast  <= temp_tlast;
                            m_axis_tuser  <= temp_tuser;
                            temp          <= 1'b0;
                            if (temp_tlast)
                                state <= STATE_IDLE;
                        end
                    end else if (mux_tvalid) begin
                        if (!m_axis_tvalid || m_axis_tready) begin
                            // Output free: forward directly.
                            m_axis_tdata  <= mux_tdata;
                            m_axis_tvalid <= 1'b1;
                            m_axis_tlast  <= mux_tlast;
                            m_axis_tuser  <= mux_tuser;
                            if (mux_tlast)
                                state <= STATE_IDLE;
                        end else begin
                            // Output busy: capture into skid buffer.
                            temp_tdata <= mux_tdata;
                            temp_tlast <= mux_tlast;
                            temp_tuser <= mux_tuser;
                            temp       <= 1'b1;
                        end
                    end
                end

                default: state <= STATE_IDLE;
            endcase
        end
    end

endmodule


