  output wire [C_AXIS_TID_WIDTH-1:0]              m_axis_tid,
  output wire [C_AXIS_TDEST_WIDTH-1:0]            m_axis_tdest,
  output wire [C_AXIS_TUSER_WIDTH-1:0]            m_axis_tuser
);

  localparam integer SEL_W  = $clog2(NUM_INPUTS);
  localparam integer KEEP_W = C_AXIS_DATA_WIDTH/8;

  // Frame-lock state : hold the active selection stable across a
  // multi-beat packet so the stream is never switched mid-frame.
  reg  [SEL_W-1:0] sel_reg;
  reg              frame_reg;

  // Effective select : live 'sel' while idle, locked 'sel_reg' during a frame
  wire [SEL_W-1:0] sel_eff   = frame_reg ? sel_reg : sel;
  wire             sel_valid = (sel_eff < NUM_INPUTS);

  // Selected input stream signals
  wire                          in_tvalid = sel_valid ? s_axis_tvalid[sel_eff] : 1'b0;
  wire                          in_tlast  = sel_valid ? s_axis_tlast[sel_eff]  : 1'b0;
  wire [C_AXIS_DATA_WIDTH-1:0]  in_tdata  = s_axis_tdata [sel_eff*C_AXIS_DATA_WIDTH  +: C_AXIS_DATA_WIDTH];
  wire [KEEP_W-1:0]             in_tkeep  = s_axis_tkeep [sel_eff*KEEP_W             +: KEEP_W];
  wire [C_AXIS_TID_WIDTH-1:0]   in_tid    = s_axis_tid   [sel_eff*C_AXIS_TID_WIDTH   +: C_AXIS_TID_WIDTH];
  wire [C_AXIS_TDEST_WIDTH-1:0] in_tdest  = s_axis_tdest [sel_eff*C_AXIS_TDEST_WIDTH +: C_AXIS_TDEST_WIDTH];
  wire [C_AXIS_TUSER_WIDTH-1:0] in_tuser  = s_axis_tuser [sel_eff*C_AXIS_TUSER_WIDTH +: C_AXIS_TUSER_WIDTH];

  // Output stream : forward the selected input (combinational, 0-latency).
  // Forced to the reset defaults while aresetn is asserted low.
  assign m_axis_tvalid = aresetn ? in_tvalid : 1'b0;
  assign m_axis_tdata  = aresetn ? in_tdata  : {C_AXIS_DATA_WIDTH{1'b0}};
  assign m_axis_tkeep  = aresetn ? in_tkeep  : {KEEP_W{1'b0}};
  assign m_axis_tlast  = aresetn ? in_tlast  : 1'b0;
  assign m_axis_tid    = aresetn ? in_tid    : {C_AXIS_TID_WIDTH{1'b0}};
  assign m_axis_tdest  = aresetn ? in_tdest  : {C_AXIS_TDEST_WIDTH{1'b0}};
  assign m_axis_tuser  = aresetn ? in_tuser  : {C_AXIS_TUSER_WIDTH{1'b0}};

  // Ready : only the selected input receives the output ready; all
  // other inputs are held low (back-pressured). Low while in reset.
  genvar gi;
  generate
    for (gi = 0; gi < NUM_INPUTS; gi = gi + 1) begin : g_ready
      assign s_axis_tready[gi] = (aresetn && sel_valid && (sel_eff == gi)) ? m_axis_tready : 1'b0;
    end
  endgenerate

  // Frame-lock FSM : lock the selection once a non-terminal beat has been
  // transferred; release it when the terminating (tlast) beat completes.
  always @(posedge aclk or negedge aresetn) begin
    if (!aresetn) begin
      frame_reg <= 1'b0;
      sel_reg   <= {SEL_W{1'b0}};
    end else begin
      if (!frame_reg) begin
        if (in_tvalid && m_axis_tready && !in_tlast) begin
          frame_reg <= 1'b1;
          sel_reg   <= sel_eff;
        end
      end else begin
        if (in_tvalid && m_axis_tready && in_tlast) begin
          frame_reg <= 1'b0;
        end
      end
    end
  end

endmodule


