module barrel_shifter_8bit (
    input  wire [7:0] data_in,
    input  wire [2:0] shift_bits,
    input  wire       left_right,
    output wire [7:0] data_out
);

    // Combinational barrel shifter:
    //   left_right = 1 : logical shift left  (zeros into LSBs)
    //   left_right = 0 : logical shift right (zeros into MSBs)
    assign data_out = left_right ? (data_in << shift_bits)
                                 : (data_in >> shift_bits);

endmodule

module barrel_shifter #(
  parameter data_width       = 16,
  parameter shift_bits_width = 4
)(
  input  [data_width-1:0]       data_in,
  input  [shift_bits_width-1:0] shift_bits,
  input                         left_right,        // 1: left, 0: right
  input                         rotate_left_right, // 0: shift, 1: rotate
  output [data_width-1:0]       data_out
);

  // Standard logical shift (zero-fill). left_right=1 -> left, 0 -> right.
  wire [data_width-1:0] shift_result;
  assign shift_result = left_right ? (data_in << shift_bits)
                                   : (data_in >> shift_bits);

  // Rotate: bits shifted out one end wrap around to the opposite end.
  // Left rotate by n : (data_in << n) | (data_in >> (data_width - n))
  // Right rotate by n: (data_in >> n) | (data_in << (data_width - n))
  // For n = 0, (data_width - n) = data_width, so the wrap term shifts to 0 and the
  // result is data_in unchanged (no shift), as required.
  wire [data_width-1:0] rotate_result;
  assign rotate_result = left_right
      ? ((data_in << shift_bits) | (data_in >> (data_width - shift_bits)))
      : ((data_in >> shift_bits) | (data_in << (data_width - shift_bits)));

  assign data_out = rotate_left_right ? rotate_result : shift_result;

endmodule

module barrel_shifter #(
    parameter data_width = 16,
    parameter shift_bits_width = 4
)(
    input [data_width-1:0] data_in,
    input [shift_bits_width-1:0] shift_bits,
    input [2:0] mode,
    input left_right,
    input [data_width-1:0] mask,
    output reg [data_width-1:0] data_out,
    output reg error
);

always @(*) begin
    error = 1'b0;
    case (mode)
        3'b000: begin
            // Logical shift
            if (left_right)
                data_out = data_in << shift_bits;
            else
                data_out = data_in >> shift_bits;
        end
        3'b001: begin
            // Arithmetic shift (sign extension on right shift)
            if (left_right)
                data_out = data_in << shift_bits;
            else
                data_out = $signed(data_in) >>> shift_bits;
        end
        3'b010: begin
            // Rotate (circular)
            if (left_right)
                data_out = (data_in << shift_bits) | (data_in >> (data_width - shift_bits));
            else
                data_out = (data_in >> shift_bits) | (data_in << (data_width - shift_bits));
        end
        3'b011: begin
            // Custom mask-based shift
            if (left_right)
                data_out = (data_in << shift_bits) & mask;
            else
                data_out = (data_in >> shift_bits) & mask;
        end
        3'b100: begin
            // XOR with shifted data and mask
            if (left_right)
                data_out = (data_in << shift_bits) ^ mask;
            else
                data_out = (data_in >> shift_bits) ^ mask;
        end
        default: begin
            // Invalid mode
            data_out = {data_width{1'b0}};
            error = 1'b1;
        end
    endcase
end

endmodule

module barrel_shifter #(
    parameter data_width = 16,
    parameter shift_bits_width = 4
)(
    input [data_width-1:0] data_in,
    input [shift_bits_width-1:0] shift_bits,
    input [2:0] mode,
    input left_right,
    input [data_width-1:0] mask,
    input enable,
    input enable_parity,
    output reg [data_width-1:0] data_out,
    output reg parity_out,
    output reg error
);

integer i;

always @(*) begin
    if (enable) begin
        error = 1'b0;
        if (shift_bits >= data_width) begin
            // Invalid shift amount
            data_out = {data_width{1'b0}};
            error = 1'b1;
        end else begin
            case (mode)
                3'b000: begin
                    // Logical shift
                    if (left_right)
                        data_out = data_in << shift_bits;
                    else
                        data_out = data_in >> shift_bits;
                end
                3'b001: begin
                    // Arithmetic shift (sign extension on right shift)
                    if (left_right)
                        data_out = data_in << shift_bits;
                    else
                        data_out = $signed(data_in) >>> shift_bits;
                end
                3'b010: begin
                    // Rotate (circular)
                    if (left_right)
                        data_out = (data_in << shift_bits) | (data_in >> (data_width - shift_bits));
                    else
                        data_out = (data_in >> shift_bits) | (data_in << (data_width - shift_bits));
                end
                3'b011: begin
                    // Masked shift (logical shift ANDed with mask)
                    if (left_right)
                        data_out = (data_in << shift_bits) & mask;
                    else
                        data_out = (data_in >> shift_bits) & mask;
                end
                3'b100: begin
                    // Arithmetic addition / subtraction (truncated to data_width)
                    if (left_right)
                        data_out = data_in + shift_bits;
                    else
                        data_out = data_in - shift_bits;
                end
                3'b101: begin
                    // Priority encoder: position of highest set bit
                    data_out = {data_width{1'b0}};
                    for (i = 0; i < data_width; i = i + 1) begin
                        if (data_in[i])
                            data_out = i;
                    end
                end
                3'b110: begin
                    // Modulo arithmetic (result wrapped into [0, data_width-1])
                    if (left_right)
                        data_out = (data_in + shift_bits) % data_width;
                    else
                        data_out = (data_in - shift_bits) % data_width;
                end
                default: begin
                    // 3'b111 : not supported
                    data_out = {data_width{1'b0}};
                    error = 1'b1;
                end
            endcase
        end

        // Parity of the resulting data_out
        if (enable_parity)
            parity_out = ^data_out;
        else
            parity_out = 1'b0;
    end else begin
        // enable = 0 : retain previous data_out (hold), parity disabled
        parity_out = 1'b0;
        error = 1'b0;
    end
end

endmodule

module bcd_adder(
                 input  [3:0] a,             // 4-bit BCD input
                 input  [3:0] b,             // 4-bit BCD input
                 output [3:0] sum,           // The corrected 4-bit BCD result of the addition
                 output       cout           // Carry-out to indicate overflow beyond BCD range (i.e., when the result exceeds 9)
                );

wire [3:0] binary_sum;         // Intermediate binary sum
wire binary_cout;              // Intermediate binary carry
wire z1, z2;                   // Intermediate wires for BCD correction
wire carry;                    // Carry for the second adder

    // Instantiate the first four-bit adder for Binary Addition
   four_bit_adder adder1(
                      .a(a),
                      .b(b),
                      .cin(1'b0),
                      .sum(binary_sum),
                      .cout(binary_cout)
                     );

    // BCD correction condition logic:
    // correction (add 6) is required when the binary sum exceeds 9,
    // i.e. when the 4-bit adder produced a carry (binary_cout), OR when the
    // low 4 bits are in the range 10..15, detected by the upper bits:
    //   s3 & s2  (12..15)   -> z1
    //   s3 & s1  (10,11)    -> z2
    assign z1   = binary_sum[3] & binary_sum[2];
    assign z2   = binary_sum[3] & binary_sum[1];
    assign cout = binary_cout | z1 | z2;

    // Instantiate the second four-bit adder for BCD correction
    four_bit_adder adder2(
                      .a(binary_sum),
                      .b({1'b0, cout, cout, 1'b0}),
                      .cin(1'b0),
                      .sum(sum),
                      .cout(carry)
                     );
endmodule


// Module of four_bit_adder
module four_bit_adder(
                      input [3:0] a,           // 4-bit input a
                      input [3:0] b,           // 4-bit input b
                      input cin,               // Carry input
                      output [3:0] sum,        // 4-bit sum output
                      output cout              // Carry output
                     );

    wire [2:0] carry;         // Intermediate carry wires

    genvar i;                 // Declare a variable for the generate loop

    generate
        for (i = 0; i < 4; i = i + 1) begin : fa_gen
            if (i == 0) begin : fa_first
                full_adder fa(
                              .a(a[i]),
                              .b(b[i]),
                              .cin(cin),
                              .sum(sum[i]),
                              .cout(carry[i])
                             );
            end
            else if (i == 3) begin : fa_last
                full_adder fa(
                              .a(a[i]),
                              .b(b[i]),
                              .cin(carry[i-1]),
                              .sum(sum[i]),
                              .cout(cout)
                             );
            end
            else begin : fa_mid
                full_adder fa(
                              .a(a[i]),
                              .b(b[i]),
                              .cin(carry[i-1]),
                              .sum(sum[i]),
                              .cout(carry[i])
                             );
            end
        end
    endgenerate

endmodule


// Module of full_adder
module full_adder(
                  input a,     	// First Addend input
                  input b,     	// Second Addend input
                  input cin,   	// Carry input
                  output sum,  	// Sum output
                  output cout  	// Carry output
                );

    assign sum = a ^ b ^ cin;                      // Calculate sum using XOR
    assign cout = (a & b) | (b & cin) | (a & cin); // Calculate carry-out
endmodule

module bcd_counter (
    input  wire       clk,
    input  wire       rst,
    output reg [3:0]  ms_hr,
    output reg [3:0]  ls_hr,
    output reg [3:0]  ms_min,
    output reg [3:0]  ls_min,
    output reg [3:0]  ms_sec,
    output reg [3:0]  ls_sec
);

    always @(posedge clk) begin
        if (rst) begin
            ms_hr  <= 4'd0;
            ls_hr  <= 4'd0;
            ms_min <= 4'd0;
            ls_min <= 4'd0;
            ms_sec <= 4'd0;
            ls_sec <= 4'd0;
        end else begin
            if (ls_sec == 4'd9) begin
                ls_sec <= 4'd0;
                if (ms_sec == 4'd5) begin
                    ms_sec <= 4'd0;
                    if (ls_min == 4'd9) begin
                        ls_min <= 4'd0;
                        if (ms_min == 4'd5) begin
                            ms_min <= 4'd0;
                            // hour rollover: 23:59:59 -> 00:00:00
                            if (ms_hr == 4'd2 && ls_hr == 4'd3) begin
                                ms_hr <= 4'd0;
                                ls_hr <= 4'd0;
                            end else if (ls_hr == 4'd9) begin
                                ls_hr <= 4'd0;
                                ms_hr <= ms_hr + 4'd1;
                            end else begin
                                ls_hr <= ls_hr + 4'd1;
                            end
                        end else begin
                            ms_min <= ms_min + 4'd1;
                        end
                    end else begin
                        ls_min <= ls_min + 4'd1;
                    end
                end else begin
                    ms_sec <= ms_sec + 4'd1;
                end
            end else begin
                ls_sec <= ls_sec + 4'd1;
            end
        end
    end

endmodule

module bcd_to_excess_3 (
    input  wire [3:0] bcd,
    output reg  [3:0] excess3,
    output reg        error
);

    always @(*) begin
        if (bcd <= 4'd9) begin
            excess3 = bcd + 4'd3;
            error   = 1'b0;
        end else begin
            excess3 = 4'd0;
            error   = 1'b1;
        end
    end

endmodule

`timescale 1ns / 1ps
module bcd_to_excess_3(
    input            clk,        // Clock signal for synchronous operation
    input            rst,        // Synchronous active-high reset
    input            enable,     // Enable control signal
    input      [3:0] bcd,        // 4-bit BCD input
    output reg [3:0] excess3,    // 4-bit Excess-3 output
    output reg       error,      // Error flag for invalid BCD input
    output reg       parity,     // Parity bit = XOR of all BCD input bits
    output reg [1:0] error_code  // 00 = no error, 01 = out-of-range BCD
);

always @(posedge clk) begin
    if (rst) begin
        excess3    <= 4'b0000;
        error      <= 1'b0;
        parity     <= 1'b0;
        error_code <= 2'b00;
    end else if (enable) begin
        // Parity is the XOR of all bits of the BCD input, computed whenever
        // the module operates (enable asserted), independent of validity.
        parity <= ^bcd;
        if (bcd <= 4'd9) begin
            // Valid BCD (0-9): Excess-3 = BCD + 3
            excess3    <= bcd + 4'd3;
            error      <= 1'b0;
            error_code <= 2'b00;
        end else begin
            // Invalid BCD (10-15): clear output, raise error
            excess3    <= 4'b0000;
            error      <= 1'b1;
            error_code <= 2'b01;
        end
    end
    // enable de-asserted (and not reset): hold all outputs unchanged
end

endmodule

module binary_multiplier #(
    parameter WIDTH = 32  // Bit-width of operands A and B
)(
    input  logic               clk,        // Clock (positive-edge synchronized)
    input  logic               rst_n,      // Active-low asynchronous reset
    input  logic [WIDTH-1:0]   A,          // Input A
    input  logic [WIDTH-1:0]   B,          // Input B
    input  logic               valid_in,   // Inputs A/B valid (one cycle)
    output logic [2*WIDTH-1:0] Product,     // Multiplication result
    output logic               valid_out    // Product valid (one cycle)
);

    // Internal state
    logic                     start;   // High while a multiply is in progress
    logic [WIDTH-1:0]         A_reg;   // Latched A
    logic [2*WIDTH-1:0]       B_reg;   // Latched B (zero-extended to product width)
    logic [2*WIDTH-1:0]       acc;     // Running accumulated sum
    logic [$clog2(WIDTH+2):0] cnt;     // Operation cycle counter

    // Sequential add-shift multiplier.
    //   Cycle 1        : capture inputs, start<=1                 (+1)
    //   Cycles 2..W+1  : accumulate one A bit per cycle (W bits)  (WIDTH)
    //   Cycle W+2      : register Product, assert valid_out       (+1)
    // Total latency = WIDTH + 2 cycles.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            start     <= 1'b0;
            A_reg     <= {WIDTH{1'b0}};
            B_reg     <= {(2*WIDTH){1'b0}};
            acc       <= {(2*WIDTH){1'b0}};
            cnt       <= {($clog2(WIDTH+2)+1){1'b0}};
            Product   <= {(2*WIDTH){1'b0}};
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;  // default: one-cycle pulse
            if (!start) begin
                // Idle: accept a new operation when valid_in is high.
                if (valid_in) begin
                    start <= 1'b1;
                    A_reg <= A;
                    B_reg <= B;                     // zero-extended to 2*WIDTH
                    acc   <= {(2*WIDTH){1'b0}};
                    cnt   <= 1;                      // enter cycle 1
                end
            end else begin
                if (cnt <= WIDTH) begin
                    // Accumulate contribution of A bit (cnt-1): B shifted by (cnt-1).
                    if (A_reg[cnt-1])
                        acc <= acc + (B_reg << (cnt-1));
                    cnt <= cnt + 1'b1;
                end else begin
                    // cnt == WIDTH+1 -> output stage (WIDTH+2-th cycle result).
                    Product   <= acc;
                    valid_out <= 1'b1;
                    start     <= 1'b0;
                    cnt       <= {($clog2(WIDTH+2)+1){1'b0}};
                end
            end
        end
    end

endmodule

module binary_search_tree_sort #(
    parameter DATA_WIDTH = 32,
    parameter ARRAY_SIZE = 8
) (
    input clk,
    input reset,
    input [ARRAY_SIZE*DATA_WIDTH-1:0] data_in, // Input data to be sorted
    input start,
    output reg [ARRAY_SIZE*DATA_WIDTH-1:0] sorted_out, // Sorted output
    output reg done
);

    // Parameters for top-level FSM states
    parameter IDLE = 2'b00, BUILD_TREE = 2'b01, SORT_TREE = 2'b10;

    // Pointer / null encoding (one bit wider than the node index so the
    // all-ones value is a NULL sentinel distinct from every valid index).
    localparam PW = $clog2(ARRAY_SIZE) + 1;
    localparam [PW-1:0] NULL_PTR = {PW{1'b1}};

    // BUILD_TREE sub-FSM states
    localparam INIT     = 2'b00,
               CHECK    = 2'b01,
               INSERT   = 2'b10,
               COMPLETE = 2'b11;

    // SORT_TREE sub-FSM states (6 states -> needs 3 bits)
    localparam S_INIT  = 3'b000,
               S_TRAV  = 3'b001,
               S_STORE = 3'b010,
               S_RIGHT = 3'b011,
               S_CHECK = 3'b100,
               S_DONE  = 3'b101;

    // Insertion target selector used by the INSERT state
    localparam INS_ROOT = 2'b00, INS_LEFT = 2'b01, INS_RIGHT = 2'b10;

    // Registers for FSM states
    reg [1:0] top_state;
    reg [1:0] build_state;
    reg [2:0] sort_state;

    // BST representation
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys; // Array to store node keys
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child; // Left child pointers
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child; // Right child pointers
    reg [$clog2(ARRAY_SIZE):0] root; // Root node pointer
    reg [$clog2(ARRAY_SIZE):0] next_free_node; // Pointer to the next free node

    // Stack for in-order traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] stack; // Stack for traversal
    reg [$clog2(ARRAY_SIZE):0] sp; // Stack pointer

    // Working registers
    reg [$clog2(ARRAY_SIZE):0] current_node; // Current node being processed
    reg [$clog2(ARRAY_SIZE):0] input_index; // Index for input data
    reg [$clog2(ARRAY_SIZE):0] output_index; // Index for output data
    reg [DATA_WIDTH-1:0] temp_data; // Temporary data register

    // Latched copy of the input array; captured when a sort starts so that
    // any change of data_in mid-operation is ignored.
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] data_latched;

    // Selects where the current key is inserted (root / left / right)
    reg [1:0] insert_type;

    // Combinational view of the top-of-stack node (valid whenever sp > 0)
    wire [PW-1:0] stack_top = stack[(sp-1)*PW +: PW];

    // Initialize all variables
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            top_state <= IDLE;
            build_state <= INIT;
            sort_state <= S_INIT;

            root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; ; // Null pointer
            next_free_node <= 0;
            sp <= 0;
            input_index <= 0;
            output_index <= 0;
            done <= 0;
            sorted_out <= 0;
            insert_type <= INS_ROOT;
            current_node <= 0;
            temp_data <= 0;
            data_latched <= 0;

            // Clear tree arrays
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
            end

        end else begin
            case (top_state)
                IDLE: begin
                    done <= 0;
                    input_index <= 0;
                    output_index <= 0;
                    root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; ; // Null pointer
                    next_free_node <= 0;
                    sp <= 0;
                    for (i = 0; i < ARRAY_SIZE+1; i = i + 1) begin
                        keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                        left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                    end
                    if (start) begin
                        // Latch the input array so later changes are ignored
                        data_latched <= data_in;
                        top_state <= BUILD_TREE;
                        build_state <= INIT;
                    end
                end

                BUILD_TREE: begin
                    case (build_state)

                        // INIT: fetch the next key to insert (one cycle). If the
                        // tree is empty, go insert it as the root; otherwise start
                        // the traversal from the root. When all keys are inserted,
                        // move on to COMPLETE.
                        INIT: begin
                            if (ARRAY_SIZE > input_index) begin
                                temp_data <= data_latched[input_index*DATA_WIDTH +: DATA_WIDTH];
                                if (root == NULL_PTR) begin
                                    insert_type <= INS_ROOT;
                                    build_state <= INSERT;
                                end else begin
                                    current_node <= root;
                                    build_state <= CHECK;
                                end
                            end else begin
                                build_state <= COMPLETE;
                            end
                        end

                        // CHECK: one comparison per cycle. Decide left/right; if the
                        // chosen child is NULL insert there, otherwise descend to it.
                        CHECK: begin
                            if (temp_data > keys[current_node*DATA_WIDTH +: DATA_WIDTH]) begin
                                // go right
                                if (right_child[current_node*PW +: PW] == NULL_PTR) begin
                                    insert_type <= INS_RIGHT;
                                    build_state <= INSERT;
                                end else begin
                                    current_node <= right_child[current_node*PW +: PW];
                                    build_state <= CHECK;
                                end
                            end else begin
                                // go left (<=)
                                if (left_child[current_node*PW +: PW] == NULL_PTR) begin
                                    insert_type <= INS_LEFT;
                                    build_state <= INSERT;
                                end else begin
                                    current_node <= left_child[current_node*PW +: PW];
                                    build_state <= CHECK;
                                end
                            end
                        end

                        // INSERT: place the new node and link it in (one cycle).
                        INSERT: begin
                            keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                            case (insert_type)
                                INS_ROOT:  root <= next_free_node;
                                INS_LEFT:  left_child[current_node*PW +: PW]  <= next_free_node;
                                INS_RIGHT: right_child[current_node*PW +: PW] <= next_free_node;
                                default:   root <= next_free_node;
                            endcase
                            next_free_node <= next_free_node + 1;
                            input_index <= input_index + 1;
                            build_state <= INIT;
                        end

                        COMPLETE: begin
                            // Tree construction complete
                            top_state <= SORT_TREE;
                            sort_state <= S_INIT;
                        end

                    endcase
                end

                SORT_TREE: begin
                    case (sort_state)

                        // S_INIT: start in-order traversal from the root (one cycle).
                        S_INIT: begin
                            sp <= 0;
                            if (root != NULL_PTR) begin
                                current_node <= root;
                                sort_state <= S_TRAV;
                            end else begin
                                done <= 1;
                                sort_state <= S_DONE;
                            end
                        end

                        // S_TRAV: push nodes while descending the left spine. When a
                        // NULL left child is reached, move on to pop/store.
                        S_TRAV: begin
                            if (current_node != NULL_PTR) begin
                                stack[sp*PW +: PW] <= current_node;
                                sp <= sp + 1;
                                current_node <= left_child[current_node*PW +: PW];
                                sort_state <= S_TRAV;
                            end else begin
                                sort_state <= S_STORE;
                            end
                        end

                        // S_STORE: pop the top node and store its key to the output.
                        S_STORE: begin
                            current_node <= stack_top;
                            sorted_out[output_index*DATA_WIDTH +: DATA_WIDTH] <= keys[stack_top*DATA_WIDTH +: DATA_WIDTH];
                            output_index <= output_index + 1;
                            sp <= sp - 1;
                            sort_state <= S_RIGHT;
                        end

                        // S_RIGHT: move to the popped node's right child.
                        S_RIGHT: begin
                            current_node <= right_child[current_node*PW +: PW];
                            sort_state <= S_CHECK;
                        end

                        // S_CHECK: if the right child exists, traverse its left spine;
                        // else pop the next stacked node, or finish if the stack is
                        // empty.
                        S_CHECK: begin
                            if (current_node != NULL_PTR) begin
                                sort_state <= S_TRAV;
                            end else if (sp != 0) begin
                                sort_state <= S_STORE;
                            end else begin
                                done <= 1;
                                sort_state <= S_DONE;
                            end
                        end

                        // S_DONE: outputs are valid this cycle (done held high);
                        // clear them and return to IDLE.
                        S_DONE: begin
                            done <= 0;
                            sorted_out <= 0;
                            top_state <= IDLE;
                            sort_state <= S_INIT;
                        end

                        default: sort_state <= S_INIT;

                    endcase
                end
            endcase
        end
    end
endmodule

module search_binary_search_tree #(
    parameter DATA_WIDTH = 32,         // Width of the data (of a single element)
    parameter ARRAY_SIZE = 15          // Maximum number of elements in the BST
) (

    input clk,                         // Clock signal
    input reset,                       // Reset signal
    input start,                       // Start signal to initiate the search
    input [DATA_WIDTH-1:0] search_key, // Key to search in the BST
    input [$clog2(ARRAY_SIZE):0] root, // Root node of the BST
    input [ARRAY_SIZE*DATA_WIDTH-1:0] keys, // Node keys in the BST
    input [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child,  // Left child pointers
    input [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child, // Right child pointers
    output reg [$clog2(ARRAY_SIZE):0] key_position, // Position of the found key
    output reg complete_found,         // Signal indicating search completion
    output reg search_invalid          // Signal indicating invalid search
);

    // Pointer width : one bit wider than needed to index ARRAY_SIZE nodes so
    // the all-ones value is a distinct NULL sentinel (never a valid index).
    localparam PW = $clog2(ARRAY_SIZE)+1;

    // Parameters for FSM states
    parameter S_IDLE = 3'b000,                 // Idle state
              S_INIT = 3'b001,                 // Initialization state
              S_SEARCH_LEFT = 3'b010,          // Push-left phase (descend)
              S_SEARCH_LEFT_RIGHT = 3'b011,    // Pop / visit / go-right phase
              S_COMPLETE_SEARCH = 3'b100;      // Search completion state

    // Register to store the current FSM state
    reg [2:0] search_state;

    // Variables to manage traversal
    reg [PW-1:0] position;                     // Rank (sorted position) of the found key
    reg found;                                 // Indicates if the key is found

    reg left_done, right_done;                 // Completion flags (retained from skeleton)

    // Stacks for managing traversal of the subtrees
    reg [ARRAY_SIZE*PW-1:0] left_stack;        // Stack of visited-ancestor node indices
    reg [ARRAY_SIZE*PW-1:0] right_stack;       // (retained from skeleton)
    reg [PW-1:0] sp_left;                       // Stack pointer (number of pushed nodes)
    reg [PW-1:0] sp_right;                       // (retained from skeleton)

    // Pointers for the current nodes in the traversal
    reg [PW-1:0] current_left_node;            // Current node pointer during traversal
    reg [PW-1:0] current_right_node;           // (retained from skeleton)

    // Output indices for traversal
    reg [PW-1:0] left_output_index;            // In-order rank counter (count)
    reg [PW-1:0] right_output_index;           // (retained from skeleton)

    // Scratch for the popped node index (blocking temporary, combinational only)
    reg [PW-1:0] pop_node;

    // Integer for loop iterations
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            search_state <= S_IDLE;
            found <= 0;
            position <= {PW{1'b1}};              // Invalid position
            complete_found <= 0;
            key_position <= {PW{1'b1}};          // Invalid key position (null pointer)
            left_output_index <= 0;
            right_output_index <= 0;
            sp_left <= 0;
            sp_right <= 0;
            left_done <= 0;
            right_done <= 0;
            search_invalid <= 0;

            // Clear the stacks
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                left_stack[i*PW +: PW]  <= {PW{1'b1}};
                right_stack[i*PW +: PW] <= {PW{1'b1}};
            end

        end else begin
            case (search_state)
                S_IDLE: begin
                    // Reset intermediate stacks and pulse outputs
                    for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                        left_stack[i*PW +: PW]  <= {PW{1'b1}};
                        right_stack[i*PW +: PW] <= {PW{1'b1}};
                    end
                    complete_found <= 0;
                    search_invalid <= 0;

                    if (start) begin
                        // Start the search
                        left_output_index <= 0;
                        right_output_index <= 0;
                        sp_left <= 0;
                        sp_right <= 0;
                        left_done <= 0;
                        right_done <= 0;
                        found <= 0;
                        position <= {PW{1'b1}};
                        key_position <= {PW{1'b1}};
                        search_state <= S_INIT; // Move to INIT state
                    end
                end

                S_INIT: begin
                    // Detect an empty tree: root key == 0 and both children null.
                    if ((keys[root*DATA_WIDTH +: DATA_WIDTH] == {DATA_WIDTH{1'b0}}) &&
                        (left_child[root*PW +: PW]  == {PW{1'b1}}) &&
                        (right_child[root*PW +: PW] == {PW{1'b1}})) begin
                        // No valid root -> invalid search (3 cycles from start).
                        found <= 0;
                        search_state <= S_COMPLETE_SEARCH;
                    end else begin
                        // Begin the in-order traversal from the root.
                        current_left_node <= root;
                        sp_left <= 0;
                        left_output_index <= 0;
                        found <= 0;
                        search_state <= S_SEARCH_LEFT;
                    end
                end

                S_SEARCH_LEFT: begin
                    // Push-left phase: push the current node and descend to its
                    // left child.  Keep descending (staying in this state) while
                    // a left child exists; when the left child is null, switch to
                    // the pop/visit/go-right phase.
                    left_stack[sp_left*PW +: PW] <= current_left_node;
                    sp_left <= sp_left + 1'b1;
                    if (left_child[current_left_node*PW +: PW] == {PW{1'b1}}) begin
                        current_left_node <= {PW{1'b1}};
                        search_state <= S_SEARCH_LEFT_RIGHT;
                    end else begin
                        current_left_node <= left_child[current_left_node*PW +: PW];
                        search_state <= S_SEARCH_LEFT;
                    end
                end

                S_SEARCH_LEFT_RIGHT: begin
                    // Pop / visit / go-right phase: pop the top-of-stack node,
                    // assign it the next in-order rank, and move to its right
                    // child (whose left subtree is then descended).
                    pop_node = left_stack[(sp_left-1'b1)*PW +: PW];

                    if (keys[pop_node*DATA_WIDTH +: DATA_WIDTH] == search_key) begin
                        // Found: current rank counter is this node's sorted position.
                        found <= 1'b1;
                        position <= left_output_index;
                        sp_left <= sp_left - 1'b1;
                        search_state <= S_COMPLETE_SEARCH;
                    end else begin
                        // Not this node: advance the rank counter, then go right.
                        left_output_index <= left_output_index + 1'b1;
                        sp_left <= sp_left - 1'b1;
                        if (right_child[pop_node*PW +: PW] != {PW{1'b1}}) begin
                            current_left_node <= right_child[pop_node*PW +: PW];
                            search_state <= S_SEARCH_LEFT;
                        end else begin
                            current_left_node <= {PW{1'b1}};
                            if ((sp_left - 1'b1) == {PW{1'b0}}) begin
                                // Stack empty and no right subtree -> exhausted, not found.
                                found <= 1'b0;
                                search_state <= S_COMPLETE_SEARCH;
                            end else begin
                                search_state <= S_SEARCH_LEFT_RIGHT;
                            end
                        end
                    end
                end

                S_COMPLETE_SEARCH: begin
                    // Assert the completion signals (1 clock cycle) and drive the
                    // key_position at the same time complete_found is asserted.
                    if (found) begin
                        complete_found <= 1'b1;
                        search_invalid <= 1'b0;
                        key_position <= position;
                    end else begin
                        complete_found <= 1'b0;
                        search_invalid <= 1'b1;
                        key_position <= {PW{1'b1}};
                    end
                    search_state <= S_IDLE;
                end

                default: begin
                    search_state <= S_IDLE; // Default to IDLE state
                end
            endcase
        end
    end

endmodule

module binary_to_bcd (
    input  logic [7:0]  binary_in,  // 8-bit binary input
    output logic [11:0] bcd_out     // 12-bit BCD output (3 digits)
    );

    // Intermediate shift register to hold binary and BCD values
    logic [19:0] shift_reg;  // 20-bit register: 12 for BCD and 8 for binary input
    integer I;

    always_comb begin
        // Step 1: Initialize the shift register
        //  - binary input in the rightmost 8 bits ([7:0])
        //  - 12 leading zeros in [19:8] for the accumulating BCD result
        shift_reg = {12'd0, binary_in};

        // Step 2: Double Dabble - process each of the 8 binary bits (MSB -> LSB).
        // Before each left shift, examine every 4-bit BCD digit in [19:8] and
        // add 3 to any digit that is currently >= 5 so it stays a valid BCD
        // digit (0-9) after the shift.  This add-then-shift form is equivalent
        // to the shift-then-adjust worked example (the first add is a no-op on
        // the all-zero BCD field and no adjust follows the final shift).
        for (I = 0; I < 8; I = I + 1) begin
            if (shift_reg[11:8]  >= 4'd5) shift_reg[11:8]  = shift_reg[11:8]  + 4'd3;
            if (shift_reg[15:12] >= 4'd5) shift_reg[15:12] = shift_reg[15:12] + 4'd3;
            if (shift_reg[19:16] >= 4'd5) shift_reg[19:16] = shift_reg[19:16] + 4'd3;
            shift_reg = shift_reg << 1;
        end

        // Step 3: The upper 12 bits hold the BCD equivalent of the binary input.
        bcd_out = shift_reg[19:8];
    end

endmodule

module binary_bcd_converter_twoway #(
    parameter BCD_DIGITS  = 3,
    parameter INPUT_WIDTH = 9
) (
    input  logic                       switch,      // 1 = binary->BCD, 0 = BCD->binary
    input  logic [(BCD_DIGITS*4)-1:0]  bcd_in,      // BCD value to convert to binary
    input  logic [INPUT_WIDTH-1:0]     binary_in,   // binary value to convert to BCD
    output logic [INPUT_WIDTH-1:0]     binary_out,  // binary result
    output logic [(BCD_DIGITS*4)-1:0]  bcd_out      // BCD result
);

  localparam SR_WIDTH = (BCD_DIGITS*4) + INPUT_WIDTH;
  localparam [SR_WIDTH-1:0] THREE = 3;

  logic [SR_WIDTH-1:0] shift_reg;
  logic [3:0]          nib;
  integer i, j;

  always_comb begin
    // Defaults: only the selected conversion drives its corresponding output.
    binary_out = '0;
    bcd_out    = '0;
    shift_reg  = '0;
    nib        = '0;

    if (switch) begin
      // ---- Binary -> BCD (Double Dabble) ----
      shift_reg = { {(BCD_DIGITS*4){1'b0}}, binary_in };
      for (i = 0; i < INPUT_WIDTH; i = i + 1) begin
        for (j = 0; j < BCD_DIGITS; j = j + 1) begin
          // read nibble j (variable shift is supported by Icarus)
          nib = (shift_reg >> (INPUT_WIDTH + j*4)) & 4'hF;
          // if >= 5 add 3 to that nibble (5..9 -> 8..12, no carry out of nibble)
          if (nib >= 4'd5)
            shift_reg = shift_reg + (THREE << (INPUT_WIDTH + j*4));
        end
        shift_reg = shift_reg << 1;
      end
      // BCD portion is the top BCD_DIGITS*4 bits; right-shift and let the
      // narrower bcd_out target truncate the low binary bits away.
      bcd_out = (shift_reg >> INPUT_WIDTH);
    end else begin
      // ---- BCD -> Binary ----
      // binary_out = sum over digits MSD..LSD: acc = acc*10 + digit
      binary_out = '0;
      for (i = BCD_DIGITS-1; i >= 0; i = i - 1) begin
        nib = (bcd_in >> (i*4)) & 4'hF;
        binary_out = (binary_out * 10) + nib;
      end
    end
  end

endmodule

module binary_to_bcd (
    input  logic [ 7:0] binary_in,
    output logic [11:0] bcd_out
);
  // Double-dabble shift register: 12 BCD bits [19:8] + 8 binary bits [7:0]
  logic [19:0] shift_reg;
  integer i;

  always @* begin
    shift_reg = {12'd0, binary_in};
    for (i = 0; i < 8; i = i + 1) begin
      if (shift_reg[11:8]  >= 4'd5) shift_reg[11:8]  = shift_reg[11:8]  + 4'd3; // units
      if (shift_reg[15:12] >= 4'd5) shift_reg[15:12] = shift_reg[15:12] + 4'd3; // tens
      if (shift_reg[19:16] >= 4'd5) shift_reg[19:16] = shift_reg[19:16] + 4'd3; // hundreds
      shift_reg = shift_reg << 1;
    end
    bcd_out = shift_reg[19:8];
  end
endmodule

module binary_to_gray #(
    parameter WIDTH = 6  // Define the bit width of the input
) (
    input  wire [WIDTH-1:0] binary_in,  // Binary input
    output wire [WIDTH-1:0] gray_out     // Gray code output
);

    // MSB of the Gray code is the same as the MSB of the binary input
    assign gray_out[WIDTH-1] = binary_in[WIDTH-1];

    // Each subsequent Gray code bit is the XOR of the current binary bit
    // and the next-higher binary bit: G[i] = B[i+1] ^ B[i], for i = N-2..0
    genvar i;
    generate
        for (i = 0; i < WIDTH-1; i = i + 1) begin : gray_gen
            assign gray_out[i] = binary_in[i+1] ^ binary_in[i];
        end
    endgenerate

endmodule

module binary_to_gray #(
    parameter WIDTH = 6
) (
    input  wire [WIDTH-1:0] binary_in,
    output wire [WIDTH-1:0] gray_out
);

  // The Gray code MSB is identical to the binary MSB.
  assign gray_out[WIDTH-1] = binary_in[WIDTH-1];

  // Each remaining Gray bit is the XOR of adjacent binary bits.
  generate
    genvar i;
    for (i = 0; i < WIDTH - 1; i = i + 1) begin : gray_loop
      assign gray_out[i] = binary_in[i+1] ^ binary_in[i];
    end
  endgenerate

endmodule

module binary_to_one_hot_decoder #(
    parameter BINARY_WIDTH = 5,
    parameter OUTPUT_WIDTH = 32
)(
    input  wire [BINARY_WIDTH-1:0] binary_in,
    output reg  [OUTPUT_WIDTH-1:0] one_hot_out
);

    // Purely combinational binary -> one-hot decoder.
    // Only the bit at index binary_in is set. If binary_in is out of
    // range for the output width (binary_in >= OUTPUT_WIDTH), drive all 0.
    always @(*) begin
        if (binary_in < OUTPUT_WIDTH)
            one_hot_out = {{(OUTPUT_WIDTH-1){1'b0}}, 1'b1} << binary_in;
        else
            one_hot_out = {OUTPUT_WIDTH{1'b0}};
    end

endmodule

module bit_sync #(
    parameter STAGES = 2
) (
    input  logic aclk,
    input  logic bclk,
    input  logic rst_n,
    input  logic adata,
    output logic aq2_data,
    output logic bq2_data
);

    logic [STAGES-1:0] a_sync_chain, b_sync_chain;

    // Synchronization for bclk domain
    always_ff @(posedge bclk or negedge rst_n) begin
        if (!rst_n)
            b_sync_chain <= {STAGES{1'b0}};
        else
            b_sync_chain <= {b_sync_chain[STAGES-2:0], adata};
    end

    assign bq2_data = b_sync_chain[STAGES-1];

    // Synchronization for aclk domain: synchronize bq2_data into the aclk domain
    always_ff @(posedge aclk or negedge rst_n) begin
        if (!rst_n)
            a_sync_chain <= {STAGES{1'b0}};
        else
            a_sync_chain <= {a_sync_chain[STAGES-2:0], bq2_data};
    end

    assign aq2_data = a_sync_chain[STAGES-1];

endmodule

module bus_arbiter (
    input wire reset,
    input wire clk,
    input wire req1,
    input wire req2,
    output reg grant1,
    output reg grant2
);
    // State encoding using localparam
    localparam IDLE    = 3'b000,
               GRANT_1 = 3'b001,
               GRANT_2 = 3'b010,
               CLEAR   = 3'b011;

    // State registers
    reg [2:0] state;
    reg [2:0] next_state;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Combinational logic for next state
    always @(*) begin
        // Default assignments
        next_state = state;

        case (state)
            IDLE: begin
                // req2 has priority when both are asserted
                if (req2)
                    next_state = GRANT_2;
                else if (req1)
                    next_state = GRANT_1;
                else
                    next_state = IDLE;
            end

            GRANT_1: begin
                // req2 preempts an active grant1 (req2 prioritized)
                if (req2)
                    next_state = GRANT_2;
                // req1 deasserted -> pass through CLEAR before re-arbitration
                else if (!req1)
                    next_state = CLEAR;
                else
                    next_state = GRANT_1;
            end

            GRANT_2: begin
                // hold the bus for req2 while it stays asserted
                if (!req2)
                    next_state = CLEAR;
                else
                    next_state = GRANT_2;
            end

            CLEAR: begin
                // clear grants, then return to IDLE or serve a pending request
                if (req2)
                    next_state = GRANT_2;
                else if (req1)
                    next_state = GRANT_1;
                else
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            grant1 <= 1'b0;
            grant2 <= 1'b0;
        end else begin
            // Grant assignments based on next_state
            grant1 <= (next_state == GRANT_1);
            grant2 <= (next_state == GRANT_2);
        end
    end

endmodule

module cvdp_copilot_bus_arbiter (
    input      reset,
    input      clk,
    input      req1,
    input      req2,
    input      dynamic_priority,
    output reg grant1,
    output reg grant2
    );

// State Encoding
localparam IDLE    = 2'b00,
           GRANT_1 = 2'b01,
           GRANT_2 = 2'b10;

// STATE REGISTERS
reg [1:0] state;      // Current state
reg [1:0] next_state; // Next state

// State Transition (synchronous, active-high reset)
always @(posedge clk) begin
    if (reset)
        state <= IDLE;
    else
        state <= next_state;
end

// Next State Logic
always @(*) begin
    next_state = state; // Default assignment
    case (state)
        IDLE: begin
            if (req1 && req2)
                next_state = dynamic_priority ? GRANT_1 : GRANT_2;
            else if (req1)
                next_state = GRANT_1;
            else if (req2)
                next_state = GRANT_2;
            else
                next_state = IDLE;
        end
        GRANT_1: begin
            if (req1 && req2)
                next_state = dynamic_priority ? GRANT_1 : GRANT_2;
            else if (req1)
                next_state = GRANT_1;
            else if (req2)
                next_state = GRANT_2;
            else
                next_state = IDLE;
        end
        GRANT_2: begin
            if (req1 && req2)
                next_state = dynamic_priority ? GRANT_1 : GRANT_2;
            else if (req2)
                next_state = GRANT_2;
            else if (req1)
                next_state = GRANT_1;
            else
                next_state = IDLE;
        end
        default: next_state = IDLE;
    endcase
end

// Output Logic (registered => one-cycle latency, single grant only)
always @(posedge clk) begin
    if (reset) begin
        grant1 <= 1'b0;
        grant2 <= 1'b0;
    end else begin
        case (next_state)
            IDLE: begin
                grant1 <= 1'b0;
                grant2 <= 1'b0;
            end
            GRANT_1: begin
                grant1 <= 1'b1;
                grant2 <= 1'b0;
            end
            GRANT_2: begin
                grant1 <= 1'b0;
                grant2 <= 1'b1;
            end
            default: begin
                grant1 <= 1'b0;
                grant2 <= 1'b0;
            end
        endcase
    end
end

endmodule

module pseudo_lru_nmru_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
) (
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    localparam WW = $clog2(NWAYS);

    // One recency bit per way, per index.
    //   recency bit == 1 : way was used recently (not a replacement candidate)
    //   recency bit == 0 : way is a replacement candidate
    reg [NWAYS-1:0] recency [NINDEXES-1:0];

    integer reset_counter;

    // Return the smallest-index way whose recency bit is zero.
    function [WW-1:0] lru_zero_way;
        input [NWAYS-1:0] row;
        integer f;
        begin
            lru_zero_way = {WW{1'b0}};
            for (f = NWAYS-1; f >= 0; f = f - 1) begin
                if (row[f] == 1'b0)
                    lru_zero_way = f[WW-1:0];
            end
        end
    endfunction

    // Replacement Logic:
    //   - single zero bit  -> pure LRU (that way is the victim)
    //   - multiple zero bits -> NMRU (smallest-index free way pointed first)
    assign way_replace = lru_zero_way(recency[index]);

    reg [WW-1:0]    target_way;
    reg [NWAYS-1:0] cur_row;
    reg [NWAYS-1:0] one_hot;
    reg [NWAYS-1:0] set_row;

    // Recency Update Logic
    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            for (reset_counter = 0; reset_counter < NINDEXES; reset_counter = reset_counter + 1) begin
                recency[reset_counter] <= {NWAYS{1'b0}};
            end
        end else begin
            if (access) begin
                cur_row    = recency[index];
                // Way whose recency bit becomes set:
                //   hit  -> the accessed way (way_select)
                //   miss -> the way selected for replacement (smallest-index zero)
                target_way = hit ? way_select : lru_zero_way(cur_row);
                one_hot    = {{(NWAYS-1){1'b0}}, 1'b1} << target_way;
                set_row    = cur_row | one_hot;
                if (&set_row) begin
                    // Setting the target way would fill the row (no candidate left):
                    // keep only the target way set and reset all others to zero.
                    recency[index] <= one_hot;
                end else begin
                    recency[index] <= set_row;
                end
            end
        end
    end

endmodule : pseudo_lru_nmru_policy

module lru_counter_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
)(
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    localparam CW = $clog2(NWAYS);
    localparam RW = NWAYS * CW;

    // Each way holds a CW-bit counter, packed contiguously into one word per index.
    //   counter == NWAYS-1 : most recently used
    //   counter == 0       : least recently used (replacement victim)
    reg [RW-1:0] recency [NINDEXES-1:0];

    reg          lru_found;
    reg [CW-1:0] lru_slot;

    integer i, n;
    integer k;
    integer m;
    reg [CW-1:0] target_way;
    reg [CW-1:0] old_val;
    reg [CW-1:0] cval;
    reg [RW-1:0] row;      // local working copy of recency[index]
    reg [RW-1:0] newrow;   // local next-state word

    // Replacement Logic: the way whose counter value is 0 is the LRU way.
    always_comb begin
        row       = recency[index];
        lru_slot  = {CW{1'b0}};
        lru_found = 1'b0;
        for (m = 0; m < NWAYS; m = m + 1) begin
            if (!lru_found && (row[(m*CW) +: CW] == {CW{1'b0}})) begin
                lru_slot  = m[CW-1:0];
                lru_found = 1'b1;
            end
        end
    end

    assign way_replace = lru_slot;

    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            // Initialization: unique counter value (0..NWAYS-1) per way, ascending.
            for (i = 0; i < NINDEXES; i = i + 1) begin
                newrow = {RW{1'b0}};
                for (n = 0; n < NWAYS; n = n + 1) begin
                    newrow[(n * CW) +: CW] = n[CW-1:0];
                end
                recency[i] <= newrow;
            end
        end else begin
            if (access) begin
                row    = recency[index];
                newrow = row;

                // Target way = accessed way on a hit, LRU victim on a miss.
                target_way = hit ? way_select : lru_slot;
                old_val    = row[(target_way*CW) +: CW];

                // Recency Update Logic:
                //   target way  -> set to maximum value (NWAYS-1), most recently used
                //   any counter greater than target's previous value -> decrement
                for (k = 0; k < NWAYS; k = k + 1) begin
                    cval = row[(k*CW) +: CW];
                    if (k == target_way)
                        newrow[(k*CW) +: CW] = (NWAYS-1);
                    else if (cval > old_val)
                        newrow[(k*CW) +: CW] = cval - 1'b1;
                end

                recency[index] <= newrow;
            end
        end
    end

endmodule : lru_counter_policy

module mru_counter_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
)(
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    localparam CW = $clog2(NWAYS);

    // Each cache index holds NWAYS counters (CW bits each) packed contiguously.
    // The counters always form a permutation of the values 0 .. NWAYS-1.
    reg [(NWAYS * CW)-1:0] recency [NINDEXES-1:0];

    // Combinational MRU slot: the way holding the maximum counter value.
    reg [CW-1:0] mru_slot;
    reg [CW-1:0] max_val;

    // Sequential update state
    reg [CW-1:0] target;
    reg [CW-1:0] old_val;

    integer i, n, w;

    // -----------------------------------------------------------------
    // Sequential recency update (single-cycle, asynchronous active-high reset)
    // -----------------------------------------------------------------
    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            // Initialize each way's counter to a unique ascending value 0..NWAYS-1
            for (i = 0; i < NINDEXES; i = i + 1) begin
                for (n = 0; n < NWAYS; n = n + 1) begin
                    recency[i][(n * CW) +: CW] <= n[CW-1:0];
                end
            end
        end else begin
            if (access) begin
                // On hit the accessed way is promoted; on miss the MRU (max) way is.
                target  = hit ? way_select : mru_slot;
                old_val = recency[index][(target * CW) +: CW];
                for (n = 0; n < NWAYS; n = n + 1) begin
                    if (n[CW-1:0] == target) begin
                        // Promote target to the most-recently-used value
                        recency[index][(n * CW) +: CW] <= {CW{1'b1}};
                    end else if (recency[index][(n * CW) +: CW] > old_val) begin
                        // Decrement every counter that outranked the target's old value
                        recency[index][(n * CW) +: CW] <=
                            recency[index][(n * CW) +: CW] - 1'b1;
                    end
                end
            end
        end
    end

    // -----------------------------------------------------------------
    // Select the MRU slot: way with the maximum counter value
    // -----------------------------------------------------------------
    always_comb begin
        mru_slot = '0;
        max_val  = '0;
        for (w = 0; w < NWAYS; w = w + 1) begin
            if (recency[index][(w * CW) +: CW] > max_val) begin
                max_val  = recency[index][(w * CW) +: CW];
                mru_slot = w[CW-1:0];
            end
        end
    end

    // Way selected for replacement is the MRU slot
    assign way_replace = mru_slot;

endmodule : mru_counter_policy

module lfu_counter_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32,
    parameter COUNTERW = 2
)(
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    localparam WW = $clog2(NWAYS);
    localparam MAX_FREQUENCY = (2**COUNTERW) - 1;

    // Each cache index holds NWAYS frequency counters (COUNTERW bits each).
    reg [(NWAYS * COUNTERW)-1:0] frequency [NINDEXES-1:0];

    // Combinational least-frequently-used way selection
    reg [WW-1:0]       lfu_way;
    reg [COUNTERW-1:0] min_val;

    integer i, n, w;

    // -----------------------------------------------------------------
    // Sequential frequency update (single-cycle, asynchronous active-high reset)
    // -----------------------------------------------------------------
    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            // Initialize all frequency counters to zero
            for (i = 0; i < NINDEXES; i = i + 1) begin
                for (n = 0; n < NWAYS; n = n + 1) begin
                    frequency[i][(n * COUNTERW) +: COUNTERW] <= {COUNTERW{1'b0}};
                end
            end
        end else begin
            if (access) begin
                if (hit) begin
                    if (frequency[index][(way_select * COUNTERW) +: COUNTERW] != MAX_FREQUENCY) begin
                        // Increment the accessed way's counter (saturates at MAX_FREQUENCY)
                        frequency[index][(way_select * COUNTERW) +: COUNTERW] <=
                            frequency[index][(way_select * COUNTERW) +: COUNTERW] + 1'b1;
                    end else begin
                        // Accessed way already saturated: relieve other high counters
                        // (decrement other ways whose counter is higher than 2)
                        for (n = 0; n < NWAYS; n = n + 1) begin
                            if ((n[WW-1:0] != way_select) &&
                                (frequency[index][(n * COUNTERW) +: COUNTERW] > 2)) begin
                                frequency[index][(n * COUNTERW) +: COUNTERW] <=
                                    frequency[index][(n * COUNTERW) +: COUNTERW] - 1'b1;
                            end
                        end
                    end
                end else begin
                    // Miss: replace the least-frequently-used way, seed its counter to 1
                    frequency[index][(lfu_way * COUNTERW) +: COUNTERW] <= {{(COUNTERW-1){1'b0}}, 1'b1};
                end
            end
        end
    end

    // -----------------------------------------------------------------
    // Combinational LFU selection: minimum counter, ties resolved to lower index
    // -----------------------------------------------------------------
    always_comb begin
        lfu_way = '0;
        min_val = {COUNTERW{1'b1}};
        for (w = 0; w < NWAYS; w = w + 1) begin
            if (frequency[index][(w * COUNTERW) +: COUNTERW] < min_val) begin
                min_val = frequency[index][(w * COUNTERW) +: COUNTERW];
                lfu_way = w[WW-1:0];
            end
        end
    end

    // Way selected for replacement is the LFU way
    assign way_replace = lfu_way;

endmodule : lfu_counter_policy

module pseudo_lru_tree_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
)(
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    localparam NBITS_TREE = NWAYS - 1;
    localparam MAX_DEPTH  = $clog2(NWAYS);

    // Recency array to track next way to be replaced
    reg [NBITS_TREE-1:0] recency [NINDEXES-1:0];

    wire [NBITS_TREE-1:0] recency_updated;
    wire [$clog2(NWAYS)-1:0] pseudo_lru_slot;

    integer i;

    // Sequential logic for reset and recency updates
    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            for (i = 0; i < NINDEXES; i++) begin
                recency[i] <= NBITS_TREE'(0);
            end
        end else begin
            if (access) begin
                recency[index] <= recency_updated;
            end
        end
    end

    // Current recency tree for the selected index
    wire [NBITS_TREE-1:0] recency_current = recency[index];

    // Way that becomes most-recently-used after this access:
    //  - on a hit  : the accessed way (way_select)
    //  - on a miss : the way being replaced (pseudo_lru_slot)
    wire [$clog2(NWAYS)-1:0] mru_way = hit ? way_select : pseudo_lru_slot;

    // Update the recency tree so that `target` becomes MRU.
    // Walk the (MSB-first) path to `target`; at every internal node on that
    // path force the node bit to point to the OPPOSITE subtree (away from the
    // accessed leaf) -- i.e. the MRU (opposite) traversal.  A subsequent LRU
    // traversal (slot_select_pseudo_lru_tree) then avoids the accessed way.
    function automatic [NBITS_TREE-1:0] update_recency
        (input [NBITS_TREE-1:0] cur, input [$clog2(NWAYS)-1:0] target);
        reg [NBITS_TREE-1:0] tmp;
        integer d;
        integer node_pos;
        integer arr_idx;
        reg     pbit;
        begin
            tmp      = cur;
            node_pos = 0;
            for (d = 0; d < MAX_DEPTH; d = d + 1) begin
                pbit         = target[MAX_DEPTH-1-d];   // path direction (MSB first)
                arr_idx      = (2**d - 1) + node_pos;   // linear index of node at this depth
                tmp[arr_idx] = ~pbit;                   // point away -> mark MRU
                node_pos     = (node_pos << 1) | (pbit ? 1 : 0);
            end
            update_recency = tmp;
        end
    endfunction

    // recency_updated wire
    assign recency_updated = update_recency(recency_current, mru_way);

    // Select the Pseudo LRU slot
    slot_select_pseudo_lru_tree #(
        .NWAYS (NWAYS)
    ) slot_select_unit (
        .array (recency_current),
        .index (pseudo_lru_slot)
    );

    assign way_replace = pseudo_lru_slot;

endmodule : pseudo_lru_tree_policy

module slot_select_pseudo_lru_tree #(
    parameter NWAYS = 4
)(
    input [NWAYS-2:0] array,
    output logic [$clog2(NWAYS)-1:0] index
);

    localparam MAX_DEPTH = $clog2(NWAYS);

    integer depth;
    logic [$clog2(NWAYS)-1:0] step;
    logic direction;

    always_comb begin
        // Traverse the tree following the stored direction bits.
        // Each node bit points toward the pseudo-LRU (victim) subtree.
        step      = '0;
        direction = 1'b0;
        for (depth = 0; depth < MAX_DEPTH; depth = depth + 1) begin
            direction = array[(2**depth - 1) + step];
            step      = (step << 1) | direction;
        end
        index = step;
    end

endmodule : slot_select_pseudo_lru_tree

module fifo_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
)(
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    // FIFO array to track next way to be replaced
    reg [$clog2(NWAYS)-1:0] fifo_array [NINDEXES-1:0];

    integer i;

    // Sequential logic for reset and fifo_array updates
    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            for (i = 0; i < NINDEXES; i++) begin
                fifo_array[i] <= $clog2(NWAYS)'(0);
            end
        end else begin
            // Update the fifo_array only on an access that is a MISS (~hit).
            // During a cache hit the fifo_array (and thus way_replace) must
            // remain unchanged.
            if (access && !hit) begin
                // Set the fifo_array position for the next replacement
                fifo_array[index] <= fifo_array[index] + $clog2(NWAYS)'(1);
            end
        end
    end

    assign way_replace = fifo_array[index];

endmodule : fifo_policy

module caesar_cipher (
    input  wire [7:0] input_char,
    input  wire [3:0] key,
    output reg  [7:0] output_char
);

    // Detect character class
    wire is_upper = (input_char >= 8'd65) && (input_char <= 8'd90);  // 'A'..'Z'
    wire is_lower = (input_char >= 8'd97) && (input_char <= 8'd122); // 'a'..'z'

    // Shifted position within the alphabet, wrapping via modulo 26
    reg [7:0] pos;

    always @(*) begin
        if (is_upper) begin
            pos         = ((input_char - 8'd65) + {4'd0, key}) % 8'd26;
            output_char = pos + 8'd65;
        end else if (is_lower) begin
            pos         = ((input_char - 8'd97) + {4'd0, key}) % 8'd26;
            output_char = pos + 8'd97;
        end else begin
            pos         = 8'd0;
            output_char = input_char;
        end
    end

endmodule


// --- harness-toplevel alias (auto-added by cvdp_gate; the official
// harness compiles `-s cvdp_copilot_caesar_cipher`; the author declared `caesar_cipher`
// with the same interface) ---
module cvdp_copilot_caesar_cipher (
    input wire [7:0] input_char,
    input wire [3:0] key,
    output [7:0] output_char
);
    caesar_cipher u_caesar_cipher (.input_char(input_char), .key(key), .output_char(output_char));
endmodule


// --- harness-toplevel alias (auto-added by cvdp_gate; the official
