  // outputs default to 0 so they are not X at t=0.
  initial begin
    current_char = 0;
  end

endmodule

module caesar_cipher(
    input  wire [7:0] input_char,  // 8-bit ASCII character
    input  wire [3:0] key,         // 4-bit shift key
    output reg  [7:0] output_char  // 8-bit shifted output character
);

    // LINT review fix:
    //   The original computed ((input_char - "A" + key) % 26) + "A".  The
    //   unsized decimal literal 26 forced the % expression into a 32-bit
    //   self-determined context, so the final result was 32 bits wide and got
    //   silently truncated when assigned to the 8-bit output_char
    //   (verilator WIDTHTRUNC).  The 4-bit `key` was also implicitly
    //   zero-extended into the wider expression (WIDTHEXPAND).
    //
    // Fix: keep every intermediate expression at a fixed 8-bit width.
    //   - explicitly zero-extend `key` to 8 bits: {4'b0, key}
    //   - use an 8-bit sized modulus constant: 8'd26
    //   The value range is bounded ([0,40] % 26 -> [0,25], + "A"/"a" -> <=122),
    //   so 8 bits is sufficient and the result is functionally identical.

    always @(*) begin
        if (input_char >= "A" && input_char <= "Z")
            output_char = ((input_char - "A" + {4'b0, key}) % 8'd26) + "A";
        else if (input_char >= "a" && input_char <= "z")
            output_char = ((input_char - "a" + {4'b0, key}) % 8'd26) + "a";
        else
            output_char = input_char;
    end

endmodule

// Car Parking Management System
// FSM-based controller that tracks vehicle entry/exit, available parking
// spaces, and the number of parked cars, driving LED and 7-segment displays.
module car_parking_system #(
    parameter TOTAL_SPACES = 12
) (
    input  wire                            clk,
    input  wire                            reset,
    input  wire                            vehicle_entry_sensor,
    input  wire                            vehicle_exit_sensor,
    output reg  [$clog2(TOTAL_SPACES)-1:0] available_spaces,
    output reg  [$clog2(TOTAL_SPACES)-1:0] count_car,
    output reg                             led_status,
    output reg  [6:0]                      seven_seg_display_available_tens,
    output reg  [6:0]                      seven_seg_display_available_units,
    output reg  [6:0]                      seven_seg_display_count_tens,
    output reg  [6:0]                      seven_seg_display_count_units
);

    // ------------------------------------------------------------------
    // FSM state encoding
    // ------------------------------------------------------------------
    localparam [1:0] IDLE = 2'b00, // no vehicle detected
                     ENTRY = 2'b01, // vehicle entering
                     EXIT = 2'b10, // vehicle exiting
                     FULL = 2'b11; // parking full, entry denied

    reg [1:0] state, next_state;

    // ------------------------------------------------------------------
    // Next-state (combinational) logic
    // ------------------------------------------------------------------
    always @(*) begin
        next_state = state;
        case (state)
            // Full: entry denied until a vehicle exits and frees a space
            FULL: begin
                if (available_spaces != {$clog2(TOTAL_SPACES){1'b0}}) begin
                    if (vehicle_exit_sensor && !vehicle_entry_sensor &&
                        (count_car != {$clog2(TOTAL_SPACES){1'b0}}))
                        next_state = EXIT;
                    else
                        next_state = IDLE;
                end else begin
                    next_state = FULL;
                end
            end
            // Idle / Entry / Exit all share the same arbitration
            default: begin
                if (available_spaces == {$clog2(TOTAL_SPACES){1'b0}})
                    next_state = FULL;
                else if (vehicle_entry_sensor && !vehicle_exit_sensor)
                    next_state = ENTRY;
                else if (vehicle_exit_sensor && !vehicle_entry_sensor &&
                         (count_car != {$clog2(TOTAL_SPACES){1'b0}}))
                    next_state = EXIT;
                else
                    next_state = IDLE;
            end
        endcase
    end

    // ------------------------------------------------------------------
    // State register (asynchronous active-high reset)
    // ------------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // ------------------------------------------------------------------
    // Space / car counters (asynchronous active-high reset)
    // ------------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            available_spaces <= TOTAL_SPACES[$clog2(TOTAL_SPACES)-1:0];
            count_car        <= {$clog2(TOTAL_SPACES){1'b0}};
        end else begin
            if (vehicle_entry_sensor && !vehicle_exit_sensor &&
                (available_spaces != {$clog2(TOTAL_SPACES){1'b0}})) begin
                // Vehicle entering: one fewer space, one more car
                available_spaces <= available_spaces - 1'b1;
                count_car        <= count_car + 1'b1;
            end else if (vehicle_exit_sensor && !vehicle_entry_sensor &&
                         (count_car != {$clog2(TOTAL_SPACES){1'b0}})) begin
                // Vehicle exiting: one more space, one fewer car
                available_spaces <= available_spaces + 1'b1;
                count_car        <= count_car - 1'b1;
            end
        end
    end

    // ------------------------------------------------------------------
    // LED status: 1 = spaces available, 0 = full
    // ------------------------------------------------------------------
    always @(*) begin
        led_status = (available_spaces != {$clog2(TOTAL_SPACES){1'b0}});
    end

    // ------------------------------------------------------------------
    // 7-segment decoder
    // Segment mapping: MSB = A ... LSB = G  ({a,b,c,d,e,f,g}), active high
    // ------------------------------------------------------------------
    function [6:0] seg7;
        input [3:0] digit;
        begin
            case (digit)
                4'd0: seg7 = 7'b1111110;
                4'd1: seg7 = 7'b0110000;
                4'd2: seg7 = 7'b1101101;
                4'd3: seg7 = 7'b1111001;
                4'd4: seg7 = 7'b0110011;
                4'd5: seg7 = 7'b1011011;
                4'd6: seg7 = 7'b1011111;
                4'd7: seg7 = 7'b1110000;
                4'd8: seg7 = 7'b1111111;
                4'd9: seg7 = 7'b1111011;
                default: seg7 = 7'b0000000;
            endcase
        end
    endfunction

    // ------------------------------------------------------------------
    // Drive the four 7-segment displays with the decimal tens/units digits
    // ------------------------------------------------------------------
    always @(*) begin
        seven_seg_display_available_tens  = seg7((available_spaces / 4'd10) & 4'hF);
        seven_seg_display_available_units = seg7((available_spaces % 4'd10) & 4'hF);
        seven_seg_display_count_tens      = seg7((count_car / 4'd10) & 4'hF);
        seven_seg_display_count_units     = seg7((count_car % 4'd10) & 4'hF);
    end

endmodule


