// This module implements a car parking management system
// - Uses an FSM to handle different states: `IDLE`, `ENTRY_PROCESSING`, `EXIT_PROCESSING`, and `FULL`.
// - Extended with a Time-Based Billing System that computes the parking fee
//   for each exiting vehicle based on its parked duration.

module car_parking_system #(
    parameter TOTAL_SPACES      = 12,
    parameter PARKING_FEE_VALUE = 50
)(
    input  wire                             clk,
    input  wire                             reset,
    input  wire                             vehicle_entry_sensor,
    input  wire                             vehicle_exit_sensor,
    input  wire [31:0]                      current_time,
    input  wire [$clog2(TOTAL_SPACES)-1:0]  current_slot,
    output reg  [$clog2(TOTAL_SPACES)-1:0]  available_spaces,
    output reg  [$clog2(TOTAL_SPACES)-1:0]  count_car,
    output reg                              led_status,
    output reg  [6:0]                       seven_seg_display_available_tens,
    output reg  [6:0]                       seven_seg_display_available_units,
    output reg  [6:0]                       seven_seg_display_count_tens,
    output reg  [6:0]                       seven_seg_display_count_units,
    output reg  [31:0]                       parking_fee,
    output reg                               fee_ready
);

    // Local parameters for FSM states
    localparam IDLE            = 2'b00,
               ENTRY_PROCESSING = 2'b01,
               EXIT_PROCESSING  = 2'b10,
               FULL            = 2'b11;

    // Internal signals
    reg [1:0] state, next_state;

    // Internal register array to store the entry timestamp for each parking slot.
    // Each index corresponds to a specific parking slot.
    reg [31:0] entry_time [0:TOTAL_SPACES-1];

    integer i;

    // Seven-segment encoding
    function [6:0] seven_segment_encoding;
        input [3:0] digit;
        begin
            case (digit)
                4'd0: seven_segment_encoding = 7'b1111110; // 0
                4'd1: seven_segment_encoding = 7'b0110000; // 1
                4'd2: seven_segment_encoding = 7'b1101101; // 2
                4'd3: seven_segment_encoding = 7'b1111001; // 3
                4'd4: seven_segment_encoding = 7'b0110011; // 4
                4'd5: seven_segment_encoding = 7'b1011011; // 5
                4'd6: seven_segment_encoding = 7'b1011111; // 6
                4'd7: seven_segment_encoding = 7'b1110000; // 7
                4'd8: seven_segment_encoding = 7'b1111111; // 8
                4'd9: seven_segment_encoding = 7'b1111011; // 9
                default: seven_segment_encoding = 7'b0000000; // Blank display
            endcase
        end
    endfunction

    // Time-based billing calculation.
    // Accepts the total parked time (in seconds) and the hourly rate (currency
    // units), rounds partial hours UP to the next hour, and multiplies by the rate.
    function [31:0] calculate_fee;
        input [31:0] parked_time;
        input [31:0] rate;
        reg   [31:0] hours;
        begin
            hours = parked_time / 32'd3600;
            if ((parked_time % 32'd3600) != 32'd0) begin
                hours = hours + 32'd1; // round up for partial hour
            end
            calculate_fee = hours * rate;
        end
    endfunction

    // Reset logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic and outputs
    always @(*) begin
        // Defaults
        next_state = state;
        case (state)
            IDLE: begin
                if (vehicle_entry_sensor && available_spaces > 0) begin
                    next_state = ENTRY_PROCESSING;
                end else if (vehicle_exit_sensor && count_car > 0) begin
                    next_state = EXIT_PROCESSING;
                end else if (available_spaces == 0) begin
                    next_state = FULL;
                end
            end
            ENTRY_PROCESSING: begin
                if (available_spaces > 0) begin
                    next_state = IDLE;
                end
            end
            EXIT_PROCESSING: begin
                if (count_car > 0) begin
                    next_state = IDLE;
                end
            end
            FULL: begin
                if (vehicle_exit_sensor) begin
                    next_state = EXIT_PROCESSING;
                end
            end
        endcase
    end

    always@(*)begin
        if(state == FULL) begin
            led_status = 1'b0;
        end else begin
            led_status = 1'b1;
        end
    end

    // Space and count management
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            available_spaces <= TOTAL_SPACES;
            count_car <= 0;
        end else begin
            if (state == ENTRY_PROCESSING) begin
                available_spaces <= available_spaces - 1;
                count_car <= count_car + 1;
            end else if (state == EXIT_PROCESSING) begin
                available_spaces <= available_spaces + 1;
                count_car <= count_car - 1;
            end else begin
                available_spaces <= available_spaces;
                count_car <= count_car;
            end
        end
    end

    // Time-based billing: store the entry timestamp on entry, and on exit
    // compute the fee from the parked duration and clear the stored timestamp.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            parking_fee <= 32'd0;
            fee_ready   <= 1'b0;
            for (i = 0; i < TOTAL_SPACES; i = i + 1) begin
                entry_time[i] <= 32'd0;
            end
        end else begin
            case (state)
                ENTRY_PROCESSING: begin
                    // Store the entry timestamp for the vehicle's slot upon entry.
                    entry_time[current_slot] <= current_time;
                    fee_ready <= 1'b0;
                end
                EXIT_PROCESSING: begin
                    // Retrieve the stored entry time for the vehicle using current_slot,
                    // compute the fee, flag completion, and clear the entry time.
                    parking_fee <= calculate_fee(current_time - entry_time[current_slot], PARKING_FEE_VALUE);
                    fee_ready   <= 1'b1;
                    entry_time[current_slot] <= 32'd0;
                end
                default: begin
                    fee_ready <= 1'b0;
                end
            endcase
        end
    end

    // Seven-segment display update
    always @(*) begin
        seven_seg_display_available_tens = seven_segment_encoding(available_spaces / 10);
        seven_seg_display_available_units = seven_segment_encoding(available_spaces % 10);
        seven_seg_display_count_tens = seven_segment_encoding(count_car / 10);
        seven_seg_display_count_units = seven_segment_encoding(count_car % 10);
    end

endmodule

// This module implements a car parking management system
// - Uses an FSM to handle different states: `IDLE`, `ENTRY_PROCESSING`, `EXIT_PROCESSING`, and `FULL`.

module car_parking_system #(
    parameter TOTAL_SPACES = 12,
    parameter PARKING_FEE_VALUE = 50,
    // Internal parameter for MAX_DAILY_FEE (fee cap per vehicle for the day).
    parameter MAX_DAILY_FEE = 500
)(
    input wire clk,
    input wire reset,
    input wire vehicle_entry_sensor,
    input wire vehicle_exit_sensor,
    input wire [31:0] current_time, // Current time in seconds
    input wire [$clog2(TOTAL_SPACES)-1:0] current_slot, // Slot number for the vehicle
    output reg [$clog2(TOTAL_SPACES)-1:0] available_spaces,
    output reg [$clog2(TOTAL_SPACES)-1:0] count_car,
    output reg led_status,
    output reg [6:0] seven_seg_display_available_tens,
    output reg [6:0] seven_seg_display_available_units,
    output reg [6:0] seven_seg_display_count_tens,
    output reg [6:0] seven_seg_display_count_units,
    output [15:0] parking_fee, // Total parking fee for the vehicle exiting
    output fee_ready,          // Indicates that the parking fee is ready
    // Hour of the day (0-23), used for peak-hour dynamic pricing.
    input wire [4:0] hour_of_day,
    // QR code encoding the parking fee details for payment.
    output [127:0] qr_code
);

    // Local parameters for FSM states
    localparam IDLE            = 2'b00,
               ENTRY_PROCESSING = 2'b01,
               EXIT_PROCESSING  = 2'b10,
               FULL            = 2'b11;

    // Internal signals
    reg [1:0] state, next_state;
    reg [31:0] entry_time [TOTAL_SPACES-1:0]; // Array to store entry times for each parking space
    integer i;

    reg [15:0] parking_fee_internal;
    reg fee_ready_internal;

    // Register for dynamic parking fee (per-hour rate):
    // double for peak hours, default for off-peak.
    reg [15:0] dynamic_fee;

    // Register holding the generated QR code for payment.
    reg [127:0] qr_code_internal;

    // Temporaries used during fee computation
    reg [31:0] parked_duration;
    reg [15:0] computed_fee;

    // Seven-segment encoding
    function [6:0] seven_segment_encoding;
        input [3:0] digit;
        begin
            case (digit)
                4'd0: seven_segment_encoding = 7'b1111110; // 0
                4'd1: seven_segment_encoding = 7'b0110000; // 1
                4'd2: seven_segment_encoding = 7'b1101101; // 2
                4'd3: seven_segment_encoding = 7'b1111001; // 3
                4'd4: seven_segment_encoding = 7'b0110011; // 4
                4'd5: seven_segment_encoding = 7'b1011011; // 5
                4'd6: seven_segment_encoding = 7'b1011111; // 6
                4'd7: seven_segment_encoding = 7'b1110000; // 7
                4'd8: seven_segment_encoding = 7'b1111111; // 8
                4'd9: seven_segment_encoding = 7'b1111011; // 9
                default: seven_segment_encoding = 7'b0000000; // Blank display
            endcase
        end
    endfunction

    reg [31:0] hours = 0;

    // Fee calculation function
    function [15:0] calculate_fee;
        input [31:0] parked_time; // Total parked time in seconds
        input [15:0] fee_per_hour;
        begin
            hours = parked_time / 3600; // Convert seconds to hours
            if (parked_time % 3600 > 0) begin
                hours = hours + 1; // Round up to the next hour if there's a remainder
            end
            calculate_fee = hours * fee_per_hour;
        end
    endfunction

    // QR code generation function
    function [127:0] generate_qr_code;
        input [15:0] fee;
        input [$clog2(TOTAL_SPACES)-1:0] slot;
        input [31:0] time_spent;
        begin
            // Concatenate slot, fee, and time spent for QR data
            generate_qr_code = {slot, fee, time_spent[15:0], 80'b0}; // Include time spent in the lower bits
        end
    endfunction

    // Reset logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Dynamic pricing logic:
    // Peak hours are 8 AM to 6 PM (hours 8 through 18); the fee per hour is
    // doubled during peak hours, otherwise the default fee per hour is used.
    always @(*) begin
        if ((hour_of_day >= 5'd8) && (hour_of_day <= 5'd18)) begin
            dynamic_fee = PARKING_FEE_VALUE * 2; // peak hours -> double
        end else begin
            dynamic_fee = PARKING_FEE_VALUE;     // off-peak -> default
        end
    end

    // Next state logic and outputs
    always @(*) begin
        // Defaults
        next_state = state;
        case (state)
            IDLE: begin
                if (vehicle_entry_sensor && available_spaces > 0) begin
                    next_state = ENTRY_PROCESSING;
                end else if (vehicle_exit_sensor && count_car > 0) begin
                    next_state = EXIT_PROCESSING;
                end else if (available_spaces == 0) begin
                    next_state = FULL;
                end
            end
            ENTRY_PROCESSING: begin
                if (available_spaces > 0) begin
                    next_state = IDLE;
                end
            end
            EXIT_PROCESSING: begin
                if (count_car > 0) begin
                    next_state = IDLE;
                end
            end
            FULL: begin
                if (vehicle_exit_sensor) begin
                    next_state = EXIT_PROCESSING;
                end
            end
        endcase
    end

    always@(*)begin
        if(state == FULL) begin
            led_status = 1'b0;
        end else begin
            led_status = 1'b1;
        end
    end

    // Space and count management
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            available_spaces <= TOTAL_SPACES;
            count_car <= 0;
            for (i = 0; i < TOTAL_SPACES; i = i + 1) begin
                entry_time[i] <= 0;
            end
        end else begin
            if (state == ENTRY_PROCESSING) begin
                entry_time[current_slot] <= current_time; // Store the entry time based on slot
                available_spaces <= available_spaces - 1;
                count_car <= count_car + 1;
            end else if (state == EXIT_PROCESSING) begin
                if (entry_time[current_slot] != 0) begin
                    entry_time[current_slot] <= 0; // Clear the slot
                end
                available_spaces <= available_spaces + 1;
                count_car <= count_car - 1;
            end else begin
                available_spaces <= available_spaces;
                count_car <= count_car;
            end
        end
    end

    // Fee calculation and QR code generation logic.
    // On exit, compute the parked duration (current_time - entry_time), apply
    // the dynamic (peak/off-peak) per-hour fee, cap the total at MAX_DAILY_FEE,
    // and generate the 128-bit QR code from the fee, slot and duration.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            parking_fee_internal <= 16'd0;
            fee_ready_internal   <= 1'b0;
            qr_code_internal     <= 128'd0;
        end else if (state == EXIT_PROCESSING) begin
            // Duration the vehicle stayed parked (in seconds)
            parked_duration = current_time - entry_time[current_slot];
            // Fee for the duration at the dynamic (peak/off-peak) hourly rate
            computed_fee    = calculate_fee(parked_duration, dynamic_fee);
            // Cap at the maximum daily fee
            if (computed_fee > MAX_DAILY_FEE) begin
                computed_fee = MAX_DAILY_FEE;
            end
