// This module implements a car parking management system
// - Uses an FSM to handle different states: `IDLE`, `ENTRY_PROCESSING`, `EXIT_PROCESSING`, and `FULL`.

module car_parking_system #(
    parameter TOTAL_SPACES = 12,
    parameter PARKING_FEE_VALUE = 50,
    parameter MAX_DAILY_FEE = 500,
    parameter WARNING_LIMIT = 12 * 3600, // 12 hours in seconds
    parameter OVERSTAY_LIMIT = 24 * 3600 // 24 hours in seconds
)(
    input wire clk,
    input wire reset,
    input wire clear,
    input wire vehicle_entry_sensor,
    input wire vehicle_exit_sensor,
    input wire [31:0] current_time, // Current time in seconds
    input wire [$clog2(TOTAL_SPACES)-1:0] current_slot, // Slot number for the vehicle
    input wire [4:0] hour_of_day, // Current hour of the day (0-23), provided externally
    output reg [$clog2(TOTAL_SPACES)-1:0] available_spaces,
    output reg [$clog2(TOTAL_SPACES)-1:0] count_car,
    output reg led_status,
    output reg [6:0] seven_seg_display_available_tens,
    output reg [6:0] seven_seg_display_available_units,
    output reg [6:0] seven_seg_display_count_tens,
    output reg [6:0] seven_seg_display_count_units,
    output reg [15:0] parking_fee, // Total parking fee for the vehicle exiting
    output reg fee_ready,          // Indicates that the parking fee is ready
    output reg [127:0] qr_code, // QR code data for parking fee payment
    output time_warning_alert, // Alert if parked beyond WARNING_LIMIT
    output reg led_warning // Blinking LED for warning
);

    // Local parameters for FSM states
    localparam IDLE            = 2'b00,
               ENTRY_PROCESSING = 2'b01,
               EXIT_PROCESSING  = 2'b10,
               FULL            = 2'b11;

    // Internal signals
    reg [1:0] state, next_state;
    reg [31:0] entry_time [TOTAL_SPACES-1:0]; // Array to store entry times for each parking space
    integer i;

    reg [15:0] dynamic_parking_fee;

    // Seven-segment encoding
    function [6:0] seven_segment_encoding;
        input [3:0] digit;
        begin
            case (digit)
                4'd0: seven_segment_encoding = 7'b1111110; // 0
                4'd1: seven_segment_encoding = 7'b0110000; // 1
                4'd2: seven_segment_encoding = 7'b1101101; // 2
                4'd3: seven_segment_encoding = 7'b1111001; // 3
                4'd4: seven_segment_encoding = 7'b0110011; // 4
                4'd5: seven_segment_encoding = 7'b1011011; // 5
                4'd6: seven_segment_encoding = 7'b1011111; // 6
                4'd7: seven_segment_encoding = 7'b1110000; // 7
                4'd8: seven_segment_encoding = 7'b1111111; // 8
                4'd9: seven_segment_encoding = 7'b1111011; // 9
                default: seven_segment_encoding = 7'b0000000; // Blank display
            endcase
        end
    endfunction

    // Fee calculation function
    function [15:0] calculate_fee;
        input [31:0] parked_time; // Total parked time in seconds
        input [15:0] fee_per_hour;
        begin
                    // Convert seconds to hours
            if (parked_time % 3600 > 0) begin
                calculate_fee = ((parked_time / 3600) + 1)*fee_per_hour; // Round up to the next hour if there's a remainder
            end else begin
                calculate_fee = ((parked_time / 3600))*fee_per_hour;
            end
        end
    endfunction

    // QR code generation function
    function [127:0] generate_qr_code;
        input [15:0] fee;
        input [$clog2(TOTAL_SPACES)-1:0] slot;
        input [31:0] time_spent;
        begin

            // Concatenate slot, fee, and time spent for QR data
            generate_qr_code = {slot, fee, time_spent, {128- ($clog2(TOTAL_SPACES) + 16 + 32){1'b0}}}; // Include time spent in the lower bits
        end
    endfunction

    // Reset logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Dynamic fee adjustment based on hour of day
    always @(*) begin
        if (hour_of_day >= 8 && hour_of_day <= 18) begin
            dynamic_parking_fee = PARKING_FEE_VALUE * 2; // Peak hours: double the fee
        end else begin
            dynamic_parking_fee = PARKING_FEE_VALUE; // Regular hours
        end
    end

    // Next state logic and outputs
    always @(*) begin
        // Defaults
        next_state = state;
        case (state)
            IDLE: begin
                if (vehicle_entry_sensor && available_spaces > 0) begin
                    next_state = ENTRY_PROCESSING;
                end else if (vehicle_exit_sensor && count_car > 0) begin
                    next_state = EXIT_PROCESSING;
                end else if (available_spaces == 0) begin
                    next_state = FULL;
                end
            end
            ENTRY_PROCESSING: begin
                next_state = IDLE;
            end
            EXIT_PROCESSING: begin
                if(clear)
                    next_state = IDLE;
                else if(time_warning_alert == 1'b1)
                    next_state = EXIT_PROCESSING;
                else
                    next_state = IDLE;
            end
            FULL: begin
                next_state = (vehicle_exit_sensor) ? EXIT_PROCESSING : FULL;
            end
        endcase
    end

    // LED Status Control
    always @(*) begin
        led_status = (state != FULL);
    end

    // Space and count management
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            available_spaces <= TOTAL_SPACES;
            count_car <= 0;
            for (i = 0; i < TOTAL_SPACES; i = i + 1) begin
                entry_time[i] <= 0;
            end
        end else begin
            if (state == ENTRY_PROCESSING) begin
                entry_time[current_slot] <= current_time; // Store the entry time based on slot
                available_spaces <= available_spaces - 1;
                count_car <= count_car + 1;
            end else if (state == EXIT_PROCESSING) begin
                    entry_time[current_slot] <= 0; // Clear the slot
                available_spaces <= available_spaces + 1;
                count_car <= count_car - 1;
            end else begin
                available_spaces <= available_spaces;
                count_car <= count_car;
            end
        end
    end

assign time_warning_alert = ((current_time - entry_time[current_slot]) > WARNING_LIMIT && (current_time - entry_time[current_slot]) < OVERSTAY_LIMIT) & !clear ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (state == EXIT_PROCESSING) begin
        // If parked time exceeds WARNING_LIMIT but is less than OVERSTAY_LIMIT, trigger alert
        if(time_warning_alert == 1)begin
            led_warning <= ~led_warning;
        end else begin
            led_warning <= 0;
        end
    end else begin
        led_warning <= 0;
    end
end



    always@(posedge clk) begin
        if(state == EXIT_PROCESSING) begin
            if (calculate_fee(current_time - entry_time[current_slot], dynamic_parking_fee) > MAX_DAILY_FEE) begin
                parking_fee <= MAX_DAILY_FEE; // Cap fee at maximum daily value
                qr_code <= generate_qr_code(MAX_DAILY_FEE, current_slot, current_time - entry_time[current_slot]); // Generate QR code with time spent
            end else begin
                parking_fee <= calculate_fee(current_time - entry_time[current_slot], dynamic_parking_fee); // Calculate fee
                qr_code <= generate_qr_code(calculate_fee(current_time - entry_time[current_slot], dynamic_parking_fee), current_slot, current_time - entry_time[current_slot]); // Generate QR code with time spent
            end
        end else begin
            parking_fee <= 0;
            qr_code <= 128'b0; // Clear QR code data
        end
    end

    always@(posedge clk) begin
        fee_ready <= (state == EXIT_PROCESSING);
    end

    // Seven-segment display update
    always @(*) begin
        seven_seg_display_available_tens = seven_segment_encoding(available_spaces / 10);
        seven_seg_display_available_units = seven_segment_encoding(available_spaces % 10);
        seven_seg_display_count_tens = seven_segment_encoding(count_car / 10);
        seven_seg_display_count_units = seven_segment_encoding(count_car % 10);
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    parking_fee = 0;
    fee_ready = 0;
    qr_code = 0;
    led_warning = 0;
  end

endmodule

module cascaded_adder #(
    parameter IN_DATA_WIDTH = 16,
    parameter IN_DATA_NS    = 4
) (
    input  wire                                                 clk,
    input  wire                                                 rst_n,
    input  wire                                                 i_valid,
    input  wire [IN_DATA_WIDTH*IN_DATA_NS-1:0]                  i_data,
    output reg                                                  o_valid,
    output reg  [IN_DATA_WIDTH+$clog2(IN_DATA_NS)-1:0]          o_data
);

    localparam OUT_DATA_WIDTH = IN_DATA_WIDTH + $clog2(IN_DATA_NS);

    // Stage 1: register the input data and valid
    reg [IN_DATA_WIDTH*IN_DATA_NS-1:0] i_data_reg;
    reg                                i_valid_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i_data_reg  <= {(IN_DATA_WIDTH*IN_DATA_NS){1'b0}};
            i_valid_reg <= 1'b0;
        end else if (i_valid) begin
            i_data_reg  <= i_data;
            i_valid_reg <= i_valid;
        end else begin
            i_valid_reg <= 1'b0;
        end
    end

    // Cascaded addition using combinational logic on the registered data
    integer idx;
    reg [OUT_DATA_WIDTH-1:0] sum;

    always @(*) begin
        sum = {OUT_DATA_WIDTH{1'b0}};
        for (idx = 0; idx < IN_DATA_NS; idx = idx + 1) begin
            sum = sum + i_data_reg[idx*IN_DATA_WIDTH +: IN_DATA_WIDTH];
        end
    end

    // Stage 2: register the cumulative sum to the output
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_data  <= {OUT_DATA_WIDTH{1'b0}};
            o_valid <= 1'b0;
        end else begin
            o_data  <= sum;
            o_valid <= i_valid_reg;
        end
    end

endmodule

module cascaded_adder #(
    parameter int IN_DATA_WIDTH = 16,                       // Width of each input data
    parameter int IN_DATA_NS = 4,                           // Number of input data elements
    parameter int NUM_STAGES = $clog2(IN_DATA_NS),          // Number of summation stages (calculated once)
    parameter logic [NUM_STAGES-1:0] REG = {NUM_STAGES{1'b1}}  // Control bits for register insertion
) (
   input  logic clk,
   input  logic rst_n,
   input  logic i_valid,
   input  logic [IN_DATA_WIDTH*IN_DATA_NS-1:0] i_data,  // Flattened input data array
   output logic o_valid,
   output logic [(IN_DATA_WIDTH+$clog2(IN_DATA_NS))-1:0] o_data // Output data (sum)
);

   // Internal signals for the adder tree
   logic [IN_DATA_WIDTH*IN_DATA_NS-1:0] i_data_ff;                             // Flattened input data array register
   logic [IN_DATA_WIDTH-1:0] in_data_2d [IN_DATA_NS-1:0];                      // Intermediate 2D array
   logic [(IN_DATA_WIDTH+$clog2(IN_DATA_NS))-1:0] stage_output [NUM_STAGES-1:0][IN_DATA_NS>>1-1:0];
   logic valid_ff;
   logic valid_pipeline [NUM_STAGES-1:0];  // Pipeline to handle the valid signal latencies based on REG

   // Register the input data on valid signal
   always_ff @(posedge clk or negedge rst_n) begin : reg_indata
      if(!rst_n)
         i_data_ff <= 0;
      else begin
         if(i_valid) begin
            i_data_ff <= i_data;
         end
      end
   end

   // Convert flattened input to 2D array
   always_comb begin
       for (int i = 0; i < IN_DATA_NS; i++) begin : conv_1d_to_2d
           in_data_2d[i] = i_data_ff[(i+1)*IN_DATA_WIDTH-1 -: IN_DATA_WIDTH];
       end
   end

   // Insert Code here for parallel logic of the adder tree using generate statements
   // Binary tree of pairwise adders. Each stage halves the number of partial sums.
   // Stage gs consumes NUM_SUMS_prev partial sums (in_data_2d at stage 0, otherwise
   // stage_output[gs-1]) and produces NUM_SUMS = IN_DATA_NS >> (gs+1) partial sums.
   // REG[gs]==1 -> the stage is registered (1 clock latency); REG[gs]==0 -> combinational.
   genvar gs, gj;
   generate
      for (gs = 0; gs < NUM_STAGES; gs = gs + 1) begin : gen_stage
         localparam int NUM_SUMS = IN_DATA_NS >> (gs + 1);
         for (gj = 0; gj < NUM_SUMS; gj = gj + 1) begin : gen_add
            if (gs == 0) begin : gen_lvl0
               // First stage: operands come from the unflattened input array.
               if (REG[gs]) begin : gen_reg
                  always_ff @(posedge clk or negedge rst_n) begin
                     if (!rst_n)
                        stage_output[gs][gj] <= '0;
                     else
                        stage_output[gs][gj] <= in_data_2d[2*gj] + in_data_2d[2*gj+1];
                  end
               end else begin : gen_comb
                  always_comb begin
                     stage_output[gs][gj] = in_data_2d[2*gj] + in_data_2d[2*gj+1];
                  end
               end
            end else begin : gen_lvln
               // Subsequent stages: operands come from the previous stage output.
               if (REG[gs]) begin : gen_reg
                  always_ff @(posedge clk or negedge rst_n) begin
                     if (!rst_n)
                        stage_output[gs][gj] <= '0;
                     else
                        stage_output[gs][gj] <= stage_output[gs-1][2*gj] + stage_output[gs-1][2*gj+1];
                  end
               end else begin : gen_comb
                  always_comb begin
                     stage_output[gs][gj] = stage_output[gs-1][2*gj] + stage_output[gs-1][2*gj+1];
                  end
               end
            end
         end
      end
   endgenerate

   always_ff @(posedge clk or negedge rst_n) begin
      if(!rst_n)
         valid_ff <= 1'b0;
      else
         valid_ff <= i_valid;
   end


   // Insert Code here for Valid signal propagation with latency based on REG
   // The valid pipeline mirrors the data adder tree stage-for-stage so that the
   // valid flag stays aligned with the partial-sum data: a registered stage
   // (REG[gs]==1) delays the valid by one clock; a combinational stage
   // (REG[gs]==0) passes it through with no added latency.
   generate
      for (gs = 0; gs < NUM_STAGES; gs = gs + 1) begin : gen_valid
         if (gs == 0) begin : gen_v0
            if (REG[gs]) begin : gen_reg
               always_ff @(posedge clk or negedge rst_n) begin
                  if (!rst_n)
                     valid_pipeline[gs] <= 1'b0;
                  else
                     valid_pipeline[gs] <= valid_ff;
               end
            end else begin : gen_comb
               always_comb begin
                  valid_pipeline[gs] = valid_ff;
               end
            end
         end else begin : gen_vn
            if (REG[gs]) begin : gen_reg
               always_ff @(posedge clk or negedge rst_n) begin
                  if (!rst_n)
                     valid_pipeline[gs] <= 1'b0;
                  else
                     valid_pipeline[gs] <= valid_pipeline[gs-1];
               end
            end else begin : gen_comb
               always_comb begin
                  valid_pipeline[gs] = valid_pipeline[gs-1];
               end
            end
         end
      end
   endgenerate


   // Assign the final stage of valid_pipeline to o_valid
   always_ff @(posedge clk or negedge rst_n) begin
      if(!rst_n)
         o_valid <= 1'b0;
      else
         o_valid <= valid_pipeline[NUM_STAGES-1];
   end

   // Output data assignment
   always_ff @(posedge clk or negedge rst_n) begin : reg_outdata
      if ( !rst_n) begin
         o_data <= 0 ;
      end else if (valid_pipeline[NUM_STAGES-1]) begin
         o_data <= stage_output[NUM_STAGES-1][0];
      end
   end

endmodule

module cdc_pulse_synchronizer (
    input  logic src_clock,   // Source Clock Domain
    input  logic des_clock,   // Destination Clock Domain
    input  logic rst_in,      // Reset
    input  logic src_pulse,   // Source Pulse
    output logic des_pulse    // Destination Pulse
);

    logic pls_toggle;
    logic pls_toggle_synca;
    logic pls_toggle_syncc;

    //--------------------------------------------------
    //   Toggle Flop Circuit
    //---------------------------------------------------
    // BUG FIX: the toggle must FLIP once per src_pulse and HOLD its value
    // otherwise. The original code forced pls_toggle back to 0 on every
    // cycle where src_pulse was low, which created a second (falling) edge
    // on the toggle net for each source pulse. That second edge crossed the
    // synchronizer and produced a spurious second des_pulse. Holding the
    // toggle (removing the else -> 0 branch) yields exactly one edge, hence
    // exactly one destination pulse, per source pulse.

    always_ff @(posedge src_clock or posedge rst_in) begin
        if (rst_in) begin
            pls_toggle <= 1'b0;
        end else if (src_pulse) begin
            pls_toggle <= ~pls_toggle;
        end
    end

    //--------------------------------------------------
    //   Double Flop Bit Synchronizer
    //---------------------------------------------------

    always_ff @(posedge des_clock or posedge rst_in) begin
        if (rst_in) begin
            pls_toggle_synca <= 1'b0;
        end else begin
            pls_toggle_synca <= pls_toggle;
        end
    end

    //--------------------------------------------------
    //   Delay Logic of Output signal
    //---------------------------------------------------

    always_ff @(posedge des_clock or posedge rst_in) begin
        if (rst_in) begin
            pls_toggle_syncc <= 1'b0;
        end else begin
            pls_toggle_syncc <= pls_toggle_synca;
        end
    end

    //--------------------------------------------------
    //   Assign Statement for posedge and negedge detection
    //---------------------------------------------------

    assign des_pulse = pls_toggle_syncc ^ pls_toggle_synca;

endmodule

module cdc_pulse_synchronizer #(
    parameter NUM_CHANNELS = 4
) (
    input  logic                      src_clock,   // Source Clock Domain
    input  logic                      des_clock,   // Destination Clock Domain
    input  logic                      rst_in,      // Asynchronous Active-High Reset
    input  logic [NUM_CHANNELS-1:0]   src_pulse,   // Source Pulse (per channel)
    output logic [NUM_CHANNELS-1:0]   des_pulse    // Destination Pulse (per channel)
);

    // Per-channel toggle and destination synchronizer stages
    logic [NUM_CHANNELS-1:0] pls_toggle;
    logic [NUM_CHANNELS-1:0] pls_toggle_synca, pls_toggle_syncb, pls_toggle_syncc;

    // Shared reset synchronizers (source / destination domains)
    logic rst_src_sync;
    logic rst_des_sync;
    logic rst_src_synca, rst_src_syncb;
    logic rst_des_synca, rst_des_syncb;

    // --- Source-domain reset synchronizer ---
    always_ff @(posedge src_clock or posedge rst_in) begin
        if (rst_in) begin
            rst_src_synca <= 1'b1;
            rst_src_syncb <= 1'b1;
        end else begin
            rst_src_synca <= 1'b0;
            rst_src_syncb <= rst_src_synca;
        end
    end

    assign rst_src_sync = rst_src_syncb;

    // --- Destination-domain reset synchronizer ---
    always_ff @(posedge des_clock or posedge rst_in) begin
        if (rst_in) begin
            rst_des_synca <= 1'b1;
            rst_des_syncb <= 1'b1;
        end else begin
            rst_des_synca <= 1'b0;
            rst_des_syncb <= rst_des_synca;
        end
    end

    assign rst_des_sync = rst_des_syncb;

    // --- Per-channel independent CDC pulse synchronizers ---
    genvar ch;
    generate
        for (ch = 0; ch < NUM_CHANNELS; ch = ch + 1) begin : gen_channel
            // Convert source pulse to a toggle in the source domain
            always_ff @(posedge src_clock or posedge rst_src_sync) begin
                if (rst_src_sync) begin
                    pls_toggle[ch] <= 1'b0;
                end else if (src_pulse[ch]) begin
                    pls_toggle[ch] <= ~pls_toggle[ch];
                end
            end

            // Double-flop the toggle into the destination domain
            always_ff @(posedge des_clock or posedge rst_des_sync) begin
                if (rst_des_sync) begin
                    pls_toggle_synca[ch] <= 1'b0;
                    pls_toggle_syncb[ch] <= 1'b0;
                end else begin
                    pls_toggle_synca[ch] <= pls_toggle[ch];
                    pls_toggle_syncb[ch] <= pls_toggle_synca[ch];
                end
            end

            // Extra destination flop for edge detection
            always_ff @(posedge des_clock or posedge rst_des_sync) begin
                if (rst_des_sync) begin
                    pls_toggle_syncc[ch] <= 1'b0;
                end else begin
                    pls_toggle_syncc[ch] <= pls_toggle_syncb[ch];
                end
            end

            // Any toggle edge produces a single-cycle destination pulse
            assign des_pulse[ch] = pls_toggle_syncc[ch] ^ pls_toggle_syncb[ch];
        end
    endgenerate

endmodule

module pseudoRandGenerator_ca (
    input  logic        clock,    // Clock input
    input  logic        reset,    // Active-high synchronous Reset
    input  logic [15:0] CA_seed,  // 16-bit Cellular Automata seed
    output logic [15:0] CA_out    // 16-bit Cellular Automata output
);

    // Current cell states taken from the registered output.
    // q1 maps to CA_out[0] (leftmost cell) ... q16 maps to CA_out[15] (rightmost cell).
    // Boundary neighbours (to the left of q1 and to the right of q16) are 0.
    logic q1, q2, q3, q4, q5, q6, q7, q8;
    logic q9, q10, q11, q12, q13, q14, q15, q16;

    assign q1  = CA_out[0];
    assign q2  = CA_out[1];
    assign q3  = CA_out[2];
    assign q4  = CA_out[3];
    assign q5  = CA_out[4];
    assign q6  = CA_out[5];
    assign q7  = CA_out[6];
    assign q8  = CA_out[7];
    assign q9  = CA_out[8];
    assign q10 = CA_out[9];
    assign q11 = CA_out[10];
    assign q12 = CA_out[11];
    assign q13 = CA_out[12];
    assign q14 = CA_out[13];
    assign q15 = CA_out[14];
    assign q16 = CA_out[15];

    // Next-state computation for each cell.
    // Configuration (cell 1 -> cell 16):
    //   R90 - R90 - R150 - R90 - R150 - R90 - R150 - R90 -
    //   R150 - R90 - R150 - R90 - R150 - R90 - R150 - R90
    // Rule 90  : next = left  XOR right
    // Rule 150 : next = left  XOR current XOR right
    logic [15:0] next_state;

    always_comb begin
        next_state[0]  = q2;                 // cell 1  : R90  (left=0)
        next_state[1]  = q1  ^ q3;           // cell 2  : R90
        next_state[2]  = q2  ^ q3  ^ q4;     // cell 3  : R150
        next_state[3]  = q3  ^ q5;           // cell 4  : R90
        next_state[4]  = q4  ^ q5  ^ q6;     // cell 5  : R150
        next_state[5]  = q5  ^ q7;           // cell 6  : R90
        next_state[6]  = q6  ^ q7  ^ q8;     // cell 7  : R150
        next_state[7]  = q7  ^ q9;           // cell 8  : R90
        next_state[8]  = q8  ^ q9  ^ q10;    // cell 9  : R150
        next_state[9]  = q9  ^ q11;          // cell 10 : R90
        next_state[10] = q10 ^ q11 ^ q12;    // cell 11 : R150
        next_state[11] = q11 ^ q13;          // cell 12 : R90
        next_state[12] = q12 ^ q13 ^ q14;    // cell 13 : R150
        next_state[13] = q13 ^ q15;          // cell 14 : R90
        next_state[14] = q14 ^ q15 ^ q16;    // cell 15 : R150
        next_state[15] = q15;                // cell 16 : R90  (right=0)
    end

    // Sequential update: synchronous active-high reset loads the seed,
    // otherwise the CA evolves one step per rising clock edge.
    always_ff @(posedge clock) begin
        if (reset)
            CA_out <= CA_seed;
        else
            CA_out <= next_state;
    end

endmodule

module pseudoRandGenerator_ca (
    input  logic        clock,    // Clock input
    input  logic        reset,    // Active-high synchronous Reset
    input  logic [15:0] CA_seed,  // 16-bit Cellular Automata seed
    output logic [15:0] CA_out     // 16-bit Cellular Automata output
);

    logic q1, q2, q3, q4, q5, q6, q7, q8;
    logic q9, q10, q11, q12, q13, q14, q15, q16;

    assign q1  = CA_out[14];
    assign q2  = CA_out[15] ^ CA_out[13];
    assign q3  = CA_out[14] ^ CA_out[13] ^ CA_out[12];
    assign q4  = CA_out[13] ^ CA_out[11];
    assign q5  = CA_out[12] ^ CA_out[11] ^ CA_out[10];
    assign q6  = CA_out[11] ^ CA_out[9];
    assign q7  = CA_out[10] ^ CA_out[9] ^ CA_out[8];
    assign q8  = CA_out[9] ^ CA_out[7];
    assign q9  = CA_out[8] ^ CA_out[7] ^ CA_out[6];
    assign q10 = CA_out[7] ^ CA_out[5];
    assign q11 = CA_out[6] ^ CA_out[5] ^ CA_out[4];
    assign q12 = CA_out[5] ^ CA_out[3];
    assign q13 = CA_out[4] ^ CA_out[3] ^ CA_out[2];
    assign q14 = CA_out[3] ^ CA_out[1];
    assign q15 = CA_out[2] ^ CA_out[1] ^ CA_out[0];
    assign q16 = CA_out[1];

    always_ff @(posedge clock) begin
        if (reset) begin
            CA_out <= CA_seed;
        end else begin
            CA_out[15] <= q1;
            CA_out[14] <= q2;
            CA_out[13] <= q3;
            CA_out[12] <= q4;
            CA_out[11] <= q5;
            CA_out[10] <= q6;
            CA_out[9]  <= q7;
            CA_out[8]  <= q8;
            CA_out[7]  <= q9;
            CA_out[6]  <= q10;
            CA_out[5]  <= q11;
            CA_out[4]  <= q12;
            CA_out[3]  <= q13;
            CA_out[2]  <= q14;
            CA_out[1]  <= q15;
            CA_out[0]  <= q16;
        end
    end

endmodule

module clock_divider (
    input  wire       clk,
    input  wire       rst_n,
    input  wire [1:0] sel,
    output reg        clk_out
);

    // Divide-by-2/4/8 with 50% duty cycle.
    // All divisors are even powers of two, so the simple single-posedge
    // counter form applies: toggle clk_out when the counter reaches
    // (divisor/2 - 1), i.e. after 'half' input clocks per half-period.
    //   sel = 2'b00 -> /2  (half = 1)
    //   sel = 2'b01 -> /4  (half = 2)
    //   sel = 2'b10 -> /8  (half = 4)
    //   sel = 2'b11 -> invalid -> clk_out held at 0

    reg [2:0] half;
    reg [2:0] counter;

    always @(*) begin
        case (sel)
            2'b00:   half = 3'd1;
            2'b01:   half = 3'd2;
            2'b10:   half = 3'd4;
            default: half = 3'd0; // invalid selection
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 3'd0;
            clk_out <= 1'b0;
        end else if (half == 3'd0) begin
            // Out-of-range sel: hold output at 0.
            counter <= 3'd0;
            clk_out <= 1'b0;
        end else if (counter == (half - 3'd1)) begin
            counter <= 3'd0;
            clk_out <= ~clk_out;
        end else begin
            counter <= counter + 3'd1;
        end
    end

endmodule


