module clock_jitter_detection_module #(
    parameter JITTER_THRESHOLD = 5    // Threshold (in clock cycles) for detecting jitter
)(
    input logic clk,               // Input clock
    input logic system_clk,        // Input system clock
    input logic rst,               // Active high reset
    output logic jitter_detected   // Output flag indicating jitter detection
);

    // Internal signals
    logic [31:0] edge_count, edge_count_r;   // Counters to measure time between rising edges
    logic prev_system_clk;                   // To store the previous clock state (rising edge detection)
    logic edge_detected;                     // Flag for detecting rising edges
    logic start_counter;                     // Indicates a real inter-edge interval is being measured

    // Rising edge detection logic (detects when clock transitions from 0 to 1)
    always @(posedge clk) begin
        if (rst) begin
            // Initialize counters, edge detection, and jitter detection on reset
            edge_count      <= 32'd0;
            edge_count_r    <= 32'd0;
            prev_system_clk <= 1'b0;
            edge_detected   <= 1'b0;
            start_counter   <= 1'b0;
            jitter_detected <= 1'b0;
        end else begin
            prev_system_clk <= system_clk;

            // Detect rising edge transition of system_clk (0 -> 1) using the
            // previously registered value (prev_system_clk still holds the
            // last-cycle sample because of the non-blocking update above).
            if (system_clk && !prev_system_clk) begin
                edge_detected <= 1'b1;

                // Store the just-measured interval and restart the counter.
                edge_count_r  <= edge_count;   // measured time between edges
                edge_count    <= 32'd0;        // reset counter for next interval

                if (start_counter) begin
                    // A full edge-to-edge interval has been measured in
                    // edge_count -> compare against the threshold.  Jitter is
                    // flagged when the interval deviates from JITTER_THRESHOLD
                    // by more than one clk cycle (|edge_count - THRESHOLD| > 1).
                    if (((edge_count > JITTER_THRESHOLD) ?
                             (edge_count - JITTER_THRESHOLD) :
                             (JITTER_THRESHOLD - edge_count)) > 32'd1)
                        jitter_detected <= 1'b1;
                    else
                        jitter_detected <= 1'b0;
                end else begin
                    // First observed edge only opens the measurement window;
                    // the reset-to-first-edge span is not a valid interval.
                    start_counter   <= 1'b1;
                    jitter_detected <= 1'b0;
                end
            end else begin
                edge_detected   <= 1'b0;
                edge_count      <= edge_count + 32'd1;   // count clk cycles between edges
                jitter_detected <= 1'b0;                 // one-cycle pulse: clear when no edge
            end
        end
    end

endmodule

module coffee_machine #(
    parameter NBW_DLY    = 'd5,
    parameter NBW_BEANS  = 'd2,
    parameter NS_BEANS   = 'd4,
    parameter NS_OP      = 'd3, // Fixed
    parameter NS_SENSOR  = 'd4  // Fixed
) (
    input  logic                 clk,
    input  logic                 rst_async_n,
    input  logic [NBW_DLY-1:0]   i_grind_delay,
    input  logic [NBW_DLY-1:0]   i_heat_delay,
    input  logic [NBW_DLY-1:0]   i_pour_delay,
    input  logic [NBW_BEANS-1:0] i_bean_sel,
    input  logic [NS_OP-1:0]     i_operation_sel,
    input  logic                 i_start,
    input  logic [NS_SENSOR-1:0] i_sensor,
    output logic [NS_BEANS-1:0]  o_bean_sel,
    output logic                 o_grind_beans,
    output logic                 o_use_powder,
    output logic                 o_heat_water,
    output logic                 o_pour_coffee,
    output logic                 o_error
);

// Fixed delays (bean selection and powder usage)
localparam SEL_CYCLES    = 'd3;
localparam POWDER_CYCLES = 'd2;

typedef enum logic [2:0] {
    IDLE     = 3'b000,
    BEAN_SEL = 3'b001,
    GRIND    = 3'b011,
    POWDER   = 3'b111,
    HEAT     = 3'b110,
    POUR     = 3'b100
} state_t;

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
state_t state_ff, state_nx;
logic [NBW_DLY:0]     counter_ff, counter_nx;
logic [NBW_DLY-1:0]   grind_delay_ff, heat_delay_ff, pour_delay_ff;
logic [NS_OP-1:0]     operation_sel_ff;
logic [NBW_BEANS-1:0] bean_sel_in_ff;
logic                 start_ff;

// Output assignment (error conditions)
always_comb begin : error_logic
    if(state_ff == IDLE) begin
        o_error = (i_sensor[0] | i_sensor[3])
                | (&i_operation_sel[2:1])
                | (i_operation_sel[1] & i_sensor[1])
                | (((i_operation_sel == 3'b001) || (i_operation_sel == 3'b100)) & i_sensor[2]);
    end else begin
        o_error = i_sensor[3];
    end
end

// ----------------------------------------
// - Registers
// ----------------------------------------
always_ff @(posedge clk) begin : data_regs
    // Start is only allowed when no error condition is present.
    start_ff <= i_start & ~( (i_sensor[0] | i_sensor[3])
                           | (&i_operation_sel[2:1])
                           | (i_operation_sel[1] & i_sensor[1])
                           | (((i_operation_sel == 3'b001) || (i_operation_sel == 3'b100)) & i_sensor[2]) );

    if(i_start && state_ff == IDLE) begin
        operation_sel_ff <= i_operation_sel;
        grind_delay_ff   <= i_grind_delay;
        heat_delay_ff    <= i_heat_delay;
        pour_delay_ff    <= i_pour_delay;
        bean_sel_in_ff   <= i_bean_sel;
    end

    counter_ff      <= counter_nx;
end

always_ff @(posedge clk or negedge rst_async_n) begin : reset_regs
    if(~rst_async_n) begin
        state_ff <= IDLE;
    end else begin
        state_ff <= state_nx;
    end
end

// ----------------------------------------
// - FSM update
// ----------------------------------------
always_comb begin
    case(state_ff)
        IDLE: begin
            counter_nx = 0;

            if(start_ff) begin
                if(~(|operation_sel_ff[2:1])) begin
                    state_nx = HEAT;
                end else if(operation_sel_ff[1]) begin
                    state_nx = BEAN_SEL;
                end else if(operation_sel_ff[0]) begin
                    state_nx = POUR;
                end else begin
                    state_nx = POWDER;
                end
            end else begin
                state_nx = IDLE;
            end
        end
        BEAN_SEL: begin
            if((counter_ff + 1'b1) >= SEL_CYCLES) begin
                counter_nx = 0;
                state_nx   = GRIND;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = BEAN_SEL;
            end
        end
        GRIND: begin
            if((counter_ff + 1'b1) >= grind_delay_ff) begin
                counter_nx = 0;
                if(operation_sel_ff[0]) begin
                    state_nx = POWDER;
                end else begin
                    state_nx = HEAT;
                end
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = GRIND;
            end
        end
        POWDER: begin
            if((counter_ff + 1'b1) >= POWDER_CYCLES) begin
                counter_nx = 0;
                state_nx   = POUR;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = POWDER;
            end
        end
        HEAT: begin
            if((counter_ff + 1'b1) >= heat_delay_ff) begin
                counter_nx = 0;
                if(|operation_sel_ff[1:0]) begin
                    state_nx = POWDER;
                end else begin
                    state_nx = POUR;
                end
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = HEAT;
            end
        end
        POUR: begin
            if((counter_ff + 1'b1) >= pour_delay_ff) begin
                counter_nx = 0;
                state_nx   = IDLE;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = POUR;
            end
        end
        default: begin
            counter_nx = 0;
            state_nx   = IDLE;
        end
    endcase

    // Generic error (i_sensor[3]) can happen in any state and must
    // return the FSM to IDLE. This is the only mid-operation error.
    if(i_sensor[3]) begin
        state_nx   = IDLE;
        counter_nx = 0;
    end
end

// ----------------------------------------
// - Controller outputs
// ----------------------------------------
always_comb begin
    case(state_ff)
        IDLE: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_use_powder    = 1'b0;
            o_grind_beans   = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
        BEAN_SEL: begin
            o_bean_sel                      = {NS_BEANS{1'b0}}; // Set all bits to 0
            o_bean_sel[bean_sel_in_ff]      = 1'b1; // Only the position of bean_sel_ff should be 1
            o_grind_beans                   = 1'b0;
            o_use_powder                    = 1'b0;
            o_heat_water                    = 1'b0;
            o_pour_coffee                   = 1'b0;
        end
        GRIND: begin
            o_bean_sel                      = {NS_BEANS{1'b0}};
            o_bean_sel[bean_sel_in_ff]      = 1'b1; // o_bean_sel must remain unchanged
            o_grind_beans                   = 1'b1;
            o_use_powder                    = 1'b0;
            o_heat_water                    = 1'b0;
            o_pour_coffee                   = 1'b0;
        end
        POWDER: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b1;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
        HEAT: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b1;
            o_pour_coffee   = 1'b0;
        end
        POUR: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b1;
        end
        default: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
    endcase
end

endmodule : coffee_machine

module signed_unsigned_comparator #(
    parameter WIDTH = 5
) (
    input  wire [WIDTH-1:0] i_A,
    input  wire [WIDTH-1:0] i_B,
    input  wire             i_enable,
    input  wire             i_mode,
    output wire             o_greater,
    output wire             o_less,
    output wire             o_equal
);

    // Signed interpretation (two's complement, MSB is the sign bit)
    wire signed [WIDTH-1:0] a_s = i_A;
    wire signed [WIDTH-1:0] b_s = i_B;

    // Magnitude / unsigned interpretation (full-width, MSB carries its
    // positional weight rather than being treated as a sign)
    wire [WIDTH-1:0] a_u = i_A;
    wire [WIDTH-1:0] b_u = i_B;

    wire greater_c = i_mode ? (a_s > b_s) : (a_u > b_u);
    wire less_c    = i_mode ? (a_s < b_s) : (a_u < b_u);
    wire equal_c   = i_mode ? (a_s == b_s) : (a_u == b_u);

    // Outputs are active only while i_enable is high; otherwise all low.
    assign o_greater = i_enable & greater_c;
    assign o_less    = i_enable & less_c;
    assign o_equal   = i_enable & equal_c;

endmodule


