module complex_multiplier (
    input  wire        clk,
    input  wire        arst_n,
    input  wire [15:0] a_real,
    input  wire [15:0] a_imag,
    input  wire [15:0] b_real,
    input  wire [15:0] b_imag,
    output reg  [31:0] result_real,
    output reg  [31:0] result_imag
);

    // Treat the real/imaginary components as signed (two's complement)
    // per the complex-number multiplication of real-valued components.
    wire signed [15:0] a_real_s = a_real;
    wire signed [15:0] a_imag_s = a_imag;
    wire signed [15:0] b_real_s = b_real;
    wire signed [15:0] b_imag_s = b_imag;

    // Signed 16x16 products fit exactly in 32 bits.
    wire signed [31:0] ac = a_real_s * b_real_s; // a*c
    wire signed [31:0] bd = a_imag_s * b_imag_s; // b*d
    wire signed [31:0] ad = a_real_s * b_imag_s; // a*d
    wire signed [31:0] bc = a_imag_s * b_real_s; // b*c

    // (a+bj)*(c+dj) = (ac - bd) + (ad + bc)j
    // Registered outputs -> one cycle of latency.
    always @(posedge clk or negedge arst_n) begin
        if (!arst_n) begin
            result_real <= 32'd0;
            result_imag <= 32'd0;
        end else begin
            result_real <= ac - bd;
            result_imag <= ad + bc;
        end
    end

endmodule


