module compression_engine (
  input   logic        clk,
  input   logic        reset,
  input   logic [23:0] num_i,
  output  logic [11:0] mantissa_o,
  output  logic [3:0]  exponent_o
);

  // --------------------------------------------------------
  // Internal wires and registers
  // --------------------------------------------------------
  logic [23:12] exp_oh;         // One-hot encoded exponent (covers bits 23..12)
  logic [3:0]   exp_bin;        // Binary exponent
  logic [3:0]   exponent;       // Adjusted exponent
  logic [11:0]  mantissa;       // Mantissa

  // --------------------------------------------------------
  // One-Hot Encoding of the Exponent
  //   exp_oh[i] = num_i[i] & ~|num_i[23:i+1]
  //   Marks the first set bit from the MSB, but only within bits [23:12].
  //   If the MSB lies in the low 12 bits (or num_i==0), exp_oh is all zero.
  // --------------------------------------------------------
  assign exp_oh[23] = num_i[23];

  genvar gi;
  generate
    for (gi = 12; gi <= 22; gi = gi + 1) begin : gen_exp_oh
      assign exp_oh[gi] = num_i[gi] & ~(|num_i[23:gi+1]);
    end
  endgenerate

  // Convert one-hot to binary exponent
  onehot_to_bin #(
    .ONE_HOT_W(12),
    .BIN_W(4)
  ) exp_oh_bin (
    .oh_vec_i(exp_oh),
    .bin_vec_o(exp_bin)
  );

  assign exponent = (|exp_oh) ? exp_bin + 4'h1 : exp_bin;

  // --------------------------------------------------------
  // Mantissa Extraction Logic
  //   The 12 most-significant bits starting at (and including) the first
  //   set bit.  With exponent = MSB_position - 11 (0 when the MSB is in the
  //   low 12 bits or the input is zero), the window num_i[exponent+11:exponent]
  //   equals the low 12 bits of (num_i >> exponent).  For exponent == 0 this
  //   reduces to num_i[11:0], covering the low-12-bit and all-zero cases.
  //   (A variable indexed part-select in an always block is not simulated
  //    correctly by Icarus, so a variable-amount shift is used instead.)
  // --------------------------------------------------------
  always_comb begin
    mantissa = num_i >> exponent;   // implicitly truncated to 12 bits
  end

  // --------------------------------------------------------
  // Output assignments (registered, single-cycle latency)
  // --------------------------------------------------------
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      exponent_o <= 4'd0;
      mantissa_o <= 12'd0;
    end else begin
      exponent_o <= exponent;
      mantissa_o <= mantissa;
    end
  end

endmodule

module onehot_to_bin #(
  parameter ONE_HOT_W = 32,  // Width of the one-hot input
  parameter BIN_W     = 5    // Width of the binary output
)(
  input   wire [ONE_HOT_W-1:0]  oh_vec_i,  // One-hot encoded input
  output  logic [BIN_W-1:0]     bin_vec_o  // Binary encoded output
);

  // For a one-hot input, output bit k is set iff the set position j has
  // bit k of its index set:  bin_vec_o[k] = OR_j ( oh_vec_i[j] & j[k] ).
  // All selects use elaboration-time-constant genvar indices, so this is
  // simulated correctly (unlike a variable bit-select inside an always).
  genvar k, j;
  generate
    for (k = 0; k < BIN_W; k = k + 1) begin : gen_obit
      wire [ONE_HOT_W-1:0] masked;
      for (j = 0; j < ONE_HOT_W; j = j + 1) begin : gen_mask
        assign masked[j] = oh_vec_i[j] & (((j >> k) & 1) != 0);
      end
      assign bin_vec_o[k] = |masked;
    end
  endgenerate

endmodule

// enhanced_fsm_signal_processor
// FSM-managed signal processing with fault handling and status reporting.
// States: IDLE(00), PROCESS(01), READY(10), FAULT(11).
module enhanced_fsm_signal_processor (
    input  wire       i_clk,
    input  wire       i_rst_n,
    input  wire       i_enable,
    input  wire       i_clear,
    input  wire       i_ack,
    input  wire       i_fault,
    input  wire [4:0] i_vector_1,
    input  wire [4:0] i_vector_2,
    input  wire [4:0] i_vector_3,
    input  wire [4:0] i_vector_4,
    input  wire [4:0] i_vector_5,
    input  wire [4:0] i_vector_6,
    output reg        o_ready,
    output reg        o_error,
    output wire [1:0] o_fsm_status,
    output reg  [7:0] o_vector_1,
    output reg  [7:0] o_vector_2,
    output reg  [7:0] o_vector_3,
    output reg  [7:0] o_vector_4
);

    // FSM state encoding
    localparam [1:0] IDLE    = 2'b00,
                     PROCESS = 2'b01,
                     READY   = 2'b10,
                     FAULT   = 2'b11;

    reg [1:0] state;

    // Current FSM state reported directly (synchronous, follows the state reg)
    assign o_fsm_status = state;

    // Concatenate the six 5-bit vectors (30 bits) and append two '1' bits at
    // the LSB to form a 32-bit bus, MSB->LSB across o_vector_1..o_vector_4.
    wire [31:0] concat_bus;
    assign concat_bus = {i_vector_1, i_vector_2, i_vector_3,
                         i_vector_4, i_vector_5, i_vector_6, 2'b11};

    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            state      <= IDLE;
            o_ready    <= 1'b0;
            o_error    <= 1'b0;
            o_vector_1 <= 8'd0;
            o_vector_2 <= 8'd0;
            o_vector_3 <= 8'd0;
            o_vector_4 <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    o_ready <= 1'b0;
                    o_error <= 1'b0;
                    if (i_fault) begin
                        state      <= FAULT;
                        o_error    <= 1'b1;
                        o_ready    <= 1'b0;
                        o_vector_1 <= 8'd0;
                        o_vector_2 <= 8'd0;
                        o_vector_3 <= 8'd0;
                        o_vector_4 <= 8'd0;
                    end else if (i_clear) begin
                        o_vector_1 <= 8'd0;
                        o_vector_2 <= 8'd0;
                        o_vector_3 <= 8'd0;
                        o_vector_4 <= 8'd0;
                    end else if (i_enable) begin
                        state <= PROCESS;
                    end
                end

                PROCESS: begin
                    if (i_fault) begin
                        state      <= FAULT;
                        o_error    <= 1'b1;
                        o_ready    <= 1'b0;
                        o_vector_1 <= 8'd0;
                        o_vector_2 <= 8'd0;
                        o_vector_3 <= 8'd0;
                        o_vector_4 <= 8'd0;
                    end else begin
                        o_vector_1 <= concat_bus[31:24];
                        o_vector_2 <= concat_bus[23:16];
                        o_vector_3 <= concat_bus[15:8];
                        o_vector_4 <= concat_bus[7:0];
                        state      <= READY;
                    end
                end

                READY: begin
                    if (i_fault) begin
                        state      <= FAULT;
                        o_error    <= 1'b1;
                        o_ready    <= 1'b0;
                        o_vector_1 <= 8'd0;
                        o_vector_2 <= 8'd0;
                        o_vector_3 <= 8'd0;
                        o_vector_4 <= 8'd0;
                    end else begin
                        o_ready <= 1'b1;
                        if (i_ack) begin
                            o_ready <= 1'b0;
                            state   <= IDLE;
                        end
                    end
                end

                FAULT: begin
                    o_error <= 1'b1;
                    o_ready <= 1'b0;
                    o_vector_1 <= 8'd0;
                    o_vector_2 <= 8'd0;
                    o_vector_3 <= 8'd0;
                    o_vector_4 <= 8'd0;
                    if (!i_fault && i_clear) begin
                        state   <= IDLE;
                        o_error <= 1'b0;
                    end
                end

                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module low_pass_filter #(
    parameter DATA_WIDTH  = 16,
    parameter COEFF_WIDTH = 16,
    parameter NUM_TAPS    = 8,
    parameter NBW_MULT    = DATA_WIDTH + COEFF_WIDTH
)(
    input  wire                                          clk,
    input  wire                                          reset,
    input  wire [DATA_WIDTH*NUM_TAPS-1:0]                data_in,
    input  wire                                          valid_in,
    input  wire [COEFF_WIDTH*NUM_TAPS-1:0]               coeffs,
    output wire signed [NBW_MULT+$clog2(NUM_TAPS)-1:0]   data_out,
    output reg                                           valid_out
);

    // -----------------------------------------------------------------
    // Registered inputs (flip-flops). Captured only when valid_in is
    // high; otherwise the previously registered values are held.
    // Synchronous active-high reset clears them to zero.
    // -----------------------------------------------------------------
    reg [DATA_WIDTH*NUM_TAPS-1:0]  data_reg;
    reg [COEFF_WIDTH*NUM_TAPS-1:0] coeff_reg;

    always @(posedge clk) begin
        if (reset) begin
            data_reg  <= {(DATA_WIDTH*NUM_TAPS){1'b0}};
            coeff_reg <= {(COEFF_WIDTH*NUM_TAPS){1'b0}};
            valid_out <= 1'b0;
        end else begin
            valid_out <= valid_in;               // one-cycle registered valid
            if (valid_in) begin
                data_reg  <= data_in;
                coeff_reg <= coeffs;
            end
        end
    end

    // -----------------------------------------------------------------
    // Combinational convolution on the REGISTERED inputs.
    // data tap i is multiplied by coefficient tap (NUM_TAPS-1-i)
    // (coefficients applied in reverse order). Signed arithmetic.
    // -----------------------------------------------------------------
    integer i;
    reg signed [DATA_WIDTH-1:0]                      d_slice;
    reg signed [COEFF_WIDTH-1:0]                     c_slice;
    reg signed [NBW_MULT-1:0]                        prod;
    reg signed [NBW_MULT+$clog2(NUM_TAPS)-1:0]       acc;

    always @(*) begin
        acc = {(NBW_MULT+$clog2(NUM_TAPS)){1'b0}};
        for (i = 0; i < NUM_TAPS; i = i + 1) begin
            d_slice = data_reg [i*DATA_WIDTH                 +: DATA_WIDTH ];
            c_slice = coeff_reg[(NUM_TAPS-1-i)*COEFF_WIDTH   +: COEFF_WIDTH];
            prod    = d_slice * c_slice;
            acc     = acc + prod;
        end
    end

    assign data_out = acc;

endmodule


