// advanced_decimator_with_adaptive_peak_detection
// Data decimation + adaptive peak detection.
// Packing convention (fixed by the spec example):
//   data_in  = {sample[0], sample[1], ..., sample[N-1]}  -> sample[0] at MSB
//   data_out = {dec[0], dec[1], ..., dec[DEC_N-1]}        -> dec[0]   at MSB
// Input-to-output latency is fixed at 1 clock cycle: data_in is registered,
// then unpacking / decimation / peak / packing are purely combinational.

module advanced_decimator_with_adaptive_peak_detection #(
    parameter integer N          = 8,   // total number of input samples (> 1)
    parameter integer DATA_WIDTH = 16,  // bit-width of each sample (> 1)
    parameter integer DEC_FACTOR = 4    // decimation factor (integer divisor of N)
) (
    input  wire                                 clk,        // rising-edge clock
    input  wire                                 reset,      // async, active-high
    input  wire                                 valid_in,   // input data valid
    input  wire [DATA_WIDTH*N-1:0]              data_in,    // packed N signed samples
    output reg                                  valid_out,  // output data valid
    output wire [DATA_WIDTH*(N/DEC_FACTOR)-1:0] data_out,   // packed decimated samples
    output wire [DATA_WIDTH-1:0]                peak_value  // peak among decimated samples
);

    // Number of decimated output samples.
    localparam integer DEC_N = N / DEC_FACTOR;

    genvar gi;

    // 1. Input Data Registering -------------------------------------------------
    reg [DATA_WIDTH*N-1:0] data_reg;
    always @(posedge clk or posedge reset) begin
        if (reset)
            data_reg <= {(DATA_WIDTH*N){1'b0}};
        else
            data_reg <= data_in;
    end

    // 2. Input Unpacking (combinational) ---------------------------------------
    //    sample[0] occupies the most-significant slice of the bus.
    wire signed [DATA_WIDTH-1:0] samples [0:N-1];
    generate
        for (gi = 0; gi < N; gi = gi + 1) begin : g_unpack
            assign samples[gi] = data_reg[DATA_WIDTH*(N-1-gi) +: DATA_WIDTH];
        end
    endgenerate

    // 3. Decimation (combinational) --------------------------------------------
    //    Select one sample every DEC_FACTOR positions.
    wire signed [DATA_WIDTH-1:0] decimated [0:DEC_N-1];
    generate
        for (gi = 0; gi < DEC_N; gi = gi + 1) begin : g_decimate
            assign decimated[gi] = samples[gi*DEC_FACTOR];
        end
    endgenerate

    // 4. Peak Detection (combinational) ----------------------------------------
    //    Signed maximum over the decimated samples.
    integer index;
    reg signed [DATA_WIDTH-1:0] peak_comb;
    always @(*) begin
        peak_comb = decimated[0];
        for (index = 1; index < DEC_N; index = index + 1) begin
            if (decimated[index] > peak_comb)
                peak_comb = decimated[index];
        end
    end
    assign peak_value = peak_comb;

    // 5. Output Packing (combinational) ----------------------------------------
    //    dec[0] occupies the most-significant slice of the bus.
    generate
        for (gi = 0; gi < DEC_N; gi = gi + 1) begin : g_pack
            assign data_out[DATA_WIDTH*(DEC_N-1-gi) +: DATA_WIDTH] = decimated[gi];
        end
    endgenerate

    // 6. Validation Control (sequential) ---------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset)
            valid_out <= 1'b0;
        else
            valid_out <= valid_in;
    end

endmodule


