module sgd_linear_regression #(
    parameter DATA_WIDTH = 16,
    parameter LEARNING_RATE = 3'd1
) (
    input  logic clk,                               // Clock
    input  logic reset,                             // Asynchronous reset
    input  logic signed [DATA_WIDTH-1:0] x_in,      // Input data (x)
    input  logic signed [DATA_WIDTH-1:0] y_true,    // True output (target)
    output logic signed [DATA_WIDTH-1:0] w,     // Trained weight
    output logic signed [DATA_WIDTH-1:0] b      // Trained bias
);
    localparam NBW_PRED  = 2*DATA_WIDTH + 1;
    localparam NBW_ERROR = NBW_PRED + 1;
    localparam NBW_DELTA = 3 + NBW_ERROR + DATA_WIDTH;

    // Intermediate values
    logic signed [NBW_PRED-1:0]  y_pred;
    logic signed [NBW_ERROR-1:0] error;
    logic signed [NBW_DELTA-1:0] delta_w;
    logic signed [NBW_DELTA-1:0] delta_b;

    // Predicted output calculation
    always_comb begin
      y_pred = (w * x_in) + b;
    end

    // Error calculation (combinational)
    //   error = y_true - y_pred
    always_comb begin
      error = y_true - y_pred;
    end

    // Weight / bias update terms (combinational)
    //   delta_w = LEARNING_RATE * error * x_in
    //   delta_b = LEARNING_RATE * error
    // LEARNING_RATE is cast to signed so the multiplications stay signed
    // (any unsigned operand would force the whole expression unsigned and
    //  corrupt negative operands).  The wide NBW_DELTA target prevents
    //  overflow of the two chained multiplications.
    always_comb begin
      delta_w = error * x_in * $signed(LEARNING_RATE);
      delta_b = error * $signed(LEARNING_RATE);
    end

    // Register update (sequential, asynchronous active-high reset).
    // w/b keep the DATA_WIDTH least-significant bits of the wide sum.
    always_ff @(posedge clk or posedge reset) begin
      if (reset) begin
        w <= '0;
        b <= '0;
      end else begin
        w <= w + delta_w;
        b <= b + delta_b;
      end
    end

endmodule

module fsm_linear_reg #(
    parameter DATA_WIDTH = 16
)(
    input  wire                           clk,
    input  wire                           reset,   // asynchronous, active high
    input  wire                           start,
    input  wire signed [DATA_WIDTH-1:0]   x_in,
    input  wire signed [DATA_WIDTH-1:0]   w_in,
    input  wire signed [DATA_WIDTH-1:0]   b_in,
    output reg  signed [2*DATA_WIDTH-1:0] result1,
    output reg  signed [DATA_WIDTH:0]     result2,
    output reg                            done
);

    // -----------------------------------------------------------------
    // State encoding
    // -----------------------------------------------------------------
    localparam [1:0] IDLE    = 2'd0,
                     COMPUTE = 2'd1,
                     DONE    = 2'd2;

    reg [1:0] state, next_state;

    // -----------------------------------------------------------------
    // Next-state logic (combinational)
    // -----------------------------------------------------------------
    always @(*) begin
        case (state)
            IDLE:    next_state = start ? COMPUTE : IDLE;
            COMPUTE: next_state = DONE;
            DONE:    next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // -----------------------------------------------------------------
    // State register + registered outputs (async active-high reset).
    //
    // Timeline (start held at 1, sampled from cycle 0):
    //   c0 IDLE      -> c1 COMPUTE
    //   c1 COMPUTE   -> c2 DONE   : result1/result2 updated at edge (visible c2)  => 2-cycle latency
    //   c2 DONE      -> c3 IDLE   : done set at edge (visible c3)                  => 3-cycle latency
    //   c3 IDLE      : done cleared (done high for exactly 1 cycle)
    // -----------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state   <= IDLE;
            result1 <= {(2*DATA_WIDTH){1'b0}};
            result2 <= {(DATA_WIDTH+1){1'b0}};
            done    <= 1'b0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    result1 <= {(2*DATA_WIDTH){1'b0}};
                    result2 <= {(DATA_WIDTH+1){1'b0}};
                    done    <= 1'b0;
                end
                COMPUTE: begin
                    result1 <= (w_in * x_in) >>> 1;
                    result2 <= b_in + (x_in >>> 2);
                    done    <= 1'b0;
                end
                DONE: begin
                    done    <= 1'b1;   // hold result1/result2, pulse done
                end
                default: begin
                    result1 <= {(2*DATA_WIDTH){1'b0}};
                    result2 <= {(DATA_WIDTH+1){1'b0}};
                    done    <= 1'b0;
                end
            endcase
        end
    end

endmodule


