module continuous_adder #(
    parameter DATA_WIDTH      = 32, // Width of data_in, sum_out and internal registers
    parameter THRESHOLD_VALUE = 100, // Threshold used to decide when to output sum_out
    parameter SIGNED_INPUTS   = 1   // 1 = signed arithmetic, 0 = unsigned behavior
)(
    input  logic                    clk,        // Clock signal
    input  logic                    reset,      // Reset signal, Active high and Synchronous
    input  logic [DATA_WIDTH-1:0]   data_in,    // Input data stream
    input  logic                    data_valid, // Input data valid signal
    output logic [DATA_WIDTH-1:0]   sum_out,    // Output the accumulated sum
    output logic                    sum_ready   // Signal to indicate sum is output and accumulator is reset
);

    logic [DATA_WIDTH-1:0] sum_accum; // Internal accumulator to store the running sum
    logic [DATA_WIDTH-1:0] next_sum;  // Combinational next accumulated value
    logic                  threshold_met;

    // Combinational computation of the next sum and threshold decision.
    always_comb begin
        // Two's-complement addition is bit-identical for signed and unsigned.
        next_sum = sum_accum + data_in;

        if (SIGNED_INPUTS != 0) begin
            // Signed: trigger when the sum is >= +THRESHOLD_VALUE or <= -THRESHOLD_VALUE.
            threshold_met = ($signed(next_sum) >= $signed(THRESHOLD_VALUE)) ||
                            ($signed(next_sum) <= -$signed(THRESHOLD_VALUE));
        end else begin
            // Unsigned: trigger only on the positive threshold.
            threshold_met = (next_sum >= THRESHOLD_VALUE);
        end
    end

    // Sequential logic for sum accumulation (synchronous, active-high reset).
    always_ff @(posedge clk) begin
        if (reset) begin
            // On reset, clear the accumulator and sum_ready.
            sum_accum <= {DATA_WIDTH{1'b0}};
            sum_ready <= 1'b0;
        end
        else begin
            if (data_valid) begin
                if (threshold_met) begin
                    // Output the current sum and reset the accumulator.
                    sum_out   <= next_sum;
                    sum_ready <= 1'b1;
                    sum_accum <= {DATA_WIDTH{1'b0}};
                end
                else begin
                    // Continue accumulating; no output until the threshold is reached.
                    sum_accum <= next_sum;
                    sum_ready <= 1'b0;
                end
            end
            else begin
                // No valid input this cycle: hold the accumulator, clear ready.
                sum_ready <= 1'b0;
            end
        end
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    sum_out = 0;
  end

endmodule

module continuous_adder #(
    parameter DATA_WIDTH        = 32,   // Configurable bit-width of data/accumulators
    parameter THRESHOLD_VALUE_1 = 50,   // First threshold value
    parameter THRESHOLD_VALUE_2 = 100,  // Second threshold value
    parameter SIGNED_INPUTS     = 1,    // 1 = signed arithmetic, 0 = unsigned
    parameter ACCUM_MODE        = 0,    // 0 = threshold-based, 1 = window-based
    parameter WEIGHT            = 1     // Multiplicative weight applied to each input
) (
    input  logic                          clk,          // Clock signal
    input  logic                          reset,        // Active-high, synchronous reset
    input  logic signed [DATA_WIDTH-1:0]  data_in,      // Input data stream
    input  logic                          data_valid,   // Input data valid
    input  logic        [15:0]            window_size,  // Window size (ACCUM_MODE = 1 only)
    output logic signed [DATA_WIDTH-1:0]  sum_out,      // Accumulated sum output
    output logic signed [DATA_WIDTH-1:0]  avg_out,      // Average output (ACCUM_MODE = 1 only)
    output logic                          threshold_1,  // High when |sum| crossed THRESHOLD_VALUE_1
    output logic                          threshold_2,  // High when |sum| crossed THRESHOLD_VALUE_2
    output logic                          sum_ready     // High when sum_out (and avg_out) valid
);

    // Internal accumulator and sample counter
    logic signed [DATA_WIDTH-1:0] sum_accum;
    logic        [15:0]           sample_count;

    // Combinational helpers
    logic signed [DATA_WIDTH-1:0] weighted_input;
    logic signed [DATA_WIDTH-1:0] new_sum;
    logic                         t1_comb;
    logic                         t2_comb;
    logic        [15:0]           sc_next;

    // weighted_input = data_in * WEIGHT (low DATA_WIDTH bits hold the correct 2's complement)
    assign weighted_input = data_in * WEIGHT;
    assign new_sum        = sum_accum + weighted_input;
    assign sc_next        = sample_count + 16'd1;

    // Threshold crossing detection, evaluated on the value being accumulated (new_sum).
    // For signed inputs, cross when new_sum >= +TH or new_sum <= -TH.
    assign t1_comb = (SIGNED_INPUTS != 0)
                   ? ((new_sum >= THRESHOLD_VALUE_1) || (new_sum <= -THRESHOLD_VALUE_1))
                   : ($unsigned(new_sum) >= THRESHOLD_VALUE_1);
    assign t2_comb = (SIGNED_INPUTS != 0)
                   ? ((new_sum >= THRESHOLD_VALUE_2) || (new_sum <= -THRESHOLD_VALUE_2))
                   : ($unsigned(new_sum) >= THRESHOLD_VALUE_2);

    always_ff @(posedge clk) begin
        if (reset) begin
            sum_accum    <= '0;
            sample_count <= '0;
            sum_out      <= '0;
            avg_out      <= '0;
            threshold_1  <= 1'b0;
            threshold_2  <= 1'b0;
            sum_ready    <= 1'b0;
        end else begin
            // Default: deassert sum_ready unless we output this cycle
            sum_ready <= 1'b0;

            if (data_valid) begin
                // Threshold outputs track the current (post-add) accumulated value
                threshold_1 <= t1_comb;
                threshold_2 <= t2_comb;

                if (ACCUM_MODE == 0) begin
                    // ------- Threshold-based continuous accumulation -------
                    // Accumulator keeps growing; it is NOT reset on a crossing.
                    sum_accum <= new_sum;
                    if (t1_comb || t2_comb) begin
                        sum_out   <= new_sum;   // publish the accumulated sum
                        sum_ready <= 1'b1;
                    end
                end else begin
                    // ------- Window-based accumulation with averaging -------
                    if (sc_next == window_size) begin
                        sum_out      <= new_sum;
                        if (SIGNED_INPUTS != 0)
                            avg_out <= new_sum / $signed({1'b0, window_size});
                        else
                            avg_out <= $unsigned(new_sum) / window_size;
                        sum_ready    <= 1'b1;
                        sum_accum    <= '0;    // reset accumulator after window
                        sample_count <= '0;    // reset sample counter after window
                    end else begin
                        sum_accum    <= new_sum;
                        sample_count <= sc_next;
                    end
                end
            end
        end
    end

endmodule

module cont_adder #(
    parameter DATA_WIDTH = 32,
    parameter signed THRESHOLD_VALUE_1 = 50,
    parameter signed THRESHOLD_VALUE_2 = 100,
    parameter SIGNED_INPUTS = 1,
    parameter ACCUM_MODE = 0,
    parameter WEIGHT = 1
) (
    input  logic                         clk,
    input  logic                         reset,
    input  logic signed [DATA_WIDTH-1:0] data_in,
    input  logic                         data_valid,
    input  logic [15:0]                  window_size,
    output logic signed [DATA_WIDTH-1:0] sum_out,
    output logic signed [DATA_WIDTH-1:0] avg_out,
    output logic                         threshold_1,
    output logic                         threshold_2,
    output logic                         sum_ready
);

    // Sequential Registers
    logic signed [DATA_WIDTH+1:0] sum_accum;
    logic [15:0]                  sample_count;

    // Combinational Signals
    logic signed [DATA_WIDTH-1:0] weighted_input;
    // Sign-extended (DATA_WIDTH+2)-bit view of the DATA_WIDTH-bit weighted_input,
    // so that additions against the (DATA_WIDTH+2)-bit sum_accum are width-matched.
    // This is exactly the implicit sign extension the original relied on, made
    // explicit to satisfy the lint width checks without changing behaviour.
    logic signed [DATA_WIDTH+1:0] weighted_input_ext;
    logic signed [DATA_WIDTH-1:0] new_sum;
    logic                         threshold_1_comb;
    logic                         threshold_2_comb;
    logic                         sum_ready_reg;

    // Combinational Logic
    always_comb begin
        sum_ready_reg = 1'b0;

        // Weighted input. The retained low DATA_WIDTH bits of the product are
        // identical regardless of the SIGNED_INPUTS selection (the low-order
        // bits of a two's-complement multiply are sign-agnostic), preserving
        // the original behaviour while explicitly using the parameter and
        // making the truncation explicit.
        if (SIGNED_INPUTS)
            weighted_input = DATA_WIDTH'($signed(data_in) * WEIGHT);
        else
            weighted_input = DATA_WIDTH'($unsigned(data_in) * WEIGHT);

        // Explicit sign extension to the accumulator width.
        weighted_input_ext = (DATA_WIDTH+2)'(weighted_input);

        new_sum = DATA_WIDTH'(sum_accum + weighted_input_ext);

        threshold_1_comb = (new_sum >= THRESHOLD_VALUE_1) || (new_sum <= -THRESHOLD_VALUE_1);
        threshold_2_comb = (new_sum >= THRESHOLD_VALUE_2) || (new_sum <= -THRESHOLD_VALUE_2);

        if (data_valid) begin
            if (ACCUM_MODE == 0) begin
                if (threshold_1_comb || threshold_2_comb) begin
                    sum_ready_reg = 1'b1;
                end else begin
                    sum_ready_reg = 1'b0;
                end
            end else if (ACCUM_MODE == 1) begin
                if ((sample_count + 16'd1) >= window_size) begin
                    sum_ready_reg = 1'b1;
                end else begin
                    sum_ready_reg = 1'b0;
                end
            end
        end else begin
            sum_ready_reg = 1'b0;
        end
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            sum_accum     <= '0;
            sample_count  <= '0;
            sum_ready     <= 1'b0;
            sum_out       <= '0;
            avg_out       <= '0;
            threshold_1   <= 1'b0;
            threshold_2   <= 1'b0;
        end else if (data_valid) begin
            threshold_1 <= threshold_1_comb;
            threshold_2 <= threshold_2_comb;

            if (ACCUM_MODE == 1) begin
                sum_accum    <= sum_accum + weighted_input_ext;
                sample_count <= sample_count + 16'd1;
                if (sum_ready_reg) begin
                    sum_out      <= DATA_WIDTH'(sum_accum + weighted_input_ext);
                    avg_out      <= DATA_WIDTH'($unsigned(sum_accum + weighted_input_ext) / (DATA_WIDTH+2)'(window_size));
                    sum_ready    <= 1'b1;
                    sum_accum    <= '0;
                    sample_count <= '0;
                end else begin
                    sum_ready <= 1'b0;
                    sum_out   <= '0;
                    avg_out   <= '0;
                end
            end else begin
                sum_accum <= sum_accum + weighted_input_ext;
                if (sum_ready_reg) begin
                    sum_out   <= DATA_WIDTH'(sum_accum + weighted_input_ext);
                    sum_ready <= 1'b1;
                end else begin
                    sum_ready <= 1'b0;
                    sum_out   <= '0;
                end
                avg_out <= '0;
            end
        end else begin
            sum_ready <= 1'b0;
        end
    end

endmodule

module cont_adder #(
  parameter DATA_WIDTH = 32,
  parameter signed THRESHOLD_VALUE_1 = 50,
  parameter signed THRESHOLD_VALUE_2 = 100,
  parameter signed THRESHOLD_VALUE_3 = 150,
  parameter ACCUM_MODE = 0,
  parameter WEIGHT = 1,
  parameter signed SAT_MAX = (2**(DATA_WIDTH-1))-1,
  parameter signed SAT_MIN = -(2**(DATA_WIDTH-1))
) (
  input  logic                         clk,
  input  logic                         reset,
  input  logic                         accum_clear,
  input  logic                         enable,
  input  logic signed [DATA_WIDTH-1:0] data_in,
  input  logic                         data_valid,
  input  logic [15:0]                  window_size,
  output logic signed [DATA_WIDTH-1:0] sum_out,
  output logic signed [DATA_WIDTH-1:0] avg_out,
  output logic                         threshold_1,
  output logic                         threshold_2,
  output logic                         threshold_3,
  output logic                         sum_ready,
  output logic                         busy
);

  // Crossing any of the three thresholds ((sat_sum >= TVk) || (sat_sum <= -TVk),
  // for k = 1,2,3) is EXACTLY equivalent to crossing the smallest-magnitude
  // threshold: (sat_sum >= min(TVk)) || (sat_sum <= -min(TVk)).  This identity
  // holds for any parameter values and lets 6 comparators collapse to 2.
  localparam signed TH_MIN =
      (THRESHOLD_VALUE_1 <= THRESHOLD_VALUE_2)
        ? ((THRESHOLD_VALUE_1 <= THRESHOLD_VALUE_3) ? THRESHOLD_VALUE_1 : THRESHOLD_VALUE_3)
        : ((THRESHOLD_VALUE_2 <= THRESHOLD_VALUE_3) ? THRESHOLD_VALUE_2 : THRESHOLD_VALUE_3);

  typedef enum logic [1:0] {IDLE, ACCUM, DONE} state_t;
  state_t state;
  logic signed [DATA_WIDTH-1:0] sum_accum;
  logic [15:0] sample_count;
  logic signed [DATA_WIDTH-1:0] weighted_in_reg;
  logic signed [DATA_WIDTH-1:0] sat_sum;

  // Registered weighted sample (WEIGHT==1 => no multiplier).
  always_ff @(posedge clk or posedge reset) begin
    if (reset)
      weighted_in_reg <= 0;
    else if (enable && data_valid) begin
      if (WEIGHT == 1)
        weighted_in_reg <= data_in;
      else
        weighted_in_reg <= data_in * WEIGHT;
    end
  end

  // Saturation removed: with the default full-range SAT_MAX/SAT_MIN the sum is
  // formed in DATA_WIDTH-wide arithmetic and can never leave [SAT_MIN,SAT_MAX],
  // so the clamp is dead logic.  (The dead 'new_sum' register is also dropped.)
  always_ff @(posedge clk or posedge reset) begin
    if (reset)
      sat_sum <= 0;
    else if (enable && data_valid)
      sat_sum <= sum_accum + weighted_in_reg;
  end

  // FSM + running accumulator + sample counter (behaviour unchanged).
  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      sum_accum <= 0;
      sample_count <= 0;
    end else if (accum_clear) begin
      state <= IDLE;
      sum_accum <= 0;
      sample_count <= 0;
    end else if (enable && data_valid) begin
      case (state)
        IDLE: begin
          state <= ACCUM;
          sum_accum <= sat_sum;
          sample_count <= 1;
        end
        ACCUM: begin
          sum_accum <= sat_sum;
          sample_count <= sample_count + 1;
          if (ACCUM_MODE == 1) begin
            if ((sample_count + 1) >= window_size)
              state <= DONE;
          end else begin
            if ((sat_sum >= TH_MIN) || (sat_sum <= -TH_MIN))
              state <= DONE;
          end
        end
        DONE: begin
          state <= IDLE;
          sum_accum <= 0;
          sample_count <= 0;
        end
        default: state <= IDLE;
      endcase
    end
  end

  // Output register stage (behaviour unchanged).
  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      sum_out <= 0;
      avg_out <= 0;
      sum_ready <= 0;
      threshold_1 <= 0;
      threshold_2 <= 0;
      threshold_3 <= 0;
      busy <= 0;
    end else begin
      busy <= (state == ACCUM);
      if (state == DONE) begin
        sum_out <= sum_accum;
        avg_out <= (ACCUM_MODE == 1) ? (sum_accum / sample_count) : 0;
        sum_ready <= 1;
        threshold_1 <= (sum_accum >= THRESHOLD_VALUE_1) || (sum_accum <= -THRESHOLD_VALUE_1);
        threshold_2 <= (sum_accum >= THRESHOLD_VALUE_2) || (sum_accum <= -THRESHOLD_VALUE_2);
        threshold_3 <= (sum_accum >= THRESHOLD_VALUE_3) || (sum_accum <= -THRESHOLD_VALUE_3);
      end else begin
        sum_out <= 0;
        avg_out <= 0;
        sum_ready <= 0;
        threshold_1 <= 0;
        threshold_2 <= 0;
        threshold_3 <= 0;
      end
    end
  end

endmodule

module convolutional_encoder (
    input  wire clk,
    input  wire rst,
    input  wire data_in,
    output reg  encoded_bit1,
    output reg  encoded_bit2
);

    // Constraint length K = 3: the encoder uses the current input bit
    // (data_in) together with the previous two input bits held in a
    // 2-bit shift register.
    //   shift_reg[0] : input bit delayed by 1 (b_{n-1})
    //   shift_reg[1] : input bit delayed by 2 (b_{n-2})
    reg [1:0] shift_reg;

    // Asynchronous, active-high reset. On reset the shift register and the
    // registered encoded output bits are cleared to 0.
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shift_reg    <= 2'b00;
            encoded_bit1 <= 1'b0;
            encoded_bit2 <= 1'b0;
        end else begin
            // g1 = "111" -> g1(x) = x^2 + x + 1
            //   encoded_bit1 = b_n XOR b_{n-1} XOR b_{n-2}
            encoded_bit1 <= data_in ^ shift_reg[0] ^ shift_reg[1];

            // g2 = "101" -> g2(x) = x^2 + 1
            //   encoded_bit2 = b_n XOR b_{n-2}
            encoded_bit2 <= data_in ^ shift_reg[1];

            // Shift the current input bit into the register (b_{n-1} <- b_n,
            // b_{n-2} <- b_{n-1}).
            shift_reg <= {shift_reg[0], data_in};
        end
    end

endmodule


