module convolutional_encoder (
    input wire clk,
    input wire rst,
    input wire data_in,
    output reg encoded_bit1,
    output reg encoded_bit2
);
    // Fixed constraint length K=3 -> two memory (shift-register) stages
    // shift_reg[0] holds the previous input bit (delay 1)
    // shift_reg[1] holds the input bit before that (delay 2)
    reg [1:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shift_reg    <= 2'b00;
            encoded_bit1 <= 1'b0;
            encoded_bit2 <= 1'b0;
        end else begin
            // Generator polynomials:
            //   g1 = 111 (x^2 + x + 1): current bit XOR both delayed bits
            //   g2 = 101 (x^2 + 1)    : current bit XOR the oldest delayed bit
            encoded_bit1 <= data_in ^ shift_reg[0] ^ shift_reg[1];
            encoded_bit2 <= data_in ^ shift_reg[1];

            // Advance the shift register with the new input bit
            shift_reg <= {shift_reg[0], data_in};
        end
    end
endmodule

module crossbar_switch #(
    parameter DATA_WIDTH = 8,  // Parameterized data width
    localparam NUM_PORTS = 4,
    localparam DATA_WIDTH_IN = (DATA_WIDTH + $clog2(NUM_PORTS))
)(
    input  logic                        clk,        // Clock signal
    input  logic                        reset,      // Reset signal
    // Input data and destination IDs
    input  logic [DATA_WIDTH_IN-1 :0]  in0, in1, in2, in3,  // Input data
    input  logic                       valid_in0, valid_in1, valid_in2, valid_in3,  // Input data valid
    // Output data
    output logic  [DATA_WIDTH-1:0]      out0, out1, out2, out3,  // Output data
    output logic                        valid_out0, valid_out1, valid_out2, valid_out3  // Output data valid
);
    // Internal Signals
    logic [$clog2(NUM_PORTS)-1 : 0] dest0,dest1,dest2,dest3;           // Destination ID for each input

    // ----------------------------------------
    // - Procedural blocks
    // ----------------------------------------
    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            out0 <= 0;
            out1 <= 0;
            out2 <= 0;
            out3 <= 0;
            valid_out0 <= 1'b0;
            valid_out1 <= 1'b0;
            valid_out2 <= 1'b0;
            valid_out3 <= 1'b0;
        end else begin
            out0 <= 0 ;
            out1 <= 0 ;
            out2 <= 0 ;
            out3 <= 0 ;
            valid_out0 <= 1'b0;
            valid_out1 <= 1'b0;
            valid_out2 <= 1'b0;
            valid_out3 <= 1'b0;

            if (valid_in0 == 1) begin

                    // Insert code for Input 0 Port here
                    case (dest0)
                        2'd0 : begin out0 <= in0[DATA_WIDTH-1:0]; valid_out0 <= 1'b1; end
                        2'd1 : begin out1 <= in0[DATA_WIDTH-1:0]; valid_out1 <= 1'b1; end
                        2'd2 : begin out2 <= in0[DATA_WIDTH-1:0]; valid_out2 <= 1'b1; end
                        2'd3 : begin out3 <= in0[DATA_WIDTH-1:0]; valid_out3 <= 1'b1; end
                    endcase

            end else if (valid_in1 == 1) begin

                    // Insert code for Input 1 Port here
                    case (dest1)
                        2'd0 : begin out0 <= in1[DATA_WIDTH-1:0]; valid_out0 <= 1'b1; end
                        2'd1 : begin out1 <= in1[DATA_WIDTH-1:0]; valid_out1 <= 1'b1; end
                        2'd2 : begin out2 <= in1[DATA_WIDTH-1:0]; valid_out2 <= 1'b1; end
                        2'd3 : begin out3 <= in1[DATA_WIDTH-1:0]; valid_out3 <= 1'b1; end
                    endcase

            end else if (valid_in2 == 1) begin

                    // Insert code for Input 2 Port here
                    case (dest2)
                        2'd0 : begin out0 <= in2[DATA_WIDTH-1:0]; valid_out0 <= 1'b1; end
                        2'd1 : begin out1 <= in2[DATA_WIDTH-1:0]; valid_out1 <= 1'b1; end
                        2'd2 : begin out2 <= in2[DATA_WIDTH-1:0]; valid_out2 <= 1'b1; end
                        2'd3 : begin out3 <= in2[DATA_WIDTH-1:0]; valid_out3 <= 1'b1; end
                    endcase

            end else if (valid_in3 == 1) begin

                    // Insert code for Input 3 Port here
                    case (dest3)
                        2'd0 : begin out0 <= in3[DATA_WIDTH-1:0]; valid_out0 <= 1'b1; end
                        2'd1 : begin out1 <= in3[DATA_WIDTH-1:0]; valid_out1 <= 1'b1; end
                        2'd2 : begin out2 <= in3[DATA_WIDTH-1:0]; valid_out2 <= 1'b1; end
                        2'd3 : begin out3 <= in3[DATA_WIDTH-1:0]; valid_out3 <= 1'b1; end
                    endcase

            end else begin
                out0 <= 0 ;
                out1 <= 0 ;
                out2 <= 0 ;
                out3 <= 0 ;
            end
        end
    end

    // ----------------------------------------
    // - Combinational Assignments
    // ----------------------------------------
    assign dest0 = in0 [DATA_WIDTH_IN-1 : DATA_WIDTH_IN-2] ; // Destination port ID for in0 data
    assign dest1 = in1 [DATA_WIDTH_IN-1 : DATA_WIDTH_IN-2] ; // Destination port ID for in1 data
    assign dest2 = in2 [DATA_WIDTH_IN-1 : DATA_WIDTH_IN-2] ; // Destination port ID for in2 data
    assign dest3 = in3 [DATA_WIDTH_IN-1 : DATA_WIDTH_IN-2] ; // Destination port ID for in3 data

endmodule

// Data bus controller: arbitrates two independent ready-valid masters (m0, m1)
// onto a single ready-valid slave port. First-come-first-served when the two
// masters assert in different cycles; on a same-cycle tie the AFINITY parameter
// selects the winner. The datapath has one cycle of latency (a registered stage
// from a master's request to the slave output). The slave's ready is passed
// through to the currently-served master's ready.
//
// NOTE: the prompt's literal module header spells the handshake-ready ports
// m0_read / m1_read / s_read (the descriptive table calls them *_ready with the
// same directions). The embedded module header is the port contract the CVDP
// harness binds to by name, so the header spelling (*_read) is used here.
module data_bus_controller #(
    parameter AFINITY = 0
)(
    input             clk,
    input             rst_n,

    // Master 0 interface
    output            m0_read,
    input             m0_valid,
    input      [31:0] m0_data,

    // Master 1 interface
    output            m1_read,
    input             m1_valid,
    input      [31:0] m1_data,

    // Slave interface
    input             s_read,
    output reg        s_valid,
    output reg [31:0] s_data
);

    // Which master owns the transaction currently presented to the slave.
    //   1'b0 -> m0 , 1'b1 -> m1  (only meaningful while s_valid is high)
    reg sel;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s_valid <= 1'b0;
            s_data  <= 32'b0;
            sel     <= 1'b0;
        end else if (s_valid) begin
            // A transaction is currently presented to the slave.
            if (s_read) begin
                // Handshake with the slave completes this cycle. Give the OTHER
                // master immediate priority (FCFS: it has been waiting while the
                // current one was served). The just-completed master is deferred
                // to a fresh sample so a stale (not-yet-deasserted) valid cannot
                // duplicate its transaction.
                if (sel == 1'b0) begin
                    if (m1_valid) begin
                        s_valid <= 1'b1;
                        sel     <= 1'b1;
                        s_data  <= m1_data;
                    end else begin
                        s_valid <= 1'b0;
                    end
                end else begin
                    if (m0_valid) begin
                        s_valid <= 1'b1;
                        sel     <= 1'b0;
                        s_data  <= m0_data;
                    end else begin
                        s_valid <= 1'b0;
                    end
                end
            end else begin
                // Slave not ready: hold the current transaction stable.
                s_valid <= 1'b1;
            end
        end else begin
            // Idle: no transaction in flight. Sample the master requests.
            if (m0_valid && m1_valid) begin
                // Same-cycle conflict -> AFINITY decides the winner.
                if (AFINITY == 0) begin
                    s_valid <= 1'b1;
                    sel     <= 1'b0;
                    s_data  <= m0_data;
                end else begin
                    s_valid <= 1'b1;
                    sel     <= 1'b1;
                    s_data  <= m1_data;
                end
            end else if (m0_valid) begin
                s_valid <= 1'b1;
                sel     <= 1'b0;
                s_data  <= m0_data;
            end else if (m1_valid) begin
                s_valid <= 1'b1;
                sel     <= 1'b1;
                s_data  <= m1_data;
            end else begin
                s_valid <= 1'b0;
            end
        end
    end

    // The slave's ready is transferred to the ready of whichever master's
    // transaction is currently presented to the slave.
    assign m0_read = s_valid & (sel == 1'b0) & s_read;
    assign m1_read = s_valid & (sel == 1'b1) & s_read;

endmodule

module data_serializer #(
  parameter DATA_W   = 8,
  parameter BIT_ORDER= 0,
  parameter PARITY   = 0
)(
  input                  clk,
  input                  reset,
  // Parallel data interface
  input                  p_valid_i,
  input  [DATA_W-1:0]    p_data_i,
  output                 p_ready_o,
  // Serial data interface
  output                 s_valid_o,
  output                 s_data_o,
  input                  s_ready_i,
  // Transmission enable
  input                  tx_en_i
);

  // Local constants
  localparam ST_RX = 1'b0;
  localparam ST_TX = 1'b1;

  // If PARITY != 0 => We use 1 extra bit for parity
  localparam EXTRA_BIT = (PARITY == 0) ? 0 : 1;
  localparam SHIFT_W   = DATA_W + EXTRA_BIT;

  // Internal regs
  reg                    state_q, state_d;
  reg  [SHIFT_W-1:0]     shift_reg_q, shift_reg_d;
  reg  [$clog2(SHIFT_W)-1:0] count_q, count_d;

  // Parity calculation
  wire parity_bit_even = ^p_data_i;   // XOR => "even"
  wire parity_bit_odd  = ~^p_data_i;  // invert XOR => "odd"

  wire parity_bit = (PARITY == 1) ? parity_bit_even :
                    (PARITY == 2) ? parity_bit_odd  :
                                    1'b0; // NONE

  // Sequential state & register updates
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state_q     <= ST_RX;
      shift_reg_q <= {SHIFT_W{1'b0}};
      count_q     <= 0;
    end else begin
      state_q     <= state_d;
      shift_reg_q <= shift_reg_d;
      count_q     <= count_d;
    end
  end

  // Next-state logic
  always @* begin
    // Default assignments
    state_d     = state_q;
    shift_reg_d = shift_reg_q;
    count_d     = count_q;

    case (state_q)

      // ST_RX: Load parallel data + parity
      ST_RX: begin
        if (p_valid_i) begin
          if (BIT_ORDER == 0) begin
            // LSB-first => store LSB in shift_reg_d[0]
            // With parity: parity is the MSB of the serialized stream (last bit out).
            if (EXTRA_BIT == 1)
              shift_reg_d = {parity_bit, p_data_i};  // 9 bits if PARITY!=0
            else
              shift_reg_d = p_data_i;                // 8 bits if PARITY=0
          end
          else begin
            // MSB-first => store MSB in shift_reg_d[SHIFT_W-1]
            // With parity: parity is the LSB of the serialized stream (last bit out),
            // so data occupies the high bits and parity sits at bit 0.
            // Bug #1 fix: load parallel data unmodified (no nibble swap).
            if (EXTRA_BIT == 1)
              shift_reg_d = {p_data_i, parity_bit};  // 9 bits if PARITY!=0
            else
              shift_reg_d = p_data_i;                // 8 bits if PARITY=0
          end

          count_d = 0;
          state_d = ST_TX;
        end
      end

      // ST_TX: Shift bits out until SHIFT_W done
      ST_TX: begin
        // Only shift if s_ready_i & tx_en_i
        if (s_ready_i && tx_en_i) begin
          if (count_q == (SHIFT_W - 1)) begin
            // Done sending SHIFT_W bits
            state_d   = ST_RX;
            count_d   = 0;
          end
          else begin
            if (BIT_ORDER == 1) begin
              // MSB-first => shift left by 1 (Bug #2 fix: single-bit shift,
              // no extra 2-bit shift when parity is enabled).
              shift_reg_d = {shift_reg_q[SHIFT_W-2:0], 1'b0};
              count_d     = count_q + 1;
            end
            else begin
              // LSB-first => shift right by 1
              shift_reg_d = {1'b0, shift_reg_q[SHIFT_W-1:1]};
              count_d     = count_q + 1;
            end
          end
        end
      end

      default: begin
        state_d = ST_RX; // safe fallback
      end
    endcase
  end

  // Outputs
  assign s_valid_o = (state_q == ST_TX);

  // LSB-first => s_data_o = shift_reg_q[0]
  // MSB-first => s_data_o = shift_reg_q[SHIFT_W-1]
  assign s_data_o  = (BIT_ORDER == 0) ? shift_reg_q[0] : shift_reg_q[SHIFT_W-1];

  assign p_ready_o = (state_q == ST_RX);

endmodule

// data_width_converter
// 32-bit -> 128-bit data width converter.
// Concatenates four consecutive valid 32-bit inputs into one 128-bit output.
// First received sample occupies the most-significant word ([127:96]),
// the fourth received sample occupies the least-significant word ([31:0]).
// Asynchronous active-high reset clears all internal state.

module data_width_converter (
    input  wire          clk,
    input  wire          reset,
    input  wire [31:0]   data_in,
    input  wire          data_valid,
    output reg  [127:0]  o_data_out,
    output reg           o_data_out_valid
);

    // Number of valid 32-bit samples accepted so far (0..3).
    reg [1:0]   count;
    // Rolling buffer holding the samples accepted before the completing one.
    reg [127:0] data_buffer;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count            <= 2'd0;
            data_buffer      <= 128'd0;
            o_data_out       <= 128'd0;
            o_data_out_valid <= 1'b0;
        end else begin
            if (data_valid) begin
                // Shift the new sample into the least-significant word so the
                // earliest sample migrates toward the most-significant bits.
                data_buffer <= {data_buffer[95:0], data_in};

                if (count == 2'd3) begin
                    // Fourth valid sample completes a 128-bit word.
                    o_data_out       <= {data_buffer[95:0], data_in};
                    o_data_out_valid <= 1'b1;
                    count            <= 2'd0;
                end else begin
                    count            <= count + 2'd1;
                    o_data_out_valid <= 1'b0;
                end
            end else begin
                // No valid input this cycle: deassert the one-cycle valid pulse.
                o_data_out_valid <= 1'b0;
            end
        end
    end

endmodule


