module dbi_enc (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [39:0] data_in,
    output reg  [39:0] data_out,
    output reg  [1:0]  dbi_cntrl
);

    // Count the number of set bits in a 20-bit vector.
    function [5:0] count_ones;
        input [19:0] v;
        integer k;
        begin
            count_ones = 6'd0;
            for (k = 0; k < 20; k = k + 1)
                count_ones = count_ones + {5'd0, v[k]};
        end
    endfunction

    reg [5:0] diff_g1;   // toggles in Group-1 (MSBs) vs previous codeword
    reg [5:0] diff_g0;   // toggles in Group-0 (LSBs) vs previous codeword

    // data_out is registered; its current (pre-edge) value is the previous
    // codeword used for the toggle comparison. It is seeded to 0 by reset,
    // matching "first operation compared with 20 bits of zeroes".
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out  <= 40'h00_0000_0000;
            dbi_cntrl <= 2'b00;
        end else begin
            // Group-1 : MSBs [39:20]
            diff_g1 = count_ones(data_in[39:20] ^ data_out[39:20]);
            if (diff_g1 > 6'd10) begin
                dbi_cntrl[1]    <= 1'b1;
                data_out[39:20] <= ~data_in[39:20];
            end else begin
                dbi_cntrl[1]    <= 1'b0;
                data_out[39:20] <= data_in[39:20];
            end

            // Group-0 : LSBs [19:0]
            diff_g0 = count_ones(data_in[19:0] ^ data_out[19:0]);
            if (diff_g0 > 6'd10) begin
                dbi_cntrl[0]  <= 1'b1;
                data_out[19:0] <= ~data_in[19:0];
            end else begin
                dbi_cntrl[0]  <= 1'b0;
                data_out[19:0] <= data_in[19:0];
            end
        end
    end

endmodule


