module dbi_enc(
   // Inputs
   input  wire        rst_n,      // Asynchronous reset
   input  wire        clk,        // Clock
   input  wire        dbi_enable, // Enable/disable data bus inversion operation
   input  wire [39:0] data_in,    // Data input before DBI logic
   // Outputs
   output wire [4:0]  dbi_cntrl,
   output wire [39:0] data_out    // Data output after DBI logic
   );
   wire [39:0] next_dbi_data_out; //calculated dbi_out
   wire [7:0] dat0;       //  data group 1 to 8
   wire [7:0] dat1;       // data group 9 to 16
   wire [7:0] dat2;       //  data group 17 to 24
   wire [7:0] dat3;       // data group 25 to 32
   wire [7:0] dat4;       // data group  33 to 40
   wire [7:0] prev_dat0;    // Prev data group
   wire [7:0] prev_dat1;    // Prev data group
   wire [7:0] prev_dat2;    // Prev data group
   wire [7:0] prev_dat3;    // Prev data group
   wire [7:0] prev_dat4;    // Prev data group
   wire [4:0] dbi_bits;     // dbi_bits[0]
                            // dbi_bits[1]
   reg  [44:0] dbi_data_out; // Registers to latch data after DBI calculations

   assign data_out = dbi_data_out[39:0];
   assign dbi_cntrl = dbi_data_out[44:40];
   assign {dat4,dat3,dat2,dat1,dat0} = data_in;
   assign dbi_bits[4:0] = {(dbi_bit(dat4[7:0],prev_dat4[7:0])),
                   (dbi_bit(dat3[7:0],prev_dat3[7:0])),
                   (dbi_bit(dat2[7:0],prev_dat2[7:0])),
                   (dbi_bit(dat1[7:0],prev_dat1[7:0])),
                   (dbi_bit(dat0[7:0],prev_dat0[7:0]))};

    assign next_dbi_data_out = { ({8{dbi_bits[4]}} ^ dat4 ), ({8{dbi_bits[3]}} ^ dat3 ), ({8{dbi_bits[2]}} ^ dat2) , ({8{dbi_bits[1]}} ^ dat1) ,
                                 ({8{dbi_bits[0]}} ^ dat0)  };

    assign prev_dat0 = dbi_data_out[7:0];//Prev  0 data group. Used to dbi contrl
    assign prev_dat1 = dbi_data_out[15:8];//Prev  1 data group. Used to get dbi contrl
    assign prev_dat2 = dbi_data_out[23:16];//Prev 2 data group. Used to get dbi contrl
    assign prev_dat3 = dbi_data_out[31:24];//Prev  3 data group. Used to get dbi contrl
    assign prev_dat4 = dbi_data_out[39:32];//Prev 4 data group. Used to get dbi contrl


   // DBI data output registered
always @(posedge clk or negedge rst_n)
  begin: dbi_data_out_register
    if (!rst_n)
      begin
        dbi_data_out <= 45'h0;
      end
    else if (dbi_enable)
      begin
        // Normal data bus inversion operation
        dbi_data_out <= {dbi_bits,next_dbi_data_out};
      end
    else
      begin
        // DBI disabled: pass input through after a clock cycle, dbi_cntrl = 0
        dbi_data_out <= {5'b00000, data_in};
      end
  end



  // Function to calculate each DBI bit
function automatic reg dbi_bit (
  input [7:0] cur_d,  // Current data
  input [7:0] prv_d); // Previous data
  integer          i;  // Integer index
  reg [4:0] tmp;       // Counter Variable
  reg [7:0] temp_dat;  // Intermediate DBI value

  tmp = 5'd0;
  for (i=0; i<8; i=i+1)
    begin
      temp_dat[i] = cur_d[i] ^ prv_d[i];
      tmp = tmp + temp_dat[i];
    end
 dbi_bit = (tmp > 4) ? 1 : 0;

endfunction



endmodule

module dbi_dec (
   // Inputs
   input  wire        rst_n,     // Asynchronous reset
   input  wire        clk,       // Clock
   input  wire [39:0] data_in,   // Data input before DBI decoder logic
   input  wire [1:0]  dbi_cntrl, // Indicate data inversion enabled for each group
   // Outputs
   output wire [39:0] data_out   // Output data after DBI logic
   );

   // Split incoming data into two 20-bit groups.
   // Group-0 : least significant 20 bits, controlled by dbi_cntrl[0]
   // Group-1 : most  significant 20 bits, controlled by dbi_cntrl[1]
   wire [19:0] group0_dec = dbi_cntrl[0] ? ~data_in[19:0]  : data_in[19:0];
   wire [19:0] group1_dec = dbi_cntrl[1] ? ~data_in[39:20] : data_in[39:20];

   reg [39:0] data_out_reg;

   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         data_out_reg <= 40'h00_0000_0000;
      end else begin
         data_out_reg <= {group1_dec, group0_dec};
      end
   end

   assign data_out = data_out_reg;

endmodule

module decode_firstbit #(
    parameter integer InWidth_g = 32,
    parameter integer InReg_g   = 1,
    parameter integer OutReg_g  = 1,
    parameter integer PlRegs_g  = 1
)(
    input  wire                          Clk,
    input  wire                          Rst,
    input  wire [InWidth_g-1:0]          In_Data,
    input  wire                          In_Valid,
    output wire [$clog2(InWidth_g)-1:0]  Out_FirstBit,
    output wire                          Out_Found,
    output wire                          Out_Valid
);

    localparam integer BinBits_c = $clog2(InWidth_g);
    localparam integer PW        = BinBits_c + 2;         // {valid, found, firstbit}
    localparam integer DEPTH     = PlRegs_g + OutReg_g;   // result-path registers

    // ---------------------------------------------------------------------
    // Lowest-set-bit index detection.
    // The input is conceptually zero-padded at the high end to the nearest
    // power of two (2**BinBits_c); since padding bits are 0 they never win
    // the lowest-set-bit search, so we scan the InWidth_g bits directly.
    // ---------------------------------------------------------------------
    function [BinBits_c-1:0] find_first_bit;
        input [InWidth_g-1:0] d;
        integer i;
        begin
            find_first_bit = {BinBits_c{1'b0}};
            for (i = InWidth_g-1; i >= 0; i = i - 1) begin
                if (d[i])
                    find_first_bit = i[BinBits_c-1:0];
            end
        end
    endfunction

    // ---------------------------------------------------------------------
    // Optional input register stage (InReg_g)
    // ---------------------------------------------------------------------
    wire [InWidth_g-1:0] data_s0;
    wire                 valid_s0;

    generate
        if (InReg_g != 0) begin : g_in_reg
            reg [InWidth_g-1:0] data_r;
            reg                 valid_r;
            always @(posedge Clk or posedge Rst) begin
                if (Rst) begin
                    data_r  <= {InWidth_g{1'b0}};
                    valid_r <= 1'b0;
                end else begin
                    data_r  <= In_Data;
                    valid_r <= In_Valid;
                end
            end
            assign data_s0  = data_r;
            assign valid_s0 = valid_r;
        end else begin : g_in_comb
            assign data_s0  = In_Data;
            assign valid_s0 = In_Valid;
        end
    endgenerate

    // ---------------------------------------------------------------------
    // Combinational detection
    // ---------------------------------------------------------------------
    wire                 found_c    = |data_s0;
    wire [BinBits_c-1:0] firstbit_c = find_first_bit(data_s0);
    wire [PW-1:0]        payload_c  = {valid_s0, found_c, firstbit_c};

    // ---------------------------------------------------------------------
    // Result pipeline: PlRegs_g pipeline registers + OutReg_g output register.
    // Total I/O latency = InReg_g + PlRegs_g + OutReg_g.
    // ---------------------------------------------------------------------
    generate
        if (DEPTH == 0) begin : g_no_pipe
            assign Out_Valid    = payload_c[PW-1];
            assign Out_Found    = payload_c[BinBits_c];
            assign Out_FirstBit = payload_c[BinBits_c-1:0];
        end else begin : g_pipe
            reg [PW-1:0] pl [0:DEPTH-1];
            integer j;
            always @(posedge Clk or posedge Rst) begin
                if (Rst) begin
                    for (j = 0; j < DEPTH; j = j + 1)
                        pl[j] <= {PW{1'b0}};
                end else begin
                    pl[0] <= payload_c;
                    for (j = 1; j < DEPTH; j = j + 1)
                        pl[j] <= pl[j-1];
                end
            end
            assign Out_Valid    = pl[DEPTH-1][PW-1];
            assign Out_Found    = pl[DEPTH-1][BinBits_c];
            assign Out_FirstBit = pl[DEPTH-1][BinBits_c-1:0];
        end
    endgenerate

endmodule


