module decoder_8b10b (
    input  logic        clk_in,       // trigger on rising edge
    input  logic        reset_in,     // reset_in, assert HI
    input  logic [9:0]  decoder_in,   // 10bit input
    output logic [7:0]  decoder_out,  // 8bit decoded output
    output logic        control_out   // control char, assert HI for control words
);

logic [9:0] s_in_10b_reg;
logic [7:0] s_decoder_out;
logic       s_control_out;

always_ff @(posedge clk_in or posedge reset_in) begin
    if (reset_in) begin
        s_in_10b_reg  <= 10'b0000000000;
        s_decoder_out <= 8'b00000000;
        s_control_out <= 1'b0;
    end else begin
        s_in_10b_reg  <= decoder_in;

        // Decode the incoming 10-bit codeword against the valid control symbols.
        // Latency is one clock cycle: the result of decoding the current
        // decoder_in is registered and appears on the outputs next cycle.
        case (decoder_in)
            // K.28.0 -> 0x1C
            10'b0011110100, 10'b1100001011: begin s_decoder_out <= 8'h1C; s_control_out <= 1'b1; end
            // K.28.1 -> 0x3C
            10'b0011111001, 10'b1100000110: begin s_decoder_out <= 8'h3C; s_control_out <= 1'b1; end
            // K.28.2 -> 0x5C
            10'b0011110101, 10'b1100001010: begin s_decoder_out <= 8'h5C; s_control_out <= 1'b1; end
            // K.28.3 -> 0x7C
            10'b0011110011, 10'b1100001100: begin s_decoder_out <= 8'h7C; s_control_out <= 1'b1; end
            // K.28.4 -> 0x9C
            10'b0011110010, 10'b1100001101: begin s_decoder_out <= 8'h9C; s_control_out <= 1'b1; end
            // K.28.5 -> 0xBC
            10'b0011111010, 10'b1100000101: begin s_decoder_out <= 8'hBC; s_control_out <= 1'b1; end
            // K.28.6 -> 0xDC
            10'b0011110110, 10'b1100001001: begin s_decoder_out <= 8'hDC; s_control_out <= 1'b1; end
            // K.28.7 -> 0xFC
            10'b0011111000, 10'b1100000111: begin s_decoder_out <= 8'hFC; s_control_out <= 1'b1; end
            // K.23.7 -> 0xF7
            10'b1110101000, 10'b0001010111: begin s_decoder_out <= 8'hF7; s_control_out <= 1'b1; end
            // K.27.7 -> 0xFB
            10'b1101101000, 10'b0010010111: begin s_decoder_out <= 8'hFB; s_control_out <= 1'b1; end
            // K.29.7 -> 0xFD
            10'b1011101000, 10'b0100010111: begin s_decoder_out <= 8'hFD; s_control_out <= 1'b1; end
            // K.30.7 -> 0xFE
            10'b0111101000, 10'b1000010111: begin s_decoder_out <= 8'hFE; s_control_out <= 1'b1; end
            // Invalid control symbol -> output 0
            default: begin s_decoder_out <= 8'b00000000; s_control_out <= 1'b0; end
        endcase
    end
end

assign decoder_out = s_decoder_out;
assign control_out = s_control_out;

endmodule

module digital_dice_roller (
    input  wire       clk,
    input  wire       reset_n,
    input  wire       button,
    output reg  [2:0] dice_value
);

    // FSM states
    localparam IDLE    = 1'b0;
    localparam ROLLING = 1'b1;

    reg       state;
    reg       next_state;
    reg [2:0] counter;

    // Next-state logic (level-sensitive on button)
    always @(*) begin
        case (state)
            IDLE:    next_state = button ? ROLLING : IDLE;
            ROLLING: next_state = button ? ROLLING : IDLE;
            default: next_state = IDLE;
        endcase
    end

    // State register: asynchronous active-low reset -> IDLE
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Internal counter: cycles 1..6 while ROLLING, held at start value (1) in IDLE
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            counter <= 3'd1;
        else if (state == ROLLING)
            counter <= (counter == 3'd6) ? 3'd1 : (counter + 3'd1);
        else
            counter <= 3'd1;
    end

    // dice_value: 000 on reset; holds during IDLE; on release (ROLLING->IDLE)
    // captures the last counter value shown while rolling.
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n)
            dice_value <= 3'd0;
        else if (state == ROLLING && button == 1'b0)
            dice_value <= counter;
    end

endmodule


