module digital_dice_roller #(
    parameter int DICE_MAX  = 6,                    // Maximum dice value
    parameter int BIT_WIDTH = $clog2(DICE_MAX) + 1, // Bits to represent a dice value
    parameter int NUM_DICE  = 2                     // Number of dice rolled simultaneously
) (
    input  wire                              clk,          // System clock (posedge)
    input  wire                              reset,        // Asynchronous, active LOW
    input  wire                              button,       // HIGH = roll, LOW = latch/idle
    output logic [(NUM_DICE*BIT_WIDTH)-1:0]  dice_values   // Flattened dice values
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        ROLLING = 2'b01
    } state_t;

    state_t current_state, next_state;

    // Per-dice counter values and independent 16-bit random seeds
    logic [BIT_WIDTH-1:0] counters    [0:NUM_DICE-1];
    logic [15:0]          random_seed [0:NUM_DICE-1];

    integer i;

    // 16-bit Fibonacci LFSR for x^16 + x^5 + x^4 + x^3 + 1
    // (taps at bit positions 15, 4, 3, 2; feedback shifted into the LSB)
    function automatic [15:0] lfsr_next(input [15:0] s);
        lfsr_next = {s[14:0], s[15] ^ s[4] ^ s[3] ^ s[2]};
    endfunction

    // State register with asynchronous active-low reset
    always_ff @(posedge clk or negedge reset) begin
        if (!reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Next-state logic (combinational)
    always_comb begin
        next_state = current_state;
        case (current_state)
            IDLE:    if (button)  next_state = ROLLING;
            ROLLING: if (!button) next_state = IDLE;
            default:              next_state = IDLE;
        endcase
    end

    // Counter / seed evolution and flattened output latching
    always_ff @(posedge clk or negedge reset) begin
        if (!reset) begin
            // Reset: counters to 1, unique seed per dice, output cleared
            for (i = 0; i < NUM_DICE; i = i + 1) begin
                counters[i]    <= 1;
                random_seed[i] <= i + 1;    // Dice1 -> 1, Dice2 -> 2, Dice3 -> 3, ...
            end
            dice_values <= '0;
        end else if (current_state == ROLLING) begin
            // Independently advance each dice's LFSR and derive a value in [1, DICE_MAX]
            for (i = 0; i < NUM_DICE; i = i + 1) begin
                random_seed[i] <= lfsr_next(random_seed[i]);
                counters[i]    <= (lfsr_next(random_seed[i]) % DICE_MAX) + 1;
            end
        end else if (current_state == IDLE) begin
            // Latch the current counter values into the flattened output.
            // Dice1 occupies the most-significant BIT_WIDTH segment.
            for (i = 0; i < NUM_DICE; i = i + 1) begin
                dice_values[(NUM_DICE-1-i)*BIT_WIDTH +: BIT_WIDTH] <= counters[i];
            end
        end
    end

endmodule

module dig_stopwatch #(
    parameter CLK_FREQ = 50000000
) (
    input  wire       clk,
    input  wire       reset,       // asynchronous active-high
    input  wire       start_stop,  // 1 = run, 0 = pause (hold)
    output reg [5:0]  seconds,     // 0-59
    output reg [5:0]  minutes,     // 0-59
    output reg        hour         // set to 1 after one hour
);

    // Width for the clock-divider counter (0 .. CLK_FREQ-1)
    localparam integer DIV_W = (CLK_FREQ > 1) ? $clog2(CLK_FREQ) : 1;

    reg [DIV_W-1:0] div_counter;
    wire            one_sec_pulse;

    // One-second strobe: high for a single clk cycle when a full second
    // has elapsed while running.  Gated by start_stop so no pulse occurs
    // while paused.
    assign one_sec_pulse = start_stop && (div_counter == (CLK_FREQ - 1));

    // Clock divider: counts input-clock cycles while running; holds its
    // partial progress while paused; cleared by asynchronous reset.
    always @(posedge clk or posedge reset) begin
        if (reset)
            div_counter <= {DIV_W{1'b0}};
        else if (start_stop) begin
            if (div_counter == (CLK_FREQ - 1))
                div_counter <= {DIV_W{1'b0}};
            else
                div_counter <= div_counter + 1'b1;
        end
        // paused: hold div_counter (partial progress preserved)
    end

    // Time counters: advance on the one-second strobe.  Asynchronous reset
    // clears all.  Once one hour is reached, all values are frozen until
    // reset (do not count beyond one hour).
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            seconds <= 6'd0;
            minutes <= 6'd0;
            hour    <= 1'b0;
        end else if (one_sec_pulse && !hour) begin
            if (seconds == 6'd59) begin
                seconds <= 6'd0;
                if (minutes == 6'd59) begin
                    minutes <= 6'd0;
                    hour    <= 1'b1;   // one hour elapsed
                end else begin
                    minutes <= minutes + 1'b1;
                end
            end else begin
                seconds <= seconds + 1'b1;
            end
        end
        // when hour == 1, hold 1 hour / 0 min / 0 sec until reset
    end

endmodule


