module dig_stopwatch #(
    parameter CLK_FREQ = 50000000  // Default clock frequency is 50 MHz
)(
    input  wire       clk,           // Input clock (parameterized frequency)
    input  wire       reset,         // Reset signal (async, active-high)
    input  wire       start_stop,    // Start/Stop control
    input  wire       load,          // Asynchronous active-high load
    input  wire [4:0] load_hours,    // Hours to load   (valid 0-23)
    input  wire [5:0] load_minutes,  // Minutes to load (valid 0-59)
    input  wire [5:0] load_seconds,  // Seconds to load (valid 0-59)
    output reg  [4:0] hours,         // Hours counter   (0-23)
    output reg  [5:0] minutes,       // Minutes counter (0-59)
    output reg  [5:0] seconds        // Seconds counter (0-59)
);

    localparam COUNTER_MAX = CLK_FREQ - 1;  // Max clock-divider value
    reg [$clog2(COUNTER_MAX):0] counter;    // Clock divider counter

    // Per-field saturation: out-of-range loads clamp to the maximum valid value
    wire [4:0] ld_hours   = (load_hours   > 5'd23) ? 5'd23 : load_hours;
    wire [5:0] ld_minutes = (load_minutes > 6'd59) ? 6'd59 : load_minutes;
    wire [5:0] ld_seconds = (load_seconds > 6'd59) ? 6'd59 : load_seconds;

    // Single-clock countdown timer.
    //   Priority: reset (async) > load (async) > countdown (synchronous).
    //   Pause (start_stop low): hold divider counter and time (retain progress).
    always @(posedge clk or posedge reset or posedge load) begin
        if (reset) begin
            counter <= 0;
            hours   <= 5'd0;
            minutes <= 6'd0;
            seconds <= 6'd0;
        end else if (load) begin
            // Immediate (level-sensitive) load of clamped preset values.
            counter <= 0;
            hours   <= ld_hours;
            minutes <= ld_minutes;
            seconds <= ld_seconds;
        end else if (start_stop) begin
            if (counter == COUNTER_MAX) begin
                counter <= 0;                       // one-second tick
                if (seconds != 6'd0) begin
                    seconds <= seconds - 6'd1;
                end else if (minutes != 6'd0) begin
                    seconds <= 6'd59;
                    minutes <= minutes - 6'd1;
                end else if (hours != 5'd0) begin
                    seconds <= 6'd59;
                    minutes <= 6'd59;
                    hours   <= hours - 5'd1;
                end
                // 00:00:00 -> no branch taken: hold at zero
            end else begin
                counter <= counter + 1'b1;
            end
        end
        // start_stop deasserted: hold counter and time (pause)
    end

endmodule

module dot_product (
    input               clk_in,                     // Clock signal
    input               reset_in,                   // Asynchronous Reset signal, Active HIGH
    input               start_in,                   // Start computation signal
    input       [6:0]   dot_length_in,              // Length of the dot product vectors
    input       [7:0]   vector_a_in,                // Input vector A (8-bit)
    input               vector_a_valid_in,          // Valid signal for vector A
    input       [15:0]  vector_b_in,                // Input vector B (16-bit)
    input               vector_b_valid_in,          // Valid signal for vector B
    output reg  [31:0]  dot_product_out,            // Output dot product result (32-bit)
    output reg          dot_product_valid_out       // Valid signal for dot product output
);

    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        COMPUTE = 2'b01,
        OUTPUT  = 2'b10
    } state_t;

    state_t state;

    // Internal datapath registers
    reg [31:0] accumulator;      // Running sum of element-wise products
    reg [6:0]  element_count;    // Number of element pairs accumulated so far
    reg [6:0]  dot_length_reg;   // Latched vector length for the active computation

    always @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            // Active-HIGH asynchronous reset -> clear all outputs and state
            state                 <= IDLE;
            accumulator           <= 32'h0;
            element_count         <= 7'h0;
            dot_length_reg        <= 7'h0;
            dot_product_out       <= 32'h0;
            dot_product_valid_out <= 1'b0;
        end else begin
            case (state)
                // Wait for start; keep datapath cleared and result invalid
                IDLE: begin
                    dot_product_valid_out <= 1'b0;
                    accumulator           <= 32'h0;
                    element_count         <= 7'h0;
                    if (start_in) begin
                        dot_length_reg <= dot_length_in;
                        state          <= COMPUTE;
                    end
                end

                // Accumulate products of corresponding elements while both
                // operands are valid; gaps (either valid low) freeze the datapath.
                COMPUTE: begin
                    if (vector_a_valid_in && vector_b_valid_in) begin
                        accumulator   <= accumulator +
                                         ({24'h0, vector_a_in} * {16'h0, vector_b_in});
                        element_count <= element_count + 7'h1;
                        if (element_count == (dot_length_reg - 7'h1)) begin
                            state <= OUTPUT;
                        end
                    end
                end

                // Present the final dot product with its valid strobe (1 cycle).
                OUTPUT: begin
                    dot_product_out       <= accumulator;
                    dot_product_valid_out <= 1'b1;
                    state                 <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module dot_product (
    input               clk_in,                 // Clock signal
    input               reset_in,               // Asynchronous reset, active HIGH
    input               start_in,               // Start computation, active HIGH one cycle
    input       [7:0]   dot_length_in,          // Vector length (up to 256 elements)
    input       [31:0]  vector_a_in,            // Vector A {Imag[31:16], Real[15:0]}
    input               vector_a_valid_in,      // Valid signal for vector A
    input       [31:0]  vector_b_in,            // Vector B {Imag[31:16], Real[15:0]}
    input               vector_b_valid_in,      // Valid signal for vector B
    input               a_complex_in,           // 1 = vector A complex
    input               b_complex_in,           // 1 = vector B complex
    output reg  [31:0]  dot_product_out,        // Dot product result
    output reg          dot_product_valid_out,  // Result valid, active HIGH
    output reg          dot_product_error_out   // Error, active HIGH on dropped valid
);

    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        COMPUTE = 2'b01,
        OUTPUT  = 2'b10,
        ERROR   = 2'b11
    } state_t;

    state_t state;

    // ---- Registered inputs (metastability / synchronization) ----
    reg [31:0] a_reg, b_reg;
    reg        av_reg, bv_reg;
    reg        ac_reg, bc_reg;

    always @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            a_reg  <= 32'd0;
            b_reg  <= 32'd0;
            av_reg <= 1'b0;
            bv_reg <= 1'b0;
            ac_reg <= 1'b0;
            bc_reg <= 1'b0;
        end else begin
            a_reg  <= vector_a_in;
            b_reg  <= vector_b_in;
            av_reg <= vector_a_valid_in;
            bv_reg <= vector_b_valid_in;
            ac_reg <= a_complex_in;
            bc_reg <= b_complex_in;
        end
    end

    // ---- Datapath : signed real / imaginary field products ----
    wire signed [15:0] a_re_w = a_reg[15:0];
    wire signed [15:0] a_im_w = a_reg[31:16];
    wire signed [15:0] b_re_w = b_reg[15:0];
    wire signed [15:0] b_im_w = b_reg[31:16];

    wire signed [31:0] pr_rr = a_re_w * b_re_w;
    wire signed [31:0] pr_ii = a_im_w * b_im_w;
    wire signed [31:0] pr_ri = a_re_w * b_im_w;
    wire signed [31:0] pr_ir = a_im_w * b_re_w;

    // Captured mode for the in-flight computation (config, snapshot at start)
    reg cmplx_a, cmplx_b;

    reg signed [33:0] real_term;
    reg signed [33:0] imag_term;
    always @(*) begin
        if (cmplx_a && cmplx_b) begin
            // Complex * complex
            real_term = pr_rr - pr_ii;
            imag_term = pr_ri + pr_ir;
        end else if (cmplx_a && !cmplx_b) begin
            // A complex, B real
            real_term = pr_rr;          // A_re * B_re
            imag_term = pr_ir;          // A_im * B_re
        end else if (!cmplx_a && cmplx_b) begin
            // A real, B complex
            real_term = pr_rr;          // A_re * B_re
            imag_term = pr_ri;          // A_re * B_im
        end else begin
            // Real only
            real_term = pr_rr;
            imag_term = 34'sd0;
        end
    end

    // ---- Accumulators / control ----
    reg signed [39:0] acc_re, acc_im;
    reg        [7:0]  cnt;
    reg        [7:0]  len_reg;

    always @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            state                 <= IDLE;
            acc_re                <= 40'sd0;
            acc_im                <= 40'sd0;
            cnt                   <= 8'd0;
            len_reg               <= 8'd0;
            cmplx_a               <= 1'b0;
            cmplx_b               <= 1'b0;
            dot_product_out       <= 32'd0;
            dot_product_valid_out <= 1'b0;
            dot_product_error_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    dot_product_valid_out <= 1'b0;
                    if (start_in) begin
                        state                 <= COMPUTE;
                        acc_re                <= 40'sd0;
                        acc_im                <= 40'sd0;
                        cnt                   <= 8'd0;
                        len_reg               <= dot_length_in;
                        cmplx_a               <= ac_reg;
                        cmplx_b               <= bc_reg;
                        dot_product_error_out <= 1'b0;
                    end
                end

                COMPUTE: begin
                    if (av_reg && bv_reg) begin
                        acc_re <= acc_re + real_term;
                        acc_im <= acc_im + imag_term;
                        if (cnt == len_reg - 8'd1) begin
                            state <= OUTPUT;
                        end else begin
                            cnt <= cnt + 8'd1;
                        end
                    end else begin
                        // Valid dropped mid-computation -> error
                        state                 <= ERROR;
                        dot_product_error_out <= 1'b1;
                        dot_product_out       <= 32'd0;
                        dot_product_valid_out <= 1'b0;
                    end
                end

                OUTPUT: begin
                    if (!cmplx_a && !cmplx_b)
                        dot_product_out <= acc_re[31:0];               // 32-bit real
                    else
                        dot_product_out <= {acc_im[15:0], acc_re[15:0]}; // {Imag, Real}
                    dot_product_valid_out <= 1'b1;
                    state                 <= IDLE;
                end

                ERROR: begin
                    dot_product_error_out <= 1'b1;   // hold error
                    dot_product_valid_out <= 1'b0;
                    dot_product_out       <= 32'd0;
                    state                 <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module dot_product (
    input               clk_in,                     // Clock signal
    input               reset_in,                   // Asynchronous Reset signal, Active HIGH
    input               start_in,                   // Start computation signal
    input       [6:0]   dot_length_in,              // Length of the dot product vectors
    input       [7:0]   vector_a_in,                // Input vector A (8-bit)
    input               vector_a_valid_in,          // Valid signal for vector A
    input       [15:0]  vector_b_in,                // Input vector B (16-bit)
    input               vector_b_valid_in,          // Valid signal for vector B
    output reg  [31:0]  dot_product_out,            // Output dot product result (32-bit)
    output reg          dot_product_valid_out       // Valid signal for dot product output
);

    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        COMPUTE = 2'b01,
        OUTPUT  = 2'b10
    } state_t;

    state_t state;
    reg [31:0] acc;
    reg [6:0]  cnt;

    // Single driver for all state / outputs (the redundant second always block
    // that also drove dot_product_valid_out is removed to fix the multi-driver).
    // Unused registers (dot_length_reg, vector_a_valid_in_prev,
    // vector_b_valid_in_prev) are removed.
    always @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            state <= IDLE;
            acc <= 0;
            cnt <= 0;
            dot_product_out <= 0;
            dot_product_valid_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    dot_product_valid_out <= 0;
                    if (start_in) begin
                        state <= COMPUTE;
                        acc <= 0;
                        cnt <= 0;
                    end
                end
                COMPUTE: begin
                    if (vector_a_valid_in && vector_b_valid_in) begin
                        acc <= acc + (vector_a_in * vector_b_in);
                        cnt <= cnt + 1;
                    end
                    if (cnt == dot_length_in - 1) begin
                        state <= OUTPUT;
                    end else begin
                        state <= COMPUTE;
                    end
                end
                OUTPUT: begin
                    dot_product_out <= acc;
                    dot_product_valid_out <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

module sync_pos_neg_edge_detector (
    input  wire i_clk,
    input  wire i_rstb,
    input  wire i_detection_signal,
    output reg  o_positive_edge_detected,
    output reg  o_negative_edge_detected
);

    // Registered previous value of the debounced input, used to compare
    // against the current sample to identify a transition (edge).
    reg detection_signal_delayed;

    always @(posedge i_clk or negedge i_rstb) begin
        if (!i_rstb) begin
            detection_signal_delayed <= 1'b0;
            o_positive_edge_detected <= 1'b0;
            o_negative_edge_detected <= 1'b0;
        end else begin
            detection_signal_delayed <= i_detection_signal;
            // Positive (rising) edge: was low last cycle, high this cycle.
            o_positive_edge_detected <=  i_detection_signal & ~detection_signal_delayed;
            // Negative (falling) edge: was high last cycle, low this cycle.
            o_negative_edge_detected <= ~i_detection_signal &  detection_signal_delayed;
        end
    end

endmodule

module elastic_buffer_pattern_matcher #(
   parameter WIDTH  = 16,
   parameter ERR_TOLERANCE  = 2
   )(
   input                         clk      , // clock input
   input                         rst      , // Active high synchronous reset
   input         [WIDTH-1:0]     i_data   , // input data to be matched
   input         [WIDTH-1:0]     i_pattern, // pattern to be matched against
   output logic                  o_match    // output indicating a match between the pattern and i_data.
);

// Internal variables
logic [WIDTH-1:0]        xor_data  ; // bitwise mismatch between data and pattern
logic [$clog2(WIDTH):0]  err_count ; // number of mismatched bits
logic                    match_comb; // combinational match decision

// Matching logic
always_comb begin
   // XOR marks every bit position where i_data and i_pattern differ
   xor_data         = i_data ^ i_pattern;
   // Count the mismatched bits
   err_count        = ones_count(xor_data);
   // A valid match: mismatched bits are within the tolerance.
   // ERR_TOLERANCE is (Error Tolerance + 1), so up to (ERR_TOLERANCE-1)
   // mismatched bits are allowed => match when err_count < ERR_TOLERANCE.
   match_comb       = (err_count < ERR_TOLERANCE);
end

// Set the final output: 1 clock cycle latency, active-high synchronous reset
always_ff @(posedge clk) begin
   if (rst)
      o_match <= 1'b0;
   else
      o_match <= match_comb;
end

//The following function counts the number of ones.
function [$clog2(WIDTH):0] ones_count;
   input [WIDTH-1:0] i_data;
   integer idx;
   begin
      ones_count = {($clog2(WIDTH)+1){1'b0}};
      for (idx = 0; idx < WIDTH; idx = idx + 1)
         ones_count = ones_count + i_data[idx];
   end
endfunction
endmodule


