module Binary2BCD(
    input      [7:0] num,
    output reg [3:0] thousand,
    output reg [3:0] hundred,
    output reg [3:0] ten,
    output reg [3:0] one
);
    reg [19:0] shift;
    integer i;

    always @(*) begin
        // Initialize the shift register and load the binary input
        shift = 20'd0;
        shift[7:0] = num;

        // Double-dabble: for each of the 8 binary bits, add 3 to any BCD
        // nibble >= 5 then shift the whole register left by one.
        for (i = 0; i < 8; i = i + 1) begin
            if (shift[11:8]  >= 5) shift[11:8]  = shift[11:8]  + 4'd3;
            if (shift[15:12] >= 5) shift[15:12] = shift[15:12] + 4'd3;
            if (shift[19:16] >= 5) shift[19:16] = shift[19:16] + 4'd3;
            shift = shift << 1;
        end

        // Extract BCD digits from the shift register
        one      = shift[11:8];
        ten      = shift[15:12];
        hundred  = shift[19:16];
        thousand = 4'd0; // Not used for the 8-bit input range
    end

