// -----------------------------------------------------------------------------
// ethernet_packet_parser
// Extracts the two most-significant bytes (data[31:16]) of the 2nd beat of a
// burst on a simple vld/sof/eof bus. ack is fixed high (no backpressure).
// 2-bit FSM: IDLE(0) -> EXTRACTING(1) -> DONE(2) -> FAIL_FINAL(3) -> IDLE.
// field_vld asserts once the 2nd-beat bytes are captured, clears on eof.
// Verilog-2001 for maximum simulator compatibility.
// -----------------------------------------------------------------------------
module ethernet_packet_parser (
    input  wire        clk,
    input  wire        rst,
    input  wire        vld,
    input  wire        sof,
    input  wire [31:0] data,
    input  wire        eof,
    output wire        ack,
    output reg  [15:0] field,
    output reg         field_vld
);

    // State encoding (2-bit state machine, four states)
    localparam [1:0] IDLE       = 2'd0;
    localparam [1:0] EXTRACTING = 2'd1;
    localparam [1:0] DONE       = 2'd2;
    localparam [1:0] FAIL_FINAL = 2'd3;

    // Spec-named internal signals (declared verbatim)
    reg [1:0]  state;
    reg [3:0]  beat_cnt;
    reg [15:0] temp_extracted_field;

    // ack is fixed high: the receiver always accepts valid data, no backpressure
    assign ack = 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state                <= IDLE;
            beat_cnt             <= 4'd0;
            temp_extracted_field <= 16'd0;
            field                <= 16'd0;
            field_vld            <= 1'b0;
        end else begin
            case (state)
                // ---------------------------------------------------------
                // IDLE: await start of a new packet (vld & sof). Clear the
                // beat counter, field and field_vld on entry / while idle.
                // ---------------------------------------------------------
                IDLE: begin
                    beat_cnt  <= 4'd0;
                    field     <= 16'd0;
                    field_vld <= 1'b0;
                    if (vld && sof) begin
                        // sof beat is the 1st beat of the burst
                        beat_cnt <= 4'd1;
                        state    <= EXTRACTING;
                    end
                end

                // ---------------------------------------------------------
                // EXTRACTING: count beats. On the 2nd beat (beat_cnt == 1)
                // capture data[31:16] and advance to DONE.
                // ---------------------------------------------------------
                EXTRACTING: begin
                    if (vld) begin
                        if (beat_cnt == 4'd1) begin
                            temp_extracted_field <= data[31:16];
                            state                <= DONE;
                        end
                        beat_cnt <= beat_cnt + 4'd1;
                    end
                end

                // ---------------------------------------------------------
                // DONE: drive the captured bytes onto field and assert
                // field_vld. Hold steady until eof marks burst completion.
                // ---------------------------------------------------------
                DONE: begin
                    field     <= temp_extracted_field;
                    field_vld <= 1'b1;
                    if (eof) begin
                        state <= FAIL_FINAL;
                    end
                end

                // ---------------------------------------------------------
                // FAIL_FINAL: clear field_vld and return to IDLE, ready for
                // the next burst.
                // ---------------------------------------------------------
                FAIL_FINAL: begin
                    field_vld <= 1'b0;
                    state     <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule


