module apb_controller (
    input  wire        clk,
    input  wire        reset_n,
    input  wire        select_a_i,
    input  wire        select_b_i,
    input  wire        select_c_i,
    input  wire [31:0] addr_a_i,
    input  wire [31:0] data_a_i,
    input  wire [31:0] addr_b_i,
    input  wire [31:0] data_b_i,
    input  wire [31:0] addr_c_i,
    input  wire [31:0] data_c_i,
    input  wire        apb_pready_i,
    output reg         apb_psel_o,
    output reg         apb_penable_o,
    output reg         apb_pwrite_o,
    output reg  [31:0] apb_paddr_o,
    output reg  [31:0] apb_pwdata_o
);

    // FSM states
    localparam [1:0] IDLE   = 2'd0;
    localparam [1:0] SETUP  = 2'd1;
    localparam [1:0] ACCESS = 2'd2;

    reg [1:0]  state;
    reg [31:0] addr_reg;
    reg [31:0] data_reg;
    reg [3:0]  timeout_counter;

    // Sequential: state, captured address/data, timeout counter
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            state           <= IDLE;
            addr_reg        <= 32'd0;
            data_reg        <= 32'd0;
            timeout_counter <= 4'd0;
        end else begin
            case (state)
                IDLE: begin
                    timeout_counter <= 4'd0;
                    // Priority: select_a > select_b > select_c
                    if (select_a_i) begin
                        addr_reg <= addr_a_i;
                        data_reg <= data_a_i;
                        state    <= SETUP;
                    end else if (select_b_i) begin
                        addr_reg <= addr_b_i;
                        data_reg <= data_b_i;
                        state    <= SETUP;
                    end else if (select_c_i) begin
                        addr_reg <= addr_c_i;
                        data_reg <= data_c_i;
                        state    <= SETUP;
                    end else begin
                        state <= IDLE;
                    end
                end

                SETUP: begin
                    timeout_counter <= 4'd0;
                    state           <= ACCESS;
                end

                ACCESS: begin
                    if (apb_pready_i) begin
                        // Successful transfer -> return to IDLE
                        state           <= IDLE;
                        timeout_counter <= 4'd0;
                    end else if (timeout_counter == 4'd15) begin
                        // Timeout -> abort, return to IDLE (outputs cleared)
                        state           <= IDLE;
                        timeout_counter <= 4'd0;
                    end else begin
                        timeout_counter <= timeout_counter + 4'd1;
                        state           <= ACCESS;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    // Moore outputs decoded from the current state
    always @(*) begin
        // IDLE defaults: all outputs deasserted / zero
        apb_psel_o    = 1'b0;
        apb_penable_o = 1'b0;
        apb_pwrite_o  = 1'b0;
        apb_paddr_o   = 32'd0;
        apb_pwdata_o  = 32'd0;
        case (state)
            SETUP: begin
                apb_psel_o    = 1'b1;
                apb_pwrite_o  = 1'b1;
                apb_penable_o = 1'b0;
                apb_paddr_o   = addr_reg;
                apb_pwdata_o  = data_reg;
            end
            ACCESS: begin
                apb_psel_o    = 1'b1;
                apb_pwrite_o  = 1'b1;
                apb_penable_o = 1'b1;
                apb_paddr_o   = addr_reg;
                apb_pwdata_o  = data_reg;
            end
            default: begin
                apb_psel_o    = 1'b0;
                apb_penable_o = 1'b0;
                apb_pwrite_o  = 1'b0;
                apb_paddr_o   = 32'd0;
                apb_pwdata_o  = 32'd0;
            end
        endcase
    end

endmodule


