module factorial (
    input  wire        clk,
    input  wire        arst_n,
    input  wire [4:0]  num_in,
    input  wire        start,
    output wire        busy,
    output reg  [63:0] fact,
    output wire        done
);

    // FSM states
    localparam [1:0] IDLE = 2'd0;
    localparam [1:0] BUSY = 2'd1;
    localparam [1:0] DONE = 2'd2;

    reg [1:0] state;
    reg [5:0] i;      // running multiplier index (1 .. num_in)
    reg [4:0] n_reg;  // captured input number

    assign busy = (state == BUSY);
    assign done = (state == DONE);

    always @(posedge clk or negedge arst_n) begin
        if (!arst_n) begin
            state <= IDLE;
            fact  <= 64'd0;
            i     <= 6'd0;
            n_reg <= 5'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        n_reg <= num_in;
                        fact  <= 64'd1;           // accumulator / 0! = 1
                        if (num_in == 5'd0) begin
                            // 0! = 1, no compute cycles
                            state <= DONE;
                        end else begin
                            i     <= 6'd1;        // first multiplier
                            state <= BUSY;
                        end
                    end
                end

                BUSY: begin
                    // Multiply by current index; truncated to 64 bits (mod 2^64)
                    fact <= fact * i;
                    if (i == {1'b0, n_reg}) begin
                        // last iteration -> total BUSY cycles == num_in
                        state <= DONE;
                    end else begin
                        i <= i + 6'd1;
                    end
                end

                DONE: begin
                    // one-cycle done pulse, then ready for next input
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule


