module fan_controller (
    input wire clk,                 // System clock
    input wire reset,               // Reset signal
    output reg fan_pwm_out,         // PWM output for fan control

    //APB signals
    input  wire         psel,       // Slave select
    input  wire         penable,    // Enable signal
    input  wire         pwrite,     // Write control
    input  wire [7:0]   paddr,      // Address bus
    input  wire [7:0]   pwdata,     // Write data bus
    output reg  [7:0]   prdata,     // Read data bus
    output reg          pready,     // Ready signal
    output reg          pslverr     // Slave error
);

    // ---------------------------------------------------------------
    // Register address map
    // ---------------------------------------------------------------
    localparam [7:0] ADDR_TEMP_LOW  = 8'h0a;
    localparam [7:0] ADDR_TEMP_MED  = 8'h0b;
    localparam [7:0] ADDR_TEMP_HIGH = 8'h0c;
    localparam [7:0] ADDR_TEMP_ADC  = 8'h0f;

    // ---------------------------------------------------------------
    // Duty-cycle load values (PWM period = 256 clock cycles)
    // ---------------------------------------------------------------
    localparam [7:0] DUTY_25  = 8'd64;   // 25%  : high 64,  low 192
    localparam [7:0] DUTY_50  = 8'd128;  // 50%  : high 128, low 128
    localparam [7:0] DUTY_75  = 8'd192;  // 75%  : high 192, low 64
    localparam [7:0] DUTY_100 = 8'd255;  // 100% : high 255, low 1

    // ---------------------------------------------------------------
    // Configuration / status registers
    // ---------------------------------------------------------------
    reg [7:0] temp_low;
    reg [7:0] temp_med;
    reg [7:0] temp_high;
    reg [7:0] temp_adc_in;

    // ---------------------------------------------------------------
    // PWM datapath
    // ---------------------------------------------------------------
    reg [7:0] pwm_duty_cycle;
    reg [7:0] pwm_counter;

    // Address validity (recognized register addresses)
    wire valid_addr = (paddr == ADDR_TEMP_LOW)  ||
                      (paddr == ADDR_TEMP_MED)  ||
                      (paddr == ADDR_TEMP_HIGH) ||
                      (paddr == ADDR_TEMP_ADC);

    // ---------------------------------------------------------------
    // APB write / register update (synchronous, async active-high reset)
    //   Write occurs in the access phase (psel && penable && pwrite)
    // ---------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            temp_low    <= 8'h00;
            temp_med    <= 8'h00;
            temp_high   <= 8'h00;
            temp_adc_in <= 8'h00;
        end else if (psel && penable && pwrite && valid_addr) begin
            case (paddr)
                ADDR_TEMP_LOW  : temp_low    <= pwdata;
                ADDR_TEMP_MED  : temp_med    <= pwdata;
                ADDR_TEMP_HIGH : temp_high   <= pwdata;
                ADDR_TEMP_ADC  : temp_adc_in <= pwdata;
                default        : ;
            endcase
        end
    end

    // ---------------------------------------------------------------
    // APB read + status generation (combinational)
    //   pready / pslverr asserted only during the access phase.
    //   When the slave is not selected, all status signals are cleared.
    // ---------------------------------------------------------------
    always @(*) begin
        prdata  = 8'h00;
        pready  = 1'b0;
        pslverr = 1'b0;
        if (psel && penable) begin
            pready = 1'b1;               // zero-wait-state completion
            if (!valid_addr) begin
                pslverr = 1'b1;          // invalid address -> slave error
            end
            if (!pwrite) begin           // read operation
                case (paddr)
                    ADDR_TEMP_LOW  : prdata = temp_low;
                    ADDR_TEMP_MED  : prdata = temp_med;
                    ADDR_TEMP_HIGH : prdata = temp_high;
                    ADDR_TEMP_ADC  : prdata = temp_adc_in;
                    default        : prdata = 8'h00;
                endcase
            end
        end
    end

    // ---------------------------------------------------------------
    // Temperature-based duty-cycle selection
    //   TEMP_LOW/MED/HIGH each hold the MAXIMUM temperature of their band.
    //   On reset the duty cycle is 0 (fan disabled).
    // ---------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pwm_duty_cycle <= 8'h00;
        end else begin
            if (temp_adc_in <= temp_low)
                pwm_duty_cycle <= DUTY_25;
            else if (temp_adc_in <= temp_med)
                pwm_duty_cycle <= DUTY_50;
            else if (temp_adc_in <= temp_high)
                pwm_duty_cycle <= DUTY_75;
            else
                pwm_duty_cycle <= DUTY_100;
        end
    end

    // ---------------------------------------------------------------
    // Free-running PWM counter (period = 256 clock cycles)
    // ---------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset)
            pwm_counter <= 8'h00;
        else
            pwm_counter <= pwm_counter + 8'd1;
    end

    // ---------------------------------------------------------------
    // PWM output: high while counter < duty value, else low.
    //   duty=64  -> 64 high / 192 low  (25%)
    //   duty=128 -> 128/128            (50%)
    //   duty=192 -> 192/64             (75%)
    //   duty=255 -> 255/1              (100%)
    //   duty=0   -> always low         (disabled on reset)
    // ---------------------------------------------------------------
    always @(*) begin
        if (pwm_counter < pwm_duty_cycle)
            fan_pwm_out = 1'b1;
        else
            fan_pwm_out = 1'b0;
    end

endmodule

module fan_controller (
    input wire clk,                 // System clock
    input wire reset,               // Reset signal
    output reg fan_pwm_out,         // PWM output for fan control

    //APB signals
    input  wire         psel,       // Slave select
    input  wire         penable,    // Enable signal
    input  wire         pwrite,     // Write control
    input  wire [7:0]   paddr,      // Address bus
    input  wire [7:0]   pwdata,     // Write data bus
    output reg  [7:0]   prdata,     // Read data bus
    output reg          pready,      // Ready signal
    output reg          pslverr     // Slave error
);

    // Parameters for temperature thresholds
    reg [7:0] TEMP_LOW ;      // Low temperature threshold
    reg [7:0] TEMP_MED ;      // Medium temperature threshold
    reg [7:0] TEMP_HIGH;      // High temperature threshold
    reg [7:0]  temp_adc_in;   // Temperature sensor input (0-255)

    reg setup;
    // APB Protocol States
    always @(posedge clk or posedge reset)
	begin
        if (reset)
        begin
            prdata   <= 8'b0;
            pready   <= 1'b0;
            pslverr  <= 1'b0;
            TEMP_LOW <= 8'd30;
            TEMP_MED <= 8'd60;
            TEMP_HIGH <=8'd90;
            setup  <= 1'b0;
        end
        else
        begin
            if (psel && !penable && !setup)
            begin
                // Setup phase: Indicate the slave is not yet ready
                pready <= 1'b0;
                setup  <= 1'b1;

            end
            else if (psel && penable && setup)
            begin
                // Access phase: Perform read/write operation and indicate ready
                pready <= 1'b1; // Slave is ready for the current operation
                setup  <= 1'b0;
                if (pwrite)
                 begin
                    // Write Operation
                    case(paddr)
                          8'h0a: begin
                                  TEMP_LOW    <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0b: begin
                                  TEMP_MED    <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0c: begin
                                  TEMP_HIGH   <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0f: begin
                                  temp_adc_in <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          default:pslverr     <= 1'b1;
                    endcase
                end
                else
                begin
                    // Read Operation
                    case(paddr)
                          8'h0a: begin
                                  prdata   <= TEMP_LOW ;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0b: begin
                                  prdata   <= TEMP_MED ;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0c: begin
                                  prdata   <= TEMP_HIGH;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0f: begin
                                  prdata   <= temp_adc_in;
                                  pslverr  <= 1'b0;
                                  end
                          default:pslverr  <= 1'b1;
                    endcase
                end
            end
            else
            begin
                // Default case: Clear ready signal when not selected
                pready <= 1'b0;
                setup  <= 1'b0;
            end
        end
    end

    // PWM control
    reg [7:0] pwm_duty_cycle;    // Duty cycle (0-255)
    reg [7:0] pwm_counter;       // Counter for PWM generation
    wire [2:0] speed_control;    //speed control bit
    // Fan speed adjustment logic
    always @(posedge clk or posedge reset) begin
        if (reset)
        begin
            pwm_duty_cycle <= 8'd0;  // Fan off by default
        end
        else
        begin
            case(speed_control)
              3'd1 : pwm_duty_cycle <= 8'd64;  // Low speed (25% duty cycle)
              3'd2 : pwm_duty_cycle <= 8'd128; // Medium speed (50% duty cycle)
              3'd3 : pwm_duty_cycle <= 8'd192; // High speed (75% duty cycle)
              3'd4 : pwm_duty_cycle <= 8'd255; // Full speed (100% duty cycle)
            default :  pwm_duty_cycle <= 8'd255; // Full speed (100% duty cycle)
            endcase

        end
    end

    assign speed_control = (temp_adc_in < TEMP_LOW ? 3'd1 :
                           (temp_adc_in < TEMP_MED ? 3'd2 :
                           (temp_adc_in < TEMP_HIGH ? 3'd3 : 3'd4)));

    // PWM generation logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pwm_counter <= 8'd0;
            fan_pwm_out <= 1'b0;
        end else begin
            pwm_counter <= pwm_counter + 1;
            fan_pwm_out <= (pwm_counter < pwm_duty_cycle) ? 1'b1 : 1'b0;
        end
    end

endmodule

module fan_controller (
    input wire clk,                 // System clock
    input wire reset,               // Reset signal
    output reg fan_pwm_out,         // PWM output for fan control

    //APB signals
    input  wire         psel,       // Slave select
    input  wire         penable,    // Enable signal
    input  wire         pwrite,     // Write control
    input  wire [7:0]   paddr,      // Address bus
    input  wire [7:0]   pwdata,     // Write data bus
    output reg  [7:0]   prdata,     // Read data bus
    output reg          pready,      // Ready signal
    output reg          pslverr     // Slave error
);

    // Parameters for temperature thresholds
    reg [7:0] TEMP_LOW ;      // Low temperature threshold
    reg [7:0] TEMP_MED ;      // Medium temperature threshold
    reg [7:0] TEMP_HIGH;      // High temperature threshold
    reg [7:0]  temp_adc_in;   // Temperature sensor input (0-255)

    reg setup;
    // APB Protocol States
    always @(posedge clk or posedge reset)
	begin
        if (reset)
        begin
            prdata   <= 8'b0;
            pready   <= 1'b0;
            pslverr  <= 1'b0;
            TEMP_LOW <= 8'd30;
            TEMP_MED <= 8'd60;
            TEMP_HIGH <=8'd90;
            setup  <= 1'b0;
        end
        else
        begin
            if (psel && !penable && !setup)
            begin
                // Setup phase: Indicate the slave is not yet ready
                pready <= 1'b0;
                setup  <= 1'b1;

            end
            else if (psel && penable && setup)
            begin
                // Access phase: Perform read/write operation and indicate ready
                pready <= 1'b1; // Slave is ready for the current operation
                setup  <= 1'b0;
                if (pwrite)
                 begin
                    // Write Operation
                    case(paddr)
                          8'h0a: begin
                                  TEMP_LOW    <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0b: begin
                                  TEMP_MED    <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0c: begin
                                  TEMP_HIGH   <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0f: begin
                                  temp_adc_in <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          default:pslverr     <= 1'b1;
                    endcase
                end
                else
                begin
                    // Read Operation
                    case(paddr)
                          8'h0a: begin
                                  prdata   <= TEMP_LOW ;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0b: begin
                                  prdata   <= TEMP_MED ;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0c: begin
                                  prdata   <= TEMP_HIGH;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0f: begin
                                  prdata   <= temp_adc_in;
                                  pslverr  <= 1'b0;
                                  end
                          default:pslverr  <= 1'b1;
                    endcase
                end
            end
            else
            begin
                // Default case: Clear ready signal when not selected
                pready <= 1'b0;
                setup  <= 1'b0;
            end
        end
    end

    // PWM control
    reg [7:0] pwm_duty_cycle;    // Duty cycle (0-255)
    reg [7:0] pwm_counter;       // Counter for PWM generation

    // Fan speed adjustment logic (area-optimized):
    // The original design encoded a 3-bit intermediate "speed_control" from the
    // temperature comparisons and then decoded it back to an 8-bit duty cycle
    // through a case statement whose default (and its 3'd4 branch) map to full
    // speed. That encode-then-decode round-trip (and its 3-bit intermediate net)
    // is redundant. Fold it into a single direct priority chain driven straight
    // by the same temperature comparisons. An if/else-if chain (not a ternary)
    // is used so that, like the original's case default, an undefined
    // temperature comparison falls through to full speed (255) rather than
    // propagating X -- keeping the design bit-for-bit equivalent including
    // power-up X behavior. The duty cycle stays registered (identical timing),
    // and the intermediate wire plus the decoder logic are removed.
    always @(posedge clk or posedge reset) begin
        if (reset)
        begin
            pwm_duty_cycle <= 8'd0;  // Fan off by default
        end
        else
        begin
            if      (temp_adc_in < TEMP_LOW )  pwm_duty_cycle <= 8'd64;  // Low speed  (25%)
            else if (temp_adc_in < TEMP_MED )  pwm_duty_cycle <= 8'd128; // Medium     (50%)
            else if (temp_adc_in < TEMP_HIGH)  pwm_duty_cycle <= 8'd192; // High speed (75%)
            else                               pwm_duty_cycle <= 8'd255; // Full speed (100%)
        end
    end

    // PWM generation logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pwm_counter <= 8'd0;
            fan_pwm_out <= 1'b0;
        end else begin
            pwm_counter <= pwm_counter + 1;
            fan_pwm_out <= (pwm_counter < pwm_duty_cycle) ? 1'b1 : 1'b0;
        end
    end

endmodule

module fibonacci_series (
    input  wire        clk,
    input  wire        rst,
    output reg  [31:0] fib_out,
    output reg         overflow_flag
);

    // F(n-2) and F(n-1)
    reg [31:0] RegA;
    reg [31:0] RegB;

    // set when a computed Fibonacci number exceeds 32 bits; used to defer the
    // overflow_flag / restart by exactly one clock cycle.
    reg overflow_detected;

    // 33-bit sum so that bit [32] is the overflow (carry) bit.
    wire [32:0] next_fib = RegA + RegB;

    always @(posedge clk) begin
        if (rst) begin
            // Reset behaviour: F(0)=0, F(1)=1, output F(0)=0, flag cleared.
            RegA              <= 32'd0;
            RegB              <= 32'd1;
            fib_out           <= 32'd0;
            overflow_flag     <= 1'b0;
            overflow_detected <= 1'b0;
        end else if (overflow_detected) begin
            // One clock cycle after overflow was detected: raise the flag,
            // drive the output to 0 and restart the sequence from F(0),F(1).
            overflow_flag     <= 1'b1;
            fib_out           <= 32'd0;
            RegA              <= 32'd0;
            RegB              <= 32'd1;
            overflow_detected <= 1'b0;
        end else begin
            if (next_fib[32]) begin
                // Overflow this cycle: propagate the last valid Fibonacci
                // number (RegB) to the output and remember the overflow so the
                // flag/restart happen on the following clock cycle.
                overflow_detected <= 1'b1;
                fib_out           <= RegB;
                overflow_flag     <= 1'b0;
                // RegA/RegB hold their (last valid) values.
            end else begin
                // Normal Fibonacci progression.
                RegA              <= RegB;
                RegB              <= next_fib[31:0];
                fib_out           <= next_fib[31:0];
                overflow_flag     <= 1'b0;
                overflow_detected <= 1'b0;
            end
        end
    end

endmodule

module fifo_async #(
    parameter DATA_WIDTH = 8,
    parameter DEPTH      = 16
) (
    input  wire                  w_clk,
    input  wire                  w_rst,
    input  wire                  w_inc,
    input  wire [DATA_WIDTH-1:0] w_data,
    input  wire                  r_clk,
    input  wire                  r_rst,
    input  wire                  r_inc,
    output reg                   w_full,
    output reg                   r_empty,
    output wire [DATA_WIDTH-1:0] r_data
);

    // Address width; pointers carry one extra (MSB) bit to detect wrap/overflow.
    localparam ADDR_WIDTH = $clog2(DEPTH);

    // Storage.
    reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // Write-domain pointers (binary + gray).
    reg  [ADDR_WIDTH:0] w_bin, w_gray;
    wire [ADDR_WIDTH:0] w_bin_next, w_gray_next;

    // Read-domain pointers (binary + gray).
    reg  [ADDR_WIDTH:0] r_bin, r_gray;
    wire [ADDR_WIDTH:0] r_bin_next, r_gray_next;

    // Cross-clock synchronizers (two registers in series).
    reg  [ADDR_WIDTH:0] rptr_sync1, rptr_sync2; // read gray ptr -> write domain
    reg  [ADDR_WIDTH:0] wptr_sync1, wptr_sync2; // write gray ptr -> read domain

    // ------------------------------------------------------------------
    // Write pointer logic
    // ------------------------------------------------------------------
    assign w_bin_next  = w_bin + (w_inc & ~w_full);
    assign w_gray_next = (w_bin_next >> 1) ^ w_bin_next;

    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            w_bin  <= {(ADDR_WIDTH+1){1'b0}};
            w_gray <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            w_bin  <= w_bin_next;
            w_gray <= w_gray_next;
        end
    end

    // Memory write port.
    always @(posedge w_clk) begin
        if (w_inc & ~w_full)
            mem[w_bin[ADDR_WIDTH-1:0]] <= w_data;
    end

    // ------------------------------------------------------------------
    // Read pointer logic
    // ------------------------------------------------------------------
    assign r_bin_next  = r_bin + (r_inc & ~r_empty);
    assign r_gray_next = (r_bin_next >> 1) ^ r_bin_next;

    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            r_bin  <= {(ADDR_WIDTH+1){1'b0}};
            r_gray <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            r_bin  <= r_bin_next;
            r_gray <= r_gray_next;
        end
    end

    // Combinational memory read (spec declares r_data as a plain output).
    assign r_data = mem[r_bin[ADDR_WIDTH-1:0]];

    // ------------------------------------------------------------------
    // Synchronizers
    // ------------------------------------------------------------------
    // Read gray pointer synchronized into the write clock domain.
    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            rptr_sync1 <= {(ADDR_WIDTH+1){1'b0}};
            rptr_sync2 <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            rptr_sync1 <= r_gray;
            rptr_sync2 <= rptr_sync1;
        end
    end

    // Write gray pointer synchronized into the read clock domain.
    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            wptr_sync1 <= {(ADDR_WIDTH+1){1'b0}};
            wptr_sync2 <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            wptr_sync1 <= w_gray;
            wptr_sync2 <= wptr_sync1;
        end
    end

    // ------------------------------------------------------------------
    // Full / Empty generation
    // ------------------------------------------------------------------
    // Full: top two gray bits inverted, remaining bits equal (the gray-code
    // equivalent of "MSB differs, all other bits equal" on the binary pointers).
    wire w_full_val = (w_gray_next == {~rptr_sync2[ADDR_WIDTH:ADDR_WIDTH-1],
                                        rptr_sync2[ADDR_WIDTH-2:0]});

    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) w_full <= 1'b0;
        else       w_full <= w_full_val;
    end

    // Empty: read and write gray pointers exactly equal.
    wire r_empty_val = (r_gray_next == wptr_sync2);

    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) r_empty <= 1'b1;
        else       r_empty <= r_empty_val;
    end

endmodule


