module ping_pong_fifo_2_axi_stream #(
  parameter logic                              DATA_WIDTH          = 24,
  parameter logic                              STROBE_WIDTH        = DATA_WIDTH / 8,
  parameter logic                              USE_KEEP            = 0,
  parameter logic                              USER_IN_DATA        = 1
)(
  input  logic                                 rst,

  // Ping Pong FIFO Read Interface
  input  logic                                 i_block_fifo_rdy,
  output logic                                 o_block_fifo_act,
  input  logic [23:0]                          i_block_fifo_size,
  input  logic [(DATA_WIDTH + 1) - 1:0]        i_block_fifo_data,
  output logic                                 o_block_fifo_stb,
  input  logic [3:0]                           i_axi_user,

  // AXI Stream Output
  input  logic                                 i_axi_clk,
  output logic [3:0]                           o_axi_user,
  input  logic                                 i_axi_ready,
  output logic [DATA_WIDTH - 1:0]              o_axi_data,
  output logic                                 o_axi_last,
  output logic                                 o_axi_valid
);

// Internal signals
logic [DATA_WIDTH - 1:0] fifo_data_buffer;
logic fifo_valid_buffer;
logic fifo_last_buffer;

// Burst read bookkeeping
logic [23:0] r_count;   // number of words already accepted in the current block
logic [23:0] r_size;    // number of words in the currently activated block

//---------------------------------------------------------------------------
// Combinational (asynchronous) outputs
//---------------------------------------------------------------------------
// The FIFO word carries {last, data}.  While a word is being presented on the
// AXI-Stream interface it is a straight pass-through of the current FIFO word
// at the read pointer (Example 1).  The strobe reads/advances the FIFO only
// when the downstream sink actually accepts the beat (valid && ready), so no
// data is lost when i_axi_ready is deasserted.
assign o_axi_data       = i_block_fifo_data[DATA_WIDTH - 1:0];
assign o_axi_last       = i_block_fifo_data[DATA_WIDTH];
assign o_axi_user       = i_axi_user;
assign o_block_fifo_stb = o_axi_valid & i_axi_ready;

//---------------------------------------------------------------------------
// Synchronous control (single clock domain: i_axi_clk, async active-high rst)
//---------------------------------------------------------------------------
always_ff @(posedge i_axi_clk or posedge rst) begin
  if (rst) begin
    o_block_fifo_act   <= 1'b0;
    o_axi_valid        <= 1'b0;
    fifo_data_buffer   <= {DATA_WIDTH{1'b0}};
    fifo_valid_buffer  <= 1'b0;
    fifo_last_buffer   <= 1'b0;
    r_count            <= 24'd0;
    r_size             <= 24'd0;
  end else begin
    if (!o_block_fifo_act) begin
      // Idle: not currently reading a block.  No data is read while the FIFO
      // is not ready (Example 2).
      o_axi_valid       <= 1'b0;
      fifo_valid_buffer <= 1'b0;
      if (i_block_fifo_rdy) begin
        // A block is ready: activate it and capture its word count.
        o_block_fifo_act <= 1'b1;
        r_count          <= 24'd0;
        r_size           <= i_block_fifo_size;
      end
    end
    else begin
      // Active: streaming the words of the activated block.
      if (r_count < r_size) begin
        // Present the current FIFO word to the AXI-Stream interface.
        o_axi_valid       <= 1'b1;
        fifo_data_buffer  <= i_block_fifo_data[DATA_WIDTH - 1:0];
        fifo_last_buffer  <= i_block_fifo_data[DATA_WIDTH];
        fifo_valid_buffer <= 1'b1;

        // A beat is transferred when it is accepted by the sink.  The strobe
        // (o_block_fifo_stb) advances the FIFO read pointer on the same event.
        if (o_axi_valid && i_axi_ready) begin
          r_count <= r_count + 24'd1;
          if ((r_count + 24'd1) >= r_size) begin
            // Last word of the block just accepted: stop and release.
            o_axi_valid       <= 1'b0;
            fifo_valid_buffer <= 1'b0;
            o_block_fifo_act  <= 1'b0;
          end
        end
      end
      else begin
        // Zero-length block (or already drained): release the FIFO block.
        o_axi_valid       <= 1'b0;
        fifo_valid_buffer <= 1'b0;
        o_block_fifo_act  <= 1'b0;
      end
    end
  end
end

endmodule

module ping_pong_fifo_2_axi_stream #(
    parameter DATA_WIDTH = 32
)(
    input  logic                                 rst,

    // Flush / Pause Controls
    input  logic                                 i_flush,
    input  logic                                 i_pause,

    // Ping Pong FIFO Read Interface
    input  logic                                 i_block_fifo_rdy,
    output logic                                 o_block_fifo_act,
    input  logic [23:0]                          i_block_fifo_size,
    input  logic [(DATA_WIDTH + 1) - 1:0]        i_block_fifo_data,
    output logic                                 o_block_fifo_stb,
    input  logic [3:0]                           i_axi_user,

    // AXI Stream Output
    input  logic                                 i_axi_clk,
    output logic [3:0]                           o_axi_user,
    input  logic                                 i_axi_ready,
    output logic [DATA_WIDTH - 1:0]              o_axi_data,
    output logic                                 o_axi_last,
    output logic                                 o_axi_valid
);

    // Internal Registers
    logic [23:0]                    block_size_reg;
    logic [23:0]                    data_count;
    logic                           fifo_active;

    // Improved data handling
    logic [(DATA_WIDTH + 1) - 1:0]  fifo_data_reg;    // Intermediate data register
    logic                           fifo_data_valid;  // Data validity flag
    logic                           data_pending;     // Pending data indicator

    typedef enum logic [1:0] {
        IDLE,
        READ_FIFO,
        SEND_AXI
    } state_t;

    state_t current_state;

    always_ff @(posedge i_axi_clk or posedge rst) begin
        if (rst) begin
            current_state    <= IDLE;
            block_size_reg   <= 24'd0;
            data_count       <= 24'd0;
            fifo_active      <= 1'b0;
            fifo_data_reg    <= {(DATA_WIDTH + 1){1'b0}};
            fifo_data_valid  <= 1'b0;
            data_pending     <= 1'b0;
            o_block_fifo_act <= 1'b0;
            o_block_fifo_stb <= 1'b0;
            o_axi_valid      <= 1'b0;
            o_axi_data       <= {DATA_WIDTH{1'b0}};
            o_axi_last       <= 1'b0;
            o_axi_user       <= 4'd0;
        end else begin
            // Default output values each clock cycle for signal stability
            o_block_fifo_act <= 1'b0;
            o_block_fifo_stb <= 1'b0;
            o_axi_valid      <= 1'b0;
            o_axi_last       <= 1'b0;
            o_axi_user       <= 4'd0;

            if (i_flush) begin
                // Immediate reset of the state machine, clear pending operations
                current_state    <= IDLE;
                block_size_reg   <= 24'd0;
                data_count       <= 24'd0;
                fifo_active      <= 1'b0;
                fifo_data_reg    <= {(DATA_WIDTH + 1){1'b0}};
                fifo_data_valid  <= 1'b0;
                data_pending     <= 1'b0;
                o_block_fifo_act <= 1'b0;
                o_block_fifo_stb <= 1'b0;
                o_axi_valid      <= 1'b0;
                o_axi_data       <= {DATA_WIDTH{1'b0}};
                o_axi_last       <= 1'b0;
                o_axi_user       <= 4'd0;
            end else begin
                case (current_state)
                    IDLE: begin
                        fifo_data_valid <= 1'b0;
                        data_pending    <= 1'b0;
                        if (i_block_fifo_rdy) begin
                            o_block_fifo_act <= 1'b1;
                            block_size_reg   <= i_block_fifo_size;
                            fifo_active      <= 1'b1;
                            data_count       <= 24'd0;
                            current_state    <= READ_FIFO;
                        end
                    end

                    READ_FIFO: begin
                        if (fifo_active && i_block_fifo_rdy) begin
                            o_block_fifo_stb <= 1'b1;
                            fifo_data_reg    <= i_block_fifo_data;
                            fifo_data_valid  <= 1'b1;
                            data_count       <= data_count + 24'd1;
                            data_pending     <= 1'b0;
                            current_state    <= SEND_AXI;
                        end else begin
                            data_pending <= 1'b1;
                        end
                    end

                    SEND_AXI: begin
                        if (i_pause) begin
                            // Suspend transmission, retain state and internal data
                            current_state <= SEND_AXI;
                        end else if (fifo_data_valid && i_axi_ready) begin
                            o_axi_valid <= 1'b1;
                            o_axi_data  <= fifo_data_reg[DATA_WIDTH-1:0];
                            o_axi_user  <= i_axi_user;
                            fifo_data_valid <= 1'b0;

                            if (data_count >= block_size_reg) begin
                                o_axi_last    <= 1'b1;
                                fifo_active   <= 1'b0;
                                current_state <= IDLE;
                            end else begin
                                current_state <= READ_FIFO;
                            end
                        end
                    end

                    default: current_state <= IDLE;
                endcase
            end
        end
    end

endmodule

// FILO_RTL : First-In-Last-Out (stack) buffer
// Parameterizable data width and depth.
module FILO_RTL #(
    parameter DATA_WIDTH = 8,
    parameter FILO_DEPTH = 16
) (
    input  wire                  clk,
    input  wire                  reset,
    input  wire                  push,
    input  wire                  pop,
    input  wire [DATA_WIDTH-1:0] data_in,
    output reg  [DATA_WIDTH-1:0] data_out,
    output reg                   full,
    output reg                   empty
);

    // Pointer must be able to represent 0 .. FILO_DEPTH (inclusive).
    localparam PTR_WIDTH = $clog2(FILO_DEPTH + 1);

    // Named internal stack pointer (spec-named 'top' -- preserve verbatim).
    reg [PTR_WIDTH-1:0]  top;

    // Stack storage.
    reg [DATA_WIDTH-1:0] mem [0:FILO_DEPTH-1];

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Asynchronous, active-HIGH reset: buffer cleared.
            top   <= {PTR_WIDTH{1'b0}};
            full  <= 1'b0;
            empty <= 1'b1;
        end else begin
            if (push && pop && empty) begin
                // Feedthrough: empty buffer with simultaneous push+pop.
                // Data passes straight through without being stored.
                data_out <= data_in;
                empty    <= 1'b1;
                full     <= 1'b0;
            end else if (push && !full) begin
                // Push: store data at 'top', advance pointer.
                mem[top] <= data_in;
                top      <= top + 1'b1;
                empty    <= 1'b0;
                if ((top + 1'b1) == FILO_DEPTH)
                    full <= 1'b1;
                else
                    full <= 1'b0;
            end else if (pop && !empty) begin
                // Pop: retreat pointer, drive top-of-stack to data_out.
                top      <= top - 1'b1;
                data_out <= mem[top - 1'b1];
                full     <= 1'b0;
                if ((top - 1'b1) == {PTR_WIDTH{1'b0}})
                    empty <= 1'b1;
                else
                    empty <= 1'b0;
            end
        end
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    data_out = 0;
  end

endmodule

module FILO_RTL #(
    parameter DATA_WIDTH = 8,  // Width of the data entries
    parameter FILO_DEPTH = 16  // Depth of the FILO buffer
) (
    input  wire                  clk,       // Clock signal
    input  wire                  reset,     // Asynchronous reset signal
    input  wire                  push,      // Push control signal
    input  wire                  pop,       // Pop control signal
    input  wire [DATA_WIDTH-1:0] data_in,   // Data input
    output reg  [DATA_WIDTH-1:0] data_out,  // Data output
    output reg                   full,      // Full status signal
    output reg                   empty      // Empty status signal
);


  reg [DATA_WIDTH-1:0] memory[FILO_DEPTH-1:0];
  reg [$clog2(FILO_DEPTH):0] top;

  reg feedthrough_valid;
  reg [DATA_WIDTH-1:0] feedthrough_data;


  always @(posedge clk or posedge reset) begin
    if (reset) begin
      top <= 0;
      empty <= 1;
      full <= 0;
      feedthrough_valid <= 0;
      data_out <= 0;
    end else begin

      if (push && pop && empty) begin
        data_out <= data_in;
        feedthrough_data <= data_in;
        feedthrough_valid <= 1;
      end else begin

        if (push && !full) begin
          memory[top] <= data_in;
          top <= top + 1;
          feedthrough_valid <= 0;
        end

        if (pop && !empty) begin
          if (feedthrough_valid) begin
            data_out <= feedthrough_data;
            feedthrough_valid <= 0;
          end else begin
            top <= top - 1;
            data_out <= memory[top-1];
          end
        end
      end

      empty <= (top == 0);
      full  <= (top == FILO_DEPTH);
    end
  end
endmodule

`timescale 1ns/1ps

module FindFasterClock(
    input  wire clk_A,
    input  wire clk_B,
    input  wire rst_n,            // Active-low reset
    output reg  A_faster_than_B,  // 1 if clk_A is measured faster
    output reg  valid             // 1 once both clocks have measured a period
);

    //----------------------------------------
    // Internal signals
    //----------------------------------------
    reg        measure_B;
    reg [31:0] b_count;
    reg [31:0] periodA;
    reg        done_A;
    reg        measure_A;
    reg [31:0] a_count;
    reg [31:0] periodB;
    reg        done_B;

    // A-domain FSM for measuring "periodA"
    reg [1:0] stateA;
    localparam A_IDLE    = 2'd0,
               A_COUNT   = 2'd1,
               A_DONE    = 2'd2;
    // B-domain FSM for measuring "periodB"
    reg [1:0] stateB;
    localparam B_IDLE    = 2'd0,
               B_COUNT   = 2'd1,
               B_DONE    = 2'd2;

    // Clock A FSM
    always @(posedge clk_A or negedge rst_n) begin
        if (!rst_n) begin
            stateA <= A_IDLE;
            measure_B <= 0;
            b_count <= 0;
            periodA <= 0;
            done_A <= 0;
        end else begin
            case (stateA)
                A_IDLE: begin
                    // Start measurement: enable the clk_B pulse counter and
                    // move to the counting state for exactly one clk_A period.
                    measure_B <= 1'b1;
                    stateA    <= A_COUNT;
                end
                A_COUNT: begin
                    // One full clk_A period has elapsed while measure_B was
                    // asserted. Capture the accumulated clk_B pulse count as
                    // periodA, stop counting, and finalize.
                    periodA   <= b_count;
                    measure_B <= 1'b0;
                    done_A    <= 1'b1;
                    stateA    <= A_DONE;
                end
                A_DONE: begin
                    // Hold the measured result.
                    measure_B <= 1'b0;
                    done_A    <= 1'b1;
                    stateA    <= A_DONE;
                end
                default: stateA <= A_IDLE;
            endcase
        end
    end

    // Clock B FSM
    always @(posedge clk_B or negedge rst_n) begin
        if (!rst_n) begin
            stateB <= B_IDLE;
            measure_A <= 0;
            a_count <= 0;
            periodB <= 0;
            done_B <= 0;
        end else begin
            case (stateB)
                B_IDLE: begin
                    // Start measurement: enable the clk_A pulse counter and
                    // move to the counting state for exactly one clk_B period.
                    measure_A <= 1'b1;
                    stateB    <= B_COUNT;
                end
                B_COUNT: begin
                    // One full clk_B period has elapsed while measure_A was
                    // asserted. Capture the accumulated clk_A pulse count as
                    // periodB, stop counting, and finalize.
                    periodB   <= a_count;
                    measure_A <= 1'b0;
                    done_B    <= 1'b1;
                    stateB    <= B_DONE;
                end
                B_DONE: begin
                    // Hold the measured result.
                    measure_A <= 1'b0;
                    done_B    <= 1'b1;
                    stateB    <= B_DONE;
                end
                default: stateB <= B_IDLE;
            endcase
        end
    end

    // In B-domain, if measure_B=1, increment b_count on each B rising edge
    always @(posedge clk_B or negedge rst_n) begin
        if (!rst_n) begin
            b_count <= 0;
        end else if (measure_B) begin
            b_count <= b_count + 1'b1;
        end
    end

    // In A-domain, if measure_A=1, increment a_count on each A rising edge
    always @(posedge clk_A or negedge rst_n) begin
        if (!rst_n) begin
            a_count <= 0;
        end else if (measure_A) begin
            a_count <= a_count + 1'b1;
        end
    end

    // Combine results
    // valid = done_A && done_B
    always @(*) begin
        if (!rst_n) begin
            valid = 0;
            A_faster_than_B = 0;
        end else begin
            valid = (done_A && done_B);
            if (valid) begin
                // periodA = # of clk_B pulses in one clk_A cycle (small when A fast)
                // periodB = # of clk_A pulses in one clk_B cycle (large when A fast)
                // Hence periodB > periodA => clk_A is faster.
                if (periodB > periodA)
                    A_faster_than_B = 1'b1;
                else
                    A_faster_than_B = 1'b0;
            end else begin
                A_faster_than_B = 0;
            end
        end
    end

endmodule


