module SR_flipflop(
    input i_S,        // Set input
    input i_R,        // Reset input
    input i_clk,      // Clock input
    input i_rst_b,    // Asynchronous active-low reset input
    output reg o_Q,   // Output Q
    output reg o_Q_b  // Inverted output Q
);

    // Always block triggered on the positive edge of the clock
    // and asynchronous (active-low) system reset
    always @(posedge i_clk or negedge i_rst_b)
    begin
        if (!i_rst_b) // Asynchronous reset active-low
        begin
            o_Q   <= 1'b0;  // Set output Q to 0
            o_Q_b <= 1'b1;  // Set inverted output Q to 1
        end
        else
        begin
            case ({i_S, i_R})
                2'b00: begin           // Hold current state
                    o_Q   <= o_Q;
                    o_Q_b <= o_Q_b;
                end
                2'b01: begin           // Reset: o_Q -> 0
                    o_Q   <= 1'b0;
                    o_Q_b <= 1'b1;
                end
                2'b10: begin           // Set: o_Q -> 1
                    o_Q   <= 1'b1;
                    o_Q_b <= 1'b0;
                end
                2'b11: begin           // Invalid: both outputs low
                    o_Q   <= 1'b0;
                    o_Q_b <= 1'b0;
                end
            endcase
        end
    end

endmodule

module JK_flipflop(
    input i_J,       // J input of the JK flip-flop
    input i_K,       // K input of the JK flip-flop
    input i_clk,     // Clock input
    input i_rst_b,   // Asynchronous reset, active low
    output reg o_Q,  // Q output
    output reg o_Q_b // Inverted Q output
);

    // Rising edge of clock, or asynchronous falling edge of active-low reset
    always @(posedge i_clk or negedge i_rst_b)
    begin
        if (!i_rst_b) // Asynchronous reset active (low)
        begin
            o_Q   <= 1'b0; // Force Q low
            o_Q_b <= 1'b1; // Force Q_b high
        end
        else
        begin
            case ({i_J, i_K})
                2'b00: begin // Hold previous state
                    o_Q   <= o_Q;
                    o_Q_b <= o_Q_b;
                end
                2'b01: begin // Reset: Q low
                    o_Q   <= 1'b0;
                    o_Q_b <= 1'b1;
                end
                2'b10: begin // Set: Q high
                    o_Q   <= 1'b1;
                    o_Q_b <= 1'b0;
                end
                2'b11: begin // Toggle
                    o_Q   <= ~o_Q;
                    o_Q_b <= ~o_Q_b;
                end
            endcase
        end
    end

endmodule

// FSM sequence detector for the 8-bit pattern 10110001 (MSB first).
// Detects overlapping occurrences on a continuous serial input.
module fsm_seq_detector
(
    input  bit     clk_in,        // Free running clock, act on rising edge
    input  logic   rst_in,        // Asynchronous active-high reset
    input  logic   seq_in,        // Continuous 1-bit serial input
    output logic   seq_detected   // High for one clock cycle on detection
);

    // Eight states: S0..S7 encoded as 3-bit values.
    // Sn = number of leading bits of "10110001" matched so far.
    typedef enum logic [2:0] {S0, S1, S2, S3, S4, S5, S6, S7} state_t;

    state_t cur_state, next_state;

    logic seq_detected_w;

    // State register (async active-high reset to S0)
    always @(posedge clk_in or posedge rst_in) begin
        if (rst_in)
            cur_state <= S0;
        else
            cur_state <= next_state;
    end

    // Registered output, synchronized to clk_in
    always @(posedge clk_in or posedge rst_in) begin
        if (rst_in)
            seq_detected <= 1'b0;
        else
            seq_detected <= seq_detected_w;
    end

    // Next-state and combinational output logic.
    // Transitions follow the longest-prefix-that-is-a-suffix rule so that
    // overlapping sequences (e.g. ...0001 10001...) are detected correctly.
    always_comb begin
        next_state     = S0;
        seq_detected_w = 1'b0;
        case (cur_state)
            // matched ""       target pattern bit: 1
            S0: if (seq_in) next_state = S1; else next_state = S0;
            // matched "1"       next expected: 0
            S1: if (seq_in) next_state = S1; else next_state = S2;
            // matched "10"      next expected: 1
            S2: if (seq_in) next_state = S3; else next_state = S0;
            // matched "101"     next expected: 1
            S3: if (seq_in) next_state = S4; else next_state = S2;
            // matched "1011"    next expected: 0
            S4: if (seq_in) next_state = S1; else next_state = S5;
            // matched "10110"   next expected: 0
            S5: if (seq_in) next_state = S3; else next_state = S6;
            // matched "101100"  next expected: 0
            S6: if (seq_in) next_state = S1; else next_state = S7;
            // matched "1011000" next expected: 1 -> full match on seq_in==1
            S7: begin
                if (seq_in) begin
                    next_state     = S1;   // overlap: "10110001" ends in "1"
                    seq_detected_w = 1'b1;
                end
                else begin
                    next_state = S0;
                end
            end
            default: next_state = S0;
        endcase
    end

endmodule


