module fsm_seq_detector
(
    input  bit     clk_in,       // Free Running Clock
    input  logic   rst_in,       // Active HIGH reset
    input  logic   seq_in,       // Continuous 1-bit Sequence Input
    output logic   seq_detected  // '0': Not Detected. '1': Detected. Will be HIGH for 1 Clock cycle Only
);

typedef enum logic [2:0] {S0, S1, S2, S3, S4, S5, S6, S7} state_t;
state_t cur_state, next_state;

logic seq_detected_w;

always @ (posedge clk_in or posedge rst_in)
begin
    if (rst_in)
        cur_state <= S0;
    else
        cur_state <= next_state;
end

always_comb begin
    if (rst_in) begin
        seq_detected_w = 1'b0;
        next_state = S0;
    end
    else begin
        case (cur_state)
            S0: begin
                if (seq_in) begin
                    next_state = S0;
                    seq_detected_w = 1'b0;
                end
                else begin
                    next_state = S1;
                    seq_detected_w = 1'b0;
                end
            end
            S1: begin
                if (seq_in) begin
                    next_state = S2;
                    seq_detected_w = 1'b0;
                end
                else begin
                    next_state = S1;
                    seq_detected_w = 1'b0;
                end
            end
            S2: begin
                if (seq_in) begin
                    next_state = S0;
                    seq_detected_w = 1'b0;
                end
                else begin
                    next_state = S3;
                    seq_detected_w = 1'b0;
                end
            end
            S3: begin
                if (seq_in) begin
                    next_state = S2;
                    seq_detected_w = 1'b0;
                end
                else begin
                    next_state = S4;
                    seq_detected_w = 1'b0;
                end
            end
            S4: begin
                if (seq_in) begin
                    next_state = S5;
                    seq_detected_w = 1'b0;
                end
                else begin
                    next_state = S1;
                    seq_detected_w = 1'b0;
                end
            end
            S5: begin
                if (seq_in) begin
                    next_state = S6;
                    seq_detected_w = 1'b0;
                end
                else begin
                    next_state = S3;
                    seq_detected_w = 1'b0;
                end
            end
            S6: begin
                if (seq_in) begin
                    next_state = S7;
                    seq_detected_w = 1'b0;
                end
                else begin
                    next_state = S1;
                    seq_detected_w = 1'b0;
                end
            end
            S7: begin
                if (seq_in) begin
                    next_state = S0;
                    seq_detected_w = 1'b0;
                end
                else begin
                    next_state = S1;
                    seq_detected_w = 1'b1;
                end
            end
            default: begin
                next_state = S0;
                seq_detected_w = 1'b0;
            end
        endcase
    end
end

always @ (posedge clk_in or posedge rst_in)
begin
    if (rst_in)
        seq_detected <= 1'b0;
    else
        seq_detected <= seq_detected_w;
end

endmodule

/*
Galois field (2^8) matrix-based encryption/decryption system using AES's polynomial
to perform Galois field operations.

3-stage pipeline (latency = 3 cycles from the rising edge where i_valid is read as 1
to the rising edge where o_valid is 1):
  stage 1 : capture 4x4 byte matrix from i_data (decrypt: XOR key first)
  stage 2 : GF(2^8) products (x2/x3 for encrypt, x9/xB/xD/xE for decrypt) + matrix copy
  stage 3 : MixColumns result (encrypt: XOR key last)
*/

module galois_encryption #(
    parameter NBW_DATA = 'd128,
    parameter NBW_KEY  = 'd32
) (
    input  logic                clk,
    input  logic                rst_async_n,
    input  logic                i_encrypt,
    input  logic                i_valid,
    input  logic [NBW_DATA-1:0] i_data,
    input  logic                i_update_key,
    input  logic [NBW_KEY-1:0]  i_key,
    output logic                o_valid,
    output logic [NBW_DATA-1:0] o_data
);

// ----------------------------------------
// - Internal Parameters
// ----------------------------------------
localparam int NBW_WORD = 8;
localparam int LINES    = 4;
localparam int COLUMNS  = 4;
localparam int NBYTES   = NBW_DATA/NBW_WORD; // 16 data bytes
localparam int NKBYTES  = NBW_KEY /NBW_WORD; // 4  key  bytes

// GF(2^8) multiply by 2 (xtime), reduction by m(x) = x^8 + x^4 + x^3 + x + 1 (0x1B)
// MSB tested via bitwise AND (no bit-select); (b<<1) is truncated to 8 bits.
function automatic logic [7:0] gf_xtime (input logic [7:0] b);
    gf_xtime = ((b << 1) ^ ((b & 8'h80) ? 8'h1b : 8'h00)) & 8'hff;
endfunction

// ----------------------------------------
// - Byte unpack of i_data / key_ff (constant selects via generate)
//   Matrix element (line,column) -> byte index = column*LINES + line
//   Byte b occupies i_data[NBW_DATA-1-8*b -: 8]  (column-major AES layout)
// ----------------------------------------
logic [NBW_KEY-1:0] key_ff;

logic [NBW_WORD-1:0] ibyte [0:NBYTES-1];  // i_data bytes
logic [NBW_WORD-1:0] kbyte [0:NKBYTES-1]; // key bytes (row 0 = key[MSB byte])

genvar gb;
generate
    for (gb = 0; gb < NBYTES; gb = gb + 1) begin : g_ibyte
        assign ibyte[gb] = i_data[NBW_DATA-1-NBW_WORD*gb -: NBW_WORD];
    end
    for (gb = 0; gb < NKBYTES; gb = gb + 1) begin : g_kbyte
        assign kbyte[gb] = key_ff[NBW_KEY-1-NBW_WORD*gb -: NBW_WORD];
    end
endgenerate

// ----------------------------------------
// - Control registers
// ----------------------------------------
logic [2:0] valid_ff;   // 3-deep valid pipeline (latency 3)
logic       enc_s1;     // operation of datum in stage 1
logic       enc_s2;     // operation of datum in stage 2/3

// ----------------------------------------
// - Data pipeline registers
// ----------------------------------------
logic [NBW_WORD-1:0] s1   [LINES][COLUMNS]; // stage 1 : captured matrix
logic [NBW_WORD-1:0] x2_d [LINES][COLUMNS]; // stage 2 : b*02
logic [NBW_WORD-1:0] x3_d [LINES][COLUMNS]; // stage 2 : b*03
logic [NBW_WORD-1:0] x9_d [LINES][COLUMNS]; // stage 2 : b*09
logic [NBW_WORD-1:0] xb_d [LINES][COLUMNS]; // stage 2 : b*0b
logic [NBW_WORD-1:0] xd_d [LINES][COLUMNS]; // stage 2 : b*0d
logic [NBW_WORD-1:0] xe_d [LINES][COLUMNS]; // stage 2 : b*0e
logic [NBW_WORD-1:0] s1_d [LINES][COLUMNS]; // stage 2 : delayed copy of stage 1
logic [NBW_WORD-1:0] s3   [LINES][COLUMNS]; // stage 3 : result matrix

// combinational next-values
logic [NBW_WORD-1:0] x2_n [LINES][COLUMNS];
logic [NBW_WORD-1:0] x3_n [LINES][COLUMNS];
logic [NBW_WORD-1:0] x9_n [LINES][COLUMNS];
logic [NBW_WORD-1:0] xb_n [LINES][COLUMNS];
logic [NBW_WORD-1:0] xd_n [LINES][COLUMNS];
logic [NBW_WORD-1:0] xe_n [LINES][COLUMNS];
logic [NBW_WORD-1:0] s3_n [LINES][COLUMNS];

// output byte array (packed into o_data by generate)
logic [NBW_WORD-1:0] obyte [0:NBYTES-1];

integer li, ci;

// ----------------------------------------
// - Control registers (async active-low reset)
// ----------------------------------------
always_ff @(posedge clk or negedge rst_async_n) begin : ctrl_regs
    if (!rst_async_n) begin
        valid_ff <= 3'b0;
        enc_s1   <= 1'b0;
        enc_s2   <= 1'b0;
        key_ff   <= {NBW_KEY{1'b0}};
    end else begin
        valid_ff[0] <= i_valid;
        valid_ff[1] <= valid_ff[0];
        valid_ff[2] <= valid_ff[1];
        if (i_valid) enc_s1 <= i_encrypt;
        enc_s2 <= enc_s1;
        if (i_update_key) key_ff <= i_key;
    end
end

// ----------------------------------------
// - Stage 1 : input data mapping (byte index = column*LINES + line)
//   Decryption pre-XORs the key (row byte) as the first step.
// ----------------------------------------
always_ff @(posedge clk) begin : stage1_capture
    if (i_valid) begin
        for (li = 0; li < LINES; li++) begin
            for (ci = 0; ci < COLUMNS; ci++) begin
                if (i_encrypt) begin
                    s1[li][ci] <= ibyte[ci*LINES + li];
                end else begin
                    s1[li][ci] <= ibyte[ci*LINES + li] ^ kbyte[li];
                end
            end
        end
    end
end

// ----------------------------------------
// - Stage 2 : GF(2^8) products (compute all; stage 3 selects encrypt/decrypt)
// ----------------------------------------
always_comb begin : stage2_comb
    logic [NBW_WORD-1:0] b, x2, x4, x8;
    for (li = 0; li < LINES; li++) begin
        for (ci = 0; ci < COLUMNS; ci++) begin
            b  = s1[li][ci];
            x2 = gf_xtime(b);
            x4 = gf_xtime(x2);
            x8 = gf_xtime(x4);
            x2_n[li][ci] = x2;             // b*02
            x3_n[li][ci] = x2 ^ b;         // b*03
            x9_n[li][ci] = x8 ^ b;         // b*09
            xb_n[li][ci] = x8 ^ x2 ^ b;    // b*0b
            xd_n[li][ci] = x8 ^ x4 ^ b;    // b*0d
            xe_n[li][ci] = x8 ^ x4 ^ x2;   // b*0e
        end
    end
end

always_ff @(posedge clk) begin : stage2_regs
    for (li = 0; li < LINES; li++) begin
        for (ci = 0; ci < COLUMNS; ci++) begin
            x2_d[li][ci] <= x2_n[li][ci];
            x3_d[li][ci] <= x3_n[li][ci];
            x9_d[li][ci] <= x9_n[li][ci];
            xb_d[li][ci] <= xb_n[li][ci];
            xd_d[li][ci] <= xd_n[li][ci];
            xe_d[li][ci] <= xe_n[li][ci];
            s1_d[li][ci] <= s1[li][ci];
        end
    end
end

// ----------------------------------------
// - Stage 3 : MixColumns
//   Encrypt : Re = M x data_in, then XOR key per row (last step).
//     The coefficient-1 (identity) terms read the *live* captured matrix (s1),
//     matching the reference datapath where those bytes are taken from the
//     current data-in register while the x2/x3 products are the delayed copies.
//   Decrypt : Rd = N x data_key  (key already applied at stage 1)
// ----------------------------------------
always_comb begin : stage3_comb
    for (ci = 0; ci < COLUMNS; ci++) begin
        if (enc_s2) begin
            s3_n[0][ci] = (x2_d[0][ci] ^ x3_d[1][ci] ^ s1[2][ci] ^ s1[3][ci]) ^ kbyte[0];
            s3_n[1][ci] = (x2_d[1][ci] ^ x3_d[2][ci] ^ s1[3][ci] ^ s1[0][ci]) ^ kbyte[1];
            s3_n[2][ci] = (x2_d[2][ci] ^ x3_d[3][ci] ^ s1[0][ci] ^ s1[1][ci]) ^ kbyte[2];
            s3_n[3][ci] = (x2_d[3][ci] ^ x3_d[0][ci] ^ s1[1][ci] ^ s1[2][ci]) ^ kbyte[3];
        end else begin
            s3_n[0][ci] = xe_d[0][ci] ^ xb_d[1][ci] ^ xd_d[2][ci] ^ x9_d[3][ci];
            s3_n[1][ci] = xe_d[1][ci] ^ xb_d[2][ci] ^ xd_d[3][ci] ^ x9_d[0][ci];
            s3_n[2][ci] = xe_d[2][ci] ^ xb_d[3][ci] ^ xd_d[0][ci] ^ x9_d[1][ci];
            s3_n[3][ci] = xe_d[3][ci] ^ xb_d[0][ci] ^ xd_d[1][ci] ^ x9_d[2][ci];
        end
    end
end

always_ff @(posedge clk) begin : stage3_regs
    for (li = 0; li < LINES; li++) begin
        for (ci = 0; ci < COLUMNS; ci++) begin
            s3[li][ci] <= s3_n[li][ci];
        end
    end
end

// ----------------------------------------
// - Output byte mapping (same layout as input) ; gated by valid
// ----------------------------------------
always_comb begin : out_mapping
    for (li = 0; li < LINES; li++) begin
        for (ci = 0; ci < COLUMNS; ci++) begin
            if (valid_ff[2]) obyte[ci*LINES + li] = s3[li][ci];
            else             obyte[ci*LINES + li] = {NBW_WORD{1'b0}};
        end
    end
end

generate
    for (gb = 0; gb < NBYTES; gb = gb + 1) begin : g_obyte
        assign o_data[NBW_DATA-1-NBW_WORD*gb -: NBW_WORD] = obyte[gb];
    end
endgenerate

assign o_valid = valid_ff[2];

endmodule : galois_encryption

module divider #
(
    parameter WIDTH = 32
)
(
    input  wire                  clk,
    input  wire                  rst_n,      // Active-low asynchronous reset
    input  wire                  start,      // Start signal for new operation
    input  wire [WIDTH-1 : 0]    dividend,   // Dividend (numerator)
    input  wire [WIDTH-1 : 0]    divisor,    // Divisor (denominator)
    output wire [WIDTH-1 : 0]    quotient,   // Result of the division
    output wire [WIDTH-1 : 0]    remainder,  // Remainder after division
    output wire                  valid       // Indicates output is valid
);

    localparam AW = WIDTH + 1;
    // Simple 3-state FSM
    localparam IDLE = 2'b00;
    localparam BUSY = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] state_reg, state_next;

    // A+Q combined into one WIDTH + 1 + WIDTH register:
    reg [AW+WIDTH-1 : 0] aq_reg,   aq_next;

    // Divisor register
    reg [AW-1 : 0]       m_reg,    m_next;

    // Iterate exactly WIDTH times
    reg [$clog2(WIDTH)-1:0] n_reg, n_next;

    // Final outputs
    reg [WIDTH-1:0] quotient_reg, quotient_next;
    reg [WIDTH-1:0] remainder_reg, remainder_next;
    reg valid_reg, valid_next;

    // Assign the top-level outputs
    assign quotient  = quotient_reg;
    assign remainder = remainder_reg;
    assign valid     = valid_reg;

    // Insert code here for non-restoring division

    // Combinational datapath temporaries for one iteration
    reg [AW+WIDTH-1:0] aq_shift;   // AQ shifted left by 1
    reg [AW-1:0]       a_shift;    // A portion after the shift
    reg [AW-1:0]       a_op;       // A after add/subtract of M
    reg [AW-1:0]       a_final;    // A after final adjustment
    reg                sign_pre;   // sign bit of A before the shift
    reg                q0;         // new LSB of Q

    // Sequential state / register update (active-low async reset)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_reg     <= IDLE;
            aq_reg        <= {(AW+WIDTH){1'b0}};
            m_reg         <= {AW{1'b0}};
            n_reg         <= {$clog2(WIDTH){1'b0}};
            quotient_reg  <= {WIDTH{1'b0}};
            remainder_reg <= {WIDTH{1'b0}};
            valid_reg     <= 1'b0;
        end else begin
            state_reg     <= state_next;
            aq_reg        <= aq_next;
            m_reg         <= m_next;
            n_reg         <= n_next;
            quotient_reg  <= quotient_next;
            remainder_reg <= remainder_next;
            valid_reg     <= valid_next;
        end
    end

    // Combinational next-state and non-restoring iteration logic
    always @(*) begin
        // Defaults: hold current values
        state_next     = state_reg;
        aq_next        = aq_reg;
        m_next         = m_reg;
        n_next         = n_reg;
        quotient_next  = quotient_reg;
        remainder_next = remainder_reg;
        valid_next     = valid_reg;

        // One non-restoring iteration computed on the current AQ:
        //  1) check sign of A (MSB of AQ) BEFORE the shift
        //  2) shift AQ left by one
        //  3) if sign was 1 -> A = A + M, else A = A - M
        //  4) Q[0] = (new sign of A == 1) ? 0 : 1
        aq_shift = aq_reg << 1;
        sign_pre = aq_reg[AW+WIDTH-1];
        a_shift  = aq_shift[AW+WIDTH-1 : WIDTH];
        a_op     = sign_pre ? (a_shift + m_reg) : (a_shift - m_reg);
        q0       = ~a_op[AW-1];
        // Final adjustment: if remaining A is negative, add M back
        a_final  = a_op[AW-1] ? (a_op + m_reg) : a_op;

        case (state_reg)
            IDLE: begin
                valid_next = 1'b0;
                if (start) begin
                    // Load: A = 0, Q = dividend, M = divisor, N = WIDTH iterations
                    aq_next        = { {AW{1'b0}}, dividend };
                    m_next         = { 1'b0, divisor };
                    n_next         = WIDTH - 1;             // count WIDTH-1 downto 0
                    quotient_next  = {WIDTH{1'b0}};
                    remainder_next = {WIDTH{1'b0}};
                    state_next     = BUSY;
                end
            end

            BUSY: begin
                // Commit this iteration's AQ
                aq_next = { a_op, aq_shift[WIDTH-1:1], q0 };
                if (n_reg == 0) begin
                    // Last iteration: apply final adjustment and latch outputs
                    quotient_next  = { aq_shift[WIDTH-1:1], q0 };
                    remainder_next = a_final[WIDTH-1:0];
                    valid_next     = 1'b1;
                    state_next     = DONE;
                end else begin
                    n_next = n_reg - 1'b1;
                end
            end

            DONE: begin
                // Hold outputs; keep valid asserted until start is de-asserted
                valid_next = 1'b1;
                if (!start) begin
                    valid_next = 1'b0;
                    state_next = IDLE;
                end
            end

            default: begin
                state_next = IDLE;
            end
        endcase
    end

endmodule

//////////////////////////////////////////////
// Top-Level Gold-Schmidt Division Module
//////////////////////////////////////////////
module divider (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         start,
    input  logic [17:0]  dividend,
    input  logic [17:0]  divisor,
    output logic [17:0]  dv_out,
    output logic         valid
);

    //////////////////////////////////////////////
    // Local parameters
    //////////////////////////////////////////////
    localparam logic [17:0] TWO  = 18'b000000010_000000000;
    localparam logic [17:0] ZERO = 18'b000000000_000000000;

    //////////////////////////////////////////////
    // Internal signals
    //////////////////////////////////////////////
    logic [17:0] D_0, N_0;
    logic [17:0] D, D2, D4, D6, D8, D10, D12, D14, D16, D18, D20;
    logic [17:0] N, N2, N4, N6, N8, N10, N12, N14, N16, N18, N20, N21;
    logic [17:0] F, F1, F2, F3, F4, F5, F6, F7, F8, F9;
    logic [47:0] D1, N1, D3, N3, D5, N5, D7, N7, D9, N9, D11, N11, D13, N13, D15, N15, D17, N17, D19, N19;

    // Pipeline stage flags
    logic st1, st2, st3, st4, st5, st6, st7, st8, st9, st10, st11, st12;

    // Prescaled (combinational) values derived from registered raw inputs
    logic [17:0] ps_b, ps_d;

    //////////////////////////////////////////////
    // Prescaling stage : bring divisor below 1.0
    //////////////////////////////////////////////
    pre_scaler u_pre_scaler (
        .a (D_0),   // registered raw divisor
        .c (N_0),   // registered raw dividend
        .b (ps_b),  // prescaled divisor  (< 1.0)
        .d (ps_d)   // prescaled dividend (same shift)
    );

    //////////////////////////////////////////////
    // Combinational factor + product for each of the 10 iterations
    //   F_i          = 2 - D_{i-1}
    //   product_D    = F_i * D_{i-1}   (48-bit)
    //   product_N    = F_i * N_{i-1}   (48-bit)
    // Next-stage value = product[26:9]  (back to 9.9 fixed point)
    //////////////////////////////////////////////
    always_comb begin
        F  = TWO - D;    D1  = F  * D;    N1  = F  * N;
        F1 = TWO - D2;   D3  = F1 * D2;   N3  = F1 * N2;
        F2 = TWO - D4;   D5  = F2 * D4;   N5  = F2 * N4;
        F3 = TWO - D6;   D7  = F3 * D6;   N7  = F3 * N6;
        F4 = TWO - D8;   D9  = F4 * D8;   N9  = F4 * N8;
        F5 = TWO - D10;  D11 = F5 * D10;  N11 = F5 * N10;
        F6 = TWO - D12;  D13 = F6 * D12;  N13 = F6 * N12;
        F7 = TWO - D14;  D15 = F7 * D14;  N15 = F7 * N14;
        F8 = TWO - D16;  D17 = F8 * D16;  N17 = F8 * N16;
        F9 = TWO - D18;  D19 = F9 * D18;  N19 = F9 * N18;
    end

    //////////////////////////////////////////////
    // Pipelined registers (synchronous active-low reset)
    //////////////////////////////////////////////
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            D_0 <= ZERO; N_0 <= ZERO;
            D   <= ZERO; N   <= ZERO;
            D2  <= ZERO; N2  <= ZERO;
            D4  <= ZERO; N4  <= ZERO;
            D6  <= ZERO; N6  <= ZERO;
            D8  <= ZERO; N8  <= ZERO;
            D10 <= ZERO; N10 <= ZERO;
            D12 <= ZERO; N12 <= ZERO;
            D14 <= ZERO; N14 <= ZERO;
            D16 <= ZERO; N16 <= ZERO;
            D18 <= ZERO; N18 <= ZERO;
            D20 <= ZERO; N20 <= ZERO;
            N21 <= ZERO;
            st1  <= 1'b0; st2  <= 1'b0; st3  <= 1'b0; st4  <= 1'b0;
            st5  <= 1'b0; st6  <= 1'b0; st7  <= 1'b0; st8  <= 1'b0;
            st9  <= 1'b0; st10 <= 1'b0; st11 <= 1'b0; st12 <= 1'b0;
            valid <= 1'b0;
        end else begin
            // Stage 1 : register raw inputs
            D_0 <= divisor;
            N_0 <= dividend;

            // Stage 2 : register prescaled values
            D <= ps_b;
            N <= ps_d;

            // Stages 3..12 : the 10 Gold-Schmidt iterations (register truncated products)
            D2  <= D1 [26:9];  N2  <= N1 [26:9];
            D4  <= D3 [26:9];  N4  <= N3 [26:9];
            D6  <= D5 [26:9];  N6  <= N5 [26:9];
            D8  <= D7 [26:9];  N8  <= N7 [26:9];
            D10 <= D9 [26:9];  N10 <= N9 [26:9];
            D12 <= D11[26:9];  N12 <= N11[26:9];
            D14 <= D13[26:9];  N14 <= N13[26:9];
            D16 <= D15[26:9];  N16 <= N15[26:9];
            D18 <= D17[26:9];  N18 <= N17[26:9];
            D20 <= D19[26:9];  N20 <= N19[26:9];

            // Stage 13 : register output; hold value until the next result is ready
            if (st12)
                N21 <= N20;

            // Valid pipeline : start is delayed 13 clocks to align with dv_out
            st1  <= start;
            st2  <= st1;
            st3  <= st2;
            st4  <= st3;
            st5  <= st4;
            st6  <= st5;
            st7  <= st6;
            st8  <= st7;
            st9  <= st8;
            st10 <= st9;
            st11 <= st10;
            st12 <= st11;
            valid <= st12;
        end
    end

    assign dv_out = N21;

endmodule

////////////////////////////////////////////////
// Pre-scaling (Prescaling) Module
//   Right-shift both operands (by the same amount) until the divisor `a`
//   has all-zero integer bits, i.e. its fixed-point value is < 1.0.
////////////////////////////////////////////////
module pre_scaler (
    input  logic [17:0] a,  // unsigned divisor
    input  logic [17:0] c,  // unsigned dividend
    output logic [17:0] b,  // prescaled divisor
    output logic [17:0] d   // prescaled dividend
);

    integer i;

    always_comb begin : SHIFT_LOGIC
        b = a;
        d = c;
        for (i = 0; i < 18; i = i + 1) begin
            if (b[17:9] != 9'b0) begin
                b = b >> 1;
                d = d >> 1;
            end
        end
    end

endmodule


////////////////////////////////////////////////
// Single-bit DFF
////////////////////////////////////////////////
module dff1 (
    input  logic clk,
    input  logic reset,
    input  logic d,
    output logic q
);
    always_ff @(posedge clk) begin
        if (reset) q <= 1'b0;
        else       q <= d;
    end
endmodule


////////////////////////////////////////////////
// 18-bit register (parallel load)
////////////////////////////////////////////////
module reg18 (
    input  logic        clk,
    input  logic        reset,
    input  logic [17:0] data_in,
    output logic [17:0] data_out
);
    always_ff @(posedge clk) begin
        if (reset) data_out <= 18'b0;
        else       data_out <= data_in;
    end
endmodule


