//////////////////////////////////////////////
// Top-Level Gold-Schmidt Division Module
// Latency-optimized: reduced by exactly 12 clock cycles (13 -> 1)
// using only 2 instances of module reg18 (the raw-input registers).
// The prescaling stage and all 10 Gold-Schmidt iterations are now
// purely combinational, preserving functional equivalence.
//////////////////////////////////////////////
module divider (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         start,
    input  logic [17:0]  dividend,  // unsigned
    input  logic [17:0]  divisor,   // unsigned
    output logic [17:0]  dv_out,
    output logic         valid
);

    //////////////////////////////////////////////
    // Local parameters
    //////////////////////////////////////////////
    localparam logic [17:0] TWO = 18'b000000010_000000000;  // "2.0" in Q9.9

    //////////////////////////////////////////////
    // Internal signals
    //////////////////////////////////////////////
    logic [17:0] D_0, N_0;
    logic [17:0] prescaled_divisor, prescaled_dividend;

    logic [17:0] D, D2, D4, D6, D8, D10, D12, D14, D16, D18, D20;
    logic [17:0] N, N2, N4, N6, N8, N10, N12, N14, N16, N18, N20, N21;
    logic [17:0] F, F1, F2, F3, F4, F5, F6, F7, F8, F9;
    logic [47:0] D1, N1, D3, N3, D5, N5, D7, N7, D9, N9,
                 D11, N11, D13, N13, D15, N15, D17, N17, D19, N19;

    //////////////////////////////////////////////
    // reg18 instance #1 and #2: register the raw
    // dividend/divisor. This single register layer is
    // the ONLY sequential element in the datapath, giving
    // a total latency of 1 clock cycle.
    //////////////////////////////////////////////
    reg18 reg_dividend_pre(
        .clk    (clk),
        .reset  (~rst_n),
        .data_in(dividend),
        .data_out(N_0)
    );

    reg18 reg_divisor_pre(
        .clk    (clk),
        .reset  (~rst_n),
        .data_in(divisor),
        .data_out(D_0)
    );

    //////////////////////////////////////////////
    // Prescaling: only for magnitude < 1 (combinational)
    //////////////////////////////////////////////
    pre_scaler prescaler_inst(
        .a(D_0),
        .c(N_0),
        .b(prescaled_divisor),
        .d(prescaled_dividend)
    );

    //////////////////////////////////////////////
    // Fully combinational Gold-Schmidt iteration chain.
    // Each iteration: F = 2 - D ; D_next = (F*D)[26:9] ;
    //                 N_next = (F*N)[26:9]. 10 iterations.
    //////////////////////////////////////////////
    always_comb begin
        // Prescaled operands
        D  = prescaled_divisor;
        N  = prescaled_dividend;

        // Iteration 1
        F  = TWO - D;
        D1 = F * D;    N1 = F * N;
        D2 = D1[26:9]; N2 = N1[26:9];

        // Iteration 2
        F1 = TWO - D2;
        D3 = F1 * D2;  N3 = F1 * N2;
        D4 = D3[26:9]; N4 = N3[26:9];

        // Iteration 3
        F2 = TWO - D4;
        D5 = F2 * D4;  N5 = F2 * N4;
        D6 = D5[26:9]; N6 = N5[26:9];

        // Iteration 4
        F3 = TWO - D6;
        D7 = F3 * D6;  N7 = F3 * N6;
        D8 = D7[26:9]; N8 = N7[26:9];

        // Iteration 5
        F4 = TWO - D8;
        D9 = F4 * D8;   N9 = F4 * N8;
        D10 = D9[26:9]; N10 = N9[26:9];

        // Iteration 6
        F5 = TWO - D10;
        D11 = F5 * D10;  N11 = F5 * N10;
        D12 = D11[26:9]; N12 = N11[26:9];

        // Iteration 7
        F6 = TWO - D12;
        D13 = F6 * D12;  N13 = F6 * N12;
        D14 = D13[26:9]; N14 = N13[26:9];

        // Iteration 8
        F7 = TWO - D14;
        D15 = F7 * D14;  N15 = F7 * N14;
        D16 = D15[26:9]; N16 = N15[26:9];

        // Iteration 9
        F8 = TWO - D16;
        D17 = F8 * D16;  N17 = F8 * N16;
        D18 = D17[26:9]; N18 = N17[26:9];

        // Iteration 10
        F9 = TWO - D18;
        D19 = F9 * D18;  N19 = F9 * N18;
        D20 = D19[26:9]; N20 = N19[26:9];

        // Final quotient
        N21 = N20;
    end

    // Combinational output (registered inputs -> settled quotient in 1 cycle)
    assign dv_out = N21;

    //////////////////////////////////////////////
    // Pipeline control: valid asserts exactly 1 cycle
    // after start (latency = 1).
    //////////////////////////////////////////////
    dff1 ff0(
        .clk   (clk),
        .reset (~rst_n),
        .d     (start),
        .q     (valid)
    );

endmodule

////////////////////////////////////////////////
// Pre-scaling (Prescaling) Module
////////////////////////////////////////////////
module pre_scaler (
    input  logic [17:0] a,  // unsigned divisor
    input  logic [17:0] c,  // unsigned dividend
    output logic [17:0] b,  // prescaled divisor
    output logic [17:0] d   // prescaled dividend
);
    always_comb begin : SHIFT_LOGIC
        if (a[17]) begin
            b = a >> 8;
            d = c >> 8;
        end
        else if (a[16]) begin
            b = a >> 7;
            d = c >> 7;
        end
        else if (a[15]) begin
            b = a >> 6;
            d = c >> 6;
        end
        else if (a[14]) begin
            b = a >> 5;
            d = c >> 5;
        end
        else if (a[13]) begin
            b = a >> 4;
            d = c >> 4;
        end
        else if (a[12]) begin
            b = a >> 3;
            d = c >> 3;
        end
        else if (a[11]) begin
            b = a >> 2;
            d = c >> 2;
        end
        else if (a[10]) begin
            b = a >> 1;
            d = c >> 1;
        end
        else begin
            b = a;
            d = c;
        end
    end
endmodule

////////////////////////////////////////////////
// Single-bit DFF
////////////////////////////////////////////////
module dff1 (
    input  logic clk,
    input  logic reset,
    input  logic d,
    output logic q
);
    always_ff @(posedge clk) begin
        if (reset)
            q <= 1'b0;
        else
            q <= d;
    end
endmodule

////////////////////////////////////////////////
// 18-bit register (parallel load)
////////////////////////////////////////////////
module reg18 (
    input  logic        clk,
    input  logic        reset,
    input  logic [17:0] data_in,
    output logic [17:0] data_out
);
    always_ff @(posedge clk) begin
        if (reset)
            data_out <= 18'd0;
        else
            data_out <= data_in;
    end
endmodule

`timescale 1ns/1ps
module divider #
(
    parameter WIDTH = 32
)
(
    input  wire                  clk,
    input  wire                  rst_n,      // Active-low asynchronous reset
    input  wire                  start,      // Start signal for new operation
    input  wire [WIDTH-1 : 0]    dividend,   // Dividend (numerator)
    input  wire [WIDTH-1 : 0]    divisor,    // Divisor (denominator)
    output wire [WIDTH-1 : 0]    quotient,   // Result of the division
    output wire [WIDTH-1 : 0]    remainder,  // Remainder after division
    output wire                  valid       // Indicates output is valid
);

    // one extra bit for A
    localparam AW = WIDTH + 1;
    // Simple 3-state FSM
    localparam IDLE = 2'b00;
    localparam BUSY = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] state_reg, state_next;

    // A+Q combined into one WIDTH + 1 + WIDTH register:
    reg [AW+WIDTH-1 : 0] aq_reg,   aq_next;

    // Divisor register.
    // AREA OPT: the original m_reg was AW = WIDTH+1 bits wide but its MSB was
    // always 0 ({1'b0, divisor}); store only the WIDTH-bit divisor and re-create
    // the zero MSB where the AW-wide add/sub needs it. Removes one flop + its
    // next-state logic with identical arithmetic.
    reg [WIDTH-1 : 0]    m_reg,    m_next;

    // Iterate exactly WIDTH times (counter width kept identical to the original
    // so the iteration count / latency is byte-for-byte the same).
    reg [$clog2(WIDTH)-1:0] n_reg, n_next;

    reg valid_reg, valid_next;

    // AREA OPT: the original kept two dedicated WIDTH-bit output register banks
    // (quotient_reg / remainder_reg) that merely re-latch slices of aq. The
    // corrected result already resides in aq at the exact cycle valid asserts,
    // and aq holds that value through the post-completion IDLE, so the outputs
    // can be driven straight from aq_reg. This removes 2*WIDTH flip-flops (and
    // their next-state muxes) with no change to latency or the valid-qualified
    // result. quotient = Q (lower WIDTH bits), remainder = low WIDTH bits of A.
    assign quotient  = aq_reg[WIDTH-1 : 0];
    assign remainder = aq_reg[2*WIDTH-1 : WIDTH];
    assign valid     = valid_reg;

    //------------------------------------------------
    // SEQUENTIAL: State & register updates
    //------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_reg     <= IDLE;
            aq_reg        <= 0;
            m_reg         <= 0;
            n_reg         <= 0;
            valid_reg     <= 0;
        end
        else begin
            state_reg     <= state_next;
            aq_reg        <= aq_next;
            m_reg         <= m_next;
            n_reg         <= n_next;
            valid_reg     <= valid_next;
        end
    end

    //------------------------------------------------
    // COMBINATIONAL: Next-state logic
    //------------------------------------------------
    always @* begin
        // Default "hold" behavior
        state_next     = state_reg;
        aq_next        = aq_reg;
        m_next         = m_reg;
        n_next         = n_reg;
        valid_next     = valid_reg;

        case (state_reg)
        //---------------------------------------------
        // IDLE: Wait for start
        //---------------------------------------------
        IDLE: begin
            // Outputs not valid yet
            valid_next = 1'b0;

            if (start) begin
                // Step-1: Initialize
                // A = 0 => upper AW bits all zero
                // Q = dividend => lower WIDTH bits of aq
                aq_next = { {AW{1'b0}}, dividend };
                // divisor stored directly (zero MSB implied)
                m_next   = divisor;
                n_next   = WIDTH;
                // Move to BUSY
                state_next = BUSY;
            end
        end

        //---------------------------------------------
        // BUSY: Perform the N iterations
        //---------------------------------------------
        BUSY: begin
            // 1) SHIFT LEFT
            aq_next = aq_reg << 1;

            // 2) If sign bit of old A == 1 => add M; else => subtract M.
            if (aq_reg[AW+WIDTH-1] == 1'b1) begin
                aq_next[AW+WIDTH-1 : WIDTH] = aq_next[AW+WIDTH-1 : WIDTH] + {1'b0, m_reg};
            end
            else begin
                aq_next[AW+WIDTH-1 : WIDTH] = aq_next[AW+WIDTH-1 : WIDTH] - {1'b0, m_reg};
            end

            // 3) Check the new sign bit of A (after the add/sub).
            //    If sign(A) = 1 => Q[0] = 0; else => Q[0] = 1.
            if (aq_next[AW+WIDTH-1] == 1'b1) begin
                aq_next[0] = 1'b0;
            end
            else begin
                aq_next[0] = 1'b1;
            end

            // Decrement iteration count
            n_next = n_reg - 1;

            // Step-7: if n != 0 => repeat, else => next step
            if (n_next == 0) begin
                state_next = DONE;
            end
        end

        //---------------------------------------------
        // DONE: Final correction + output
        //---------------------------------------------
        DONE: begin
            // Step-8: If sign bit of A == 1 => A = A + M
            if (aq_reg[AW+WIDTH-1] == 1'b1) begin
                aq_next = aq_reg;  // default
                aq_next[AW+WIDTH-1 : WIDTH] = aq_reg[AW+WIDTH-1 : WIDTH] + {1'b0, m_reg};
            end

            // Step-9: result (Q and remainder) now settled in aq and driven to
            // the top-level outputs combinationally.

            // Output becomes valid
            valid_next = 1'b1;

            // Return to IDLE when 'start' goes low
            if (!start) begin
                state_next = IDLE;
            end else begin
                state_next = DONE;
            end
        end

        default: begin
            state_next = IDLE;
        end
        endcase
    end

endmodule

module gcd_controlpath #(
    parameter WIDTH = 4
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       go,
    input  wire       equal,
    input  wire       greater_than,
    output reg  [1:0] controlpath_state,
    output reg        done
);

    localparam [1:0] S0 = 2'b00, // IDLE
                     S1 = 2'b01, // DONE
                     S2 = 2'b10, // A > B
                     S3 = 2'b11; // B > A

    reg [1:0] next_state;

    // Combinational next-state logic
    always @(*) begin
        next_state = controlpath_state;
        case (controlpath_state)
            S0: begin
                if (go) begin
                    if (equal)             next_state = S1;
                    else if (greater_than) next_state = S2;
                    else                   next_state = S3;
                end else begin
                    next_state = S0;
                end
            end
            S2: begin
                if (equal)             next_state = S1;
                else if (greater_than) next_state = S2;
                else                   next_state = S3;
            end
            S3: begin
                if (equal)             next_state = S1;
                else if (greater_than) next_state = S2;
                else                   next_state = S3;
            end
            S1:      next_state = S0;
            default: next_state = S0;
        endcase
    end

    // Registered outputs (synchronous active-high reset)
    always @(posedge clk) begin
        if (rst) begin
            controlpath_state <= S0;
            done              <= 1'b0;
        end else begin
            controlpath_state <= next_state;
            // done is asserted for exactly one clock cycle, during the S1 state
            done              <= (next_state == S1);
        end
    end

endmodule


module gcd_datapath #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire [WIDTH-1:0] A,
    input  wire [WIDTH-1:0] B,
    input  wire [1:0]       controlpath_state,
    output reg  [WIDTH-1:0] OUT,
    output wire             equal,
    output wire             greater_than
);

    localparam [1:0] S0 = 2'b00,
                     S1 = 2'b01,
                     S2 = 2'b10,
                     S3 = 2'b11;

    reg [WIDTH-1:0] A_ff, B_ff;

    // Comparison uses the primary inputs in S0, and the working registers otherwise
    assign equal        = (controlpath_state == S0) ? (A == B) : (A_ff == B_ff);
    assign greater_than = (controlpath_state == S0) ? (A >  B) : (A_ff >  B_ff);

    always @(posedge clk) begin
        if (rst) begin
            A_ff <= {WIDTH{1'b0}};
            B_ff <= {WIDTH{1'b0}};
            OUT  <= {WIDTH{1'b0}};
        end else begin
            case (controlpath_state)
                S0: begin
                    // Latch the new inputs for a fresh computation
                    A_ff <= A;
                    B_ff <= B;
                    // A == B at the start : GCD is A itself
                    if (equal) OUT <= A;
                end
                S2: begin
                    // A_ff > B_ff : subtract B_ff from A_ff (guarded so the
                    // final equal-cycle does not corrupt the result)
                    if (A_ff > B_ff) A_ff <= A_ff - B_ff;
                    if (equal)       OUT  <= A_ff;
                end
                S3: begin
                    // B_ff > A_ff : subtract A_ff from B_ff
                    if (B_ff > A_ff) B_ff <= B_ff - A_ff;
                    if (equal)       OUT  <= A_ff;
                end
                default: ;
            endcase
        end
    end

endmodule


module gcd_top #(
    parameter WIDTH = 4
) (
    input  wire             clk,
    input  wire             rst,
    input  wire [WIDTH-1:0] A,
    input  wire [WIDTH-1:0] B,
    input  wire             go,
    output wire [WIDTH-1:0] OUT,
    output wire             done
);

    wire [1:0] controlpath_state;
    wire       equal;
    wire       greater_than;

    gcd_controlpath #(.WIDTH(WIDTH)) u_controlpath (
        .clk               (clk),
        .rst               (rst),
        .go                (go),
        .equal             (equal),
        .greater_than      (greater_than),
        .controlpath_state (controlpath_state),
        .done              (done)
    );

    gcd_datapath #(.WIDTH(WIDTH)) u_datapath (
        .clk               (clk),
        .rst               (rst),
        .A                 (A),
        .B                 (B),
        .controlpath_state (controlpath_state),
        .OUT               (OUT),
        .equal             (equal),
        .greater_than      (greater_than)
    );

endmodule


