// Three-input GCD top module built from three gcd_top instances.
// Computes gcd(A,B,C) = gcd( gcd(A,B), gcd(B,C) ).
module gcd_3_ip #(
   parameter WIDTH = 4                  // Bit-width of the inputs and output
   )(
   input                     clk,       // Clock signal
   input                     rst,       // Active High Synchronous reset signal
   input  [WIDTH-1:0]        A,         // Input operand A
   input  [WIDTH-1:0]        B,         // Input operand B
   input  [WIDTH-1:0]        C,         // Input operand C (third input)
   input                     go,        // Start signal to begin GCD computation
   output logic  [WIDTH-1:0] OUT,       // Output for the 3-input GCD result
   output logic              done       // Signal to indicate completion of computation
);

   // Intermediate GCD results and their completion strobes
   logic [WIDTH-1:0] out_ab;
   logic [WIDTH-1:0] out_bc;
   logic             done_ab;
   logic             done_bc;

   // Latched intermediate results and control state
   logic [WIDTH-1:0] reg_ab;
   logic [WIDTH-1:0] reg_bc;
   logic             done_ab_seen;
   logic             done_bc_seen;
   logic             go3;          // Latched start for the final GCD stage
   logic             started3;     // Ensures the final stage is launched only once
   logic             go_d;         // Delayed 'go' for rising-edge (re-arm) detection

   // First intermediate GCD: gcd(A, B)
   gcd_top #(
      .WIDTH(WIDTH)
   ) gcd_ab (
      .clk  (clk),
      .rst  (rst),
      .A    (A),
      .B    (B),
      .go   (go),
      .OUT  (out_ab),
      .done (done_ab)
   );

   // Second intermediate GCD: gcd(B, C)
   gcd_top #(
      .WIDTH(WIDTH)
   ) gcd_bc (
      .clk  (clk),
      .rst  (rst),
      .A    (B),
      .B    (C),
      .go   (go),
      .OUT  (out_bc),
      .done (done_bc)
   );

   // Final GCD stage: gcd( gcd(A,B), gcd(B,C) ).
   // Started (via latched go3) only after BOTH intermediate results are ready.
   gcd_top #(
      .WIDTH(WIDTH)
   ) gcd_final (
      .clk  (clk),
      .rst  (rst),
      .A    (reg_ab),
      .B    (reg_bc),
      .go   (go3),
      .OUT  (OUT),
      .done (done)
   );

   // Control/latching logic for the final stage.
   always_ff @(posedge clk) begin
      if (rst) begin
         go_d         <= 1'b0;
         done_ab_seen <= 1'b0;
         done_bc_seen <= 1'b0;
         reg_ab       <= {WIDTH{1'b0}};
         reg_bc       <= {WIDTH{1'b0}};
         go3          <= 1'b0;
         started3     <= 1'b0;
      end else begin
         go_d <= go;
         go3  <= 1'b0;   // default: single-cycle launch pulse

         if (go && !go_d) begin
            // A fresh computation has been requested: re-arm the control logic.
            done_ab_seen <= 1'b0;
            done_bc_seen <= 1'b0;
            started3     <= 1'b0;
         end else begin
            // Capture each intermediate result the cycle its 'done' asserts.
            if (done_ab && !started3) begin
               done_ab_seen <= 1'b1;
               reg_ab       <= out_ab;
            end
            if (done_bc && !started3) begin
               done_bc_seen <= 1'b1;
               reg_bc       <= out_bc;
            end
            // When both intermediate GCDs are ready, launch the final stage
            // exactly once (one latch cycle after both are ready).
            if (!started3 &&
                (done_ab || done_ab_seen) &&
                (done_bc || done_bc_seen)) begin
               go3      <= 1'b1;
               started3 <= 1'b1;
            end
         end
      end
   end

endmodule

// LCM of three WIDTH-bit inputs, built on the existing 3-input GCD module.
//
//   LCM(A, B, C) = (A * B * C) / GCD(A * B, B * C, C * A)
//
// Latency = GCD computation latency + 2 clock cycles:
//   +1 cycle : capture the three pairwise products (and the triple product)
//              and launch the GCD (Stage 1).
//    L cycles: GCD computation of GCD(A*B, B*C, C*A).
//   +1 cycle : divide the triple product by the GCD result and register
//              OUT / done (Stage 2).
module lcm_3_ip #(
   parameter WIDTH = 4                    // Input bit-width
   )(
   input                         clk,     // Clock signal (positive-edge synchronized)
   input                         rst,     // Active high Synchronous reset signal
   input  [WIDTH-1:0]            A,       // WIDTH bit input
   input  [WIDTH-1:0]            B,       // WIDTH bit input
   input  [WIDTH-1:0]            C,       // WIDTH bit input
   input                         go,      // Active high Start signal for LCM computation
   output logic  [3 * WIDTH-1:0] OUT,     // Computed LCM. 3*WIDTH bits wide
   output logic                  done     // Signal indicating that the computation is complete
);

   // Stage-1 registers.
   // Pairwise products are up to 2*WIDTH bits; the triple product up to 3*WIDTH bits,
   // so no overflow can occur.
   logic [2*WIDTH-1:0] prod_ab;   // A * B
   logic [2*WIDTH-1:0] prod_bc;   // B * C
   logic [2*WIDTH-1:0] prod_ca;   // C * A
   logic [3*WIDTH-1:0] prod_abc;  // A * B * C
   logic               go_gcd;    // go delayed by 1 cycle, aligned with the captured products

   // GCD-of-products results.
   logic [2*WIDTH-1:0] gcd_out;   // GCD(A*B, B*C, C*A)
   logic               gcd_done;  // GCD completion strobe

   // Stage 1 : capture the products one cycle after go and start the GCD.
   // Capture is gated on go so prod_abc is HELD stable across the whole GCD
   // computation until it is consumed by the divide in Stage 2.
   always_ff @(posedge clk) begin
      if (rst) begin
         prod_ab  <= '0;
         prod_bc  <= '0;
         prod_ca  <= '0;
         prod_abc <= '0;
         go_gcd   <= 1'b0;
      end else begin
         go_gcd <= go;
         if (go) begin
            prod_ab  <= A * B;
            prod_bc  <= B * C;
            prod_ca  <= C * A;
            prod_abc <= A * B * C;
         end
      end
   end

   // Reuse the existing 3-input GCD, widened to hold the pairwise products,
   // to compute GCD(A*B, B*C, C*A). Clock/reset behavior is unchanged.
   gcd_3_ip #(
      .WIDTH (2 * WIDTH)
   ) gcd_products_inst (
      .clk  (clk),
      .rst  (rst),
      .A    (prod_ab),
      .B    (prod_bc),
      .C    (prod_ca),
      .go   (go_gcd),
      .OUT  (gcd_out),
      .done (gcd_done)
   );

   // Stage 2 : LCM = (A*B*C) / GCD(A*B, B*C, C*A).
   // OUT is updated only together with done (which pulses high for 1 cycle);
   // otherwise OUT holds its previous value. Inputs are guaranteed non-zero,
   // so gcd_out >= 1 and the divide never divides by zero.
   always_ff @(posedge clk) begin
      if (rst) begin
         OUT  <= '0;
         done <= 1'b0;
      end else begin
         done <= gcd_done;
         if (gcd_done) begin
            OUT <= prod_abc / gcd_out;
         end
      end
   end

endmodule


module gcd_3_ip #(
   parameter WIDTH = 4
   )(
   input                     clk,
   input                     rst,
