// Datapath module for GCD computation using Stein's (binary GCD) algorithm
module gcd_datapath  #(
   parameter WIDTH = 4                           // Bit-width of operands
   )(
   input                     clk,                // Clock signal
   input                     rst,                // Active High Synchronous reset
   input  [WIDTH-1:0]        A,                  // Input operand A
   input  [WIDTH-1:0]        B,                  // Input operand B
   input  [1:0]              controlpath_state,  // Current state from control path
   output logic              equal,              // Signal indicating A_ff == B_ff
   output logic  [WIDTH-1:0] OUT                 // Output GCD result
);

   // Registers to hold intermediate values of A and B
   logic [WIDTH-1:0] A_ff;
   logic [WIDTH-1:0] B_ff;

   // Register tracking how many common factors of two have been removed (Step 1)
   logic [WIDTH:0]   k_ff;

   // State encoding for control signals
   localparam S0 = 2'd0;    // State 0: Initialization / latch inputs
   localparam S1 = 2'd1;    // State 1: Computation complete / finalize output
   localparam S2 = 2'd2;    // State 2: Iterative Stein's step (one step per cycle)

   // Sequential logic to update registers based on controlpath_state
   always_ff @ (posedge clk) begin
      if (rst) begin
         // On reset, initialize registers to zero
         A_ff <= '0;
         B_ff <= '0;
         OUT  <= '0;
         k_ff <= '0;
      end else begin
         case (controlpath_state)
            S0: begin
                // In state S0, load input values into registers and clear the
                // factored-out-twos counter for a fresh computation.
                A_ff <= A;
                B_ff <= B;
                k_ff <= '0;
             end
            S1: begin
                // In state S1, computation is done. The final GCD is
                // 2^k * (common odd value), realized with a left shift.
                OUT  <= A_ff << k_ff;
             end
            S2: begin
                // In state S2, execute exactly one step of Stein's algorithm.
                if (A_ff == B_ff) begin
                   // Equal: iteration complete, hold values (FSM moves to final).
                end else if (A_ff == '0) begin
                   // One operand is zero: make it equal to the other.
                   A_ff <= B_ff;
                end else if (B_ff == '0) begin
                   B_ff <= A_ff;
                end else if (!A_ff[0] && !B_ff[0]) begin
                   // Step 1: both even -> remove a common factor of two.
                   A_ff <= A_ff >> 1;
                   B_ff <= B_ff >> 1;
                   k_ff <= k_ff + 1'b1;
                end else if (!A_ff[0] && B_ff[0]) begin
                   // Step 2: A even, B odd -> halve A.
                   A_ff <= A_ff >> 1;
                end else if (A_ff[0] && !B_ff[0]) begin
                   // Step 2: A odd, B even -> halve B.
                   B_ff <= B_ff >> 1;
                end else begin
                   // Step 3: both odd -> replace the larger with |a-b|/2.
                   if (A_ff > B_ff)
                      A_ff <= (A_ff - B_ff) >> 1;
                   else
                      B_ff <= (B_ff - A_ff) >> 1;
                end
             end
            default: begin
                // Unused state: hold current values.
            end
         endcase
      end
   end

   // Equality flag for the control path FSM (compares the register values).
   always_comb begin
      equal = (A_ff == B_ff) ? 1'b1 : 1'b0;
   end
endmodule

// Control path module for GCD computation FSM (Stein's algorithm)
module gcd_controlpath (
   input                    clk,               // Clock signal
   input                    rst,               // Active High Synchronous reset
   input                    go,                // Start GCD calculation signal
   input                    equal,             // From Datapath: A_ff equals B_ff
   output logic [1:0]       controlpath_state, // Current state to Datapath
   output logic             done               // Indicates completion of GCD calculation
);

   // Internal state registers
   logic [1:0] curr_state;  // Current state of FSM
   logic [1:0] next_state;  // Next state of FSM

   // State encoding
   localparam S0 = 2'd0;    // State 0: Initialization / waiting for 'go'
   localparam S1 = 2'd1;    // State 1: Computation complete / finalize
   localparam S2 = 2'd2;    // State 2: Iterative Stein's step

   // State latching logic: Update current state on clock edge
   always_ff @ (posedge clk) begin
      if (rst) begin
         curr_state   <= S0;   // On reset, set state to S0
      end else begin
         curr_state   <= next_state;   // Transition to next state
      end
   end

   // State transition logic
   always_comb begin
      case(curr_state)
         S0: begin
             // State S0: latch inputs; on 'go' proceed to the iterative stage.
             if(!go)
                next_state = S0;         // Remain in S0 until 'go' is asserted
             else
                next_state = S2;         // Begin Stein's iteration
         end
         S2: begin
             // State S2: iterate one Stein step per cycle; exit only when equal.
             if(equal)
                next_state = S1;         // A_ff == B_ff -> finalize
             else
                next_state = S2;         // Continue iterating
         end
         S1: begin
             // State S1: computation complete, output the result.
             next_state = S0;           // Return to S0 after completion
         end
         default: begin
             next_state = S0;
         end
      endcase
   end

   // Output logic: Generate 'done' signal when computation is complete
   always_ff @ (posedge clk) begin
     if(rst) begin
        done <= 1'b0;             // On reset, 'done' is low
     end else begin
        done <= (curr_state == S1); // 'done' is asserted when in state S1
     end
   end

   // Assign current state to output for datapath
   assign controlpath_state = curr_state;

endmodule

module gcd_top #(
   parameter WIDTH = 4              // Parameter to define the bit-width of the input and output data
   )(
   input                     clk,   // Clock signal
   input                     rst,   // Active High Synchronous reset signal
   input  [WIDTH-1:0]        A,     // Input operand A
   input  [WIDTH-1:0]        B,     // Input operand B
   input                     go,    // Start signal to begin GCD computation
   output logic  [WIDTH-1:0] OUT,   // Output for the GCD result
   output logic              done   // Signal to indicate completion of computation
);

   // Single combined FSM (control + datapath merged, submodules removed)

   // State encoding
   localparam S0 = 2'd0;   // State 0: Initialization / waiting for 'go'
   localparam S1 = 2'd1;   // State 1: Computation complete
   localparam S2 = 2'd2;   // State 2: A_ff > B_ff, subtract B_ff from A_ff
   localparam S3 = 2'd3;   // State 3: B_ff > A_ff, subtract A_ff from B_ff

   logic [1:0]        curr_state;   // Current FSM state
   logic [1:0]        next_state;   // Next FSM state
   logic [WIDTH-1:0]  A_ff;         // Register holding intermediate A
   logic [WIDTH-1:0]  B_ff;         // Register holding intermediate B
   logic              equal;        // A/A_ff == B/B_ff
   logic              greater_than; // A/A_ff >  B/B_ff

   // Comparison signals: in S0 compare primary inputs, otherwise the registers
   always_comb begin
      case (curr_state)
         S0: begin
            equal        = (A == B) ? 1'b1 : 1'b0;
            greater_than = (A >  B) ? 1'b1 : 1'b0;
         end
         default: begin
            equal        = (A_ff == B_ff) ? 1'b1 : 1'b0;
            greater_than = (A_ff >  B_ff) ? 1'b1 : 1'b0;
         end
      endcase
   end

   // Next-state logic
   always_comb begin
      case (curr_state)
         S0: begin
            if (!go)
               next_state = S0;
            else if (equal)
               next_state = S1;
            else if (greater_than)
               next_state = S2;
            else
               next_state = S3;
         end
         S1: begin
            next_state = S0;
         end
         S2: begin
            if (equal)
               next_state = S1;
            else if (greater_than)
               next_state = S2;
            else
               next_state = S3;
         end
         S3: begin
            if (equal)
               next_state = S1;
            else if (greater_than)
               next_state = S2;
            else
               next_state = S3;
         end
         default: begin
            next_state = S0;
         end
      endcase
   end

   // Sequential logic: state register, datapath registers, and done output
   always_ff @ (posedge clk) begin
      if (rst) begin
         curr_state <= S0;
         A_ff       <= 'b0;
         B_ff       <= 'b0;
         OUT        <= 'b0;
         done       <= 1'b0;
      end else begin
         curr_state <= next_state;
         done       <= (curr_state == S1);
         case (curr_state)
            S0: begin
               // Load input operands
               A_ff <= A;
               B_ff <= B;
            end
            S1: begin
               // Output the result
               OUT <= A_ff;
            end
            S2: begin
               // A_ff > B_ff: subtract B_ff from A_ff
               if (greater_than)
                  A_ff <= A_ff - B_ff;
            end
            S3: begin
               // B_ff > A_ff: subtract A_ff from B_ff
               if (!equal & !greater_than)
                  B_ff <= B_ff - A_ff;
            end
            default: begin
               A_ff <= 'b0;
               B_ff <= 'b0;
               OUT  <= 'b0;
            end
         endcase
      end
   end

endmodule

module lcm_3_ip #(
   parameter WIDTH = 4                    // Input bit-width
   )(
   input                         clk,
   input                         rst,
   input  [WIDTH-1:0]            A,
   input  [WIDTH-1:0]            B,
   input  [WIDTH-1:0]            C,
   input                         go,
   output logic  [3 * WIDTH-1:0] OUT,   // Updated output width
   output logic                  done
);

   logic [2*WIDTH-1:0]      gcd_result;     // GCD result
   logic [3*WIDTH-1:0]      product;        // Intermediate product
   logic                    gcd_done;
   logic                    product_ready;
   logic [2*WIDTH-1:0]      A_int;
   logic [2*WIDTH-1:0]      B_int;
   logic [2*WIDTH-1:0]      C_int;

   always_comb begin
      A_int = A*B;
      B_int = B*C;
      C_int = C*A;
   end

   // Calculate GCD of A, B, and C
   gcd_3_ip #(
      .WIDTH(2*WIDTH)
   ) gcd_inst (
      .clk   (clk),
      .rst   (rst),
      .A     (A_int),
      .B     (B_int),
      .C     (C_int),
      .go    (go),
      .OUT   (gcd_result),
      .done  (gcd_done)
   );

   // Sequential logic for LCM computation
   always_ff @(posedge clk) begin
      if (rst) begin
         OUT <= 0;
         done <= 0;
         product_ready <= 0;
      end else begin
         if (gcd_done) begin
            // Compute |A * B * C|
            product <= A * B * C;
            product_ready <= 1;
         end

         if (product_ready) begin
            // Compute LCM = |A * B * C| / GCD
            OUT <= product / {{WIDTH{1'b0}}, gcd_result};
            done <= 1;
            product_ready <= 0;
         end else begin
            done <= 0;
         end
      end
   end
endmodule

module gcd_3_ip #(
   parameter WIDTH = 4
