always_ff @ (posedge clk) begin
   if (rst) begin
      done_ab_latched    <= 0;
      done_bc_latched    <= 0;
   end else begin
      if(done_ab) begin
         done_ab_latched <= done_ab;
      end else if (go_abc) begin
         done_ab_latched <= 0;
      end

      if(done_bc) begin
         done_bc_latched <= done_bc;
      end else if (go_abc) begin
         done_bc_latched <= 0;
      end
   end
end

assign go_abc = done_ab_latched & done_bc_latched;

endmodule

module gcd_top #(
   parameter WIDTH = 4              // Parameter to define the bit-width of the input and output data
   )(
   input                     clk,   // Clock signal
   input                     rst,   // Active High Synchronous reset signal
   input  [WIDTH-1:0]        A,     // Input operand A
   input  [WIDTH-1:0]        B,     // Input operand B
   input                     go,    // Start signal to begin GCD computation
   output logic  [WIDTH-1:0] OUT,   // Output for the GCD result
   output logic              done   // Signal to indicate completion of computation
);

   // Internal signals to communicate between control path and data path
   logic equal;                     // Signal indicating A == B
   logic greater_than;              // Signal indicating A > B
   logic [1:0] controlpath_state;   // Current state of the control FSM

   // Instantiate the control path module
   gcd_controlpath gcd_controlpath_inst (
      .clk               (clk),               // Connect clock signal
      .rst               (rst),               // Connect reset signal
      .go                (go),                // Connect go signal
      .equal             (equal),             // Connect equal signal from datapath
      .greater_than      (greater_than),      // Connect greater_than signal from datapath
      .controlpath_state (controlpath_state), // Output current state to datapath
      .done              (done)               // Output done signal
   );

   // Instantiate the data path module
   gcd_datapath
   #( .WIDTH(WIDTH)
   ) gcd_datapath_inst (
      .clk               (clk),               // Connect clock signal
      .rst               (rst),               // Connect reset signal
      .A                 (A),                 // Connect input A
      .B                 (B),                 // Connect input B
      .controlpath_state (controlpath_state), // Connect current state from control path
      .equal             (equal),             // Output equal signal to control path
      .greater_than      (greater_than),      // Output greater_than signal to control path
      .OUT               (OUT)                // Output GCD result
   );
endmodule


// Datapath module for GCD computation
module gcd_datapath  #(
   parameter WIDTH = 4                           // Bit-width of operands
   )(
   input                     clk,                // Clock signal
   input                     rst,                // Active High Synchronous reset
   input  [WIDTH-1:0]        A,                  // Input operand A
   input  [WIDTH-1:0]        B,                  // Input operand B
   input  [1:0]              controlpath_state,  // Current state from control path
   output logic              equal,              // Signal indicating A_ff == B_ff
   output logic              greater_than,       // Signal indicating A_ff > B_ff
   output logic  [WIDTH-1:0] OUT                 // Output GCD result
);

   // Registers to hold intermediate values of A and B
   logic [WIDTH-1:0] A_ff;
   logic [WIDTH-1:0] B_ff;

   // State encoding for control signals
   localparam S0 = 2'd0;    // State 0: Initialization state
   localparam S1 = 2'd1;    // State 1: Computation complete
   localparam S2 = 2'd2;    // State 2: A_ff > B_ff, subtract B_ff from A_ff
   localparam S3 = 2'd3;    // State 3: B_ff > A_ff, subtract A_ff from B_ff

   // Sequential logic to update registers based on controlpath_state
   always_ff @ (posedge clk) begin
      if (rst) begin
         // On reset, initialize registers to zero
         A_ff <= 'b0;
         B_ff <= 'b0;
         OUT  <= 'b0;
      end else begin
         case (controlpath_state)
            S0: begin
                // In state S0, load input values into registers
                A_ff <= A;
                B_ff <= B;
             end
            S1: begin
                // In state S1, computation is done, output the result
                OUT  <= A_ff;
             end
            S2: begin
                // In state S2, A_ff > B_ff, subtract B_ff from A_ff
                if (greater_than)
                   A_ff <= A_ff - B_ff;
             end
            S3: begin
                // In state S3, B_ff > A_ff, subtract A_ff from B_ff
                if (!equal & !greater_than)
                   B_ff <= B_ff - A_ff;
             end
            default: begin
                A_ff <= 'b0;
                B_ff <= 'b0;
                OUT <= 'b0;
            end
         endcase
      end
   end

   // Generating control response signals for the control path FSM
   always_comb begin
      case(controlpath_state)
         S0: begin
            // In state S0, compare initial input values A and B
            equal        = (A == B)? 1'b1 : 1'b0;
            greater_than = (A >  B)? 1'b1 : 1'b0;
          end
          default: begin
            // In other states, compare the current values in registers A_ff and B_ff
            equal        = (A_ff == B_ff)? 1'b1 : 1'b0;
            greater_than = (A_ff >  B_ff)? 1'b1 : 1'b0;
          end
      endcase
   end
endmodule

// Control path module for GCD computation FSM
module gcd_controlpath (
   input                    clk,               // Clock signal
   input                    rst,               // Active High Synchronous reset
   input                    go,                // Start GCD calculation signal
   input                    equal,             // From Datapath: A_ff equals B_ff
   input                    greater_than,      // From Datapath: A_ff is greater than B_ff
   output logic [1:0]       controlpath_state, // Current state to Datapath
   output logic             done               // Indicates completion of GCD calculation
);

   // Internal state registers
   logic [1:0] curr_state;  // Current state of FSM
   logic [1:0] next_state;  // Next state of FSM

   // State encoding
   localparam S0 = 2'd0;    // State 0: Initialization or waiting for 'go' signal
   localparam S1 = 2'd1;    // State 1: Computation complete
   localparam S2 = 2'd2;    // State 2: A_ff > B_ff
   localparam S3 = 2'd3;    // State 3: B_ff > A_ff

   // State latching logic: Update current state on clock edge
   always_ff @ (posedge clk) begin
      if (rst) begin
         curr_state   <= S0;   // On reset, set state to S0
      end else begin
         curr_state   <= next_state;   // Transition to next state
      end
   end

   // State transition logic: Determine next state based on current state and inputs
   always_comb begin
      case(curr_state)
         S0: begin
             // State S0: Waiting for 'go' signal
             if(!go)
                next_state = S0;         // Remain in S0 until 'go' is asserted
             else if (equal)
                next_state = S1;         // If A == B, computation is complete
             else if (greater_than)
                next_state = S2;         // If A > B, go to state S2
             else
                next_state = S3;         // If B > A, go to state S3
         end
         S1: begin
             // State S1: Computation complete, output the result
             next_state = S0;           // Return to S0 after completion
         end
         S2: begin
             // State S2: A_ff > B_ff, subtract B_ff from A_ff
             if(equal)
                next_state = S1;         // If A_ff == B_ff after subtraction, go to S1
             else if (greater_than)
                next_state = S2;         // If A_ff > B_ff, stay in S2
             else
                next_state = S3;         // If B_ff > A_ff, go to S3
         end
         S3: begin
             // State S3: B_ff > A_ff, subtract A_ff from B_ff
             if (equal)
                next_state = S1;         // If A_ff == B_ff after subtraction, go to S1
             else if (greater_than)
                next_state = S2;         // If A_ff > B_ff, go to S2
             else
                next_state = S3;         // If B_ff > A_ff, stay in S3
         end
         default: begin
             next_state = S0;
         end
      endcase
   end

   // Output logic: Generate 'done' signal when computation is complete
   always_ff @ (posedge clk) begin
     if(rst) begin
        done <= 1'b0;             // On reset, 'done' is low
     end else begin
        done <= (curr_state == S1); // 'done' is asserted when in state S1
     end
   end

   // Assign current state to output for datapath
   assign controlpath_state = curr_state;

endmodule

module gcd_top #(
   parameter WIDTH = 4
)(
   input                     clk,
   input                     rst,
   input  [WIDTH-1:0]        A,
   input  [WIDTH-1:0]        B,
   input                     go,
   output logic [WIDTH-1:0]  OUT,
   output logic              done
);

   // State encoding (merged control + datapath FSM)
   localparam S0 = 2'd0; // Idle/Load
   localparam S1 = 2'd1; // Done/finalize
   localparam S2 = 2'd2; // Processing (Stein steps)

   logic [1:0]               state, next_state;
   logic [WIDTH-1:0]         A_ff, B_ff;
   logic [$clog2(WIDTH+1):0] k_ff;

   logic [WIDTH-1:0]         next_A_ff, next_B_ff, next_OUT;
   logic [$clog2(WIDTH+1):0] next_k_ff;

   logic                     equal, a_even, b_even, both_even;
   logic [WIDTH-1:0]         diff, gcd_base;

   always_comb begin
      // Intermediate flags
      a_even    = (A_ff[0] == 1'b0);
      b_even    = (B_ff[0] == 1'b0);
      both_even = a_even && b_even;
      equal     = (A_ff == B_ff);
      diff      = '0;
      // Pre-muxed shift source: shares a single barrel shifter for finalize.
      // both-zero -> B_ff(=0)<<k = 0 ; A_ff==0 -> B_ff<<k ; else A_ff<<k
      gcd_base  = (A_ff == 0) ? B_ff : A_ff;

      // Defaults: hold current register values
      next_A_ff  = A_ff;
      next_B_ff  = B_ff;
      next_k_ff  = k_ff;
      next_OUT   = OUT;
      next_state = state;

      case (state)
         S0: begin
            // Load inputs
            next_A_ff  = A;
            next_B_ff  = B;
            next_k_ff  = '0;
            next_OUT   = '0;
            next_state = go ? S2 : S0;
         end

         S1: begin
            // Finalize: gcd = base << k
            next_OUT   = gcd_base << k_ff;
            next_state = S0;
         end

         S2: begin
            // One step of Stein's algorithm
            if ((A_ff != 0) && (B_ff != 0)) begin
               if (both_even) begin
                  next_A_ff = A_ff >> 1;
                  next_B_ff = B_ff >> 1;
                  next_k_ff = k_ff + 1;
               end else if (a_even && !b_even) begin
                  next_A_ff = A_ff >> 1;
               end else if (b_even && !a_even) begin
                  next_B_ff = B_ff >> 1;
               end else begin
                  // both odd
                  if (A_ff >= B_ff) begin
                     diff      = A_ff - B_ff;
                     next_A_ff = diff >> 1;
                     next_B_ff = B_ff;
                  end else begin
                     diff      = B_ff - A_ff;
                     next_B_ff = diff >> 1;
                     next_A_ff = A_ff;
                  end
               end
            end else if (A_ff == 0 && B_ff != 0) begin
               next_A_ff = B_ff;
               next_B_ff = B_ff;
            end else if (B_ff == 0 && A_ff != 0) begin
               next_B_ff = A_ff;
               next_A_ff = A_ff;
            end
            next_state = equal ? S1 : S2;
         end

         default: begin
            next_A_ff  = '0;
            next_B_ff  = '0;
            next_k_ff  = '0;
            next_OUT   = '0;
            next_state = S0;
         end
      endcase
   end

   // Single sequential block (synchronous reset), OUT registered directly
   always_ff @(posedge clk) begin
      if (rst) begin
         state <= S0;
         A_ff  <= '0;
         B_ff  <= '0;
         k_ff  <= '0;
         OUT   <= '0;
         done  <= 1'b0;
      end else begin
         state <= next_state;
         A_ff  <= next_A_ff;
         B_ff  <= next_B_ff;
         k_ff  <= next_k_ff;
         OUT   <= next_OUT;
         done  <= (state == S1);
      end
   end

endmodule

module generic_counter #(parameter N = 8) (
    input logic clk_in,          // Clock input
    input logic rst_in,          // Active HIGH Reset input
    input logic [2:0] mode_in,   // Mode input (3 bits)
    input logic enable_in,       // Enable input
    input logic [N-1:0] ref_modulo, // Reference modulo value for Modulo-256 counter
    output logic [N-1:0] o_count   // Output count (N bits)
);

    parameter BINARY_UP = 3'b000;
    parameter BINARY_DOWN = 3'b001;
    parameter MODULO_256 = 3'b010;
    parameter JOHNSON = 3'b011;
    parameter GRAY = 3'b100;
    parameter RING = 3'b101;

    logic [N-1:0] count;

    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            count <= {N{1'b0}};
        end else if (enable_in) begin
            case (mode_in)
                BINARY_UP: begin
                    count <= count + 1;
                end
                BINARY_DOWN: begin
                    count <= count - 1;
                end
                MODULO_256: begin
                    if (count == ref_modulo) begin
                        count <= {N{1'b0}};
                    end else begin
                        count <= count + 1;
                    end
                end
                JOHNSON: begin
                    count <= {~count[0], count[N-1:1]};
                end
                GRAY: begin
                    count <= count + 1;
                end
                RING: begin
                    if (count == {N{1'b0}}) begin
                        count <= {{(N-1){1'b0}}, 1'b1};
                    end else begin
                        count <= {count[N-2:0], count[N-1]};
                    end
                end
                default: begin
                    count <= {N{1'b0}};
                end
            endcase
        end
    end

    assign o_count = (mode_in == GRAY) ? (count ^ (count >> 1)) : count;

endmodule

module generic_counter #(parameter N = 8) (
    input  logic         clk_in,          // Clock input
    input  logic         rst_in,          // Active HIGH Reset input (synchronous)
    input  logic [2:0]   mode_in,         // Mode input (3 bits)
    input  logic         enable_in,       // Enable input
    input  logic [N-1:0] ref_modulo,      // Reference modulo value for Modulo-N counter
    output logic [N-1:0] o_count          // Output count (N bits)
);

    parameter BINARY_UP   = 3'b000;
    parameter BINARY_DOWN = 3'b001;
    parameter MODULO_N    = 3'b010;
    parameter JOHNSON     = 3'b011;
    parameter GRAY        = 3'b100;
    parameter RING        = 3'b101;

    // Base state registers.
    //  - count_bin_up serves BINARY_UP, BINARY_DOWN (= -count_bin_up) and
    //    GRAY (binary->gray of count_bin_up), since count_gray shares the
    //    identical +1 recurrence and count_bin_down = -count_bin_up (mod 2^N).
    logic [N-1:0] count_bin_up;
    logic [N-1:0] count_modulo;
    logic [N-1:0] count_johnson;
    logic [N-1:0] count_ring;

    // Single sequential block: every base counter free-runs on enable,
    // independent of mode_in (matches the original's parallel counters).
    always_ff @(posedge clk_in) begin
        if (rst_in) begin
            count_bin_up  <= {N{1'b0}};
            count_modulo  <= {N{1'b0}};
            count_johnson <= {N{1'b0}};
            count_ring    <= {N{1'b0}};
        end else if (enable_in) begin
            count_bin_up  <= count_bin_up + 1'b1;
            count_modulo  <= (count_modulo == ref_modulo) ? {N{1'b0}}
                                                          : count_modulo + 1'b1;
            count_johnson <= {~count_johnson[0], count_johnson[N-1:1]};
            count_ring    <= (count_ring == {N{1'b0}})
                                ? {{(N-1){1'b0}}, 1'b1}
                                : {count_ring[N-2:0], count_ring[N-1]};
        end
    end

    // Output selection.
    always_comb begin
        case (mode_in)
            BINARY_UP:   o_count = count_bin_up;
            BINARY_DOWN: o_count = (~count_bin_up + 1'b1);          // -count_bin_up
            MODULO_N:    o_count = count_modulo;
            JOHNSON:     o_count = count_johnson;
            GRAY:        o_count = count_bin_up ^ (count_bin_up >> 1);
            RING:        o_count = count_ring;
            default:     o_count = {N{1'b0}};
        endcase
    end

endmodule

// GF(2^4) Galois Field Multiplier
// Irreducible polynomial: x^4 + x + 1  (5'b10011)
// Combinational: result updates whenever A or B changes.
module gf_multiplier (
    input  wire [3:0] A,        // multiplicand
    input  wire [3:0] B,        // multiplier
    output reg  [3:0] result    // GF product
);

    // Internal registers holding the running multiplicand and the
    // intermediate result. The multiplicand is carried as 5 bits so the
    // left-shift overflow bit can be tested against the irreducible
    // polynomial 5'b10011 (x^4 + x + 1).
    reg [4:0] multiplicand;
    integer   i;

    always @(*) begin
        // 1. Initialize result = 0
        result       = 4'b0000;
        // 2. Set multiplicand = A
        multiplicand = {1'b0, A};

        // 3. For each bit of the multiplier B (LSB to MSB)
        for (i = 0; i < 4; i = i + 1) begin
            // If B[i] is 1, result = result XOR multiplicand (else XOR 0)
            if (B[i])
                result = result ^ multiplicand[3:0];

            // Shift multiplicand left by 1 bit
            multiplicand = multiplicand << 1;

            // If the MSB is 1 after shifting, reduce by the polynomial
            if (multiplicand[4])
                multiplicand = multiplicand ^ 5'b10011;
        end
    end

endmodule


// --- harness-toplevel alias (auto-added by cvdp_gate; the official
