module gf_mac #(
    parameter integer WIDTH = 32   // Configurable input width, must be a multiple of 8
) (
    input  [WIDTH-1:0] a,          // Multiplicand, segmented into 8-bit blocks
    input  [WIDTH-1:0] b,          // Multiplier, segmented into 8-bit blocks
    output [7:0]       result      // Final 8-bit GF MAC result
);

    localparam integer NUM_SEG = WIDTH / 8; // Number of 8-bit segments

    // Per-segment GF(2^8) multiplication results
    wire [7:0] segment_result [0:NUM_SEG-1];
    // Running XOR-accumulation chain across segments (GF addition == XOR)
    wire [7:0] xor_chain      [0:NUM_SEG-1];

    genvar g;
    generate
        for (g = 0; g < NUM_SEG; g = g + 1) begin : gen_seg
            // Instantiate the 8-bit GF(2^8) multiplier per 8-bit segment
            gf_multiplier u_mult (
                .A      (a[g*8 +: 8]),
                .B      (b[g*8 +: 8]),
                .result (segment_result[g])
            );

            if (g == 0) begin : gen_first
                assign xor_chain[0] = segment_result[0];
            end else begin : gen_rest
                assign xor_chain[g] = xor_chain[g-1] ^ segment_result[g];
            end
        end
    endgenerate

    // Final cumulative XOR of all segment multiplications
    assign result = xor_chain[NUM_SEG-1];

endmodule

module gf_mac #(
    parameter WIDTH = 32  // Input width, should be a multiple of 8
)(
    input  [WIDTH-1:0] a,            // Multiplicand
    input  [WIDTH-1:0] b,            // Multiplier
    output reg [7:0]   result,       // 8-bit XORed result of all GF multiplications
    output             error_flag,   // 1 when WIDTH is not a multiple of 8
    output             valid_result  // 1 when result is valid (WIDTH multiple of 8)
);

    // Number of 8-bit segments (kept >= 1 so the array range is always legal,
    // even for an invalid WIDTH < 8).
    localparam integer NSEG = (WIDTH >= 8) ? (WIDTH/8) : 1;

    integer i;
    reg [7:0] temp_result;
    wire [7:0] partial_results [NSEG-1:0];

    // Generate GF multipliers for each 8-bit segment
    genvar j;
    generate
        for (j = 0; j < WIDTH/8; j = j + 1) begin : segment_mult
            gf_multiplier segment_mult (
                .A(a[(j+1)*8-1:j*8]),
                .B(b[(j+1)*8-1:j*8]),
                .result(partial_results[j])
            );
        end
    endgenerate

    // Result: only computed when WIDTH is a multiple of 8, else forced to 0
    always @(*) begin
        if (WIDTH % 8 != 0) begin
            result = 8'b0;
        end else begin
            temp_result = 8'b0;
            for (i = 0; i < WIDTH/8; i = i + 1) begin
                temp_result = temp_result ^ partial_results[i];
            end
            result = temp_result;
        end
    end

    // Error detection / result validation (WIDTH is a compile-time parameter)
    assign error_flag   = (WIDTH % 8 != 0) ? 1'b1 : 1'b0;
    assign valid_result = (WIDTH % 8 != 0) ? 1'b0 : 1'b1;

endmodule

module gf_multiplier (
    input [7:0] A,
    input [7:0] B,
    output reg [7:0] result
);
    reg [7:0] temp_result;
    reg [8:0] multiplicand;
    reg [8:0] irreducible_poly = 9'b100011011; // x^8 + x^4 + x^3 + x + 1

    integer i;

    always @(*) begin
        temp_result = 8'b00000000;
        multiplicand = {1'b0, A};
        for (i = 0; i < 8; i = i + 1) begin
            if (B[i]) begin
                temp_result = temp_result ^ multiplicand[7:0];
            end
            multiplicand = multiplicand << 1;
            if (multiplicand[8]) begin
                multiplicand = multiplicand ^ irreducible_poly;
            end
        end
        result = temp_result;
    end
endmodule

module gmii_rx_to_axi_stream (
    //GMII Input Signals:
    input wire        gmii_rx_clk,
    input wire [7:0]  gmii_rxd,
    input wire        gmii_rx_dv,

    //AXI-Stream Output Signals:
    output wire [7:0] m_axis_tdata,
    output wire       m_axis_tvalid,
    input wire        m_axis_tready,
    output wire       m_axis_tlast
);

    // State definitions
    localparam IDLE = 2'b00,
               RECEIVING = 2'b01,
               FINISHED = 2'b10;

    // Frame reception FSM state and one-cycle pipeline registers.
    // The GMII stream is captured one cycle before it is presented on the
    // AXI-Stream side; this delay is what lets end-of-frame (the falling edge
    // of gmii_rx_dv) be turned into a m_axis_tlast on the very last valid byte.
    reg [1:0] state       = IDLE;
    reg [7:0] gmii_rxd_d  = 8'd0;   // gmii_rxd captured on the previous clock
    reg       gmii_rx_dv_d = 1'b0;  // gmii_rx_dv captured on the previous clock

    // Capture the GMII data/valid every clock (GMII cannot be back-pressured)
    // and advance the frame FSM.  gmii_rx_dv qualifies gmii_rxd: when
    // gmii_rx_dv is not asserted the incoming gmii_rxd is ignored.
    always @(posedge gmii_rx_clk) begin
        gmii_rxd_d   <= gmii_rxd;
        gmii_rx_dv_d <= gmii_rx_dv;

        case (state)
            IDLE: begin
                // Start of a frame: gmii_rx_dv asserted.
                if (gmii_rx_dv)
                    state <= RECEIVING;
            end
            RECEIVING: begin
                // Frame continues while gmii_rx_dv stays asserted; when it
                // drops the frame is finished.
                if (!gmii_rx_dv)
                    state <= FINISHED;
            end
            FINISHED: begin
                // A new frame may start immediately (back-to-back frames),
                // otherwise return to IDLE.
                state <= gmii_rx_dv ? RECEIVING : IDLE;
            end
            default: state <= IDLE;
        endcase
    end

    // AXI-Stream outputs.
    //  - tdata is the byte captured on the previous clock (1-cycle latency).
    //  - tvalid is asserted while a frame's bytes are streaming out; per the
    //    specification it is de-asserted whenever the downstream m_axis_tready
    //    is low.
    //  - tlast marks the final byte of the frame: the last captured byte is
    //    presented in the RECEIVING state on the cycle gmii_rx_dv has just
    //    de-asserted.
    assign m_axis_tdata  = gmii_rxd_d;
    assign m_axis_tvalid = (state == RECEIVING) & m_axis_tready;
    assign m_axis_tlast  = (state == RECEIVING) & ~gmii_rx_dv;

endmodule

module gray_to_binary #(
    parameter WIDTH      = 4,  // Specify the width of the Gray code input
    parameter DEBUG_MODE = 0   // Debug mode: 0 = Disabled, 1 = Enabled
) (
    input  logic [WIDTH-1:0] gray_in,
    output logic [WIDTH-1:0] binary_out,
    output logic [WIDTH-1:0] debug_mask,
    output logic             parity,
    output logic             valid
);

  logic [WIDTH-1:0] intermediate_stage_1;
  logic [WIDTH-1:0] intermediate_stage_2;
  logic [WIDTH-1:0] masked_output;
  logic [WIDTH-1:0] final_binary;
  logic             valid_stage_1;
  logic             valid_stage_2;

  always @* begin

    // Stage 1: Intermediate Binary Computation (cascading XOR from MSB down)
    intermediate_stage_1[WIDTH-1] = gray_in[WIDTH-1];
    for (int i = WIDTH - 2; i >= 0; i--) begin
      intermediate_stage_1[i] = intermediate_stage_1[i+1] ^ gray_in[i];
    end
    valid_stage_1 = 1'b1;

    // Stage 2: Debugging and Masking
    if (DEBUG_MODE == 1) begin
      // Apply diagnostic masking; the final binary result is unchanged,
      // and the debug mask is the bitwise inversion of the binary result.
      masked_output = intermediate_stage_1;
      debug_mask    = ~intermediate_stage_1;
    end else begin
      // Debug disabled: pass through unmodified, zero the debug mask.
      masked_output = intermediate_stage_1;
      debug_mask    = {WIDTH{1'b0}};
    end
    intermediate_stage_2 = masked_output;
    valid_stage_2        = valid_stage_1;

    // Stage 3: Final Outputs
    final_binary = intermediate_stage_2;
    binary_out   = final_binary;
    parity       = ^final_binary;   // 1 = odd number of 1's, 0 = even
    valid        = valid_stage_2;

  end

endmodule

module conv3x3 (
    input logic          clk,               // Clock signal
    input logic          rst_n,             // Reset signal, active low
    input logic  [7:0]   image_data0,       // Individual pixel data inputs (8-bit each)
    input logic  [7:0]   image_data1,
    input logic  [7:0]   image_data2,
    input logic  [7:0]   image_data3,
    input logic  [7:0]   image_data4,
    input logic  [7:0]   image_data5,
    input logic  [7:0]   image_data6,
    input logic  [7:0]   image_data7,
    input logic  [7:0]   image_data8,
    input logic  [7:0]   kernel0,           // Individual kernel inputs (8-bit each)
    input logic  [7:0]   kernel1,
    input logic  [7:0]   kernel2,
    input logic  [7:0]   kernel3,
    input logic  [7:0]   kernel4,
    input logic  [7:0]   kernel5,
    input logic  [7:0]   kernel6,
    input logic  [7:0]   kernel7,
    input logic  [7:0]   kernel8,
    output logic [15:0]  convolved_data     // 16-bit convolved output
);

    // Stage 1: Element-wise multiplication results
    logic [15:0] mult_result0, mult_result1, mult_result2;
    logic [15:0] mult_result3, mult_result4, mult_result5;
    logic [15:0] mult_result6, mult_result7, mult_result8;

    // Stage 2: Row-wise partial sums
    logic [19:0] pipeline_sum_stage10, pipeline_sum_stage11, pipeline_sum_stage12;

    // Stage 3: Final total sum
    logic [19:0] sum_result;

    // Stage 4: Normalized result
    logic [15:0] normalized_result;

    // Stage 1: Element-wise multiplications
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mult_result0 <= 0; mult_result1 <= 0; mult_result2 <= 0;
            mult_result3 <= 0; mult_result4 <= 0; mult_result5 <= 0;
            mult_result6 <= 0; mult_result7 <= 0; mult_result8 <= 0;
        end else begin
            mult_result0 <= image_data0 * kernel0;
            mult_result1 <= image_data1 * kernel1;
            mult_result2 <= image_data2 * kernel2;
            mult_result3 <= image_data3 * kernel3;
            mult_result4 <= image_data4 * kernel4;
            mult_result5 <= image_data5 * kernel5;
            mult_result6 <= image_data6 * kernel6;
            mult_result7 <= image_data7 * kernel7;
            mult_result8 <= image_data8 * kernel8;
        end
    end

    // Stage 2: Row-wise summation
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pipeline_sum_stage10 <= 0;
            pipeline_sum_stage11 <= 0;
            pipeline_sum_stage12 <= 0;
        end else begin
            pipeline_sum_stage10 <= mult_result0 + mult_result1 + mult_result2;
            pipeline_sum_stage11 <= mult_result3 + mult_result4 + mult_result5;
            pipeline_sum_stage12 <= mult_result6 + mult_result7 + mult_result8;
        end
    end

    // Stage 3: Total summation
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_result <= 0;
        end else begin
            sum_result <= pipeline_sum_stage10 + pipeline_sum_stage11 + pipeline_sum_stage12;
        end
    end

    // Stage 4: Normalization
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            convolved_data <= 0;
        end else begin
            convolved_data <= sum_result / 9; // Normalization by number of kernel elements (3x3 = 9)
        end
    end

endmodule

module halfband_fir #(
    parameter LGNTAPS = 7,
    parameter IW      = 16,
    parameter TW      = 12,
    parameter OW      = IW + TW + LGNTAPS,
    parameter [LGNTAPS:0] NTAPS        = 107,
    parameter [0:0]       FIXED_TAPS   = 1'b0,
    parameter           INITIAL_COEFFS = "",
    parameter [0:0]       OPT_HILBERT  = 1'b0,
    localparam LGNMEM  = LGNTAPS - 1,
    localparam LGNCOEF = LGNMEM - 1,
    localparam [LGNTAPS-1:0] HALFTAPS = NTAPS[LGNTAPS:1],
    localparam [LGNTAPS-2:0] QTRTAPS  = HALFTAPS[LGNTAPS-1:1] + 1,
    localparam DMEMSZ = (1 << LGNMEM),
    localparam CMEMSZ = (1 << LGNCOEF)
)(
    input  wire i_clk,
    input  wire i_reset,
    input  wire i_tap_wr,
    input  wire [(TW-1):0] i_tap,
    input  wire i_ce,
    input  wire [(IW-1):0] i_sample,
    output reg  o_ce,
    output reg  [(OW-1):0] o_result
);

    reg [3:0] messy_flag;

    reg [TW-1:0] coef_mem_messy [0:CMEMSZ-1];


    reg [IW-1:0] dmem1_messy [0:DMEMSZ-1];
    reg [IW-1:0] dmem2_messy [0:DMEMSZ-1];

    reg [LGNMEM-1:0] write_idx, left_idx, right_idx;
    reg [LGNCOEF-1:0] tap_idx;
    reg signed [IW-1:0] sample_left, sample_right, mid_sample_messy;
    reg signed [IW:0]   sum_data;
    reg clk_en, data_en, sum_en;
    reg signed [IW+TW-1:0] mult_result;
    reg signed [OW-1:0]    acc_result;

    // Control wires:
    wire last_tap_warn, last_data_warn;
    wire [LGNTAPS-2:0] remaining_taps;

    generate
      if (FIXED_TAPS || (INITIAL_COEFFS != "")) begin : LOAD_COEFFS
         initial begin
             $readmemh(INITIAL_COEFFS, coef_mem_messy);
         end
      end else begin : DYNAMIC_COEFFS
         reg [LGNCOEF-1:0] tap_wr_idx;
         initial tap_wr_idx = 0;
         always @(posedge i_clk)
            if (i_reset)
                tap_wr_idx <= 0;
            else if (i_tap_wr)
                tap_wr_idx <= tap_wr_idx + 1'b1;
         always @(posedge i_clk)
            if (i_tap_wr)
                coef_mem_messy[tap_wr_idx] <= i_tap;
      end
    endgenerate


    initial write_idx = 0;
    always @(posedge i_clk) begin
        if (i_ce)
            write_idx <= write_idx + 1;
    end

    always @(posedge i_clk)
      if (i_ce) begin
         dmem1_messy[write_idx] <= i_sample;
         dmem2_messy[write_idx] <= mid_sample_messy;
      end

    always @(posedge i_clk)
    begin
      if (i_reset)
         mid_sample_messy <= 0;
      else if (i_ce)
         mid_sample_messy <= sample_left;
    end

    assign remaining_taps = QTRTAPS - tap_idx;
    assign last_tap_warn = (remaining_taps <= 1);
    assign last_data_warn = (QTRTAPS - tap_idx <= 2);


    initial messy_flag = 4'b0;
    always @(posedge i_clk) begin
      if (i_reset)
        messy_flag[0] <= 1'b0;
      else if (i_ce)
        messy_flag[0] <= 1'b1;
      else if (messy_flag[0] && !last_tap_warn)
        messy_flag[0] <= 1'b1;
      else if (!clk_en)
        messy_flag[0] <= 1'b0;
    end

    always @(posedge i_clk)
      if (i_reset)
         messy_flag[3:1] <= 3'b0;
      else
         messy_flag[3:1] <= { messy_flag[2:1], (clk_en || (messy_flag[0] && !last_tap_warn)) };


    initial begin
      left_idx = 0;
      right_idx = 0;
    end

    always @(posedge i_clk) begin
      if (i_reset) begin
        left_idx <= 0;
        right_idx <= 0;
      end else if (i_ce) begin
        left_idx <= write_idx;
        right_idx <= write_idx - (HALFTAPS[LGNMEM-1:0]) + 1;
      end else if (clk_en || !last_data_warn) begin
        left_idx <= left_idx - 2;
        right_idx <= right_idx + 2;
      end
    end


    initial tap_idx = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         tap_idx <= 0;
      else if (clk_en)
         tap_idx <= 0;
      else if (!last_tap_warn)
         tap_idx <= tap_idx + 1;
    end


    initial clk_en = 1'b0;
    always @(posedge i_clk) begin
      clk_en <= (i_ce && !i_reset);
    end


    initial begin
        sample_left  = 0;
        sample_right = 0;
    end

    always @(posedge i_clk) begin
      sample_left  <= dmem1_messy[left_idx];
      sample_right <= dmem2_messy[right_idx];
    end

    // --- Data Enable Update ---
    initial data_en = 1'b0;
    always @(posedge i_clk)
       data_en <= (clk_en && !i_reset);

    // --- Coefficient Read and Data Sum Computation ---
    reg [TW-1:0] current_coef;
    initial current_coef = 0;
    always @(posedge i_clk)
       current_coef <= coef_mem_messy[tap_idx[LGNCOEF-1:0]];

    initial sum_data = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         sum_data <= 0;
      else if (OPT_HILBERT)
         sum_data <= sample_left - sample_right;
      else
         sum_data <= sample_left + sample_right;
    end

    // --- Summation Enable ---
    initial sum_en = 1'b0;
    always @(posedge i_clk)
       sum_en <= (data_en && !i_reset);

    // --- Multiply Operation ---
    initial mult_result = 0;
    always @(posedge i_clk)
       mult_result <= current_coef * sum_data;

       wire [OW-1:0] mid_prod;
    generate
      if (OPT_HILBERT) begin : NO_MIDPOINT
         assign mid_prod = 0;
      end else begin : GEN_MIDPOINT
         reg [OW-1:0] mid_prod_reg;
         initial mid_prod_reg = 0;
         always @(posedge i_clk) begin
            if (i_reset)
               mid_prod_reg <= 0;
            else if (clk_en)
               mid_prod_reg <= { {(OW-IW-TW+1){mid_sample_messy[IW-1]}},
                                  mid_sample_messy, {(TW-1){1'b0}} }
                              - { {(OW-IW){mid_sample_messy[IW-1]}},
                                  mid_sample_messy };
         end
         assign mid_prod = mid_prod_reg;
      end
    endgenerate

    // --- Accumulation ---
    initial acc_result = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         acc_result <= 0;
      else if (sum_en)
         acc_result <= mid_prod;
      else if (messy_flag[3])
         acc_result <= acc_result + { {(OW-(IW+TW)){mult_result[IW+TW-1]}}, mult_result };
    end

    // --- Output Assignments ---
    initial o_result = 0;
    always @(posedge i_clk)
       if (sum_en)
          o_result <= acc_result;

    // --- Output Clock Enable Update ---
    initial o_ce = 1'b0;
    always @(posedge i_clk)
       o_ce <= (sum_en && !i_reset);

endmodule

module hamming_code_tx_for_4bit (
    input  wire [3:0] data_in,
    output wire [7:0] data_out
);

    // Redundant padding bit (LSB), fixed to 0
    assign data_out[0] = 1'b0;

    // Parity bits (even parity via XOR), placed at power-of-2 positions
    assign data_out[1] = data_in[0] ^ data_in[1] ^ data_in[3];
    assign data_out[2] = data_in[0] ^ data_in[2] ^ data_in[3];
    assign data_out[4] = data_in[1] ^ data_in[2] ^ data_in[3];

    // Data bits preserved in order
    assign data_out[3] = data_in[0];
    assign data_out[5] = data_in[1];
    assign data_out[6] = data_in[2];
    assign data_out[7] = data_in[3];

endmodule

module hamming_code_receiver (
    input  wire [7:0] data_in,
    output wire [3:0] data_out
);

    // Even-parity syndrome bits {c1, c2, c3}
    wire c1, c2, c3;

    // c3: positions with LSB set (1,3,5,7)
    assign c3 = data_in[1] ^ data_in[3] ^ data_in[5] ^ data_in[7];
    // c2: positions with 2nd-LSB set (2,3,6,7)
    assign c2 = data_in[2] ^ data_in[3] ^ data_in[6] ^ data_in[7];
    // c1: positions with MSB set (4,5,6,7)
    assign c1 = data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7];

    // Error position pointed to by {c1, c2, c3}
    wire [2:0] error_pos;
    assign error_pos = {c1, c2, c3};

    // Corrected 8-bit word: invert the bit at error_pos (except position 0)
    reg [7:0] corrected;
    always @(*) begin
        corrected = data_in;
        if (error_pos != 3'b000)
            corrected[error_pos] = ~data_in[error_pos];
    end

    // Data bits reside at positions 3, 5, 6, 7 of the corrected word.
    // data_out = { pos7, pos6, pos5, pos3 }
    assign data_out = {corrected[7], corrected[6], corrected[5], corrected[3]};

endmodule

module hamming_tx #(
  parameter DATA_WIDTH       = 4,
  parameter PARITY_BIT       = 3,
  parameter ENCODED_DATA     = PARITY_BIT + DATA_WIDTH + 1,
  parameter ENCODED_DATA_BIT = $clog2(ENCODED_DATA)
) (
  input  wire [DATA_WIDTH-1:0]    data_in,
  output reg  [ENCODED_DATA-1:0]  data_out
);

  // Internal PARITY_BIT-width array holding the calculated parity values.
  reg [PARITY_BIT-1:0] parity;

  integer i;
  integer j;
  integer n;
  integer k;

  always @* begin
    // Step 1: Clear all internal registers to 0.
    data_out = {ENCODED_DATA{1'b0}};
    parity   = {PARITY_BIT{1'b0}};

    // Step 2: Map data_in sequentially (LSB -> MSB) into the non-parity,
    // non-redundant positions of data_out (increasing index order).
    // data_out[0] is the redundant bit and stays 1'b0. Positions that are
    // powers of two (1, 2, 4, 8, ...) are reserved for parity bits.
    j = 0;
    for (i = 0; i < ENCODED_DATA; i = i + 1) begin
      // A position is a parity position iff i != 0 and i is a power of two.
      if (i != 0 && ((i & (i - 1)) != 0)) begin
        if (j < DATA_WIDTH) begin
          data_out[i] = data_in[j];
          j = j + 1;
        end
      end
    end

    // Step 3: Compute even parity bits (XOR) per the Hamming principle.
    // parity[n] = XOR of data_out at all indices whose n-th bit is set,
    // excluding the power-of-two (parity) positions themselves.
    for (n = 0; n < PARITY_BIT; n = n + 1) begin
      for (k = 0; k < ENCODED_DATA; k = k + 1) begin
        if (((k >> n) & 1) == 1 &&
            !(k != 0 && ((k & (k - 1)) == 0))) begin
          parity[n] = parity[n] ^ data_out[k];
        end
      end
    end

    // Step 4: Insert parity bits at positions corresponding to powers of two.
    for (n = 0; n < PARITY_BIT; n = n + 1) begin
      data_out[(1 << n)] = parity[n];
    end
  end

endmodule

// Parameterized Hamming-code receiver (single-bit error detect + correct).
// Generalizes the fixed-width `hamming_code_receiver` reference into `hamming_rx`.
// Combinational: data_out updates immediately with data_in.
module hamming_rx #(
    // Width of the original data payload (m). Default 4, must be > 0.
    parameter integer DATA_WIDTH      = 4,
    // Number of parity bits (p): min p s.t. 2^p >= (p + m) + 1.
    parameter integer PARITY_BIT      = 3,
    // Total encoded width = parity + data + 1 redundant bit (LSB, index 0).
    parameter integer ENCODED_DATA    = PARITY_BIT + DATA_WIDTH + 1,
    // Bits needed to index a position in the encoded word.
    parameter integer ENCODED_DATA_BIT = $clog2(ENCODED_DATA)
) (
    input  wire [ENCODED_DATA-1:0] data_in,
    output wire [DATA_WIDTH-1:0]   data_out
);

    // Calculated parity/check bits: parity[n] = even-parity (XOR) over every
    // position i whose 1-in-bit-n binary index selects it.
    reg [PARITY_BIT-1:0]    parity;

    // Encoded word after single-bit correction (redundant bit @0 untouched).
    reg [ENCODED_DATA-1:0]  correct_data;

    // Extracted, corrected data payload driving data_out.
    reg [DATA_WIDTH-1:0]    data_out_reg;

    integer i;
    integer n;
    integer d;

    always @(*) begin
        // ---- 1. Initialize ----
        parity       = {PARITY_BIT{1'b0}};
        correct_data = {ENCODED_DATA{1'b0}};
        data_out_reg = {DATA_WIDTH{1'b0}};

        // ---- 2. Error detection: even-parity per power-of-2 check group ----
        for (n = 0; n < PARITY_BIT; n = n + 1) begin
            for (i = 0; i < ENCODED_DATA; i = i + 1) begin
                if ((i & (1 << n)) != 0)
                    parity[n] = parity[n] ^ data_in[i];
            end
        end

        // ---- 3. Error correction ----
        // Syndrome {parity[PARITY_BIT-1:0]} is the binary index of the faulty
        // bit. Zero => no error. Non-zero => invert that position; the syndrome
        // can never be 0 for a correction, so the redundant bit @0 is never hit.
        correct_data = data_in;
        if (parity != {PARITY_BIT{1'b0}})
            correct_data[parity] = ~correct_data[parity];

        // ---- 4. Output assignment ----
        // Data bits live at non-power-of-2, non-zero positions (3,5,6,7,...).
        // Pack them LSB->MSB, lowest source index to data_out[0] upward.
        d = 0;
        for (i = 1; i < ENCODED_DATA; i = i + 1) begin
            if ((i & (i - 1)) != 0) begin
                data_out_reg[d] = correct_data[i];
                d = d + 1;
            end
        end
    end

    assign data_out = data_out_reg;

endmodule

module hamming_tx #(
    parameter DATA_WIDTH    = 64,
    parameter PART_WIDTH    = 4,
    parameter PARITY_BIT    = 3,
    parameter ENCODED_DATA  = PARITY_BIT + PART_WIDTH + 1,
    parameter NUM_MODULES   = DATA_WIDTH / PART_WIDTH,
    parameter TOTAL_ENCODED = ENCODED_DATA * NUM_MODULES
 )(
    input  [DATA_WIDTH-1:0]    data_in,
    output [TOTAL_ENCODED-1:0] data_out
);

    genvar i;

    // Split data_in into NUM_MODULES parts (part 0 = least significant bits),
    // encode each with a t_hamming_tx instance, and concatenate the encoded
    // outputs sequentially (instance 0 output = least significant bits of
    // data_out) so the input data order is preserved.
    generate
        for (i = 0; i < NUM_MODULES; i = i + 1) begin : gen_hamming
            t_hamming_tx #(
                .DATA_WIDTH (PART_WIDTH),
                .PARITY_BIT (PARITY_BIT)
            ) u_t_hamming_tx (
                .data_in  (data_in[i*PART_WIDTH   +: PART_WIDTH]),
                .data_out (data_out[i*ENCODED_DATA +: ENCODED_DATA])
            );
        end
    endgenerate

endmodule



module t_hamming_tx #(
    parameter DATA_WIDTH       = 4,
    parameter PARITY_BIT       = 3,
    parameter ENCODED_DATA     = PARITY_BIT + DATA_WIDTH + 1,
    parameter ENCODED_DATA_BIT = $clog2(ENCODED_DATA)
)(
    input  [DATA_WIDTH-1:0]       data_in,
    output  reg[ENCODED_DATA-1:0] data_out
);

    reg [PARITY_BIT-1:0] parity;
    integer i, j, count;
    reg [ENCODED_DATA_BIT:0] pos;

    always @(*) begin
        data_out = {ENCODED_DATA{1'b0}};
        parity   = {PARITY_BIT{1'b0}};
        count    = 0;

        for (pos = 1; pos < ENCODED_DATA; pos = pos + 1) begin
            if (count < DATA_WIDTH) begin
                if ((pos & (pos - 1)) != 0) begin
                    data_out[pos] = data_in[count];
                    count = count + 1;
                end
            end
        end

        for (j = 0; j < PARITY_BIT; j = j + 1) begin
            for (i = 1; i <= ENCODED_DATA-1; i = i + 1) begin
                if ((i & (1 << j)) != 0) begin
                    parity[j] = parity[j] ^ data_out[i];
                end
            end
        end

        for (j = 0; j < PARITY_BIT; j = j + 1) begin
            data_out[(1 << j)] = parity[j];
        end
    end

endmodule

module hebb_gates(
   input  logic               clk,
   input  logic               rst,
   input  logic               start, // To start the FSM
   input  logic  signed [3:0] a, // First Input
   input  logic  signed [3:0] b, // Second Input
   input  logic         [1:0] gate_select, // To provide the targets for a selected gate in order to train
   output logic  signed [3:0] w1, // Weight 1 obtained by training
   output logic  signed [3:0] w2, // Weight 2 obtained by training
   output logic  signed [3:0] bias,// Bias obtained by training
   output logic [3:0] present_state,// Present State of the Training FSM
   output logic [3:0] next_state, // Next_State of the Training FSM
   // ---- Testing FSM outputs ----
   output logic [3:0]        test_present_state, // Present state of the Testing FSM
   output logic signed [3:0] test_output,        // Calculated output during testing (+1/-1)
   output logic [3:0]        test_result,        // Count of correct matches
   output logic              test_done           // Active high: testing complete
);
   logic signed [3:0] t1;
   logic signed [3:0] t2;
   logic signed [3:0] t3;
   logic signed [3:0] t4;

   gate_target dut(
       .gate_select(gate_select),
       .o_1        (t1),
       .o_2        (t2),
       .o_3        (t3),
       .o_4        (t4)
   );

   localparam [3:0] S0 = 4'd0;
   localparam [3:0] S1 = 4'd1;
   localparam [3:0] S2 = 4'd2;
   localparam [3:0] S3 = 4'd3;
   localparam [3:0] S4 = 4'd4;
   localparam [3:0] S5 = 4'd5;
   localparam [3:0] S6 = 4'd6;
   localparam [3:0] S7 = 4'd7;
   localparam [3:0] S8 = 4'd8;
   localparam [3:0] S9 = 4'd9;
   localparam [3:0] S10 = 4'd10;

   logic [2:0] iteration;
   logic signed [3:0] x1;
   logic signed [3:0] x2;
   logic signed [3:0] delta_w1;
   logic signed [3:0] delta_w2;
   logic signed [3:0] delta_b;
   logic signed [3:0] w1_reg;
   logic signed [3:0] w2_reg;
   logic signed [3:0] bias_reg;
   logic signed [1:0] target;
   logic delta_en;
   logic sum_en;
   logic clr_en;
   logic cap_en;
   logic done; // Training-complete flag (starts the Testing FSM)

   always_comb begin
     if(cap_en ) begin
        x1 = a;
        x2 = b;
     end else begin
        x1 = x1 + 4'h0;
        x2 = x2 + 4'h0;
     end

   end

   always_comb begin

     if(delta_en) begin
       delta_w1 = x1 * target;
       delta_w2 = x2 * target;
       delta_b  = target;
     end else begin
       delta_w1 = delta_w1 + 4'h0;
       delta_w2 = delta_w2 + 4'h0;
       delta_b  = delta_b + 4'h0;
   end

  end

  always_comb begin

     if(sum_en) begin
       w1_reg = w1_reg + delta_w1;
       w2_reg = w2_reg + delta_w2;
       bias_reg = bias_reg + delta_b;
     end else begin
       w1_reg = w1_reg + 4'h0;
       w2_reg = w2_reg + 4'h0;
       bias_reg = bias_reg + 4'h0;
   end
  end

   always_comb begin

     if(clr_en) begin
       w1_reg = 0;
       w2_reg = 0;
       bias_reg = 0;
     end else begin
       w1_reg = w1_reg + 4'h0;
       w2_reg = w2_reg + 4'h0;
       bias_reg = bias_reg + 4'h0;
    end
   end

   always_ff@(posedge clk or negedge rst) begin
       if(!rst) begin
          present_state <= S0;
          iteration <= 0;
        end else
          present_state <= next_state;
   end

   always_comb begin
        next_state = present_state;

     case(present_state)
             S0  : begin
                      if(start)
                         next_state = S1;
                      else
                         next_state = S0;
                   end
             S1  : begin
                         next_state = S2;
                   end
             S2  : begin
                      if(iteration == 0)
                        next_state = S3;
                     else if(iteration == 1)
                        next_state = S4;
                     else if(iteration == 2)
                        next_state = S5;
                     else
                        next_state = S6;
                   end
             S3  : begin
                         next_state = S7;

                   end
             S4  : begin
                         next_state = S7;
                  end
             S5  : begin
                         next_state = S7;
                  end
             S6  : begin
                         next_state = S7;
                  end
             S7  :begin
                         next_state = S8;
                  end
             S8  : begin
                         next_state = S9;
                  end
             S9  : begin
                      if(iteration < 4)
                         next_state = S1;
                      else
                         next_state = S10;
                   end
             S10 : begin
                      next_state = S0;
                   end
             default : ;
     endcase
   end

   always_comb begin

      case(present_state)
             S0 : begin
                    clr_en = 1;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en   = 0;
                    iteration = 0;
                    target = target + 4'h0;
                  end
             S1 : begin
                    clr_en = 0;
                    cap_en = 1;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end
             S2 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end
             S3 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = t1;
                  end
             S4 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = t2;
                  end

             S5 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = t3;
                  end
             S6 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = t4;
                  end
             S7 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 1;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end
             S8 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 1;
                    iteration = iteration + 1;
                    target = target + 4'h0;
                  end
             S9 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end
             S10 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end



           default : begin
                      clr_en = 0;
                      cap_en = 0;
                      delta_en = 0;
                      sum_en = 0;
                      iteration = 0;
                      target = target + 4'h0;
                     end
       endcase
   end
   assign w1 = w1_reg;
   assign w2 = w2_reg;
   assign bias = bias_reg;

   // ==================================================================
   //  Testing FSM (microcode-sequencer controlled)
   // ==================================================================

   // Training-complete flag: raised while the training FSM is in S10.
   assign done = (present_state == S10);

   // Latch the trained weights/bias at completion (the training FSM
   // re-clears them in S0, so testing samples them at 'done').
   logic signed [3:0] w1_lat, w2_lat, bias_lat;
   always_ff @(posedge clk or negedge rst) begin
      if(!rst) begin
         w1_lat   <= 4'sd0;
         w2_lat   <= 4'sd0;
         bias_lat <= 4'sd0;
      end else if(done) begin
         w1_lat   <= w1;
         w2_lat   <= w2;
         bias_lat <= bias;
      end
   end

   // Predefined test vectors (depth 16, 4-bit signed, bipolar).
   // Input combinations per 4-vector gate group: (1,1),(1,-1),(-1,1),(-1,-1).
   // Expected outputs mirror the gate_target table for each gate group.
   logic signed [3:0] test_inputs_x1        [0:15];
   logic signed [3:0] test_inputs_x2        [0:15];
   logic signed [3:0] test_expected_outputs [0:15];

   integer k;
   initial begin
      // x1 pattern repeats {1,1,-1,-1} for every gate group
      for (k = 0; k < 16; k = k + 1) begin
         case (k % 4)
            0: test_inputs_x1[k] =  4'sd1;
            1: test_inputs_x1[k] =  4'sd1;
            2: test_inputs_x1[k] = -4'sd1;
            3: test_inputs_x1[k] = -4'sd1;
         endcase
         case (k % 4)
            0: test_inputs_x2[k] =  4'sd1;
            1: test_inputs_x2[k] = -4'sd1;
            2: test_inputs_x2[k] =  4'sd1;
            3: test_inputs_x2[k] = -4'sd1;
         endcase
      end
      // gate_select 2'b00 -> {1,-1,-1,-1}
      test_expected_outputs[0]  =  4'sd1;
      test_expected_outputs[1]  = -4'sd1;
      test_expected_outputs[2]  = -4'sd1;
      test_expected_outputs[3]  = -4'sd1;
      // gate_select 2'b01 -> {1,1,1,-1}
      test_expected_outputs[4]  =  4'sd1;
      test_expected_outputs[5]  =  4'sd1;
      test_expected_outputs[6]  =  4'sd1;
      test_expected_outputs[7]  = -4'sd1;
      // gate_select 2'b10 -> {1,1,1,-1}
      test_expected_outputs[8]  =  4'sd1;
      test_expected_outputs[9]  =  4'sd1;
      test_expected_outputs[10] =  4'sd1;
      test_expected_outputs[11] = -4'sd1;
      // gate_select 2'b11 -> {1,-1,-1,-1}
      test_expected_outputs[12] =  4'sd1;
      test_expected_outputs[13] = -4'sd1;
      test_expected_outputs[14] = -4'sd1;
      test_expected_outputs[15] = -4'sd1;
   end

   // Microcode ROM: 5 locations x 16-bit instruction word.
   //   [15:12] = test_next_state , [11:8] = test_action , [7:0] = 0 (reserved)
   // ROM index maps to active testing states 1..5 (INIT,FETCH,CALC,VERIFY,DONE).
   logic [15:0] microcode_rom [0:4];
   initial begin
      microcode_rom[0] = 16'h2100; // INIT   -> next FETCH(2) , action 1
      microcode_rom[1] = 16'h3200; // FETCH  -> next CALC(3)  , action 2
      microcode_rom[2] = 16'h4300; // CALC   -> next VERIFY(4), action 3
      microcode_rom[3] = 16'h2400; // VERIFY -> next FETCH(2) , action 4 (loop)
      microcode_rom[4] = 16'h0500; // DONE   -> next IDLE(0)  , action 5
   end

   // Testing FSM state encodings
   localparam [3:0] T_IDLE   = 4'd0;
   localparam [3:0] T_INIT   = 4'd1;
   localparam [3:0] T_FETCH  = 4'd2;
   localparam [3:0] T_CALC   = 4'd3;
   localparam [3:0] T_VERIFY = 4'd4;
   localparam [3:0] T_DONE   = 4'd5;

   logic [3:0]         test_next_state;
   logic [3:0]         test_action;
   logic [3:0]         test_index;
   logic signed [3:0]  test_x1;
   logic signed [3:0]  test_x2;
   logic signed [3:0]  expected_output;
   logic signed [15:0] test_calc;

   // Terminal index for the current gate group: start value + 3
   wire terminal = (test_index[1:0] == 2'b11);

   // Next-state logic (microcode-driven, with the VERIFY loop/done branch)
   always_comb begin
      test_next_state = T_IDLE;
      case (test_present_state)
         T_IDLE   : test_next_state = done ? T_INIT : T_IDLE;
         T_INIT   : test_next_state = microcode_rom[0][15:12];
         T_FETCH  : test_next_state = microcode_rom[1][15:12];
         T_CALC   : test_next_state = microcode_rom[2][15:12];
         T_VERIFY : test_next_state = terminal ? T_DONE : microcode_rom[3][15:12];
         T_DONE   : test_next_state = microcode_rom[4][15:12];
         default  : test_next_state = T_IDLE;
      endcase
   end

   // Instruction (action) decode from the microcode ROM
   always_comb begin
      case (test_present_state)
         T_INIT   : test_action = microcode_rom[0][11:8];
         T_FETCH  : test_action = microcode_rom[1][11:8];
         T_CALC   : test_action = microcode_rom[2][11:8];
         T_VERIFY : test_action = microcode_rom[3][11:8];
         T_DONE   : test_action = microcode_rom[4][11:8];
         default  : test_action = 4'd0;
      endcase
   end

   // test_calc combinational datapath (uses the latched trained weights)
   always_comb begin
      test_calc = (w1_lat * test_x1) + (w2_lat * test_x2) + bias_lat;
   end

   // Testing FSM sequential engine
   always_ff @(posedge clk or negedge rst) begin
      if(!rst) begin
         test_present_state <= T_IDLE;
         test_index         <= 4'd0;
         test_result        <= 4'd0;
         test_output        <= 4'sd0;
         test_done          <= 1'b0;
         test_x1            <= 4'sd0;
         test_x2            <= 4'sd0;
         expected_output    <= 4'sd0;
      end else begin
         test_present_state <= test_next_state;
         case (test_action)
            4'd1 : begin // INIT
                      test_result <= 4'd0;
                      test_output <= 4'sd0;
                      test_done   <= 1'b0;
                      test_index  <= {gate_select, 2'b00};
                   end
            4'd2 : begin // FETCH
                      test_x1         <= test_inputs_x1[test_index];
                      test_x2         <= test_inputs_x2[test_index];
                      expected_output <= test_expected_outputs[test_index];
                   end
            4'd3 : begin // CALC
                      test_output <= (test_calc > 0) ? 4'sd1 : -4'sd1;
                   end
            4'd4 : begin // VERIFY
                      if (test_output == expected_output)
                         test_result <= test_result + 4'd1;
                      if (!terminal)
                         test_index <= test_index + 4'd1;
                   end
            4'd5 : begin // DONE
                      test_done <= 1'b1;
                   end
            default : ; // IDLE / NOP
         endcase
      end
   end

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
     case(gate_select)
          2'b00 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
          2'b01 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b10 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b11 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
        default : begin
                    o_1 =  0;
                    o_2 =  0;
                    o_3 =  0;
                    o_4 =  0;
                  end
        endcase
   end
endmodule

// hebbian_rule : Moore FSM that trains a two-input Hebbian learning model.
// Bipolar inputs (+1 / -1) are captured, a per-gate target is produced by the
// instantiated `gate_target` submodule, and the weights/bias are updated with
// the Hebbian rule over multiple training iterations.

module gate_target (
    input  wire signed [3:0] in1,
    input  wire signed [3:0] in2,
    input  wire        [1:0] gate_select,
    output reg  signed [3:0] target
);
    // A bipolar input is treated as logic-high when it is positive (+1).
    wire in1_high;
    wire in2_high;
    reg  result;

    assign in1_high = (in1 > 0);
    assign in2_high = (in2 > 0);

    always @(*) begin
        case (gate_select)
            2'b00  : result =  (in1_high & in2_high); // AND
            2'b01  : result =  (in1_high | in2_high); // OR
            2'b10  : result = ~(in1_high & in2_high); // NAND
            2'b11  : result = ~(in1_high | in2_high); // NOR
            default: result = 1'b0;
        endcase
        // Map the bipolar target : logic-high -> +1 , logic-low -> -1.
        target = result ? 4'sd1 : -4'sd1;
    end
endmodule


module hebbian_rule (
    input  wire               clk,
    input  wire               rst,          // asynchronous, active-LOW
    input  wire               start,
    input  wire signed [3:0]  a,
    input  wire signed [3:0]  b,
    input  wire        [1:0]  gate_select,
    output reg  signed [3:0]  w1,
    output reg  signed [3:0]  w2,
    output reg  signed [3:0]  bias,
    output reg         [3:0]  present_state,
    output reg         [3:0]  next_state
);

    // ---------------------------------------------------------------------
    // State encoding (11 Moore states)
    // ---------------------------------------------------------------------
    localparam [3:0] STATE_0  = 4'd0;   // reset / init
    localparam [3:0] STATE_1  = 4'd1;   // capture inputs
    localparam [3:0] STATE_2  = 4'd2;   // assign target
    localparam [3:0] STATE_3  = 4'd3;   // assign target
    localparam [3:0] STATE_4  = 4'd4;   // assign target
    localparam [3:0] STATE_5  = 4'd5;   // assign target
    localparam [3:0] STATE_6  = 4'd6;   // assign target
    localparam [3:0] STATE_7  = 4'd7;   // compute deltas
    localparam [3:0] STATE_8  = 4'd8;   // update weights / bias
    localparam [3:0] STATE_9  = 4'd9;   // loop through iterations
    localparam [3:0] STATE_10 = 4'd10;  // return to initial state

    localparam [2:0] MAX_ITER = 3'd4;   // one pass per gate input combination

    // ---------------------------------------------------------------------
    // Datapath registers (spec-named verbatim)
    // ---------------------------------------------------------------------
    reg signed [3:0] x1;
    reg signed [3:0] x2;
    reg signed [3:0] t1;          // captured target for the current vector
    reg signed [3:0] delta_w1;
    reg signed [3:0] delta_w2;
    reg signed [3:0] delta_b;
    reg        [2:0] counter;     // iteration counter

    // ---------------------------------------------------------------------
    // Gate-target submodule (drives the `gate_target` net)
    // ---------------------------------------------------------------------
    wire signed [3:0] gate_target;

    gate_target u_gate_target (
        .in1         (x1),
        .in2         (x2),
        .gate_select (gate_select),
        .target      (gate_target)
    );

    // ---------------------------------------------------------------------
    // Next-state combinational logic (Moore)
    // ---------------------------------------------------------------------
    always @(*) begin
        next_state = present_state;
        case (present_state)
            STATE_0  : next_state = start ? STATE_1 : STATE_0;
            STATE_1  : next_state = STATE_2;
            STATE_2  : next_state = STATE_3;
            STATE_3  : next_state = STATE_4;
            STATE_4  : next_state = STATE_5;
            STATE_5  : next_state = STATE_6;
            STATE_6  : next_state = STATE_7;
            STATE_7  : next_state = STATE_8;
            STATE_8  : next_state = STATE_9;
            STATE_9  : next_state = (counter >= (MAX_ITER - 3'd1)) ? STATE_10 : STATE_1;
            STATE_10 : next_state = STATE_0;
            default  : next_state = STATE_0;
        endcase
    end

    // ---------------------------------------------------------------------
    // Sequential state register + datapath (async active-low reset)
    // ---------------------------------------------------------------------
    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            present_state <= STATE_0;
            w1       <= 4'sd0;
            w2       <= 4'sd0;
            bias     <= 4'sd0;
            x1       <= 4'sd0;
            x2       <= 4'sd0;
            t1       <= 4'sd0;
            delta_w1 <= 4'sd0;
            delta_w2 <= 4'sd0;
            delta_b  <= 4'sd0;
            counter  <= 3'd0;
        end else begin
            present_state <= next_state;
            case (present_state)
                STATE_0 : begin
                    // Step 1 : initialise all weights and bias to zero.
                    w1      <= 4'sd0;
                    w2      <= 4'sd0;
                    bias    <= 4'sd0;
                    counter <= 3'd0;
                end
                STATE_1 : begin
                    // Step 2a : set activation for the input units.
                    x1 <= a;
                    x2 <= b;
                end
                STATE_6 : begin
                    // Step 2b : latch the target selected by the gate.
                    t1 <= gate_target;
                end
                STATE_7 : begin
                    // Step 2c : compute the incremental updates.
                    delta_w1 <= 4'($signed(x1) * $signed(t1));
                    delta_w2 <= 4'($signed(x2) * $signed(t1));
                    delta_b  <= t1;
                end
                STATE_8 : begin
                    // Apply the Hebbian update.
                    w1   <= w1   + delta_w1;
                    w2   <= w2   + delta_w2;
                    bias <= bias + delta_b;
                end
                STATE_9 : begin
                    // Advance the iteration counter.
                    counter <= counter + 3'd1;
                end
                default : begin
                    // STATE_2..STATE_5, STATE_10 : no datapath change.
                end
            endcase
        end
    end

endmodule


