module hill_cipher (
    input  wire        clk,
    input  wire        reset,      // asynchronous, active-high
    input  wire        start,
    input  wire [14:0] plaintext,  // [14:10]=P0, [9:5]=P1, [4:0]=P2
    input  wire [44:0] key,        // 3x3 key matrix, 5 bits per element
    output reg  [14:0] ciphertext, // [14:10]=C0, [9:5]=C1, [4:0]=C2
    output reg         done
);

    localparam [1:0] IDLE  = 2'd0,
                     CALC1 = 2'd1,
                     CALC2 = 2'd2;

    reg [1:0] state;

    // Latched plaintext letters
    reg [4:0] p0, p1, p2;

    // Latched key-matrix elements
    reg [4:0] k00, k01, k02;
    reg [4:0] k10, k11, k12;
    reg [4:0] k20, k21, k22;

    // Matrix multiplication : C_i = (K_i0*P0 + K_i1*P1 + K_i2*P2)
    // Widened to 16 bits so the products/sums never truncate
    // (max value = 25*25*3 = 1875).
    wire [15:0] acc0 = (k00 * p0) + (k01 * p1) + (k02 * p2);
    wire [15:0] acc1 = (k10 * p0) + (k11 * p1) + (k12 * p2);
    wire [15:0] acc2 = (k20 * p0) + (k21 * p1) + (k22 * p2);

    // Modulo 26 of each ciphertext element (result is 0..25 -> 5 bits)
    wire [4:0] c0 = acc0 % 16'd26;
    wire [4:0] c1 = acc1 % 16'd26;
    wire [4:0] c2 = acc2 % 16'd26;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ciphertext <= 15'd0;
            done       <= 1'b0;
            state      <= IDLE;
            p0 <= 5'd0; p1 <= 5'd0; p2 <= 5'd0;
            k00 <= 5'd0; k01 <= 5'd0; k02 <= 5'd0;
            k10 <= 5'd0; k11 <= 5'd0; k12 <= 5'd0;
            k20 <= 5'd0; k21 <= 5'd0; k22 <= 5'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        // Capture plaintext block
                        p0 <= plaintext[14:10];
                        p1 <= plaintext[9:5];
                        p2 <= plaintext[4:0];
                        // Capture key matrix
                        k00 <= key[44:40]; k01 <= key[39:35]; k02 <= key[34:30];
                        k10 <= key[29:25]; k11 <= key[24:20]; k12 <= key[19:15];
                        k20 <= key[14:10]; k21 <= key[9:5];   k22 <= key[4:0];
                        state <= CALC1;
                    end
                end
                CALC1: begin
                    state <= CALC2;
                end
                CALC2: begin
                    // 3-cycle latency : ciphertext valid here (start + 3)
                    ciphertext <= {c0, c1, c2};
                    done       <= 1'b1;
                    state      <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule


