module hill_cipher (
    input  logic        clk,
    input  logic        reset,
    input  logic        start,
    input  logic [14:0] plaintext,   // 3 letters, 5 bits each
    input  logic [44:0] key,         // 9 elements, 5 bits each
    output logic [14:0] ciphertext,  // 3 letters, 5 bits each
    output logic        done
);

    logic [4:0] P0, P1, P2;
    logic [4:0] K00, K01, K02;
    logic [4:0] K10, K11, K12;
    logic [4:0] K20, K21, K22;

    // Each row accumulates three mod-26 terms (max 25*3 = 75) -> 7 bits.
    logic [6:0] temp0, temp1, temp2;
    logic [4:0] C0_reg, C1_reg, C2_reg;

    typedef enum logic [1:0] {
        IDLE        = 2'b00,
        COMPUTE     = 2'b01,
        COMPUTE_MOD = 2'b10,
        DONE        = 2'b11
    } state_t;

    state_t current_state, next_state;

    assign P0 = plaintext[14:10];
    assign P1 = plaintext[9:5];
    assign P2 = plaintext[4:0];

    assign K00 = key[44:40];
    assign K01 = key[39:35];
    assign K02 = key[34:30];
    assign K10 = key[29:25];
    assign K11 = key[24:20];
    assign K12 = key[19:15];
    assign K20 = key[14:10];
    assign K21 = key[9:5];
    assign K22 = key[4:0];

    // Products of two 5-bit letters need 10 bits (max 25*25 = 625).
    logic [9:0] prod00, prod01, prod02;
    logic [9:0] prod10, prod11, prod12;
    logic [9:0] prod20, prod21, prod22;

    assign prod00 = {5'b0, K00} * {5'b0, P0};
    assign prod01 = {5'b0, K01} * {5'b0, P1};
    assign prod02 = {5'b0, K02} * {5'b0, P2};
    assign prod10 = {5'b0, K10} * {5'b0, P0};
    assign prod11 = {5'b0, K11} * {5'b0, P1};
    assign prod12 = {5'b0, K12} * {5'b0, P2};
    assign prod20 = {5'b0, K20} * {5'b0, P0};
    assign prod21 = {5'b0, K21} * {5'b0, P1};
    assign prod22 = {5'b0, K22} * {5'b0, P2};

    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always_comb begin
        next_state = current_state;
        done       = 1'b0;

        case (current_state)
            IDLE: begin
                if (start)
                    next_state = COMPUTE;
            end
            COMPUTE: begin
                next_state = COMPUTE_MOD;
            end
            COMPUTE_MOD: begin
                next_state = DONE;
            end
            DONE: begin
                done       = 1'b1;
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            temp0  <= 7'b0;
            temp1  <= 7'b0;
            temp2  <= 7'b0;
            C0_reg <= 5'b0;
            C1_reg <= 5'b0;
            C2_reg <= 5'b0;
        end
        else begin
            case (current_state)
                COMPUTE: begin
                    temp0 <= 7'((prod00 % 10'd26) + (prod01 % 10'd26) + (prod02 % 10'd26));
                    temp1 <= 7'((prod10 % 10'd26) + (prod11 % 10'd26) + (prod12 % 10'd26));
                    temp2 <= 7'((prod20 % 10'd26) + (prod21 % 10'd26) + (prod22 % 10'd26));
                end
                COMPUTE_MOD: begin
                    C0_reg <= 5'(temp0 % 7'd26);
                    C1_reg <= 5'(temp1 % 7'd26);
                    C2_reg <= 5'(temp2 % 7'd26);
                end
                default: begin
                    temp0  <= 7'b0;
                    temp1  <= 7'b0;
                    temp2  <= 7'b0;
                    C0_reg <= 5'b0;
                    C1_reg <= 5'b0;
                    C2_reg <= 5'b0;
                end
            endcase
        end
    end

    assign ciphertext = {C0_reg, C1_reg, C2_reg};

endmodule

module hmac_reg_interface #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  write_en,
    input  logic                  read_en,
    input  logic [ADDR_WIDTH-1:0] addr,
    input  logic [DATA_WIDTH-1:0] wdata,
    input  logic                  i_wait_en,
    output logic [DATA_WIDTH-1:0] rdata,
    output logic                  hmac_valid,
    output logic                  hmac_key_error
);

    // Number of registers
    localparam NUM_REGS = 1 << ADDR_WIDTH;
    localparam [DATA_WIDTH-1:0] XOR = {(DATA_WIDTH/2){2'b01}};

    // FSM States
    localparam [2:0] IDLE      = 3'b000;
    localparam [2:0] ANALYZE   = 3'b001;
    localparam [2:0] XOR_DATA  = 3'b010;
    localparam [2:0] WRITE     = 3'b011;
    localparam [2:0] LOST      = 3'b100;
    localparam [2:0] CHECK_KEY = 3'b101;
    localparam [2:0] TRIG_WAIT = 3'b110;

    logic [2:0] current_state, next_state;

    // Registers
    logic [DATA_WIDTH-1:0] registers [NUM_REGS-1:0];

    // HMAC data
    logic [DATA_WIDTH-1:0] hmac_key;
    logic [DATA_WIDTH-1:0] hmac_data;

    logic [DATA_WIDTH-1:0] xor_data;

    integer i;

    //------------------------------------------------------------------
    // XOR logic (combinational): XOR every 2 bits of wdata with 2'b01
    //------------------------------------------------------------------
    assign xor_data = wdata ^ XOR;

    // MSB of wdata (hoisted so parameter-indexed selects stay out of
    // procedural blocks) and the value written to a register.
    wire                  wdata_msb = wdata[DATA_WIDTH-1];
    wire [DATA_WIDTH-1:0] wr_value  = wdata_msb ? xor_data : wdata;

    //------------------------------------------------------------------
    // Key analysis (combinational): 2 MSB and 2 LSB of key must be zero
    //------------------------------------------------------------------
    logic key_valid;
    assign key_valid = (hmac_key[DATA_WIDTH-1] == 1'b0) &&
                       (hmac_key[DATA_WIDTH-2] == 1'b0) &&
                       (hmac_key[1] == 1'b0) &&
                       (hmac_key[0] == 1'b0);
    assign hmac_key_error = ~key_valid;

    //------------------------------------------------------------------
    // FSM next-state logic (combinational)
    //------------------------------------------------------------------
    always_comb begin
        next_state = current_state;
        case (current_state)
            IDLE:      next_state = write_en ? ANALYZE : IDLE;
            ANALYZE:   next_state = wdata_msb ? XOR_DATA : WRITE;
            XOR_DATA:  next_state = WRITE;
            WRITE:     next_state = write_en ? IDLE : LOST;
            LOST:      next_state = read_en ? CHECK_KEY : LOST;
            CHECK_KEY: next_state = key_valid ? TRIG_WAIT : WRITE;
            TRIG_WAIT: begin
                if (i_wait_en)
                    next_state = TRIG_WAIT;
                else if ((hmac_data != {DATA_WIDTH{1'b0}}) &&
                         (hmac_key  != {DATA_WIDTH{1'b0}}))
                    next_state = IDLE;
                else
                    next_state = WRITE;
            end
            default:   next_state = IDLE;
        endcase
    end

    //------------------------------------------------------------------
    // FSM state register (sequential)
    //------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    //------------------------------------------------------------------
    // Write logic + hmac_valid + special key/data registers
    //  - Processed data is written during the WRITE state.
    //  - MSB of wdata selects XOR-processed data vs raw data.
    //  - addr 0 -> hmac_key, addr 1 -> hmac_data (special handling).
    //  - hmac_valid asserted only during the WRITE state.
    //------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hmac_key   <= {DATA_WIDTH{1'b0}};
            hmac_data  <= {DATA_WIDTH{1'b0}};
            hmac_valid <= 1'b0;
            for (i = 0; i < NUM_REGS; i = i + 1)
                registers[i] <= {DATA_WIDTH{1'b0}};
        end else begin
            hmac_valid <= (next_state == WRITE);
            if (current_state == WRITE) begin
                registers[addr] <= wr_value;
                if (addr == 0)
                    hmac_key  <= wr_value;
                else if (addr == 1)
                    hmac_data <= wr_value;
            end
        end
    end

    //------------------------------------------------------------------
    // Read logic (1-cycle latency, independent of FSM):
    //  - read when read_en, not writing, and FSM not in WRITE state.
    //  - addr 0 -> hmac_key, addr 1 -> hmac_data (special handling).
    //------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            rdata <= {DATA_WIDTH{1'b0}};
        else if (read_en && !write_en && (current_state != WRITE)) begin
            if (addr == 0)
                rdata <= hmac_key;
            else if (addr == 1)
                rdata <= hmac_data;
            else
                rdata <= registers[addr];
        end
    end

endmodule

module huffman_encoder(
    input wire clk,
    input wire reset,
    input wire data_valid,
    input wire [3:0] data_in,
    input wire [1:0] data_priority,
    input wire update_enable,
    input wire [3:0] config_symbol,
    input wire [6:0] config_code,
    input wire [2:0] config_length,
    output reg [6:0] huffman_code_out,
    output reg code_valid,
    output reg error_flag
);

    // Memory Interfaces for code and queue storage
    wire [6:0] huffman_code;
    wire [2:0] code_length;
    wire [3:0] queue_high_out, queue_medium_out, queue_low_out;

    // FSM state encoding
    localparam IDLE         = 3'd0;
    localparam PREPARE      = 3'd1;
    localparam CHECK_UPDATE = 3'd2;
    localparam ENCODE       = 3'd3;
    localparam OUTPUT       = 3'd4;
    localparam HANDLE_ERROR = 3'd5;
    localparam UPDATE_TABLE = 3'd6;

    reg [2:0] state;

    // Latched request context
    reg [3:0] symbol_reg;      // symbol currently being encoded
    reg [3:0] cfg_sym;         // latched config symbol
    reg [6:0] cfg_code;        // latched config code
    reg [2:0] cfg_len;         // latched config length

    // Priority queue write pointers
    reg [3:0] wp_high, wp_medium, wp_low;

    // Configuration validity: length must be non-zero and the code must
    // fit within the declared number of bits.
    wire config_ok = (cfg_len != 3'd0) && ((cfg_code >> cfg_len) == 7'd0);

    // Priority queue write enables (written when data_valid and the
    // matching priority level is asserted).
    wire qh_we = data_valid & (data_priority == 2'b10);
    wire qm_we = data_valid & (data_priority == 2'b01);
    wire ql_we = data_valid & (data_priority == 2'b00);

    // Shared address/we for the Huffman table and code-length RAMs.
    //  - During UPDATE_TABLE : write config at config symbol.
    //  - Otherwise           : read the symbol being encoded.
    wire [3:0] mem_addr = (state == UPDATE_TABLE) ? cfg_sym : symbol_reg;
    wire       mem_we   = (state == UPDATE_TABLE);

    // Huffman code table RAM (stores 7-bit codes, indexed by 4-bit symbol)
    single_port_ram #(.DATA_WIDTH(7), .ADDR_WIDTH(4)) huffman_table (
        .clk (clk),
        .we  (mem_we),
        .addr(mem_addr),
        .din (cfg_code),
        .dout(huffman_code)
    );

    // Code length RAM (stores 3-bit lengths, indexed by 4-bit symbol)
    single_port_ram #(.DATA_WIDTH(3), .ADDR_WIDTH(4)) code_len_table (
        .clk (clk),
        .we  (mem_we),
        .addr(mem_addr),
        .din (cfg_len),
        .dout(code_length)
    );

    // Priority queues (store 4-bit symbols)
    single_port_ram #(.DATA_WIDTH(4), .ADDR_WIDTH(4)) queue_high (
        .clk (clk),
        .we  (qh_we),
        .addr(wp_high),
        .din (data_in),
        .dout(queue_high_out)
    );

    single_port_ram #(.DATA_WIDTH(4), .ADDR_WIDTH(4)) queue_medium (
        .clk (clk),
        .we  (qm_we),
        .addr(wp_medium),
        .din (data_in),
        .dout(queue_medium_out)
    );

    single_port_ram #(.DATA_WIDTH(4), .ADDR_WIDTH(4)) queue_low (
        .clk (clk),
        .we  (ql_we),
        .addr(wp_low),
        .din (data_in),
        .dout(queue_low_out)
    );

    //------------------------------------------------------------------
    // Main FSM (asynchronous, active-high reset)
    //------------------------------------------------------------------
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state            <= IDLE;
            huffman_code_out <= 7'd0;
            code_valid       <= 1'b0;
            error_flag       <= 1'b0;
            symbol_reg       <= 4'd0;
            cfg_sym          <= 4'd0;
            cfg_code         <= 7'd0;
            cfg_len          <= 3'd0;
            wp_high          <= 4'd0;
            wp_medium        <= 4'd0;
            wp_low           <= 4'd0;
        end else begin
            // Default single-cycle pulses
            code_valid <= 1'b0;
            error_flag <= 1'b0;

            // Priority queue pointer maintenance (independent of FSM)
            if (qh_we) wp_high   <= wp_high   + 4'd1;
            if (qm_we) wp_medium <= wp_medium + 4'd1;
            if (ql_we) wp_low    <= wp_low    + 4'd1;

            case (state)
                IDLE: begin
                    if (update_enable) begin
                        cfg_sym  <= config_symbol;
                        cfg_code <= config_code;
                        cfg_len  <= config_length;
                        state    <= CHECK_UPDATE;
                    end else if (data_valid) begin
                        symbol_reg <= data_in;
                        state      <= PREPARE;
                    end else begin
                        state <= IDLE;
                    end
                end

                PREPARE: begin
                    // table read address is driven with symbol_reg;
                    // the synchronous RAM captures the code this edge.
                    state <= ENCODE;
                end

                CHECK_UPDATE: begin
                    if (config_ok)
                        state <= UPDATE_TABLE;
                    else begin
                        error_flag <= 1'b1;
                        state      <= HANDLE_ERROR;
                    end
                end

                ENCODE: begin
                    // huffman_code is valid now; register it and assert
                    // code_valid so both are aligned during OUTPUT.
                    huffman_code_out <= huffman_code;
                    code_valid       <= 1'b1;
                    state            <= OUTPUT;
                end

                OUTPUT: begin
                    // code_valid returns low via default (single pulse).
                    state <= IDLE;
                end

                HANDLE_ERROR: begin
                    state <= IDLE;
                end

                UPDATE_TABLE: begin
                    // mem_we drives the write of cfg_code/cfg_len this edge.
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module single_port_ram #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 4
)(
    input wire clk,
    input wire we,
    input wire [ADDR_WIDTH-1:0] addr,
    input wire [DATA_WIDTH-1:0] din,
    output reg [DATA_WIDTH-1:0] dout
);

    reg [DATA_WIDTH-1:0] mem [(1<<ADDR_WIDTH)-1:0];
    integer k;

    initial begin
        dout = {DATA_WIDTH{1'b0}};
        for (k = 0; k < (1<<ADDR_WIDTH); k = k + 1)
            mem[k] = {DATA_WIDTH{1'b0}};
    end

    // Synchronous single-port RAM: 1-cycle read latency, read-first.
    always @(posedge clk) begin
        if (we)
            mem[addr] <= din;
        dout <= mem[addr];
    end

endmodule


