module instruction_cache_controller (
    input  wire        clk,                // Clock signal
    input  wire        rst,                // Reset signal

    output reg         io_mem_valid,       // Indicates that memory operation is valid
    input  wire        io_mem_ready,       // Indicates that memory is ready for the operation
    output reg  [16:0] io_mem_addr,        // Address for memory operation

    output reg         l1b_wait,           // Indicates if the L1 cache is still waiting for data
    output wire [31:0] l1b_data,           // Data output from the L1 cache
    input  wire [17:0] l1b_addr,           // Address of the L1 cache (18-bits)

    // RAM256_T0 (Tag Memory 0)
    output wire       ram256_t0_we,        // Write enable for the RAM256_T0 (Tag RAM 0)
    output wire [7:0] ram256_t0_addr,      // Address for the RAM256_T0 (Tag RAM 0)
    input  wire [7:0] ram256_t0_data,      // Data read from the RAM256_T0 (Tag RAM 0)

    // RAM256_T1 (Tag Memory 1)
    output wire       ram256_t1_we,        // Write enable for the RAM256_T1 (Tag RAM 1)
    output wire [7:0] ram256_t1_addr,      // Address for the RAM256_T1 (Tag RAM 1)
    input  wire [7:0] ram256_t1_data,      // Data read from the RAM256_T1 (Tag RAM 1)

    // RAM512_D0 (Data Memory 0)
    output wire        ram512_d0_we,       // Write enable for the RAM512_D0 (Data RAM 0)
    output wire [8:0]  ram512_d0_addr,     // Address for the RAM512_D0 (Data RAM 0)
    input  wire [15:0] ram512_d0_data,     // Data read from the RAM512_D0 (Data RAM 0)

    // RAM512_D1 (Data Memory 1)
    output wire        ram512_d1_we,       // Write enable for the RAM512_D1 (Data RAM 1)
    output wire [8:0]  ram512_d1_addr,     // Address for the RAM512_D1 (Data RAM 1)
    input  wire [15:0] ram512_d1_data      // Data read from the RAM512_D1 (Data RAM 1)
);
    wire [15:0] data_0;
    wire [15:0] data_1;

    // Unaligned access handling: data_0 is the lower half, data_1 the upper half.
    // For an aligned access (LSB = 0) the natural 32-bit word is {upper, lower};
    // for an unaligned access (LSB = 1) the two halves are swapped.
    assign data_0   = ram512_d0_data;
    assign data_1   = ram512_d1_data;
    assign l1b_data = l1b_addr[0] ? {data_0, data_1} : {data_1, data_0};

    localparam TAG_BITS = 8;
    localparam ADR_BITS = 9;

    localparam IDLE      = 3'd0,
               READMEM0  = 3'd1,
               READMEM1  = 3'd2,
               READCACHE = 3'd3;

    reg [2:0] state, next_state;
    reg [ADR_BITS-1:0] addr_0, addr_1;
    reg write_enable;

    wire [ADR_BITS-1:0] data_addr_0 = l1b_addr[17:9] + {{8{1'b0}}, l1b_addr[0]};
    wire [ADR_BITS-1:0] data_addr_1 = l1b_addr[17:9];

    wire valid_0, valid_1;
    wire [TAG_BITS-1:0] tag_0, tag_1;

    wire data_0_ready = (l1b_addr[17:9] == tag_0) && valid_0;
    wire data_1_ready = (l1b_addr[17:9] == tag_1) && valid_1;


    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            write_enable <= 1'b0;
            addr_0 <= {ADR_BITS{1'b0}};
            addr_1 <= {ADR_BITS{1'b0}};
        end else begin
            if ((state == READMEM0 || state == READMEM1) && io_mem_ready) begin
                write_enable <= 1'b1;
            end else begin
                write_enable <= 1'b0;
            end
            state <= next_state;
            addr_0 <= data_addr_0;
            addr_1 <= data_addr_1;
        end
    end

    // State machine logic + memory-request output driving
    always @(*) begin
        // Defaults
        next_state   = state;
        io_mem_valid = 1'b0;
        io_mem_addr  = {8'b0, data_addr_1};
        l1b_wait     = 1'b0;

        case (state)
            IDLE: begin
                if (data_0_ready && data_1_ready) begin
                    // Cache hit: serve the request without stalling.
                    next_state   = IDLE;
                    l1b_wait     = 1'b0;
                    io_mem_valid = 1'b0;
                end else begin
                    // Cache miss: stall the L1 and begin a memory fetch.
                    next_state   = READMEM0;
                    l1b_wait     = 1'b1;
                    io_mem_valid = 1'b0;
                end
            end

            READMEM0: begin
                // Fetch the first part of the cache line from memory.
                l1b_wait     = 1'b1;
                io_mem_valid = 1'b1;
                io_mem_addr  = {8'b0, data_addr_0};
                if (io_mem_ready)
                    next_state = READMEM1;
                else
                    next_state = READMEM0;
            end

            READMEM1: begin
                // Fetch the second part of the cache line from memory.
                l1b_wait     = 1'b1;
                io_mem_valid = 1'b1;
                io_mem_addr  = {8'b0, data_addr_1};
                if (io_mem_ready)
                    next_state = READCACHE;
                else
                    next_state = READMEM1;
            end

            READCACHE: begin
                // Fetched data is now valid in the cache; return to IDLE.
                l1b_wait     = 1'b1;
                io_mem_valid = 1'b0;
                next_state   = IDLE;
            end

            default: begin
                next_state   = IDLE;
                l1b_wait     = 1'b0;
                io_mem_valid = 1'b0;
            end
        endcase
    end

    // Data-RAM address selection and write-enable driving.
    // On a read the address is the offset derived from l1b_addr; during a
    // cache-fill (write_enable) the fetched line is stored at io_mem_addr.
    assign ram512_d0_addr = write_enable ? io_mem_addr[8:0] : data_addr_0;
    assign ram512_d1_addr = write_enable ? io_mem_addr[8:0] : data_addr_1;
    assign ram512_d0_we   = write_enable;
    assign ram512_d1_we   = write_enable;


    tag_controller tag_ctrl (
        .clk(clk),
        .rst(rst),
        .write_enable(write_enable),
        .write_addr(io_mem_addr[ADR_BITS-1:0]),
        .data_0_out({valid_0, tag_0}),
        .read_addr_0(data_addr_0[7:0]),
        .data_1_out({valid_1, tag_1}),
        .read_addr_1(data_addr_1[7:0]),
        .ram_t0_we(ram256_t0_we),
        .ram_t0_addr(ram256_t0_addr),
        .ram_t0_data(ram256_t0_data),
        .ram_t1_we(ram256_t1_we),
        .ram_t1_addr(ram256_t1_addr),
        .ram_t1_data(ram256_t1_data)
    );

endmodule


module tag_controller (
   input wire clk,                     // Clock signal
   input wire rst,                     // Reset signal

   // Port 0: Write operation (W)
   input wire       write_enable,      // Enable write operation
   input wire [8:0] write_addr,        // Write address (9 bits)

   // Port 0: Read operation for address 0 (R)
   output reg [8:0] data_0_out,        // Data output for read operation on address 0 (9 bits)
   input  wire [7:0] read_addr_0,      // Read address for tag memory 0 (8 bits)

   // Port 1: Read operation for address 1 (R)
   output reg [8:0] data_1_out,        // Data output for read operation on address 1 (9 bits)
   input  wire [7:0] read_addr_1,      // Read address for tag memory 1 (8 bits)

   // RAM256_T0 (Tag Memory 0)
   output reg       ram_t0_we,         // Write enable for the RAM256_T0 (Tag RAM 0)
   output reg [7:0] ram_t0_addr,       // Address for the RAM256_T0 (Tag RAM 0)
   input  wire [7:0] ram_t0_data,      // Data read from the RAM256_T0 (Tag RAM 0)

   // RAM256_T1 (Tag Memory 1)
   output reg       ram_t1_we,         // Write enable for the RAM256_T1 (Tag RAM 1)
   output reg [7:0] ram_t1_addr,       // Address for the RAM256_T1 (Tag RAM 1)
   input  wire [7:0] ram_t1_data       // Data read from the RAM256_T1 (Tag RAM 1)
);
   // Internal valid-bit array: one validity bit per cache-line index.
   reg [511:0] RAM;

   // Address decoding: on a write both tag blocks are addressed with the
   // write address; on a read each block uses its own read address.
   wire [7:0] tag_addr_0 = write_enable ? write_addr[7:0] : read_addr_0;
   wire [7:0] tag_addr_1 = write_enable ? write_addr[7:0] : read_addr_1;

   always @(posedge clk or posedge rst) begin
       if (rst) begin
           RAM <= 0;
       end else if (write_enable) begin
           // Mark the written cache line valid.
           RAM[write_addr[7:0]] <= 1'b1;
       end
   end

   always @(*) begin
      // Tag SRAM address decoding
      ram_t0_addr = tag_addr_0;
      ram_t1_addr = tag_addr_1;

      // Tag write enable logic
      ram_t0_we = write_enable;
      ram_t1_we = write_enable;

      // Tag and valid bit outputs: {valid_bit, 8-bit tag}
      data_0_out = {RAM[read_addr_0], ram_t0_data};
      data_1_out = {RAM[read_addr_1], ram_t1_data};
   end

endmodule

module image_rotate #(
  parameter IN_ROW     = 4                                  , // Number of rows in input matrix
  parameter IN_COL     = 4                                  , // Number of columns in input matrix
  parameter OUT_ROW    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output rows after padding
  parameter OUT_COL    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output columns after padding
  parameter DATA_WIDTH = 8                                    // Bit-width of data
) (
  input  logic [                             1:0] rotation_angle, // Rotation angle (00: 90°, 01: 180°, 10: 270°, 11: No Rotation)
  input  logic [  (IN_ROW*IN_COL*DATA_WIDTH)-1:0] image_in      , // Flattened input image
  output logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] image_out       // Flattened output image
);

  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] padded_image    ; // Padded square image
  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] transposed_image; // Transposed square image

  genvar pad_row, pad_col, trans_row, trans_col, rot_row, rot_col;

  // Padded image: copy image_in into the bottom-right portion of the square
  // OUT_ROW x OUT_COL matrix, zero-filling the top rows and left columns.
  generate
    for (pad_row = 0; pad_row < OUT_ROW; pad_row = pad_row + 1) begin: pad_row_block
      for (pad_col = 0; pad_col < OUT_COL; pad_col = pad_col + 1) begin: pad_col_block
        if ((pad_row >= (OUT_ROW - IN_ROW)) && (pad_col >= (OUT_COL - IN_COL))) begin: pad_copy
          assign padded_image[(pad_row*OUT_COL + pad_col)*DATA_WIDTH +: DATA_WIDTH] =
                 image_in[((pad_row-(OUT_ROW-IN_ROW))*IN_COL + (pad_col-(OUT_COL-IN_COL)))*DATA_WIDTH +: DATA_WIDTH];
        end else begin: pad_zero
          assign padded_image[(pad_row*OUT_COL + pad_col)*DATA_WIDTH +: DATA_WIDTH] = {DATA_WIDTH{1'b0}};
        end
      end
    end
  endgenerate


  generate
    for (trans_row = 0; trans_row < OUT_ROW; trans_row++) begin: trans_row_block
      for (trans_col = 0; trans_col < OUT_COL; trans_col++) begin: trans_col_block
        // transposed_image[trans_row][trans_col] = padded_image[trans_col][trans_row]
        assign transposed_image[(trans_row*OUT_COL + trans_col)*DATA_WIDTH +: DATA_WIDTH] =
               padded_image[(trans_col*OUT_COL + trans_row)*DATA_WIDTH +: DATA_WIDTH];
      end
    end
  endgenerate



  // Output logic: select rotated result per element based on rotation_angle.
  //   00 (90° CW)  : transpose then reverse each row  -> transposed[r][OUT_COL-1-c]
  //   01 (180° CW) : reverse rows and columns         -> padded[OUT_ROW-1-r][OUT_COL-1-c]
  //   10 (270° CW) : transpose then reverse columns   -> transposed[OUT_ROW-1-r][c]
  //   11 (no rot)  : pass through padded              -> padded[r][c]
  generate
    for (rot_row = 0; rot_row < OUT_ROW; rot_row = rot_row + 1) begin: rot_row_block
      for (rot_col = 0; rot_col < OUT_COL; rot_col = rot_col + 1) begin: rot_col_block
        assign image_out[(rot_row*OUT_COL + rot_col)*DATA_WIDTH +: DATA_WIDTH] =
          (rotation_angle == 2'b00) ? transposed_image[(rot_row*OUT_COL + (OUT_COL-1-rot_col))*DATA_WIDTH +: DATA_WIDTH] :
          (rotation_angle == 2'b01) ? padded_image[((OUT_ROW-1-rot_row)*OUT_COL + (OUT_COL-1-rot_col))*DATA_WIDTH +: DATA_WIDTH] :
          (rotation_angle == 2'b10) ? transposed_image[((OUT_ROW-1-rot_row)*OUT_COL + rot_col)*DATA_WIDTH +: DATA_WIDTH] :
                                      padded_image[(rot_row*OUT_COL + rot_col)*DATA_WIDTH +: DATA_WIDTH];
      end
    end
  endgenerate

endmodule


