module image_rotate #(
  parameter IN_ROW     = 4,                                   // Number of rows in input image
  parameter IN_COL     = 4,                                   // Number of columns in input image
  parameter OUT_ROW    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output rows after padding
  parameter OUT_COL    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output columns after padding
  parameter DATA_WIDTH = 8                                    // Bit-width of data
) (
  input  logic                                    clk,                // Clock Signal
  input  logic                                    srst,               // Active-High Synchronous Reset
  input  logic                                    valid_in,           // Indicates valid input image
  input  logic                       [       1:0] rotation_angle,     // Rotation angle (00: 90°, 01: 180°, 10: 270°, 11: No Rotation)
  input  logic   [(IN_ROW*IN_COL*DATA_WIDTH)-1:0] image_in,           // Flattened input image
  output logic                                    valid_out,          // Indicates valid output image
  output logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] image_out           // Flattened output image
);

  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] padded_image, padded_image_reg, padded_image_reg2, padded_image_reg3; // Padded image stored in registers
  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] transposed_image, transposed_image_reg; // Transposed image stored in registers
  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] rotated_image, rotated_image_reg;        // Final rotated image (latency buffer)

  logic [5:0] valid_out_reg;

  always_ff @(posedge clk)
    if (srst)
      {valid_out, valid_out_reg} <= '0;
    else
      {valid_out, valid_out_reg} <= {valid_out_reg, valid_in};

  // Step 1: Pad the input image into a square image (Sequentially Stored)
  always_ff @(posedge clk) begin
    if (srst) begin
      padded_image <= '0;
    end else begin
      for (int pad_row = 0; pad_row < OUT_ROW; pad_row++) begin
        for (int pad_col = 0; pad_col < OUT_COL; pad_col++) begin
          if ((pad_row < IN_ROW) && (pad_col < IN_COL)) begin
            // Copy input data into padded_image
            padded_image[(pad_row * OUT_COL + pad_col) * DATA_WIDTH +: DATA_WIDTH] <= image_in[(pad_row * IN_COL + pad_col) * DATA_WIDTH +: DATA_WIDTH];
          end else begin
            // Fill remaining positions with zeros
            padded_image[(pad_row * OUT_COL + pad_col) * DATA_WIDTH +: DATA_WIDTH] <= '0;
          end
        end
      end
    end
  end

  always_ff @(posedge clk) begin
    padded_image_reg <= padded_image;
    padded_image_reg2 <= padded_image_reg;
    padded_image_reg3 <= padded_image_reg2;
  end

  // Step 2: Transpose the padded image (Stored in Registers)
  always_ff @(posedge clk) begin
    if (srst) begin
      transposed_image <= '0;
    end else begin
      for (int trans_row = 0; trans_row < OUT_ROW; trans_row++) begin
        for (int trans_col = 0; trans_col < OUT_COL; trans_col++) begin
          // Transpose logic: Swap rows and columns
          transposed_image[(trans_col * OUT_ROW + trans_row) * DATA_WIDTH +: DATA_WIDTH] <= padded_image_reg[(trans_row * OUT_COL + trans_col) * DATA_WIDTH +: DATA_WIDTH];
        end
      end
    end
  end

  always_ff @(posedge clk) begin
    transposed_image_reg <= transposed_image;
  end

  // Step 3: Apply rotation logic with additional latency buffer
  always_ff @(posedge clk) begin
    if (srst) begin
      rotated_image <= '0;
    end else begin
      for (int rot_row = 0; rot_row < OUT_ROW; rot_row++) begin
        for (int rot_col = 0; rot_col < OUT_COL; rot_col++) begin
          case (rotation_angle)
            // 90° Clockwise: Transpose + Reverse Rows
            2'b00: rotated_image[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH] <= transposed_image_reg[(rot_row * OUT_COL + (OUT_COL-1-rot_col)) * DATA_WIDTH +: DATA_WIDTH];

            // 180° Clockwise: Reverse Rows and Columns
            2'b01: rotated_image[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH] <= padded_image_reg3[((OUT_ROW-1-rot_row) * OUT_COL + (OUT_COL-1-rot_col)) * DATA_WIDTH +: DATA_WIDTH];

            // 270° Clockwise: Transpose + Reverse Columns
            2'b10: rotated_image[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH] <= transposed_image_reg[((OUT_ROW-1-rot_row) * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH];

            // No Rotation (Pass-through)
            2'b11: rotated_image[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH] <= padded_image_reg3[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH];
          endcase
        end
      end
    end
  end

  always_ff @(posedge clk) begin
    rotated_image_reg <= rotated_image;
  end

  // Step 4: Output Register for Added Latency
  always_ff @(posedge clk) begin
    if (srst) begin
      image_out <= '0;
    end else begin
      image_out <= rotated_image_reg;
    end
  end

endmodule

module image_rotate #(
  parameter IN_ROW     = 4,                                   // Number of rows in input image
  parameter IN_COL     = 4,                                   // Number of columns in input image
  parameter OUT_ROW    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output rows after padding
  parameter OUT_COL    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output columns after padding
  parameter DATA_WIDTH = 8                                    // Bit-width of data
) (
  input  logic                                    clk,                // Clock Signal
  input  logic                                    srst,               // Active-High Synchronous Reset
  input  logic                                    valid_in,           // Indicates valid input image
  input  logic                       [       1:0] rotation_angle,     // Rotation angle (00: 90°, 01: 180°, 10: 270°, 11: No Rotation)
  input  logic   [(IN_ROW*IN_COL*DATA_WIDTH)-1:0] image_in,           // Flattened input image
  output logic                                    valid_out,          // Indicates valid output image
  output logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] image_out           // Flattened output image
);

  // -------------------------------------------------------------------------
  // Area + latency optimization (functionally equivalent to the reference).
  //
  // The reference design is a pure byte-permutation of a zero-padded square
  // image selected by rotation_angle.  It spent 7 pipeline stages (latency 7)
  // and 9 full-width registers moving the same data around.  All rotations can
  // be expressed as a single combinational permutation of the padded image, so
  // the pipeline is collapsed to 4 stages (latency reduced by exactly 3) using
  // only 4 full-width registers -> well over a 25% cell reduction.
  // -------------------------------------------------------------------------

  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] padded_image;      // Stage 1: zero-padded square image
  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] padded_image_reg;  // Stage 2: alignment register
  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] rotated_image;     // Stage 3: permuted (rotated) image

  logic [1:0] rotation_angle_reg;   // Stage 1: capture angle alongside its image
  logic [1:0] rotation_angle_reg2;  // Stage 2: align angle with padded_image_reg

  // Valid pipeline: latency 4 (reduced by 3 from the reference latency of 7)
  logic [2:0] valid_pipe;
  always_ff @(posedge clk)
    if (srst)
      {valid_out, valid_pipe} <= '0;
    else
      {valid_out, valid_pipe} <= {valid_pipe, valid_in};

  // Stage 1: Pad the input image into a square image + capture rotation angle
  always_ff @(posedge clk) begin
    if (srst) begin
      padded_image       <= '0;
      rotation_angle_reg <= '0;
    end else begin
      rotation_angle_reg <= rotation_angle;
      for (int pad_row = 0; pad_row < OUT_ROW; pad_row++) begin
        for (int pad_col = 0; pad_col < OUT_COL; pad_col++) begin
          if ((pad_row < IN_ROW) && (pad_col < IN_COL))
            padded_image[(pad_row * OUT_COL + pad_col) * DATA_WIDTH +: DATA_WIDTH] <=
              image_in[(pad_row * IN_COL + pad_col) * DATA_WIDTH +: DATA_WIDTH];
          else
            padded_image[(pad_row * OUT_COL + pad_col) * DATA_WIDTH +: DATA_WIDTH] <= '0;
        end
      end
    end
  end

  // Stage 2: Alignment register (keeps angle synchronized with its image)
  always_ff @(posedge clk) begin
    if (srst) begin
      padded_image_reg    <= '0;
      rotation_angle_reg2 <= '0;
    end else begin
      padded_image_reg    <= padded_image;
      rotation_angle_reg2 <= rotation_angle_reg;
    end
  end

  // Stage 3: Apply rotation as a single combinational permutation, registered.
  //   90°  (00): rot[r][c] = pad[N-1-c][r]
  //   180° (01): rot[r][c] = pad[N-1-r][N-1-c]
  //   270° (10): rot[r][c] = pad[c][N-1-r]
  //   none (11): rot[r][c] = pad[r][c]
  // (N = OUT_ROW = OUT_COL; flat index = row*OUT_COL + col)
  always_ff @(posedge clk) begin
    if (srst) begin
      rotated_image <= '0;
    end else begin
      for (int rot_row = 0; rot_row < OUT_ROW; rot_row++) begin
        for (int rot_col = 0; rot_col < OUT_COL; rot_col++) begin
          case (rotation_angle_reg2)
            // 90° Clockwise: Transpose + Reverse Rows
            2'b00: rotated_image[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH] <=
                     padded_image_reg[((OUT_COL-1-rot_col) * OUT_COL + rot_row) * DATA_WIDTH +: DATA_WIDTH];

            // 180° Clockwise: Reverse Rows and Columns
            2'b01: rotated_image[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH] <=
                     padded_image_reg[((OUT_ROW-1-rot_row) * OUT_COL + (OUT_COL-1-rot_col)) * DATA_WIDTH +: DATA_WIDTH];

            // 270° Clockwise: Transpose + Reverse Columns
            2'b10: rotated_image[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH] <=
                     padded_image_reg[(rot_col * OUT_COL + (OUT_ROW-1-rot_row)) * DATA_WIDTH +: DATA_WIDTH];

            // No Rotation (Pass-through)
            2'b11: rotated_image[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH] <=
                     padded_image_reg[(rot_row * OUT_COL + rot_col) * DATA_WIDTH +: DATA_WIDTH];
          endcase
        end
      end
    end
  end

  // Stage 4: Output register
  always_ff @(posedge clk) begin
    if (srst)
      image_out <= '0;
    else
      image_out <= rotated_image;
  end

endmodule

module image_stego #(
  parameter row = 2,
  parameter col = 2
)(
  input  [(row*col*8)-1:0] img_in,
  input  [(row*col*4)-1:0] data_in,
  input  [1:0]             bpp,
  output [(row*col*8)-1:0] img_out
);

  genvar i;
  generate
    for(i = 0; i < row*col; i++) begin
      assign img_out[(i*8)+7:(i*8)] = (bpp[1] == 1'b0)
                                      ? (bpp[0] == 1'b0
                                         ? {img_in[(i*8)+7 : (i*8)+1], data_in[i]}
                                         : {img_in[(i*8)+7 : (i*8)+2], data_in[(2*i)+1], data_in[2*i]})
                                      : (bpp[0] == 1'b0
                                         ? {img_in[(i*8)+7 : (i*8)+3], data_in[(3*i)+2], data_in[(3*i)+1], data_in[3*i]}
                                         : {img_in[(i*8)+7 : (i*8)+4], data_in[(4*i)+3], data_in[(4*i)+2], data_in[(4*i)+1], data_in[4*i]});
    end
  endgenerate

endmodule

module interrupt_controller
#(
    parameter NUM_INTERRUPTS = 4,
    parameter ADDR_WIDTH = 8)
(
    input  logic                              clk,
    input  logic                              rst_n,
    input  logic [NUM_INTERRUPTS-1:0]         interrupt_requests,
    output logic [NUM_INTERRUPTS-1:0]         interrupt_service,
    output logic                              cpu_interrupt,
    input  logic                              cpu_ack,
    output logic [$clog2(NUM_INTERRUPTS)-1:0] interrupt_idx,
    output logic [ADDR_WIDTH-1:0]             interrupt_vector,
    input  logic [NUM_INTERRUPTS-1:0]         priority_map_value [NUM_INTERRUPTS-1:0],
    input  logic                              priority_map_update,
    input  logic [ADDR_WIDTH-1:0]             vector_table_value [NUM_INTERRUPTS-1:0],
    input  logic                              vector_table_update,
    input  logic [NUM_INTERRUPTS-1:0]         interrupt_mask_value,
    input  logic                              interrupt_mask_update
);

    logic [NUM_INTERRUPTS-1:0] priority_mask;
    logic [NUM_INTERRUPTS-1:0] pending_interrupts;
    logic [NUM_INTERRUPTS-1:0] interrupt_mask;

    // Internal storage for the priority map and vector table.
    logic [NUM_INTERRUPTS-1:0] priority_map  [NUM_INTERRUPTS-1:0];
    logic [ADDR_WIDTH-1:0]     vector_table  [NUM_INTERRUPTS-1:0];

    // Synchronized request capture (feature 5).
    logic [NUM_INTERRUPTS-1:0] sync_requests;

    // Combinational priority selection.
    logic                              found;
    logic [$clog2(NUM_INTERRUPTS)-1:0] sel_idx;
    logic [NUM_INTERRUPTS-1:0]         sel_pri;
    logic [NUM_INTERRUPTS-1:0]         eligible;

    integer ci;
    integer ri;

    // Highest priority = lowest value in the priority map, among pending,
    // unmasked interrupts. Ties break to the lowest index.
    always_comb begin
        eligible = pending_interrupts & ~interrupt_mask;
        found    = 1'b0;
        sel_idx  = '0;
        sel_pri  = {NUM_INTERRUPTS{1'b1}};
        for (ci = 0; ci < NUM_INTERRUPTS; ci = ci + 1) begin
            if (eligible[ci] && (!found || (priority_map[ci] < sel_pri))) begin
                found   = 1'b1;
                sel_idx = ci;
                sel_pri = priority_map[ci];
            end
        end
    end

    assign priority_mask = eligible;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (ri = 0; ri < NUM_INTERRUPTS; ri = ri + 1) begin
                priority_map[ri] <= ri[NUM_INTERRUPTS-1:0];   // sequential default
                vector_table[ri] <= ri * 4;                   // multiples of 4
            end
            interrupt_mask     <= '0;
            pending_interrupts <= '0;
            interrupt_service  <= '0;
            cpu_interrupt      <= 1'b0;
            interrupt_vector   <= '0;
            interrupt_idx      <= '0;
            sync_requests      <= '0;
        end else begin
            // Synchronize incoming requests.
            sync_requests <= interrupt_requests;

            // Dynamic updates.
            if (priority_map_update)
