        next_interrupt_id = 4'd0;
        found             = 1'b0;
        for (i = 0; i < 10; i = i + 1) begin
            if (pending_interrupts[i] &&
                (!found || (effective_priority[i] > max_priority))) begin
                max_priority      = effective_priority[i];
                next_interrupt_id = i[3:0];
                found             = 1'b1;
            end
        end
    end

    // ------------------------------------------------------------------
    // Starvation detection.
    // ------------------------------------------------------------------
    always @(*) begin
        any_starved = 1'b0;
        for (i = 0; i < 10; i = i + 1)
