    input  logic                      pclk,
    input  logic                      presetn,
    input  logic                      psel,
    input  logic                      penable,
    input  logic                      pwrite,
    input  logic [ADDR_WIDTH-1:0]     paddr,
    input  logic [31:0]               pwdata,
    output logic [31:0]               prdata,
    output logic                      pready
);

    localparam int IDX_WIDTH = $clog2(NUM_INTERRUPTS);

    // Register address map (word indices)
    localparam [7:0] REG_PRIORITY_MAP   = 8'h0;
    localparam [7:0] REG_INTERRUPT_MASK = 8'h1;
    localparam [7:0] REG_VECTOR_TABLE   = 8'h2;
    localparam [7:0] REG_PENDING        = 8'h3;
    localparam [7:0] REG_CURRENT_INT    = 8'h4;

    // Internal registers
    logic [NUM_INTERRUPTS-1:0] interrupt_mask;
    logic servicing;
    logic [NUM_INTERRUPTS-1:0] pending_interrupts;

    logic [31:0]           priority_map [NUM_INTERRUPTS];
    logic [ADDR_WIDTH-1:0] vector_table [NUM_INTERRUPTS];

    logic [IDX_WIDTH-1:0]  current_interrupt;

    // Request synchronizer (into clk domain)
