    logic [IDX_WIDTH-1:0]      cur_meta, cur_sync;
    logic                      serv_meta, serv_sync;

    // ------------------------------------------------------------------
    // Priority arbitration (combinational, clk domain)
    // Selects the pending & enabled interrupt with the highest priority
    // value; ties broken toward the higher index.
    // ------------------------------------------------------------------
    logic [NUM_INTERRUPTS-1:0] masked_pending;
    logic [IDX_WIDTH-1:0]      sel_idx;
    logic                      sel_found;
    logic [31:0]               best_prio;

    always_comb begin
        masked_pending = pending_interrupts & interrupt_mask;
        sel_idx   = '0;
        sel_found = 1'b0;
        best_prio = 32'd0;
        for (int i = 0; i < NUM_INTERRUPTS; i++) begin
            if (masked_pending[i]) begin
                if (!sel_found || (priority_map[i] >= best_prio)) begin
                    best_prio = priority_map[i];
                    sel_idx   = i[IDX_WIDTH-1:0];
                    sel_found = 1'b1;
                end
            end
        end
    end

    // ------------------------------------------------------------------
    // Interrupt processing / servicing FSM (clk domain)
    // ------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pending_interrupts <= '0;
            servicing          <= 1'b0;
            cpu_interrupt      <= 1'b0;
            interrupt_service  <= '0;
            current_interrupt  <= '1;
            interrupt_idx      <= '1;
            interrupt_vector   <= '0;
            req_meta           <= '0;
            req_sync           <= '0;
        end else begin
            // Two-flop synchronizer for external requests
            req_meta <= interrupt_requests;
            req_sync <= req_meta;

            if (servicing && cpu_ack) begin
                // Clear the serviced interrupt, latch any new ones
                pending_interrupts <= (pending_interrupts | (req_sync & interrupt_mask))
