    // ------------------------------------------------------------------
    // APB register file writes + CDC synchronizers (pclk domain)
    // ------------------------------------------------------------------
    always_ff @(posedge pclk or negedge presetn) begin
        if (!presetn) begin
            for (int i = 0; i < NUM_INTERRUPTS; i++) begin
                priority_map[i] <= i[31:0];
                vector_table[i] <= (i * 4);
            end
            interrupt_mask <= '1;
            pending_meta   <= '0;
            pending_sync   <= '0;
            cur_meta       <= '1;
            cur_sync       <= '1;
            serv_meta      <= 1'b0;
            serv_sync      <= 1'b0;
        end else begin
            // CDC: sample clk-domain status into pclk domain
            pending_meta <= pending_interrupts;
            pending_sync <= pending_meta;
            cur_meta     <= current_interrupt;
            cur_sync     <= cur_meta;
            serv_meta    <= servicing;
            serv_sync    <= serv_meta;

            // APB writes complete in the ACCESS phase (no wait states)
            if (psel && penable && pwrite) begin
                case (paddr)
                    REG_PRIORITY_MAP: begin
                        if (pwdata[7:0] < NUM_INTERRUPTS)
                            priority_map[pwdata[7:0]] <= pwdata[31:8];
                    end
                    REG_INTERRUPT_MASK: begin
                        interrupt_mask <= pwdata[NUM_INTERRUPTS-1:0];
                    end
                    REG_VECTOR_TABLE: begin
                        if (pwdata[7:0] < NUM_INTERRUPTS)
                            vector_table[pwdata[7:0]] <= pwdata[8 +: ADDR_WIDTH];
                    end
                    default: ;
                endcase
            end
        end
    end

    // ------------------------------------------------------------------
    // APB read data (combinational, single-cycle access)
    // ------------------------------------------------------------------
    always_comb begin
        prdata = 32'd0;
        if (psel && penable && !pwrite) begin
            case (paddr)
                REG_PENDING: begin
                    prdata[NUM_INTERRUPTS-1:0] = pending_sync;
                end
                REG_CURRENT_INT: begin
                    if (serv_sync)
                        prdata[IDX_WIDTH-1:0] = cur_sync;
                    else
                        prdata = 32'hFFFFFFFF;
                end
                REG_INTERRUPT_MASK: begin
                    prdata[NUM_INTERRUPTS-1:0] = interrupt_mask;
                end
                default: prdata = 32'd0;
            endcase
        end
    end

    // APB ready: asserted in the same cycle as a valid access (no wait states)
    assign pready = presetn & psel & penable;

endmodule


