module ir_receiver (
    input  logic        reset_in,       // Active HIGH reset
    input  logic        clk_in,         // System clock (100 KHz, 10us)
    input  logic        ir_signal_in,   // Input signal (IR)
    output logic [11:0] ir_frame_out,   // Decoded 12-bit frame
    output logic        ir_frame_valid  // Indicates validity of the decoded frame
);

    typedef enum logic [1:0] {idle, start, decoding, finish} ir_state;
    ir_state present_state, next_state;

    logic started;
    logic decoded;
    logic failed;
    logic success;

    int cycle_counter;
    int bit_counter;

    logic [11:0] ir_frame_reg;
    logic stored;

    // Previous sample of the IR line for edge detection
    logic ir_prev;

    // Timing thresholds (clk_in = 100 KHz => 10 us period)
    //   0.6 ms  = 60 cycles
    //   1.2 ms  = 120 cycles
    //   2.4 ms  = 240 cycles
    // Generous windows tolerate small edge-alignment error while still
    // rejecting grossly-invalid timing.
    localparam int START_MIN = 150;
    localparam int START_MAX = 330;
    localparam int LOW_MIN   = 30;
    localparam int LOW_MAX   = 90;
    localparam int HIGH_MIN  = 30;   // shortest valid ('0') high pulse
    localparam int HIGH_MAX  = 150;  // longest  valid ('1') high pulse
    localparam int HIGH_SPLIT = 90;  // > SPLIT => bit '1', else bit '0'

    // Edge detection
    wire rising  =  ir_signal_in & ~ir_prev;
    wire falling = ~ir_signal_in &  ir_prev;

    // Pulse classification (uses the currently-accumulated cycle_counter,
    // which holds the completed-pulse duration at the edge)
    wire start_valid = (cycle_counter >= START_MIN) && (cycle_counter <= START_MAX);
    wire low_valid   = (cycle_counter >= LOW_MIN)   && (cycle_counter <= LOW_MAX);
    wire high_valid  = (cycle_counter >= HIGH_MIN)  && (cycle_counter <= HIGH_MAX);
    wire high_bit    = (cycle_counter >  HIGH_SPLIT);

    // State register
    always_ff @(posedge clk_in or posedge reset_in) begin
        if (reset_in)
            present_state <= idle;
        else
            present_state <= next_state;
    end

    // Next-state logic
    always_comb begin
        next_state = present_state;
        case (present_state)
            idle: begin
                // Wait for the rising edge that begins the start (HIGH) pulse
                if (rising)
                    next_state = start;
            end
            start: begin
                // Measuring the start HIGH pulse; it ends at the falling edge
                if (falling) begin
                    if (start_valid)
                        next_state = decoding;
                    else
                        next_state = idle;
                end
            end
            decoding: begin
                if (rising) begin
                    // End of a bit's LOW pulse
                    if (!low_valid)
                        next_state = idle;
                end else if (falling) begin
                    // End of a bit's HIGH pulse
                    if (!high_valid)
                        next_state = idle;
                    else if (bit_counter == 11)
                        next_state = finish;
                end
            end
            finish: begin
                next_state = idle;
            end
            default: next_state = idle;
        endcase
    end

    // Datapath: edge tracking, cycle counting, bit assembly, outputs
    always_ff @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            ir_prev        <= 1'b0;
            cycle_counter  <= 0;
            bit_counter    <= 0;
            ir_frame_reg   <= 12'd0;
            ir_frame_out   <= 12'd0;
            ir_frame_valid <= 1'b0;
            started        <= 1'b0;
            decoded        <= 1'b0;
            failed         <= 1'b0;
            success        <= 1'b0;
            stored         <= 1'b0;
        end else begin
            ir_prev        <= ir_signal_in;
            ir_frame_valid <= 1'b0;   // default; asserted for one cycle in finish

            case (present_state)
                idle: begin
                    bit_counter <= 0;
                    started     <= 1'b0;
                    if (rising)
                        cycle_counter <= 1;   // first cycle of the start pulse
                    else
                        cycle_counter <= 0;
                end

                start: begin
                    started <= 1'b1;
                    if (falling)
                        cycle_counter <= 1;   // begin measuring first LOW pulse
                    else
                        cycle_counter <= cycle_counter + 1;
                end

                decoding: begin
                    if (rising) begin
                        // LOW pulse ended -> begin HIGH pulse measurement
                        cycle_counter <= 1;
                    end else if (falling) begin
                        // HIGH pulse ended -> classify and store the bit
                        if (high_valid) begin
                            ir_frame_reg[bit_counter] <= high_bit;
                            bit_counter <= bit_counter + 1;
                        end
                        cycle_counter <= 1;   // begin next LOW pulse (if any)
                    end else begin
                        cycle_counter <= cycle_counter + 1;
                    end
                end

                finish: begin
                    // 1-cycle latency: present the decoded frame and pulse valid
                    ir_frame_out   <= ir_frame_reg;
                    ir_frame_valid <= 1'b1;
                    success        <= 1'b1;
                    decoded        <= 1'b1;
                    bit_counter    <= 0;
                    cycle_counter  <= 0;
                end

                default: begin
                    cycle_counter <= 0;
                    bit_counter   <= 0;
                end
            endcase
        end
    end

endmodule

module ir_receiver (
    input  logic        reset_in,               // Active HIGH reset
    input  logic        clk_in,                 // System clock (10 KHz, 100us)
    input  logic        ir_signal_in,           // Input signal (IR)
    output logic [6:0]  ir_function_code_out,   // Decoded output for different functions
    output logic [4:0]  ir_device_address_out,  // "00001": TV, "00010":HDMI1, "00100":USB, "01000":HDMI2, "10000": VCR
    output logic        ir_output_valid         // Indicates validity of the decoded frame
);

    typedef enum logic [2:0] {idle, start, decoding, finish, frame_space} ir_state;
    ir_state present_state, next_state;

    logic started;
    logic decoded;
    logic failed;
    logic success;
    logic frame_full;
    logic ir_frame_valid;

    int cycle_counter;
    int frame_space_counter;
    int bit_counter;
    int finish_counter;
    int low_counter;

    logic [11:0] ir_frame_reg;
    logic [11:0] ir_frame_out;
    logic stored;

    // Timing constants (clk period = 100us).
    localparam int START_THRESH       = 18;   // >1.2ms high, <2.4ms => confirm start pulse
    localparam int BIT_THRESH         = 9;    // midpoint of 0.6ms(=6) and 1.2ms(=12) high
    localparam int LOW_TIMEOUT        = 30;   // abnormal gap => incomplete frame
    localparam int FRAME_SPACE_CYCLES = 450;  // 45ms
    localparam int OUT_LATENCY        = 3;    // output latency after decode completes

    logic [6:0] func_code_w;
    logic [4:0] dev_addr_w;

    // Function-code decode table (command = frame[6:0])
    always_comb begin
        case (ir_frame_reg[6:0])
            7'd0:  func_code_w = 7'b0000001;
            7'd1:  func_code_w = 7'b0000010;
            7'd2:  func_code_w = 7'b0000011;
            7'd3:  func_code_w = 7'b0000100;
            7'd4:  func_code_w = 7'b0000101;
            7'd5:  func_code_w = 7'b0000110;
            7'd6:  func_code_w = 7'b0000111;
            7'd7:  func_code_w = 7'b0001000;
            7'd8:  func_code_w = 7'b0001001;
            7'd9:  func_code_w = 7'b0000000;
            7'd16: func_code_w = 7'b0011111;
            7'd17: func_code_w = 7'b0101111;
            7'd18: func_code_w = 7'b0111111;
            7'd19: func_code_w = 7'b1001111;
            7'd20: func_code_w = 7'b1011111;
            7'd21: func_code_w = 7'b1101111;
            7'd22: func_code_w = 7'b1111111;
            default: func_code_w = 7'b0000000;
        endcase
    end

    // Device-address decode table (address = frame[11:7])
    always_comb begin
        case (ir_frame_reg[11:7])
            5'd0: dev_addr_w = 5'b00001;
            5'd1: dev_addr_w = 5'b00010;
            5'd2: dev_addr_w = 5'b00100;
            5'd3: dev_addr_w = 5'b01000;
            5'd4: dev_addr_w = 5'b10000;
            default: dev_addr_w = 5'b00000;
        endcase
    end

    // State register
    always_ff @(posedge clk_in or posedge reset_in) begin
        if (reset_in)
            present_state <= idle;
        else
            present_state <= next_state;
    end

    // Next-state logic
    always_comb begin
        next_state = present_state;
        case (present_state)
            idle: begin
                if (ir_signal_in == 1 && started == 0)
                    next_state = start;
                else
                    next_state = idle;
            end
            start: begin
                if (ir_signal_in == 0 && started == 1)
                    next_state = decoding;
                else if (failed == 1)
                    next_state = idle;
                else
                    next_state = start;
            end
            decoding: begin
                if (decoded == 1)
                    next_state = finish;
                else if (failed == 1)
                    next_state = idle;
                else
                    next_state = decoding;
            end
            finish: begin
                if (success == 1)
                    next_state = frame_space;
                else
                    next_state = finish;
            end
            frame_space: begin
                if (frame_space_counter >= FRAME_SPACE_CYCLES)
                    next_state = idle;
                else
                    next_state = frame_space;
            end
            default: next_state = idle;
        endcase
    end

    // Datapath / flags
    always_ff @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            started               <= 1'b0;
            decoded               <= 1'b0;
            failed                <= 1'b0;
            success               <= 1'b0;
            frame_full            <= 1'b0;
            ir_frame_valid        <= 1'b0;
            stored                <= 1'b0;
            cycle_counter         <= 0;
            frame_space_counter   <= 0;
            bit_counter           <= 0;
            finish_counter        <= 0;
            low_counter           <= 0;
            ir_frame_reg          <= 12'b0;
            ir_frame_out          <= 12'b0;
            ir_function_code_out  <= 7'b0;
            ir_device_address_out <= 5'b0;
            ir_output_valid       <= 1'b0;
        end else begin
            ir_output_valid <= 1'b0;
            case (present_state)
                idle: begin
                    started             <= 1'b0;
                    decoded             <= 1'b0;
                    failed              <= 1'b0;
                    success             <= 1'b0;
                    frame_full          <= 1'b0;
                    ir_frame_valid      <= 1'b0;
                    stored              <= 1'b0;
                    cycle_counter       <= 0;
                    bit_counter         <= 0;
                    frame_space_counter <= 0;
                    finish_counter      <= 0;
                    low_counter         <= 0;
                    ir_frame_reg        <= 12'b0;
                end
                start: begin
                    if (ir_signal_in == 1) begin
                        cycle_counter <= cycle_counter + 1;
                        if (cycle_counter + 1 >= START_THRESH)
                            started <= 1'b1;
                    end else begin
                        if (started == 1'b0)
                            failed <= 1'b1;
                        cycle_counter <= 0;
                        low_counter   <= 0;
                    end
                end
                decoding: begin
                    if (ir_signal_in == 1) begin
                        cycle_counter <= cycle_counter + 1;
                        low_counter   <= 0;
                    end else begin
                        low_counter <= low_counter + 1;
                        if (cycle_counter != 0) begin
                            if (bit_counter < 12) begin
                                ir_frame_reg[bit_counter] <= (cycle_counter >= BIT_THRESH) ? 1'b1 : 1'b0;
                                bit_counter <= bit_counter + 1;
                                if (bit_counter + 1 == 12) begin
                                    decoded    <= 1'b1;
                                    frame_full <= 1'b1;
                                end
                            end
                            cycle_counter <= 0;
                            low_counter   <= 0;
                        end else begin
                            if ((low_counter + 1 >= LOW_TIMEOUT) && (bit_counter < 12))
                                failed <= 1'b1;
                        end
                    end
                end
                finish: begin
                    if (!success) begin
                        if (finish_counter < OUT_LATENCY-1) begin
                            finish_counter <= finish_counter + 1;
                        end else begin
                            ir_frame_out          <= ir_frame_reg;
                            ir_function_code_out  <= func_code_w;
                            ir_device_address_out <= dev_addr_w;
                            ir_output_valid       <= 1'b1;
                            ir_frame_valid        <= 1'b1;
                            stored                <= 1'b1;
                            success               <= 1'b1;
                        end
                    end
                end
                frame_space: begin
                    success             <= 1'b0;
                    decoded             <= 1'b0;
                    frame_space_counter <= frame_space_counter + 1;
                end
                default: ;
            endcase
        end
    end

endmodule

module kogge_stone_adder (
    input logic clk,
    input logic reset,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic start,
    output logic [16:0] Sum,
    output logic done
);

    logic [15:0] G0, G1, G2, G3;
    logic [15:0] P0, P1, P2, P3;
    logic [16:0] carry;
    logic [16:0] sum_comb;
    logic [3:0] stage;
    logic active;

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            Sum <= 0;
            done <= 0;
            active <= 0;
            stage <= 0;
        end else if (start && !active) begin
            active <= 1;
            stage <= 0;
            done <= 0;
            Sum <= 0;
        end else if (active) begin
            if (stage == 4) begin
                Sum <= sum_comb;
                done <= 1;
                active <= 0;
            end else begin
                stage <= stage + 1;
            end
        end else if (!start) begin
            done <= 0;
        end
    end

    always_comb begin
        G1 = 0; G2 = 0; G3 = 0;
        P1 = 0; P2 = 0; P3 = 0;
        carry = 0;
        sum_comb = 0;

        for (int i = 0; i < 16; i++) begin
            G0[i] = A[i] & B[i];
            P0[i] = A[i] ^ B[i];
        end

        if (stage >= 0) begin
            for (int i = 0; i < 16; i++) begin
                if (i >= 1) begin
                    G1[i] = G0[i] | (P0[i] & G0[i - 1]);
                    P1[i] = P0[i] & P0[i - 1];
                end else begin
                    G1[i] = G0[i];
                    P1[i] = P0[i];
                end
            end
        end

        if (stage >= 1) begin
            for (int i = 0; i < 16; i++) begin
                if (i >= 2) begin
                    G2[i] = G1[i] | (P1[i] & G1[i - 2]);
                    P2[i] = P1[i] & P1[i - 2];
                end else begin
                    G2[i] = G1[i];
                    P2[i] = P1[i];
                end
            end
        end

        if (stage >= 2) begin
            for (int i = 0; i < 16; i++) begin
                if (i >= 4) begin
                    G3[i] = G2[i] | (P2[i] & G2[i - 4]);
                    P3[i] = P2[i] & P2[i - 4];
                end else begin
                    G3[i] = G2[i];
                    P3[i] = P2[i];
                end
            end
        end

        if (stage >= 3) begin
            carry[0] = 0;
            for (int i = 1; i <= 16; i++) begin
                carry[i] = G3[i - 1] | (P3[i - 1] & carry[i - 1]);
            end

            for (int i = 0; i < 16; i++) begin
                sum_comb[i] = P0[i] ^ carry[i];
            end
            sum_comb[16] = carry[16];
        end
    end
endmodule

module lfsr_8bit(input clock, reset, input [7:0] lfsr_seed, output reg [7:0] lfsr_out);
	// 8-bit LFSR in Fibonacci configuration.
	// Primitive polynomial: x^8 + x^6 + x^5 + x + 1.
	// Non-zero coefficients (excluding x^8 and x^0) define the tap positions.
	// Feedback is applied to the input of the shift register:
	//   lfsr_out[7] = lfsr_out[6] ^ lfsr_out[5] ^ lfsr_out[1] ^ lfsr_out[0]
	//   lfsr_out[6:0] = lfsr_out[7:1]  (right shift)

	// Feedback bit computed from tap positions XORed with the final register value
	logic feedback;
	assign feedback = lfsr_out[6] ^ lfsr_out[5] ^ lfsr_out[1] ^ lfsr_out[0];

	always_ff @(posedge clock or negedge reset)
	begin
		if (!reset)
			lfsr_out <= lfsr_seed;                 // Async-low reset loads the initial seed
		else
			lfsr_out <= {feedback, lfsr_out[7:1]}; // Fibonacci shift: feedback into MSB, shift right
	end
endmodule

module load_store_unit (
    // Clock and reset
    input  logic        clk,
    input  logic        rst_n,

    // Data-cache interface
    output logic        dmem_req_o,
    input  logic        dmem_gnt_i,
    output logic [31:0] dmem_req_addr_o,
    output logic        dmem_req_we_o,
    output logic [3:0]  dmem_req_be_o,
    output logic [31:0] dmem_req_wdata_o,
    input  logic        dmem_rvalid_i,
    input  logic [31:0] dmem_rsp_rdata_i,

    // Execution stage interface
    input  logic        ex_if_req_i,
    input  logic        ex_if_we_i,
    input  logic [1:0]  ex_if_type_i,
    input  logic [31:0] ex_if_wdata_i,
    input  logic [31:0] ex_if_addr_base_i,
    input  logic [31:0] ex_if_addr_offset_i,
    output logic        ex_if_ready_o,

    // Writeback interface
    output logic [31:0] wb_if_rdata_o,
    output logic        wb_if_rvalid_o
);

    // FSM states
    localparam [1:0] S_IDLE = 2'd0,
                     S_REQ  = 2'd1,
                     S_WAIT = 2'd2;

    // Data-type encodings
    localparam [1:0] TYPE_BYTE = 2'b00,
                     TYPE_HALF = 2'b01,
                     TYPE_WORD = 2'b10;

    logic [1:0] state;
    logic       is_store;

    // Combinational effective-address / byte-enable / alignment path
    logic [31:0] eff_addr;
    logic [1:0]  addr_lsb;   // low two bits of the effective address
    logic        addr_b0;    // eff_addr[0]
    logic        addr_b1;    // eff_addr[1]
    logic [3:0]  be_c;
    logic        aligned_c;
    logic        accept;

    assign eff_addr = ex_if_addr_base_i + ex_if_addr_offset_i;
    assign addr_lsb = eff_addr[1:0];
    assign addr_b0  = eff_addr[0];
    assign addr_b1  = eff_addr[1];

    always_comb begin
        be_c      = 4'b0000;
        aligned_c = 1'b0;
        case (ex_if_type_i)
            TYPE_BYTE: begin
                // Byte access: always aligned; single byte selected by LSBs
                aligned_c = 1'b1;
                be_c      = 4'b0001 << addr_lsb;
            end
            TYPE_HALF: begin
                // Halfword: must be 2-byte aligned (bit0 == 0)
                if (addr_b0 == 1'b0) begin
                    aligned_c = 1'b1;
                    be_c      = (addr_b1 == 1'b0) ? 4'b0011 : 4'b1100;
                end
            end
            TYPE_WORD: begin
                // Word: must be 4-byte aligned
                if (addr_lsb == 2'b00) begin
                    aligned_c = 1'b1;
                    be_c      = 4'b1111;
                end
            end
            default: begin
                aligned_c = 1'b0;
                be_c      = 4'b0000;
            end
        endcase
    end

    // A request is accepted only when the LSU is idle/ready, EX requests,
    // and the access is aligned. Misaligned/illegal accesses are discarded.
    assign accept = ex_if_ready_o & ex_if_req_i & aligned_c;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state            <= S_IDLE;
            is_store         <= 1'b0;
            dmem_req_o       <= 1'b0;
            dmem_req_we_o    <= 1'b0;
            dmem_req_addr_o  <= 32'b0;
            dmem_req_be_o    <= 4'b0;
            dmem_req_wdata_o <= 32'b0;
            ex_if_ready_o    <= 1'b1;
            wb_if_rvalid_o   <= 1'b0;
            wb_if_rdata_o    <= 32'b0;
        end else begin
            // wb valid is a one-cycle pulse; data is held until next load
            wb_if_rvalid_o <= 1'b0;

            case (state)
                S_IDLE: begin
                    if (accept) begin
                        // Drive the data-cache request one cycle after the
                        // EX request is received; deassert ready meanwhile.
                        dmem_req_o       <= 1'b1;
                        dmem_req_we_o    <= ex_if_we_i;
                        dmem_req_addr_o  <= eff_addr;
                        dmem_req_be_o    <= be_c;
                        dmem_req_wdata_o <= ex_if_we_i ? ex_if_wdata_i : 32'b0;
                        ex_if_ready_o    <= 1'b0;
                        is_store         <= ex_if_we_i;
                        state            <= S_REQ;
                    end
                end

                S_REQ: begin
                    // Wait for the memory grant.
                    if (dmem_gnt_i) begin
                        // On grant, clear the request the next cycle.
                        dmem_req_o       <= 1'b0;
                        dmem_req_we_o    <= 1'b0;
                        dmem_req_addr_o  <= 32'b0;
                        dmem_req_be_o    <= 4'b0;
                        dmem_req_wdata_o <= 32'b0;
                        if (is_store) begin
                            // Store completes on grant; become ready again.
                            ex_if_ready_o <= 1'b1;
                            state         <= S_IDLE;
                        end else begin
                            // Load: wait for the read-valid response.
                            state         <= S_WAIT;
                        end
                    end
                end

                S_WAIT: begin
                    // Wait for the one-cycle read-valid pulse from memory.
                    if (dmem_rvalid_i) begin
                        wb_if_rvalid_o <= 1'b1;
                        wb_if_rdata_o  <= dmem_rsp_rdata_i;
                        ex_if_ready_o  <= 1'b1;
                        state          <= S_IDLE;
                    end
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

module load_store_unit (
    input  logic                 clk,
    input  logic                 rst_n,

    // EX stage interface
    input  logic                 ex_if_req_i,           // LSU request
    input  logic                 ex_if_we_i,            // Write enable: 0 (load), 1 (store)
    input  logic     [ 1:0]      ex_if_type_i,          // Data type: 0x2 (word), 0x1 (halfword), 0x0 (byte)
    input  logic     [31:0]      ex_if_wdata_i,         // Data to write to memory
    input  logic     [31:0]      ex_if_addr_base_i,     // Base address
    input  logic     [31:0]      ex_if_addr_offset_i,   // Offset address
    input  logic                 ex_if_extend_mode_i,   // 0: zero-extend, 1: sign-extend (byte/halfword loads)
    output logic                 ex_if_ready_o    ,

    // Writeback stage interface
    output logic     [31:0]      wb_if_rdata_o,         // Requested data
    output logic                 wb_if_rvalid_o,        // Requested data valid

    // Data memory (DMEM) interface
    output logic                 dmem_req_o,
    input  logic                 dmem_gnt_i,
    output logic     [31:0]      dmem_req_addr_o,
    output logic                 dmem_req_we_o,
    output logic     [ 3:0]      dmem_req_be_o,
    output logic     [31:0]      dmem_req_wdata_o,
    input  logic     [31:0]      dmem_rsp_rdata_i,
    input  logic                 dmem_rvalid_i
    );

  // Internal signals
  logic ex_req_fire;
  logic dmem_req_we_q;
  logic [31:0] data_addr_int;
  logic misaligned_addr;
  logic [3:0] dmem_be, dmem_req_be_q;

  logic busy_q;  // Sticky busy bit: Set with EX req and cleared with DMEM response
  logic dmem_req_q ;

  logic [31:0] dmem_req_wdata_q;
  logic [31:0] dmem_req_addr_q;

  logic [31:0] wb_if_rdata_q;
  logic wb_if_rvalid_q;

  // Captured extension context (sampled at request fire)
  logic [1:0]  rdata_offset_q;
  logic [1:0]  data_type_q;
  logic        data_sign_ext_q;

  // Extension results
  logic [31:0] rdata_w_ext, rdata_h_ext, rdata_b_ext, data_rdata_ext;

  // Address calculation
  assign data_addr_int = ex_if_addr_base_i + ex_if_addr_offset_i;

  // EX request fire condition
  assign ex_req_fire = ex_if_req_i && !busy_q && !misaligned_addr;
  assign ex_if_ready_o = !busy_q;

  ///////////////////////////////// Byte Enable Generation ////////////////////////////////
  always_comb begin
    misaligned_addr = 1'b0;
    dmem_be = 4'b0000;
    case (ex_if_type_i)  // 0x2 (word), 0x1 (halfword), 0x0 (byte)
      2'b00: begin  // Byte
          case (data_addr_int[1:0])
            2'b00:   dmem_be = 4'b0001;
            2'b01:   dmem_be = 4'b0010;
            2'b10:   dmem_be = 4'b0100;
            2'b11:   dmem_be = 4'b1000;
            default: dmem_be = 4'b0000;
          endcase
      end

      2'b01: begin  // Half-word
          case (data_addr_int[1:0])
            2'b00:   dmem_be = 4'b0011;
            2'b10:   dmem_be = 4'b1100;
            default: begin
                dmem_be = 4'b0000;
                misaligned_addr = 1'b1;
            end
          endcase
      end

      2'b10: begin  // Word
          case (data_addr_int[1:0])
            2'b00:   dmem_be = 4'b1111;
            default: begin
                dmem_be = 4'b0000;
                misaligned_addr = 1'b1;
            end
          endcase
      end
      default: begin
          dmem_be = 4'b0000;
          misaligned_addr = 1'b1;
      end
    endcase
  end

  ///////////////////////////////// dmem_req ////////////////////////////////
  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      dmem_req_q       <= 1'b0;
      dmem_req_addr_q  <= '0;
      dmem_req_we_q    <= '0 ;
      dmem_req_be_q    <= '0 ;
      dmem_req_wdata_q <= '0 ;
      rdata_offset_q   <= '0 ;
      data_type_q      <= '0 ;
      data_sign_ext_q  <= '0 ;
    end else if (ex_req_fire) begin
      dmem_req_q       <= 1'b1;
      dmem_req_addr_q  <= data_addr_int;
      dmem_req_we_q    <= ex_if_we_i;
      dmem_req_be_q    <= dmem_be ;
      dmem_req_wdata_q <= ex_if_wdata_i ;

      rdata_offset_q   <= data_addr_int[1:0];
      data_type_q      <= ex_if_type_i;
      data_sign_ext_q  <= ex_if_extend_mode_i;
    end else if (dmem_req_q && dmem_gnt_i) begin
      dmem_req_q       <= 1'b0;  // request granted
      dmem_req_addr_q  <= '0 ;
      dmem_req_we_q    <= '0 ;
      dmem_req_be_q    <= '0 ;
      dmem_req_wdata_q <= '0 ;
    end
  end

  ///////////////////////////////// Load Data Extension ////////////////////////////////
  // Word: no extension effect (full 32-bit)
  always_comb begin
    case (rdata_offset_q)
      2'b00:   rdata_w_ext = dmem_rsp_rdata_i[31:0];
      default: rdata_w_ext = '0 ;
    endcase
  end

  // Halfword
  always_comb begin
    case (rdata_offset_q)
      2'b00: begin
        if (data_sign_ext_q) rdata_h_ext = {{16{dmem_rsp_rdata_i[15]}}, dmem_rsp_rdata_i[15:0]};
        else                 rdata_h_ext = {16'h0000, dmem_rsp_rdata_i[15:0]};
      end
      2'b10: begin
        if (data_sign_ext_q) rdata_h_ext = {{16{dmem_rsp_rdata_i[31]}}, dmem_rsp_rdata_i[31:16]};
        else                 rdata_h_ext = {16'h0000, dmem_rsp_rdata_i[31:16]};
      end
      default: rdata_h_ext = '0 ;
    endcase
  end

  // Byte
  always_comb begin
    case (rdata_offset_q)
      2'b00: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[7]}},  dmem_rsp_rdata_i[7:0]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[7:0]};
      end
      2'b01: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[15]}}, dmem_rsp_rdata_i[15:8]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[15:8]};
      end
      2'b10: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[23]}}, dmem_rsp_rdata_i[23:16]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[23:16]};
      end
      2'b11: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[31]}}, dmem_rsp_rdata_i[31:24]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[31:24]};
      end
      default: rdata_b_ext = '0 ;
    endcase
  end

  always_comb begin
    case (data_type_q)
      2'b00:   data_rdata_ext = rdata_b_ext ;
      2'b01:   data_rdata_ext = rdata_h_ext ;
      2'b10:   data_rdata_ext = rdata_w_ext ;
      default: data_rdata_ext = 32'b0;
    endcase
  end

  ///////////////////////////////// DMEM Request Interface ////////////////////////////////
  always_comb begin : dmem_req
    dmem_req_o        = dmem_req_q;
    dmem_req_addr_o   = dmem_req_addr_q;
    dmem_req_we_o     = dmem_req_we_q;
    dmem_req_be_o     = dmem_req_be_q;
    dmem_req_wdata_o  = dmem_req_wdata_q;
  end

  ///////////////////////////////// Read Response Handling ////////////////////////////////
  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      wb_if_rdata_q   <= 32'b0;
      wb_if_rvalid_q  <= 1'b0;
    end else if (dmem_rvalid_i) begin
      wb_if_rdata_q   <= data_rdata_ext;
      wb_if_rvalid_q  <= 1'b1;
    end else begin
      wb_if_rvalid_q  <= 1'b0;
    end
  end

  assign wb_if_rdata_o =  wb_if_rdata_q;
  assign wb_if_rvalid_o = wb_if_rvalid_q;

  ///////////////////////////////// Busy Logic ////////////////////////////////
  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      busy_q <= 1'b0;
    end else if (ex_req_fire) begin
      busy_q <= 1'b1;
    end else if (dmem_req_we_q && dmem_gnt_i) begin
      busy_q <= 1'b0;  // Write request granted
    end else if (!dmem_req_we_q && dmem_rvalid_i) begin
      busy_q <= 1'b0;  // Read request response received
    end
  end

endmodule

module load_store_unit (
    input  logic                 clk,
    input  logic                 rst_n,

    // EX stage interface
    input  logic                 ex_if_req_i,           // LSU request
    input  logic                 ex_if_we_i,            // Write enable: 0 (load), 1 (store)
    input  logic     [ 1:0]      ex_if_type_i,          // Data type: 0x2 (word), 0x1 (halfword), 0x0 (byte)
    input  logic     [31:0]      ex_if_wdata_i,         // Data to write to memory
    input  logic     [31:0]      ex_if_addr_base_i,     // Base address
    input  logic     [31:0]      ex_if_addr_offset_i,   // Offset address
    input  logic                 ex_if_extend_mode_i,
    output logic                 ex_if_ready_o    ,

    // Writeback stage interface
    output logic     [31:0]      wb_if_rdata_o,         // Requested data
    output logic                 wb_if_rvalid_o,        // Requested data valid

    // Data memory (DMEM) interface
    output logic                 dmem_req_o,
    input  logic                 dmem_gnt_i,
    output logic     [31:0]      dmem_req_addr_o,
    output logic                 dmem_req_we_o,
    output logic     [ 3:0]      dmem_req_be_o,
    output logic     [31:0]      dmem_req_wdata_o,
    input  logic     [31:0]      dmem_rsp_rdata_i,
    input  logic                 dmem_rvalid_i
    );

  // FSM states (per the specified state diagram)
  localparam [3:0] IDLE                = 4'd0;
  localparam [3:0] ALIGNED_WR          = 4'd1;
  localparam [3:0] ALIGNED_RD          = 4'd2;
  localparam [3:0] ALIGNED_RD_GNT      = 4'd3;
  localparam [3:0] MISALIGNED_WR       = 4'd4;
  localparam [3:0] MISALIGNED_WR_1     = 4'd5;
  localparam [3:0] MISALIGNED_RD       = 4'd6;
  localparam [3:0] MISALIGNED_RD_GNT   = 4'd7;
  localparam [3:0] MISALIGNED_RD_1     = 4'd8;
  localparam [3:0] MISALIGNED_RD_GNT_1 = 4'd9;

  logic [3:0] state, next_state;

  logic [31:0] data_addr_int;

  // Byte-enable / word-boundary-crossing computation (combinational, from EX inputs)
  logic [3:0] be_lo, be_hi;
  logic       word_cross;

  // Captured request context (sampled when a request is accepted in IDLE)
  logic [31:0] addr_lo_q, addr_hi_q;
  logic [3:0]  be_lo_q, be_hi_q;
  logic        we_q;
  logic [31:0] wdata_q;
  logic        misaligned_q;
  logic [1:0]  rdata_offset_q;
  logic [1:0]  data_type_q;
  logic        data_sign_ext_q;

  // Extension results (aligned loads)
  logic [31:0] rdata_w_ext, rdata_h_ext, rdata_b_ext, data_rdata_ext;

  logic [31:0] wb_if_rdata_q;
  logic        wb_if_rvalid_q;

  // Effective address
  assign data_addr_int = ex_if_addr_base_i + ex_if_addr_offset_i;

  ///////////////////////////////// Byte-enable / crossing generation ////////////////////////////////
  // be_lo : byte enables for the first (lower-address) transaction / word
  // be_hi : byte enables for the second (upper-address) transaction / word
  // word_cross : the access crosses a word boundary and needs two transactions
  always_comb begin
    be_lo = 4'b0000;
    be_hi = 4'b0000;
    case (ex_if_type_i)  // 0x2 (word), 0x1 (halfword), 0x0 (byte)
      2'b00: begin  // Byte : never crosses a word boundary
          case (data_addr_int[1:0])
            2'b00:   be_lo = 4'b0001;
            2'b01:   be_lo = 4'b0010;
            2'b10:   be_lo = 4'b0100;
            2'b11:   be_lo = 4'b1000;
            default: be_lo = 4'b0000;
          endcase
      end
      2'b01: begin  // Half-word : crosses only at offset 0b11
          case (data_addr_int[1:0])
            2'b00:   be_lo = 4'b0011;
            2'b01:   be_lo = 4'b0110;
            2'b10:   be_lo = 4'b1100;
            2'b11:   begin be_lo = 4'b1000; be_hi = 4'b0001; end
            default: be_lo = 4'b0000;
          endcase
      end
      2'b10: begin  // Word : crosses at any non-zero offset
          case (data_addr_int[1:0])
            2'b00:   be_lo = 4'b1111;
            2'b01:   begin be_lo = 4'b1110; be_hi = 4'b0001; end
            2'b10:   begin be_lo = 4'b1100; be_hi = 4'b0011; end
            2'b11:   begin be_lo = 4'b1000; be_hi = 4'b0111; end
            default: be_lo = 4'b0000;
          endcase
      end
      default: begin
          be_lo = 4'b0000;
          be_hi = 4'b0000;
      end
    endcase
  end

  assign word_cross = |be_hi;

  assign ex_if_ready_o = (state == IDLE);

  ///////////////////////////////// FSM next-state ////////////////////////////////
  always_comb begin
    next_state = state;
    case (state)
      IDLE: begin
        if (ex_if_req_i) begin
          if (word_cross) next_state = ex_if_we_i ? MISALIGNED_WR : MISALIGNED_RD;
          else       next_state = ex_if_we_i ? ALIGNED_WR    : ALIGNED_RD;
        end
      end
      ALIGNED_WR:          if (dmem_gnt_i)    next_state = IDLE;
      ALIGNED_RD:          if (dmem_gnt_i)    next_state = ALIGNED_RD_GNT;
      ALIGNED_RD_GNT:      if (dmem_rvalid_i) next_state = IDLE;
      MISALIGNED_WR:       if (dmem_gnt_i)    next_state = MISALIGNED_WR_1;
      MISALIGNED_WR_1:     if (dmem_gnt_i)    next_state = IDLE;
      MISALIGNED_RD:       if (dmem_gnt_i)    next_state = MISALIGNED_RD_GNT;
      MISALIGNED_RD_GNT:   if (dmem_rvalid_i) next_state = MISALIGNED_RD_1;
      MISALIGNED_RD_1:     if (dmem_gnt_i)    next_state = MISALIGNED_RD_GNT_1;
      MISALIGNED_RD_GNT_1: if (dmem_rvalid_i) next_state = IDLE;
      default:                                next_state = IDLE;
    endcase
  end

  ///////////////////////////////// FSM state + context capture ////////////////////////////////
  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      state           <= IDLE;
      addr_lo_q       <= '0;
      addr_hi_q       <= '0;
      be_lo_q         <= '0;
      be_hi_q         <= '0;
      we_q            <= 1'b0;
      wdata_q         <= '0;
      misaligned_q    <= 1'b0;
      rdata_offset_q  <= '0;
      data_type_q     <= '0;
      data_sign_ext_q <= 1'b0;
    end else begin
      state <= next_state;
      if (state == IDLE && ex_if_req_i) begin
        // Transaction 1 targets the effective (lower) address;
        // transaction 2 (if any) targets the next word.
        addr_lo_q       <= data_addr_int;
        addr_hi_q       <= data_addr_int + 32'd4;
        be_lo_q         <= be_lo;
        be_hi_q         <= be_hi;
        we_q            <= ex_if_we_i;
        wdata_q         <= ex_if_wdata_i;      // store data assumed pre-aligned
        misaligned_q    <= word_cross;
        rdata_offset_q  <= data_addr_int[1:0];
        data_type_q     <= ex_if_type_i;
        data_sign_ext_q <= ex_if_extend_mode_i;
      end
    end
  end

  ///////////////////////////////// DMEM Request Interface ////////////////////////////////
  // All data-cache bus signals are zeroed whenever dmem_req_o is deasserted.
  always_comb begin : dmem_req
    dmem_req_o        = 1'b0;
    dmem_req_addr_o   = 32'b0;
    dmem_req_we_o     = 1'b0;
    dmem_req_be_o     = 4'b0;
    dmem_req_wdata_o  = 32'b0;
    case (state)
      // First (lower-address) bus transaction
      ALIGNED_WR, ALIGNED_RD, MISALIGNED_WR, MISALIGNED_RD: begin
        dmem_req_o       = 1'b1;
        dmem_req_addr_o  = addr_lo_q;
        dmem_req_we_o    = we_q;
        dmem_req_be_o    = be_lo_q;
        dmem_req_wdata_o = wdata_q;
      end
      // Second (upper-address) bus transaction
      MISALIGNED_WR_1, MISALIGNED_RD_1: begin
        dmem_req_o       = 1'b1;
        dmem_req_addr_o  = addr_hi_q;
        dmem_req_we_o    = we_q;
        dmem_req_be_o    = be_hi_q;
        dmem_req_wdata_o = wdata_q;
      end
      default: ; // IDLE and *_GNT states: bus idle / zeroed
    endcase
  end

  ///////////////////////////////// Load Data Extension (aligned loads) ////////////////////////////////
  always_comb begin
    case (rdata_offset_q)
      2'b00:   rdata_w_ext = dmem_rsp_rdata_i[31:0];
      default: rdata_w_ext = '0 ;
    endcase
  end

  always_comb begin
    case (rdata_offset_q)
      2'b00: begin
        if (data_sign_ext_q) rdata_h_ext = {{16{dmem_rsp_rdata_i[15]}}, dmem_rsp_rdata_i[15:0]};
        else                 rdata_h_ext = {16'h0000, dmem_rsp_rdata_i[15:0]};
      end
      2'b10: begin
        if (data_sign_ext_q) rdata_h_ext = {{16{dmem_rsp_rdata_i[31]}}, dmem_rsp_rdata_i[31:16]};
        else                 rdata_h_ext = {16'h0000, dmem_rsp_rdata_i[31:16]};
      end
      default: rdata_h_ext = '0 ;
    endcase
  end

  always_comb begin
    case (rdata_offset_q)
      2'b00: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[7]}},  dmem_rsp_rdata_i[7:0]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[7:0]};
      end
      2'b01: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[15]}}, dmem_rsp_rdata_i[15:8]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[15:8]};
      end
      2'b10: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[23]}}, dmem_rsp_rdata_i[23:16]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[23:16]};
      end
      2'b11: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[31]}}, dmem_rsp_rdata_i[31:24]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[31:24]};
      end
      default: rdata_b_ext = '0 ;
    endcase
  end

  always_comb begin
    case (data_type_q)
      2'b00:   data_rdata_ext = rdata_b_ext ;
      2'b01:   data_rdata_ext = rdata_h_ext ;
      2'b10:   data_rdata_ext = rdata_w_ext ;
      default: data_rdata_ext = 32'b0;
    endcase
  end

  ///////////////////////////////// Read Response / Writeback ////////////////////////////////
  // Misaligned loads : raw response per transaction.
  // Aligned loads    : sized + sign/zero-extended response.
  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      wb_if_rdata_q   <= 32'b0;
      wb_if_rvalid_q  <= 1'b0;
    end else if (dmem_rvalid_i) begin
      wb_if_rdata_q   <= misaligned_q ? dmem_rsp_rdata_i : data_rdata_ext;
      wb_if_rvalid_q  <= 1'b1;
    end else begin
      wb_if_rvalid_q  <= 1'b0;
    end
  end

  assign wb_if_rdata_o  = wb_if_rdata_q;
  assign wb_if_rvalid_o = wb_if_rvalid_q;

endmodule

// Manchester encoder module

module manchester_encoder #(
    parameter N = 8  // Default width of input data
) (
    input  logic clk_in,          // Clock input
    input  logic rst_in,          // Active high reset input
    input  logic enc_valid_in,        // Input valid signal
    input  logic [N-1:0] enc_data_in, // N-bit input data
    output logic enc_valid_out,       // Output valid signal
    output logic [2*N-1:0] enc_data_out // 2N-bit output encoded data
);

    // Combinational logic to generate Manchester encoded data.
    // Unconditional default assignments to BOTH outputs at the top of the
    // block prevent latch inference: whenever the encode branch is not taken
    // (reset asserted, or no valid input) the outputs are driven to 0 rather
    // than holding their previous value.
    always_comb begin
        enc_data_out  = '0;   // default -> no latch
        enc_valid_out = 1'b0; // default -> no latch

        if (rst_in) begin
            // Active-high reset forces the output to zero and clears valid.
            enc_data_out  = '0;
            enc_valid_out = 1'b0;
        end else if (enc_valid_in) begin
            for (int i = 0; i < N; i++) begin
                if (enc_data_in[i] == 1'b1) begin
                    enc_data_out[2*i]     = 1'b1;
                    enc_data_out[2*i + 1] = 1'b0;
                end else begin
                    enc_data_out[2*i]     = 1'b0;
                    enc_data_out[2*i + 1] = 1'b1;
                end
            end
            enc_valid_out = 1'b1; // Set the valid signal
        end
        // else: outputs keep their default 0 (valid_in == 0 -> zeroed output)
    end

endmodule

module top_manchester #(
    parameter N = 8  // Default width of input and output data
) (
    input  logic clk_in,          // Clock input
    input  logic rst_in,          // Active high reset input
    // Encoder Signals
    input  logic enc_valid_in,    // Input valid signal
    input  logic [N-1:0] enc_data_in, // N-bit input data
    output logic enc_valid_out,   // Output valid signal
    output logic [2*N-1:0] enc_data_out, // 2*N-bit encoder output data

    // Decoder Signals
    input  logic dec_valid_in,    // Input valid signal
    input  logic [2*N-1:0] dec_data_in, // 2*N-bit input data
    output logic dec_valid_out,   // Output valid signal
    output logic [N-1:0] dec_data_out // N-bit output decoded data
);

    manchester_encoder #(
        .N(N)
    ) encoder_dut (
        .clk_in(clk_in),
        .rst_in(rst_in),
        .enc_valid_in(enc_valid_in),
        .enc_data_in(enc_data_in),
        .enc_valid_out(enc_valid_out),
        .enc_data_out(enc_data_out)
    );

    manchester_decoder #(
        .N(N)
    ) decoder_dut (
        .clk_in(clk_in),
        .rst_in(rst_in),
        .dec_valid_in(dec_valid_in),
        .dec_data_in(dec_data_in),
        .dec_valid_out(dec_valid_out),
        .dec_data_out(dec_data_out)
    );

endmodule

module manchester_encoder #(
    parameter N = 8  // Default width of input data
) (
    input  logic clk_in,          // Clock input
    input  logic rst_in,          // Active high reset input
    input  logic enc_valid_in,    // Input valid signal
    input  logic [N-1:0] enc_data_in, // N-bit input data
    output logic enc_valid_out,   // Output valid signal
    output logic [2*N-1:0] enc_data_out // 2N-bit output encoded data
);

    always_ff @(posedge clk_in) begin
        if (rst_in) begin
            enc_data_out <= '0;
            enc_valid_out <= 1'b0;
        end else if (enc_valid_in) begin
            for (int i = 0; i < N; i++) begin
                if (enc_data_in[i] == 1'b1) begin
                    enc_data_out[2*i]   <= 1'b1;
                    enc_data_out[2*i+1] <= 1'b0;
                end else begin
                    enc_data_out[2*i]   <= 1'b0;
                    enc_data_out[2*i+1] <= 1'b1;
                end
            end
            enc_valid_out <= 1'b1;
        end else begin
            enc_data_out <= 'd0;
            enc_valid_out <= 1'b0;
        end
    end

endmodule

module manchester_decoder #(
    parameter N = 8  // Default width of output data
) (
    input  logic clk_in,          // Clock input
    input  logic rst_in,          // Active high reset input
    input  logic dec_valid_in,    // Input valid signal
    input  logic [2*N-1:0] dec_data_in, // 2N-bit Manchester encoded input data
    output logic dec_valid_out,   // Output valid signal
    output logic [N-1:0] dec_data_out  // N-bit output decoded data
);

    always_ff @(posedge clk_in) begin
        if (rst_in) begin
            dec_data_out <= '0;
            dec_valid_out <= 1'b0;
        end else if (dec_valid_in) begin
            for (int i = 0; i < N; i++) begin
                if (dec_data_in[2*i] == 1'b1 && dec_data_in[2*i+1] == 1'b0) begin
                    dec_data_out[i] <= 1'b1;
                end else if (dec_data_in[2*i] == 1'b0 && dec_data_in[2*i+1] == 1'b1) begin
                    dec_data_out[i] <= 1'b0;
                end else begin
                    dec_data_out[i] <= 1'b0;
                end
            end
            dec_valid_out <= 1'b1;
        end else begin
            dec_data_out <= '0;
            dec_valid_out <= 1'b0;
        end
    end

endmodule

module matrix_multiplier #(
    parameter integer ROW_A             = 4,
    parameter integer COL_A             = 4,
    parameter integer ROW_B             = 4,   // must equal COL_A
    parameter integer COL_B             = 4,
    parameter integer INPUT_DATA_WIDTH  = 8,
    // Wide enough to hold sum of COL_A products of two INPUT_DATA_WIDTH values
    parameter integer OUTPUT_DATA_WIDTH = 2*INPUT_DATA_WIDTH + $clog2(COL_A)
) (
    input  wire [ROW_A*COL_A*INPUT_DATA_WIDTH-1:0] matrix_a,
    input  wire [ROW_B*COL_B*INPUT_DATA_WIDTH-1:0] matrix_b,
    output reg  [ROW_A*COL_B*OUTPUT_DATA_WIDTH-1:0] matrix_c
);

    // Flattening is row-major with element [0][0] in the least-significant slot:
    //   A[i][k] occupies bits [(i*COL_A + k)*INPUT_DATA_WIDTH +: INPUT_DATA_WIDTH]
    //   B[k][j] occupies bits [(k*COL_B + j)*INPUT_DATA_WIDTH +: INPUT_DATA_WIDTH]
    //   C[i][j] occupies bits [(i*COL_B + j)*OUTPUT_DATA_WIDTH +: OUTPUT_DATA_WIDTH]

    integer i, j, k;
    reg [OUTPUT_DATA_WIDTH-1:0]   acc;
    reg [INPUT_DATA_WIDTH-1:0]    a_elem;
    reg [INPUT_DATA_WIDTH-1:0]    b_elem;
    reg [2*INPUT_DATA_WIDTH-1:0]  prod;

    always @* begin
        matrix_c = {(ROW_A*COL_B*OUTPUT_DATA_WIDTH){1'b0}};
        for (i = 0; i < ROW_A; i = i + 1) begin
            for (j = 0; j < COL_B; j = j + 1) begin
                acc = {OUTPUT_DATA_WIDTH{1'b0}};
                for (k = 0; k < COL_A; k = k + 1) begin
                    a_elem = matrix_a[(i*COL_A + k)*INPUT_DATA_WIDTH +: INPUT_DATA_WIDTH];
                    b_elem = matrix_b[(k*COL_B + j)*INPUT_DATA_WIDTH +: INPUT_DATA_WIDTH];
                    prod   = a_elem * b_elem;                 // unsigned, exact in 2*W bits
                    acc    = acc + prod;                      // accumulate in OUTPUT width
                end
                matrix_c[(i*COL_B + j)*OUTPUT_DATA_WIDTH +: OUTPUT_DATA_WIDTH] = acc;
            end
        end
    end

endmodule


// --- harness-toplevel alias (auto-added by cvdp_gate; the official
// harness compiles `-s cvdp_copilot_matrix_multiplier`; the author declared `matrix_multiplier`
// with the same interface) ---
module cvdp_copilot_matrix_multiplier #(
    parameter integer ROW_A             = 4,
    parameter integer COL_A             = 4,
    parameter integer ROW_B             = 4,    
    parameter integer COL_B             = 4,
    parameter integer INPUT_DATA_WIDTH  = 8,

    parameter integer OUTPUT_DATA_WIDTH = 2*INPUT_DATA_WIDTH + $clog2(COL_A)
) (
    input wire [ROW_A*COL_A*INPUT_DATA_WIDTH-1:0] matrix_a,
    input wire [ROW_B*COL_B*INPUT_DATA_WIDTH-1:0] matrix_b,
    output [ROW_A*COL_B*OUTPUT_DATA_WIDTH-1:0] matrix_c
);
    matrix_multiplier u_matrix_multiplier (.matrix_a(matrix_a), .matrix_b(matrix_b), .matrix_c(matrix_c));
endmodule


