module matrix_multiplier #(
  parameter ROW_A             = 4                                                   , // Number of rows in matrix A
  parameter COL_A             = 4                                                   , // Number of columns in matrix A
  parameter ROW_B             = 4                                                   , // Number of rows in matrix B
  parameter COL_B             = 4                                                   , // Number of columns in matrix B
  parameter INPUT_DATA_WIDTH  = 8                                                   , // Bit-width of input data
  parameter OUTPUT_DATA_WIDTH = (INPUT_DATA_WIDTH * 2) + $clog2(COL_A)                // Bit-width of output data
) (
  input  logic                                       clk      , // Clock input
  input  logic                                       srst     , // Active-high synchronous reset
  input  logic                                       valid_in , // Indicates valid input matrices
  input  logic [ (ROW_A*COL_A*INPUT_DATA_WIDTH)-1:0] matrix_a , // Input matrix A in 1D form
  input  logic [ (ROW_B*COL_B*INPUT_DATA_WIDTH)-1:0] matrix_b , // Input matrix B in 1D form
  output logic                                       valid_out, // Indicates valid output matrix
  output logic [(ROW_A*COL_B*OUTPUT_DATA_WIDTH)-1:0] matrix_c   // Output matrix C in 1D form
);
  genvar gv1;
  genvar gv2;
  genvar gv3;

  generate
    // Valid pipeline shift register: total latency valid_in -> valid_out = COL_A + 2
    logic [                                  COL_A:0] valid_out_reg; // Pipeline valid signal shift register
    logic [(ROW_A*COL_B*COL_A*OUTPUT_DATA_WIDTH)-1:0] mult_stage   ; // Intermediate multiplication results
    logic [(ROW_A*COL_B*COL_A*OUTPUT_DATA_WIDTH)-1:0] add_stage    ; // Accumulated addition results

    always_ff @(posedge clk)
      if (srst)
        {valid_out, valid_out_reg} <= '0;
      else
        {valid_out, valid_out_reg} <= {valid_out_reg, valid_in};

    for (gv1 = 0 ; gv1 < ROW_A ; gv1++) begin: row_a_gb
      for (gv2 = 0 ; gv2 < COL_B ; gv2++) begin: col_b_gb
        for (gv3 = 0 ; gv3 < COL_A ; gv3++) begin: col_a_gb
          // Multiplication stage: 1 clock cycle
          always_ff @(posedge clk)
            if (srst)
              mult_stage[((((gv1*COL_B)+gv2)*COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
            else
              mult_stage[((((gv1*COL_B)+gv2)*COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= matrix_a[((gv1*COL_A)+gv3)*INPUT_DATA_WIDTH+:INPUT_DATA_WIDTH] * matrix_b[((gv3*COL_B)+gv2)*INPUT_DATA_WIDTH+:INPUT_DATA_WIDTH];

          // Accumulation stage: systolic add chain over COL_A clock cycles
          always_ff @(posedge clk)
            if (srst)
              add_stage[((((gv1*COL_B)+gv2)*COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
            else if (gv3 == 0)
              add_stage[((((gv1*COL_B)+gv2)*COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= mult_stage[((((gv1*COL_B)+gv2)*COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH];
            else
              add_stage[((((gv1*COL_B)+gv2)*COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= mult_stage[((((gv1*COL_B)+gv2)*COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] + add_stage[((((gv1*COL_B)+gv2)*COL_A)+(gv3-1))*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH];
        end

        // Output stage: register accumulated result, 1 clock cycle
        always_ff @(posedge clk)
          if (srst)
            matrix_c[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
          else if (valid_out_reg[COL_A])
            matrix_c[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= add_stage[((((gv1*COL_B)+gv2)*COL_A)+(COL_A-1))*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH];
      end
    end

  endgenerate

endmodule

module matrix_multiplier #(
  parameter ROW_A             = 4                                                   , // Number of rows in matrix A
  parameter COL_A             = 4                                                   , // Number of columns in matrix A
  parameter ROW_B             = 4                                                   , // Number of rows in matrix B
  parameter COL_B             = 4                                                   , // Number of columns in matrix B
  parameter INPUT_DATA_WIDTH  = 8                                                   , // Bit-width of input data
  parameter OUTPUT_DATA_WIDTH = (INPUT_DATA_WIDTH * 2) + $clog2(COL_A)                // Bit-width of output data
) (
  input  logic                                       clk      , // Clock input
  input  logic                                       srst     , // Active-high Synchronous reset
  input  logic                                       valid_in , // Indicates valid input matrices
  input  logic [ (ROW_A*COL_A*INPUT_DATA_WIDTH)-1:0] matrix_a , // Input matrix A in 1D form
  input  logic [ (ROW_B*COL_B*INPUT_DATA_WIDTH)-1:0] matrix_b , // Input matrix B in 1D form
  output logic                                       valid_out, // Indicates valid output matrix
  output logic [(ROW_A*COL_B*OUTPUT_DATA_WIDTH)-1:0] matrix_c   // Output matrix C in 1D form
);

  // Local parameters for the balanced binary reduction tree.
  // MODIFIED_COL_A      : nearest power of two >= COL_A (padding/alignment, sizes mult_stage)
  // HALF_MODIFIED_COL_A : half of MODIFIED_COL_A (first level of the tree, sizes add_stage)
  localparam LOG2_COL_A          = $clog2(COL_A)         ;
  localparam MODIFIED_COL_A      = 2 ** LOG2_COL_A       ;
  localparam HALF_MODIFIED_COL_A = MODIFIED_COL_A / 2    ;

  genvar gv1;
  genvar gv2;
  genvar gv3;

  generate
    if (COL_A == 1) begin : g_col1
      // -------------------------------------------------------------------
      // Edge case COL_A == 1: no accumulation tree (would create zero-width
      // add_stage). Latency = $clog2(1) + 2 = 2 cycles.
      // -------------------------------------------------------------------
      logic [                                    0:0] valid_out_reg; // Pipeline valid shift register
      logic [        (ROW_A*COL_B*OUTPUT_DATA_WIDTH)-1:0] mult_stage; // Product results (single column)

      always_ff @(posedge clk)
        if (srst)
          {valid_out, valid_out_reg} <= '0;
        else
          {valid_out, valid_out_reg} <= {valid_out_reg, valid_in};

      for (gv1 = 0 ; gv1 < ROW_A ; gv1++) begin: row_a_gb
        for (gv2 = 0 ; gv2 < COL_B ; gv2++) begin: col_b_gb
          // Multiplication stage
          always_ff @(posedge clk)
            if (srst)
              mult_stage[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
            else
              mult_stage[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= matrix_a[((gv1*COL_A)+0)*INPUT_DATA_WIDTH+:INPUT_DATA_WIDTH] * matrix_b[((0*COL_B)+gv2)*INPUT_DATA_WIDTH+:INPUT_DATA_WIDTH];

          // Output stage: bypass tree, forward product directly
          always_ff @(posedge clk)
            if (srst)
              matrix_c[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
            else if (valid_out_reg[0])
              matrix_c[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= mult_stage[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH];
        end
      end
    end else begin : g_tree
      // -------------------------------------------------------------------
      // Binary reduction tree. Latency = $clog2(COL_A) + 2 cycles:
      //   1 cycle multiplication + LOG2_COL_A cycles reduction + 1 cycle output.
      // -------------------------------------------------------------------
      logic [                          LOG2_COL_A:0] valid_out_reg; // Pipeline valid shift register (LOG2_COL_A+2 total latency)
      logic [(ROW_A*COL_B*MODIFIED_COL_A*OUTPUT_DATA_WIDTH)-1:0] mult_stage; // Padded product results
      logic [(ROW_A*COL_B*HALF_MODIFIED_COL_A*OUTPUT_DATA_WIDTH)-1:0] add_stage; // Reduction-tree working register

      always_ff @(posedge clk)
        if (srst)
          {valid_out, valid_out_reg} <= '0;
        else
          {valid_out, valid_out_reg} <= {valid_out_reg, valid_in};

      for (gv1 = 0 ; gv1 < ROW_A ; gv1++) begin: row_a_gb
        for (gv2 = 0 ; gv2 < COL_B ; gv2++) begin: col_b_gb

          // Multiplication stage: MODIFIED_COL_A slots per element, padding held at 0
          for (gv3 = 0 ; gv3 < MODIFIED_COL_A ; gv3++) begin: mult_gb
            if (gv3 < COL_A) begin: real_prod
              always_ff @(posedge clk)
                if (srst)
                  mult_stage[((((gv1*COL_B)+gv2)*MODIFIED_COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
                else
                  mult_stage[((((gv1*COL_B)+gv2)*MODIFIED_COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= matrix_a[((gv1*COL_A)+gv3)*INPUT_DATA_WIDTH+:INPUT_DATA_WIDTH] * matrix_b[((gv3*COL_B)+gv2)*INPUT_DATA_WIDTH+:INPUT_DATA_WIDTH];
            end else begin: pad_prod
              always_ff @(posedge clk)
                mult_stage[((((gv1*COL_B)+gv2)*MODIFIED_COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
            end
          end

          // Accumulation stage: in-place binary reduction over LOG2_COL_A cycles.
          //   valid_out_reg[0] high  -> level 1: pair adjacent mult_stage products
          //   otherwise              -> subsequent levels: pair adjacent add_stage sums
          for (gv3 = 0 ; gv3 < HALF_MODIFIED_COL_A ; gv3++) begin: add_gb
            if ((2*gv3+1) < HALF_MODIFIED_COL_A) begin: reduce
              always_ff @(posedge clk)
                if (srst)
                  add_stage[((((gv1*COL_B)+gv2)*HALF_MODIFIED_COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
                else if (valid_out_reg[0])
                  add_stage[((((gv1*COL_B)+gv2)*HALF_MODIFIED_COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= mult_stage[((((gv1*COL_B)+gv2)*MODIFIED_COL_A)+(2*gv3))*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] + mult_stage[((((gv1*COL_B)+gv2)*MODIFIED_COL_A)+(2*gv3+1))*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH];
                else
                  add_stage[((((gv1*COL_B)+gv2)*HALF_MODIFIED_COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= add_stage[((((gv1*COL_B)+gv2)*HALF_MODIFIED_COL_A)+(2*gv3))*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] + add_stage[((((gv1*COL_B)+gv2)*HALF_MODIFIED_COL_A)+(2*gv3+1))*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH];
            end else begin: leaf
              always_ff @(posedge clk)
                if (srst)
                  add_stage[((((gv1*COL_B)+gv2)*HALF_MODIFIED_COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
                else if (valid_out_reg[0])
                  add_stage[((((gv1*COL_B)+gv2)*HALF_MODIFIED_COL_A)+gv3)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= mult_stage[((((gv1*COL_B)+gv2)*MODIFIED_COL_A)+(2*gv3))*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] + mult_stage[((((gv1*COL_B)+gv2)*MODIFIED_COL_A)+(2*gv3+1))*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH];
            end
          end

          // Output stage: capture the single accumulated sum (add_stage slot 0)
          always_ff @(posedge clk)
            if (srst)
              matrix_c[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= '0;
            else if (valid_out_reg[LOG2_COL_A])
              matrix_c[((gv1*COL_B)+gv2)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH] <= add_stage[((((gv1*COL_B)+gv2)*HALF_MODIFIED_COL_A)+0)*OUTPUT_DATA_WIDTH+:OUTPUT_DATA_WIDTH];
        end
      end
    end
  endgenerate

endmodule

module cvdp_copilot_mem_allocator #(
    parameter SIZE  = 4,
    parameter ADDRW = $clog2(SIZE)
) (
    input  wire             clk,
    input  wire             reset,

    input  wire             acquire_en,
    output wire [ADDRW-1:0] acquire_addr,

    input  wire             release_en,
    input  wire [ADDRW-1:0] release_addr,

    output wire             empty,
    output wire             full
);
    reg [SIZE-1:0] free_slots, free_slots_n;
    reg [ADDRW-1:0] acquire_addr_r;
    reg empty_r, full_r;
    wire [ADDRW-1:0] free_index;
    wire full_d;

    /* Leading zero counter instantiation */
    cvdp_leading_zero_cnt #(
        .DATA_WIDTH (SIZE),
        .REVERSE    (1)
        ) free_slots_sel (
            .data   (free_slots_n),
            .leading_zeros  (free_index),
            .all_zeros (full_d)
        );

    // Combinationally compute the next free_slots value.
    // acquire_en clears the currently-presented first-free slot;
    // release_en marks release_addr as free again.
    always @* begin
        free_slots_n = free_slots;
        if (acquire_en)
            free_slots_n[acquire_addr_r] = 1'b0;
        if (release_en)
            free_slots_n[release_addr]   = 1'b1;
    end

    // Sequential state / output registration.
    always @(posedge clk) begin
        if (reset) begin
            free_slots     <= {SIZE{1'b1}};
            acquire_addr_r <= {ADDRW{1'b0}};
            empty_r        <= 1'b1;
            full_r         <= 1'b0;
        end else begin
            free_slots     <= free_slots_n;
            acquire_addr_r <= free_index;      // precomputed first-free slot, ready next cycle
            empty_r        <= &free_slots_n;    // all slots free
            full_r         <= full_d;           // no slots free (all_zeros)
        end
    end

    assign acquire_addr = acquire_addr_r;
    assign empty        = empty_r;
    assign full         = full_r;

endmodule

module cvdp_leading_zero_cnt #(
    parameter DATA_WIDTH = 32,
    parameter REVERSE = 0
)(
    input  [DATA_WIDTH -1:0] data,
    output  [$clog2(DATA_WIDTH)-1:0] leading_zeros,
    output all_zeros
);
    localparam NIBBLES_NUM = DATA_WIDTH/4 ;
    reg [NIBBLES_NUM-1 :0] all_zeros_flag ;
    reg [1:0]  zeros_cnt_per_nibble [NIBBLES_NUM-1 :0]  ;

    genvar i;
    integer k ;
    // Assign data/nibble
    reg [3:0]  data_per_nibble [NIBBLES_NUM-1 :0]  ;
    generate
        for (i=0; i < NIBBLES_NUM ; i=i+1) begin
            always @* begin
                data_per_nibble[i] = data[(i*4)+3: (i*4)] ;
            end
        end
    endgenerate

    generate
        for (i=0; i < NIBBLES_NUM ; i=i+1) begin
            if (REVERSE) begin
                always @* begin
                        zeros_cnt_per_nibble[i] [1] = ~(data_per_nibble[i][1] | data_per_nibble[i][0]);
                        zeros_cnt_per_nibble[i] [0] = (~data_per_nibble[i][0]) &
                                                      ((~data_per_nibble[i][2]) | data_per_nibble[i][1]);
                        all_zeros_flag[i] = (data_per_nibble[i] == 4'b0000);
                end
            end else begin
                always @* begin
                    zeros_cnt_per_nibble[NIBBLES_NUM-1-i][1] = ~(data_per_nibble[i][3] | data_per_nibble[i][2]);
                    zeros_cnt_per_nibble[NIBBLES_NUM-1-i][0] = (~data_per_nibble[i][3]) &
                                     ((~data_per_nibble[i][1]) | data_per_nibble[i][2]);

                    all_zeros_flag[NIBBLES_NUM-1-i] = (data_per_nibble[i] == 4'b0000);
                end
            end
        end
    endgenerate



    reg [$clog2(NIBBLES_NUM)-1:0] index ;
    reg [1:0]    choosen_nibbles_zeros_count ;
    reg [ $clog2(NIBBLES_NUM*4)-1:0] zeros_count_result ;
    wire [NIBBLES_NUM-1:0]         all_zeros_flag_decoded;

    assign all_zeros_flag_decoded[0] = all_zeros_flag[0] ;
    genvar j;
        generate
            for (j=1; j < NIBBLES_NUM; j=j+1) begin
                assign all_zeros_flag_decoded[j] = all_zeros_flag_decoded[j-1] & all_zeros_flag[j];
            end
        endgenerate

    always@ * begin
        index = 0 ;
        for ( k =0 ; k< NIBBLES_NUM ; k =k +1) begin
            index = index + all_zeros_flag_decoded[k] ;
        end
    end

    always@* begin
        choosen_nibbles_zeros_count = zeros_cnt_per_nibble[index]  ;
        zeros_count_result = choosen_nibbles_zeros_count + (index <<2) ;
    end

    assign leading_zeros =  zeros_count_result ;
    assign all_zeros = (data ==0) ;

endmodule


