//============================================================================
// microcode_sequencer : 5-bit instruction -> 4-bit control-store address
//   Hierarchical microcoded bit-slice sequencer with a LIFO stack,
//   program counter, arithmetic unit (ripple-carry full adder + aux reg),
//   instruction decoder and result register.
//============================================================================

//----------------------------------------------------------------------------
// Instruction decoder
//----------------------------------------------------------------------------
module instruction_decoder (
    input  wire [4:0] instr_in,
    input  wire       cc_in,      // condition code (active low), unused by base opcodes
    input  wire       instr_en,   // active LOW : decoder enabled when 0
    output reg        cen,        // active high : allow full_adder carry-in
    output reg        rst,        // active high : reset stack pointer
    output reg        oe,         // active high : full_adder output -> d_out
    output reg        inc,        // active high : allow pc increment
    output reg        rsel,       // active high : aux_reg_mux select
    output reg        rce,        // active high : aux_reg chip enable
    output reg        pc_mux_sel, // 1 -> full_adder data, 0 -> current pc
    output reg  [1:0] a_mux_sel,
    output reg  [1:0] b_mux_sel,
    output reg        push,
    output reg        pop,
    output reg        src_sel,    // stack data mux select
    output reg        stack_we,
    output reg        stack_re,
    output reg        out_ce
);
    always @(*) begin
        // inactive defaults
        cen        = 1'b0;
        rst        = 1'b0;
        oe         = 1'b0;
        inc        = 1'b0;
        rsel       = 1'b0;
        rce        = 1'b0;
        pc_mux_sel = 1'b0;
        a_mux_sel  = 2'b10;   // constant 0
        b_mux_sel  = 2'b10;   // constant 0
        push       = 1'b0;
        pop        = 1'b0;
        src_sel    = 1'b0;
        stack_we   = 1'b0;
        stack_re   = 1'b0;
        out_ce     = 1'b0;

        if (instr_en == 1'b0) begin
            case (instr_in)
                5'b00000: begin // PRST : d_out forced 0, load 0/1 into PC, reset SP
                    oe         = 1'b0;
                    rst        = 1'b1;
                    inc        = 1'b1;
                    pc_mux_sel = 1'b1;   // load full_adder(=0) into incrementer
                    a_mux_sel  = 2'b10;  // 0
                    b_mux_sel  = 2'b10;  // 0
                end
                5'b00001: begin // Fetch PC : d_out = PC
                    oe        = 1'b1;
                    inc       = 1'b1;
                    a_mux_sel = 2'b10;   // 0
                    b_mux_sel = 2'b00;   // pc_data
                    out_ce    = 1'b1;
                end
                5'b00010: begin // Fetch R : d_out = aux_reg
                    oe        = 1'b1;
                    inc       = 1'b1;
                    a_mux_sel = 2'b01;   // register_data
                    b_mux_sel = 2'b10;   // 0
                    out_ce    = 1'b1;
                end
                5'b00011: begin // Fetch D : d_out = d_in
                    oe        = 1'b1;
                    inc       = 1'b1;
                    a_mux_sel = 2'b00;   // data_in
                    b_mux_sel = 2'b10;   // 0
                    out_ce    = 1'b1;
                end
                5'b00100: begin // Fetch R + D : d_out = d_in + aux_reg (+carry)
                    oe        = 1'b1;
                    cen       = 1'b1;
                    inc       = 1'b1;
                    a_mux_sel = 2'b00;   // data_in
                    b_mux_sel = 2'b11;   // register_data
                    out_ce    = 1'b1;
                end
                5'b01011: begin // Push PC : write PC to top-of-stack, SP++
                    oe        = 1'b0;
                    inc       = 1'b1;
                    push      = 1'b1;
                    stack_we  = 1'b1;
                    src_sel   = 1'b0;    // select pc data
                    b_mux_sel = 2'b00;
                end
                5'b01110: begin // Pop PC : read top-of-stack -> d_out, SP--
                    oe        = 1'b1;
                    inc       = 1'b1;
                    pop       = 1'b1;
                    stack_re  = 1'b1;
                    a_mux_sel = 2'b10;   // 0
                    b_mux_sel = 2'b01;   // stack_data
                    out_ce    = 1'b1;
                end
                default: begin
                    oe  = 1'b0;
                    inc = 1'b0;
                end
            endcase
        end
    end
endmodule

//----------------------------------------------------------------------------
// LIFO stack  (stack_pointer + stack_ram + stack_data_mux)
//----------------------------------------------------------------------------
module lifo_stack (
    input  wire       clk,
    input  wire [3:0] stack_data1_in,  // d_in
    input  wire [3:0] stack_data2_in,  // pc
    input  wire       stack_reset,
    input  wire       stack_push,
    input  wire       stack_pop,
    input  wire       stack_mux_sel,   // 1 -> data1 (d_in), 0 -> data2 (pc)
    input  wire       stack_we,
    input  wire       stack_re,
    output reg  [3:0] stack_data_out,
    output wire       full_o,
    output wire       empty_o
);
    reg [4:0] sp;
    reg [3:0] mem [0:16];

    wire [3:0] mux_out = stack_mux_sel ? stack_data1_in : stack_data2_in;

    assign full_o  = (sp == 5'd16);
    assign empty_o = (sp == 5'd0);

    initial begin
        sp             = 5'b00000;
        stack_data_out = 4'b0000;
    end

    always @(posedge clk) begin
        if (stack_reset) begin
            sp <= 5'b00000;
        end else if (stack_push && !full_o) begin
            if (stack_we)
                mem[sp] <= mux_out;
            sp <= sp + 5'd1;
        end else if (stack_pop && !empty_o) begin
            if (stack_re)
                stack_data_out <= mem[sp - 5'd1];
            sp <= sp - 5'd1;
        end
    end
endmodule

//----------------------------------------------------------------------------
// Program counter  (pc_mux + pc_incrementer + pc_reg)
//----------------------------------------------------------------------------
module program_counter (
    input  wire       clk,
    input  wire [3:0] full_adder_data_i,
    input  wire       pc_c_in,
    input  wire       inc,
    input  wire       pc_mux_sel,   // 1 -> full_adder data, 0 -> current pc
    output wire [3:0] pc_out,
    output wire       pc_c_out
);
    reg  [3:0] pc_reg_q;
    wire [3:0] pc_mux_out = pc_mux_sel ? full_adder_data_i : pc_reg_q;
    wire [4:0] pc_inc     = {1'b0, pc_mux_out} + (inc ? {4'b0000, pc_c_in} : 5'b00000);

    initial pc_reg_q = 4'b0000;

    always @(posedge clk)
        pc_reg_q <= pc_inc[3:0];

    assign pc_out   = pc_reg_q;
    assign pc_c_out = pc_inc[4];
endmodule

//----------------------------------------------------------------------------
// Microcode arithmetic  (aux_reg_mux + aux_reg + a_mux + b_mux + full_adder)
//----------------------------------------------------------------------------
module microcode_arithmetic (
    input  wire       clk,
    input  wire [3:0] fa_in,          // full_adder sum fed back
    input  wire [3:0] d_in,
    input  wire [3:0] stack_data_in,
    input  wire [3:0] pc_data_in,
    input  wire       reg_en,         // r_en, ACTIVE LOW
    input  wire       rce,            // ACTIVE HIGH aux_reg chip enable
    input  wire       cen,            // ACTIVE HIGH allow carry-in
    input  wire [1:0] a_mux_sel,
    input  wire [1:0] b_mux_sel,
    input  wire       arith_cin,
    input  wire       rsel,           // ACTIVE HIGH aux_reg_mux select
    output wire       arith_cout,
    output wire [3:0] d_out
);
    // aux_reg_mux : select = rsel & ~reg_en ; 1 -> fa_in, 0 -> d_in
    wire       mux_sel     = rsel & ~reg_en;
    wire [3:0] reg_mux_out = mux_sel ? fa_in : d_in;

    // aux_reg enable : rce | ~reg_en
    wire       reg_ce = rce | ~reg_en;
    reg  [3:0] reg_out;
    initial reg_out = 4'b0000;
    always @(posedge clk)
        if (reg_ce)
            reg_out <= reg_mux_out;

    // a_mux
    reg [3:0] a_mux_out;
    always @(*) begin
        case (a_mux_sel)
            2'b00:   a_mux_out = d_in;
            2'b01:   a_mux_out = reg_out;
            default: a_mux_out = 4'b0000;   // 2'b10 -> 0
        endcase
    end

    // b_mux
    reg [3:0] b_mux_out;
    always @(*) begin
        case (b_mux_sel)
            2'b00:   b_mux_out = pc_data_in;
            2'b01:   b_mux_out = stack_data_in;
            2'b10:   b_mux_out = 4'b0000;
            2'b11:   b_mux_out = reg_out;
            default: b_mux_out = 4'b0000;
        endcase
    end

    // ripple-carry full adder with optional carry-in
    wire [4:0] add = {1'b0, a_mux_out} + {1'b0, b_mux_out}
                     + (cen ? {4'b0000, arith_cin} : 5'b00000);

    assign d_out      = add[3:0];
    assign arith_cout = add[4];
endmodule

//----------------------------------------------------------------------------
// Result register
//----------------------------------------------------------------------------
module result_register (
    input  wire       clk,
    input  wire [3:0] data_in,
    input  wire       out_ce,
    output reg  [3:0] data_out
);
    initial data_out = 4'b0000;
    always @(posedge clk)
        if (out_ce)
            data_out <= data_in;
endmodule

//----------------------------------------------------------------------------
// Top level
//----------------------------------------------------------------------------
module microcode_sequencer (
    input  wire       clk,
    input  wire       c_n_in,     // carry-in for ripple carry adder
    input  wire       c_inc_in,   // carry-in for pc incrementer
    input  wire       r_en,       // ACTIVE LOW aux register enable
    input  wire       cc,         // ACTIVE LOW condition code
    input  wire       ien,        // ACTIVE LOW instruction enable
    input  wire [3:0] d_in,
    input  wire [4:0] instr_in,
    input  wire       oen,        // ACTIVE LOW output enable
    output wire [3:0] d_out,
    output wire       c_n_out,
    output wire       c_inc_out,
    output wire       full,
    output wire       empty
);
    // decoder control lines
    wire        cen, rst, oe_dec, inc, rsel, rce, pc_mux_sel;
    wire [1:0]  a_mux_sel, b_mux_sel;
    wire        push, pop, src_sel, stack_we, stack_re, out_ce;

    // datapath nets
    wire [3:0]  arith_sum;
    wire        arith_cout;
    wire [3:0]  pc_out;
    wire        pc_c_out;
    wire [3:0]  stack_data_out;
    wire [3:0]  res_out;

    instruction_decoder u_dec (
        .instr_in   (instr_in),
        .cc_in      (cc),
        .instr_en   (ien),
        .cen        (cen),
        .rst        (rst),
        .oe         (oe_dec),
        .inc        (inc),
        .rsel       (rsel),
        .rce        (rce),
        .pc_mux_sel (pc_mux_sel),
        .a_mux_sel  (a_mux_sel),
        .b_mux_sel  (b_mux_sel),
        .push       (push),
        .pop        (pop),
        .src_sel    (src_sel),
        .stack_we   (stack_we),
        .stack_re   (stack_re),
        .out_ce     (out_ce)
    );

    lifo_stack u_stack (
        .clk            (clk),
        .stack_data1_in (d_in),
        .stack_data2_in (pc_out),
        .stack_reset    (rst),
        .stack_push     (push),
        .stack_pop      (pop),
        .stack_mux_sel  (src_sel),
        .stack_we       (stack_we),
        .stack_re       (stack_re),
        .stack_data_out (stack_data_out),
        .full_o         (full),
        .empty_o        (empty)
    );

    program_counter u_pc (
        .clk               (clk),
        .full_adder_data_i (arith_sum),
        .pc_c_in           (c_inc_in),
        .inc               (inc),
        .pc_mux_sel        (pc_mux_sel),
        .pc_out            (pc_out),
        .pc_c_out          (pc_c_out)
    );

    microcode_arithmetic u_arith (
        .clk           (clk),
        .fa_in         (arith_sum),
        .d_in          (d_in),
        .stack_data_in (stack_data_out),
        .pc_data_in    (pc_out),
        .reg_en        (r_en),
        .rce           (rce),
        .cen           (cen),
        .a_mux_sel     (a_mux_sel),
        .b_mux_sel     (b_mux_sel),
        .arith_cin     (c_n_in),
        .rsel          (rsel),
        .arith_cout    (arith_cout),
        .d_out         (arith_sum)
    );

    result_register u_res (
        .clk      (clk),
        .data_in  (arith_sum),
        .out_ce   (out_ce),
        .data_out (res_out)
    );

    // output-enable gating : full_adder result appears at d_out when
    // decoder output-enable is high and top-level oen (active low) is low.
    assign d_out     = (oe_dec & ~oen) ? arith_sum : 4'b0000;
    assign c_n_out   = arith_cout;
    assign c_inc_out = pc_c_out;
endmodule


