module signed_sequential_booth_multiplier #(parameter WIDTH = 8) (
    input  wire signed [WIDTH-1:0] A,
    input  wire signed [WIDTH-1:0] B,
    input  wire clk,
    input  wire rst,
    input  wire start,
    output reg  signed [2*WIDTH-1:0] result,
    output reg done
);

    // FSM states
    typedef enum logic [2:0] {
        IDLE     = 3'b000,
        ENCODE   = 3'b001,
        PARTIAL  = 3'b010,
        ADDITION = 3'b011,
        DONE     = 3'b100
    } state_t;

    state_t state, next_state;

    // Registers for control and data signals
    reg signed [2*WIDTH-1:0] partial_products [0:WIDTH/2-1];
    reg signed [2*WIDTH-1:0] multiplicand;
    reg signed [WIDTH:0] booth_bits;
    reg signed [2*WIDTH-1:0] accumulator;
    reg [2:0] encoding_bits [0:WIDTH/2-1];
    reg [$clog2(WIDTH/2):0] addition_counter; // Counter for addition cycles
    integer i;

    // State machine: Sequential process for state transitions
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // State machine: Combinational process for next-state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start) begin
                    next_state = ENCODE;
                end else begin
                    next_state = IDLE;
                end
            end

            ENCODE: begin
                next_state = PARTIAL;
            end

            PARTIAL: begin
                next_state = ADDITION;
            end

            ADDITION: begin
                // Accumulate one partial product per clock cycle. Remain in
                // ADDITION until the last partial product has been added, so
                // the addition phase lasts WIDTH/2 cycles (total latency
                // WIDTH/2 + 4 clocks from start to done).
                if (addition_counter == (WIDTH/2 - 1)) begin
                    next_state = DONE;
                end else begin
                    next_state = ADDITION;
                end
            end

            DONE: begin
                if (!start) begin
                    next_state = IDLE;
                end else begin
                    next_state = DONE;
                end
            end

            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Signal assignments: Perform operations based on current state
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            done <= 0;
            result <= 0;
            accumulator <= 0;
            addition_counter <= 0;
            multiplicand <= 0;
            booth_bits <= 0;
            for (i = 0; i < WIDTH/2; i = i + 1) begin
                encoding_bits[i] <= 0;
                partial_products[i] <= 0;
            end
        end else begin
            case (state)
                IDLE: begin
                    // Prepare for new computation
                    done <= 0;
                    result <= 0;
                    if (start) begin
                        multiplicand <= {{(WIDTH){A[WIDTH-1]}}, A}; // Sign-extend A
                        booth_bits <= {B, 1'b0};
                        accumulator <= 0;
                        addition_counter <= 0;
                        for (i = 0; i < WIDTH/2; i = i + 1) begin
                            partial_products[i] <= 0;
                        end
                    end
                end

                ENCODE: begin
                    // Extract 3-bit Booth segments
                    for (i = 0; i < WIDTH/2; i = i + 1) begin
                        encoding_bits[i] <= booth_bits[2*i +: 3];
                    end
                end

                PARTIAL: begin
                    // Generate partial products based on Booth encoding
                    for (i = 0; i < WIDTH/2; i = i + 1) begin
                        case (encoding_bits[i])
                            3'b001, 3'b010: partial_products[i] <= (multiplicand << (2 * i));
                            3'b011:         partial_products[i] <= ((multiplicand << 1) << (2 * i));
                            3'b100:         partial_products[i] <= -((multiplicand << 1) << (2 * i));
                            3'b101, 3'b110: partial_products[i] <= -(multiplicand << (2 * i));
                            default:        partial_products[i] <= 0;
                        endcase
                    end
                    // Prepare the accumulation phase with a clean start so a
                    // subsequent multiplication is not corrupted by prior state.
                    accumulator <= 0;
                    addition_counter <= 0;
                end

                ADDITION: begin
                    // Add exactly one partial product per clock cycle.
                    accumulator <= accumulator + partial_products[addition_counter];
                    addition_counter <= addition_counter + 1;
                end

                DONE: begin
                    // Output the result
                    result <= accumulator;
                    done <= 1;
                end
            endcase
        end
    end
endmodule

module pipelined_modified_booth_multiplier (
    input clk,
    input rst,
    input start,
    input signed [15:0] X,
    input signed [15:0] Y,
    output reg signed  [31:0] result,
    output reg done
);

    reg signed [31:0] partial_products [0:7];
    reg signed [15:0] X_reg, Y_reg;
    reg [4:0] valid_reg; // Extended valid register for more granular state control

    integer i;

    // Registers for pipelining the addition stages
    reg signed [31:0] s1, s2, s3, s4;
    reg signed [31:0] temp_products1, temp_products2;

    always @(posedge clk or posedge rst)
    begin
        if (rst)
        begin
            X_reg <= 16'd0;
            Y_reg <= 16'd0;
            valid_reg <= 5'd0;
            done <= 0;
            for (i = 0; i < 8; i = i + 1)
            begin
                partial_products[i] <= 32'd0;
            end
            s1 <= 0; s2 <= 0; s3 <= 0; s4 <= 0;
            temp_products1 <= 0; temp_products2 <= 0;
            result <= 32'd0;
            done <= 1'b0;
        end
        else
        begin
            if (start && !valid_reg[0]) begin
                X_reg <= X;
                Y_reg <= Y;
                valid_reg[0] <= 1;  // Initiate state 1
            end
            else
              valid_reg[0] <= 0;  // Initiate state 1

            // Process Booth multiplication
            if (valid_reg[0]) begin
                for (i = 0; i < 8; i = i + 1) begin
                    case ({Y_reg[2*i+1], Y_reg[2*i], (i == 0) ? 1'b0 : Y_reg[2*i-1]})
                        3'b000, 3'b111: partial_products[i] <= 32'd0;
                        3'b001, 3'b010: partial_products[i] <= {{16{X_reg[15]}}, X_reg} << (2*i);
                        3'b011: partial_products[i] <= {{16{X_reg[15]}}, X_reg} << (2*i + 1);
                        3'b100: partial_products[i] <= -({{16{X_reg[15]}}, X_reg} << (2*i + 1));
                        3'b101, 3'b110: partial_products[i] <= -({{16{X_reg[15]}}, X_reg} << (2*i));
                        default: partial_products[i] <= 32'd0;
                    endcase
                end
                valid_reg[1] <= 1; // State 1 done, mark State 2 as ready
                valid_reg[0] <= 0; // Reset state 1 active flag
            end
            else
              valid_reg[1] <= 0; // State 1 done, mark State 2 as ready

            // State 3: Partial Summation
            if (valid_reg[1]) begin
                s1 <= partial_products[0] + partial_products[1] + partial_products[2];
                s2 <= partial_products[3] + partial_products[4] + partial_products[5];

                valid_reg[2] <= 1; // State 3 done, mark State 4 as ready
                valid_reg[1] <= 0; // Clear state 2 active flag
            end
            else
              valid_reg[2] <= 0; // State 3 done, mark State 4 as ready

            // State 4: Sum of Sums
            if (valid_reg[2]) begin
                s3 <= s1 + s2;
                s4 <= partial_products[6] + partial_products[7];

                valid_reg[3] <= 1; // State 4 done, mark State 5 as ready
                valid_reg[2] <= 0; // Clear state 3 active flag
            end
            else
              valid_reg[3] <= 0; // State 4 done, mark State 5 as ready


            // State 5: Final Result
            if (valid_reg[3]) begin
                result <= s3 + s4;
                done <= 1;  // Output done signal
                valid_reg[3] <= 0; // Reset state 5 active flag after result computation
            end
            else
            begin
              result <= 0;
              done <= 1'b0;
            end

        end
    end

endmodule

module montgomery_redc #
(
    parameter N = 7,
    parameter R = 8,
    parameter R_INVERSE = 1,
    parameter NWIDTH = $clog2(N),
    parameter TWIDTH = $clog2(N*R)
)(
    input  wire [TWIDTH-1:0] T,
    output wire [NWIDTH-1:0] result
);
    // Derived parameters
    localparam RWIDTH = $clog2(R)+1;
    // R is a power of 2, so a value in [0, R-1] occupies exactly $clog2(R) bits.
    // T mod R = low LOGR bits of T; division by R = right shift by LOGR.
    localparam LOGR = $clog2(R);

    localparam [RWIDTH-1:0] N_PRIME = (R * R_INVERSE - 1) / N;

    wire [RWIDTH-1:0] T_mod_R;
    wire [2*RWIDTH-1:0] T_mod_R_X_N_PRIME;
    wire [RWIDTH-1:0] m;
    wire [NWIDTH:0] t;

    assign T_mod_R = T[LOGR-1:0];

    assign T_mod_R_X_N_PRIME = T_mod_R * N_PRIME;

    assign m = T_mod_R_X_N_PRIME[LOGR-1:0];

    assign t = (T + m * N) >> LOGR;

    assign result = (t >= N) ? (t - N) : t;

endmodule

module montgomery_mult #
(
    parameter N = 7,
    parameter R = 8,
    parameter R_INVERSE = 1,
    parameter NWIDTH = $clog2(N)
    )(
    input clk ,
    input rst_n,
    input  wire [NWIDTH-1:0] a,b,
    input valid_in,
    output wire [NWIDTH-1:0] result ,
    output valid_out
);

    // Fix (Issue 1): to transform an input into Montgomery form the reduction
    // must be fed with (input * R^2 mod N), not (input * R mod N).  Using
    // (R mod N) makes redc(a*(R mod N)) == a (an identity), which drops one
    // factor of R and makes the final output equal redc(expected).  R^2 mod N
    // yields a' = a*R mod N (true Montgomery form).
    localparam  R2_MOD_N = (R*R) % N     ;
    localparam  TWO_NWIDTH = $clog2(2*N)   ;
    localparam  TWIDTH   = $clog2(N*R)   ;

    reg [NWIDTH-1:0] a_q,b_q;

    wire [NWIDTH-1:0] a_redc, b_redc  ;
    reg [NWIDTH-1:0] a_redc_q, b_redc_q  ;

    // result' (Montgomery form of the product) = a*b*R mod N
    wire [NWIDTH-1:0] result_prime_d ;
    reg  [NWIDTH-1:0] result_prime_q ;

    // final result (standard form) = a*b mod N
    wire [NWIDTH-1:0] result_final_d ;
    reg  [NWIDTH-1:0] result_q ;

    reg valid_in_q, valid_in_q1, valid_in_q2;
    reg valid_out_q ;

    wire [TWIDTH-1:0] ar = a_q * R2_MOD_N ;
    wire [TWIDTH-1:0] br = b_q * R2_MOD_N ;

    wire [TWIDTH-1:0] a_redc_x_b_redc ;
    wire [TWIDTH-1:0] result_prime_ext ;


    assign a_redc_x_b_redc = a_redc_q * b_redc_q ;
    assign result_prime_ext = result_prime_q ;
    assign result = result_q;
    assign valid_out = valid_out_q ;

    // Fix (Issue 2): valid_out has a 4-cycle latency.  The corrected datapath
    // now has 4 register stages (a_q, a_redc_q, result_prime_q, result_q) so
    // the result is presented on the same cycle valid_out is asserted.
    always_ff @( posedge clk or negedge rst_n ) begin : valid_out_pipeline
        if (!rst_n) begin
            valid_in_q      <=  0 ;
            valid_in_q1     <=  0 ;
            valid_in_q2     <=  0 ;
            valid_out_q     <=  0 ;
        end else begin
            valid_in_q      <=  valid_in        ;
            valid_in_q1     <=  valid_in_q      ;
            valid_in_q2     <=  valid_in_q1     ;
            valid_out_q     <=  valid_in_q2     ;
        end
    end

    always_ff @( posedge clk or negedge rst_n ) begin : input_registers
        if (!rst_n) begin
            a_q <= 0 ;
            b_q <= 0 ;
        end else begin
            if(valid_in) begin
                a_q <= a ;
                b_q <= b ;
            end
        end
    end

    always_ff @( posedge clk or negedge rst_n ) begin : a_b_reduction_pipeline
        if (!rst_n) begin
            a_redc_q <= 0 ;
            b_redc_q <= 0 ;
        end else begin
            a_redc_q <= a_redc ;
            b_redc_q <= b_redc ;
        end
    end

    always_ff @( posedge clk or negedge rst_n ) begin : result_prime_register
        if (!rst_n) begin
            result_prime_q <= 0 ;
        end else begin
            result_prime_q <= result_prime_d ;
        end
    end

    always_ff @( posedge clk or negedge rst_n ) begin : output_register
        if (!rst_n) begin
            result_q <= 0 ;
        end else begin
            result_q <= result_final_d ;
        end
    end

    // Step 3: transform inputs to Montgomery form (a' = a*R mod N, b' = b*R mod N)
    montgomery_redc #
    (
        .N (N),
        .R (R),
        .R_INVERSE(R_INVERSE)
    ) ar2_redc (
        .T(ar),
        .result(a_redc)
    );

    montgomery_redc #
    (
        .N (N),
        .R (R),
        .R_INVERSE(R_INVERSE)
    ) br2_redc (
        .T(br),
        .result(b_redc)
    );

    // Step 4: modular multiply in Montgomery form -> result' = a*b*R mod N
    montgomery_redc #
    (
        .N (N),
        .R (R),
        .R_INVERSE(R_INVERSE)
    ) prod_redc (
        .T(a_redc_x_b_redc),
        .result(result_prime_d)
    );

    // Step 5 (fix): convert result' back to standard form -> result = a*b mod N
    montgomery_redc #
    (
        .N (N),
        .R (R),
        .R_INVERSE(R_INVERSE)
    ) final_redc (
        .T(result_prime_ext),
        .result(result_final_d)
    );



endmodule


module montgomery_redc #
(
    parameter N = 7,
    parameter R = 8,
    parameter R_INVERSE = 1,
    parameter NWIDTH = $clog2(N),
    parameter TWIDTH = $clog2(N*R)
)(
    input  wire [TWIDTH-1:0] T,
    output wire [NWIDTH-1:0] result
);
    // Derived parameters
    localparam RWIDTH = $clog2(R);
    localparam TWO_NWIDTH = $clog2(2*N)   ;
    localparam [RWIDTH-1:0] N_PRIME = (R * R_INVERSE - 1) / N;

    wire [RWIDTH-1:0] T_mod_R;
    wire [2*RWIDTH-1:0] T_mod_R_X_N_PRIME;
    wire [RWIDTH-1:0] m;
    wire [TWO_NWIDTH-1:0] t;

    assign T_mod_R = T[RWIDTH-1:0];

    assign T_mod_R_X_N_PRIME = T_mod_R * N_PRIME;

    assign m = T_mod_R_X_N_PRIME[RWIDTH-1:0];

    assign t = (T + m * N) >> RWIDTH;

    assign result = (t >= N) ? (t - N) : t;

endmodule

module moving_average (
    input  wire        clk,
    input  wire        reset,
    input  wire [11:0] data_in,
    output reg  [11:0] data_out
);

    // Memory buffer holding the most recent 8 samples.
    reg  [11:0] buffer [0:7];
    // Running sum of the 8 buffer entries. Max = 8*4095 = 32760 -> 16 bits (headroom).
    reg  [15:0] sum;
    integer i;

    always @(posedge clk) begin
        if (reset) begin
            // Clear output and buffer; average restarts fresh.
            for (i = 0; i < 8; i = i + 1)
                buffer[i] <= 12'd0;
            sum      <= 16'd0;
            data_out <= 12'd0;
        end else begin
            // Remove the oldest sample (buffer[7]) and add the new one.
            // buffer is zero-initialised, so with fewer than 8 valid samples
            // the empty slots contribute 0 and the average is still /8.
            sum <= sum - buffer[7] + data_in;

            // Shift the buffer: buffer[0] is newest, buffer[7] is oldest.
            for (i = 7; i > 0; i = i - 1)
                buffer[i] <= buffer[i-1];
            buffer[0] <= data_in;

            // Registered output: (new running sum) / 8. Max 32760/8 = 4095 (fits 12 bits).
            data_out <= (sum - buffer[7] + data_in) >> 3;
        end
    end

endmodule


