module moving_average(
    input wire clk,
    input wire reset,
    input wire enable,
    input  wire [11 : 0] data_in,
    output wire [11 : 0] data_out
);

reg [11 : 0] memory [7 : 0];
reg [14 : 0] sum;
reg [2  : 0] write_address;
wire [2 : 0] next_address;
reg [11 : 0] read_data;

assign next_address=write_address + 1'b1;
assign data_out=sum[14 : 3];

    // write current input to memory
    integer i;
    always @(posedge clk ) begin
        if (reset == 1'b1) begin
            for (i = 0 ;i < 8 ; i = i + 1 ) begin
                memory[i]<='h0;
            end
        end else if (enable == 1'b1) begin
            memory[write_address]<=data_in;
        end
    end

    // read the oldest element written to memory
    always @(posedge clk ) begin
        if(reset == 1'b1)begin
            read_data<='h0;
        end else if (enable == 1'b1) begin
            read_data<=memory[next_address];
        end
    end

    // increase the write address to move onto the next data
    always @(posedge clk ) begin
        if(reset == 1'b1)begin
            write_address<='h0;
        end else if (enable == 1'b1) begin
            write_address<=write_address + 1'b1;
        end
    end

    // calculate sum by adding the latest data to the sum and substracting the oldest data
    always @(posedge clk ) begin
        if(reset == 1'b1)begin
            sum<='h0;
        end else if (enable == 1'b1) begin
            sum<=sum+data_in-read_data;
        end
    end

endmodule

module mux_synch (

	input [7:0] data_in,   			//asynchronous data input
	input req,                  		//indicating that data is available at the data_in input
	input dst_clk,                 		//destination clock
	input src_clk,                 		//source clock
    	input nrst,                    		//asynchronous reset
	output reg [7:0] data_out ); 		//synchronized version of data_in to the destination clock domain

	// Synchronize the source-domain req pulse into the destination clock
	// domain using a two-flop synchronizer.  The synchronized version is
	// used as the multiplexer select line.
	wire sel;

	nff u_req_sync (
		.d_in    (req),
		.dst_clk (dst_clk),
		.rst     (nrst),
		.syncd   (sel)
	);

	// Recirculation multiplexer captured in the destination clock domain.
	// When the synchronized select is high the stable source data is
	// captured; otherwise the previously captured value is held.  The input
	// data must remain stable for at least three destination clock cycles
	// (2 for the synchronizer + 1 for the capture) for correct operation.
	always @(posedge dst_clk or negedge nrst) begin
		if (!nrst)
			data_out <= 8'b0000_0000;
		else if (sel)
			data_out <= data_in;
		else
			data_out <= data_out;
	end

endmodule

module nff  (

	input d_in,   						//input data that needs to be synchronized to the dst_clk domain.
	input dst_clk,     					//destination domain clock.
	input rst,         					//asynchronous active-low reset
	output reg  syncd 					//synced output, which is a 2-clock-cycle delayed version of d_in.
	                   );

	// Two flip-flops in series clocked by dst_clk with an active-low
	// asynchronous reset.  This minimizes metastability risk on the clock
	// domain crossing and yields a 2-cycle delayed, stable output.
	reg meta;

	always @(posedge dst_clk or negedge rst) begin
		if (!rst) begin
			meta  <= 1'b0;
			syncd <= 1'b0;
		end else begin
			meta  <= d_in;
			syncd <= meta;
		end
	end

endmodule

module mux_synch (

input [7:0] data_in,   			//asynchronous data input
input req,                  		//indicating that data is available at the data_in input
input dst_clk,                 		//destination clock
input src_clk,                 		//source clock
input nrst,                    		//asynchronous reset
output reg [7:0] data_out,              //synchronized version of data_in to the destination clock domain
output ack_out );


wire syncd_req,anded_req,syncd_ack;
reg syncd_req_1,ack;
reg syncd_ack_1;


nff  req_synch_0 (.d_in(req),.dst_clk(dst_clk),.rst(nrst),.syncd(syncd_req)) ;		//2-flop synchronizer for the enable input


always_ff @(posedge dst_clk)                     					//one clock cycle delayed synced_enable
begin
    syncd_req_1 <= syncd_req;
end

assign anded_req = (!syncd_req_1 && syncd_req);    					//posedge detector


always_ff @(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		data_out <= 8'b0;               					//forcing the output data_in to zero when an active-low asynchronous reset is detected.

	else if (anded_req==1'b1)
		data_out <= data_in;                    				//latching data_in to data_out when the enable signal is available.

	else
		data_out <= data_out;                   				//holds the data till next req comes.
end


// acknowledgment signal generation
// BUG FIX: ack crosses from the faster (dst) to the slower (src) clock domain.
// A single-cycle pulse can fall entirely between two src_clk active edges and
// be missed by the synchronizer. Drive ack as a held LEVEL that TOGGLES on each
// transfer so it is always captured regardless of the clock-frequency ratio.
always_ff@(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		ack <= 1'b0;

	else if (anded_req==1'b1)
		ack <= ~ack;								//toggle the level on every transfer (level held between transfers)

	else
		ack <= ack;								//hold the toggle level until the next transfer
end

//changing the clock domain of the ack signal (toggle level is safe across any ratio)
nff  enable_synch_1 (.d_in(ack),.dst_clk(src_clk),.rst(nrst),.syncd(syncd_ack)) ;

//edge detector circuit: regenerate a one-src-cycle ack_out pulse from the synchronized toggle
always_ff @(posedge src_clk or negedge nrst)
begin
	if(!nrst)
		syncd_ack_1 <= 1'b0;
	else
		syncd_ack_1 <= syncd_ack;
end

assign ack_out = syncd_ack ^ syncd_ack_1;						//pulse on either edge of the synchronized toggle


endmodule

module nff  (

	input d_in,   									//input data that needs to be synchronized to the dst_clk domain.
	input dst_clk,     								//destination domain clock.
	input rst,         								//asynchronous active-low reset
	output reg  syncd 								//synced output, which is a 2-clock-cycle delayed version of d_in.
	                   );

reg   dmeta;             								//register to hold output.



always@(posedge dst_clk or negedge rst)
begin
	if(!rst)              								//active-low asynchronous reset
  begin
    syncd <= 1'b0;      								//resetting the synced register to 0
    dmeta <= 1'b0;      								//resetting dmeta register to 0
  end
  else
  begin
    dmeta <= d_in;      								//passing d_in to dmeta
    syncd <= dmeta;     								//passing dmeta to syncd
  end
end

endmodule

module nbit_swizzling #(
    parameter integer DATA_WIDTH = 64
)(
    input  wire [DATA_WIDTH-1:0] data_in,
    input  wire [1:0]            sel,
    output reg  [DATA_WIDTH-1:0] data_out
);

    // Section sizes (compile-time constants) for each configuration.
    localparam integer SEG0 = DATA_WIDTH;      // sel=0 : 1 section  (full reverse)
    localparam integer SEG1 = DATA_WIDTH / 2;  // sel=1 : 2 sections
    localparam integer SEG2 = DATA_WIDTH / 4;  // sel=2 : 4 sections
    localparam integer SEG3 = DATA_WIDTH / 8;  // sel=3 : 8 sections

    integer s, j;

    // Combinational: reverse each equal-size section within its own position.
    // data_out[s*SEG + j] = data_in[s*SEG + (SEG-1-j)]
    always @(*) begin
        data_out = data_in; // default: output matches input
        case (sel)
            2'd0: begin
                for (s = 0; s < 1; s = s + 1)
                    for (j = 0; j < SEG0; j = j + 1)
                        data_out[s*SEG0 + j] = data_in[s*SEG0 + SEG0 - 1 - j];
            end
            2'd1: begin
                for (s = 0; s < 2; s = s + 1)
                    for (j = 0; j < SEG1; j = j + 1)
                        data_out[s*SEG1 + j] = data_in[s*SEG1 + SEG1 - 1 - j];
            end
            2'd2: begin
                for (s = 0; s < 4; s = s + 1)
                    for (j = 0; j < SEG2; j = j + 1)
                        data_out[s*SEG2 + j] = data_in[s*SEG2 + SEG2 - 1 - j];
            end
            2'd3: begin
                for (s = 0; s < 8; s = s + 1)
                    for (j = 0; j < SEG3; j = j + 1)
                        data_out[s*SEG3 + j] = data_in[s*SEG3 + SEG3 - 1 - j];
            end
            default: data_out = data_in;
        endcase
    end

endmodule


