module nbit_swizzling #(parameter DATA_WIDTH = 64)(
    input [DATA_WIDTH-1:0] data_in,                                        // Input data of size DATA_WIDTH
    input [1:0] sel,                                                       //  2-bit selection signal
    output reg [DATA_WIDTH:0] data_out                                     // Output data of size DATA_WIDTH + 1 (parity in MSB)
);

integer i;

always @(*) begin
    case(sel)
        2'b00: begin
            for (i = 0; i < DATA_WIDTH; i = i + 1) begin
                data_out[i] = data_in[DATA_WIDTH-1-i];
            end
        end

        2'b01: begin
            for (i = 0; i < DATA_WIDTH/2; i = i + 1) begin
                data_out[i]                = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i] = data_in[DATA_WIDTH-1-i];
            end
        end

        2'b10: begin
            for (i = 0; i < DATA_WIDTH/4; i = i + 1) begin
                data_out[i] = data_in[DATA_WIDTH/4-1-i];
                data_out[DATA_WIDTH/4 + i]   = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i]   = data_in[3*DATA_WIDTH/4-1-i];
                data_out[3*DATA_WIDTH/4 + i] = data_in[DATA_WIDTH-1-i];
            end
        end

        2'b11: begin
            for (i = 0; i < DATA_WIDTH/8; i = i + 1) begin
                data_out[i]                  = data_in[DATA_WIDTH/8-1-i];
                data_out[DATA_WIDTH/8 + i]   = data_in[DATA_WIDTH/4-1-i];
                data_out[DATA_WIDTH/4 + i]   = data_in[3*DATA_WIDTH/8-1-i];
                data_out[3*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i]   = data_in[5*DATA_WIDTH/8-1-i];
                data_out[5*DATA_WIDTH/8 + i] = data_in[3*DATA_WIDTH/4-1-i];
                data_out[3*DATA_WIDTH/4 + i] = data_in[7*DATA_WIDTH/8-1-i];
                data_out[7*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH-1-i];
            end
        end
        default: begin
            data_out = data_in;
        end
    endcase

    // Parity bit: XOR reduction of data_in, appended as the MSB of data_out
    data_out[DATA_WIDTH] = ^data_in;
end

endmodule

module nbit_swizzling #(parameter DATA_WIDTH = 64)(
    input [DATA_WIDTH-1:0] data_in,                                         // Input data of size DATA_WIDTH
    input [1:0] sel,                                                        //  2-bit selection signal
    output reg [DATA_WIDTH:0] data_out,                                     // Output data of size DATA_WIDTH
    output reg [DATA_WIDTH + $clog2(DATA_WIDTH):0] ecc_out                  // Hamming-encoded output with parity bits
);

localparam integer CLOG2_DW    = $clog2(DATA_WIDTH);
localparam integer PARITY_BITS = $clog2(DATA_WIDTH + CLOG2_DW + 1);
localparam integer CODE_LEN    = DATA_WIDTH + CLOG2_DW + 1;

integer i;
wire parity_bit;

assign parity_bit = ^data_in;

always @(*) begin
    case(sel)
        2'b00: begin
            for (i = 0; i < DATA_WIDTH; i = i + 1) begin
                data_out[i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b01: begin
            for (i = 0; i < DATA_WIDTH/2; i = i + 1) begin
                data_out[i]                = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b10: begin
            for (i = 0; i < DATA_WIDTH/4; i = i + 1) begin
                data_out[i] = data_in[DATA_WIDTH/4-1-i];
                data_out[DATA_WIDTH/4 + i]   = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i]   = data_in[3*DATA_WIDTH/4-1-i];
                data_out[3*DATA_WIDTH/4 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b11: begin
            for (i = 0; i < DATA_WIDTH/8; i = i + 1) begin
                data_out[i]                  = data_in[DATA_WIDTH/8-1-i];
                data_out[DATA_WIDTH/8 + i]   = data_in[DATA_WIDTH/4-1-i];
                data_out[DATA_WIDTH/4 + i]   = data_in[3*DATA_WIDTH/8-1-i];
                data_out[3*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i]   = data_in[5*DATA_WIDTH/8-1-i];
                data_out[5*DATA_WIDTH/8 + i] = data_in[3*DATA_WIDTH/4-1-i];
                data_out[3*DATA_WIDTH/4 + i] = data_in[7*DATA_WIDTH/8-1-i];
                data_out[7*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end
        default: begin
            data_out = data_in;
            data_out[DATA_WIDTH] = parity_bit;
        end
    endcase
end

// -----------------------------------------------------------------------
// Hamming ECC generation for data_in
//   * codeword positions are 1-indexed (position p == ecc_out[p-1])
//   * positions that are a power of two (1,2,4,8,16,...) hold parity bits
//   * all remaining positions are filled with data_in bits, in order
//     (data_in[0] -> first data position, data_in[1] -> next, ...)
//   * each parity bit uses even parity over the data positions it covers
// -----------------------------------------------------------------------
integer j;
integer k;
integer dcount;
reg [CODE_LEN-1:0] code;
reg par;

always @(*) begin
    code   = {CODE_LEN{1'b0}};
    dcount = 0;

    // place data bits into the non-power-of-two positions
    for (j = 1; j <= CODE_LEN; j = j + 1) begin
        if ((j & (j-1)) != 0) begin
            code[j-1] = data_in[dcount];
            dcount    = dcount + 1;
        end
    end

    // compute each parity bit at position 2^k
    for (k = 0; k < PARITY_BITS; k = k + 1) begin
        par = 1'b0;
        for (j = 1; j <= CODE_LEN; j = j + 1) begin
            if ((((j >> k) & 1) == 1) && ((j & (j-1)) != 0)) begin
                par = par ^ code[j-1];
            end
        end
        code[(1 << k) - 1] = par;
    end

    ecc_out = code;
end

endmodule

module neuromorphic_array #(
    parameter NEURONS = 8,       // Number of neurons
    parameter INPUTS = 8,        // Number of inputs
    parameter OUTPUTS = 8         // Number of outputs
) (
    input  logic [7:0] ui_in,       // Control input
    input logic [7:0] uio_in,      // Input data
    output logic [7:0] uo_out,     // Output data
    input logic clk,                // Clock
    input logic rst_n               // Reset
);
    // Internal wires for neuron outputs
    logic [7:0] neuron_outputs [0:NEURONS-1];

    // Instantiate the neurons.  Each neuron stores its own 8-bit state and
    // updates it (when the control bit ui_in[0] is high) with the data at its
    // seq_in.  The first neuron is fed the module input data (uio_in); every
    // subsequent neuron is fed the stored value of the neuron before it, so
    // data propagates sequentially through the array.
    genvar i;
    generate
    // Write RTL to instantiate  single_neuron_dut according to the number of neurons
        for (i = 0; i < NEURONS; i = i + 1) begin : neuron_gen
            if (i == 0) begin : first_neuron
                single_neuron_dut u_neuron (
                    .clk     (clk),
                    .rst_n   (rst_n),
                    .control (ui_in[0]),
                    .seq_in  (uio_in),
                    .seq_out (neuron_outputs[i])
                );
            end else begin : chain_neuron
                single_neuron_dut u_neuron (
                    .clk     (clk),
                    .rst_n   (rst_n),
                    .control (ui_in[0]),
                    .seq_in  (neuron_outputs[i-1]),
                    .seq_out (neuron_outputs[i])
                );
            end
        end
    endgenerate

    // Combine outputs from the last neuron
    assign uo_out = neuron_outputs[NEURONS-1]; // Output from the last neuron

endmodule

module single_neuron_dut (
    input logic clk,
    input logic rst_n,
    input logic control,        // Control signal
    input logic [7:0] seq_in,   // Input sequence
    output logic [7:0] seq_out   // Output sequence
);
    // Insert local variables and logic here
    // 8-bit internal state, updated with seq_in when control is high,
    // otherwise held.  Cleared to zero on active-low asynchronous reset.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            seq_out <= 8'b0;
        else if (control)
            seq_out <= seq_in;
        else
            seq_out <= seq_out;
    end
endmodule

module one_hot_gen #(
    parameter NS_A = 'd8,
    parameter NS_B = 'd4
) (
    input  logic                 clk,
    input  logic                 rst_async_n,
    input  logic [1:0]           i_config,
    input  logic                 i_start,
    output logic                 o_ready,
    output logic [NS_A+NS_B-1:0] o_address_one_hot
);

typedef enum logic [1:0] {IDLE = 2'b00, REGION_A = 2'b01, REGION_B = 2'b10} state_t;

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
state_t state_ff, state_nx;
logic [NS_A-1:0] region_A_ff, region_A_nx;
logic [NS_B-1:0] region_B_ff, region_B_nx;
logic A_to_B, B_to_A;

// Input register
logic [1:0] config_ff;

// ----------------------------------------
// - Wire connections
// ----------------------------------------

// Region change flags
assign A_to_B = ( config_ff[1] & ~config_ff[0]);
assign B_to_A = ( config_ff[1] &  config_ff[0]);

// Output assignment (Region A concatenated with Region B)
assign o_address_one_hot = {region_A_ff, region_B_ff};

// ----------------------------------------
// - Registers
// ----------------------------------------

always_ff @(posedge clk or negedge rst_async_n) begin : input_register
    if(~rst_async_n) begin
        config_ff <= 0;
    end else begin
        if(i_start && state_ff == IDLE) begin
            config_ff <= i_config;
        end
    end
end

always_ff @(posedge clk or negedge rst_async_n) begin : reset_regs
    if(~rst_async_n) begin
        o_ready <= 1;
        state_ff <= IDLE;
        region_A_ff <= {NS_A{1'b0}};
        region_B_ff <= {NS_B{1'b0}};
    end else begin
        o_ready <= (state_nx == IDLE);
        state_ff <= state_nx;
        region_A_ff <= region_A_nx;
        region_B_ff <= region_B_nx;
    end
end

// ----------------------------------------
// - One-hot address generation
// ----------------------------------------

always_comb begin : drive_regions
    case(state_ff)
        IDLE: begin
            if(i_start) begin
                region_A_nx[NS_A-1] = (~i_config[0]);
                region_B_nx[NS_B-1] = (i_config[0]);
            end else begin
                region_A_nx[NS_A-1] = 1'b0;
                region_B_nx[NS_B-1] = 1'b0;
            end

            region_A_nx[NS_A-2:0] = {(NS_A-1){1'b0}};
            region_B_nx[NS_B-2:0] = {(NS_B-1){1'b0}};
        end
        REGION_A: begin
            region_A_nx = region_A_ff >> 1;

            if(region_A_ff[0]) begin
                region_B_nx[NS_B-1] = A_to_B;
            end else begin
                region_B_nx[NS_B-1] = 1'b0;
            end
            region_B_nx[NS_B-2:0] = {(NS_B-1){1'b0}};
        end
        REGION_B: begin
            if(region_B_ff[0]) begin
                region_A_nx[NS_A-1] = B_to_A;
            end else begin
                region_A_nx[NS_A-1] = 1'b0;
            end
            region_A_nx[NS_A-2:0] = {(NS_A-1){1'b0}};

            region_B_nx = region_B_ff >> 1;
        end
        default: begin
            region_A_nx = {NS_A{1'b0}};
            region_B_nx = {NS_B{1'b0}};
        end
    endcase
end

// ----------------------------------------
// - FSM update
// ----------------------------------------

always_comb begin : update_state
    case(state_ff)
        IDLE: begin
            if(i_start) begin
                if(i_config[0]) begin
                    state_nx = REGION_B;
                end else begin
                    state_nx = REGION_A;
                end
            end else begin
                state_nx = IDLE;
            end
        end
        REGION_A: begin
            if(region_A_ff[0]) begin
                if(A_to_B) begin
                    state_nx = REGION_B;
                end else begin
                    state_nx = IDLE;
                end
            end else begin
                state_nx = REGION_A;
            end
        end
        REGION_B: begin
            if(region_B_ff[0]) begin
                if(B_to_A) begin
                    state_nx = REGION_A;
                end else begin
                    state_nx = IDLE;
                end
            end else begin
                state_nx = REGION_B;
            end
        end
        default: begin
            state_nx = IDLE;
        end
    endcase
end

endmodule : one_hot_gen

module packet_controller (
    input  wire        clk,
    input  wire        rst,
    input  wire        rx_valid_i,
    input  wire [7:0]  rx_data_8_i,
    input  wire        tx_done_tick_i,
    output reg         tx_start_o,
    output reg  [7:0]  tx_data_8_o
);

    // ------------------------------------------------------------------
    // FSM state encoding
    // ------------------------------------------------------------------
    localparam [2:0]
        S_IDLE           = 3'd0,
        S_GOT_8_BYTES    = 3'd1,
        S_RECV_CHECKSUM  = 3'd2,
        S_BUILD_RESPONSE = 3'd3,
        S_SEND_FIRST_BYTE= 3'd4,
        S_RESPONSE_READY = 3'd5;

    reg [2:0] state;

    // Incoming packet buffer (8 bytes):
    //  [0]=header hi, [1]=header lo, [2]=num1 hi, [3]=num1 lo,
    //  [4]=num2 hi,   [5]=num2 lo,   [6]=opcode,  [7]=checksum
    reg [7:0] buffer [0:7];
    reg [3:0] byte_cnt;

    // Outgoing response packet (5 bytes):
    //  [0]=0xAB, [1]=0xCD, [2]=result hi, [3]=result lo, [4]=checksum
    reg [7:0] resp [0:4];
    reg [2:0] tx_index;

    // ------------------------------------------------------------------
    // Combinational decode of the received packet
    // ------------------------------------------------------------------
    wire [7:0]  sum8   = buffer[0] + buffer[1] + buffer[2] + buffer[3]
                       + buffer[4] + buffer[5] + buffer[6] + buffer[7];
    wire [15:0] hdr    = {buffer[0], buffer[1]};
    wire [15:0] num1   = {buffer[2], buffer[3]};
    wire [15:0] num2   = {buffer[4], buffer[5]};
    wire [7:0]  opcode = buffer[6];

    reg  [15:0] result;
    always @(*) begin
        case (opcode)
            8'h00:   result = num1 + num2;   // Addition
            8'h01:   result = num1 - num2;   // Subtraction
            default: result = 16'h0000;      // Other opcodes -> 0
        endcase
    end

    // Outgoing checksum so that (AB+CD+resHi+resLo+cksum) mod 256 == 0
    wire [7:0] out_checksum = 8'h00 - (8'hAB + 8'hCD + result[15:8] + result[7:0]);

    integer i;

    // ------------------------------------------------------------------
    // Main FSM (synchronous, active-high async reset)
    // ------------------------------------------------------------------
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state       <= S_IDLE;
            byte_cnt    <= 4'd0;
            tx_start_o  <= 1'b0;
            tx_data_8_o <= 8'h00;
            tx_index    <= 3'd0;
            for (i = 0; i < 8; i = i + 1) buffer[i] <= 8'h00;
            for (i = 0; i < 5; i = i + 1) resp[i]   <= 8'h00;
        end else begin
            case (state)
                // Accumulate 8 bytes from the RX interface
                S_IDLE: begin
                    tx_start_o <= 1'b0;
                    if (rx_valid_i) begin
                        buffer[byte_cnt] <= rx_data_8_i;
                        if (byte_cnt == 4'd7) begin
                            byte_cnt <= 4'd0;
                            state    <= S_GOT_8_BYTES;
                        end else begin
                            byte_cnt <= byte_cnt + 4'd1;
                        end
                    end
                end

                // Validate the header
                S_GOT_8_BYTES: begin
                    if (hdr == 16'hBACD)
                        state <= S_RECV_CHECKSUM;
                    else
                        state <= S_IDLE;   // unexpected header
                end

                // Validate the checksum (sum of all bytes mod 256 == 0)
                S_RECV_CHECKSUM: begin
                    if (sum8 == 8'h00)
                        state <= S_BUILD_RESPONSE;
                    else
                        state <= S_IDLE;   // checksum mismatch
                end

                // Build the outgoing response packet
                S_BUILD_RESPONSE: begin
                    resp[0] <= 8'hAB;
                    resp[1] <= 8'hCD;
                    resp[2] <= result[15:8];
                    resp[3] <= result[7:0];
                    resp[4] <= out_checksum;
                    state   <= S_SEND_FIRST_BYTE;
                end

                // Present the first byte and raise tx_start
                S_SEND_FIRST_BYTE: begin
                    tx_start_o  <= 1'b1;
                    tx_data_8_o <= resp[0];
                    tx_index    <= 3'd1;
                    state       <= S_RESPONSE_READY;
                end

                // Stream the remaining bytes, advancing on tx_done_tick_i
                S_RESPONSE_READY: begin
                    tx_start_o <= 1'b1;
                    if (tx_done_tick_i) begin
                        if (tx_index == 3'd5) begin
                            // all 5 bytes transmitted
                            tx_start_o <= 1'b0;
                            state      <= S_IDLE;
                        end else begin
                            tx_data_8_o <= resp[tx_index];
                            tx_index    <= tx_index + 3'd1;
                        end
                    end
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

module palindrome_detect #(
    parameter N = 3
) (
    input  clk,
    input  reset,
    input  bit_stream,
    output reg palindrome_detected
);

    // Sliding window of the last N bits seen on the stream.
    reg [N-1:0] shift_reg;

    // Count of valid bits shifted in so far (saturates at N).
    reg [$clog2(N+1)-1:0] count;

    integer i;
    reg [N-1:0] next_window;
    reg is_pal;

    // Combinationally form the next window and test it for a palindrome.
    always @(*) begin
        next_window = {shift_reg[N-2:0], bit_stream};
        is_pal = 1'b1;
        for (i = 0; i < N; i = i + 1) begin
            if (next_window[i] != next_window[N-1-i])
                is_pal = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            shift_reg          <= {N{1'b0}};
            count              <= {($clog2(N+1)){1'b0}};
            palindrome_detected <= 1'b0;
        end else begin
            shift_reg <= next_window;
            if (count < N)
                count <= count + 1'b1;
            // Only report once at least N bits form a full window.
            palindrome_detected <= (count >= (N-1)) && is_pal;
        end
    end

endmodule

module password_generator #(
    parameter WIDTH = 4
) (
    input  logic clk,
    input  logic reset,
    output logic [(WIDTH*8)-1:0] password
);

  logic [7:0] char_array [WIDTH-1:0];  // temporary per-character storage
  logic [7:0] counter;                 // byte-wide pseudo-random counter
  logic [1:0] char_type;               // category selector

  int i;

  // Counter logic for pseudo-random generation + password character generation.
  // reset is asynchronous, active HIGH.
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      counter <= 8'd0;
      for (i = 0; i < WIDTH; i = i + 1) begin
        char_array[i] <= 8'd0;
      end
    end else begin
      counter <= counter + 8'd1;
      for (i = 0; i < WIDTH; i = i + 1) begin
        // char_type cycles through the four categories by character index
        char_type = i[1:0];
        case (char_type)
          2'b00: char_array[i] <= (((counter + char_array[(i+1)%WIDTH]) % 26) + 8'd97);          // a-z
          2'b01: char_array[i] <= (((counter + i) % 26) + 8'd65);                                 // A-Z
          2'b10: char_array[i] <= (((counter + char_array[(i+WIDTH-1)%WIDTH]) % 14) + 8'd33);     // ! to /
          2'b11: char_array[i] <= (((counter + i) % 10) + 8'd48);                                 // 0-9
          default: char_array[i] <= 8'd0;
        endcase
      end
    end
  end

  // Pack char_array into the password output using combinational logic.
  integer j;
  always @(*) begin
    for (j = 0; j < WIDTH; j = j + 1) begin
      password[j*8 +: 8] = char_array[j];
    end
  end

endmodule

module perceptron_gates (
    input  wire               clk,
    input  wire               rst_n,
    input  wire signed [3:0]  x1,
    input  wire signed [3:0]  x2,
    input  wire               learning_rate,
    input  wire signed [3:0]  threshold,
    input  wire        [1:0]  gate_select,
    output reg  signed [3:0]  percep_w1,
    output reg  signed [3:0]  percep_w2,
    output reg  signed [3:0]  percep_bias,
    output reg         [3:0]  present_addr,
    output reg                stop,
    output reg         [2:0]  input_index,
    output reg  signed [3:0]  y_in,
    output reg  signed [3:0]  y,
    output reg  signed [3:0]  prev_percep_wt_1,
    output reg  signed [3:0]  prev_percep_wt_2,
    output reg  signed [3:0]  prev_percep_bias
);

    // ------------------------------------------------------------------
    // Gate-target submodule (target selection based on gate_select)
    // ------------------------------------------------------------------
    wire signed [3:0] o_1, o_2, o_3, o_4;
    gate_target u_gate_target (
        .gate_select(gate_select),
        .o_1(o_1), .o_2(o_2), .o_3(o_3), .o_4(o_4)
    );

    // ------------------------------------------------------------------
    // Internal registers
    // ------------------------------------------------------------------
    reg signed [3:0] target;
    reg signed [3:0] wt1_update, wt2_update, bias_update;
    reg              update_seen_epoch;   // any nonzero update this epoch?

    // ------------------------------------------------------------------
    // Combinational datapath
    // ------------------------------------------------------------------
    // Target for the current index of the current gate
    wire signed [3:0] sel_target = (input_index == 3'd0) ? o_1 :
                                   (input_index == 3'd1) ? o_2 :
                                   (input_index == 3'd2) ? o_3 : o_4;

    // Weighted sum + bias
    wire signed [9:0] y_in_full = percep_bias + (x1 * percep_w1) + (x2 * percep_w2);

    // Thresholded output y in {+1, 0, -1}
    wire signed [3:0] y_next = (y_in_full >  threshold) ?  4'sd1 :
                               (y_in_full == threshold) ?  4'sd0 : -4'sd1;

    // Learning rate as a signed value (0 or 1)
    wire signed [3:0] lr_s   = learning_rate ? 4'sd1 : 4'sd0;
    wire              differ = (y != target);

    // Weight / bias update terms (nonzero only when y != target)
    wire signed [3:0] u1n = differ ? (lr_s * x1 * target) : 4'sd0;
    wire signed [3:0] u2n = differ ? (lr_s * x2 * target) : 4'sd0;
    wire signed [3:0] ubn = differ ? (lr_s * target)      : 4'sd0;

    // ------------------------------------------------------------------
    // Microcode ROM addresses (6 micro-instructions)
    // ------------------------------------------------------------------
    localparam [3:0] A_INIT     = 4'd0,   // initialize weights/bias to zero
                     A_COMPUTE  = 4'd1,   // compute y_in and y
                     A_TARGET   = 4'd2,   // select target
                     A_UPDATE   = 4'd3,   // update weights/bias
                     A_CONVERGE = 4'd4,   // convergence check
                     A_FINAL    = 4'd5;   // finalize / prepare next input

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            present_addr      <= 4'd0;
            percep_w1         <= 4'sd0;
            percep_w2         <= 4'sd0;
            percep_bias       <= 4'sd0;
            input_index       <= 3'd0;
            stop              <= 1'b0;
            y_in              <= 4'sd0;
            y                 <= 4'sd0;
            target            <= 4'sd0;
            wt1_update        <= 4'sd0;
            wt2_update        <= 4'sd0;
            bias_update       <= 4'sd0;
            prev_percep_wt_1  <= 4'sd0;
            prev_percep_wt_2  <= 4'sd0;
            prev_percep_bias  <= 4'sd0;
            update_seen_epoch <= 1'b0;
        end else if (!stop) begin
            case (present_addr)
                // Action 0: one-time initialization
                A_INIT: begin
                    percep_w1         <= 4'sd0;
                    percep_w2         <= 4'sd0;
                    percep_bias       <= 4'sd0;
                    input_index       <= 3'd0;
                    prev_percep_wt_1  <= 4'sd0;
                    prev_percep_wt_2  <= 4'sd0;
                    prev_percep_bias  <= 4'sd0;
                    wt1_update        <= 4'sd0;
                    wt2_update        <= 4'sd0;
                    bias_update       <= 4'sd0;
                    update_seen_epoch <= 1'b0;
                    present_addr      <= A_COMPUTE;
                end

                // Action 1: compute weighted sum + threshold
                A_COMPUTE: begin
                    y_in         <= y_in_full[3:0];
                    y            <= y_next;
                    present_addr <= A_TARGET;
                end

                // Action 2: select target for current index/gate
                A_TARGET: begin
                    target       <= sel_target;
                    present_addr <= A_UPDATE;
                end

                // Action 3: update weights and bias (if y != target)
                A_UPDATE: begin
                    percep_w1   <= percep_w1   + u1n;
                    percep_w2   <= percep_w2   + u2n;
                    percep_bias <= percep_bias + ubn;
                    wt1_update  <= u1n;
                    wt2_update  <= u2n;
                    bias_update <= ubn;
                    if ((u1n != 4'sd0) || (u2n != 4'sd0) || (ubn != 4'sd0))
                        update_seen_epoch <= 1'b1;
                    present_addr <= A_CONVERGE;
                end

                // Action 4: record updates as "previous" and check convergence.
                // Convergence: a whole epoch (4 inputs) with no nonzero update.
                A_CONVERGE: begin
                    prev_percep_wt_1 <= wt1_update;
                    prev_percep_wt_2 <= wt2_update;
                    prev_percep_bias <= bias_update;
                    if ((input_index == 3'd3) && (!update_seen_epoch))
                        stop <= 1'b1;
                    present_addr <= A_FINAL;
                end

                // Action 5: finalize / prepare for next input (or next epoch)
                A_FINAL: begin
                    if (input_index == 3'd3) begin
                        input_index       <= 3'd0;
                        update_seen_epoch <= 1'b0;
                    end else begin
                        input_index <= input_index + 3'd1;
                    end
                    present_addr <= A_COMPUTE;
                end

                default: present_addr <= A_COMPUTE;
            endcase
        end
    end

endmodule

// ----------------------------------------------------------------------
// Gate-target submodule: produces the four target values for the
// selected gate, in the order (index0, index1, index2, index3) matching
// the input application order (1,1),(1,-1),(-1,1),(-1,-1).
// Target tables are taken verbatim from the specification.
// ----------------------------------------------------------------------
module gate_target (
    input  wire        [1:0]  gate_select,
    output reg  signed [3:0]  o_1,
    output reg  signed [3:0]  o_2,
    output reg  signed [3:0]  o_3,
    output reg  signed [3:0]  o_4
);
    always @(*) begin
        case (gate_select)
            2'b00: begin o_1 = 4'sd1; o_2 = -4'sd1; o_3 = -4'sd1; o_4 = -4'sd1; end // AND
            2'b01: begin o_1 = 4'sd1; o_2 =  4'sd1; o_3 =  4'sd1; o_4 = -4'sd1; end // OR
            2'b10: begin o_1 = 4'sd1; o_2 =  4'sd1; o_3 =  4'sd1; o_4 = -4'sd1; end // NAND (per spec)
            2'b11: begin o_1 = 4'sd1; o_2 = -4'sd1; o_3 = -4'sd1; o_4 = -4'sd1; end // NOR (per spec)
            default: begin o_1 = 4'sd0; o_2 = 4'sd0; o_3 = 4'sd0; o_4 = 4'sd0; end
        endcase
    end
endmodule


