module perceptron_gates (
   input  logic clk,// Posedge clock
   input  logic rst_n,// Negedge reset
   input  logic signed [3:0] x1, // First Input of the Perceptron
   input  logic signed [3:0] x2, // Second Input of the Perceptron
   input  logic learning_rate, // Learning rate (alpha)
   input  logic signed [3:0] threshold, // Threshold value
   input  logic [1:0] gate_select, // Gate selection for target values
   output logic signed [3:0] percep_w1, // Trained Weight 1
   output logic signed [3:0] percep_w2, // Trained Weight 2
   output logic signed [3:0] percep_bias, // Trained Bias
   output logic [3:0] present_addr, // Current address in microcode ROM
   output logic stop, // Condition to indicate no learning has occurred(i.e. no weight change between iterations)
   output logic [2:0] input_index,// Vector to track the selection of target for a given input combination for a gate
   output logic signed [3:0] y_in, // Calculated Response
   output logic signed [3:0] y, // Calculated Response obtained by comparing y_in against a threshold value
   output logic signed [3:0] prev_percep_wt_1,//Value of Weight 1 during a previous iteration
   output logic signed [3:0] prev_percep_wt_2,//Value of Weight 2 during a previous iteration
   output logic signed [3:0] prev_percep_bias, // Value of Bias during a previous iteration
   // ---- Testing microcode control unit outputs ----
   output logic        [3:0] test_percep_present_state, // Present state of the Testing microcode ROM
   output logic signed [3:0] expected_percep_output,    // Output extracted from an internally predefined vector
   output logic signed [3:0] test_percep_output,        // Actual output generated by the Testing microcode ROM
   output logic signed [3:0] test_percep_result,        // Number of times expected matched actual
   output logic signed [3:0] test_percep_done,          // Indicates completion of Testing operation
   output logic signed [3:0] test_percep_x1,            // Input extracted from an internally predefined vector
   output logic signed [3:0] test_percep_x2             // Input extracted from an internally predefined vector
);

   logic [15:0] microcode_rom [0:5];
   logic [3:0]  next_addr;
   logic [3:0]  train_action;
   logic [3:0]  microcode_addr;
   logic [15:0] microinstruction;
   logic signed [3:0] t1, t2, t3, t4;

   gate_target dut (
       .gate_select(gate_select),
       .o_1(t1),
       .o_2(t2),
       .o_3(t3),
       .o_4(t4)
   );

   logic signed [3:0] percep_wt_1_reg;
   logic signed [3:0] percep_wt_2_reg;
   logic signed [3:0] percep_bias_reg;


   logic signed [3:0] target;
   logic signed [3:0] prev_wt1_update;
   logic signed [3:0] prev_wt2_update;
   logic signed [3:0] prev_bias_update;

   logic signed [3:0] wt1_update;
   logic signed [3:0] wt2_update;
   logic signed [3:0] bias_update;
   logic [7:0] epoch_counter;

   assign  prev_percep_wt_1 = prev_wt1_update;
   assign  prev_percep_wt_2 = prev_wt2_update;
   assign  prev_percep_bias = prev_bias_update;

   initial begin
      microcode_rom[0] = 16'b0001_0000_0000_0000;
      microcode_rom[1] = 16'b0010_0001_0000_0000;
      microcode_rom[2] = 16'b0011_0010_0000_0000;
      microcode_rom[3] = 16'b0100_0011_0000_0000;
      microcode_rom[4] = 16'b0101_0100_0000_0000;
      microcode_rom[5] = 16'b0000_0101_0000_0000;
   end

   always@(*) begin
      microinstruction = microcode_rom[microcode_addr];
      next_addr        = microinstruction[15:12];
      train_action     = microinstruction[11:8];
   end

   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         present_addr    <= 4'd0;
         microcode_addr  <= 4'd0;
         percep_wt_1_reg <= 4'd0;
         percep_wt_2_reg <= 4'd0;
         percep_bias_reg <= 4'd0;
         input_index     <= 2'd0;
         stop            <= 1'b0;
      end else begin
         present_addr    <= next_addr;
         microcode_addr  <= present_addr;
      end
   end

   always_comb begin
      case (train_action)
         4'd0:  begin
                   percep_wt_1_reg = 4'd0;
                   percep_wt_2_reg = 4'd0;
                   percep_bias_reg = 4'd0;
                   stop = 1'b0;
                   next_addr = next_addr + 4'd0;
                   y_in = 4'd0;
                   y    = 4'd0;
                   prev_wt1_update = 4'd0;
                   prev_wt2_update = 4'd0;
                   prev_bias_update = 4'd0;
                   input_index = 0;
                   target = 0;
                   wt1_update = 0;
                   wt2_update = 0;
                   bias_update = 0;
                   epoch_counter = 0;
                end
         4'd1 : begin
                   y_in = percep_bias_reg + (x1 * percep_wt_1_reg) + (x2 * percep_wt_2_reg);
                   if (y_in > threshold)
                      y = 4'd1;
                   else if (y_in >= -threshold && y_in <= threshold)
                      y = 4'd0;
                   else
                      y = -4'd1;

                   percep_wt_1_reg  = percep_wt_1_reg  + 4'd0;
                   percep_wt_2_reg  = percep_wt_2_reg  + 4'd0;
                   percep_bias_reg  = percep_bias_reg  + 4'd0;
                   prev_wt1_update  = prev_wt1_update  + 4'd0;
                   prev_wt2_update  = prev_wt2_update  + 4'd0;
                   prev_bias_update = prev_bias_update + 4'd0;
                   input_index = input_index + 0;
                   next_addr = next_addr + 4'd0;
                   stop = stop + 1'b0;
                   target = target + 4'd0;
                   wt1_update = wt1_update + 4'd0 ;
                   wt2_update = wt2_update + 4'd0 ;
                   bias_update = bias_update + 4'd0 ;
                   epoch_counter = epoch_counter + 0;
                end
         4'd2 : begin
                   if(input_index == 0)
                        target = t1;
                   else if(input_index == 1)
                        target = t2;
                   else if(input_index == 2)
                        target = t3;
                   else if(input_index == 3)
                        target = t4;
                   else begin
                        input_index = 0;
                        target = 0;
                   end
                   stop = stop + 1'b0;
                   input_index = input_index + 0;
                   next_addr = next_addr + 4'd0;
                   target = target + 4'd0;
                   prev_wt1_update  = prev_wt1_update  + 4'd0;
                   prev_wt2_update  = prev_wt2_update  + 4'd0;
                   prev_bias_update = prev_bias_update + 4'd0;

                   percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                   percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                   percep_bias_reg = percep_bias_reg + 4'd0;
                   y_in = y_in + 4'd0;
                   y = y + 4'd0;
                   wt1_update = wt1_update + 4'd0 ;
                   wt2_update = wt2_update + 4'd0 ;
                   bias_update = bias_update + 4'd0 ;
                   epoch_counter = epoch_counter + 0;
                end
         4'd3 : begin
                   if (y != target) begin
                        wt1_update = learning_rate * x1 * target ;
                        wt2_update = learning_rate * x2 * target ;
                        bias_update = learning_rate * target ;
                    end else begin
                        wt1_update = 0 ;
                        wt2_update = 0 ;
                        bias_update = 0 ;
                    end
                    percep_wt_1_reg = percep_wt_1_reg + wt1_update;
                    percep_wt_2_reg = percep_wt_2_reg + wt2_update;
                    percep_bias_reg = percep_bias_reg + bias_update;
                    prev_wt1_update  = prev_wt1_update  + 4'd0;
                    prev_wt2_update  = prev_wt2_update  + 4'd0;
                    prev_bias_update = prev_bias_update + 4'd0;
                    y_in = y_in + 4'd0;
                    y = y + 4'd0;
                    stop = stop + 1'b0;
                    input_index = input_index + 0;
                    next_addr = next_addr + 4'd0;
                    target = target + 4'd0;
                    epoch_counter = epoch_counter + 0;
                end
         4'd4 : begin
                  if ((prev_wt1_update == wt1_update) & (prev_wt2_update == wt2_update) & (input_index == 4'd3)) begin
                          epoch_counter = 0;
                          stop = 1'b1;
                          input_index = 0;
                          next_addr = 4'd0;
                          percep_wt_1_reg = 0;
                          percep_wt_2_reg = 0;
                          percep_bias_reg = 0;
                          prev_wt1_update =  0;
                          prev_wt2_update =  0;
                          prev_bias_update = 0;
                          y_in = 0;
                          y = 0;
                          target = 0;
                          wt1_update = 0 ;
                          wt2_update = 0 ;
                          bias_update = 0 ;
                  end else begin
                          stop = 1'b0;
                          input_index = input_index + 0;
                          epoch_counter = epoch_counter + 1;
                          next_addr = 4'd5;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update = prev_wt1_update + 4'd0;
                          prev_wt2_update = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                  end
                end
         4'd5 : begin
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update  = wt1_update;
                          prev_wt2_update  = wt2_update;
                          prev_bias_update = bias_update;
                          next_addr = 4'd1;
                          input_index = input_index + 1;
                          stop = stop + 1'b0;
                          epoch_counter = epoch_counter + 0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0;
                          wt2_update = wt2_update + 4'd0;
                          bias_update = bias_update + 4'd0;
                end
      default : begin
                          next_addr = next_addr + 4'd0;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update = prev_wt1_update + 4'd0;
                          prev_wt2_update = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          stop = stop + 1'b0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          input_index = input_index + 0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                          epoch_counter = epoch_counter + 0;
                end
      endcase
   end
   assign percep_w1 = percep_wt_1_reg;
   assign percep_w2 = percep_wt_2_reg;
   assign percep_bias = percep_bias_reg;

   // =====================================================================
   // Testing microcode control unit
   //   Activated once the Training control unit reaches the stop condition.
   //   Walks the 4 predefined test vectors for the selected gate, computes
   //   the perceptron response with the trained (captured) weights, and
   //   accumulates the number of matches against the expected outputs.
   // =====================================================================

   // Predefined test-vector arrays (depth 16, gate-major layout).
   //   Each gate occupies a contiguous block of 4 entries:
   //     AND : 0-3   OR : 4-7   NAND : 8-11   NOR : 12-15
   //   The four input combinations within each block are, in order:
   //     (x1,x2) = (1,1), (-1,1), (1,-1), (-1,-1)
   logic signed [3:0] test_inputs_x1        [0:15];
   logic signed [3:0] test_inputs_x2        [0:15];
   logic signed [3:0] test_expected_outputs [0:15];

   integer ti;
   initial begin
      // input combinations replicated for every gate block
      for (ti = 0; ti < 16; ti = ti + 1) begin
         case (ti % 4)
            0: begin test_inputs_x1[ti] =  4'sd1; test_inputs_x2[ti] =  4'sd1; end
            1: begin test_inputs_x1[ti] = -4'sd1; test_inputs_x2[ti] =  4'sd1; end
            2: begin test_inputs_x1[ti] =  4'sd1; test_inputs_x2[ti] = -4'sd1; end
            3: begin test_inputs_x1[ti] = -4'sd1; test_inputs_x2[ti] = -4'sd1; end
         endcase
      end
      // AND gate expected outputs (block 0-3)
      test_expected_outputs[0]  =  4'sd1;
      test_expected_outputs[1]  = -4'sd1;
      test_expected_outputs[2]  = -4'sd1;
      test_expected_outputs[3]  = -4'sd1;
      // OR gate expected outputs (block 4-7)
      test_expected_outputs[4]  =  4'sd1;
      test_expected_outputs[5]  =  4'sd1;
      test_expected_outputs[6]  =  4'sd1;
      test_expected_outputs[7]  = -4'sd1;
      // NAND gate expected outputs (block 8-11)
      test_expected_outputs[8]  = -4'sd1;
      test_expected_outputs[9]  =  4'sd1;
      test_expected_outputs[10] =  4'sd1;
      test_expected_outputs[11] =  4'sd1;
      // NOR gate expected outputs (block 12-15)
      test_expected_outputs[12] = -4'sd1;
      test_expected_outputs[13] = -4'sd1;
      test_expected_outputs[14] = -4'sd1;
      test_expected_outputs[15] =  4'sd1;
   end

   // starting / terminal index for the selected gate
   wire [3:0] test_start    = {gate_select, 2'b00}; // 00->0, 01->4, 10->8, 11->12
   wire [3:0] test_terminal = test_start + 4'd3;

   // captured (frozen) trained weights used during testing
   logic signed [3:0] tw1, tw2, tb;
   logic              testing_active;
   logic        [3:0] test_percep_index;

   // combinational evaluation of the perceptron response for a test vector
   function automatic logic signed [3:0] test_out_f
      (input logic signed [3:0] w1, input logic signed [3:0] w2,
       input logic signed [3:0] b,
       input logic signed [3:0] ix1, input logic signed [3:0] ix2,
       input logic signed [3:0] th);
      logic signed [15:0] calc;
      begin
         calc = (w1 * ix1) + (w2 * ix2) + b;
         if (calc > th)
            test_out_f =  4'sd1;
         else if (calc >= -th && calc <= th)
            test_out_f =  4'sd0;
         else
            test_out_f = -4'sd1;
      end
   endfunction

   logic signed [3:0] tv_out;

   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         testing_active            <= 1'b0;
         test_percep_index         <= 4'd0;
         test_percep_result        <= 4'sd0;
         test_percep_done          <= 4'sd0;
         test_percep_output        <= 4'sd0;
         test_percep_x1            <= 4'sd0;
         test_percep_x2            <= 4'sd0;
         expected_percep_output    <= 4'sd0;
         test_percep_present_state <= 4'd0;
         tw1                       <= 4'sd0;
         tw2                       <= 4'sd0;
         tb                        <= 4'sd0;
      end else begin
         // freeze the trained weights: hold the last value seen while
         // training is still in progress (before the stop condition).
         if (!stop) begin
            tw1 <= percep_w1;
            tw2 <= percep_w2;
            tb  <= percep_bias;
         end

         if (stop && !testing_active) begin
            // enter the testing phase
            testing_active            <= 1'b1;
            test_percep_index         <= test_start;
            test_percep_result        <= 4'sd0;
            test_percep_done          <= 4'sd0;
            test_percep_output        <= 4'sd0;
            test_percep_present_state <= 4'd5;
         end else if (testing_active && (test_percep_done == 4'sd0)) begin
            // process the test vector at the current index
            test_percep_present_state <= 4'd5;
            test_percep_x1            <= test_inputs_x1[test_percep_index];
            test_percep_x2            <= test_inputs_x2[test_percep_index];
            expected_percep_output    <= test_expected_outputs[test_percep_index];

            tv_out = test_out_f(tw1, tw2, tb,
                                test_inputs_x1[test_percep_index],
                                test_inputs_x2[test_percep_index],
                                threshold);
            test_percep_output <= tv_out;

            if (test_percep_index == test_terminal) begin
               // terminal vector reached -> testing complete
               test_percep_done   <= 4'sd1;
               test_percep_result <= 4'sd0;
            end else begin
               if (tv_out == test_expected_outputs[test_percep_index])
                  test_percep_result <= test_percep_result + 4'sd1;
               test_percep_index <= test_percep_index + 4'd1;
            end
         end
      end
   end

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
     case(gate_select)
          2'b00 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
          2'b01 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b10 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b11 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
        default : begin
                    o_1 =  0;
                    o_2 =  0;
                    o_3 =  0;
                    o_4 =  0;
                  end
        endcase
   end
endmodule

module perceptron_gates (
   input  logic clk,                       // Posedge clock
   input  logic rst_n,                     // Negedge reset
   input  logic signed [3:0] x1,           // First Input of the Perceptron
   input  logic signed [3:0] x2,           // Second Input of the Perceptron
   input  logic learning_rate,             // Learning rate (alpha)
   input  logic signed [3:0] threshold,    // Threshold value
   input  logic [1:0] gate_select,         // Gate selection for target values
   output logic signed [3:0] percep_w1,    // Trained Weight 1
   output logic signed [3:0] percep_w2,    // Trained Weight 2
   output logic signed [3:0] percep_bias,  // Trained Bias
   output logic [3:0] present_addr,        // Current address in microcode ROM
   output logic stop,                      // No-learning stop indicator
   output logic [2:0] input_index,         // Target-selection index for a gate
   output logic signed [3:0] y_in,         // Calculated Response
   output logic signed [3:0] y,            // Thresholded response
   output logic signed [3:0] prev_percep_wt_1,  // Weight 1 previous iteration
   output logic signed [3:0] prev_percep_wt_2,  // Weight 2 previous iteration
   output logic signed [3:0] prev_percep_bias   // Bias previous iteration
);

   logic [7:0]  microcode_rom [0:5];
   logic [3:0]  next_addr;
   logic [3:0]  train_action;
   logic [3:0]  microcode_addr;
   logic [15:0] microinstruction;
   logic signed [3:0] t1, t2, t3, t4;

   gate_target dut (
       .gate_select(gate_select),
       .o_1(t1),
       .o_2(t2),
       .o_3(t3),
       .o_4(t4)
   );

   logic signed [3:0] percep_wt_1_reg;
   logic signed [3:0] percep_wt_2_reg;
   logic signed [3:0] percep_bias_reg;

   logic signed [3:0] target;
   logic signed [3:0] prev_wt1_update;
   logic signed [3:0] prev_wt2_update;
   logic signed [3:0] prev_bias_update;

   logic signed [3:0] wt1_update;
   logic signed [3:0] wt2_update;
   logic signed [3:0] bias_update;
   logic [7:0] epoch_counter;

   logic [3:0]        microcode_addr_d;   // one-visit edge detect
   logic signed [9:0] yin_calc;           // wide accumulate for y_in

   assign  prev_percep_wt_1 = prev_wt1_update;
   assign  prev_percep_wt_2 = prev_wt2_update;
   assign  prev_percep_bias = prev_bias_update;

   initial begin
      microcode_rom[0] = 8'b0001_0000;   // next=1, action=0 : init
      microcode_rom[1] = 8'b0010_0001;   // next=2, action=1 : compute y_in,y
      microcode_rom[2] = 8'b0011_0010;   // next=3, action=2 : select target
      microcode_rom[3] = 8'b0100_0011;   // next=4, action=3 : compute deltas / update
      microcode_rom[4] = 8'b0101_0100;   // next=5, action=4 : stop check / epoch
      microcode_rom[5] = 8'b0000_0101;   // next=0(->1), action=5 : save prev / index++
   end

   // ---- target selection (combinational) ----
   always_comb begin
      case (input_index)
         3'd0:    target = t1;
         3'd1:    target = t2;
         3'd2:    target = t3;
         3'd3:    target = t4;
         default: target = 4'sd0;
      endcase
   end

   // ---- current-iteration weight/bias deltas (combinational) ----
   always_comb begin
      if (y != target) begin
         wt1_update  = learning_rate ? (x1 * target) : 4'sd0;
         wt2_update  = learning_rate ? (x2 * target) : 4'sd0;
         bias_update = learning_rate ? target        : 4'sd0;
      end else begin
         wt1_update  = 4'sd0;
         wt2_update  = 4'sd0;
         bias_update = 4'sd0;
      end
   end

   // ---- microcode decode + next address (combinational, with overrides) ----
   always_comb begin
      microinstruction = microcode_rom[microcode_addr];
      train_action     = microinstruction[3:0];
      next_addr        = microinstruction[7:4];
      case (train_action)
         4'd4: next_addr = ((wt1_update  == prev_wt1_update)  &&
                            (wt2_update  == prev_wt2_update)  &&
                            (bias_update == prev_bias_update)) ? 4'd0 : 4'd5;
         4'd5: next_addr = 4'd1;
         default: /* keep ROM value */ ;
      endcase
   end

   // ---- sequential microcode engine ----
   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         present_addr     <= 4'd0;
         microcode_addr   <= 4'd0;
         microcode_addr_d <= 4'hf;
         percep_wt_1_reg  <= 4'sd0;
         percep_wt_2_reg  <= 4'sd0;
         percep_bias_reg  <= 4'sd0;
         input_index      <= 3'd0;
         stop             <= 1'b0;
         y_in             <= 4'sd0;
         y                <= 4'sd0;
         prev_wt1_update  <= 4'sd0;
         prev_wt2_update  <= 4'sd0;
         prev_bias_update <= 4'sd0;
         epoch_counter    <= 8'd0;
      end else begin
         present_addr     <= next_addr;
         microcode_addr   <= present_addr;
         microcode_addr_d <= microcode_addr;

         // execute each microcode step exactly once (dwell-2 pipeline)
         if (microcode_addr != microcode_addr_d) begin
            case (train_action)
               4'd0: begin  // initialize
                  percep_wt_1_reg  <= 4'sd0;
                  percep_wt_2_reg  <= 4'sd0;
                  percep_bias_reg  <= 4'sd0;
                  stop             <= 1'b0;
                  y_in             <= 4'sd0;
                  y                <= 4'sd0;
                  prev_wt1_update  <= 4'sd0;
                  prev_wt2_update  <= 4'sd0;
                  prev_bias_update <= 4'sd0;
                  epoch_counter    <= 8'd0;
               end
               4'd1: begin  // compute y_in and y
                  yin_calc = percep_bias_reg
                           + (x1 * percep_wt_1_reg)
                           + (x2 * percep_wt_2_reg);
                  y_in <= yin_calc[3:0];
                  if (yin_calc > threshold)
                     y <= 4'sd1;
                  else if (yin_calc >= -threshold && yin_calc <= threshold)
                     y <= 4'sd0;
                  else
                     y <= -4'sd1;
               end
               4'd2: begin  // target select (combinational); nothing to latch
               end
               4'd3: begin  // apply weight/bias update if error
                  if (y != target) begin
                     percep_wt_1_reg <= percep_wt_1_reg + wt1_update;
                     percep_wt_2_reg <= percep_wt_2_reg + wt2_update;
                     percep_bias_reg <= percep_bias_reg + bias_update;
                  end
               end
               4'd4: begin  // stop check / epoch counter
                  if ((wt1_update  == prev_wt1_update)  &&
                      (wt2_update  == prev_wt2_update)  &&
                      (bias_update == prev_bias_update))
                     stop <= 1'b1;
                  else
                     epoch_counter <= epoch_counter + 8'd1;
               end
               4'd5: begin  // save prev deltas, advance iteration index
                  prev_wt1_update  <= wt1_update;
                  prev_wt2_update  <= wt2_update;
                  prev_bias_update <= bias_update;
                  input_index      <= (input_index == 3'd3) ? 3'd0
                                                            : input_index + 3'd1;
               end
               default: /* no action */ ;
            endcase
         end
      end
   end

   assign percep_w1   = percep_wt_1_reg;
   assign percep_w2   = percep_wt_2_reg;
   assign percep_bias = percep_bias_reg;

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
     case(gate_select)
          2'b00 : begin
                    o_1 =  4'b0001;
                    o_2 = -4'b0001;
                    o_3 = -4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b01 : begin
                    o_1 =  4'b0001;
                    o_2 =  4'b0001;
                    o_3 =  4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b10 : begin
                    o_1 =  4'b0001;
                    o_2 =  4'b0001;
                    o_3 =  4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b11 : begin
                    o_1 =  4'b0001;
                    o_2 = -4'b0001;
                    o_3 = -4'b0001;
                    o_4 = -4'b0001;
                  end
        default : begin
                    o_1 =  4'b0000;
                    o_2 =  4'b0000;
                    o_3 =  4'b0000;
                    o_4 =  4'b0000;
                  end
        endcase
   end
endmodule

module perf_counters #(
    parameter CNT_W = 32
) (
    input  wire              clk,
    input  wire              reset,
    input  wire              sw_req_i,
    input  wire              cpu_trig_i,
    output wire [CNT_W-1:0]  p_count_o
);

    // Internal event counter.  Positive-edge-triggered flip-flops with an
    // asynchronous active-high reset.
    reg [CNT_W-1:0] count_q;

    always @(posedge clk or posedge reset) begin
        if (reset)
            // On reset the counter value is set to zero.
            count_q <= {CNT_W{1'b0}};
        else if (sw_req_i)
            // Once the software reads the value, the counter resets to zero
            // in the next cycle.  Read-clear takes priority; counting resumes
            // from zero afterwards (counter and read are independent).
            count_q <= {CNT_W{1'b0}};
        else if (cpu_trig_i)
            // The counter increments when a CPU trigger event is received.
            // Natural CNT_W-bit wrap provides the parameterized overflow.
            count_q <= count_q + 1'b1;
    end

    // The counter value is only readable via a software request.  If there is
    // no read request, the output remains zero.
    assign p_count_o = sw_req_i ? count_q : {CNT_W{1'b0}};

endmodule


// --- harness-toplevel alias (auto-added by cvdp_gate; the official
