module perfect_squares_generator (
    input  wire        clk,
    input  wire        reset,
    output reg  [31:0] sqr_o
);

    // Perfect squares are generated incrementally: (n+1)^2 = n^2 + (2n+1).
    // "step" holds the next odd increment (2n+1).  On reset sqr_o = 1 (the
    // first square) and step = 3, so the sequence advances 1, 4, 9, 16, ...
    // on each following positive clock edge.
    reg [31:0] step;

    // 33-bit sum so an out-of-32-bit result is detected by bit [32].
    wire [32:0] next_sum = {1'b0, sqr_o} + {1'b0, step};

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Asynchronous, active-high reset: begin the sequence anew.
            sqr_o <= 32'd1;
            step  <= 32'd3;
        end else begin
            if (next_sum[32]) begin
                // Overflow protection: saturate at the 32-bit maximum.
                sqr_o <= 32'hFFFFFFFF;
                step  <= step;
            end else begin
                sqr_o <= next_sum[31:0];
                step  <= step + 32'd2;
            end
        end
    end

endmodule


