module ping_pong_buffer (
    input logic clk,
    input logic rst_n,
    input logic write_enable,
    input logic read_enable,
    input logic [7:0] data_in,
    output logic [7:0] data_out,
    output logic buffer_full,
    output logic buffer_empty,
    output reg buffer_select
);

    localparam DEPTH = 256;
    localparam ADDR_WIDTH = 8;

    logic [ADDR_WIDTH-1:0] write_ptr, read_ptr;
    logic [7:0] data_out0, data_out1;

    // Dual port memory bank 0: written/read when buffer_select == 0
    dual_port_memory memory0 (
        .clk        (clk),
        .we         (write_enable && !buffer_select && !buffer_full),
        .write_addr (write_ptr),
        .din        (data_in),
        .read_addr  (read_ptr),
        .dout       (data_out0)
    );

    // Dual port memory bank 1: written/read when buffer_select == 1
    dual_port_memory memory1 (
        .clk        (clk),
        .we         (write_enable && buffer_select && !buffer_full),
        .write_addr (write_ptr),
        .din        (data_in),
        .read_addr  (read_ptr),
        .dout       (data_out1)
    );

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset: clear pointers, select bank 0, not full, empty asserted
            write_ptr     <= '0;
            read_ptr      <= '0;
            buffer_select <= 1'b0;
            buffer_full   <= 1'b0;
            buffer_empty  <= 1'b1;
        end else begin
            // Writing: store into the active buffer, wrap pointer modulo DEPTH,
            // flag full when the last slot of the buffer is written.
            if (write_enable && !buffer_full) begin
                write_ptr    <= (write_ptr + 1) % DEPTH;
                buffer_empty <= 1'b0;
                if (write_ptr == DEPTH-1)
                    buffer_full <= 1'b1;
            end

            // Reading: advance read pointer modulo DEPTH; when the read pointer
            // reaches the end of the buffer, toggle the active buffer and mark
            // the buffer empty. Reading clears the full flag.
            if (read_enable && !buffer_empty) begin
                read_ptr    <= (read_ptr + 1) % DEPTH;
                buffer_full <= 1'b0;
                if (read_ptr == DEPTH-1) begin
                    buffer_select <= ~buffer_select;
                    buffer_empty  <= 1'b1;
                end
            end
        end
    end

    // Output: data comes from the buffer designated by buffer_select
    assign data_out = buffer_select ? data_out1 : data_out0;

endmodule

module pipeline_mac #(
    parameter DWIDTH = 16,  // Bit width for multiplicand and multiplier
    parameter N      = 4    // Number of data points to accumulate over
) (
    clk,
    rstn,
    multiplicand,
    multiplier,
    valid_i,
    result,
    valid_out
);
  // ----------------------------------------
  // - Local parameter definition
  // ----------------------------------------

  // Accumulator width: product is 2*DWIDTH bits, and accumulating up to N
  // products can grow the result by $clog2(N) additional bits. This is the
  // minimum width that holds the maximum expected value N*(2^DWIDTH-1)^2
  // without overflow.
  localparam DWIDTH_ACCUMULATOR = (2 * DWIDTH) + $clog2(N);

  // ----------------------------------------
  // - Interface Definitions
  // ----------------------------------------
  input logic clk;                                // Clock signal
  input logic rstn;                               // Active low reset signal
  input logic [DWIDTH-1:0] multiplicand;          // Input multiplicand
  input logic [DWIDTH-1:0] multiplier;            // Input multiplier
  input logic valid_i;                            // Input valid signal
  output logic [DWIDTH_ACCUMULATOR-1:0] result;   // Accumulated result output
  output logic valid_out;                         // Output valid signal, indicates when result is ready

  // ----------------------------------------
  // - Internal signals
  // ----------------------------------------
  logic [DWIDTH_ACCUMULATOR-1:0] mult_result_reg;    // Register to store intermediate multiplication result
  logic [DWIDTH_ACCUMULATOR-1:0] accumulation_reg;   // Register to store accumulated result
  logic [$clog2(N):0] counter;                       // Counter to track the number of accumulations
  logic [$clog2(N):0] counter_reg;                   // Register to hold the value of the counter
  logic count_rst, accumulator_rst;                  // Reset signals for counter and accumulator
  logic valid_out_s0,valid_out_s1,valid_out_s2;      // Intermediate Signals indicating that the valid output is ready
  logic valid_i_s1;                                  // Intermediate Signals indicating input valid signal
  // ----------------------------------------
  // - Procedural blocks
  // ----------------------------------------

  // Stage 1 of the pipeline: Perform multiplication
  always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
      mult_result_reg <= '0;
    end else if (valid_i) begin
      // On a valid input, register the product. When valid_i is low the
      // register holds its current value (no new data processed).
      mult_result_reg <= multiplicand * multiplier;
    end
  end

  // Stage 2 of the pipeline: Accumulation logic
  always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
      accumulation_reg <= '0;
    end else if (accumulator_rst) begin
      // End of a batch: the result has just been output; start the next
      // batch with the product currently in the pipeline so that no valid
      // product is dropped at the batch boundary.
      accumulation_reg <= mult_result_reg;
    end else if (valid_i_s1) begin
      // Accumulate the (1-cycle-delayed) valid product.
      accumulation_reg <= accumulation_reg + mult_result_reg;
    end
  end

  // N-bit counter to track the number of accumulations
  always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
      counter_reg <= '0;
    end else begin
      counter_reg <= counter;
    end
  end

  // Register valid output for 2-stage pipeline
  always @(posedge clk or negedge rstn) begin
    if (!rstn) begin
      valid_out_s1 <= 1'b0;
      valid_out_s2 <= 1'b0;
      valid_i_s1   <= 1'b0;
    end else begin
      valid_out_s1 <= valid_out_s0;   // Delay valid_out_s0 by one cycle
      valid_out_s2 <= valid_out_s1;   // Delay valid_out_s1 by one more cycle
      valid_i_s1   <= valid_i;        // Align input-valid with the multiplication stage
    end
  end

  // ----------------------------------------
  // - Combinational Assignments
  // ----------------------------------------
  assign counter = count_rst ? 'b1 : (valid_i & rstn ? (counter_reg + 'd1) : counter_reg);  // Increment counter on valid input
  assign valid_out_s0 = (counter_reg == N-1);    // Assert valid_out_s0 when N accumulations are done
  assign count_rst = valid_out_s1;                  // Reset counter after N accumulations
  assign accumulator_rst = valid_out_s1;            // Reset accumulator after N accumulations
  assign result = accumulation_reg;              // Output final result assignment
  assign valid_out = valid_out_s1 & ~valid_out_s2; // Valid_out signal generation by detecting posedge of previous stages of valid out

endmodule : pipeline_mac

module piso_8bit (
    input  wire clk,
    input  wire rst,
    output reg  serial_out
);

    // Internal 8-bit parallel register, spec-named `tmp`
    reg [7:0] tmp;
    // Bit-position counter for the 8 shift cycles
    reg [2:0] count;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            // Asynchronous active-LOW reset:
            // initialize tmp to 0000_0001, hold serial_out LOW
            tmp        <= 8'b0000_0001;
            count      <= 3'd0;
            serial_out <= 1'b0;
        end else begin
            // Emit one bit per clock, MSB (bit 7) first down to LSB (bit 0)
            serial_out <= tmp[7 - count];

            if (count == 3'd7) begin
                // After all eight bits transmitted, advance to next pattern
                count <= 3'd0;
                tmp   <= tmp + 8'd1;
            end else begin
                count <= count + 3'd1;
            end
        end
    end

endmodule


