module pkt_detector #(
    parameter PKT_CNT_WIDTH = 4
) (
    input  logic                       reset,
    input  logic                       clk,
    input  logic [7:0]                 data_in,
    input  logic                       data_k_flag,
    output logic [PKT_CNT_WIDTH - 1:0] pkt_count,
    output logic [159:0]               pkt_data,
    output logic                       mem_read_detected,
    output logic                       mem_write_detected,
    output logic                       io_read_detected,
    output logic                       io_write_detected,
    output logic                       cfg_read0_detected,
    output logic                       cfg_write0_detected,
    output logic                       cfg_read1_detected,
    output logic                       cfg_write1_detected,
    output logic                       completion_detected,
    output logic                       completion_data_detected,
    output logic                       error_detected
);

localparam [7:0] START_SYMBOL = 8'hFB;
localparam [7:0] END_SYMBOL   = 8'hFD;
localparam       PKT_BYTES    = 20;

typedef enum logic [1:0] {
    S_IDLE     = 2'b00,
    S_ACTIVE   = 2'b01,
    S_WAIT_END = 2'b10,
    S_ERROR    = 2'b11
} state_t;

state_t curr_state, nxt_state;

logic [7:0]    byte_cnt;
logic [159:0]  pkt_reg;

// State Register
always_ff @(posedge clk or negedge reset) begin
    if (!reset)
        curr_state <= S_IDLE;
    else
        curr_state <= nxt_state;
end

// Next State Logic
always_comb begin
    case (curr_state)
        S_IDLE:
            if ((data_in == START_SYMBOL) && (data_k_flag == 1'b1))
                nxt_state = S_ACTIVE;
            else
                nxt_state = S_IDLE;

        S_ACTIVE:
            if (byte_cnt == PKT_BYTES)
                nxt_state = S_WAIT_END;
            else
                nxt_state = S_ACTIVE;

        S_WAIT_END:
            if (pkt_reg[159:152] == END_SYMBOL)
                nxt_state = S_IDLE;
            else
                nxt_state = S_ERROR;

        S_ERROR:
            if ((data_in == START_SYMBOL) && (data_k_flag == 1'b1))
                nxt_state = S_ACTIVE;
            else
                nxt_state = S_ERROR;

        default: nxt_state = S_IDLE;
    endcase
end

// Datapath, packet validation, flag decode, and reset behavior.
//   1. Accumulate exactly PKT_BYTES bytes into pkt_reg during S_ACTIVE.
//      Right-shift so the most-recently received byte occupies the MSB
//      (pkt_reg[159:152]); the final (END_SYMBOL) byte therefore lands
//      at the position the next-state logic validates.
//   2. On a valid END_SYMBOL in S_WAIT_END, latch pkt_data, bump
//      pkt_count and decode the header byte (pkt_reg[31:24]) into the
//      one-hot detection flags.
//   3. Assert error_detected in S_ERROR and reset the accumulation.
always_ff @(posedge clk or negedge reset) begin
    if (!reset) begin
        byte_cnt                 <= 8'd0;
        pkt_reg                  <= 160'd0;
        pkt_data                 <= 160'd0;
        pkt_count                <= '0;
        mem_read_detected        <= 1'b0;
        mem_write_detected       <= 1'b0;
        io_read_detected         <= 1'b0;
        io_write_detected        <= 1'b0;
        cfg_read0_detected       <= 1'b0;
        cfg_write0_detected      <= 1'b0;
        cfg_read1_detected       <= 1'b0;
        cfg_write1_detected      <= 1'b0;
        completion_detected      <= 1'b0;
        completion_data_detected <= 1'b0;
        error_detected           <= 1'b0;
    end else begin
        case (curr_state)
            S_IDLE: begin
                byte_cnt       <= 8'd0;
                error_detected <= 1'b0;
            end

            S_ACTIVE: begin
                // Shift in and count exactly PKT_BYTES bytes.  The last
                // accepted byte is the END_SYMBOL and ends up at the MSB.
                if (byte_cnt < PKT_BYTES) begin
                    pkt_reg  <= {data_in, pkt_reg[159:8]};
                    byte_cnt <= byte_cnt + 8'd1;
                end
                error_detected <= 1'b0;
            end

            S_WAIT_END: begin
                byte_cnt <= 8'd0;
                if (pkt_reg[159:152] == END_SYMBOL) begin
                    pkt_data       <= pkt_reg;
                    pkt_count      <= pkt_count + 1'b1;
                    error_detected <= 1'b0;

                    // Re-decode all flags for this packet's header byte.
                    mem_read_detected        <= 1'b0;
                    mem_write_detected       <= 1'b0;
                    io_read_detected         <= 1'b0;
                    io_write_detected        <= 1'b0;
                    cfg_read0_detected       <= 1'b0;
                    cfg_write0_detected      <= 1'b0;
                    cfg_read1_detected       <= 1'b0;
                    cfg_write1_detected      <= 1'b0;
                    completion_detected      <= 1'b0;
                    completion_data_detected <= 1'b0;

                    // Header byte pkt_reg[31:24]:
                    //   bit[6]  -> pkt_reg[30] : 0 = read/no-data, 1 = write/with-data
                    //   bit[4:0]-> pkt_reg[28:24] : TLP type field
                    case (pkt_reg[28:24])
                        5'h00: if (pkt_reg[30]) mem_write_detected       <= 1'b1;
                               else             mem_read_detected        <= 1'b1;
                        5'h02: if (pkt_reg[30]) io_write_detected        <= 1'b1;
                               else             io_read_detected         <= 1'b1;
                        5'h04: if (pkt_reg[30]) cfg_write0_detected      <= 1'b1;
                               else             cfg_read0_detected       <= 1'b1;
                        5'h05: if (pkt_reg[30]) cfg_write1_detected      <= 1'b1;
                               else             cfg_read1_detected       <= 1'b1;
                        5'h0A: if (pkt_reg[30]) completion_data_detected <= 1'b1;
                               else             completion_detected      <= 1'b1;
                        default: ; // unrecognised header: leave all clear
                    endcase
                end
            end

            S_ERROR: begin
                // Invalid packet: flag the error and reset accumulation
                // so a fresh START can be captured on recovery.
                error_detected <= 1'b1;
                byte_cnt       <= 8'd0;
                pkt_reg        <= 160'd0;
            end

            default: begin
                byte_cnt       <= 8'd0;
                error_detected <= 1'b0;
            end
        endcase
    end
end

endmodule

module cvdp_prbs_gen #(
    parameter CHECK_MODE  = 0,
    parameter POLY_LENGTH = 31,
    parameter POLY_TAP    = 3,
    parameter WIDTH       = 16
) (
    input  wire             clk,
    input  wire             rst,
    input  wire [WIDTH-1:0] data_in,
    output reg  [WIDTH-1:0] data_out
);

    // 1-based indexing: bit 1 is the MSB, bit POLY_LENGTH is the LSB.
    wire [1:WIDTH]       data_in_i;
    reg  [1:POLY_LENGTH] lfsr_q;
    reg  [1:POLY_LENGTH] next_lfsr;
    reg  [1:WIDTH]       prbs_xor_a;   // generated PRBS bits
    reg  [1:WIDTH]       prbs_xor_b;   // checker (generated XOR data_in)
    reg  [1:POLY_LENGTH] cur;

    assign data_in_i = data_in;

    integer j;
    always @(*) begin
        cur = lfsr_q;
        for (j = 1; j <= WIDTH; j = j + 1) begin
            prbs_xor_a[j] = cur[POLY_TAP] ^ cur[POLY_LENGTH];
            prbs_xor_b[j] = prbs_xor_a[j] ^ data_in_i[j];
            // shift right, insert feedback bit at the MSB (bit 1)
            cur = {prbs_xor_a[j], cur[1:POLY_LENGTH-1]};
        end
        next_lfsr = cur;
    end

    always @(posedge clk) begin
        if (rst) begin
            data_out <= {WIDTH{1'b1}};
            lfsr_q   <= {POLY_LENGTH{1'b1}};
        end else begin
            data_out <= (CHECK_MODE == 0) ? prbs_xor_a : prbs_xor_b;
            lfsr_q   <= next_lfsr;
        end
    end

endmodule

module prim_max_find #(
  parameter int NumSrc = 8,
  parameter int Width = 8,
  // Derived parameters
  localparam int SrcWidth = $clog2(NumSrc),
  localparam int NumLevels = $clog2(NumSrc),
  localparam int NumNodes = 2**(NumLevels+1) - 1
) (
  input                         clk_i,
  input                         rst_ni,
  input [Width*NumSrc-1:0]      values_i,    // Flattened Input values
  input [NumSrc-1:0]            valid_i,     // Input valid bits
  output wire [Width-1:0]       max_value_o, // Maximum value
  output wire [SrcWidth-1:0]    max_idx_o,   // Index of the maximum value
  output wire                   max_valid_o  // Whether any of the inputs is valid
);

  reg [NumNodes-1:0]                vld_tree [0:NumLevels];
  reg [SrcWidth-1:0]                 idx_tree [0:NumLevels][NumNodes-1:0];
  reg [Width-1:0]                    max_tree [0:NumLevels][NumNodes-1:0];

  generate
    for (genvar level = 0; level <= NumLevels; level++) begin : gen_tree
      localparam int Base0 = (2**level) - 1;
      localparam int Base1 = (2**(level+1)) - 1;

      for (genvar offset = 0; offset < 2**level; offset++) begin : gen_level
        localparam int Pa = Base0 + offset;
        localparam int C0 = Base1 + 2*offset;
        localparam int C1 = Base1 + 2*offset + 1;

        if (level == NumLevels) begin : gen_leafs
          if (offset < NumSrc) begin : gen_assign
            always @(posedge clk_i or negedge rst_ni) begin
              if (!rst_ni) begin
                vld_tree[level][Pa] <= 1'b0;
                idx_tree[level][Pa] <= '0;
                max_tree[level][Pa] <= '0;
              end else begin
                vld_tree[level][Pa] <= valid_i[offset];
                idx_tree[level][Pa] <= offset;
                max_tree[level][Pa] <= values_i[offset*Width +: Width];
              end
            end
          end else begin : gen_tie_off
            always @(posedge clk_i or negedge rst_ni) begin
              if (!rst_ni) begin
                vld_tree[level][Pa] <= 1'b0;
                idx_tree[level][Pa] <= '0;
                max_tree[level][Pa] <= '0;
              end
            end
          end
        end

        else begin : gen_nodes
          reg sel;
          always @(posedge clk_i or negedge rst_ni) begin
            if (!rst_ni) begin
              vld_tree[level][Pa] <= 1'b0;
              idx_tree[level][Pa] <= '0;
              max_tree[level][Pa] <= '0;
            end else begin
              sel = (~vld_tree[level+1][C0] & vld_tree[level+1][C1]) |
                    (vld_tree[level+1][C0] & vld_tree[level+1][C1] & (max_tree[level+1][C1] > max_tree[level+1][C0]));

              vld_tree[level][Pa] <= (sel) ? vld_tree[level+1][C1] : vld_tree[level+1][C0];
              idx_tree[level][Pa] <= (sel) ? idx_tree[level+1][C1] : idx_tree[level+1][C0];
              max_tree[level][Pa] <= (sel) ? max_tree[level+1][C1] : max_tree[level+1][C0];
            end
          end
        end
      end : gen_level
    end : gen_tree
  endgenerate

  assign max_valid_o = vld_tree[0][0];
  assign max_idx_o   = idx_tree[0][0];
  assign max_value_o = max_tree[0][0];

endmodule

module radix2_div(
    input            clk,
    input            rst_n,
    input            start,
    input      [7:0] dividend,
    input      [7:0] divisor,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg       done
);

    reg [7:0] rem;
    reg [3:0] bit_counter;
    reg [7:0] divisor_reg;
    reg       busy;

    // Normal, correct shift and compare logic
    wire [8:0] shifted_rem = {rem, dividend[bit_counter]};
    wire       bit_set     = shifted_rem >= {1'b0, divisor_reg};
    wire [8:0] next_rem    = bit_set ? (shifted_rem - {1'b0, divisor_reg}) : shifted_rem;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            quotient <= 8'd0;
        else if (start && !busy) begin
            if (divisor == 8'd0)
                quotient <= 8'hFF;
            else
                quotient <= 8'd0;
        end
        else if (busy) begin
            quotient[bit_counter] <= bit_set;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            rem <= 8'd0;
        else if (start && !busy)
            rem <= 8'd0;
        else if (busy)
            rem <= next_rem[7:0];
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            remainder <= 8'd0;
        else if (start && !busy && divisor == 8'd0)
            remainder <= 8'hFF;
        else if (busy && bit_counter == 4'd0)
            remainder <= next_rem[7:0];
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            bit_counter <= 4'd0;
        else if (start && !busy) begin
            if (divisor != 8'd0)
                bit_counter <= 4'd7;  // Start from MSB
        end
        else if (busy && bit_counter != 4'd0) begin
            bit_counter <= bit_counter - 4'd1; // Normal decrement
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            divisor_reg <= 8'd0;
        else if (start && !busy && divisor != 8'd0)
            divisor_reg <= divisor;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            done <= 1'b0;
        else if (start && !busy) begin
            if (divisor == 8'd0)
                done <= 1'b1;
            else
                done <= 1'b0;
        end
        else if (busy && bit_counter == 4'd0)
            done <= 1'b1;
        else
            done <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            busy <= 1'b0;
        else if (start && !busy) begin
            if (divisor != 8'd0)
                busy <= 1'b1;
            else
                busy <= 1'b0;
        end
        else if (busy && bit_counter == 4'd0)
            busy <= 1'b0;
    end

endmodule

module reed_solomon_encoder #(
    parameter DATA_WIDTH = 8,   // Width of input data symbols
    parameter N = 255,         // Total number of symbols in the codeword
    parameter K = 223          // Number of data symbols
) (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [DATA_WIDTH-1:0] data_in,
    input wire valid_in,
    output reg [DATA_WIDTH-1:0] codeword_out,
    output reg valid_out,
    output reg [DATA_WIDTH-1:0] parity_0,
    output reg [DATA_WIDTH-1:0] parity_1
);

    localparam PARITY_SYMBOLS = N - K;// Number of parity symbols

    // Internal registers for shift-register based encoding
    reg [DATA_WIDTH-1:0] feedback;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all registers
            parity_0 <= 0 ;
            parity_1 <= 0 ;
            codeword_out <= 0;
            valid_out <= 0;
        end else if (enable && valid_in) begin
            // Shift-register based Reed-Solomon parity computation.
            // Feedback is derived from the incoming symbol XORed with the
            // last (top) parity register; each parity stage shifts from its
            // lower neighbour while the feedback is XORed with the
            // corresponding generator-polynomial coefficient.
            feedback = data_in ^ parity_1;
            parity_0 <= feedback ^ generator_polynomial(0);
            parity_1 <= parity_0 ^ feedback ^ generator_polynomial(1);
            // Systematic codeword: data symbols pass straight through.
            codeword_out <= data_in;
            valid_out <= 1'b1;
        end
    end

    function [DATA_WIDTH-1:0] generator_polynomial;
        input integer index;
        begin
            // Choose between the two generator-polynomial coefficients
            // based on the parity-stage index.
            if (index == 0)
                generator_polynomial = 8'h1D;
            else
                generator_polynomial = 8'h33;
        end
    endfunction

endmodule


