module cvdp_copilot_register_file_2R1W #(
    parameter DATA_WIDTH = 32,   // Configurable data width
    parameter DEPTH      = 32    // Number of register entries
) (
    // Inputs
    input  logic [DATA_WIDTH-1:0] din,     // Input data
    input  logic [4:0]            wad1,    // Write address
    input  logic [4:0]            rad1,    // Read address 1
    input  logic [4:0]            rad2,    // Read address 2
    input  logic                  wen1,    // Write-enable signal
    input  logic                  ren1,    // Read-enable signal 1
    input  logic                  ren2,    // Read-enable signal 2
    input  logic                  clk,     // Clock signal
    input  logic                  resetn,  // Active-low reset
    input  logic                  test_mode, // BIST activation (active high)

    // Outputs
    output logic [DATA_WIDTH-1:0] dout1,     // Output data 1
    output logic [DATA_WIDTH-1:0] dout2,     // Output data 2
    output logic                  collision, // Collision flag
    output logic                  bist_done, // BIST sequence complete
    output logic                  bist_fail  // BIST detected a mismatch
);

    // -------------------------------
    // Register-file storage
    // -------------------------------
    // The memory array has EXACTLY ONE synchronous driver (on the primary clk):
    // BIST-generated writes when test_mode, normal writes otherwise.  No gated
    // write clock is used (a gated clock lags clk by a delta and can drop a
    // single-cycle wen pulse).
    logic [DATA_WIDTH-1:0] rf_mem [0:DEPTH-1]; // Register-file memory
    logic [DEPTH-1:0]      rf_valid;           // Validity of each entry
    integer                i;

    // -------------------------------
    // BIST state / datapath
    // -------------------------------
    localparam logic [1:0] S_IDLE  = 2'd0;
    localparam logic [1:0] S_WRITE = 2'd1;
    localparam logic [1:0] S_READ  = 2'd2;
    localparam logic [1:0] S_DONE  = 2'd3;

    logic [1:0]               bist_state;           // BIST FSM state
    logic [$clog2(DEPTH):0]   bist_addr;            // March address pointer
    logic [DATA_WIDTH-1:0]    bist_pattern;         // Address-derived pattern
    logic [DATA_WIDTH-1:0]    read_data_reg;        // Latched read-back data
    logic [DATA_WIDTH-1:0]    expected_pattern_reg; // Latched expected pattern
    logic                     bist_compare_fail;    // Sticky compare-fail flag

    // Deterministic address-derived test pattern (pattern[a] = a).
    assign bist_pattern = bist_addr[DATA_WIDTH-1:0];

    // -------------------------------
    // BIST control FSM
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            bist_state           <= S_IDLE;
            bist_addr            <= '0;
            read_data_reg        <= '0;
            expected_pattern_reg <= '0;
            bist_compare_fail    <= 1'b0;
            bist_done            <= 1'b0;
            bist_fail            <= 1'b0;
        end else if (!test_mode) begin
            // BIST idle / cleared while in normal operation.
            bist_state           <= S_IDLE;
            bist_addr            <= '0;
            bist_compare_fail    <= 1'b0;
            bist_done            <= 1'b0;
            bist_fail            <= 1'b0;
        end else begin
            case (bist_state)
                S_IDLE: begin
                    // Enter the write pass of the march.
                    bist_state        <= S_WRITE;
                    bist_addr         <= '0;
                    bist_compare_fail <= 1'b0;
                    bist_done         <= 1'b0;
                    bist_fail         <= 1'b0;
                end

                S_WRITE: begin
                    // Write pattern to every location, then switch to read pass.
                    if (bist_addr == (DEPTH-1)) begin
                        bist_state <= S_READ;
                        bist_addr  <= '0;
                    end else begin
                        bist_addr  <= bist_addr + 1'b1;
                    end
                end

                S_READ: begin
                    // Read back and compare against the expected pattern.
                    read_data_reg        <= rf_mem[bist_addr];
                    expected_pattern_reg <= bist_pattern;
                    if (rf_mem[bist_addr] !== bist_pattern) begin
                        bist_compare_fail <= 1'b1;
                        bist_fail         <= 1'b1;
                    end
                    if (bist_addr == (DEPTH-1)) begin
                        bist_state <= S_DONE;
                    end else begin
                        bist_addr  <= bist_addr + 1'b1;
                    end
                end

                S_DONE: begin
                    // March complete: latch completion, hold state.
                    bist_done  <= 1'b1;
                    bist_state <= S_DONE;
                end

                default: bist_state <= S_IDLE;
            endcase
        end
    end

    // -------------------------------
    // Register-file write (single synchronous driver)
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                rf_mem[i] <= {DATA_WIDTH{1'b0}};
            end
            rf_valid <= '0;
        end else if (test_mode) begin
            // BIST-driven writes during the write pass.
            if (bist_state == S_WRITE) begin
                rf_mem[bist_addr]   <= bist_pattern;
                rf_valid[bist_addr] <= 1'b1;
            end
        end else if (wen1) begin
            // Normal write operation (disabled during test_mode).
            rf_mem[wad1]   <= din;
            rf_valid[wad1] <= 1'b1;
        end
    end

    // -------------------------------
    // Read ports (zero-latency combinational; disabled during test_mode)
    // -------------------------------
    assign dout1 = (test_mode) ? {DATA_WIDTH{1'b0}}
                 : (ren1 ? (rf_valid[rad1] ? rf_mem[rad1] : {DATA_WIDTH{1'b0}})
                         : {DATA_WIDTH{1'b0}});

    assign dout2 = (test_mode) ? {DATA_WIDTH{1'b0}}
                 : (ren2 ? (rf_valid[rad2] ? rf_mem[rad2] : {DATA_WIDTH{1'b0}})
                         : {DATA_WIDTH{1'b0}});

    // -------------------------------
    // Collision detection (forced off during test_mode)
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            collision <= 1'b0;
        end else if (test_mode) begin
            collision <= 1'b0;
        end else begin
            collision <= (
                (ren1 && ren2 && (rad1 == rad2)) ||   // Both reads to same address
                (wen1 && ren1 && (wad1 == rad1)) ||   // Write and read 1 to same address
                (wen1 && ren2 && (wad1 == rad2))      // Write and read 2 to same address
            );
        end
    end

endmodule

module cvdp_copilot_register_file_2R1W #(
    parameter DATA_WIDTH = 32  // Configurable data width
) (
    // Inputs
    input  logic [DATA_WIDTH-1:0] din,    // Input data
    input  logic [4:0] wad1,              // Write address
    input  logic [4:0] rad1,              // Read address 1
    input  logic [4:0] rad2,              // Read address 2
    input  logic wen1,                    // Write-enable signal
    input  logic ren1,                    // Read-enable signal 1
    input  logic ren2,                    // Read-enable signal 2
    input  logic clk,                     // Clock signal
    input  logic resetn,                  // Active-low reset

    // Outputs
    output logic [DATA_WIDTH-1:0] dout1,   // Output data 1
    output logic [DATA_WIDTH-1:0] dout2,   // Output data 2
    output logic collision                 // Collision flag
);

    // -------------------------------
    // Internal Registers and Wires
    // -------------------------------

    // Register file memory with 32 entries of DATA_WIDTH-bit words
    logic [DATA_WIDTH-1:0] rf_mem [0:31];
    logic [31:0] rf_valid;                   // Validity of each register entry
    integer i;

    // Clock Gating Enable Signal: High when any read or write operation is active
    wire clk_en = wen1 | ren1 | ren2;

    // Custom Clock Gating Logic
    logic gated_clk;    // Gated clock output
    logic en_latch;     // Enable latch

    // Enable latch generation logic:
    // Transparent while clk is low so the enable value captured is stable
    // before the rising edge; holds its value while clk is high.
    always @(*) begin
        if (!clk)
            en_latch = clk_en;
    end

    // Gated clock output logic: pass the clock through only when the
    // latched enable is asserted.
    always @(*) begin
        gated_clk = clk & en_latch;
    end

    // -------------------------------
    // Register File Operations
    // -------------------------------

    // Reset and Write Operation Logic with Gated Clock
    always_ff @(posedge gated_clk or negedge resetn) begin
        if (!resetn) begin
            // Zero-initialise all memory entries on reset
            for (i = 0; i < 32; i = i + 1) begin
                rf_mem[i] <= '0;
            end
            rf_valid <= 0;  // Mark all entries as invalid
        end
        else if (wen1) begin
            // Write operation and validity update
            rf_mem[wad1]   <= din;
            rf_valid[wad1] <= 1'b1;
        end
    end

    // Read Data Output Logic for Port 1 with Gated Clock
    always_ff @(posedge gated_clk or negedge resetn) begin
        if (!resetn) begin
            dout1 <= 0;
        end
        else if (ren1) begin
            dout1 <= rf_valid[rad1] ? rf_mem[rad1] : 0;  // Output data if valid
        end
        else begin
            dout1 <= 0;
        end
    end

    // Read Data Output Logic for Port 2 with Gated Clock
    always_ff @(posedge gated_clk or negedge resetn) begin
        if (!resetn) begin
            dout2 <= 0;
        end
        else if (ren2) begin
            dout2 <= rf_valid[rad2] ? rf_mem[rad2] : 0;  // Output data if valid
        end
        else begin
            dout2 <= 0;
        end
    end

    // -------------------------------
    // Collision Detection Logic
    // -------------------------------

    // Collision Flag Logic with Original Clock (non-gated)
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            collision <= 0;
        end
        else begin
            // Collision when both reads hit the same address, or a write
            // conflicts with either active read port.
            collision <= (ren1 & ren2 & (rad1 == rad2))
                       | (wen1 & ren1 & (wad1 == rad1))
                       | (wen1 & ren2 & (wad1 == rad2));
        end
    end

endmodule

module restoring_division #(
    parameter WIDTH = 6
) (
    input  wire             clk,
    input  wire             rst,       // active-low asynchronous reset
    input  wire             start,     // active-high start
    input  wire [WIDTH-1:0] dividend,
    input  wire [WIDTH-1:0] divisor,
    output reg  [WIDTH-1:0] quotient,
    output reg  [WIDTH-1:0] remainder,
    output reg              valid
);

    localparam IDLE = 1'b0;
    localparam CALC = 1'b1;

    reg                   state;
    reg [WIDTH-1:0]       dvd;    // dividend shift register (MSB first)
    reg [WIDTH-1:0]       dvs;    // divisor register
    reg [WIDTH:0]         rem;    // remainder/accumulator, WIDTH+1 bits
    reg [WIDTH-1:0]       quo;    // quotient being assembled
    reg [$clog2(WIDTH):0] count;  // iteration counter

    // one shift-and-subtract step (combinational, from current registers)
    wire [WIDTH:0] shifted  = {rem[WIDTH-1:0], dvd[WIDTH-1]};
    wire [WIDTH:0] sub      = shifted - {1'b0, dvs};
    wire           qbit     = ~sub[WIDTH];                 // 1 if subtraction fit
    wire [WIDTH:0] next_rem = sub[WIDTH] ? shifted : sub;  // restore on negative

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            state     <= IDLE;
            dvd       <= {WIDTH{1'b0}};
            dvs       <= {WIDTH{1'b0}};
            rem       <= {(WIDTH+1){1'b0}};
            quo       <= {WIDTH{1'b0}};
            count     <= {($clog2(WIDTH)+1){1'b0}};
            quotient  <= {WIDTH{1'b0}};
            remainder <= {WIDTH{1'b0}};
            valid     <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    valid <= 1'b0;
                    if (start) begin
                        dvd   <= dividend;
                        dvs   <= divisor;
                        rem   <= {(WIDTH+1){1'b0}};
                        quo   <= {WIDTH{1'b0}};
                        count <= {($clog2(WIDTH)+1){1'b0}};
                        state <= CALC;
                    end
                end
                CALC: begin
                    rem   <= next_rem;
                    quo   <= (quo << 1) | qbit;
                    dvd   <= dvd << 1;
                    count <= count + 1'b1;
                    if (count == WIDTH-1) begin
                        quotient  <= (quo << 1) | qbit;
                        remainder <= next_rem[WIDTH-1:0];
                        valid     <= 1'b1;
                        state     <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule


