// reverse_bits
// Combinational 32-bit bit-reversal.
// The LSB of num_in becomes the MSB of num_out, the 2nd LSB becomes the
// 2nd MSB, and so on. Purely combinational: no clock, no reset.
module reverse_bits (
    input  [31:0] num_in,   // 32-bit unsigned number to be reversed
    output [31:0] num_out    // bit-reversed 32-bit result
);

    // For every bit position i of the output, take the mirror-image bit
    // (31 - i) of the input, so num_out[31] = num_in[0], num_out[0] = num_in[31].
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : reverse_loop
            assign num_out[i] = num_in[31 - i];
        end
    endgenerate

endmodule

module axis_rgb2ycbcr #(
    parameter PIXEL_WIDTH = 16,
    parameter FIFO_DEPTH = 16
)(
    input  wire            aclk,
    input  wire            aresetn,

    // AXI Stream Slave Interface (Input)
    input  wire [15:0]     s_axis_tdata,
    input  wire            s_axis_tvalid,
    output wire            s_axis_tready,
    input  wire            s_axis_tlast,
    input  wire            s_axis_tuser,

    // AXI Stream Master Interface (Output)
    output wire [15:0]     m_axis_tdata,
    output wire            m_axis_tvalid,
    input  wire            m_axis_tready,
    output wire            m_axis_tlast,
    output wire            m_axis_tuser
);

    // -----------------------------
    // FIFO Buffer (16-depth buffer)
    // -----------------------------
    reg [15:0] fifo_data [0:FIFO_DEPTH-1];
    reg        fifo_tlast [0:FIFO_DEPTH-1];
    reg        fifo_tuser [0:FIFO_DEPTH-1];

    reg [3:0]  write_ptr, read_ptr; // 4-bit pointers for FIFO
    reg        full;
    wire       empty;

    wire       fifo_write = s_axis_tvalid && !full;
    wire       fifo_read  = !empty && m_axis_tready;

    // -----------------------------
    // RGB Extraction (combinational, from the current input pixel)
    // -----------------------------
    wire [7:0] r = {s_axis_tdata[15:11], 3'b0}; // 5-bit to 8-bit
    wire [7:0] g = {s_axis_tdata[10:5],  2'b0}; // 6-bit to 8-bit
    wire [7:0] b = {s_axis_tdata[4:0],   3'b0}; // 5-bit to 8-bit

    // -----------------------------
    // RGB to YCbCr Conversion (combinational)
    // -----------------------------
    wire [7:0] y_calc  = (( 77 * r + 150 * g +  29 * b) >> 8) + 16;
    wire [7:0] cb_calc = ((-43 * r - 85 * g + 128 * b) >> 8) + 128;
    wire [7:0] cr_calc = ((128 * r - 107 * g - 21 * b) >> 8) + 128;

    // -----------------------------
    // FIFO Buffer Write
    // Store the current pixel's YCbCr in the SAME cycle it is accepted so that
    // the write pointer and the computed data stay aligned (no unintended
    // pipeline delay). fifo_data[i] therefore holds the conversion of input i.
    // -----------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            write_ptr <= 0;
            full <= 0;
        end else if (fifo_write) begin
            fifo_data[write_ptr]  <= {y_calc[7:3], cb_calc[7:2], cr_calc[7:3]}; // Store YCbCr in buffer
            fifo_tlast[write_ptr] <= s_axis_tlast;
            fifo_tuser[write_ptr] <= s_axis_tuser;
            write_ptr <= write_ptr + 1;
            full <= (write_ptr == FIFO_DEPTH-1);
        end
    end

    // -----------------------------
    // FIFO Buffer Read
    // -----------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            read_ptr <= 0;
        end else if (fifo_read) begin
            read_ptr <= read_ptr + 1;
        end
    end
    assign empty = (read_ptr == write_ptr);

    // -----------------------------
    // AXI-Stream Output Signals
    // -----------------------------
    assign s_axis_tready = !full; // Only accept data when FIFO is not full
    assign m_axis_tvalid = !empty; // Only transmit when FIFO has data
    assign m_axis_tdata  = fifo_data[read_ptr];
    assign m_axis_tlast  = fifo_tlast[read_ptr];
    assign m_axis_tuser  = fifo_tuser[read_ptr];

endmodule

module round_robin_arbiter #(
    parameter N       = 4,
    parameter TIMEOUT = 16
)(
    input  wire             clk,
    input  wire             rstn,
    input  wire [N-1:0]     req,
    input  wire [N-1:0]     priority_level,
    output reg  [N-1:0]     grant,
    output wire             idle
);

    reg [$clog2(N)-1:0] pointer;
    reg [$clog2(N)-1:0] pointer_next;
    reg                 found;

    // Independent timeout counter per channel (32 bits each).
    reg [31:0] timeout_counter [0:N-1];

    integer i;
    integer j;
    integer idx;

    // Idle: high when no channel has an active request.
    assign idle = (req == {N{1'b0}});

    // Combinational grant selection: high-priority (or timed-out) channels
    // are served first; ties broken by the round-robin pointer.
    always @(*) begin
        grant        = {N{1'b0}};
        pointer_next = pointer;
        found        = 1'b0;

        if (req != {N{1'b0}}) begin
            // Pass 1: elevated requests (statically high priority OR timed out).
            for (i = 0; i < N; i = i + 1) begin
                idx = (pointer + i) % N;
                if (!found && req[idx] &&
                    (priority_level[idx] || (timeout_counter[idx] >= TIMEOUT))) begin
                    grant[idx]   = 1'b1;
                    pointer_next = (idx + 1) % N;
                    found        = 1'b1;
                end
            end
            // Pass 2: any pending request in round-robin order.
            if (!found) begin
                for (i = 0; i < N; i = i + 1) begin
                    idx = (pointer + i) % N;
                    if (!found && req[idx]) begin
                        grant[idx]   = 1'b1;
                        pointer_next = (idx + 1) % N;
                        found        = 1'b1;
                    end
                end
            end
        end
    end

    // Registered state: round-robin pointer + per-channel timeout counters.
    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            pointer <= {$clog2(N){1'b0}};
            for (j = 0; j < N; j = j + 1)
                timeout_counter[j] <= 32'b0;
        end else begin
            pointer <= pointer_next;
            for (j = 0; j < N; j = j + 1) begin
                // Count while a request stays pending and ungranted;
                // clear as soon as it is granted or withdrawn.
                if (req[j] && !grant[j])
                    timeout_counter[j] <= timeout_counter[j] + 32'b1;
                else
                    timeout_counter[j] <= 32'b0;
            end
        end
    end

endmodule

module rounding #(
  parameter WIDTH = 24
)(
  input  logic [WIDTH-1:0] in_data  , // Input value for rounding
  input  logic             sign     , // Indicates sign of input (1: negative, 0: positive)
  input  logic             roundin  , // Round bit
  input  logic             stickyin , // Sticky bit for precision
  input  logic [2:0]       rm       , // Rounding mode
  output logic [WIDTH-1:0] out_data , // Rounded output
  output logic             inexact  , // Indicates precision loss
  output logic             cout     , // Carry-out signal
  output logic             r_up       // Indicates rounding up
);

  localparam RNE = 3'b000; // Round to Nearest, ties to Even
  localparam RTZ = 3'b001; // Round Toward Zero (truncate)
  localparam RUP = 3'b010; // Round toward +Infinity (ceiling)
  localparam RDN = 3'b011; // Round toward -Infinity (floor)
  localparam RMM = 3'b100; // Round to Nearest, ties to Max Magnitude (away from zero)

  logic rounding_up;
  logic lsb;

  // Least-significant bit of the input (used for RNE tie-to-even).
  assign lsb = in_data[0];

  // The round-up decision is a pure function of the round (guard) bit,
  // the sticky bit, the sign, the current LSB and the rounding mode.
  always_comb begin
    case (rm)
      // Ties (round & !sticky) resolve to even: round up only if LSB is odd.
      RNE:     rounding_up = roundin & (stickyin | lsb);
      // Truncate: never increase magnitude.
      RTZ:     rounding_up = 1'b0;
      // Ceiling: only positive, inexact values move up (increase magnitude).
      RUP:     rounding_up = (~sign) & (roundin | stickyin);
      // Floor: only negative, inexact values move up (increase magnitude).
      RDN:     rounding_up = sign & (roundin | stickyin);
      // Away from zero: any guard bit rounds up (ties go away from zero).
      RMM:     rounding_up = roundin;
      // Unsupported modes default to no rounding (RTZ behavior).
      default: rounding_up = 1'b0;
    endcase
  end

  // Increment by the round-up decision; the carry out of the WIDTH range is cout.
  assign {cout, out_data} = {1'b0, in_data} + rounding_up;

  // Precision was lost whenever a round or sticky bit is present.
  assign inexact = roundin | stickyin;

  // Report whether an increment actually took place.
  assign r_up = rounding_up;

endmodule

module copilot_rs_232 (
    clock,
    reset_neg,
    tx_datain_ready,
    Present_Processing_Completed,
    tx_datain,
    tx_transmitter,
    tx_transmitter_valid
);
    // Parameters
    parameter HIGH = 1'b1;
    parameter LOW = 1'b0;
    parameter CLOCK_FREQ = 100000000; // 100MHz
    parameter BAUD_RATE = 115200;     // Default baud rate
    parameter REG_INPUT = 1;
    parameter BAUD_ACC_WIDTH = 16;

    // Inputs
    input reset_neg;
    input clock;
    input tx_datain_ready;
    input Present_Processing_Completed;
    input [7:0] tx_datain;

    // Outputs
    output tx_transmitter;
    output tx_transmitter_valid;

    // Internal signals
    reg tx_transmitter;
    wire baud_pulse;

    // Instantiate the Baud Rate Generator
    baud_rate_generator #(
        .BAUD_ACC_WIDTH(BAUD_ACC_WIDTH),
        .CLOCK_FREQ(CLOCK_FREQ),
        .BAUD_RATE(BAUD_RATE)
    ) baud_gen (
        .clock(clock),
        .reset_neg(reset_neg),
        .enable(tx_transmitter_valid),
        .baud_pulse(baud_pulse)
    );

    // ---------------------------------------------------------------
    // Transmitter State Machine
    // ---------------------------------------------------------------
    // 4-bit state encoding chosen so the given glitch-free output
    // expression  (State < 4) | (State[3] & MuxBit)  produces:
    //   idle / stop bits (State < 4)  -> line HIGH
    //   start bit        (State == 4) -> line LOW
    //   data bits 0..7   (State[3]=1) -> line = MuxBit
    reg [3:0] State;

    // Ready when idle; transmitter is busy (valid) otherwise.
    wire tx_ready = (State == 4'b0000);
    assign tx_transmitter_valid = ~tx_ready;

    // Optionally register the input data (REG_INPUT).
    reg [7:0] tx_dataReg;
    always @(posedge clock or negedge reset_neg) begin
        if (reset_neg == LOW)
            tx_dataReg <= 8'h00;
        else if (Present_Processing_Completed == HIGH)
            tx_dataReg <= 8'h00;
        else if (tx_ready & tx_datain_ready)
            tx_dataReg <= tx_datain;
    end
    wire [7:0] tx_dataD = REG_INPUT ? tx_dataReg : tx_datain;

    // State transitions.  Bit periods are paced by baud_pulse.
    always @(posedge clock or negedge reset_neg) begin
        if (reset_neg == LOW)
            State <= 4'b0000;
        else if (Present_Processing_Completed == HIGH)
            State <= 4'b0000;   // resets internal state, line returns to idle
        else begin
            case (State)
                4'b0000: if (tx_datain_ready) State <= 4'b0100; // idle -> start requested
                4'b0100: if (baud_pulse)      State <= 4'b1000; // start bit  -> data0
                4'b1000: if (baud_pulse)      State <= 4'b1001; // data bit 0
                4'b1001: if (baud_pulse)      State <= 4'b1010; // data bit 1
                4'b1010: if (baud_pulse)      State <= 4'b1011; // data bit 2
                4'b1011: if (baud_pulse)      State <= 4'b1100; // data bit 3
                4'b1100: if (baud_pulse)      State <= 4'b1101; // data bit 4
                4'b1101: if (baud_pulse)      State <= 4'b1110; // data bit 5
                4'b1110: if (baud_pulse)      State <= 4'b1111; // data bit 6
                4'b1111: if (baud_pulse)      State <= 4'b0010; // data bit 7 -> stop1
                4'b0010: if (baud_pulse)      State <= 4'b0011; // stop bit 1 -> stop2
                4'b0011: if (baud_pulse)      State <= 4'b0000; // stop bit 2 -> idle
                default: if (baud_pulse)      State <= 4'b0000;
            endcase
        end
    end

    // ---------------------------------------------------------------
    // Output Multiplexer
    // ---------------------------------------------------------------
    // During the data states (State[3]=1) State[2:0] selects the bit,
    // LSB first.
    reg MuxBit;
    always @(*) begin
        case (State[2:0])
            3'd0: MuxBit = tx_dataD[0];
            3'd1: MuxBit = tx_dataD[1];
            3'd2: MuxBit = tx_dataD[2];
            3'd3: MuxBit = tx_dataD[3];
            3'd4: MuxBit = tx_dataD[4];
            3'd5: MuxBit = tx_dataD[5];
            3'd6: MuxBit = tx_dataD[6];
            3'd7: MuxBit = tx_dataD[7];
        endcase
    end

    // Assemble Start, Data, and Stop Bits
    always @ (posedge clock or negedge reset_neg) begin
        if (reset_neg == LOW) begin
            tx_transmitter <= HIGH;
        end else if (Present_Processing_Completed == HIGH) begin
            tx_transmitter <= HIGH;
        end else begin
            tx_transmitter <= (State < 4) | (State[3] & MuxBit); // Glitch-free output
        end
    end

endmodule

// Baud Rate Generator Module
module baud_rate_generator #(
    parameter CLOCK_FREQ = 100000000, // 100MHz
    parameter BAUD_RATE = 115200, // Default baud rate
    parameter BAUD_ACC_WIDTH = 16
)
 (
    input clock,
    input reset_neg,
    input enable,
    output reg baud_pulse
);


    // Internal signals
    wire [BAUD_ACC_WIDTH:0] baud_inc;
    reg [BAUD_ACC_WIDTH:0] baud_acc;

    // Calculate the baud increment value
    assign baud_inc = ((BAUD_RATE << (BAUD_ACC_WIDTH - 4)) + (CLOCK_FREQ >> 5)) / (CLOCK_FREQ >> 4);

    // Accumulate the increment while enabled.  Only the low BAUD_ACC_WIDTH
    // bits are retained each cycle; the carry into the top bit
    // (baud_acc[BAUD_ACC_WIDTH]) marks one baud period and is presented
    // on baud_pulse.
    always @(posedge clock or negedge reset_neg) begin
        if (reset_neg == 1'b0)
            baud_acc <= 0;
        else if (enable)
            baud_acc <= baud_acc[BAUD_ACC_WIDTH-1:0] + baud_inc;
        else
            baud_acc <= 0;
    end

    always @(*)
        baud_pulse = baud_acc[BAUD_ACC_WIDTH];

endmodule

module run_length
#(
    parameter DATA_WIDTH = 8                        // Width of the output run-length counter
)
(
    input wire clk,                                 // Clock signal
    input wire reset_n,                             // Active-low reset signal
    input wire data_in,                             // Input data stream
    output reg  data_out,                           // Output data to indicate the previous data_in
    output reg [$clog2(DATA_WIDTH):0] run_value,    // Output the run length value
    output reg valid                                // Output valid flag for run length

);
    reg [$clog2(DATA_WIDTH):0] run_length;
    reg prev_data_in;

    // Run-length counting logic: track run_length / run_value / prev_data_in.
    // A run terminates on EITHER a value transition OR saturation at DATA_WIDTH.
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            run_length   <= 'b0;
            run_value    <= 'b0;
            prev_data_in <= 1'b0;
        end
        else begin
            if (data_in != prev_data_in) begin
                // Value transition: emit the length of the just-ended run,
                // then start a new run with the current sample (length 1).
                run_value  <= run_length;
                run_length <= 'd1;
            end
            else begin
                // Same value: continue the run, saturating at DATA_WIDTH.
                if (run_length == DATA_WIDTH) begin
                    // Counter already at the maximum -> saturation event:
                    // output DATA_WIDTH and credit the current sample to the new run.
                    run_value  <= DATA_WIDTH;
                    run_length <= 'd1;
                end
                else begin
                    run_length <= run_length + 1'b1;
                end
            end
            prev_data_in <= data_in;
        end
    end

    // valid / data_out generation (reads the same registered state as above).
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            valid    <= 1'b0;
            data_out <= 1'b0;
        end
        else begin
            if (data_in != prev_data_in) begin
                // Transition: pulse valid and present the previous run's value.
                valid    <= 1'b1;
                data_out <= prev_data_in;
            end
            else if (run_length == DATA_WIDTH) begin
                // Saturation: pulse valid (data_out not updated on a non-transition).
                valid    <= 1'b1;
                data_out <= 1'b0;
            end
            else begin
                valid    <= 1'b0;
                data_out <= 1'b0;
            end
        end
    end

endmodule

module parallel_run_length
#(
    parameter DATA_WIDTH  = 8,                     // Maximum run length per stream
    parameter NUM_STREAMS = 4                      // Number of parallel input streams
)
(
    input  wire                                             clk,           // Clock (rising edge)
    input  wire                                             reset_n,       // Active-low async reset
    input  wire [NUM_STREAMS-1:0]                           data_in,       // Parallel input streams
    input  wire [NUM_STREAMS-1:0]                           stream_enable, // Per-stream enable
    output reg  [NUM_STREAMS-1:0]                           data_out,      // Last value per stream
    output reg  [(NUM_STREAMS*($clog2(DATA_WIDTH)+1))-1:0]  run_value,     // Packed run lengths
    output reg  [NUM_STREAMS-1:0]                           valid          // Per-stream valid flag
);

    localparam RW = $clog2(DATA_WIDTH) + 1;        // Run-length field width

    reg [RW-1:0] run_length [0:NUM_STREAMS-1];
    reg          prev_data  [0:NUM_STREAMS-1];

    genvar gi;
    generate
        for (gi = 0; gi < NUM_STREAMS; gi = gi + 1) begin : stream
            // Run-length counter + run_value field for this stream.
            always @(posedge clk or negedge reset_n) begin
                if (!reset_n) begin
                    run_length[gi]         <= {RW{1'b0}};
                    run_value[gi*RW +: RW] <= {RW{1'b0}};
                    prev_data[gi]          <= 1'b0;
                end else if (!stream_enable[gi]) begin
                    // Disabled stream: reset/hold at default; resume fresh later.
                    run_length[gi]         <= {RW{1'b0}};
                    run_value[gi*RW +: RW] <= {RW{1'b0}};
                    prev_data[gi]          <= 1'b0;
                end else begin
                    if (data_in[gi] == prev_data[gi]) begin
                        if (run_length[gi] == DATA_WIDTH) begin
                            run_value[gi*RW +: RW] <= run_length[gi];
                        end
                        if (run_length[gi] < DATA_WIDTH) begin
                            run_length[gi] <= run_length[gi] + 1'b1;
                        end else begin
                            run_length[gi] <= 1'b1;
                        end
                    end else begin
                        run_value[gi*RW +: RW] <= run_length[gi];
                        run_length[gi]         <= 1'b1;
                    end
                    prev_data[gi] <= data_in[gi];
                end
            end

            // Valid + data_out for this stream (aligned with run_value update).
            always @(posedge clk or negedge reset_n) begin
                if (!reset_n) begin
                    valid[gi]    <= 1'b0;
                    data_out[gi] <= 1'b0;
                end else if (!stream_enable[gi]) begin
                    valid[gi]    <= 1'b0;
                    data_out[gi] <= 1'b0;
                end else begin
                    if (run_length[gi] == DATA_WIDTH || data_in[gi] != prev_data[gi]) begin
                        valid[gi]    <= 1'b1;
                        data_out[gi] <= prev_data[gi];
                    end else begin
                        valid[gi]    <= 1'b0;
                        data_out[gi] <= 1'b0;
                    end
                end
            end
        end
    endgenerate

endmodule

module scrambler #(
    parameter DATA_WIDTH = 128   // Width of input data
) (
    input  logic                  clk,        // Clock signal
    input  logic                  rst_n,      // Active-low reset
    input  logic [DATA_WIDTH-1:0] data_in,    // Input data
    input  logic [3:0]            mode,       // Mode to select polynomial
    output logic [DATA_WIDTH-1:0] data_out    // Scrambled data
);

    localparam LFSR_WIDTH = 16;    // Width of the LFSR
    localparam [LFSR_WIDTH-1:0] LFSR_INIT = {1'b0,1'b1,{(LFSR_WIDTH-2){1'b0}}};
    // LFSR registers and feedback logic
    logic [LFSR_WIDTH-1:0] lfsr;
    logic feedback;

    // Polynomial selection based on mode.
    // For a left-shifting LFSR (lfsr <= {lfsr[LFSR_WIDTH-2:0], feedback}) the
    // feedback tap for term x^k is bit lfsr[k-1]. The x^0 ("+1") term is the
    // implicit feedback insertion point and is not a tap.
    always_comb begin
        case (mode)
            4'b0000: feedback = lfsr[15] ^ lfsr[14];             // Mode 0: x^16 + x^15 + 1
            4'b0001: feedback = lfsr[15] ^ lfsr[13];             // Mode 1: x^16 + x^14 + 1
            4'b0010: feedback = lfsr[15] ^ lfsr[7]  ^ lfsr[0];   // Mode 2: x^16 + x^8 + x + 1
            4'b0011: feedback = lfsr[15] ^ lfsr[7];              // Mode 3: x^16 + x^8 + 1
            4'b0100: feedback = lfsr[15] ^ lfsr[12] ^ lfsr[1];   // Mode 4: x^16 + x^13 + x^2 + 1
            4'b0101: feedback = lfsr[15] ^ lfsr[11];             // Mode 5: x^16 + x^12 + 1
            4'b0110: feedback = lfsr[15] ^ lfsr[2]  ^ lfsr[0];   // Mode 6: x^16 + x^3 + x + 1
            4'b0111: feedback = lfsr[15] ^ lfsr[10] ^ lfsr[3];   // Mode 7: x^16 + x^11 + x^4 + 1
            default: feedback = lfsr[15] ^ lfsr[0];              // Mode 8: x^16 + x + 1
        endcase
    end

    // LFSR shift logic
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr <= LFSR_INIT; // Initialize LFSR with a fixed value
        end else begin
            lfsr <= {lfsr[LFSR_WIDTH-2:0], feedback};
        end
    end

    // Scramble data block
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i++) begin
            assign data_out[i] = data_in[i] ^ lfsr[i % LFSR_WIDTH];
        end
    endgenerate

endmodule

module deinter_block #(
    parameter ROW_COL_WIDTH = 16,
    parameter SUB_BLOCKS    = 4,
    parameter DATA_WIDTH    = ROW_COL_WIDTH*ROW_COL_WIDTH,
    parameter OUT_DATA_WIDTH= 16,
    parameter WAIT_CYCLES   = 4
)(
    input  logic clk,
    input  logic rst_n,
    input  logic i_valid,
    input  logic [DATA_WIDTH-1:0] in_data, // Input: 256 bits
    output logic [OUT_DATA_WIDTH-1:0] out_data // Output: 256 bits rearranged
);

localparam CHUNK = 8;
localparam NBW_COUNTER = $clog2(SUB_BLOCKS) + 1;
localparam NBW_COUNTER_SUB_OUT = 2;

localparam OUT_CYCLES = 32;

localparam N_CYCLES = SUB_BLOCKS*DATA_WIDTH/OUT_DATA_WIDTH;
localparam NBW_COUNTER_OUTPUT = $clog2(N_CYCLES);
logic [NBW_COUNTER_OUTPUT-1:0] counter_output;

logic [NBW_COUNTER-1:0] counter_sub_blocks;
logic [NBW_COUNTER_SUB_OUT-1:0] counter_sub_out;

logic [DATA_WIDTH-1:0] in_data_reg [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_intra_block [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_intra_block_reg [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_aux [SUB_BLOCKS-1:0];
logic start_intra;

always_ff @(posedge clk or negedge rst_n ) begin
   if(!rst_n) begin
      counter_sub_blocks <= {NBW_COUNTER{1'b0}};
      start_intra <= 0;
      for(int i = 0; i < SUB_BLOCKS; i++) begin
         in_data_reg[i] <= {DATA_WIDTH{1'b0}};
      end
   end
   else begin
      if(i_valid) begin
         in_data_reg[counter_sub_blocks] <= in_data;

         if(counter_sub_blocks == SUB_BLOCKS) begin
            counter_sub_blocks <= {NBW_COUNTER{1'b0}};
         end
         else begin
            start_intra <= 0;
            counter_sub_blocks <= counter_sub_blocks + 1;
         end
      end
      else if(counter_sub_blocks == SUB_BLOCKS) begin
         start_intra        <= 1;
         counter_sub_blocks <= {NBW_COUNTER{1'b0}};
      end
   end
end

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      for(int i = 0; i < SUB_BLOCKS; i++)
         out_data_intra_block_reg[i] <= {DATA_WIDTH{1'b0}};
   end
   else begin
      if(start_intra)
         for(int i = 0; i < SUB_BLOCKS; i++)
            out_data_intra_block_reg[i] <= in_data_reg[i];
   end
end

logic [WAIT_CYCLES-1:0] start_intra_ff;
logic enable_output;

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      enable_output  <= 0;
      start_intra_ff <= 0;
   end
   else begin
      enable_output <= start_intra_ff[WAIT_CYCLES-1];
      // BUGFIX: the original concat {start_intra_ff[WAIT_CYCLES-1:1], start_intra}
      // left the upper stages stuck at their reset value so start_intra never
      // reached the MSB and enable_output never asserted.  A correct shift
      // register drops the MSB, shifts every stage up one and injects
      // start_intra at bit 0, delaying it by exactly WAIT_CYCLES cycles.
      start_intra_ff<= {start_intra_ff[WAIT_CYCLES-2:0],start_intra};
   end
end

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      for(int i = 0; i < SUB_BLOCKS; i++)
         out_data_aux[i] <= {DATA_WIDTH{1'b0}};
   end
   else begin
      if(start_intra) begin
         for(int i = 0; i < 32; i++) begin
            out_data_aux[0][(i+1)*CHUNK-1-:CHUNK] <= out_data_intra_block_reg[i%4][((i+1)*CHUNK)-1-:CHUNK];
            out_data_aux[1][(i+1)*CHUNK-1-:CHUNK] <= out_data_intra_block_reg[i%4][(((i+1)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
            out_data_aux[2][(i+1)*CHUNK-1-:CHUNK] <= out_data_intra_block_reg[i%4][(((i+2)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
            out_data_aux[3][(i+1)*CHUNK-1-:CHUNK] <= out_data_intra_block_reg[i%4][(((i+3)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
         end
      end
   end
end

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      out_data        <= {DATA_WIDTH{1'b0}};
      counter_sub_out <= {NBW_COUNTER_SUB_OUT{1'b0}};
      counter_output  <= {NBW_COUNTER_OUTPUT{1'b0}};
   end
   // BUGFIX: the original output stage ran unconditionally every cycle, so the
   // output counters free-ran from reset and out_data started emitting data
   // (at the wrong offset) before the WAIT_CYCLES delay elapsed.  Gate the
   // whole output stage on enable_output so the counters start from 0 and
   // output begins exactly when the delayed start flag arrives.
   else if(enable_output) begin
      counter_sub_out <= counter_sub_out + 1;
      counter_output  <= counter_output  + 1;
      out_data        <= out_data_aux[counter_sub_out][((counter_output%(DATA_WIDTH/OUT_DATA_WIDTH) + 1))*OUT_DATA_WIDTH-1-:OUT_DATA_WIDTH];
   end
end

endmodule

module inter_block #(
    parameter ROW_COL_WIDTH = 16,
    parameter SUB_BLOCKS    = 4,
    parameter DATA_WIDTH    = ROW_COL_WIDTH*ROW_COL_WIDTH
)(
    input  logic clk,
    input  logic rst_n,
    input  logic i_valid,
    input  logic [DATA_WIDTH-1:0] in_data, // Input: 256 bits
    output logic [DATA_WIDTH-1:0] out_data // Output: 256 bits rearranged
);

localparam CHUNK = 8;
localparam NBW_COUNTER = $clog2(SUB_BLOCKS) + 1;
localparam NBW_COUNTER_SUB_OUT = 2;
localparam OUT_CYCLES = 32;
logic [NBW_COUNTER-1:0] counter_sub_blocks;
logic [NBW_COUNTER_SUB_OUT-1:0] counter_sub_out;

logic [DATA_WIDTH-1:0] in_data_reg [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_intra_block [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_intra_block_reg [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_aux [SUB_BLOCKS-1:0];
logic start_intra;

always_ff @(posedge clk or negedge rst_n ) begin
   if(!rst_n) begin
      counter_sub_blocks <= {NBW_COUNTER{1'b0}};
      start_intra <= 0;
      for(int i = 0; i < SUB_BLOCKS; i++) begin
         in_data_reg[i] <= {DATA_WIDTH{1'b0}};
      end
   end
   else begin
      if(i_valid) begin
         in_data_reg[counter_sub_blocks] <= in_data;

         if(counter_sub_blocks == SUB_BLOCKS) begin
            counter_sub_blocks <= {NBW_COUNTER{1'b0}};
         end
         else begin
            start_intra <= 0;
            counter_sub_blocks <= counter_sub_blocks + 1;
         end
      end
      else if(counter_sub_blocks == SUB_BLOCKS) begin
         start_intra        <= 1;
         counter_sub_blocks <= {NBW_COUNTER{1'b0}};
      end
   end
end

genvar k;
generate
   for(k = 0; k < SUB_BLOCKS; k++) begin
      intra_block uu_intra_block (
         .in_data(in_data_reg[k]),
         .out_data(out_data_intra_block[k])
      );
   end
endgenerate

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      for(int i = 0; i < SUB_BLOCKS; i++) begin
         out_data_intra_block_reg[i] <= {DATA_WIDTH{1'b0}};
      end
   end
   else begin
      if(start_intra) begin
         for(int i = 0; i < SUB_BLOCKS; i++) begin
            out_data_intra_block_reg[i] <= out_data_intra_block[i];
         end
      end
   end
end

always_comb begin
   for(int i = 0; i < 32; i++) begin
      out_data_aux[0][(i+1)*CHUNK-1-:CHUNK] = out_data_intra_block_reg[i%4][((i+1)*CHUNK)-1-:CHUNK];
      out_data_aux[1][(i+1)*CHUNK-1-:CHUNK] = out_data_intra_block_reg[i%4][(((i+1)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
      out_data_aux[2][(i+1)*CHUNK-1-:CHUNK] = out_data_intra_block_reg[i%4][(((i+2)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
      out_data_aux[3][(i+1)*CHUNK-1-:CHUNK] = out_data_intra_block_reg[i%4][(((i+3)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
   end
end

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      counter_sub_out <= {NBW_COUNTER_SUB_OUT{1'b1}};
      out_data        <= {DATA_WIDTH{1'b0}};
   end
   else begin
      if(start_intra) begin
         counter_sub_out <= counter_sub_out + 1;
         out_data        <= out_data_aux[counter_sub_out];
      end
   end
end

endmodule

module intra_block #(
    parameter ROW_COL_WIDTH = 16,
    parameter DATA_WIDTH = ROW_COL_WIDTH*ROW_COL_WIDTH
)(
    input logic [DATA_WIDTH-1:0] in_data,  // Input: 256 bits
    output logic [DATA_WIDTH-1:0] out_data // Output: 256 bits rearranged
);

    // Area optimization:
    // The original design computed r_prime[256], c_prime[256] and
    // output_index[256] with divide/modulo/multiply arithmetic in two
    // always_comb blocks.  Because every index depends ONLY on the constant
    // loop variable, the whole block is a FIXED bit permutation.  Resolving
    // that permutation at elaboration time removes the entire arithmetic
    // cloud and all intermediate storage wires, while keeping the exact same
    // function: out_data[j] = in_data[ r_prime(j)*16 + c_prime(j) ].

    // Elaboration-time source-bit index for output bit i.
    function automatic int unsigned src_index(input int i);
        int unsigned r_prime;
        int unsigned c_prime;
        begin
            if (i < 128) begin
                r_prime = (i - 2 * (i / 16))     % 16;
                c_prime = (i -     (i / 16))     % 16;
            end
            else begin
                r_prime = (i - 2 * (i / 16) - 1) % 16;
                c_prime = (i -     (i / 16) - 1) % 16;
            end
            src_index = r_prime * 16 + c_prime;
        end
    endfunction

    // Pure permutation wiring (no intermediate arithmetic / storage wires).
    genvar g;
    generate
        for (g = 0; g < DATA_WIDTH; g = g + 1) begin : g_perm
            assign out_data[g] = in_data[src_index(g)];
        end
    endgenerate

endmodule

module sdram_controller (clk,reset,addr,data_in,data_out,read,write,sdram_clk,sdram_cke,sdram_cs,sdram_ras,sdram_cas,sdram_we,sdram_addr,sdram_ba,sdram_dq,dq_out);

    input         clk;
    input         reset;          // asynchronous active-high reset
    input  [23:0] addr;           // 24-bit address for SDRAM access
    input  [15:0] data_in;        // 16-bit write data
    input         read;
    input         write;
    input  [15:0] sdram_dq;       // 16-bit data bus from SDRAM

    output reg [15:0] data_out;   // 16-bit read data
    output            sdram_clk;
    output reg        sdram_cke;
    output reg        sdram_cs;
    output reg        sdram_ras;
    output reg        sdram_cas;
    output reg        sdram_we;
    output reg [12:0] sdram_addr;
    output reg [1:0]  sdram_ba;
    output reg [15:0] dq_out;     // 16-bit write data bus to SDRAM

    // FSM states
    localparam INIT     = 3'd0;
    localparam IDLE     = 3'd1;
    localparam ACTIVATE = 3'd2;
    localparam READ     = 3'd3;
    localparam WRITE    = 3'd4;
    localparam REFRESH  = 3'd5;

    localparam INIT_CYCLES    = 10;
    localparam REFRESH_PERIOD = 1024;

    reg [2:0]  state;
    reg [3:0]  init_cnt;       // counts up to INIT_CYCLES
    reg [9:0]  refresh_cnt;    // counts up to REFRESH_PERIOD
    reg        pend_read;      // latched request type
    reg        pend_write;

    // SDRAM clock is simply the system clock forwarded to the device.
    assign sdram_clk = clk;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state       <= INIT;
            init_cnt    <= 4'd0;
            refresh_cnt <= 10'd0;
            pend_read   <= 1'b0;
            pend_write  <= 1'b0;
            data_out    <= 16'd0;
            dq_out      <= 16'd0;
            sdram_addr  <= 13'd0;
            sdram_ba    <= 2'd0;
            // idle command (CKE high, chip deselected)
            sdram_cke   <= 1'b1;
            sdram_cs    <= 1'b0;
            sdram_ras   <= 1'b0;
            sdram_cas   <= 1'b0;
            sdram_we    <= 1'b0;
        end else begin
            // default: deassert command strobes each cycle unless a state drives them
            sdram_cke <= 1'b1;
            sdram_cs  <= 1'b0;
            sdram_ras <= 1'b0;
            sdram_cas <= 1'b0;
            sdram_we  <= 1'b0;

            case (state)
                // -------- Initialization: 10 clock cycles --------
                INIT: begin
                    if (init_cnt == INIT_CYCLES-1) begin
                        init_cnt <= 4'd0;
                        state    <= IDLE;
                    end else begin
                        init_cnt <= init_cnt + 4'd1;
                    end
                end

                // -------- Idle: wait for read/write or trigger refresh --------
                IDLE: begin
                    if (read || write) begin
                        // capture request and latch the row/bank/column address
                        pend_read   <= read;
                        pend_write  <= write;
                        sdram_addr  <= addr[12:0];
                        sdram_ba    <= addr[23:22];
                        refresh_cnt <= 10'd0;
                        // Activate command: CS=1, RAS=1, CAS=1
                        sdram_cs    <= 1'b1;
                        sdram_ras   <= 1'b1;
                        sdram_cas   <= 1'b1;
                        state       <= ACTIVATE;
                    end else if (refresh_cnt == REFRESH_PERIOD-1) begin
                        refresh_cnt <= 10'd0;
                        // Auto Refresh command: CS=1, RAS=1, CAS=1, WE=0
                        sdram_cs    <= 1'b1;
                        sdram_ras   <= 1'b1;
                        sdram_cas   <= 1'b1;
                        sdram_we    <= 1'b0;
                        state       <= REFRESH;
                    end else begin
                        refresh_cnt <= refresh_cnt + 10'd1;
                    end
                end

                // -------- Activate: next cycle go to READ or WRITE --------
                ACTIVATE: begin
                    if (pend_read)
                        state <= READ;
                    else if (pend_write)
                        state <= WRITE;
                    else
                        state <= IDLE;
                end

                // -------- Read: CS=1, CKE=1, RAS=0, CAS=1, WE=0 --------
                READ: begin
                    sdram_cs   <= 1'b1;
                    sdram_cke  <= 1'b1;
                    sdram_ras  <= 1'b0;
                    sdram_cas  <= 1'b1;
                    sdram_we   <= 1'b0;
                    data_out   <= sdram_dq;     // capture read data
                    pend_read  <= 1'b0;
                    state      <= IDLE;
                end

                // -------- Write: CS=1, CKE=1, RAS=0, CAS=1, WE=1 --------
                WRITE: begin
                    sdram_cs   <= 1'b1;
                    sdram_cke  <= 1'b1;
                    sdram_ras  <= 1'b0;
                    sdram_cas  <= 1'b1;
                    sdram_we   <= 1'b1;
                    dq_out     <= data_in;      // drive write data
                    pend_write <= 1'b0;
                    state      <= IDLE;
                end

                // -------- Refresh: hold the refresh command then return --------
                REFRESH: begin
                    sdram_cs   <= 1'b1;
                    sdram_ras  <= 1'b1;
                    sdram_cas  <= 1'b1;
                    sdram_we   <= 1'b0;
                    state      <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

// secure_read_write_bus_interface
// Parameterized read/write bus with 8-bit key-based access control.
//
// The bus captures its inputs on the RISING EDGE of i_capture_pulse (the
// capture pulse acts as the clock; all inputs are synchronous to it).
// i_reset_bar is an asynchronous, active-low reset that clears every internal
// register and output.
//
// Access is authorized only when i_key_in equals the internal parameterized
// key (p_configurable_key):
//   - i_read_write_enable == 1 -> READ  : o_data_out = mem[i_addr] when authorized
//   - i_read_write_enable == 0 -> WRITE : mem[i_addr] = i_data_in when authorized
// o_error is asserted (1) whenever the supplied key is incorrect, and
// deasserted (0) when the key matches. Outputs default to 0 on reset and
// on any unauthorized access.
module secure_read_write_bus_interface #(
    parameter [7:0] p_configurable_key = 8'hAA, // internal 8-bit authorization key
    parameter       p_data_width       = 8,     // configurable data width
    parameter       p_addr_width       = 8      // configurable address width
) (
    input  wire [p_addr_width-1:0] i_addr,              // target address
    input  wire [p_data_width-1:0] i_data_in,           // data to write
    input  wire [7:0]              i_key_in,            // supplied authorization key
    input  wire                    i_read_write_enable, // 1 = read, 0 = write
    input  wire                    i_capture_pulse,     // qualifies/clocks input capture
    input  wire                    i_reset_bar,         // async active-low reset
    output reg  [p_data_width-1:0] o_data_out,          // read data (valid only on authorized read)
    output reg                     o_error              // 1 = key mismatch, 0 = key match
);

    // Internal storage: one p_data_width-bit word per address.
    reg [p_data_width-1:0] mem [0:(1<<p_addr_width)-1];

    integer idx;

    always @(posedge i_capture_pulse or negedge i_reset_bar) begin
        if (!i_reset_bar) begin
            // Asynchronous reset: clear all internal registers and outputs.
            o_data_out <= {p_data_width{1'b0}};
            o_error    <= 1'b0;
            for (idx = 0; idx < (1<<p_addr_width); idx = idx + 1)
                mem[idx] <= {p_data_width{1'b0}};
        end else begin
            if (i_key_in == p_configurable_key) begin
                // Authorized access: no error.
                o_error <= 1'b0;
                if (i_read_write_enable) begin
                    // Read: drive the addressed word onto the output.
                    o_data_out <= mem[i_addr];
                end else begin
                    // Write: store the input data; output holds no valid read data.
                    mem[i_addr] <= i_data_in;
                    o_data_out  <= {p_data_width{1'b0}};
                end
            end else begin
                // Unauthorized access: flag error, force output to default 0.
                o_error    <= 1'b1;
                o_data_out <= {p_data_width{1'b0}};
            end
        end
    end

endmodule

// secure_read_write_register_bank
// Parameterized register bank with a two-stage secure unlock mechanism.
// i_capture_pulse acts as the clock; i_rst_n is an asynchronous active-low reset.
module secure_read_write_register_bank #(
    parameter p_address_width = 8,
    parameter p_data_width    = 8,
    parameter p_unlock_code_0 = 8'hAB,
    parameter p_unlock_code_1 = 8'hCD
) (
    input  wire [p_address_width-1:0] i_addr,
    input  wire [p_data_width-1:0]    i_data_in,
    input  wire                       i_read_write_enable,
    input  wire                       i_capture_pulse,
    input  wire                       i_rst_n,
    output reg  [p_data_width-1:0]    o_data_out
);

    // Register storage: 2^p_address_width entries, each p_data_width wide.
    reg [p_data_width-1:0] mem [0:(1<<p_address_width)-1];

    // Unlock state machine encoding.
    localparam LOCKED   = 2'd0;  // no unlock progress
    localparam CODE0_OK = 2'd1;  // correct unlock code written to address 0
    localparam UNLOCKED = 2'd2;  // full sequence complete, bank accessible

    reg [1:0] unlock_state;

    always @(posedge i_capture_pulse or negedge i_rst_n) begin
        if (!i_rst_n) begin
            unlock_state <= LOCKED;
            o_data_out   <= {p_data_width{1'b0}};
        end else begin
            // Default: o_data_out is 0 unless a valid read overrides it.
            o_data_out <= {p_data_width{1'b0}};

            if (i_read_write_enable == 1'b0) begin
                // -------- Write operation --------
                if (i_addr == {p_address_width{1'b0}}) begin
                    // Address 0: first unlock code (write-only).
                    if (i_data_in == p_unlock_code_0[p_data_width-1:0])
                        unlock_state <= CODE0_OK;
                    else
                        unlock_state <= LOCKED;
                end else if (i_addr == {{(p_address_width-1){1'b0}}, 1'b1}) begin
                    // Address 1: second/trigger unlock code (write-only).
                    if ((unlock_state == CODE0_OK) &&
                        (i_data_in == p_unlock_code_1[p_data_width-1:0]))
                        unlock_state <= UNLOCKED;
                    else
                        unlock_state <= LOCKED;
                end else begin
                    // All other addresses: writable only when unlocked.
                    if (unlock_state == UNLOCKED)
                        mem[i_addr] <= i_data_in;
                end
            end else begin
                // -------- Read operation --------
                // Addresses 0 and 1 are write-only and cannot be read.
                // All other addresses read only when unlocked.
                if ((unlock_state == UNLOCKED) &&
                    (i_addr != {p_address_width{1'b0}}) &&
                    (i_addr != {{(p_address_width-1){1'b0}}, 1'b1}))
                    o_data_out <= mem[i_addr];
                else
                    o_data_out <= {p_data_width{1'b0}};
            end
        end
    end

endmodule

module secure_variable_timer (
    input  wire       i_clk,        // Clock signal (rising-edge triggered)
    input  wire       i_rst_n,      // Active-low synchronous reset signal
    input  wire       i_data_in,    // Serial data input
    output reg  [3:0] o_time_left,  // 4-bit output showing remaining time during counting phase
    output reg        o_processing, // Asserted high when the timer is actively counting
    output reg        o_completed,  // Asserted high when the timer completes its delay
    input  wire       i_ack         // Acknowledgment signal to reset after completion
);

    // FSM state encoding
    localparam [1:0] IDLE     = 2'd0,  // Search for the 1101 start pattern
                     CONFIG   = 2'd1,  // Shift in the 4 delay bits (MSB first)
                     COUNTING = 2'd2,  // Count (delay+1)*1000 clock cycles
                     DONE     = 2'd3;  // Assert o_completed, wait for i_ack

    reg [1:0] state;        // Current FSM state
    reg [3:0] delay;        // Holds the 4-bit delay value
    reg [3:0] shift_reg;    // Sliding window of the last 4 serial bits (start-pattern detect)
    reg [1:0] bit_cnt;      // Counts the 4 configuration bits shifted in
    reg [9:0] cycle_cnt;    // Counts the 0..999 cycles inside each 1000-cycle block

    always @(posedge i_clk) begin
        if (!i_rst_n) begin
            state        <= IDLE;
            delay        <= 4'd0;
            shift_reg    <= 4'd0;
            bit_cnt      <= 2'd0;
            cycle_cnt    <= 10'd0;
            o_time_left  <= 4'd0;
            o_processing <= 1'b0;
            o_completed  <= 1'b0;
        end else begin
            case (state)
                // ---------------------------------------------------------
                // IDLE: slide i_data_in through shift_reg, hunt for 1101
                // ---------------------------------------------------------
                IDLE: begin
                    o_processing <= 1'b0;
                    o_completed  <= 1'b0;
                    shift_reg    <= {shift_reg[2:0], i_data_in};
                    if ({shift_reg[2:0], i_data_in} == 4'b1101) begin
                        state   <= CONFIG;
                        bit_cnt <= 2'd0;
                    end
                end

                // ---------------------------------------------------------
                // CONFIG: shift in the next 4 bits, MSB first, into delay
                // ---------------------------------------------------------
                CONFIG: begin
                    delay   <= {delay[2:0], i_data_in};
                    bit_cnt <= bit_cnt + 2'd1;
                    if (bit_cnt == 2'd3) begin
                        // 4th (LSB) delay bit is captured this cycle; launch counting
                        o_time_left  <= {delay[2:0], i_data_in};
                        o_processing <= 1'b1;
                        cycle_cnt    <= 10'd0;
                        state        <= COUNTING;
                    end
                end

                // ---------------------------------------------------------
                // COUNTING: (delay+1) blocks of 1000 cycles; o_time_left
                // holds a value for 1000 cycles then decrements to 0.
                // ---------------------------------------------------------
                COUNTING: begin
                    o_processing <= 1'b1;
                    if (cycle_cnt == 10'd999) begin
                        cycle_cnt <= 10'd0;
                        if (o_time_left == 4'd0) begin
                            // Final block finished -> completion
                            o_processing <= 1'b0;
                            o_completed  <= 1'b1;
                            state        <= DONE;
                        end else begin
                            o_time_left <= o_time_left - 4'd1;
                        end
                    end else begin
                        cycle_cnt <= cycle_cnt + 10'd1;
                    end
                end

                // ---------------------------------------------------------
                // DONE: hold o_completed until the user acknowledges
                // ---------------------------------------------------------
                DONE: begin
                    o_processing <= 1'b0;
                    o_completed  <= 1'b1;
                    if (i_ack) begin
                        o_completed <= 1'b0;
                        shift_reg   <= 4'd0;   // clear window so stale bits cannot re-trigger
                        state       <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module binary_to_one_hot_decoder_sequencial #(
    parameter BINARY_WIDTH = 5,
    parameter OUTPUT_WIDTH  = 32
) (
    input  wire [BINARY_WIDTH-1:0] i_binary_in,
    input  wire                    i_clk,
    input  wire                    i_rstb,
    output reg  [OUTPUT_WIDTH-1:0] o_one_hot_out
);

    // Sequential binary-to-one-hot decoder.
    // On each rising edge of i_clk, i_binary_in is sampled and the output
    // register is updated so that only the bit at index i_binary_in is set.
    // i_rstb is an asynchronous, active-low reset that clears the output.
    always @(posedge i_clk or negedge i_rstb) begin
        if (!i_rstb)
            o_one_hot_out <= {OUTPUT_WIDTH{1'b0}};
        else
            o_one_hot_out <= ({{(OUTPUT_WIDTH-1){1'b0}}, 1'b1}) << i_binary_in;
    end

endmodule

module serial_in_parallel_out_8bit (
    input  wire       clock,
    input  wire       serial_in,
    output reg  [7:0] parallel_out
);

    // On each rising edge of the clock, shift the register contents left by
    // one position, inserting serial_in at the LSB (parallel_out[0]) and
    // discarding the current MSB (parallel_out[7]).
    always @(posedge clock) begin
        parallel_out <= {parallel_out[6:0], serial_in};
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    parallel_out = 0;
  end

endmodule

module sipo_top#(parameter DATA_WIDTH = 16,                                   // Width of the shift register
                 parameter SHIFT_DIRECTION = 1,                               // Determines Left or right shift
                 parameter CODE_WIDTH = DATA_WIDTH + $clog2(DATA_WIDTH + 1)   // Encoded width
                 ) (

   input clk,                                   // Clock input
   input reset_n,                               // Reset input
   input serial_in,                             // Serial input to SIPO
   input shift_en,                              // Shift enable
   input [CODE_WIDTH-1:0] received,             // Received encoded data
   output done,                                 // Done signal indicating completion of shift
   output [DATA_WIDTH-1:0] data_out,            // corrected output of ecc block
   output [CODE_WIDTH-1:0] encoded,             // Encoded output
   output error_detected,                       // Error detected flag
   output error_corrected                       // Error corrected  flag

   );

wire [DATA_WIDTH-1:0] parallel_out;

serial_in_parallel_out_8bit  #(.WIDTH(DATA_WIDTH), .SHIFT_DIRECTION(SHIFT_DIRECTION)) uut_sipo (
        .clk           (clk),               // Clock input
        .reset_n       (reset_n),           // Reset input
        .sin           (serial_in),         // Serial input to SIPO
        .shift_en      (shift_en),          // Shift enable for SIPO
        .done          (done),              // Done signal from SIPO
        .parallel_out  (parallel_out)       // Parallel output from SIPO
    );

onebit_ecc#(.DATA_WIDTH(DATA_WIDTH),.CODE_WIDTH(CODE_WIDTH)) uut_onebit_ecc1 (

    .data_in(parallel_out),
    .encoded(encoded),
    .received(received),
    .data_out(data_out),
    .error_detected(error_detected),
    .error_corrected(error_corrected)
    );

endmodule

module serial_in_parallel_out_8bit  #(
    parameter WIDTH = 64,               // Width of the shift register
    parameter SHIFT_DIRECTION = 1       // Determines if shifting
)(
    input clk,                          // Clock signal
    input reset_n,                      // Active low reset
    input sin,                          // Serial input
    input shift_en,                     // Shift enable signal
    output reg done,                    // Done signal indicating completion of shift
    output reg [WIDTH-1:0] parallel_out // Parallel output
);

    localparam COUNT_WIDTH = $clog2(WIDTH); // Calculate width for shift_count

    reg [COUNT_WIDTH:0] shift_count;        // Parameterized counter to track number of shifts


    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            parallel_out     <= {WIDTH{1'b0}};
            done             <= 1'b0;
            shift_count      <= {COUNT_WIDTH{1'b0}};
        end else begin
            if (shift_en) begin
                if (SHIFT_DIRECTION) begin
                    parallel_out    <= {parallel_out[WIDTH-2:0], sin};
                end else begin
                    parallel_out    <= {sin, parallel_out[WIDTH-1:1]};
                end
                shift_count   <= shift_count + 1;
            end

            if (shift_count == (WIDTH - 1)) begin
                done         <= 1'b1;
                shift_count  <= {COUNT_WIDTH{1'b0}};
            end else begin
                done         <= 1'b0;
            end
        end
    end
endmodule


module onebit_ecc #(
    parameter DATA_WIDTH = 4,                                  // Width of the data input
    parameter CODE_WIDTH = DATA_WIDTH + $clog2(DATA_WIDTH + 1) // Encoded width
)(
    input [DATA_WIDTH-1:0] data_in,                     // Input data
    output reg [CODE_WIDTH-1:0] encoded,                // Encoded output
    input [CODE_WIDTH-1:0] received,                    // Received encoded data
    output reg [DATA_WIDTH-1:0] data_out,               // Corrected output
    output reg error_detected,                          // Error detected flag
    output reg error_corrected                          // Error corrected flag
);

    localparam PARITY_BITS = CODE_WIDTH - DATA_WIDTH;   // Number of parity bits

    reg [PARITY_BITS-1:0] syndrome;                     // Syndrome for error detection
    reg [CODE_WIDTH-1:0] corrected_data;                // Corrected received data


    integer idx_i, idx_j, idx_k;
    integer idx_m, idx_n;
    integer idx_p, idx_q;


    always @(*) begin
        encoded = 0;
        idx_k = 0;


        for (idx_i = 0; idx_i < CODE_WIDTH; idx_i = idx_i + 1) begin
            if ((idx_i + 1) & (idx_i)) begin
                encoded[idx_i] = data_in[idx_k];
                idx_k = idx_k + 1;
            end
        end


        for (idx_i = 0; idx_i < PARITY_BITS; idx_i = idx_i + 1) begin
            encoded[(1 << idx_i) - 1] = 0;
            for (idx_j = 0; idx_j < CODE_WIDTH; idx_j = idx_j + 1) begin
                if (((idx_j + 1) & (1 << idx_i)) && ((idx_j + 1) != (1 << idx_i))) begin
                    encoded[(1 << idx_i) - 1] = encoded[(1 << idx_i) - 1] ^ encoded[idx_j];
                end
            end
        end
    end


    always @(*) begin
        syndrome = 0;
        for (idx_m = 0; idx_m < PARITY_BITS; idx_m = idx_m + 1) begin
            for (idx_n = 0; idx_n < CODE_WIDTH; idx_n = idx_n + 1) begin
                if ((idx_n + 1) & (1 << idx_m)) begin
                    syndrome[idx_m] = syndrome[idx_m] ^ received[idx_n];
                end
            end
        end
    end


    always @(*) begin
        error_detected = |syndrome;
    end


    always @(*) begin
        corrected_data = received;
        if (error_detected) begin
            corrected_data[syndrome - 1] = ~corrected_data[syndrome - 1];
        end
    end


    always @(*) begin
        idx_q = 0;
        for (idx_p = 0; idx_p < CODE_WIDTH; idx_p = idx_p + 1) begin
            if ((idx_p + 1) & (idx_p)) begin
                data_out[idx_q] = corrected_data[idx_p];
                idx_q = idx_q + 1;
            end
        end
    end


    always @(*) begin
        error_corrected = error_detected;
    end

endmodule

module sipo_top#(parameter DATA_WIDTH = 16,                                   // Width of the shift register
                 parameter SHIFT_DIRECTION = 1,                               // Determines Left or right shift
                 parameter CODE_WIDTH = DATA_WIDTH + $clog2(DATA_WIDTH + 1),  // Encoded width
                 parameter CRC_WIDTH = DATA_WIDTH/2,                          // CRC width
                 parameter [CRC_WIDTH-1:0] POLY = 8'b10101010                 // CRC polynomial
                 ) (

   input clk,                                   // Clock input
   input reset_n,                               // Reset input
   input serial_in,                             // Serial input to SIPO
   input shift_en,                              // Shift enable
   input [CODE_WIDTH-1:0] received,             // Received encoded data
   input [CRC_WIDTH-1:0] received_crc,          // Received CRC value
   output done,                                 // Done signal indicating completion of shift
   output [DATA_WIDTH-1:0] data_out,            // corrected output of ecc block
   output [CODE_WIDTH-1:0] encoded,             // Encoded output
   output error_detected,                       // Error detected flag
   output error_corrected,                      // Error corrected  flag
   output [CRC_WIDTH-1:0] crc_out,              // CRC output
   output crc_error                             // CRC mismatch flag

   );

wire [DATA_WIDTH-1:0] parallel_out;

serial_in_parallel_out_8bit  #(.WIDTH(DATA_WIDTH), .SHIFT_DIRECTION(SHIFT_DIRECTION)) uut_sipo (
        .clk           (clk),               // Clock input
        .reset_n       (reset_n),           // Reset input
        .sin           (serial_in),         // Serial input to SIPO
        .shift_en      (shift_en),          // Shift enable for SIPO
        .done          (done),              // Done signal from SIPO
        .parallel_out  (parallel_out)       // Parallel output from SIPO
    );

onebit_ecc#(.DATA_WIDTH(DATA_WIDTH),.CODE_WIDTH(CODE_WIDTH)) uut_onebit_ecc1 (

    .data_in(parallel_out),
    .encoded(encoded),
    .received(received),
    .data_out(data_out),
    .error_detected(error_detected),
    .error_corrected(error_corrected)
    );

crc_generator #(.DATA_WIDTH(DATA_WIDTH), .CRC_WIDTH(CRC_WIDTH), .POLY(POLY)) uut_crc_generator (
    .clk       (clk),
    .rst       (reset_n),
    .data_in   (parallel_out),
    .crc_out   (crc_out)
    );

assign crc_error = (received_crc != crc_out);

endmodule

module serial_in_parallel_out_8bit  #(
    parameter WIDTH = 64,               // Width of the shift register
    parameter SHIFT_DIRECTION = 1       // Determines if shifting
)(
    input clk,                          // Clock signal
    input reset_n,                      // Active low reset
    input sin,                          // Serial input
    input shift_en,                     // Shift enable signal
    output reg done,                    // Done signal indicating completion of shift
    output reg [WIDTH-1:0] parallel_out // Parallel output
);

    localparam COUNT_WIDTH = $clog2(WIDTH); // Calculate width for shift_count

    reg [COUNT_WIDTH:0] shift_count;        // Parameterized counter to track number of shifts


    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            parallel_out     <= {WIDTH{1'b0}};
            done             <= 1'b0;
            shift_count      <= {COUNT_WIDTH{1'b0}};
        end else begin
            if (shift_en) begin
                if (SHIFT_DIRECTION) begin
                    parallel_out    <= {parallel_out[WIDTH-2:0], sin};
                end else begin
                    parallel_out    <= {sin, parallel_out[WIDTH-1:1]};
                end
                shift_count   <= shift_count + 1;
            end

            if (shift_count == (WIDTH - 1)) begin
                done         <= 1'b1;
                shift_count  <= {COUNT_WIDTH{1'b0}};
            end else begin
                done         <= 1'b0;
            end
        end
    end
endmodule


