module crc_generator #(
    parameter DATA_WIDTH = 16,                        // Width of the input data
    parameter CRC_WIDTH  = DATA_WIDTH/2,              // CRC width
    parameter [CRC_WIDTH-1:0] POLY = 8'b10101010      // CRC polynomial
)(
    input                        clk,                 // Clock signal
    input                        rst,                 // Active LOW synchronous reset
    input      [DATA_WIDTH-1:0]  data_in,             // Data for which CRC is calculated
    output reg [CRC_WIDTH-1:0]   crc_out              // CRC output
);

    integer i;
    reg [CRC_WIDTH-1:0] crc_reg;

    // Combinational CRC computation over data_in, MSB-first
    always @(*) begin
        crc_reg = {CRC_WIDTH{1'b0}};
        for (i = DATA_WIDTH-1; i >= 0; i = i - 1) begin
            if (crc_reg[CRC_WIDTH-1] ^ data_in[i])
                crc_reg = (crc_reg << 1) ^ POLY;
            else
                crc_reg = (crc_reg << 1);
        end
    end

    // Register the computed CRC with synchronous active-low reset
    always @(posedge clk) begin
        if (!rst)
            crc_out <= {CRC_WIDTH{1'b0}};
        else
            crc_out <= crc_reg;
    end

endmodule

module SetBitStreamCalculator #(
    parameter p_max_set_bit_count_width = 8
) (
    input  wire                                 i_bit_in,
    input  wire                                 i_clk,
    input  wire                                 i_ready,
    input  wire                                 i_rst_n,
    output reg  [p_max_set_bit_count_width-1:0] o_set_bit_count
);

    // Saturation value: 2^p_max_set_bit_count_width - 1
    localparam [p_max_set_bit_count_width-1:0] MAX_COUNT = {p_max_set_bit_count_width{1'b1}};

    // Registered copy of i_ready (already synchronous to i_clk) used to detect
    // the low->high transition of i_ready.
    reg i_ready_d;

    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            // Asynchronous active-low reset: clear count.
            o_set_bit_count <= {p_max_set_bit_count_width{1'b0}};
            i_ready_d       <= 1'b0;
        end else begin
            i_ready_d <= i_ready;

            if (i_ready && !i_ready_d) begin
                // i_ready just asserted (low->high): reset count to 0.
                // The first bit sampled on this edge is ignored for counting.
                o_set_bit_count <= {p_max_set_bit_count_width{1'b0}};
            end
            else if (i_ready && i_ready_d) begin
                // i_ready steady high: count set bits with saturation.
                if (i_bit_in && (o_set_bit_count != MAX_COUNT))
                    o_set_bit_count <= o_set_bit_count + 1'b1;
            end
            // i_ready low: halt and retain current count value.
        end
    end

endmodule

module sigma_delta_audio
(
  input   clk_sig,
  input   clk_en_sig,
  input  [14:0] load_data_sum,
  input  [14:0] read_data_sum,
  output  reg left_sig=0,
  output  reg right_sig=0
);

localparam DATA_WIDTH = 15;
localparam READ_WIDTH  = 4;
localparam A1_WIDTH = 2;
localparam A2_WIDTH = 5;

wire [DATA_WIDTH+2+0  -1:0] l_er0, r_er0;
reg  [DATA_WIDTH+2+0  -1:0] l_er0_prev=0, r_er0_prev=0;
wire [DATA_WIDTH+A1_WIDTH+2-1:0] l_aca1,  r_aca1;
wire [DATA_WIDTH+A2_WIDTH+2-1:0] l_aca2,  r_aca2;
reg  [DATA_WIDTH+A1_WIDTH+2-1:0] l_ac1=0, r_ac1=0;
reg  [DATA_WIDTH+A2_WIDTH+2-1:0] l_ac2=0, r_ac2=0;
wire [DATA_WIDTH+A2_WIDTH+3-1:0] l_quant, r_quant;

reg [24-1:0] seed_1 = 24'h654321;
reg [19-1:0] seed_2 = 19'h12345;
reg [24-1:0] s_sum=0, s_prev=0, s_out=0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_1)
      seed_1 <= 24'h654321;
    else
      seed_1 <= {seed_1[22:0], ~(seed_1[23] ^ seed_1[22] ^ seed_1[21] ^ seed_1[16])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_2)
      seed_2 <= 19'h12345;
    else
      seed_2 <= {seed_2[17:0], ~(seed_2[18] ^ seed_2[17] ^ seed_2[16] ^ seed_2[13] ^ seed_2[0])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    s_sum  <= seed_1 + {5'b0, seed_2};
    s_prev <= s_sum;
    s_out  <= s_sum - s_prev;
  end
end

localparam INPUT_DATA=4;
reg  [INPUT_DATA+0-1:0] integer_count = 0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    integer_count <= integer_count + 1'b1;
  end
end

reg  [DATA_WIDTH+0-1:0] ldata_current=0, ldata_previous=0;
reg  [DATA_WIDTH+0-1:0] rdata_current=0, rdata_previous=0;
wire [DATA_WIDTH+1-1:0] load_data_step, read_data_step;
reg  [DATA_WIDTH+INPUT_DATA-1:0] load_data_int=0, read_data_int=0;
wire [DATA_WIDTH+0-1:0] load_data_int_out, read_data_int_out;
assign load_data_step = {ldata_current[DATA_WIDTH-1], ldata_current} - {ldata_previous[DATA_WIDTH-1], ldata_previous};
assign read_data_step = {rdata_current[DATA_WIDTH-1], rdata_current} - {rdata_previous[DATA_WIDTH-1], rdata_previous};
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (~|integer_count) begin
      ldata_previous <= ldata_current;
      ldata_current  <= load_data_sum;
      rdata_previous <= rdata_current;
      rdata_current  <= read_data_sum;
      load_data_int  <= {ldata_current, {INPUT_DATA{1'b0}}};
      read_data_int  <= {rdata_current, {INPUT_DATA{1'b0}}};
    end else begin
      load_data_int  <= load_data_int + {{(INPUT_DATA-1){load_data_step[DATA_WIDTH+1-1]}}, load_data_step};
      read_data_int  <= read_data_int + {{(INPUT_DATA-1){read_data_step[DATA_WIDTH+1-1]}}, read_data_step};
    end
  end
end
assign load_data_int_out = load_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];
assign read_data_int_out = read_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];

wire [DATA_WIDTH+2-1:0] load_data_gain, read_data_gain;
assign load_data_gain = {load_data_int_out[DATA_WIDTH-1], load_data_int_out, 1'b0} + {{(2){load_data_int_out[DATA_WIDTH-1]}}, load_data_int_out};
assign read_data_gain = {read_data_int_out[DATA_WIDTH-1], read_data_int_out, 1'b0} + {{(2){read_data_int_out[DATA_WIDTH-1]}}, read_data_int_out};

assign l_aca1 = {{(A1_WIDTH){load_data_gain[DATA_WIDTH+2-1]}}, load_data_gain} - {{(A1_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} + l_ac1;
assign r_aca1 = {{(A1_WIDTH){read_data_gain[DATA_WIDTH+2-1]}}, read_data_gain} - {{(A1_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} + r_ac1;
assign l_aca2 = {{(A2_WIDTH-A1_WIDTH){l_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, l_aca1} - {{(A2_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} - {{(A2_WIDTH+1){l_er0_prev[DATA_WIDTH+2-1]}}, l_er0_prev[DATA_WIDTH+2-1:1]} + l_ac2;
assign r_aca2 = {{(A2_WIDTH-A1_WIDTH){r_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, r_aca1} - {{(A2_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} - {{(A2_WIDTH+1){r_er0_prev[DATA_WIDTH+2-1]}}, r_er0_prev[DATA_WIDTH+2-1:1]} + r_ac2;

always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    l_ac1 <= l_aca1;
    r_ac1 <= r_aca1;
    l_ac2 <= l_aca2;
    r_ac2 <= r_aca2;
  end
end

assign l_quant = {l_ac2[DATA_WIDTH+A2_WIDTH+2-1], l_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};
assign r_quant = {r_ac2[DATA_WIDTH+A2_WIDTH+2-1], r_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};

assign l_er0 = l_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};
assign r_er0 = r_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};

always @ (posedge clk_sig)
begin
  if (clk_en_sig)
  begin
    if (~|load_data_gain)
    begin
      left_sig <= ~left_sig;
    end
    else
    begin
      left_sig <= ~l_er0[DATA_WIDTH+2-1];
    end

    if (~|read_data_gain)
    begin
      right_sig <= ~right_sig;
    end
    else
    begin
      right_sig <= ~r_er0[DATA_WIDTH+2-1];
    end
  end
end
endmodule

module signal_correlator (
    input clk,
    input reset,
    input [7:0] input_signal,
    input [7:0] reference_signal,
    output reg [3:0] correlation_output // 4-bit output
);

integer i;
reg [4:0] sum;  // wide enough to hold the un-clamped weighted total (max 8*2 = 16)

always @(posedge clk or posedge reset) begin
    if (reset) begin
        correlation_output <= 4'd0;
        sum                <= 5'd0;
    end else begin
        sum = 5'd0;
        for (i = 0; i < 8; i = i + 1) begin
            // each matching bit (both signals high at position i) contributes +2
            if (input_signal[i] & reference_signal[i])
                sum = sum + 5'd2;
        end
        // clamp the 4-bit output at its maximum value of 15
        if (sum > 5'd15)
            correlation_output <= 4'd15;
        else
            correlation_output <= sum[3:0];
    end
end

endmodule

module signedadder #(parameter DATA_WIDTH = 8)(
    input i_clk,
    input i_rst_n,
    input i_start,
    input i_enable,
    input i_mode,
    input i_clear,
    input [DATA_WIDTH-1:0] i_operand_a,
    input [DATA_WIDTH-1:0] i_operand_b,
    output reg [DATA_WIDTH-1:0] o_resultant_sum,
    output reg o_overflow,
    output reg o_ready,
    output reg [1:0] o_status
);

    // FSM state encodings (match o_status specification)
    localparam [1:0] ST_IDLE    = 2'b00;
    localparam [1:0] ST_LOAD    = 2'b01;
    localparam [1:0] ST_COMPUTE = 2'b10;
    localparam [1:0] ST_OUTPUT  = 2'b11;

    // Internal captured operands / mode and computed results
    reg [DATA_WIDTH-1:0] op_a;
    reg [DATA_WIDTH-1:0] op_b;
    reg                  mode_reg;
    reg [DATA_WIDTH-1:0] result_reg;
    reg                  overflow_reg;

    // Sign-extend operands by one bit; add/subtract in (DATA_WIDTH+1) bits.
    // Overflow when the two most-significant bits of the extended result differ
    // (i.e. the true result does not fit in DATA_WIDTH signed bits). This is
    // exact for BOTH addition and subtraction, including the min-value case.
    wire [DATA_WIDTH:0] a_ext    = {op_a[DATA_WIDTH-1], op_a};
    wire [DATA_WIDTH:0] b_ext    = {op_b[DATA_WIDTH-1], op_b};
    wire [DATA_WIDTH:0] add_ext  = a_ext + b_ext;
    wire [DATA_WIDTH:0] sub_ext  = a_ext - b_ext;
    wire [DATA_WIDTH:0] comp_ext = mode_reg ? sub_ext : add_ext;
    wire                comp_ovf = comp_ext[DATA_WIDTH] ^ comp_ext[DATA_WIDTH-1];

    // Asynchronous active-low reset (Reset Behavior section states asynchronous).
    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            o_status        <= ST_IDLE;
            o_resultant_sum <= {DATA_WIDTH{1'b0}};
            o_overflow      <= 1'b0;
            o_ready         <= 1'b0;
            op_a            <= {DATA_WIDTH{1'b0}};
            op_b            <= {DATA_WIDTH{1'b0}};
            mode_reg        <= 1'b0;
            result_reg      <= {DATA_WIDTH{1'b0}};
            overflow_reg    <= 1'b0;
        end else if (i_clear) begin
            // Clear result and return the state machine to IDLE.
            o_status        <= ST_IDLE;
            o_resultant_sum <= {DATA_WIDTH{1'b0}};
            o_overflow      <= 1'b0;
            o_ready         <= 1'b0;
            op_a            <= {DATA_WIDTH{1'b0}};
            op_b            <= {DATA_WIDTH{1'b0}};
            mode_reg        <= 1'b0;
            result_reg      <= {DATA_WIDTH{1'b0}};
            overflow_reg    <= 1'b0;
        end else begin
            case (o_status)
                ST_IDLE: begin
                    o_ready <= 1'b0;
                    // i_enable gates i_start; begin only when both are high.
                    if (i_enable && i_start) begin
                        o_status <= ST_LOAD;
                    end
                end
                ST_LOAD: begin
                    // Capture operands (and mode) into internal registers.
                    op_a     <= i_operand_a;
                    op_b     <= i_operand_b;
                    mode_reg <= i_mode;
                    o_status <= ST_COMPUTE;
                end
                ST_COMPUTE: begin
                    // Perform addition or subtraction and evaluate overflow.
                    result_reg   <= comp_ext[DATA_WIDTH-1:0];
                    overflow_reg <= comp_ovf;
                    o_status     <= ST_OUTPUT;
                end
                ST_OUTPUT: begin
                    // Present results, assert ready for one cycle, return to IDLE.
                    o_resultant_sum <= result_reg;
                    o_overflow      <= overflow_reg;
                    o_ready         <= 1'b1;
                    o_status        <= ST_IDLE;
                end
                default: o_status <= ST_IDLE;
            endcase
        end
    end

endmodule

module spi_fsm (
    input  wire         i_clk,       // System clock
    input  wire         i_rst_b,     // Active-low async reset
    input  wire [15:0]  i_data_in,   // Parallel 16-bit data to transmit
    input  wire         i_enable,    // Enable block
    input  wire         i_fault,     // Fault indicator
    input  wire         i_clear,     // Forces FSM to clear/idle

    output reg          o_spi_cs_b,  // SPI chip select (active-low)
    output reg          o_spi_clk,   // SPI clock
    output reg          o_spi_data,  // Serialized SPI data out
    output reg [4:0]    o_bits_left, // Bits left to transmit
    output reg          o_done,      // Single-cycle pulse when done or error
    output reg [1:0]    o_fsm_state  // FSM state for external monitoring
);

    // FSM state encoding
    localparam [1:0] IDLE         = 2'b00;
    localparam [1:0] TRANSMIT     = 2'b01;
    localparam [1:0] CLOCK_TOGGLE = 2'b10;
    localparam [1:0] ERROR        = 2'b11;

    // Number of bits to serialize (all bits remaining default = 0x10 = 16)
    localparam [4:0] BITS_ALL = 5'h10;

    always @(posedge i_clk or negedge i_rst_b) begin
        if (!i_rst_b) begin
            // Asynchronous reset: clear all internal state and outputs
            o_fsm_state <= IDLE;
            o_spi_cs_b  <= 1'b1;
            o_spi_clk   <= 1'b0;
            o_spi_data  <= 1'b0;
            o_bits_left <= BITS_ALL;
            o_done      <= 1'b0;
        end else begin
            // o_done is a single-cycle pulse: default low, override where asserted
            o_done <= 1'b0;

            if (i_fault) begin
                // Fault: enter Error state, drive outputs to safe defaults,
                // pulse o_done for exactly one cycle on the entry edge only.
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= BITS_ALL;
                if (o_fsm_state != ERROR)
                    o_done <= 1'b1;
                o_fsm_state <= ERROR;
            end else if (i_clear) begin
                // Clear: immediately clear transaction and go to Idle
                o_fsm_state <= IDLE;
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= BITS_ALL;
            end else if (!i_enable) begin
                // Disabled: reset to Idle, disabling transmission
                o_fsm_state <= IDLE;
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= BITS_ALL;
            end else begin
                case (o_fsm_state)
                    IDLE: begin
                        // Idle defaults; i_enable is high here, so begin
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= BITS_ALL;
                        o_fsm_state <= TRANSMIT;
                    end
                    TRANSMIT: begin
                        // Assert chip select, drive current MSB-first bit,
                        // hold clock low for data setup.
                        o_spi_cs_b  <= 1'b0;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= i_data_in[o_bits_left - 1'b1];
                        o_fsm_state <= CLOCK_TOGGLE;
                    end
                    CLOCK_TOGGLE: begin
                        // Toggle SPI clock to latch data externally, then
                        // consume one bit.
                        o_spi_clk   <= ~o_spi_clk;
                        o_bits_left <= o_bits_left - 1'b1;
                        if (o_bits_left == 5'd1) begin
                            // Last bit sent: complete, pulse done, go Idle
                            o_done      <= 1'b1;
                            o_fsm_state <= IDLE;
                        end else begin
                            o_fsm_state <= TRANSMIT;
                        end
                    end
                    ERROR: begin
                        // Remain in Error with safe outputs until cleared/reset
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= BITS_ALL;
                        o_fsm_state <= ERROR;
                    end
                    default: begin
                        o_fsm_state <= IDLE;
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= BITS_ALL;
                    end
                endcase
            end
        end
    end

endmodule

module unique_number_identifier #(
    parameter p_bit_width   = 8,
    parameter p_max_numbers = 16
)(
    input  wire                    i_clk,
    input  wire                    i_rst_n,
    input  wire                    i_ready,
    input  wire [p_bit_width-1:0]  i_number,
    output reg  [p_bit_width-1:0]  o_unique_number
);

    // All numbers appear exactly twice except the single unique number.
    // The running XOR of the received series cancels every paired value
    // (a ^ a = 0), leaving the unique number.  o_unique_number itself holds
    // the running accumulator: it updates every cycle i_ready is asserted,
    // retains its value while i_ready is deasserted (so the calculation
    // resumes where it stopped), and clears to 0 on asynchronous reset.
    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            o_unique_number <= {p_bit_width{1'b0}};
        end else if (i_ready) begin
            o_unique_number <= o_unique_number ^ i_number;
        end
        // else: hold last value
    end

endmodule

module pipelined_skid_buffer(
    input wire clock,
    input wire rst,

    input wire [3:0] data_i,
    input wire valid_i,
    output wire ready_o,
    output wire valid_o,
    output wire [3:0] data_o,
    input wire ready_i

    );

    // Pipeline: skid_0 -> reg1 -> skid_2 -> reg3
    // Forward path : data / valid
    // Backward path: ready
    wire [3:0] w_s0_data;
    wire       w_s0_valid;
    wire [3:0] w_r1_data;
    wire       w_r1_valid;
    wire [3:0] w_s2_data;
    wire       w_s2_valid;

    wire       w_reg1_ready;   // reg1.ready_out  -> skid_0.i_ready
    wire       w_skid2_ready;  // skid_2.o_ready  -> reg1.ready_in
    wire       w_reg3_ready;   // reg3.ready_out  -> skid_2.i_ready

    skid_buffer skid_0 (
        .clk    (clock),
        .reset  (rst),
        .i_data (data_i),
        .i_valid(valid_i),
        .o_ready(ready_o),
        .o_data (w_s0_data),
        .o_valid(w_s0_valid),
        .i_ready(w_reg1_ready)
    );

    register reg1 (
        .clk      (clock),
        .rst      (rst),
        .data_in  (w_s0_data),
        .valid_in (w_s0_valid),
        .ready_out(w_reg1_ready),
        .valid_out(w_r1_valid),
        .data_out (w_r1_data),
        .ready_in (w_skid2_ready)
    );

    skid_buffer skid_2 (
        .clk    (clock),
        .reset  (rst),
        .i_data (w_r1_data),
        .i_valid(w_r1_valid),
        .o_ready(w_skid2_ready),
        .o_data (w_s2_data),
        .o_valid(w_s2_valid),
        .i_ready(w_reg3_ready)
    );

    register reg3 (
        .clk      (clock),
        .rst      (rst),
        .data_in  (w_s2_data),
        .valid_in (w_s2_valid),
        .ready_out(w_reg3_ready),
        .valid_out(valid_o),
        .data_out (data_o),
        .ready_in (ready_i)
    );

endmodule


module register(
    input clk,
    input rst,

    input [3:0] data_in,
    input valid_in,
    output ready_out,
    output valid_out,
    output [3:0] data_out,
    input  ready_in
    );

    // Elastic (full-throughput) handshake register slice.
    reg [3:0] mem;
    reg       data_present;

    assign data_out  = mem;
    assign valid_out = data_present;
    // Ready to accept new data whenever the slot is empty, or whenever the
    // currently held data is being drained downstream this same cycle.
    assign ready_out = ~data_present | ready_in;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mem          <= 4'b0;
            data_present <= 1'b0;
        end else begin
            if (~data_present | ready_in) begin
                // Empty, or being drained this cycle -> (re)load.
                mem          <= data_in;
                data_present <= valid_in;
            end
            // else: full and not drained -> hold current data
        end
    end

endmodule


module skid_buffer(

input  clk,
input  reset ,

input  [3:0]i_data,
input  i_valid,
output o_ready,

output [3:0]o_data,
output o_valid,
input  i_ready

);

    // Single-register skid buffer.
    //  - buffer flag indicates data_reg currently holds a skidded value.
    //  - o_ready depends only on local occupancy (no combinational loop).
    //  - When empty: forward the input directly to the output (pass-through).
    //  - When empty and the input is valid but downstream is not ready, the
    //    input (already accepted, since o_ready is high) is skidded into
    //    data_reg so it is never lost.
    //  - When full: present the buffered value until downstream accepts it.
    reg [3:0] data_reg;
    reg       buffer;

    assign o_ready = ~buffer;
    assign o_valid = buffer ? 1'b1     : i_valid;
    assign o_data  = buffer ? data_reg : i_data;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            buffer   <= 1'b0;
            data_reg <= 4'b0;
        end else begin
            if (~buffer) begin
                // Empty: pass-through.  If the accepted valid input cannot be
                // taken downstream this cycle, skid it into the register.
                if (i_valid & ~i_ready) begin
                    buffer   <= 1'b1;
                    data_reg <= i_data;
                end
            end else begin
                // Full: release the buffered value once downstream is ready.
                if (i_ready) begin
                    buffer <= 1'b0;
                end
            end
        end
    end

endmodule

module sobel_filter (
    input            clk,
    input            rst_n,
    input      [7:0] pixel_in,
    input            valid_in,
    output reg [7:0] edge_out,
    output reg       valid_out
);
    // Parameter for thresholding
    parameter THRESHOLD = 128;

    reg [7:0] pixel_buffer [0:8]; // 3x3 pixel window
    reg [3:0] count;              // number of pixels currently buffered
    integer i;

    // The 3x3 window is streamed row by row, left to right, top to bottom:
    //   P1=top-left  P2=top-mid  P3=top-right
    //   P4=mid-left  P5=mid-mid  P6=mid-right
    //   P7=bot-left  P8=bot-mid  P9=bot-right
    // New pixels shift into pixel_buffer[0]. Just before the 9th pixel
    // (count==8) the buffer holds P8..P1 and pixel_in carries P9, so:
    //   TL=buffer[7] TM=buffer[6] TR=buffer[5]
    //   ML=buffer[4] MM=buffer[3] MR=buffer[2]
    //   BL=buffer[1] BM=buffer[0] BR=pixel_in
    //
    //   Gx Kernel:     Gy Kernel:
    //   [-1  0  +1]    [-1  -2  -1]
    //   [-2  0  +2]    [ 0   0   0]
    //   [-1  0  +1]    [+1  +2  +1]
    //
    // Gx = -TL +TR -2*ML +2*MR -BL +BR
    // Gy = -TL -2*TM -TR +BL +2*BM +BR
    // (doubling written as repeated addition so the 12-bit sum never truncates)
    wire [11:0] gx_pos = pixel_buffer[5] + pixel_buffer[2] + pixel_buffer[2] + pixel_in;      // +TR +2*MR +BR
    wire [11:0] gx_neg = pixel_buffer[7] + pixel_buffer[4] + pixel_buffer[4] + pixel_buffer[1]; // +TL +2*ML +BL
    wire [11:0] gy_pos = pixel_buffer[1] + pixel_buffer[0] + pixel_buffer[0] + pixel_in;      // +BL +2*BM +BR
    wire [11:0] gy_neg = pixel_buffer[7] + pixel_buffer[6] + pixel_buffer[6] + pixel_buffer[5]; // +TL +2*TM +TR

    wire [11:0] abs_gx = (gx_pos >= gx_neg) ? (gx_pos - gx_neg) : (gx_neg - gx_pos);
    wire [11:0] abs_gy = (gy_pos >= gy_neg) ? (gy_pos - gy_neg) : (gy_neg - gy_pos);
    wire [12:0] magnitude = abs_gx + abs_gy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 9; i = i + 1)
                pixel_buffer[i] <= 8'd0;
            count     <= 4'd0;
            edge_out  <= 8'd0;
            valid_out <= 1'b0;
        end else if (valid_in) begin
            if (count == 4'd8) begin
                // 9th pixel completes the window: emit result for exactly one
                // cycle, then clear the buffer and start a fresh window.
                valid_out <= 1'b1;
                edge_out  <= (magnitude > THRESHOLD) ? 8'd255 : 8'd0;
                count     <= 4'd0;
                for (i = 0; i < 9; i = i + 1)
                    pixel_buffer[i] <= 8'd0;
            end else begin
                // shift the incoming pixel into the buffer
                pixel_buffer[8] <= pixel_buffer[7];
                pixel_buffer[7] <= pixel_buffer[6];
                pixel_buffer[6] <= pixel_buffer[5];
                pixel_buffer[5] <= pixel_buffer[4];
                pixel_buffer[4] <= pixel_buffer[3];
                pixel_buffer[3] <= pixel_buffer[2];
                pixel_buffer[2] <= pixel_buffer[1];
                pixel_buffer[1] <= pixel_buffer[0];
                pixel_buffer[0] <= pixel_in;
                count     <= count + 4'd1;
                valid_out <= 1'b0;
                edge_out  <= 8'd0;
            end
        end else begin
            valid_out <= 1'b0;
            edge_out  <= 8'd0;
        end
    end
endmodule

module sorting_engine #(
    parameter N     = 8,
    parameter WIDTH = 8
)(
    input  wire                  clk,
    input  wire                  rst,
    input  wire                  start,
    input  wire [N*WIDTH-1:0]    in_data,
    output reg                   done,
    output reg  [N*WIDTH-1:0]    out_data
);

    // FSM states
    localparam [1:0] IDLE    = 2'd0,
                     SORTING = 2'd1,
                     DONE    = 2'd2;

    reg [1:0]            state;
    // Working array held as a single packed vector, element k occupying
    // arr[k*WIDTH +: WIDTH] — identical element mapping to in_data/out_data.
    reg [N*WIDTH-1:0]   arr;
    integer             i;   // outer pass index   (0 .. N-1)  -> N passes
    integer             j;   // inner compare index (0 .. N-2)

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            done  <= 1'b0;
            i     <= 0;
            j     <= 0;
            // out_data and arr intentionally left uninitialized at reset
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        // latch the whole unsorted array in one assignment
                        arr   <= in_data;
                        i     <= 0;
                        j     <= 0;
                        state <= SORTING;
                    end
                end

                SORTING: begin
                    // one adjacent compare-and-potential-swap per clock cycle
                    if (arr[j*WIDTH +: WIDTH] > arr[(j+1)*WIDTH +: WIDTH]) begin
                        arr[j*WIDTH +: WIDTH]     <= arr[(j+1)*WIDTH +: WIDTH];
                        arr[(j+1)*WIDTH +: WIDTH] <= arr[j*WIDTH +: WIDTH];
                    end
                    // advance the (i,j) iteration; detect completion
                    if ((i == N-1) && (j == N-2)) begin
                        state <= DONE;             // last compare of the last pass
                    end else if (j == N-2) begin
                        j <= 0;
                        i <= i + 1;
                    end else begin
                        j <= j + 1;
                    end
                end

                DONE: begin
                    // present the sorted array and pulse done for one cycle
                    out_data <= arr;
                    done     <= 1'b1;
                    state    <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    // Internal registers to hold the array
    reg [WIDTH-1:0] array [0:N-1];

    // Main FSM states
    localparam IDLE    = 2'd0;
    localparam SORTING = 2'd1;
    localparam DONE    = 2'd2;

    reg [1:0] state;

    // Sub-states implementing the insertion-sort main logic within SORTING
    localparam SS_ACCESS = 2'd0;  // access the element to be inserted
    localparam SS_SHIFT  = 2'd1;  // shift larger elements up (1 cycle each)
    localparam SS_INSERT = 2'd2;  // insert element at the found spot
    localparam SS_CHECK  = 2'd3;  // detect that all elements are sorted

    reg [1:0] sub_state;

    // Insertion-sort indexing
    reg [$clog2(N)-1:0]      idx;  // element currently being inserted
    reg signed [$clog2(N):0] jj;   // scan index (can reach -1)
    reg [WIDTH-1:0]          key;  // value being inserted

    // Combinational shift-need evaluation (mirrors original wire style)
    wire [$clog2(N)-1:0] jj_idx  = jj[$clog2(N)-1:0];
    wire [WIDTH-1:0]     cur_val = array[jj_idx];
    wire                 need_shift = (jj >= 0) && (cur_val > key);

    integer k;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state     <= IDLE;
            sub_state <= SS_ACCESS;
            idx       <= 0;
            jj        <= 0;
            key       <= 0;
            done      <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // 1 clock cycle to set up the start conditions
                        for (k = 0; k < N; k = k + 1)
                            array[k] <= in_data[(k+1)*WIDTH-1 -: WIDTH];
                        idx       <= 1;        // first entry is skipped
                        sub_state <= SS_ACCESS;
                        state     <= SORTING;
                    end
                end

                SORTING: begin
                    case (sub_state)
                        // 1 clock cycle to access the element to be sorted
                        SS_ACCESS: begin
                            key       <= array[idx];
                            jj        <= idx - 1;
                            sub_state <= SS_SHIFT;
                        end

                        // Every shift operation takes 1 clock cycle; the cycle
                        // where no further shift is required detects the
                        // iterations for that element are complete.
                        SS_SHIFT: begin
                            if (need_shift) begin
                                array[jj_idx + 1] <= array[jj_idx];
                                jj                <= jj - 1;
                            end else begin
                                sub_state <= SS_INSERT;
                            end
                        end

                        // 1 clock cycle to insert the element at the spot found
                        SS_INSERT: begin
                            if (jj < 0)
                                array[0] <= key;
                            else
                                array[jj_idx + 1] <= key;

                            if (idx == N-1) begin
                                sub_state <= SS_CHECK;
                            end else begin
                                idx       <= idx + 1;
                                sub_state <= SS_ACCESS;
                            end
                        end

                        // 1 clock cycle to detect that all elements are sorted
                        SS_CHECK: begin
                            state <= DONE;
                        end

                        default: sub_state <= SS_ACCESS;
                    endcase
                end

                // 1 clock cycle to output the sorted array and assert done
                DONE: begin
                    done <= 1;
                    for (k = 0; k < N; k = k + 1)
                        out_data[(k+1)*WIDTH-1 -: WIDTH] <= array[k];
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,
    parameter WIDTH = 8
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);
    localparam IDLE = 2'd0,
               LOAD = 2'd1,
               SORT = 2'd2,
               DONE = 2'd3;

    reg [1:0]  state, next_state;
    reg [WIDTH-1:0] data_array [0:N-1];
    reg [$clog2(N+1)-1:0] pass_cnt;
    reg [$clog2(N/2+1)-1:0] pair_idx;

    wire [$clog2(N/2+1)-1:0] pairs_in_this_pass;
    assign pairs_in_this_pass = (pass_cnt[0] == 1'b0) ? (N/2) : ( (N/2) > 0 ? (N/2) - 1 : 0 );

    integer i;
    integer base_idx;

    // Brick sort (odd-even transposition sort) implemented as a 4-state FSM.
    // Latency = N*(N-1)/2 + 4 :
    //   1 : IDLE -> LOAD
    //   1 : load the full array in a single cycle (LOAD)
    //   N*(N-1)/2 : one compare-and-swap per cycle over N passes (SORT)
    //   1 : SORT -> DONE (recognise all passes complete)
    //   1 : latch sorted output onto out_data and pulse done (DONE)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state    <= IDLE;
            done     <= 1'b0;
            pass_cnt <= 0;
            pair_idx <= 0;
            for (i = 0; i < N; i = i + 1)
                data_array[i] <= {WIDTH{1'b0}};
            // out_data intentionally left uninitialised at reset (per spec)
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start)
                        state <= LOAD;
                end

                LOAD: begin
                    for (i = 0; i < N; i = i + 1)
                        data_array[i] <= in_data[i*WIDTH +: WIDTH];
                    pass_cnt <= 0;
                    pair_idx <= 0;
                    state    <= SORT;
                end

                SORT: begin
                    if (pass_cnt >= N) begin
                        // all N passes done -> spend one cycle transitioning to DONE
                        state <= DONE;
                    end else if (pairs_in_this_pass == 0) begin
                        // empty pass (only possible when N==2 on an odd pass)
                        pass_cnt <= pass_cnt + 1'b1;
                        pair_idx <= 0;
                    end else begin
                        // even pass compares (0,1),(2,3),...  -> base = 2*pair_idx
                        // odd  pass compares (1,2),(3,4),...  -> base = 2*pair_idx+1
                        base_idx = (pass_cnt[0]) ? (2*pair_idx + 1) : (2*pair_idx);
                        if (data_array[base_idx] > data_array[base_idx+1]) begin
                            data_array[base_idx]     <= data_array[base_idx+1];
                            data_array[base_idx + 1] <= data_array[base_idx];
                        end
                        if (pair_idx >= (pairs_in_this_pass - 1'b1)) begin
                            pair_idx <= 0;
                            pass_cnt <= pass_cnt + 1'b1;
                        end else begin
                            pair_idx <= pair_idx + 1'b1;
                        end
                    end
                end

                DONE: begin
                    for (i = 0; i < N; i = i + 1)
                        out_data[i*WIDTH +: WIDTH] <= data_array[i];
                    done  <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module sorting_engine #(
    parameter N = 8,          // number of elements to sort
    parameter WIDTH = 8       // bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    //-----------------------------------------------------
    // State machine definitions
    //-----------------------------------------------------
    localparam [3:0]
        S_IDLE         = 4'd0,
        S_LOAD_INPUT   = 4'd1,
        S_FIND_MAX     = 4'd2,
        S_COUNT        = 4'd3,
        S_PREFIX_SUM   = 4'd4,
        S_BUILD_OUTPUT = 4'd5,
        S_COPY_OUTPUT  = 4'd6,
        S_DONE         = 4'd7;

    //-----------------------------------------------------
    // Registered signals (updated in sequential always)
    //-----------------------------------------------------
    reg [3:0]           current_state;
    reg [WIDTH-1:0]     data_array [0:N-1];
    reg [WIDTH-1:0]     out_array  [0:N-1];
    reg [$clog2(N):0]   count_array[0:(1<<WIDTH)-1];

    reg [WIDTH-1:0]     max_val;
    reg [$clog2(N):0]   load_cnt;
    reg [$clog2(N):0]   find_cnt;
    reg [$clog2(N):0]   count_cnt;
    reg [WIDTH-1:0]     prefix_cnt;
    reg [$clog2(N):0]   build_cnt;
    reg [$clog2(N):0]   copy_cnt;

    //-----------------------------------------------------
    // Wires/reg for "next" values (computed combinationally)
    //-----------------------------------------------------
    reg [3:0]           next_state;

    // Arrays get "shadow copies" for combinational updates
    reg [WIDTH-1:0]     next_data_array [0:N-1];
    reg [WIDTH-1:0]     next_out_array  [0:N-1];
    reg [$clog2(N):0]   next_count_array[0:(1<<WIDTH)-1];

    reg [WIDTH-1:0]     next_max_val;
    reg [$clog2(N):0]   next_load_cnt;
    reg [$clog2(N):0]   next_find_cnt;
    reg [$clog2(N):0]   next_count_cnt;
    reg [WIDTH-1:0]     next_prefix_cnt;
    reg [$clog2(N):0]   next_build_cnt;
    reg [$clog2(N):0]   next_copy_cnt;

    reg                 next_done;
    reg [N*WIDTH-1:0]   next_out_data;
    integer rev_idx;
    reg [WIDTH-1:0] val;
    reg [$clog2(N):0] pos;

    integer i;   // used by the sequential/reset block
    integer k;   // used by the combinational block

    //-----------------------------------------------------
    // Combinational next-state / next-value logic  (Counting sort)
    //
    // The described algorithm builds the sorted array with the
    // LARGEST value first (out_array[0] = largest), reproduced by a
    // SUFFIX cumulative sum: count_array[v] = number of elements >= v,
    // then out_array[count_array[data[i]]-1] = data[i] with the input
    // scanned end -> start for stability.  This matches the prompt's
    // worked traces:  in=[0,1,2,3] -> out=[3,2,1,0]  and
    // in=[14,12,12,15] -> out_array=[15,14,12,12].
    //
    // State occupancies (matches Latency = 4*(N+1)+max_val+4):
    //   S_IDLE        : 1 (start cycle)
    //   S_LOAD_INPUT  : N+1  (N loads + 1 transition)
    //   S_FIND_MAX    : N+1
    //   S_COUNT       : N+1
    //   S_PREFIX_SUM  : max_val+1  (max_val adds + 1 transition)
    //   S_BUILD_OUTPUT: N+1
    //   S_COPY_OUTPUT : 1
    //   S_DONE        : 1  (done asserted)
    //-----------------------------------------------------
    always @(*) begin
        // Defaults: hold all state (avoid latches)
        next_state      = current_state;
        next_done       = 1'b0;
        next_out_data   = out_data;
        next_max_val    = max_val;
        next_load_cnt   = load_cnt;
        next_find_cnt   = find_cnt;
        next_count_cnt  = count_cnt;
        next_prefix_cnt = prefix_cnt;
        next_build_cnt  = build_cnt;
        next_copy_cnt   = copy_cnt;

        for (k = 0; k < N; k = k + 1) begin
            next_data_array[k] = data_array[k];
            next_out_array[k]  = out_array[k];
        end
        for (k = 0; k < (1<<WIDTH); k = k + 1) begin
            next_count_array[k] = count_array[k];
        end

        rev_idx = 0;
        val     = {WIDTH{1'b0}};
        pos     = {($clog2(N)+1){1'b0}};

        case (current_state)
            S_IDLE: begin
                next_done       = 1'b0;
                next_max_val    = {WIDTH{1'b0}};
                next_load_cnt   = 0;
                next_find_cnt   = 0;
                next_count_cnt  = 0;
                next_prefix_cnt = 0;
                next_build_cnt  = 0;
                next_copy_cnt   = 0;
                for (k = 0; k < N; k = k + 1)
                    next_out_array[k] = {WIDTH{1'b0}};
                if (start)
                    next_state = S_LOAD_INPUT;
                else
                    next_state = S_IDLE;
            end

            S_LOAD_INPUT: begin
                // Clear the histogram for a fresh sort while loading
                // (BUILD leaves count_array dirty; must re-clear per op).
                for (k = 0; k < (1<<WIDTH); k = k + 1)
                    next_count_array[k] = {($clog2(N)+1){1'b0}};

                if (load_cnt < N) begin
                    next_data_array[load_cnt] = in_data[load_cnt*WIDTH +: WIDTH];
                    next_load_cnt = load_cnt + 1;
                end else begin
                    next_state    = S_FIND_MAX;
                    next_find_cnt = 0;
                    next_max_val  = {WIDTH{1'b0}};
                end
            end

            S_FIND_MAX: begin
                if (find_cnt < N) begin
                    if (data_array[find_cnt] > max_val)
                        next_max_val = data_array[find_cnt];
                    next_find_cnt = find_cnt + 1;
                end else begin
                    next_state     = S_COUNT;
                    next_count_cnt = 0;
                end
            end

            S_COUNT: begin
                if (count_cnt < N) begin
                    next_count_array[data_array[count_cnt]] =
                        count_array[data_array[count_cnt]] + 1'b1;
                    next_count_cnt = count_cnt + 1;
                end else begin
                    next_state      = S_PREFIX_SUM;
                    next_prefix_cnt = 0;
                end
            end

            S_PREFIX_SUM: begin
                // Suffix cumulative sum: count_array[v] += count_array[v+1]
                // for v = (max_val-1) downto 0  (max_val cycles).
                if (prefix_cnt < max_val) begin
                    next_count_array[max_val - 1'b1 - prefix_cnt] =
                        count_array[max_val - 1'b1 - prefix_cnt] +
                        count_array[max_val - prefix_cnt];
                    next_prefix_cnt = prefix_cnt + 1;
                end else begin
                    next_state     = S_BUILD_OUTPUT;
                    next_build_cnt = 0;
                end
            end

            S_BUILD_OUTPUT: begin
                // Scan input end -> start for stable placement.
                if (build_cnt < N) begin
                    rev_idx = N - 1 - build_cnt;
                    val     = data_array[rev_idx];
                    pos     = count_array[val] - 1'b1;
                    next_out_array[pos]   = val;
                    next_count_array[val] = count_array[val] - 1'b1;
                    next_build_cnt        = build_cnt + 1;
                end else begin
                    next_state    = S_COPY_OUTPUT;
                    next_copy_cnt = 0;
                end
            end

            S_COPY_OUTPUT: begin
                // Pack the unpacked sorted array onto the output bus.
                for (k = 0; k < N; k = k + 1)
                    next_out_data[k*WIDTH +: WIDTH] = out_array[k];
                next_state = S_DONE;
            end

            S_DONE: begin
                // Assert done for exactly one cycle, return to idle.
                next_done  = 1'b1;
                next_state = S_IDLE;
            end

            default: next_state = S_IDLE;
        endcase
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // asynchronous reset
            current_state <= S_IDLE;
            done          <= 1'b0;
            out_data      <= {N*WIDTH{1'b0}};
            max_val       <= {WIDTH{1'b0}};

            load_cnt      <= 0;
            find_cnt      <= 0;
            count_cnt     <= 0;
            prefix_cnt    <= 0;
            build_cnt     <= 0;
            copy_cnt      <= 0;

            // Clear arrays
            for (i = 0; i < N; i = i + 1) begin
                data_array[i] <= {WIDTH{1'b0}};
                out_array[i]  <= {WIDTH{1'b0}};
            end
            for (i = 0; i < (1<<WIDTH); i = i + 1) begin
                count_array[i] <= {($clog2(N)+1){1'b0}};
            end

        end else begin
            current_state <= next_state;
            done          <= next_done;
            out_data      <= next_out_data;
            max_val       <= next_max_val;

            load_cnt      <= next_load_cnt;
            find_cnt      <= next_find_cnt;
            count_cnt     <= next_count_cnt;
            prefix_cnt    <= next_prefix_cnt;
            build_cnt     <= next_build_cnt;
            copy_cnt      <= next_copy_cnt;

            for (i = 0; i < N; i = i + 1) begin
                data_array[i] <= next_data_array[i];
                out_array[i]  <= next_out_array[i];
            end
            for (i = 0; i < (1<<WIDTH); i = i + 1) begin
                count_array[i] <= next_count_array[i];
            end
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    // Internal registers to hold the array
    reg [WIDTH-1:0] array [0:N-1];

    // FSM states
    localparam IDLE    = 2'd0;
    localparam SORTING = 2'd1;
    localparam DONE    = 2'd2;

    reg [1:0]  state, next_state;

    // Area optimization: bubble-sort indices sized to the array range
    // (was 32-bit `int`, which cost ~58 extra flops plus wide incrementers
    //  and comparators). Minimal width preserves function and latency.
    reg [$clog2(N)-1:0] i;  // Outer loop index
    reg [$clog2(N)-1:0] j;  // Inner loop index

    // Wires for comparison and swap
    wire [WIDTH-1:0] val_j;
    wire [WIDTH-1:0] val_j1;

    assign val_j  = array[j];
    assign val_j1 = array[j+1];

    // FSM: Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start)
                    next_state = SORTING;
            end
            SORTING: begin
                // Transition to DONE once all passes are complete
                if (i == (N-1) && j == (N-2))
                    next_state = DONE;
            end
            DONE: begin
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // FSM: Output and counter updates
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            i <= 0;
            j <= 0;
            done <= 0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Load the array from in_data
                        for (int k = 0; k < N; k = k + 1) begin
                            array[k] <= in_data[(k+1)*WIDTH-1 -: WIDTH];
                        end
                        i <= 0;
                        j <= 0;
                    end
                end

                SORTING: begin
                    // Perform a single comparison and swap if needed
                    if (val_j > val_j1) begin
                        array[j]   <= val_j1;
                        array[j+1] <= val_j;
                    end

                    // Update j
                    if (j == N-2) begin
                        // One pass completed, increment i
                        j <= 0;
                        i <= i + 1;
                    end else begin
                        j <= j + 1;
                    end
                end

                DONE: begin
                    // Sorting complete
                    done <= 1;
                    // Output the sorted data
                    for (int m = 0; m < N; m = m + 1) begin
                        out_data[(m+1)*WIDTH-1 -: WIDTH] <= array[m];
                    end
                end
                default: begin
                end
            endcase
        end
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    out_data = 0;
  end

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    localparam IDLE  = 0;
    localparam LOAD  = 1;
    localparam SORT  = 2;
    localparam MERGE = 3;

    function integer clog2;
        input integer value;
        integer i;
        begin
            clog2 = 0;
            for (i = 1; i < value; i = i << 1) begin
                clog2 = clog2 + 1;
            end
        end
    endfunction

    localparam ADDR_WIDTH = clog2(N) + 1;

    reg [1:0]                 state;

    reg [WIDTH-1:0]           data_mem [0:N-1];

    reg [ADDR_WIDTH-1:0]      base_idx;
    reg [ADDR_WIDTH-1:0]      left_idx;
    reg [ADDR_WIDTH-1:0]      right_idx;
    reg [ADDR_WIDTH-1:0]      merge_idx;
    reg [ADDR_WIDTH-1:0]      subarray_size;

    reg [WIDTH-1:0]           tmp_merge [0:N-1];

    reg [WIDTH-1:0]           left_val;
    reg [WIDTH-1:0]           right_val;

    integer i, k;
    reg [ADDR_WIDTH-1:0] left_end, right_end;
    reg [ADDR_WIDTH-1:0] l_addr,   r_addr;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state         <= IDLE;
            done          <= 1'b0;
            out_data      <= {N*WIDTH{1'b0}};
            base_idx      <= 0;
            left_idx      <= 0;
            right_idx     <= 0;
            merge_idx     <= 0;
            subarray_size <= 1;
        end else begin
            case (state)

                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= LOAD;
                    end
                end

                LOAD: begin
                    for (i = 0; i < N; i = i + 1) begin
                        data_mem[i] <= in_data[i*WIDTH +: WIDTH];
                    end
                    base_idx      <= 0;
                    left_idx      <= 0;
                    right_idx     <= 0;
                    merge_idx     <= 0;
                    subarray_size <= 1;
                    state <= SORT;
                end

                SORT: begin
                    if (subarray_size >= N) begin
                        // Finish: emit result and assert done directly
                        // (fold former DONE state -> latency reduced by 1 cycle)
                        for (i = 0; i < N; i = i + 1) begin
                            out_data[i*WIDTH +: WIDTH] <= data_mem[i];
                        end
                        done  <= 1'b1;
                        state <= IDLE;
                    end else begin
                        base_idx  <= 0;
                        merge_idx <= 0;
                        left_idx  <= 0;
                        right_idx <= 0;
                        state     <= MERGE;
                    end
                end

                MERGE: begin
                    if ((l_addr <= left_end) && (r_addr <= right_end)) begin
                        if (left_val <= right_val) begin
                            tmp_merge[merge_idx] <= left_val;
                            left_idx <= left_idx + 1;
                        end else begin
                            tmp_merge[merge_idx] <= right_val;
                            right_idx <= right_idx + 1;
                        end
                        merge_idx <= merge_idx + 1;
                    end
                    else if (l_addr <= left_end) begin
                        tmp_merge[merge_idx] <= left_val;
                        left_idx <= left_idx + 1;
                        merge_idx <= merge_idx + 1;
                    end
                    else if (r_addr <= right_end) begin
                        tmp_merge[merge_idx] <= right_val;
                        right_idx <= right_idx + 1;
                        merge_idx <= merge_idx + 1;
                    end
                    else begin
                        for (k = 0; k < N; k = k + 1) begin
                            if ( (k < merge_idx) && (k < (subarray_size << 1)) && ((base_idx + k) < N) )
                            begin
                                data_mem[base_idx + k] <= tmp_merge[k];
                            end
                        end
                        base_idx  <= base_idx + (subarray_size << 1);
                        left_idx  <= 0;
                        right_idx <= 0;
                        merge_idx <= 0;
                        if ((base_idx + (subarray_size << 1)) >= N) begin
                            subarray_size <= subarray_size << 1;
                            state         <= SORT;
                        end
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

always @ (*) begin
    if(state == MERGE) begin
        left_end  = base_idx + subarray_size - 1;
        right_end = base_idx + (subarray_size << 1) - 1;

        if (left_end >= N) left_end = N - 1;
        if (right_end >= N) right_end = N - 1;

        l_addr = base_idx + left_idx;
        r_addr = base_idx + subarray_size + right_idx;

        if ((l_addr <= left_end) && (l_addr < N))
            left_val = data_mem[l_addr];
        else
            left_val = {WIDTH{1'b1}};

        if ((r_addr <= right_end) && (r_addr < N))
            right_val = data_mem[r_addr];
        else
            right_val = {WIDTH{1'b1}};
    end else begin
        left_end = 0;
        right_end = 0;
        l_addr = 0;
        r_addr = 0;
        left_val = 0;
        right_val = 0;
    end
end

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    // Internal array
    reg [WIDTH-1:0] array [0:N-1];

    // FSM states
    localparam IDLE    = 2'd0;
    localparam SORTING = 2'd1;
    localparam DONE    = 2'd2;

    reg [1:0] state, next_state;

    // Area optimization: the original design used 32-bit `integer` for the
    // loop-control variables i and j.  They only ever span a tiny range, so
    // they are narrowed to the minimum width that reproduces every value
    // bit-for-bit, cycle-for-cycle (preserving function AND latency):
    //   i counts 0..N        -> unsigned IDX_W bits
    //   j spans -1..N-2       -> signed (IDX_W+1) bits (kept signed so the
    //                            "j >= 0" comparison matches the original,
    //                            where `integer` and the literal 0 are signed)
    localparam IDX_W = $clog2(N+1);

    // Insertion sort variables
    reg [IDX_W-1:0]      i;
    reg signed [IDX_W:0] j;
    reg [WIDTH-1:0]      key;

    // Insertion sort phases for each i
    // 0: Initialize key and j
    // 1: Shift elements greater than key
    // 2: Insert key
    reg [1:0] insert_phase;

    // FSM: Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start)
                    next_state = SORTING;
            end
            SORTING: begin
                // Once i reaches N, sorting is done
                if (i == N)
                    next_state = DONE;
            end
            DONE: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // FSM: main logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state         <= IDLE;
            done          <= 0;
            i             <= 0;
            j             <= 0;
            key           <= 0;
            insert_phase  <= 0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Load array from in_data
                        for (int k = 0; k < N; k = k + 1) begin
                            array[k] <= in_data[(k+1)*WIDTH-1 -: WIDTH];
                        end
                        i <= 1; // Start insertion sort from index 1
                        j <= 0;
                        key <= 0;
                        insert_phase <= 0;
                    end
                end

                SORTING: begin
                    // Perform insertion sort step-by-step
                    case (insert_phase)
                        0: begin
                            // Phase 0: Setup for inserting array[i]
                            if (i < N) begin
                                key <= array[i];
                                j <= i - 1;
                                insert_phase <= 1;
                            end
                            // If i == N, sorting complete, next cycle moves to DONE
                        end

                        1: begin
                            // Phase 1: Shift elements to the right until the correct spot is found
                            if (j >= 0 && array[j] > key) begin
                                array[j+1] <= array[j];
                                j <= j - 1;
                            end else begin
                                // We found the spot (or j < 0)
                                insert_phase <= 2;
                            end
                        end

                        2: begin
                            // Phase 2: Insert the key at array[j+1]
                            array[j+1] <= key;
                            i <= i + 1;
                            insert_phase <= 0;
                        end

                        default: insert_phase <= 0;
                    endcase
                end

                DONE: begin
                    // Sorting complete, output the result
                    done <= 1;
                    for (int m = 0; m < N; m = m + 1) begin
                        out_data[(m+1)*WIDTH-1 -: WIDTH] <= array[m];
                    end
                end

                default: begin
                    // Should not get here
                end
            endcase
        end
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    out_data = 0;
  end

endmodule

module soundgenerator #(
	parameter  CLOCK_HZ = 10_000_000
)(
	input wire clk,                                         //input clock signal with frequency 10Mhz
	input wire nrst,                                        //active low asynchronous reset.

	input wire start,                                       //indicate the start of the operation.
	input wire finish,                                      //indicate the end of operation.
	input wire [15:0] sond_dur_ms_i,                        //this signal indicate for how much time the sound should be generated in millisecond.
	input wire [15:0] half_period_us_i,                     //this signal indicate the frequency of the output signal by giving the half time period required for the output soundwave_o

	output wire soundwave_o,                                //output sound wave signal.
	output wire busy,                                       //indicate the system is busy.
	output wire done                                        //indicate the operation is completed.
);

	// Timing pulses from the two strobe generators.
	wire tick_ms;   // one pulse every 1 millisecond
	wire tick_us;   // one pulse every 1 microsecond

	reg  [15:0] duration_counter;   // remaining duration in milliseconds
	reg  [15:0] halfperiodtimer;    // counts down the half-period in microseconds
	reg         wave;               // the square wave state
	reg         busy_prev;          // registered copy of busy for edge detection

	// Busy while there is remaining duration to play.
	assign busy = (duration_counter != 16'd0);

	// Millisecond strobe generator (1 ms = 1000 us period).
	strob_gen #(
		.CLOCK_HZ (CLOCK_HZ),
		.PERIOD_US(1000)
	) TickMilli (
		.clk     (clk),
		.nrst    (nrst),
		.enable  (busy),
		.strobe_o(tick_ms)
	);

	// Microsecond strobe generator (1 us period).
	strob_gen #(
		.CLOCK_HZ (CLOCK_HZ),
		.PERIOD_US(1)
	) tickmicro (
		.clk     (clk),
		.nrst    (nrst),
		.enable  (busy),
		.strobe_o(tick_us)
	);

	// ----------------------------------------------------------------------
	// Duration timer: load on start, decrement every millisecond while active.
	// ----------------------------------------------------------------------
	always @(posedge clk or negedge nrst) begin
		if (!nrst)
			duration_counter <= 16'd0;
		else if (start)
			duration_counter <= sond_dur_ms_i;
		else if (finish)
			duration_counter <= 16'd0;
		else if (tick_ms && (duration_counter != 16'd0))
			duration_counter <= duration_counter - 16'd1;
	end

	// ----------------------------------------------------------------------
	// Half-period timer and square-wave generation.
	// On every microsecond tick while active the timer decrements; when it
	// reaches zero the wave toggles and the timer reloads.
	// ----------------------------------------------------------------------
	always @(posedge clk or negedge nrst) begin
		if (!nrst) begin
			halfperiodtimer <= 16'd0;
			wave            <= 1'b0;
		end else if (busy) begin
			if (tick_us) begin
				if (halfperiodtimer == 16'd0) begin
					wave            <= ~wave;
					halfperiodtimer <= half_period_us_i;
				end else begin
					halfperiodtimer <= halfperiodtimer - 16'd1;
				end
			end
		end else begin
			halfperiodtimer <= half_period_us_i;
			wave            <= 1'b0;
		end
	end

	// ----------------------------------------------------------------------
	// Completion detection: done pulses for one cycle when busy drops.
	// ----------------------------------------------------------------------
	always @(posedge clk or negedge nrst) begin
		if (!nrst)
			busy_prev <= 1'b0;
		else
			busy_prev <= busy;
	end

	assign done        = busy_prev & ~busy;
	assign soundwave_o = busy ? wave : 1'b0;

endmodule

module strob_gen #(
	parameter	CLOCK_HZ	= 10_000_000,
	parameter	PERIOD_US	= 100
)(
	input wire  clk,
	input wire  nrst,
	input wire  enable,
	output reg  strobe_o
);

	// Number of clock cycles that make up one strobe period.
	localparam integer DELAY = CLOCK_HZ / 1_000_000 * PERIOD_US;

	reg [31:0] counter;

	always @(posedge clk or negedge nrst) begin
		if (!nrst) begin
			counter  <= DELAY;
			strobe_o <= 1'b0;
		end else if (!enable) begin
			counter  <= DELAY;
			strobe_o <= 1'b0;
		end else if (counter == 32'd0) begin
			strobe_o <= 1'b1;
			counter  <= DELAY;
		end else begin
			strobe_o <= 1'b0;
			counter  <= counter - 32'd1;
		end
	end

endmodule

module sprite_controller_fsm#(
   parameter MEM_ADDR_WIDTH = 16,
   parameter PIXEL_WIDTH = 24,
   parameter SPRITE_WIDTH = 16,
   parameter SPRITE_HEIGHT = 16,
   parameter WAIT_WIDTH    = 4,
   parameter N_ROM         = 256
)(
   input  logic clk,
   input  logic rst_n,
   input  logic [WAIT_WIDTH-1:0] i_wait,
   output logic rw,
   output logic [MEM_ADDR_WIDTH-1:0] write_addr,
   output logic [PIXEL_WIDTH-1:0] write_data,
   output logic [SPRITE_WIDTH-1:0] x_pos,
   output logic [SPRITE_HEIGHT-1:0] y_pos,
   input  logic [PIXEL_WIDTH-1:0] pixel_out,
   output logic done
);

   // Derived coordinate widths.
   localparam int X_WIDTH = $clog2(SPRITE_WIDTH);
   localparam int Y_WIDTH = $clog2(SPRITE_HEIGHT);

   typedef enum logic [2:0] {
       IDLE,
       INIT_WRITE,
       WRITE,
       INIT_READ,
       READ,
       WAIT,
       DONE
   } state_t;

   state_t current_state, next_state;

   logic [MEM_ADDR_WIDTH-1:0] addr_counter;
   logic [PIXEL_WIDTH-1:0] data_counter;
   logic [WAIT_WIDTH-1:0] wait_counter;

   // -------------------------------------------------------------------
   // Sequential: state register and counter updates per current state.
   // Active-low asynchronous reset.
   // -------------------------------------------------------------------
   always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         current_state <= IDLE;
         addr_counter  <= '0;
         data_counter  <= '0;
         wait_counter  <= '0;
      end else begin
         current_state <= next_state;
         case (current_state)
            IDLE: begin
               addr_counter <= '0;
               data_counter <= '0;
               wait_counter <= '0;
            end
            INIT_WRITE: begin
               addr_counter <= '0;
            end
            WRITE: begin
               addr_counter <= addr_counter + 1'b1;
               data_counter <= data_counter + 1'b1;
            end
            INIT_READ: begin
               addr_counter <= '0;
            end
            READ: begin
               addr_counter <= addr_counter + 1'b1;
            end
            WAIT: begin
               wait_counter <= wait_counter + 1'b1;
            end
            DONE: begin
               // no counter activity
            end
            default: begin
               addr_counter <= '0;
               data_counter <= '0;
               wait_counter <= '0;
            end
         endcase
      end
   end

   // -------------------------------------------------------------------
   // Combinational: next-state logic.
   // -------------------------------------------------------------------
   always @(*) begin
      next_state = current_state;
      case (current_state)
         IDLE:       next_state = INIT_WRITE;
         INIT_WRITE: next_state = WRITE;
         WRITE: begin
            if (addr_counter == (N_ROM - 1)) next_state = INIT_READ;
            else                             next_state = WRITE;
         end
         INIT_READ:  next_state = READ;
         READ: begin
            if (addr_counter == (N_ROM - 1)) next_state = WAIT;
            else                             next_state = READ;
         end
         WAIT: begin
            if (wait_counter == i_wait) next_state = DONE;
            else                        next_state = WAIT;
         end
         DONE:       next_state = IDLE;
         default:    next_state = IDLE;
      endcase
   end

   // -------------------------------------------------------------------
   // Combinational: output signal generation.
   //   rw          -> 1 only in WRITE, 0 otherwise
   //   write_addr  -> addr_counter
   //   write_data  -> 24'hFF0000 in INIT_WRITE, else data_counter
   //   x_pos       -> addr_counter % SPRITE_WIDTH  (lower X_WIDTH bits)
   //   y_pos       -> addr_counter / SPRITE_WIDTH  (next Y_WIDTH bits)
   //   done        -> 1 only in DONE
   // -------------------------------------------------------------------
   always @(*) begin
      rw         = (current_state == WRITE);
      write_addr = addr_counter;
      write_data = (current_state == INIT_WRITE) ? 24'hFF0000 : data_counter;
      x_pos      = '0;
      y_pos      = '0;
      x_pos[X_WIDTH-1:0] = addr_counter[X_WIDTH-1:0];
      y_pos[Y_WIDTH-1:0] = addr_counter[X_WIDTH +: Y_WIDTH];
      done       = (current_state == DONE);
   end

endmodule

module Bitstream(input  logic clk,rst_n,
                 input  logic enb,
                 input  logic rempty_in,
                 input  logic rinc_in,
                 input  logic [7:0] i_byte,
                 output logic o_bit,
                 output logic rempty_out,
                 output logic rinc_out);

    parameter IDLE  = 3'b000;
    parameter WaitR = 3'b001;
    parameter Ready = 3'b010;

    // 3-bit state to match the 3-bit state parameters (fixes case-expression width mismatch)
    logic [2:0] curr_state, next_state;

    // Byte buffer with conventional descending range (fixes reversed bit range)
    logic [7:0] byte_buf;
    logic [3:0] bp;
    logic rde;

    //FSM state register
    always_ff @(posedge clk) begin
        if(!rst_n) curr_state <= IDLE;
        else       curr_state <= next_state;
    end

    //FSM next-state / output logic
    //Default assignments prevent inferred latches on next_state/rempty_out/rinc_out
    always_comb begin
        next_state = curr_state;
        rempty_out = 1'b1;
        rinc_out   = 1'b0;
        case(curr_state)
            IDLE: begin
                if(enb) begin
                    next_state = WaitR;
                    rempty_out = 1'b1;
                    rinc_out   = 1'b0;
                end
                else begin
                    next_state = IDLE;
                    rempty_out = 1'b1;
                    rinc_out   = 1'b0;
                end
            end
            WaitR: begin
                if(rempty_in) begin
                    next_state = WaitR;
                    rempty_out = 1'b1;
                    rinc_out   = 1'b0;
                end
                else begin
                    next_state = Ready;
                    rempty_out = 1'b1;
                    rinc_out   = 1'b1;
                end
            end
            Ready: begin
                if(rde) begin
                    if(rempty_in) begin
                        next_state = WaitR;
                        rempty_out = 1'b1;
                        rinc_out   = 1'b0;
                    end
                    else begin
                        next_state = Ready;
                        rempty_out = 1'b1;
                        rinc_out   = 1'b1;
                    end
                end
                else begin
                    next_state = Ready;
                    rempty_out = 1'b0;
                    rinc_out   = 1'b0;
                end
            end
            default: begin
                next_state = IDLE;
                rempty_out = 1'b1;
                rinc_out   = 1'b0;
            end
        endcase
    end

    //Buffer the full incoming byte (fixes truncation / unused input bit)
    always_ff @(posedge clk) begin
        if(rinc_out)
            byte_buf <= i_byte;
    end

    //Bit position pointer
    always_ff @(posedge clk) begin
        if(rinc_out)
            bp <= 4'b0;
        else if(rinc_in & ~rempty_out)
            bp <= bp + 1'b1;
    end

    //Other comb logic
    assign rde   = bp[3];
    assign o_bit = byte_buf[bp[2:0]];

endmodule

// square_root_seq: sequential subtraction-based integer square root.
// Derived from the combinational `square_root` reference by converting the
// bitwise algorithm into a subtract-consecutive-odd-numbers state machine.
module square_root_seq #(parameter WIDTH = 16) (
    input  wire [WIDTH-1:0]     num,        // number to root; stable during compute
    input  wire                 clk,        // positive-edge clock
    input  wire                 rst,        // active-high asynchronous reset
    input  wire                 start,      // active-high start (>=1 cycle)
    output reg  [WIDTH/2-1:0]   final_root, // integer square root (valid when done)
    output reg                  done        // 1-cycle completion strobe
);

    // FSM states
    localparam IDLE    = 1'b0;
    localparam COMPUTE = 1'b1;

    reg                  state;

    // spec-named intermediate signals (VERBATIM)
    reg [WIDTH-1:0]      remainder;  // running remainder, seeded with num
    reg [WIDTH-1:0]      odd;        // current consecutive odd number (1,3,5,...)
    reg [WIDTH/2-1:0]    root;       // accumulating square-root value

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state      <= IDLE;
            done       <= 1'b0;
            final_root <= {(WIDTH/2){1'b0}};
            remainder  <= {WIDTH{1'b0}};
            odd        <= {WIDTH{1'b0}};
            root       <= {(WIDTH/2){1'b0}};
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;                 // clear completion strobe
                    if (start) begin
                        remainder <= num;          // seed remainder with input
                        odd       <= {{(WIDTH-1){1'b0}}, 1'b1}; // first odd = 1
                        root      <= {(WIDTH/2){1'b0}};         // root = 0
                        state     <= COMPUTE;
                    end
                end

                COMPUTE: begin
                    if (remainder >= odd) begin
                        // subtract current odd, count it, advance odd number
                        remainder <= remainder - odd;
                        root      <= root + 1'b1;
                        odd       <= odd + 2'd2;
                    end else begin
                        // remainder < odd: computation finished
                        final_root <= root;
                        done       <= 1'b1;
                        state      <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module static_branch_predict (
    input  wire [31:0] fetch_rdata_i,
    input  wire [31:0] fetch_pc_i,
    input  wire        fetch_valid_i,
    output wire        predict_branch_taken_o,
    output wire [31:0] predict_branch_pc_o
);

    // Opcodes
    localparam [6:0] OPCODE_BRANCH = 7'h63;
    localparam [6:0] OPCODE_JAL    = 7'h6F;
    localparam [6:0] OPCODE_JALR   = 7'h67;

    wire [31:0] instr;

    wire [31:0] imm_j_type;
    wire [31:0] imm_b_type;
    wire [31:0] imm_cj_type;
    wire [31:0] imm_cb_type;
    wire [31:0] branch_imm;

    wire instr_j;
    wire instr_b;
    wire instr_cj;
    wire instr_cb;
    wire instr_b_taken;

    // Alias for the fetched instruction
    assign instr = fetch_rdata_i;

    // Immediate extraction with sign extension to 32 bits
    // Uncompressed JAL (J-type) immediate
    assign imm_j_type  = { {12{instr[31]}}, instr[19:12], instr[20], instr[30:21], 1'b0 };
    // Uncompressed conditional branch (B-type) immediate
    assign imm_b_type  = { {19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0 };
    // Compressed jump (CJ-type) immediate (raw compressed layout in instr[15:0])
    assign imm_cj_type = { {20{instr[12]}}, instr[12], instr[8], instr[10:9], instr[6],
                           instr[7], instr[2], instr[11], instr[5:3], 1'b0 };
    // Compressed branch (CB-type) immediate (raw compressed layout in instr[15:0])
    assign imm_cb_type = { {23{instr[12]}}, instr[12], instr[6:5], instr[2],
                           instr[11:10], instr[4:3], 1'b0 };

    // Instruction type decoding
    // Uncompressed detection by opcode
    assign instr_b  = (instr[6:0] == OPCODE_BRANCH);
    assign instr_j  = (instr[6:0] == OPCODE_JAL);
    // Compressed detection by quadrant (bits[1:0]==01) and funct3 (bits[15:13])
    assign instr_cj = (instr[1:0] == 2'b01) &
                      ((instr[15:13] == 3'b101) | (instr[15:13] == 3'b001)); // C.J / C.JAL
    assign instr_cb = (instr[1:0] == 2'b01) &
                      ((instr[15:13] == 3'b110) | (instr[15:13] == 3'b111)); // C.BEQZ / C.BNEZ

    // Select the appropriate immediate as the branch offset
    assign branch_imm = instr_j  ? imm_j_type  :
                        instr_b  ? imm_b_type  :
                        instr_cj ? imm_cj_type :
                        instr_cb ? imm_cb_type :
                                   imm_b_type;

    // A conditional branch (uncompressed or compressed) is predicted taken
    // when its sign-extended offset is negative (sign bit == 1)
    assign instr_b_taken = (instr_b  & imm_b_type[31]) |
                           (instr_cb & imm_cb_type[31]);

    // Jumps are always predicted taken; branches follow instr_b_taken.
    assign predict_branch_taken_o = fetch_valid_i & (instr_j | instr_cj | instr_b_taken);

    // Target address = program counter + sign-extended offset
    assign predict_branch_pc_o = fetch_pc_i + branch_imm;

endmodule


