module static_branch_predict (

  // Instruction from fetch stage
  input  logic [31:0] fetch_rdata_i,
  input  logic [31:0] fetch_pc_i,
  input  logic [31:0] register_addr_i,
  input  logic        fetch_valid_i,

  // Prediction for supplied instruction
  output logic        predict_branch_taken_o,
  output logic [31:0] predict_branch_pc_o,

  // Value-Range-Propagation prediction outputs
  output logic [7:0]  predict_confidence_o,
  output logic        predict_exception_o,
  output logic [2:0]  predict_branch_type_o,
  output logic [31:0] predict_branch_offset_o
);
  logic [31:0] reg_addr;
  logic [31:0] imm_jal_type;
  logic [31:0] imm_jalr_type;
  logic [31:0] imm_b_type;
  logic [31:0] imm_cj_type;
  logic [31:0] imm_cb_type;

  logic [31:0] branch_imm;

  logic [31:0] instr;

  logic instr_jal;
  logic instr_jalr;
  logic instr_b;
  logic instr_cj;
  logic instr_cb;

  logic instr_b_taken;


  localparam OPCODE_BRANCH = 7'h63;
  localparam OPCODE_JAL    = 7'h6F;
  localparam OPCODE_JALR   = 7'h67;

  assign instr = fetch_rdata_i;
  assign reg_addr = register_addr_i;

  assign imm_jal_type = {{12{instr[31]}}, instr[19:12], instr[20], instr[30:21], 1'b0 };
  assign imm_jalr_type = {{20{instr[31]}}, instr[31:20]}+reg_addr;
  assign imm_b_type = { {19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0 };

  assign imm_cj_type = { {20{instr[12]}}, instr[12], instr[8], instr[10:9], instr[6], instr[7],
    instr[2], instr[11], instr[5:3], 1'b0 };

  assign imm_cb_type = { {23{instr[12]}}, instr[12], instr[6:5], instr[2], instr[11:10],
    instr[4:3], 1'b0};

  assign instr_b    = instr[6:0] == OPCODE_BRANCH;
  assign instr_jal  = instr[6:0] == OPCODE_JAL;
  assign instr_jalr = instr[6:0] == OPCODE_JALR;

  assign instr_cb = (instr[1:0] == 2'b01) & ((instr[15:13] == 3'b110) | (instr[15:13] == 3'b111));
  assign instr_cj = (instr[1:0] == 2'b01) & ((instr[15:13] == 3'b101) | (instr[15:13] == 3'b001));

  always_comb begin
    branch_imm = imm_b_type;

    case(1'b1)
      instr_jal  : branch_imm = imm_jal_type;
      instr_jalr : branch_imm = imm_jalr_type;
      instr_b    : branch_imm = imm_b_type;
      instr_cj   : branch_imm = imm_cj_type;
      instr_cb   : branch_imm = imm_cb_type;
      default    : ;
    endcase
  end
  assign predict_branch_pc_o    = fetch_pc_i + branch_imm;
  assign instr_b_taken = (instr_b & imm_b_type[31]) | (instr_cb & imm_cb_type[31]);
  assign predict_branch_taken_o = fetch_valid_i & (instr_jal | instr_jalr | instr_cj | instr_b_taken);

  // Offset-direction MSBs (bit-selects computed in continuous assigns so they
  // are not used as constant selects inside always_* processes)
  wire imm_b_msb  = imm_b_type[31];
  wire imm_cb_msb = imm_cb_type[31];

  // Calculated branch offset (sign-extended immediate selected above)
  assign predict_branch_offset_o = branch_imm;

  // Fetch address misalignment detection
  assign predict_exception_o = (fetch_pc_i[1:0] != 2'b00);

  // Branch / jump type identification (based on opcode and instruction format)
  always_comb begin
    case (1'b1)
      instr_jal  : predict_branch_type_o = 3'b001;
      instr_jalr : predict_branch_type_o = 3'b010;
      instr_b    : predict_branch_type_o = 3'b011;
      instr_cj   : predict_branch_type_o = 3'b100;
      instr_cb   : predict_branch_type_o = 3'b101;
      default    : predict_branch_type_o = 3'b000;
    endcase
  end

  // Confidence level (probability) associated with the prediction
  always_comb begin
    predict_confidence_o = 8'd0;
    if (fetch_valid_i) begin
      if (instr_jal | instr_jalr | instr_cj)
        predict_confidence_o = 8'd100;                       // jumps: always taken
      else if (instr_b)
        predict_confidence_o = imm_b_msb  ? 8'd90 : 8'd50; // backward:90 forward:50
      else if (instr_cb)
        predict_confidence_o = imm_cb_msb ? 8'd90 : 8'd50; // compressed branch
      else
        predict_confidence_o = 8'd0;                         // unrecognized
    end
  end

endmodule

module static_branch_predict (

  // Instruction from fetch stage
  input  logic [31:0] fetch_rdata_i,
  input  logic [31:0] fetch_pc_i,
  input  logic [31:0] register_addr_i,
  input  logic        fetch_valid_i,

  // Prediction for supplied instruction
  output logic        predict_branch_taken_o,
  output logic [31:0] predict_branch_pc_o
);
  logic [31:0] reg_addr;
  logic [31:0] imm_jal_type;
  logic [31:0] imm_jalr_type;
  logic [31:0] imm_b_type;
  logic [31:0] imm_cj_type;
  logic [31:0] imm_cb_type;

  logic [31:0] branch_imm;

  logic [31:0] instr;

  logic instr_jal;
  logic instr_jalr;
  logic instr_b;
  logic instr_cj;
  logic instr_cb;

  logic instr_b_taken;

  assign instr    = fetch_rdata_i;
  assign reg_addr = register_addr_i;

  // ------------------------------------------------------------------
  // Immediate calculation (RISC-V immediate encodings)
  // ------------------------------------------------------------------
  // JAL : 20-bit immediate, sign extended
  assign imm_jal_type  = { {12{instr[31]}}, instr[19:12], instr[20], instr[30:21], 1'b0 };
  // JALR : 12-bit sign extended immediate added to the register address
  assign imm_jalr_type = { {20{instr[31]}}, instr[31:20] } + reg_addr;
  // B-type : 12-bit branch immediate, sign extended
  assign imm_b_type    = { {19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0 };
  // CJ (compressed jump) immediate
  assign imm_cj_type   = { {20{instr[12]}}, instr[12], instr[8], instr[10:9], instr[6], instr[7],
                           instr[2], instr[11], instr[5:3], 1'b0 };
  // CB (compressed branch) immediate
  assign imm_cb_type   = { {23{instr[12]}}, instr[12], instr[6:5], instr[2], instr[11:10],
                           instr[4:3], 1'b0 };

  // ------------------------------------------------------------------
  // Branch type decoding
  // ------------------------------------------------------------------
  assign instr_jal  = (instr[6:0] == 7'h6F);
  assign instr_jalr = (instr[6:0] == 7'h67);
  assign instr_b    = (instr[6:0] == 7'h63);
  assign instr_cj   = (instr[1:0] == 2'b01) & ((instr[15:13] == 3'b101) |
                                               (instr[15:13] == 3'b001));
  assign instr_cb   = (instr[1:0] == 2'b01) & ((instr[15:13] == 3'b110) |
                                               (instr[15:13] == 3'b111));

  // ------------------------------------------------------------------
  // Branch immediate selection
  // ------------------------------------------------------------------
  always @(*) begin
    branch_imm = imm_b_type;
    case (1'b1)
      instr_jal  : branch_imm = imm_jal_type;
      instr_jalr : branch_imm = imm_jalr_type;
      instr_b    : branch_imm = imm_b_type;
      instr_cj   : branch_imm = imm_cj_type;
      instr_cb   : branch_imm = imm_cb_type;
      default    : branch_imm = branch_imm + 0;
    endcase
  end

  // ------------------------------------------------------------------
  // Branch taken decision (B / CB predicted taken on negative offset)
  // ------------------------------------------------------------------
  assign instr_b_taken = (instr_b & imm_b_type[31]) | (instr_cb & imm_cb_type[31]);

  // ------------------------------------------------------------------
  // Branch prediction : taken for JAL/JALR/CJ, and for taken B/CB
  // ------------------------------------------------------------------
  assign predict_branch_taken_o = fetch_valid_i &
                                  (instr_jal | instr_jalr | instr_cj | instr_b_taken);

  // ------------------------------------------------------------------
  // Predicted target address
  // ------------------------------------------------------------------
  assign predict_branch_pc_o = fetch_pc_i + branch_imm;

endmodule

module static_branch_predict(
  // Instruction from fetch stage
  input  logic [31:0] fetch_rdata_i,
  input  logic [31:0] fetch_pc_i,
  input  logic [31:0] register_addr_i,
