  // ------------------------------------------------------------------
  // Offset / immediate calculation (RISC-V immediate encodings)
  // ------------------------------------------------------------------
  assign imm_jal_type  = { {12{instr[31]}}, instr[19:12], instr[20], instr[30:21], 1'b0 };
  assign imm_jalr_type = { {20{instr[31]}}, instr[31:20] } + reg_addr;
  assign imm_b_type    = { {19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0 };
  assign imm_cj_type   = { {20{instr[12]}}, instr[12], instr[8], instr[10:9], instr[6], instr[7],
                           instr[2], instr[11], instr[5:3], 1'b0 };
  assign imm_cb_type   = { {23{instr[12]}}, instr[12], instr[6:5], instr[2], instr[11:10],
                           instr[4:3], 1'b0 };

  // ------------------------------------------------------------------
  // Branch type decoding
  // ------------------------------------------------------------------
  assign instr_jal  = (instr[6:0] == 7'h6F);
  assign instr_jalr = (instr[6:0] == 7'h67);
  assign instr_b    = (instr[6:0] == 7'h63);
  assign instr_cj   = (instr[1:0] == 2'b01) & ((instr[15:13] == 3'b101) |
                                               (instr[15:13] == 3'b001));
  assign instr_cb   = (instr[1:0] == 2'b01) & ((instr[15:13] == 3'b110) |
                                               (instr[15:13] == 3'b111));

  // ------------------------------------------------------------------
  // B / CB taken indication (negative offset predicted taken)
  // ------------------------------------------------------------------
  assign instr_b_taken = (instr_b & imm_b_type[31]) | (instr_cb & imm_cb_type[31]);

  // ------------------------------------------------------------------
  // Offset selection for target calculation
  // ------------------------------------------------------------------
  always @(*) begin
    branch_imm = imm_b_type;
    case (1'b1)
      instr_jal  : branch_imm = imm_jal_type;
      instr_jalr : branch_imm = imm_jalr_type;
      instr_b    : branch_imm = imm_b_type;
      instr_cj   : branch_imm = imm_cj_type;
      instr_cb   : branch_imm = imm_cb_type;
      default    : ;
    endcase
  end

  assign predict_branch_offset_o = branch_imm;

  // ------------------------------------------------------------------
  // Confidence level calculation
  //   invalid          -> 0
  //   JAL / JALR / CJ   -> 100
  //   B / CB, sign set  -> 90, else 50
  // ------------------------------------------------------------------
  always @(*) begin
    if (!fetch_valid_i) begin
      predict_confidence_o = 8'd0;
    end else if (instr_jal | instr_jalr | instr_cj) begin
      predict_confidence_o = 8'd100;
    end else if (instr_b) begin
      predict_confidence_o = imm_b_type[31] ? 8'd90 : 8'd50;
    end else if (instr_cb) begin
      predict_confidence_o = imm_cb_type[31] ? 8'd90 : 8'd50;
    end else begin
      predict_confidence_o = 8'd0;
    end
  end

  // ------------------------------------------------------------------
  // Branch prediction decision : taken when confidence for a valid
  // instruction exceeds 50
  // ------------------------------------------------------------------
  assign predict_branch_taken_o = fetch_valid_i & (predict_confidence_o > 8'd50);

  // ------------------------------------------------------------------
  // Predicted target address
  // ------------------------------------------------------------------
  assign predict_branch_pc_o = fetch_pc_i + branch_imm;

  // ------------------------------------------------------------------
  // Branch type encoding (listing order : none/JAL/JALR/B/CJ/CB)
  // ------------------------------------------------------------------
  always @(*) begin
    if (instr_jal)       predict_branch_type_o = 3'd1;
    else if (instr_jalr) predict_branch_type_o = 3'd2;
    else if (instr_b)    predict_branch_type_o = 3'd3;
    else if (instr_cj)   predict_branch_type_o = 3'd4;
    else if (instr_cb)   predict_branch_type_o = 3'd5;
    else                 predict_branch_type_o = 3'd0;
  end

  // ------------------------------------------------------------------
  // Exception / misalignment detection : PC must be halfword aligned
  // (compressed instructions are supported, so IALIGN = 16)
  // ------------------------------------------------------------------
  assign predict_exception_o = fetch_pc_i[0];

endmodule


