module strobe_divider #(
    parameter MaxRatio_g = 10, // Maximum division ratio (positive integer)
    parameter Latency_g  = 1   // Latency: 0 or 1
)(
    input  wire                              Clk,        // Clock input
    input  wire                              Rst,        // Synchronous reset (active high)
    input  wire [log2ceil(MaxRatio_g)-1:0]   In_Ratio,   // Division ratio input
    input  wire                              In_Valid,   // Input pulse valid
    output reg                               Out_Valid,  // Output pulse valid
    input  wire                              Out_Ready   // Output ready signal
);

    // Function to calculate the ceiling of log2
    function integer log2ceil;
        input integer value;
        integer i;
        begin
            log2ceil = 1;
            for (i = 0; (2 ** i) < value; i = i + 1)
                log2ceil = i + 1;
        end
    endfunction

    // Internal state registers
    reg [log2ceil(MaxRatio_g)-1:0] r_Count, r_next_Count; // Counter register
    reg                            r_OutValid, r_next_OutValid; // Registered OutValid signal
    reg                            OutValid_v; // Intermediate OutValid for latency

    // --------------------------------------------------------
    // Combinational Logic
    // --------------------------------------------------------
    always @* begin
        // Hold current state as default
        r_next_Count    = r_Count;
        r_next_OutValid = r_OutValid;
        OutValid_v      = 1'b0;

        // ------------------------------------------------------------------
        // Counter logic for division ratio.
        // OutValid_v is first used to carry the "raw" strobe for THIS cycle:
        //   - In_Ratio = 0  -> bypass: emit a strobe on every valid pulse.
        //   - otherwise     -> emit a strobe when the counter reaches the ratio,
        //                      i.e. after In_Ratio valid pulses, then reset it.
        // ------------------------------------------------------------------
        if (In_Valid) begin
            if (In_Ratio == 0) begin
                OutValid_v   = 1'b1;
                r_next_Count = {log2ceil(MaxRatio_g){1'b0}};
            end else if (r_Count >= (In_Ratio - 1'b1)) begin
                OutValid_v   = 1'b1;
                r_next_Count = {log2ceil(MaxRatio_g){1'b0}};
            end else begin
                r_next_Count = r_Count + 1'b1;
            end
        end

        // ------------------------------------------------------------------
        // Latency handling + Output-ready handshake.
        // At this point OutValid_v holds the raw strobe generated this cycle.
        // ------------------------------------------------------------------
        if (Latency_g == 0) begin
            // Combinational (zero-latency) path: the strobe is presented in the
            // same cycle. A held (previously un-consumed) pulse stays asserted.
            OutValid_v      = OutValid_v | r_OutValid;
            // Keep the pulse pending only while it has not been consumed.
            r_next_OutValid = OutValid_v & ~Out_Ready;
        end else begin
            // Registered (one-cycle-latency) path: the strobe appears next cycle.
            r_next_OutValid = r_OutValid;
            if (Out_Ready)
                r_next_OutValid = 1'b0;   // consumed -> clear
            if (OutValid_v)
                r_next_OutValid = 1'b1;   // new strobe -> set (wins over consume)
            // Present the registered value (delayed by one clock).
            OutValid_v = r_OutValid;
        end

        // Output assignment
        Out_Valid = OutValid_v;
    end

    // --------------------------------------------------------
    // Sequential Logic
    // --------------------------------------------------------
    always @(posedge Clk) begin
        if (Rst) begin
            r_Count    <= {log2ceil(MaxRatio_g){1'b0}};
            r_OutValid <= 1'b0;
        end else begin
            r_Count    <= r_next_Count;
            r_OutValid <= r_next_OutValid;
        end
    end

endmodule

module swizzler #(
    // Parameter N: Number of serial data lanes (default is 8)
    parameter int N = 8
)(
    input  clk,
    input  reset,
    // Parallel data input lanes
    input  logic [N-1:0]                     data_in,
    // Encoded mapping input: concatenation of N mapping indices, each M bits wide.
    // M = $clog2(N+1) so an index equal to N (invalid) is representable/detectable.
    input  logic [N*($clog2(N+1))-1:0]       mapping_in,
    // Control signal: 1 - straight mapping, 0 - mirror bits in place
    input  logic                             config_in,
    // Selects the final transformation applied to the swizzled data
    input  logic [2:0]                       operation_mode,
    // Final data output
    output logic [N-1:0]                     data_out,
    // Asserted (with data_out forced to 0) when any mapping index is invalid (>= N)
    output logic                             error_flag
);
    localparam int M = $clog2(N+1);

    // Decode the N mapping indices
    logic [M-1:0] map_idx [N];
    // Per-lane invalid-index flags and selected bits
    logic [N-1:0] err_vec;
    logic [N-1:0] sel_bit;

    genvar j;
    generate
        for (j = 0; j < N; j++) begin : lane_mapping
            assign map_idx[j] = mapping_in[j*M +: M];
            assign err_vec[j] = (map_idx[j] >= N);
            // Variable index used inside a continuous assign (Icarus-safe)
            assign sel_bit[j] = data_in[map_idx[j]];
        end
    endgenerate

    // ---- Invalid-mapping error detection (any lane index >= N) ----
    logic temp_error_flag;
    assign temp_error_flag = |err_vec;

    // ---- Swizzle calculation (all bits driven to 0 on error) ----
    logic [N-1:0] temp_swizzled;
    assign temp_swizzled = temp_error_flag ? '0 : sel_bit;

    // ---- config_in : straight (1) vs mirror-in-place (0) ----
    logic [N-1:0] processed;
    generate
        for (j = 0; j < N; j++) begin : cfg_stage
            assign processed[j] = config_in ? temp_swizzled[j] : temp_swizzled[N-1-j];
        end
    endgenerate

    // ---- Candidate operation-mode transforms (constant-index continuous assigns) ----
    logic [N-1:0] op_reverse;
    logic [N-1:0] op_swap;
    logic [N-1:0] op_invert;
    logic [N-1:0] op_cleft;
    logic [N-1:0] op_cright;
    generate
        for (j = 0; j < N; j++) begin : rev_stage
            assign op_reverse[j] = processed[N-1-j];
        end
    endgenerate
    assign op_swap   = {processed[N/2-1:0], processed[N-1:N/2]};  // Swap halves
    assign op_invert = ~processed;                                // Bitwise inversion
    assign op_cleft  = {processed[N-2:0], processed[N-1]};        // Circular left shift by 1
    assign op_cright = {processed[0], processed[N-1:1]};          // Circular right shift by 1

    // ---- Operation-mode mux (whole-vector assignments only) ----
    logic [N-1:0] op_pre;
    always_comb begin
        case (operation_mode)
            3'b000:  op_pre = processed;   // Swizzle only
            3'b001:  op_pre = processed;   // Passthrough
            3'b010:  op_pre = op_reverse;  // Reverse
            3'b011:  op_pre = op_swap;     // Swap halves
            3'b100:  op_pre = op_invert;   // Bitwise inversion
            3'b101:  op_pre = op_cleft;    // Circular left shift
            3'b110:  op_pre = op_cright;   // Circular right shift
            3'b111:  op_pre = processed;   // Default / same as swizzle
            default: op_pre = processed;
        endcase
    end

    logic [N-1:0] op_result;
    assign op_result = temp_error_flag ? '0 : op_pre;

    // ---- Final bit reversal (MSB-left alignment), forced to 0 on error ----
    logic [N-1:0] final_pre;
    generate
        for (j = 0; j < N; j++) begin : fin_stage
            assign final_pre[j] = op_result[N-1-j];
        end
    endgenerate
    logic [N-1:0] final_out;
    assign final_out = temp_error_flag ? '0 : final_pre;

    // ---- Pipeline / observability registers ----
    // data_out and error_flag share a single (1-cycle) output latency so that,
    // per spec, error_flag becomes 1 on the next clock while data_out is forced
    // to 0 on that same cycle.
    logic [N-1:0] swizzle_reg;
    logic [N-1:0] operation_reg;
    logic         error_reg;

    always_ff @(posedge clk) begin
        if (reset) begin
            swizzle_reg   <= '0;
            operation_reg <= '0;
            error_reg     <= 1'b0;
            data_out      <= '0;
            error_flag    <= 1'b0;
        end
        else begin
            swizzle_reg   <= processed;
            operation_reg <= op_result;
            error_reg     <= temp_error_flag;
            data_out      <= final_out;
            error_flag    <= temp_error_flag;
        end
    end
endmodule

`timescale 1ns/1ps

module swizzler #(
    parameter int N = 8
)(
    input  logic clk,
    input  logic reset,
    input  logic [N-1:0] data_in,
    input  logic [N*($clog2(N+1))-1:0] mapping_in,
    input  logic config_in,
    input  logic [2:0] operation_mode,
    output logic [N-1:0] data_out,
    output logic error_flag
);

    localparam int M = $clog2(N+1);

    logic [M-1:0] map_idx [N];
    genvar j;
    generate
        for (j = 0; j < N; j++) begin
            assign map_idx[j] = mapping_in[(N-1-j)*M +: M];
        end
    endgenerate

    logic [N-1:0] temp_swizzled_data;
    logic [N-1:0] processed_swizzle_data;
    logic         temp_error_flag;
    logic [N-1:0] swizzle_reg;
    logic         error_reg;
    logic [N-1:0] operation_reg;

    always_comb begin
        temp_error_flag = 1'b0;

        for (int i = 0; i < N; i++) begin
            if (map_idx[i] >= N) begin
                temp_error_flag = 1'b1;
            end
        end

        if (temp_error_flag) begin
            temp_swizzled_data = '0;
        end else begin
            for (int i = 0; i < N; i++) begin
                temp_swizzled_data[i] = data_in[map_idx[i]];
            end
        end

        for (int i = 0; i < N; i++) begin
            if (config_in) begin
                processed_swizzle_data[i] = temp_swizzled_data[i];
            end else begin
                processed_swizzle_data[i] = temp_swizzled_data[N - 1 - i];
            end
        end
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            swizzle_reg <= '0;
            error_reg   <= 1'b0;
        end else begin
            swizzle_reg <= processed_swizzle_data;
            error_reg   <= temp_error_flag;
        end
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            operation_reg <= '0;
        end else begin
            case (operation_mode)
                3'b000: operation_reg <= swizzle_reg;
                3'b001: operation_reg <= swizzle_reg;
                3'b010: for (int i = 0; i < N; i++) operation_reg[i] <= swizzle_reg[N-1-i];
                3'b011: operation_reg <= {swizzle_reg[N/2-1:0], swizzle_reg[N-1:N/2]};
                3'b100: operation_reg <= ~swizzle_reg;
                3'b101: operation_reg <= {swizzle_reg[N-2:0], swizzle_reg[N-1]};
                3'b110: operation_reg <= {swizzle_reg[0], swizzle_reg[N-1:1]};
                default: operation_reg <= swizzle_reg;
            endcase
        end
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            data_out   <= '0;
            error_flag <= 1'b0;
        end else begin
            data_out   <= operation_reg;
            error_flag <= error_reg;
        end
    end

endmodule

module sync_lifo #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 3
) (
    input  wire                  clock,
    input  wire                  reset,
    input  wire                  write_en,
    input  wire                  read_en,
    input  wire [DATA_WIDTH-1:0] data_in,
    output wire                  empty,
    output wire                  full,
    output reg  [DATA_WIDTH-1:0] data_out
);

    // Depth of the LIFO
    localparam DEPTH = (1 << ADDR_WIDTH);

    // Storage array
    reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // Stack pointer / element count : ranges 0..DEPTH, so needs ADDR_WIDTH+1 bits
    reg [ADDR_WIDTH:0] sp;

    integer i;

    // Status flags derived from the pointer
    assign empty = (sp == 0);
    assign full  = (sp == DEPTH);

    always @(posedge clock) begin
        if (reset) begin
            // Synchronous, active-high reset: clear output, pointer and memory
            sp       <= {(ADDR_WIDTH+1){1'b0}};
            data_out <= {DATA_WIDTH{1'b0}};
            for (i = 0; i < DEPTH; i = i + 1)
                mem[i] <= {DATA_WIDTH{1'b0}};
        end else begin
            // Write (push): store data at the top of stack, advance pointer.
            // Overflow: when full, no write and pointer/contents unchanged.
            if (write_en && !full) begin
                mem[sp] <= data_in;
                sp      <= sp + 1'b1;
            end

            // Read (pop): output the last-written value (top of stack),
            // retract pointer. Underflow: when empty, data_out holds its
            // previous value and pointer/memory unchanged.
            if (read_en && !empty) begin
                data_out <= mem[sp - 1'b1];
                sp       <= sp - 1'b1;
            end
        end
    end

endmodule


