//============================================================================
// Synchronous serial communication : top + transmitter + receiver
//   - MSB-first serialization
//   - serial_clk is a gated version of clk (clk & tx_active), which stays LOW
//     when no data is being transmitted.  The transmit datapath is driven on
//     the NEGATIVE edge of clk so that serial_out is stable before the RX
//     samples it on the POSITIVE edge of serial_clk (source-synchronous,
//     glitch-free clock gating).
//============================================================================

//----------------------------------------------------------------------------
// Transmitter
//----------------------------------------------------------------------------
module tx_block (
    input  wire        clk,
    input  wire        reset_n,     // active-low asynchronous reset
    input  wire [63:0] data_in,
    input  wire [2:0]  sel,
    output reg         serial_out,
    output reg         done,
    output wire        serial_clk
);

    // Number of bits to transmit based on sel
    reg [6:0] n_bits;
    always @(*) begin
        case (sel)
            3'h1:    n_bits = 7'd8;
            3'h2:    n_bits = 7'd16;
            3'h3:    n_bits = 7'd32;
            3'h4:    n_bits = 7'd64;
            default: n_bits = 7'd0;   // 3'h0 and all illegal codes -> no tx
        endcase
    end

    // Left-align the valid data so bit [63] is the first (MSB) bit to send.
    wire [63:0] tx_aligned = data_in << (64 - n_bits);

    reg [63:0] tx_shift;
    reg [6:0]  tx_cnt;      // number of bits presented so far
    reg [6:0]  tx_nbits;    // latched transmit width
    reg        tx_active;   // high while data is being serialized
    reg        started;     // set once the transaction begins

    // gated serial clock : toggles like clk while transmitting, LOW otherwise.
    // tx_active changes on the negedge so this gating is glitch-free.
    assign serial_clk = clk & tx_active;

    always @(negedge clk or negedge reset_n) begin
        if (!reset_n) begin
            serial_out <= 1'b0;
            done       <= 1'b0;
            tx_shift   <= 64'h0;
            tx_cnt     <= 7'd0;
            tx_nbits   <= 7'd0;
            tx_active  <= 1'b0;
            started    <= 1'b0;
        end else begin
            if (!started) begin
                if (n_bits != 7'd0) begin
                    started    <= 1'b1;
                    tx_active  <= 1'b1;
                    tx_nbits   <= n_bits;
                    serial_out <= tx_aligned[63];  // first (MSB) bit
                    tx_shift   <= tx_aligned << 1; // prepare next bit
                    tx_cnt     <= 7'd1;
                end
                // n_bits == 0 : remain idle, nothing transmitted
            end else if (tx_active) begin
                if (tx_cnt < tx_nbits) begin
                    serial_out <= tx_shift[63];
                    tx_shift   <= tx_shift << 1;
                    tx_cnt     <= tx_cnt + 7'd1;
                end else begin
                    // all bits presented : stop and flag completion
                    tx_active  <= 1'b0;
                    serial_out <= 1'b0;
                    done       <= 1'b1;
                end
            end
        end
    end

endmodule

//----------------------------------------------------------------------------
// Receiver
//----------------------------------------------------------------------------
module rx_block (
    input  wire        clk,
    input  wire        reset_n,     // active-low asynchronous reset
    input  wire        data_in,     // serial input bit
    input  wire [2:0]  sel,
    input  wire        serial_clk,
    output reg  [63:0] data_out,
    output reg         done
);

    // Expected number of received bits based on sel
    reg [6:0] n_bits;
    always @(*) begin
        case (sel)
            3'h1:    n_bits = 7'd8;
            3'h2:    n_bits = 7'd16;
            3'h3:    n_bits = 7'd32;
            3'h4:    n_bits = 7'd64;
            default: n_bits = 7'd0;
        endcase
    end

    reg [63:0] rx_shift;
    reg [6:0]  bit_count;
    reg        latched;

    // Capture serial data on the rising edge of the (gated) serial clock,
    // MSB-first : each new bit shifts in at the LSB end.
    always @(posedge serial_clk or negedge reset_n) begin
        if (!reset_n) begin
            rx_shift  <= 64'h0;
            bit_count <= 7'd0;
        end else begin
            rx_shift  <= {rx_shift[62:0], data_in};
            bit_count <= bit_count + 7'd1;
        end
    end

    // Once all expected bits are received, reconstruct data_out and pulse
    // done for one clock cycle (in the clk domain).
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            data_out <= 64'h0;
            done     <= 1'b0;
            latched  <= 1'b0;
        end else begin
            done <= 1'b0;   // default : one-cycle pulse
            if (!latched && (n_bits != 7'd0) && (bit_count == n_bits)) begin
                case (sel)
                    3'h1:    data_out <= {56'h0, rx_shift[7:0]};
                    3'h2:    data_out <= {48'h0, rx_shift[15:0]};
                    3'h3:    data_out <= {32'h0, rx_shift[31:0]};
                    3'h4:    data_out <= rx_shift[63:0];
                    default: data_out <= 64'h0;
                endcase
                done    <= 1'b1;
                latched <= 1'b1;
            end
        end
    end

endmodule

