///// tx_block  (area-optimized: single sequential always block; the 7-bit
/////            reg_count / temp_reg_count registers are only ever consumed via
/////            "!= 0" tests, so they are reduced to 1-bit "nonzero" flags that
/////            reproduce serial_clk and serial_out bit-for-bit every cycle;
/////            bit_count narrowed 7->6 bits (max value 63). Fully functionally
/////            equivalent at the interface.)
module tx_block(
    input clk,               // Clock input
    input reset_n,           // Active-low reset input
    input [63:0] data_in,    // 64-bit parallel data input
    input [2:0] sel,         // Selection input to choose data width
    output reg serial_out,   // Serial data output
    output reg done,         // Done signal indicating completion of transmission
    output serial_clk        // Clock for serial data transmission
);

// Internal registers
reg [63:0] data_reg;         // Register to hold the data being transmitted
reg [5:0]  bit_count;        // Counter to track number of bits to transmit (max 63)
reg        reg_count_nz;     // (bit_count != 0) delayed one cycle  (was reg_count[6:0])
reg        temp_reg_nz;      // reg_count_nz delayed one cycle        (was temp_reg_count[6:0])

// Single sequential block for state control, data selection, clock-gate
// pipeline, serial output and done generation.
always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        data_reg     <= 64'h0;
        bit_count    <= 6'h0;
        reg_count_nz <= 1'b0;
        temp_reg_nz  <= 1'b0;
        serial_out   <= 1'b0;
        done         <= 1'b0;
    end else begin
        // done asserted when there are no more bits to transmit
        if (bit_count == 6'h0)
            done <= 1'b1;
        else
            done <= 1'b0;

        // Data / bit-count control (reads the currently-registered done)
        if (done == 1'b1) begin
            case (sel)
                3'b000: begin
                    data_reg  <= 64'h0;
                    bit_count <= 6'd0;
                end
                3'b001: begin
                    data_reg  <= {56'h0, data_in[7:0]};
                    bit_count <= 6'd7;
                end
                3'b010: begin
                    data_reg  <= {48'h0, data_in[15:0]};
                    bit_count <= 6'd15;
                end
                3'b011: begin
                    data_reg  <= {32'h0, data_in[31:0]};
                    bit_count <= 6'd31;
                end
                3'b100: begin
                    data_reg  <= data_in[63:0];
                    bit_count <= 6'd63;
                end
                default: begin
                    data_reg  <= 64'h0;
                    bit_count <= 6'h0;
                end
            endcase
        end else if (bit_count > 6'h0) begin
            data_reg  <= data_reg >> 1;
            bit_count <= bit_count - 1'b1;
        end

        // Clock-gate pipeline: track only the nonzero property (delayed copies)
        reg_count_nz <= (bit_count != 6'h0);
        temp_reg_nz  <= reg_count_nz;

        // Serial output: emit LSB of data_reg while transmission is active
        if (reg_count_nz || bit_count > 6'h0)
            serial_out <= data_reg[0];
    end
end

// Generate serial clock based on the (delayed) nonzero flag
//`ifdef SIMULATION
assign serial_clk = clk && (temp_reg_nz !== 1'b0) ;  // To avoid SImulator issue
//`else
//assign  serial_clk = clk && (temp_reg_nz !== 1'b0) ;
//`endif

endmodule

///// rx_block  (kept functionally identical to the original)
module rx_block(
    input wire clk,  		    // clock input
    input wire reset_n,		    // Active-low reset
    input wire data_in,		    // Serial input data
    input wire serial_clk,	    // Clock signal for serial data
    input wire [2:0] sel,           // Selection output to choose data width
    output reg done,		    // Done signal to indicate data reception complete
    output reg [63:0] data_out  	// Parallel output data after serial operation

);

    // Internal registers
    reg [63:0] data_reg;		    // Register to hold incoming serial data
    reg [7:0] bit_count;		    // Counter for the number of bits received
    reg [7:0] count;			    // General purpose counter to sync with bit_count


    // Sequential logic block to capture serial data on the rising edge of serial_clk
    always @(posedge serial_clk or negedge  reset_n) begin
        if (!reset_n) begin		    // Reset all registers on reset_n (active low)
            data_reg <= 64'h0;		// Clear the data register
            bit_count <= 8'd0;		// Clear the bit counter
        end else begin
            if(done == 1'b1) begin                   // If done signal is asserted, reset the bit counter and data register
                bit_count <= 8'b0;
                data_reg <= 64'h0;
            end
            else begin
                 bit_count <= bit_count;			 // Maintain the bit counter if not done
            end
                bit_count <= bit_count + 1'b1;	     // Increment bit count
                if (bit_count < 8'd64)               // preserve out-of-range no-op write semantics
                    data_reg[bit_count[5:0]]<=data_in; 	     // Store the incoming data bit
           end
    end

    // Sequential logic block to monitor the completion of data reception and update outputs
    always@(posedge clk or negedge reset_n) begin
    	if(!reset_n) begin			 	             // Reset all registers on reset_n (active low)
    	   count <= 8'd0;				         // Clear the bit counter
           done <= 1'b0;					         // Deassert done signal
           data_out <= 64'h0;					     // Clear the output data register
        end
        else if(count >= bit_count && count != 8'd0) begin       // When the count reaches the bit_count, assert done and output the data
           done <= 1'b1;				             // Set done to indicate transmission complete
           case(sel)
            3'b000:begin
                data_out <= 64'h0;                   // no bits to transmit
            end
            3'b001:begin
                data_out <= data_reg;                // {56'h0,data_reg} truncated to 64b == data_reg
            end
            3'b010:begin
                data_out <= data_reg;                // {48'h0,data_reg} truncated to 64b == data_reg
            end
            3'b011:begin
                data_out <= data_reg;                // {32'h0,data_reg} truncated to 64b == data_reg
            end
            3'b100:begin
                data_out <= data_reg;                // 64 bits of data_reg
            end
            default:begin
                data_out <= 64'h0;                   // no bits to transmit, default state
            end
           endcase
        end
        else if(bit_count > 8'd0) begin              // If bits are being received, increment the count and deassert done
           count <= count+ 1'b1;			     // Increment count
           done <= 1'b0;					         // Clear done signal while receiving
        end
        else begin  		                     // If no bits have been received, reset the count and deassert done
           count <= 8'd0;					         // Reset count
           done <= 1'b0;					         // Clear done signal
        end
    end

endmodule

module thermostat (
    input  wire       i_clk,
    input  wire       i_rst,            // asynchronous, active-low reset
    input  wire [5:0] i_temp_feedback,
    input  wire       i_fan_on,
    input  wire       i_enable,
    input  wire       i_fault,
    input  wire       i_clr,
    output reg        o_heater_full,
    output reg        o_heater_medium,
    output reg        o_heater_low,
    output reg        o_aircon_full,
    output reg        o_aircon_medium,
    output reg        o_aircon_low,
    output reg        o_fan,
    output reg  [2:0] o_state
);

    // -----------------------------------------------------------------
    // State encoding
    // -----------------------------------------------------------------
    localparam [2:0] HEAT_LOW  = 3'b000;
    localparam [2:0] HEAT_MED  = 3'b001;
    localparam [2:0] HEAT_FULL = 3'b010;
    localparam [2:0] AMBIENT   = 3'b011;
    localparam [2:0] COOL_LOW  = 3'b100;
    localparam [2:0] COOL_MED  = 3'b101;
    localparam [2:0] COOL_FULL = 3'b110;

    // -----------------------------------------------------------------
    // Temperature feedback bit aliases
    // -----------------------------------------------------------------
    wire i_full_cold   = i_temp_feedback[5];
    wire i_medium_cold = i_temp_feedback[4];
    wire i_low_cold    = i_temp_feedback[3];
    wire i_low_hot     = i_temp_feedback[2];
    wire i_medium_hot  = i_temp_feedback[1];
    wire i_full_hot    = i_temp_feedback[0];

    // -----------------------------------------------------------------
    // Latched fault: once a fault is signalled the thermostat remains
    // forced off until i_clr is asserted (with i_fault deasserted).
    // -----------------------------------------------------------------
    reg       fault_latched;
    reg       fault_next;
    reg [2:0] next_state;

    always @(*) begin
        if (i_fault)      fault_next = 1'b1;      // fault has priority
        else if (i_clr)   fault_next = 1'b0;      // clear when fault gone
        else              fault_next = fault_latched;
    end

    // -----------------------------------------------------------------
    // Next-state (combinational)
    // Priority: fault (hold, or clear->AMBIENT) > clr > disable > normal
    // -----------------------------------------------------------------
    always @(*) begin
        next_state = o_state;  // default hold
        if (i_fault || fault_latched) begin
            if (i_clr && !i_fault) next_state = AMBIENT; // clearing the fault
            else                   next_state = o_state; // remain frozen
        end else if (i_clr) begin
            next_state = AMBIENT;
        end else if (!i_enable) begin
            next_state = AMBIENT;
        end else begin
            // Cold conditions (highest priority first), then hot, else ambient
            if (i_full_cold)        next_state = HEAT_FULL;
            else if (i_medium_cold) next_state = HEAT_MED;
            else if (i_low_cold)    next_state = HEAT_LOW;
            else if (i_full_hot)    next_state = COOL_FULL;
            else if (i_medium_hot)  next_state = COOL_MED;
            else if (i_low_hot)     next_state = COOL_LOW;
            else                    next_state = AMBIENT;
        end
    end

    // Outputs are forced off during fault (current or latched) or disable
    wire force_off = i_fault || fault_latched || (~i_enable);

    // -----------------------------------------------------------------
    // Sequential state + registered outputs (async active-low reset)
    // Outputs decode next_state so they stay aligned with o_state.
    // -----------------------------------------------------------------
    always @(posedge i_clk or negedge i_rst) begin
        if (!i_rst) begin
            o_state         <= AMBIENT;
            fault_latched   <= 1'b0;
            o_heater_full   <= 1'b0;
            o_heater_medium <= 1'b0;
            o_heater_low    <= 1'b0;
            o_aircon_full   <= 1'b0;
            o_aircon_medium <= 1'b0;
            o_aircon_low    <= 1'b0;
            o_fan           <= 1'b0;
        end else begin
            fault_latched <= fault_next;
            o_state       <= next_state;

            // default all off
            o_heater_full   <= 1'b0;
            o_heater_medium <= 1'b0;
            o_heater_low    <= 1'b0;
            o_aircon_full   <= 1'b0;
            o_aircon_medium <= 1'b0;
            o_aircon_low    <= 1'b0;
            o_fan           <= 1'b0;

            if (!force_off) begin
                case (next_state)
                    HEAT_FULL: o_heater_full   <= 1'b1;
                    HEAT_MED:  o_heater_medium <= 1'b1;
                    HEAT_LOW:  o_heater_low    <= 1'b1;
                    COOL_FULL: o_aircon_full   <= 1'b1;
                    COOL_MED:  o_aircon_medium <= 1'b1;
                    COOL_LOW:  o_aircon_low    <= 1'b1;
                    default:   ; // AMBIENT -> all heater/cooler off
                endcase
                // Fan on if any heater/cooler active (non-AMBIENT) or manual
                if ((next_state != AMBIENT) || i_fan_on)
                    o_fan <= 1'b1;
            end
        end
    end

endmodule

// ttc_counter_lite.sv
// Lightweight timer/counter with interval mode, interrupt generation,
// and AXI-Lite register-based control/status monitoring.
module ttc_counter_lite (
    input  wire        clk,
    input  wire        reset,        // active-high synchronous reset
    input  wire [3:0]  axi_addr,
    input  wire [31:0] axi_wdata,
    input  wire        axi_write_en,
    input  wire        axi_read_en,
    output reg  [31:0] axi_rdata,
    output reg         interrupt
);

    // ---- Spec-named state (declared verbatim) --------------------------
    reg [15:0] count;
    reg [15:0] match_value;
    reg [15:0] reload_value;
    reg        enable;
    reg        interval_mode;
    reg        interrupt_enable;
    reg        match_flag;

    // ---- Register-map address encodings --------------------------------
    localparam [3:0] ADDR_COUNT   = 4'h0;
    localparam [3:0] ADDR_MATCH   = 4'h1;
    localparam [3:0] ADDR_RELOAD  = 4'h2;
    localparam [3:0] ADDR_CONTROL = 4'h3;
    localparam [3:0] ADDR_STATUS  = 4'h4;

    // ---- Sequential logic ----------------------------------------------
    always @(posedge clk) begin
        if (reset) begin
            count            <= 16'd0;
            match_value      <= 16'd0;
            reload_value     <= 16'd0;
            enable           <= 1'b0;
            interval_mode    <= 1'b0;
            interrupt_enable <= 1'b0;
            match_flag       <= 1'b0;
            interrupt        <= 1'b0;
        end else begin
            // default: match_flag pulses only on the match cycle
            match_flag <= 1'b0;

            // ---- AXI-Lite writes -------------------------------------
            if (axi_write_en) begin
                case (axi_addr)
                    ADDR_MATCH:   match_value  <= axi_wdata[15:0];
                    ADDR_RELOAD:  reload_value <= axi_wdata[15:0];
                    ADDR_CONTROL: begin
                        enable           <= axi_wdata[0];
                        interval_mode    <= axi_wdata[1];
                        interrupt_enable <= axi_wdata[2];
                    end
                    default: ; // ADDR_STATUS handled in interrupt block
                endcase
            end

            // ---- Counter logic ---------------------------------------
            if (enable) begin
                if (count == match_value) begin
                    match_flag <= 1'b1;
                    if (interval_mode)
                        count <= reload_value;   // reload on match
                    else
                        count <= match_value;    // hold at match value
                end else begin
                    count <= count + 16'd1;      // count up
                end
            end

            // ---- Interrupt generation (clear wins over set) ----------
            if (axi_write_en && (axi_addr == ADDR_STATUS))
                interrupt <= 1'b0;               // write to status clears
            else if (match_flag && interrupt_enable)
                interrupt <= 1'b1;               // assert on match
        end
    end

    // ---- AXI-Lite reads (combinational) --------------------------------
    always @(*) begin
        case (axi_addr)
            ADDR_COUNT:   axi_rdata = {16'd0, count};
            ADDR_MATCH:   axi_rdata = {16'd0, match_value};
            ADDR_RELOAD:  axi_rdata = {16'd0, reload_value};
            ADDR_CONTROL: axi_rdata = {29'd0, interrupt_enable, interval_mode, enable};
            ADDR_STATUS:  axi_rdata = {31'd0, interrupt};
            default:      axi_rdata = 32'd0;
        endcase
    end

endmodule

module unpack_one_hot (
    input               sign,
    input               size,
    input       [2:0]   one_hot_selector,
    input       [255:0] source_reg,
    output reg  [511:0] destination_reg
);

    // Spec-named integer loop variable
    integer i;

    always @(*) begin
        // Default initialization: destination cleared before unpacking
        destination_reg = 512'b0;

        case (one_hot_selector)
            // 1-bit source segment -> 8-bit destination segment
            3'b001: begin
                for (i = 0; i < 64; i = i + 1) begin
                    if (sign)
                        destination_reg[i*8 +: 8] = {{7{source_reg[i]}}, source_reg[i]};
                    else
                        destination_reg[i*8 +: 8] = {7'b0, source_reg[i]};
                end
            end

            // 2-bit source segment -> 8-bit destination segment
            3'b010: begin
                for (i = 0; i < 64; i = i + 1) begin
                    if (sign)
                        destination_reg[i*8 +: 8] = {{6{source_reg[i*2+1]}}, source_reg[i*2 +: 2]};
                    else
                        destination_reg[i*8 +: 8] = {6'b0, source_reg[i*2 +: 2]};
                end
            end

            // Size-dependent behavior
            3'b100: begin
                if (size) begin
                    // 8-bit source segment -> 16-bit destination segment
                    for (i = 0; i < 32; i = i + 1) begin
                        if (sign)
                            destination_reg[i*16 +: 16] = {{8{source_reg[i*8+7]}}, source_reg[i*8 +: 8]};
                        else
                            destination_reg[i*16 +: 16] = {8'b0, source_reg[i*8 +: 8]};
                    end
                end else begin
                    // 4-bit source segment -> 8-bit destination segment
                    for (i = 0; i < 64; i = i + 1) begin
                        if (sign)
                            destination_reg[i*8 +: 8] = {{4{source_reg[i*4+3]}}, source_reg[i*4 +: 4]};
                        else
                            destination_reg[i*8 +: 8] = {4'b0, source_reg[i*4 +: 4]};
                    end
                end
            end

            // Default: pass source through directly (zero-extended)
            default: begin
                destination_reg = {256'b0, source_reg};
            end
        endcase
    end

endmodule


