    input  wire        clk,
    input  wire        rst,               // asynchronous, active-high reset
    input  wire        item_button,       // rising-edge toggle
    input  wire [2:0]  item_selected,     // valid 3'b001..3'b100
    input  wire [3:0]  coin_input,        // valid 1,2,5,10
    input  wire        cancel,            // rising-edge toggle
    output reg         dispense_item,
    output reg         return_change,
    output reg [4:0]   item_price,
    output reg [4:0]   change_amount,
    output reg [2:0]   dispense_item_id,
    output reg         error,
    output reg         return_money
);

    // -----------------------------------------------------------------
    // FSM states
    // -----------------------------------------------------------------
    localparam [2:0] IDLE               = 3'd0;
    localparam [2:0] ITEM_SELECTION     = 3'd1;
    localparam [2:0] PAYMENT_VALIDATION = 3'd2;
    localparam [2:0] DISPENSING_ITEM    = 3'd3;
    localparam [2:0] RETURN_CHANGE      = 3'd4;
    localparam [2:0] RETURN_MONEY       = 3'd5;

    reg [2:0] state;
    reg [4:0] coins_accumulated;
    reg [2:0] sel_item;

    // Rising-edge detection for the toggle inputs
    reg item_button_prev;
    reg cancel_prev;
    wire item_button_edge = item_button & ~item_button_prev;
    wire cancel_edge      = cancel      & ~cancel_prev;

    // Input classification
    wire coin_present = (coin_input != 4'd0);
    wire coin_valid   = (coin_input == 4'd1)  ||
                        (coin_input == 4'd2)  ||
                        (coin_input == 4'd5)  ||
                        (coin_input == 4'd10);
    wire item_is_valid = (item_selected == 3'b001) ||
                         (item_selected == 3'b010) ||
                         (item_selected == 3'b011) ||
                         (item_selected == 3'b100);

    // -----------------------------------------------------------------
    // Item price lookup (items 1..4 have defined prices)
    // -----------------------------------------------------------------
    function [4:0] price_of;
        input [2:0] itm;
        begin
            case (itm)
                3'b001:  price_of = 5'd5;
                3'b010:  price_of = 5'd10;
                3'b011:  price_of = 5'd15;
                3'b100:  price_of = 5'd20;
                default: price_of = 5'd0;
            endcase
        end
    endfunction

    // -----------------------------------------------------------------
    // Main FSM (registered outputs, async active-high reset)
    // -----------------------------------------------------------------
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state             <= IDLE;
            coins_accumulated <= 5'd0;
            sel_item          <= 3'd0;
            item_price        <= 5'd0;
            change_amount     <= 5'd0;
            dispense_item_id  <= 3'd0;
            dispense_item     <= 1'b0;
            return_change     <= 1'b0;
            error             <= 1'b0;
            return_money      <= 1'b0;
            item_button_prev  <= 1'b0;
            cancel_prev       <= 1'b0;
        end else begin
            // toggle-edge history
            item_button_prev <= item_button;
            cancel_prev      <= cancel;

            // one-cycle pulse outputs default low
            dispense_item <= 1'b0;
            return_change <= 1'b0;
            error         <= 1'b0;
            return_money  <= 1'b0;

            case (state)
                // ---------------------------------------------------------
                IDLE: begin
                    if (item_button_edge) begin
                        state             <= ITEM_SELECTION;
                        coins_accumulated <= 5'd0;
                        item_price        <= 5'd0;
                        change_amount     <= 5'd0;
                        dispense_item_id  <= 3'd0;
                        sel_item          <= 3'd0;
                    end else if (coin_present) begin
                        // coins inserted without selecting an item -> error
                        error        <= 1'b1;
                        return_money  <= (coins_accumulated > 5'd0);
                        state         <= RETURN_MONEY;
                    end
                end

                // ---------------------------------------------------------
                ITEM_SELECTION: begin
                    if (cancel_edge) begin
                        error        <= 1'b1;
                        return_money <= (coins_accumulated > 5'd0);
                        state        <= RETURN_MONEY;
                    end else if (item_selected != 3'd0) begin
                        if (item_is_valid) begin
                            item_price <= price_of(item_selected);
                            sel_item   <= item_selected;
                            state      <= PAYMENT_VALIDATION;
                        end else begin
                            // invalid item id -> error
                            error        <= 1'b1;
                            return_money <= (coins_accumulated > 5'd0);
                            state        <= RETURN_MONEY;
                        end
                    end
                    // item_selected == 0 -> keep waiting
                end

                // ---------------------------------------------------------
                PAYMENT_VALIDATION: begin
                    if (cancel_edge) begin
                        error        <= 1'b1;
                        return_money <= (coins_accumulated > 5'd0);
                        state        <= RETURN_MONEY;
                    end else if (coin_present) begin
                        if (!coin_valid) begin
                            // invalid coin value -> error, refund
                            error        <= 1'b1;
                            return_money <= (coins_accumulated > 5'd0);
                            state        <= RETURN_MONEY;
                        end else begin
                            // valid coin: accumulate
                            if ((coins_accumulated + coin_input) >= item_price) begin
                                coins_accumulated <= coins_accumulated + 5'(coin_input);
                                dispense_item     <= 1'b1;
                                dispense_item_id  <= sel_item;
                                state             <= DISPENSING_ITEM;
                            end else begin
                                coins_accumulated <= coins_accumulated + 5'(coin_input);
                            end
                        end
                    end
                end

                // ---------------------------------------------------------
                DISPENSING_ITEM: begin
                    if (coins_accumulated > item_price) begin
                        change_amount <= coins_accumulated - item_price;
                        return_change <= 1'b1;
                        state         <= RETURN_CHANGE;
                    end else begin
                        state             <= IDLE;
                        coins_accumulated <= 5'd0;
                        item_price        <= 5'd0;
                        dispense_item_id  <= 3'd0;
                        sel_item          <= 3'd0;
                    end
                end

                // ---------------------------------------------------------
                RETURN_CHANGE: begin
                    state             <= IDLE;
                    coins_accumulated <= 5'd0;
                    item_price        <= 5'd0;
                    change_amount     <= 5'd0;
                    dispense_item_id  <= 3'd0;
                    sel_item          <= 3'd0;
                end

                // ---------------------------------------------------------
                RETURN_MONEY: begin
                    state             <= IDLE;
                    coins_accumulated <= 5'd0;
                    item_price        <= 5'd0;
                    change_amount     <= 5'd0;
                    dispense_item_id  <= 3'd0;
                    sel_item          <= 3'd0;
                end

                // ---------------------------------------------------------
                default: state <= IDLE;
            endcase
        end
    end

endmodule


