module vga_controller (
    input  logic        clock,
    input  logic        reset,
    input  logic [7:0]  color_in,
    output logic        hsync,
    output logic        vsync,
    output logic [7:0]  red,
    output logic [7:0]  green,
    output logic [7:0]  blue,
    output logic [9:0]  next_x,
    output logic [9:0]  next_y,
    output logic        sync,
    output logic        clk,
    output logic        blank
);

    // Horizontal timing parameters (pixel clocks)
    localparam H_ACTIVE = 640;
    localparam H_FRONT  = 16;
    localparam H_PULSE  = 96;
    localparam H_BACK   = 48;
    // Vertical timing parameters (lines)
    localparam V_ACTIVE = 480;
    localparam V_FRONT  = 10;
    localparam V_PULSE  = 2;
    localparam V_BACK   = 33;

    // FSM state encodings (active, front porch, sync pulse, back porch)
    localparam [1:0] ST_ACTIVE = 2'd0;
    localparam [1:0] ST_FRONT  = 2'd1;
    localparam [1:0] ST_PULSE  = 2'd2;
    localparam [1:0] ST_BACK   = 2'd3;

    logic [1:0] h_state, v_state;
    logic [9:0] h_counter, v_counter;
    logic       line_done;

    // Combinational next-state scratch (fully assigned each clock)
    logic [1:0] nh_state, nv_state;
    logic [9:0] nh_counter, nv_counter;
    logic       nline_done;
    logic       h_line_end;

    // Constant / passthrough outputs
    assign sync = 1'b0;
    assign clk  = clock;

    always @(posedge clock or posedge reset) begin
        if (reset) begin
            h_state   <= ST_ACTIVE;
            v_state   <= ST_ACTIVE;
            h_counter <= 10'd0;
            v_counter <= 10'd0;
            line_done <= 1'b0;
            hsync     <= 1'b0;
            vsync     <= 1'b0;
            red       <= 8'd0;
            green     <= 8'd0;
            blue      <= 8'd0;
            next_x    <= 10'd0;
            next_y    <= 10'd0;
            blank     <= 1'b0;
        end else begin
            // defaults: hold current values
            nh_state   = h_state;
            nh_counter = h_counter;
            nv_state   = v_state;
            nv_counter = v_counter;
            nline_done = 1'b0;
            h_line_end = 1'b0;

            // Horizontal state machine
            case (h_state)
                ST_ACTIVE: begin
                    if (h_counter == H_ACTIVE-1) begin nh_counter = 10'd0; nh_state = ST_FRONT; end
                    else nh_counter = h_counter + 10'd1;
                end
                ST_FRONT: begin
                    if (h_counter == H_FRONT-1) begin nh_counter = 10'd0; nh_state = ST_PULSE; end
                    else nh_counter = h_counter + 10'd1;
                end
                ST_PULSE: begin
                    if (h_counter == H_PULSE-1) begin nh_counter = 10'd0; nh_state = ST_BACK; end
                    else nh_counter = h_counter + 10'd1;
                end
                ST_BACK: begin
                    if (h_counter == H_BACK-1) begin
                        nh_counter = 10'd0; nh_state = ST_ACTIVE;
                        nline_done = 1'b1; h_line_end = 1'b1;
                    end else nh_counter = h_counter + 10'd1;
                end
                default: begin nh_counter = 10'd0; nh_state = ST_ACTIVE; end
            endcase

            // Vertical state machine advances only at end of a horizontal line
            if (h_line_end) begin
                case (v_state)
                    ST_ACTIVE: begin
                        if (v_counter == V_ACTIVE-1) begin nv_counter = 10'd0; nv_state = ST_FRONT; end
                        else nv_counter = v_counter + 10'd1;
                    end
                    ST_FRONT: begin
                        if (v_counter == V_FRONT-1) begin nv_counter = 10'd0; nv_state = ST_PULSE; end
                        else nv_counter = v_counter + 10'd1;
                    end
                    ST_PULSE: begin
                        if (v_counter == V_PULSE-1) begin nv_counter = 10'd0; nv_state = ST_BACK; end
                        else nv_counter = v_counter + 10'd1;
                    end
                    ST_BACK: begin
                        if (v_counter == V_BACK-1) begin nv_counter = 10'd0; nv_state = ST_ACTIVE; end
                        else nv_counter = v_counter + 10'd1;
                    end
                    default: begin nv_counter = 10'd0; nv_state = ST_ACTIVE; end
                endcase
            end

            // Register state and counters
            h_state   <= nh_state;
            h_counter <= nh_counter;
            v_state   <= nv_state;
            v_counter <= nv_counter;
            line_done <= nline_done;

            // Sync outputs: active-HIGH normally, LOW only during the sync pulse.
            // Aligned to the state being entered.
            hsync <= (nh_state == ST_PULSE) ? 1'b0 : 1'b1;
            vsync <= (nv_state == ST_PULSE) ? 1'b0 : 1'b1;

            // RGB: color during active video, blanked (zero) otherwise
            if ((nh_state == ST_ACTIVE) && (nv_state == ST_ACTIVE)) begin
                red   <= {color_in[7:5], 5'd0};
                green <= {color_in[4:2], 5'd0};
                blue  <= {color_in[1:0], 6'd0};
            end else begin
                red   <= 8'd0;
                green <= 8'd0;
                blue  <= 8'd0;
            end

            // Pixel-position tracking (wraps to zero outside active region)
            next_x <= (nh_state == ST_ACTIVE) ? nh_counter : 10'd0;
            next_y <= (nv_state == ST_ACTIVE) ? nv_counter : 10'd0;

            // Blank: HIGH during any blanking interval (not active video)
            blank <= ~((nh_state == ST_ACTIVE) && (nv_state == ST_ACTIVE));
        end
    end
endmodule


