module vga_controller (
    input logic clock,      // 25 MHz
    input logic reset,      // Active high
    input logic [7:0] color_in, // Pixel color data (RRRGGGBB)
    output logic [9:0] next_x,  // x-coordinate of NEXT pixel that will be drawn
    output logic [9:0] next_y,  // y-coordinate of NEXT pixel that will be drawn
    output logic hsync,     // HSYNC (to VGA connector)
    output logic vsync,     // VSYNC (to VGA connector)
    output logic [7:0] red, // RED (to resistor DAC VGA connector)
    output logic [7:0] green, // GREEN (to resistor DAC to VGA connector)
    output logic [7:0] blue, // BLUE (to resistor DAC to VGA connector)
    output logic sync,      // SYNC to VGA connector
    output logic clk,       // CLK to VGA connector
    output logic blank,      // BLANK to VGA connector
    output logic [7:0] h_state, // States of Horizontal FSM
    output logic [7:0] v_state  // States of Vertical FSM
);

    parameter logic [9:0] H_ACTIVE  =  10'd640;
    parameter logic [9:0] H_FRONT   =  10'd16;
    parameter logic [9:0] H_PULSE   =  10'd96;
    parameter logic [9:0] H_BACK    =  10'd48;
    parameter logic [9:0] V_ACTIVE  =  10'd480;
    parameter logic [9:0] V_FRONT   =  10'd10;
    parameter logic [9:0] V_PULSE   =  10'd2;
    parameter logic [9:0] V_BACK    =  10'd33;
    parameter logic LOW   = 1'b0;
    parameter logic HIGH  = 1'b1;
    parameter logic [7:0] H_ACTIVE_STATE  = 8'd0;
    parameter logic [7:0] H_FRONT_STATE   = 8'd1;
    parameter logic [7:0] H_PULSE_STATE   = 8'd2;
    parameter logic [7:0] H_BACK_STATE    = 8'd3;
    parameter logic [7:0] V_ACTIVE_STATE  = 8'd0;
    parameter logic [7:0] V_FRONT_STATE   = 8'd1;
    parameter logic [7:0] V_PULSE_STATE   = 8'd2;
    parameter logic [7:0] V_BACK_STATE    = 8'd3;


    logic line_done;
    logic [9:0] h_counter;
    logic [9:0] v_counter;

    always_ff @(posedge clock or posedge reset) begin
        if (reset) begin
            h_counter   <= 10'd0;
            v_counter   <= 10'd0;
            h_state     <= H_ACTIVE_STATE;
            v_state     <= V_ACTIVE_STATE;
            line_done   <= LOW;
            hsync       <= HIGH;
            vsync       <= HIGH;
            red         <= 8'd0;
            green       <= 8'd0;
            blue        <= 8'd0;
        end
        else begin
            // line_done is a one-cycle pulse; default it LOW every cycle.
            line_done <= LOW;

            // -------------------- Horizontal Timing FSM --------------------
            case (h_state)
                H_ACTIVE_STATE: begin
                    hsync <= HIGH;
                    if (h_counter == H_ACTIVE - 1) begin
                        h_state   <= H_FRONT_STATE;
                        h_counter <= 10'd0;
                    end
                    else begin
                        h_counter <= h_counter + 10'd1;
                    end
                end
                H_FRONT_STATE: begin
                    hsync <= HIGH;
                    if (h_counter == H_FRONT - 1) begin
                        h_state   <= H_PULSE_STATE;
                        h_counter <= 10'd0;
                    end
                    else begin
                        h_counter <= h_counter + 10'd1;
                    end
                end
                H_PULSE_STATE: begin
                    hsync <= LOW;
                    if (h_counter == H_PULSE - 1) begin
                        h_state   <= H_BACK_STATE;
                        h_counter <= 10'd0;
                    end
                    else begin
                        h_counter <= h_counter + 10'd1;
                    end
                end
                H_BACK_STATE: begin
                    hsync <= HIGH;
                    if (h_counter == H_BACK - 1) begin
                        h_state   <= H_ACTIVE_STATE;
                        h_counter <= 10'd0;
                        line_done <= HIGH;   // pulse for one cycle at line end
                    end
                    else begin
                        h_counter <= h_counter + 10'd1;
                    end
                end
                default: begin
                    h_state   <= H_ACTIVE_STATE;
                    h_counter <= 10'd0;
                    hsync     <= HIGH;
                end
            endcase

            // --------------------- Vertical Timing FSM ---------------------
            // The vertical machine advances once per completed line (line_done).
            case (v_state)
                V_ACTIVE_STATE: begin
                    vsync <= HIGH;
                    if (line_done == HIGH) begin
                        if (v_counter == V_ACTIVE - 1) begin
                            v_state   <= V_FRONT_STATE;
                            v_counter <= 10'd0;
                        end
                        else begin
                            v_counter <= v_counter + 10'd1;
                        end
                    end
                end
                V_FRONT_STATE: begin
                    vsync <= HIGH;
                    if (line_done == HIGH) begin
                        if (v_counter == V_FRONT - 1) begin
                            v_state   <= V_PULSE_STATE;
                            v_counter <= 10'd0;
                        end
                        else begin
                            v_counter <= v_counter + 10'd1;
                        end
                    end
                end
                V_PULSE_STATE: begin
                    vsync <= LOW;
                    if (line_done == HIGH) begin
                        if (v_counter == V_PULSE - 1) begin
                            v_state   <= V_BACK_STATE;
                            v_counter <= 10'd0;
                        end
                        else begin
                            v_counter <= v_counter + 10'd1;
                        end
                    end
                end
                V_BACK_STATE: begin
                    vsync <= HIGH;
                    if (line_done == HIGH) begin
                        if (v_counter == V_BACK - 1) begin
                            v_state   <= V_ACTIVE_STATE;
                            v_counter <= 10'd0;
                        end
                        else begin
                            v_counter <= v_counter + 10'd1;
                        end
                    end
                end
                default: begin
                    v_state   <= V_ACTIVE_STATE;
                    v_counter <= 10'd0;
                    vsync     <= HIGH;
                end
            endcase

            // ---------------------- RGB signal handling --------------------
            // During the visible display region drive the color; blank otherwise.
            if ((h_state == H_ACTIVE_STATE) && (v_state == V_ACTIVE_STATE)) begin
                red   <= {color_in[7:5], 5'b00000};
                green <= {color_in[4:2], 5'b00000};
                blue  <= {color_in[1:0], 6'b000000};
            end
            else begin
                red   <= 8'd0;
                green <= 8'd0;
                blue  <= 8'd0;
            end
        end
    end


    assign clk = clock;
    assign sync = 1'b0;
    assign blank = hsync & vsync;

    assign next_x = (h_state == H_ACTIVE_STATE) ? h_counter : 10'd0;
    assign next_y = (v_state == V_ACTIVE_STATE) ? v_counter : 10'd0;

endmodule

module vga_controller (
    input logic clock,      // 25 MHz
    input logic reset,      // Active high
    input logic [7:0] color_in, // Pixel color data (RRRGGGBB)
    output logic [9:0] next_x,  // x-coordinate of NEXT pixel that will be drawn
    output logic [9:0] next_y,  // y-coordinate of NEXT pixel that will be drawn
    output logic hsync,     // HSYNC (to VGA connector)
    output logic vsync,     // VSYNC (to VGA connector)
    output logic [7:0] red, // RED (to resistor DAC VGA connector)
    output logic [7:0] green, // GREEN (to resistor DAC to VGA connector)
    output logic [7:0] blue, // BLUE (to resistor DAC to VGA connector)
    output logic sync,      // SYNC to VGA connector
    output logic clk,       // CLK to VGA connector
    output logic blank,     // BLANK to VGA connector
    output logic [7:0] h_state, // States of Horizontal FSM
    output logic [7:0] v_state  // States of Vertical FSM
);

    parameter logic [9:0] H_ACTIVE  =  10'd640;
    parameter logic [9:0] H_FRONT   =  10'd16;
    parameter logic [9:0] H_PULSE   =  10'd96;
    parameter logic [9:0] H_BACK    =  10'd48;
    parameter logic [9:0] V_ACTIVE  =  10'd480;
    parameter logic [9:0] V_FRONT   =  10'd10;
    parameter logic [9:0] V_PULSE   =  10'd2;
    parameter logic [9:0] V_BACK    =  10'd33;
    parameter logic LOW   = 1'b0;
    parameter logic HIGH  = 1'b1;
    parameter logic [7:0] H_ACTIVE_STATE  = 8'd0;
    parameter logic [7:0] H_FRONT_STATE   = 8'd1;
    parameter logic [7:0] H_PULSE_STATE   = 8'd2;
    parameter logic [7:0] H_BACK_STATE    = 8'd3;
    parameter logic [7:0] V_ACTIVE_STATE  = 8'd0;
    parameter logic [7:0] V_FRONT_STATE   = 8'd1;
    parameter logic [7:0] V_PULSE_STATE   = 8'd2;
    parameter logic [7:0] V_BACK_STATE    = 8'd3;

    // 2-bit FSM state encodings (0=ACTIVE,1=FRONT,2=PULSE,3=BACK).
    // The 8-bit *_STATE output ports only ever carry values 0..3, so the
    // upper 6 bits are constant zero; register only the 2 meaningful bits.
    localparam logic [1:0] ST_ACTIVE = 2'd0;
    localparam logic [1:0] ST_FRONT  = 2'd1;
    localparam logic [1:0] ST_PULSE  = 2'd2;
    localparam logic [1:0] ST_BACK   = 2'd3;

    logic       line_done;
    logic [9:0] h_counter;
    logic [9:0] v_counter;
    logic [1:0] h_state_r;
    logic [1:0] v_state_r;
    // RGB: only the significant high bits are non-constant; low bits are 0.
    logic [2:0] red_r;
    logic [2:0] green_r;
    logic [1:0] blue_r;

    // Per-state count limit -> single comparator per FSM (instead of one
    // comparator per case arm). Fully equivalent: each arm compared the
    // same h_counter/v_counter against its own limit.
    logic [9:0] h_limit;
    logic [9:0] v_limit;

    always_comb begin
        case (h_state_r)
            ST_ACTIVE: h_limit = H_ACTIVE;
            ST_FRONT:  h_limit = H_FRONT;
            ST_PULSE:  h_limit = H_PULSE;
            default:   h_limit = H_BACK;   // ST_BACK
        endcase
    end

    always_comb begin
        case (v_state_r)
            ST_ACTIVE: v_limit = V_ACTIVE;
            ST_FRONT:  v_limit = V_FRONT;
            ST_PULSE:  v_limit = V_PULSE;
            default:   v_limit = V_BACK;   // ST_BACK
        endcase
    end

    wire h_tick = (h_counter == (h_limit - 10'd1));
    wire v_tick = (v_counter == (v_limit - 10'd1));

    always_ff @(posedge clock or posedge reset) begin
        if (reset) begin
            h_counter <= 10'd0;
            v_counter <= 10'd0;
            h_state_r <= ST_ACTIVE;
            v_state_r <= ST_ACTIVE;
            line_done <= LOW;
        end
        else begin
            // ---- Horizontal FSM ----
            // ACTIVE->FRONT->PULSE->BACK->ACTIVE is a natural 2-bit +1 wrap.
            h_counter <= h_tick ? 10'd0 : (h_counter + 10'd1);
            h_state_r <= h_tick ? (h_state_r + 2'd1) : h_state_r;
            hsync     <= (h_state_r == ST_PULSE) ? LOW : HIGH;
            // line_done: LOW in ACTIVE, (tick?HIGH:LOW) in BACK, hold otherwise.
            line_done <= (h_state_r == ST_ACTIVE) ? LOW :
                         (h_state_r == ST_BACK)   ? (h_tick ? HIGH : LOW) :
                                                    line_done;

            // ---- Vertical FSM (advances only while line_done) ----
            v_counter <= line_done ? (v_tick ? 10'd0 : (v_counter + 10'd1))
                                   : v_counter;
            v_state_r <= (line_done && v_tick) ? (v_state_r + 2'd1) : v_state_r;
            vsync     <= (v_state_r == ST_PULSE) ? LOW : HIGH;

            // ---- Pixel color (registered, 1-cycle latency) ----
            if ((h_state_r == ST_ACTIVE) && (v_state_r == ST_ACTIVE)) begin
                red_r   <= color_in[7:5];
                green_r <= color_in[4:2];
                blue_r  <= color_in[1:0];
            end
            else begin
                red_r   <= 3'd0;
                green_r <= 3'd0;
                blue_r  <= 2'd0;
            end
        end
    end

    assign clk   = clock;
    assign sync  = 1'b0;
    assign blank = hsync & vsync;

    assign red   = {red_r,   5'd0};
    assign green = {green_r, 5'd0};
    assign blue  = {blue_r,  6'd0};

    assign h_state = {6'd0, h_state_r};
    assign v_state = {6'd0, v_state_r};

    assign next_x = (h_state_r == ST_ACTIVE) ? h_counter : 10'd0;
    assign next_y = (v_state_r == ST_ACTIVE) ? v_counter : 10'd0;


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    hsync = 0;
    vsync = 0;
  end

endmodule

module virtual2physical_tlb #(parameter ADDR_WIDTH = 8, PAGE_WIDTH = 8, TLB_SIZE = 4, PAGE_TABLE_SIZE = 16) (
    input clk,
    input reset,
    input [ADDR_WIDTH-1:0] virtual_address,
    output [PAGE_WIDTH-1:0] physical_address,
    output hit, miss
);
    wire tlb_write_enable, flush, ready;
    wire [PAGE_WIDTH-1:0] page_table_entry;
    TLB #(.TLB_SIZE(TLB_SIZE), .ADDR_WIDTH(ADDR_WIDTH), .PAGE_WIDTH(PAGE_WIDTH)) tlb (
        .clk(clk),
        .reset(reset),
        .virtual_address(virtual_address),
        .tlb_write_enable(tlb_write_enable),
        .flush(flush),
        .page_table_entry(page_table_entry),
        .physical_address(physical_address),
        .hit(hit),
        .miss(miss)
    );

    PageTableHandler #(.ADDR_WIDTH(ADDR_WIDTH), .PAGE_WIDTH(PAGE_WIDTH), .PAGE_TABLE_SIZE(PAGE_TABLE_SIZE)) page_table_handler(
        .clk(clk),
        .reset(reset),
        .miss(miss),
        .virtual_page(virtual_address),
        .page_table_entry(page_table_entry),
        .ready(ready)
    );

    ControlUnit control_unit (
        .clk(clk),
        .reset(reset),
        .hit(hit),
        .miss(miss),
        .ready(ready),
        .tlb_write_enable(tlb_write_enable),
        .flush(flush)
    );
endmodule

module TLB #(parameter TLB_SIZE = 4, ADDR_WIDTH = 8, PAGE_WIDTH = 8) (
    input clk,
    input reset,
    input [ADDR_WIDTH-1:0] virtual_address,
    input tlb_write_enable,
    input flush,
    input [PAGE_WIDTH-1:0] page_table_entry,
    output reg [PAGE_WIDTH-1:0] physical_address,
    output reg hit,
    output reg miss
);
    // TLB Storage
    reg [ADDR_WIDTH-1:0] virtual_tags[TLB_SIZE-1:0];
    reg [PAGE_WIDTH-1:0] physical_pages[TLB_SIZE-1:0];
    reg [TLB_SIZE-1:0] valid_bits;
    reg [$clog2(TLB_SIZE)-1:0] replacement_index; // Index for the next replacement
    integer i;

    // Insert the logic here  to update TLB with a new page table entry using the replacement policy
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Invalidate every entry and reset the round-robin replacement pointer
            for (i = 0; i < TLB_SIZE; i = i + 1) begin
                valid_bits[i]     <= 1'b0;
                virtual_tags[i]   <= {ADDR_WIDTH{1'b0}};
                physical_pages[i] <= {PAGE_WIDTH{1'b0}};
            end
            replacement_index <= 0;
        end else if (flush) begin
            // Flush: invalidate every entry
            for (i = 0; i < TLB_SIZE; i = i + 1) begin
                valid_bits[i] <= 1'b0;
            end
            replacement_index <= 0;
        end else if (tlb_write_enable) begin
            // Insert new translation using round-robin replacement policy
            virtual_tags[replacement_index]   <= virtual_address;
            physical_pages[replacement_index] <= page_table_entry;
            valid_bits[replacement_index]     <= 1'b1;
            replacement_index                 <= replacement_index + 1'b1;
        end
    end

    always_comb begin
        hit = 0;
        miss = 1;
        physical_address = 0;

        // Insert the logic here to check for a match in TLB
        for (i = 0; i < TLB_SIZE; i = i + 1) begin
            if (valid_bits[i] && (virtual_tags[i] == virtual_address)) begin
                hit = 1'b1;
                miss = 1'b0;
                physical_address = physical_pages[i];
            end
        end
    end
endmodule

module PageTableHandler #(parameter ADDR_WIDTH = 8, PAGE_WIDTH = 8, PAGE_TABLE_SIZE = 16) (
    input clk,
    input reset,
    input miss,
    input [ADDR_WIDTH-1:0] virtual_page,
    output reg [PAGE_WIDTH-1:0] page_table_entry,
    output reg ready
);
    // Parameterized Page Table Memory
    reg [PAGE_WIDTH-1:0] page_table_memory [0:PAGE_TABLE_SIZE-1];
 assign   page_table_entry = page_table_memory[virtual_page];
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Initialize Page Table Memory during reset
            page_table_memory[0] <= 8'h0;
            page_table_memory[1] <= 8'h1;
            page_table_memory[2] <= 8'h2;
            page_table_memory[3] <= 8'h3;
            page_table_memory[4] <= 8'h4;
            page_table_memory[5] <= 8'h5;
            page_table_memory[6] <= 8'h6;
            page_table_memory[7] <= 8'h7;
            page_table_memory[8] <= 8'h8;
            page_table_memory[9] <= 8'h9;
            page_table_memory[10] <= 8'hA;
            page_table_memory[11] <= 8'hB;
            page_table_memory[12] <= 8'hC;
            page_table_memory[13] <= 8'hD;
            page_table_memory[14] <= 8'hE;
            page_table_memory[15] <= 8'hF;
            ready = 0;
        end else if (miss) begin
            // Fetch the physical page number from the simulated page table
            ready <= 1; // Indicate the entry is ready
        end else begin
            ready <= 0;
        end
    end
endmodule
module ControlUnit (
    input clk,
    input reset,
    input hit,
    input miss,
    input ready,
    output reg tlb_write_enable,
    output reg flush
);
    reg [1:0] state;

    localparam IDLE = 2'b00,
               FETCH = 2'b01,
               UPDATE = 2'b10;

    // Insert the logic for control unit here
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state            <= IDLE;
            tlb_write_enable <= 1'b0;
            flush            <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    tlb_write_enable <= 1'b0;
                    flush            <= 1'b0;
                    // A miss triggers a page-table fetch
                    if (miss) begin
                        state <= FETCH;
                    end
                end
                FETCH: begin
                    // Wait for the Page Table Handler to be ready, then update the TLB
                    if (ready) begin
                        tlb_write_enable <= 1'b1;
                        state            <= UPDATE;
                    end
                end
                UPDATE: begin
                    // Deassert the write-enable and return to idle
                    tlb_write_enable <= 1'b0;
                    state            <= IDLE;
                end
                default: begin
                    state            <= IDLE;
                    tlb_write_enable <= 1'b0;
                    flush            <= 1'b0;
                end
            endcase
        end
    end
endmodule

module wishbone_to_ahb_bridge (
    // Wishbone slave interface (from WB master)
    input  wire        clk_i,
    input  wire        rst_i,      // active-low reset
    input  wire        cyc_i,
    input  wire        stb_i,
    input  wire [3:0]  sel_i,
    input  wire        we_i,
    input  wire [31:0] addr_i,
    input  wire [31:0] data_i,
    output reg  [31:0] data_o,
    output reg         ack_o,
    // AHB master interface (to AHB slave)
    input  wire        hclk,
    input  wire        hreset_n,   // active-low reset
    input  wire [31:0] hrdata,
    input  wire [1:0]  hresp,
    input  wire        hready,
    output reg  [1:0]  htrans,
    output reg  [2:0]  hsize,
    output wire [2:0]  hburst,
    output reg         hwrite,
    output reg  [31:0] haddr,
    output reg  [31:0] hwdata
);

    // ---- AHB HTRANS encodings ----
    localparam [1:0] TRANS_IDLE   = 2'b00;
    localparam [1:0] TRANS_BUSY   = 2'b01;
    localparam [1:0] TRANS_NONSEQ = 2'b10;
    localparam [1:0] TRANS_SEQ    = 2'b11;

    // ---- AHB HSIZE encodings ----
    localparam [2:0] SIZE_BYTE = 3'b000;
    localparam [2:0] SIZE_HALF = 3'b001;
    localparam [2:0] SIZE_WORD = 3'b010;

    // ---- FSM states ----
    localparam ST_IDLE = 1'b0;   // waiting for WB request / presenting address phase
    localparam ST_DATA = 1'b1;   // AHB data phase, waiting for hready

    reg        state;
    reg [31:0] addr_hold;
    reg [31:0] data_hold;
    reg [2:0]  size_hold;
    reg        write_hold;

    wire req = cyc_i & stb_i;

    // sel_i -> AHB transfer size
    function [2:0] sel_to_size(input [3:0] sel);
        case (sel)
            4'b0001, 4'b0010, 4'b0100, 4'b1000: sel_to_size = SIZE_BYTE;
            4'b0011, 4'b1100:                    sel_to_size = SIZE_HALF;
            4'b1111:                             sel_to_size = SIZE_WORD;
            default:                             sel_to_size = SIZE_WORD; // graceful
        endcase
    endfunction

    // sel_i -> low address bits (byte-lane the active bytes live on)
    function [1:0] sel_to_addrlo(input [3:0] sel);
        case (sel)
            4'b0001: sel_to_addrlo = 2'b00;
            4'b0010: sel_to_addrlo = 2'b01;
            4'b0100: sel_to_addrlo = 2'b10;
            4'b1000: sel_to_addrlo = 2'b11;
            4'b0011: sel_to_addrlo = 2'b00;
            4'b1100: sel_to_addrlo = 2'b10;
            4'b1111: sel_to_addrlo = 2'b00;
            default: sel_to_addrlo = 2'b00; // graceful
        endcase
    endfunction

    // Single transfers only.
    assign hburst = 3'b000; // SINGLE

    // Combined active-low reset: assert when EITHER domain reset is low. A
    // single async-reset net keeps the sequential block synthesizable (yosys
    // PROC_DFF rejects two independent edge-sensitive reset events).
    wire arst_n = rst_i & hreset_n;

    // -----------------------------------------------------------------
    // AHB address/control phase outputs: combinational so they are valid
    // in the SAME cycle the Wishbone request is presented (SINGLE bridge).
    // -----------------------------------------------------------------
    always @(*) begin
        // safe defaults (held attributes)
        htrans = TRANS_IDLE;
        haddr  = addr_hold;
        hsize  = size_hold;
        hwrite = write_hold;
        hwdata = data_hold;
        case (state)
            ST_IDLE: begin
                if (req && !ack_o) begin
                    htrans = TRANS_NONSEQ;
                    haddr  = {addr_i[31:2], sel_to_addrlo(sel_i)};
                    hsize  = sel_to_size(sel_i);
                    hwrite = we_i;
                    hwdata = data_i;   // don't-care in addr phase, kept stable
                end
            end
            ST_DATA: begin
                htrans = TRANS_IDLE;   // data phase of a single transfer
                haddr  = addr_hold;
                hsize  = size_hold;
                hwrite = write_hold;
                hwdata = data_hold;    // write data driven in the data phase
            end
            default: ;
        endcase
    end

    // -----------------------------------------------------------------
    // Sequential FSM + attribute holding + Wishbone response.
    // Reset when either domain reset is asserted (both active-low).
    // -----------------------------------------------------------------
    always @(posedge clk_i or negedge arst_n) begin
        if (!arst_n) begin
            state      <= ST_IDLE;
            addr_hold  <= 32'b0;
            data_hold  <= 32'b0;
            size_hold  <= SIZE_WORD;
            write_hold <= 1'b0;
            ack_o      <= 1'b0;
            data_o     <= 32'b0;
        end else begin
            ack_o <= 1'b0; // ack_o is a single-cycle pulse by default
            case (state)
                ST_IDLE: begin
                    if (req && !ack_o) begin
                        // latch/hold transaction attributes
                        addr_hold  <= {addr_i[31:2], sel_to_addrlo(sel_i)};
                        data_hold  <= data_i;
                        size_hold  <= sel_to_size(sel_i);
                        write_hold <= we_i;
                        // advance only when the address phase is accepted
                        if (hready) begin
                            state <= ST_DATA;
                        end
                    end
                end
                ST_DATA: begin
                    if (hready) begin
                        // AHB transaction complete
                        ack_o  <= 1'b1;
                        data_o <= hrdata; // little-endian identity pass-through
                        state  <= ST_IDLE;
                    end
                end
                default: state <= ST_IDLE;
            endcase
        end
    end

endmodule

module Word_Change_Pulse #(
    parameter DATA_WIDTH = 8 // Default word width
) (
    input  wire                  clk,               // Clock signal for synchronizing operations
    input  wire                  reset,             // Active-high asynchronous reset
    input  wire [DATA_WIDTH-1:0] data_in,           // Input data word
    input  wire [DATA_WIDTH-1:0] mask,              // Per-bit change-detection mask (1=detect,0=ignore)
    input  wire [DATA_WIDTH-1:0] match_pattern,     // Pattern to compare against masked input
    input  wire                  enable,            // Active-high enable
    input  wire                  latch_pattern,     // When high, latch match_pattern
    output reg                   word_change_pulse, // Pulses one clk after any masked bit changes
    output reg                   pattern_match_pulse, // Pulses when masked input matches latched pattern
    output reg  [DATA_WIDTH-1:0] latched_pattern    // Latched pattern for comparison
);

    wire [DATA_WIDTH-1:0] change_pulses;

    reg [DATA_WIDTH-1:0] masked_data_in;
    reg [DATA_WIDTH-1:0] masked_change_pulses;
    reg                  match_detected;

    // One Bit_Change_Detector per bit of data_in
    genvar i;
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : gen_bit_change
            Bit_Change_Detector u_bcd (
                .clk         (clk),
                .reset       (reset),
                .bit_in      (data_in[i]),
                .change_pulse(change_pulses[i])
            );
        end
    endgenerate

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            masked_data_in       <= {DATA_WIDTH{1'b0}};
            masked_change_pulses <= {DATA_WIDTH{1'b0}};
            word_change_pulse    <= 1'b0;
            match_detected       <= 1'b0;
            pattern_match_pulse  <= 1'b0;
            latched_pattern      <= {DATA_WIDTH{1'b0}};
        end else if (enable) begin
            // Latch the pattern when requested
            if (latch_pattern)
                latched_pattern <= match_pattern;

            // Mask data_in, detect changes, and generate word_change_pulse
            // (one clock cycle after the combinational per-bit change detection)
            masked_data_in       <= data_in & mask;
            masked_change_pulses <= change_pulses & mask;
            word_change_pulse    <= |(change_pulses & mask);

            // Compare masked data_in with latched_pattern & mask for pattern_match_pulse
            match_detected       <= ((data_in & mask) == (latched_pattern & mask));
            pattern_match_pulse  <= ((data_in & mask) == (latched_pattern & mask));
        end else begin
            // Monitoring disabled: hold latched pattern, clear all pulse activity
            word_change_pulse    <= 1'b0;
            pattern_match_pulse  <= 1'b0;
            match_detected       <= 1'b0;
            masked_change_pulses <= {DATA_WIDTH{1'b0}};
        end
    end

endmodule


// Bit_Change_Detector Module
module Bit_Change_Detector (
    input  wire clk,          // Clock signal
    input  wire reset,        // Active-high asynchronous reset
    input  wire bit_in,       // Single-bit input to detect changes
    output reg  change_pulse  // Pulse indicating a change in bit_in
);

    reg bit_in_d;

    // Store the previous value of bit_in
    always @(posedge clk or posedge reset) begin
        if (reset)
            bit_in_d <= 1'b0;
        else
            bit_in_d <= bit_in;
    end

    // Immediately (combinationally) flag a difference from the stored value
    always @(*) begin
        change_pulse = bit_in ^ bit_in_d;
    end

endmodule


