module Data_Reduction
#(
    parameter [2:0] REDUCTION_OP = 3'b000, // Default operation: AND
    parameter DATA_WIDTH         = 4,      // Width of each data element
    parameter DATA_COUNT         = 4,      // Number of data elements
    localparam TOTAL_INPUT_WIDTH = DATA_WIDTH * DATA_COUNT
)
(
    input  wire [TOTAL_INPUT_WIDTH-1:0] data_in,
    output reg  [DATA_WIDTH-1:0]        reduced_data_out
);

    // Per-output-bit reduction results
    wire [DATA_WIDTH-1:0] reduced_bits;

    genvar bit_index;
    genvar elem_index;

    generate
        // Iterate over each bit position within a single data word
        for (bit_index = 0; bit_index < DATA_WIDTH; bit_index = bit_index + 1) begin : bit_processing
            wire [DATA_COUNT-1:0] extracted_bits;

            // Gather the corresponding bit from every input data element
            for (elem_index = 0; elem_index < DATA_COUNT; elem_index = elem_index + 1) begin : extract
                assign extracted_bits[elem_index] =
                    data_in[elem_index*DATA_WIDTH + bit_index];
            end

            // Reduce the gathered bits with the selected Boolean operation
            Bitwise_Reduction #(
                .REDUCTION_OP(REDUCTION_OP),
                .BIT_COUNT   (DATA_COUNT)
            ) u_bitwise (
                .input_bits (extracted_bits),
                .reduced_bit(reduced_bits[bit_index])
            );
        end
    endgenerate

    // Combine the per-bit results into the final reduced output word
    always @(*) begin
        reduced_data_out = reduced_bits;
    end

endmodule


module Bitwise_Reduction
#(
    parameter [2:0] REDUCTION_OP = 3'b000, // Default operation: AND
    parameter BIT_COUNT          = 4       // Number of bits to reduce
)
(
    input  wire [BIT_COUNT-1:0] input_bits,
    output reg                  reduced_bit
);

    // Reduction Operation Codes
    localparam [2:0] AND_OP  = 3'b000;
    localparam [2:0] OR_OP   = 3'b001;
    localparam [2:0] XOR_OP  = 3'b010;
    localparam [2:0] NAND_OP = 3'b011;
    localparam [2:0] NOR_OP  = 3'b100;
    localparam [2:0] XNOR_OP = 3'b101;

    int i;
    reg temp_result; // Intermediate result

    always @(*) begin
        // Initialize result with the first bit
        temp_result = input_bits[0];

        // Reduce bits using the selected operation (base AND/OR/XOR fold)
        for (i = 1; i < BIT_COUNT; i = i + 1) begin
            case (REDUCTION_OP)
                AND_OP, NAND_OP  : temp_result = temp_result & input_bits[i];
                OR_OP,  NOR_OP   : temp_result = temp_result | input_bits[i];
                XOR_OP, XNOR_OP  : temp_result = temp_result ^ input_bits[i];
                default          : temp_result = temp_result & input_bits[i];
            endcase
        end

        // Apply the inverting variants (NAND/NOR/XNOR); all others pass through.
        // An invalid REDUCTION_OP falls through to AND (temp_result already AND-folded).
        case (REDUCTION_OP)
            NAND_OP, NOR_OP, XNOR_OP : reduced_bit = ~temp_result;
            default                  : reduced_bit =  temp_result;
        endcase
    end

endmodule

// Bit_Difference_Counter
// Computes the Hamming distance (number of differing bit positions) between two
// equal-width input vectors input_A and input_B.
//
// It reuses the separately-compiled context siblings Data_Reduction and
// Bitwise_Reduction (in rtl/Data_Reduction.sv) by INSTANTIATION:
//   - Data_Reduction with DATA_COUNT=2 and REDUCTION_OP=XOR reduces the two
//     packed words {input_B, input_A} into a per-bit XOR vector, i.e. a vector
//     whose bit i is 1 exactly when input_A[i] != input_B[i].
//   - Data_Reduction in turn instantiates Bitwise_Reduction per bit position.
// The number of set bits in that XOR vector is the Hamming distance.

module Bit_Difference_Counter
#(
    parameter  integer BIT_WIDTH   = 3,                    // width of the input vectors (>= 1)
    localparam integer COUNT_WIDTH = $clog2(BIT_WIDTH + 1) // width needed to hold 0 .. BIT_WIDTH
)
(
    input  wire [BIT_WIDTH-1:0]   input_A,
    input  wire [BIT_WIDTH-1:0]   input_B,
    output wire [COUNT_WIDTH-1:0] bit_difference_count
);

    // XOR reduction opcode as defined by Bitwise_Reduction.
    localparam [2:0] XOR_OP = 3'b010;

    // Per-bit difference vector: differing_bits[i] = input_A[i] ^ input_B[i].
    wire [BIT_WIDTH-1:0] differing_bits;

    // Reuse the provided reduction submodule to compute the bitwise XOR of the
    // two words. data_in is {word1=input_B, word0=input_A}; for each bit index
    // Data_Reduction reduces the DATA_COUNT=2 corresponding bits with XOR.
    Data_Reduction
    #(
        .REDUCTION_OP (XOR_OP),
        .DATA_WIDTH   (BIT_WIDTH),
        .DATA_COUNT   (2)
    )
    xor_difference_reducer
    (
        .data_in          ({input_B, input_A}),
        .reduced_data_out (differing_bits)
    );

    // Count the number of set bits (population count) in the difference vector.
    integer bit_index;
    reg [COUNT_WIDTH-1:0] difference_count;

    always @(*) begin
        difference_count = {COUNT_WIDTH{1'b0}};
        for (bit_index = 0; bit_index < BIT_WIDTH; bit_index = bit_index + 1) begin
            difference_count = difference_count + differing_bits[bit_index];
        end
    end

    assign bit_difference_count = difference_count;

endmodule

module write_buffer_merge #(
  parameter INPUT_DATA_WIDTH  = 32,                                     // Width of input data
  parameter INPUT_ADDR_WIDTH  = 16,                                     // Width of input address
  parameter BUFFER_DEPTH      = 8,                                      // Depth of the write buffer
  parameter OUTPUT_DATA_WIDTH = INPUT_DATA_WIDTH * BUFFER_DEPTH,        // Width of merged output data
  parameter OUTPUT_ADDR_WIDTH = INPUT_ADDR_WIDTH - $clog2(BUFFER_DEPTH) // Width of merged output address
) (
  input  logic                         clk,          // Clock signal
  input  logic                         srst,         // Synchronous reset (active high)
  input  logic                         wr_en_in,     // Write enable input
  input  logic [INPUT_ADDR_WIDTH-1:0]  wr_addr_in,   // Write address input
  input  logic [INPUT_DATA_WIDTH-1:0]  wr_data_in,   // Write data input
  output logic                         wr_en_out,    // Write enable output
  output logic [OUTPUT_ADDR_WIDTH-1:0] wr_addr_out,  // Write address output
  output logic [OUTPUT_DATA_WIDTH-1:0] wr_data_out   // Write data output
);

  // Internal signals for buffer tracking and management
  logic [$clog2(BUFFER_DEPTH)-1:0]      write_count;     // Counter for the number of writes in the buffer
  logic [OUTPUT_ADDR_WIDTH-1:0]         base_addr;       // Base address for the merged writes
  logic [OUTPUT_DATA_WIDTH-1:0]         merged_data;     // Buffer to hold merged data
  logic                                 write_complete;  // Signal to indicate that the buffer is full and ready to output

  generate
    if (BUFFER_DEPTH > 1) begin
      // Write count logic: Counts the number of writes in the buffer
      always_ff @(posedge clk) begin
        if (srst)
          write_count <= '0;
        else if (wr_en_in)
          write_count <= write_count + 1;  // Increment count on write enable
      end

      // Base address logic: Captures the address of the first write in the buffer
      always_ff @(posedge clk) begin
        if (srst)
          base_addr <= '0;
        else if (wr_en_in && (write_count == '0))
          // Capture the MSBs of the first write address, dropping the
          // $clog2(BUFFER_DEPTH) LSBs to form the transformed output address.
          base_addr <= wr_addr_in[INPUT_ADDR_WIDTH-1 : $clog2(BUFFER_DEPTH)];
      end

      // Merged data logic: Concatenates incoming data into the buffer
      always_ff @(posedge clk) begin
        if (srst)
          merged_data <= '0;
        else if (wr_en_in)
          // Shift current contents right by INPUT_DATA_WIDTH bits and append
          // the new word to the most-significant slot: {DATA_new, DATA_old...}.
          merged_data <= {wr_data_in, merged_data[OUTPUT_DATA_WIDTH-1 : INPUT_DATA_WIDTH]};
      end

      // Write completion logic: Indicates when the buffer is full
      always_ff @(posedge clk) begin
        if (srst)
          write_complete <= 1'b0;
        else if ((write_count == (BUFFER_DEPTH - 1)) && wr_en_in)
          write_complete <= 1'b1;  // Assert completion when buffer is full
        else
          write_complete <= 1'b0;
      end

      // Output logic: latency of 2 clock cycles after the last buffer write.
      // The completing (last) write lands in merged_data and asserts
      // write_complete on the same edge (1st stage); this register captures
      // the merged word / base address on the next edge (2nd stage).
      always_ff @(posedge clk) begin
        if (srst) begin
          wr_en_out   <= 1'b0;
          wr_addr_out <= '0;
          wr_data_out <= '0;
        end else if (write_complete) begin
          wr_en_out   <= 1'b1;          // one-cycle valid pulse
          wr_addr_out <= base_addr;     // transformed base address
          wr_data_out <= merged_data;   // concatenated merged data
        end else begin
          wr_en_out   <= 1'b0;          // default de-asserted; addr/data retained
        end
      end

    end else begin

      // Pass-through output logic for BUFFER_DEPTH == 1: forward inputs to
      // outputs (address unmodified) with a latency of 1 clock cycle.
      always_ff @(posedge clk) begin
        if (srst) begin
          wr_en_out   <= 1'b0;
          wr_addr_out <= '0;
          wr_data_out <= '0;
        end else begin
          wr_en_out   <= wr_en_in;
          wr_addr_out <= wr_addr_in;
          wr_data_out <= wr_data_in;
        end
      end

    end
  endgenerate

endmodule


